pii merge(pii a, pii b) {
  pii res(max(a.first, b.first), min(a.second, b.second));
  if (res.first >= res.second) {
    return pii(-1, -1);
  }
  else return res;
}

pii dfs(int now, int par) {
  pii range(-inf, inf);
  rep (i, G[now].size()) {
    if (G[now][i] == par) continue;
    pii temp = dfs(G[now][i], now);
    temp.first--; temp.second++;
    if (even == (depth[now] % 2 == 0)) {
      if (temp.first % 2 != 0) temp.first++;
      if (temp.second % 2 != 0) temp.second--;
    }
    else {
      if (temp.first % 2 == 0) temp.first++;
      if (temp.second % 2 == 0) temp.second--;
    }

    range = merge(range, temp);
    if (range.first >= range.second) {
      cout << "No" << endl;
      exit(0);
    }
  }
  if (even == (depth[now] % 2 == 0)) {
    if (range.first % 2 != 0) range.first++;
    if (range.second % 2 != 0) range.second--;
  }
  else {
    if (range.first % 2 == 0) range.first++;
    if (range.second % 2 == 0) range.second--;
  }

  if (range.first >= range.second) {
    cout << "No" << endl;
    exit(0);
