        if(P[pp.second]<=pp.first) continue;
        P[pp.second] = pp.first;
        for(int i=0;i<G[pp.second].size();i++) {
            if(P[G[pp.second][i].first]>P[pp.second]+G[pp.second][i].second) PQ.push(make_pair(P[pp.second]+G[pp.second][i].second, G[pp.second][i].first));
        }
    }
}

