struct pret_t{
	int min;
	int max;
	int bl;
};

pret_t search(int x,vvi& graph,vi& come,vi& num,vector<pret_t>& pretvec){
	int i;
	pret_t pret;
	pret_t ptemp;

	come[x]=1;

	if(num[x]==-1){
		pret.min=0;
		pret.max=0;
		pret.bl=0;
	}else{
		pret.min=num[x];
		pret.max=num[x];
		pret.bl=1;
	}

	for(i=0;i<graph[x].size();i++){
		if(come[graph[x][i]]!=0) continue;
		ptemp=search(graph[x][i],graph,come,num,pretvec);
		if(ptemp.bl==0) continue;
		if(ptemp.bl==2){
			pret.bl=2;
			break;
		}
		ptemp.max++;
		ptemp.min--;
		if(pret.bl==0){
			pret=ptemp;
			pret.bl=1;
		}else{
			if((pret.max-ptemp.max)%2!=0){
				pret.bl=2;
				break;
			}
			pret.max=min(pret.max,ptemp.max);
			pret.min=max(pret.min,ptemp.min);
			if(pret.max<pret.min){
				pret.bl=2;
				break;
			}
		}
	}

	pretvec[x]=pret;
	return pret;
}

int inverse(int x,int prev,vvi& graph,vi& come,vi& num,vector<pret_t>& pretvec){
	int i;
	pret_t pret;
	pret_t ptemp;

	come[x]=1;

	if(pretvec[x].min<=prev+1&&prev+1<=pretvec[x].max){
		num[x]=prev+1;
	}else{
		num[x]=prev-1;
	}

	for(i=0;i<graph[x].size();i++){
		if(come[graph[x][i]]!=0) continue;
		inverse(graph[x][i],num[x],graph,come,num,pretvec);
	}

	return 0;
}

