    num[a] = b;
  }

  // step 1
  for(int i = 1; i <= n; ++i) {
    if( num[i] != -(1<<28) ) {
      fillRange(i, Range(num[i], num[i]));
    }
  }
  if( ansIsNo() ) {
    printf("No\n");
    return 0;
  }
  else {
    printf("Yes\n");
  }

