#define ALLOF(c) (c).begin(), (c).end()
typedef long long ll;
#define INF 100000000

vector<int> G[100005];
int val[100005];

bool visited[100005];
int mn[100005];
int mx[100005];

bool ok;

void dfs(int v, int gk){
  visited[v] = true;
  int mmx = INF;
  int mmn = -INF;
  rep(i,G[v].size()){
    int w = G[v][i];
    if(visited[w]) continue;

    dfs(w, 1-gk);
    mmx = min(mmx, mx[w]+1);
    mmn = max(mmn, mn[w]-1);
  }
  mx[v] = mmx;
  mn[v] = mmn;
  if(mmx < mmn) ok = false;
  if(val[v] != -INF){
    if(val[v]%2 != gk) ok = false;
    mx[v] = val[v];
    mn[v] = val[v];
  }
}
void dfs_ans(int v){
  visited[v] = true;
  rep(i,G[v].size()){
    int w = G[v][i];
    if(visited[w]) continue;

    if(mn[w] <= val[v]+1 && val[v]+1 <= mx[w]){
      val[w] = val[v]+1;
    }
    else if(mn[w] <= val[v]-1 && val[v]-1 <= mx[w]){
      val[w] = val[v]-1;
    }
    dfs_ans(w);
  }
}

int main(){
  int N;
  cin >> N;
  rep(i,N-1){
    int A, B;
    cin >> A >> B;
    A--;
    B--;
    G[A].push_back(B);
    G[B].push_back(A);
  }
  int K;
  cin >> K;
  rep(i,100005){
    val[i] = -INF;
    mn[i] = -INF;
    mx[i] = INF;
  }

  int root = -1;
  rep(i,K){
    int V, P;
    cin >> V >> P;
    V--;
    val[V] = P;
    root = V;
  }

  ok = true;
  dfs(root, val[root]%2);

  if(!ok){
    cout << "No" << endl;
    return 0;
  }

  rep(i,100005) visited[i] = false;
  dfs_ans(root);

  rep(i,N){
    if(val[i] == -INF){
      cout << "No" << endl;
      return 0;
    }
  }
  cout << "Yes" << endl;
  rep(i,N){
    cout << val[i] << endl;
  }


  return 0;
}

