const int INF = 1e8;

vector<int> g[100010];
int low[100010], high[100010];

bool __dfs(int cur, int pre, int num){
	bool res = false;
	for(auto to : g[cur]){
		if(to == pre) continue;
		if(high[to] != INF and high[to] % 2 != (num + 1) % 2){
			return true;
		}
		res |= __dfs(to, cur, num + 1);
	}
	return false;
}

void dfs(int cur, int pre){
	for(auto to : g[cur]){
		if(to == pre) continue;

		dfs(to, cur);
		high[cur] = min(high[cur], high[to] + 1);
		low[cur] = max(low[cur], low[to] - 1);
	}
}

void _dfs(int cur, int pre){
	for(auto to : g[cur]){
		if(to == pre) continue;
		high[to] = min(high[to], high[cur] + 1);
		low[to] = max(low[to], low[cur] - 1);
		_dfs(to, cur);
	}
}

