template<typename A, typename B> inline bool chmax(A &a, B b) { if (a<b) { a=b; return 1; } return 0; }
template<typename A, typename B> inline bool chmin(A &a, B b) { if (a>b) { a=b; return 1; } return 0; }

typedef long long ll;
typedef pair<int, int> pii;
typedef pair<ll, ll> pll;
typedef pair<int, pii> P;

const ll INF = 1ll<<60;
const ll MOD = 1000000007;
const double EPS  = 1e-10;

int n, k;
vector<int> g[112345];
int num[112345];

int main() {
	cin >> n;
	REP(i, n - 1) {
		int u, v;
		scanf("%d %d", &u, &v);
		u--; v--;
		g[u].push_back(v);
		g[v].push_back(u);
	}

	priority_queue<pii, vector<pii>, greater<pii> > pq;

	cin >> k;
	REP(i, k) {
		int v, p;
		scanf("%d %d", &v, &p);
		v--;
		num[v] = p;

		pq.push(pii(p, v));
	}

	fill(num, num + n, -1);

	while (!pq.empty()) {
		pii now = pq.top(); pq.pop();

		int p = now.first;
		int u = now.second;

		num[u] = p;

		REP(i, g[u].size()) {
			int v = g[u][i];
			if (~num[v]) continue;
			pq.push(pii(p + 1, v));
			num[v] = p + 1;
		}
	}

	bool ng = false;
	REP(u, n) if (num[u] == -1) ng = true;

	REP(u, n) REP(i, g[u].size()) {
		int v = g[u][i];
		if (abs(num[u] - num[v]) != 1) ng = true;
	}

	if (ng) puts("No");
	else {
		puts("Yes");
		REP(i, n) printf("%d\n", num[i]);
	}

	return 0;
}

