void c_dfs(ll now, ll par = -1){
    ll c = color[now] ^ 1;
    for(auto &to : graph[now]){
        if(to == par)continue;
        if(color[to] != -1 && color[to] != c){
            cok = false;
            continue;
        }
        color[to] = c;
        c_dfs(to, now);
    }
