int val[MAXN];

bool feasible = true;
int min[MAXN], max[MAXN], parity[MAXN];

void dfs_traverse(int u, int p = -1)
{
    min[u] = -INF, max[u] = INF;
    parity[u] = (val[u] == INF ? -1 : (val[u] & 1));
    for (std::vector<int>::iterator v = e[u].begin(); v != e[u].end(); ++v) if (*v != p) {
        dfs_traverse(*v, u);
        min[u] = std::max(min[u], min[*v] - 1);
        max[u] = std::min(max[u], max[*v] + 1);
        if (parity[*v] != -1) {
            if (parity[u] == -1) parity[u] = parity[*v] ^ 1;
            else if (parity[u] == parity[*v]) feasible = false;
        }
    }
    if (min[u] > max[u]) feasible = false;
    if (val[u] != INF) { 
        if (val[u] < min[u] || val[u] > max[u]) feasible = false;
        min[u] = max[u] = val[u];
    }
    //printf("%d | %d %d %d\n", u, min[u], max[u], parity[u]);
}       

void dfs_fill(int u, int p, int val)
{       
    ::val[u] = val;
    for (std::vector<int>::iterator v = e[u].begin(); v != e[u].end(); ++v) if (*v != p) {
        if (val + 1 >= min[*v] && val + 1 <= max[*v]) dfs_fill(*v, u, val + 1);
        else if (val - 1 >= min[*v] && val - 1 <= max[*v]) dfs_fill(*v, u, val - 1);
        else puts("> <"), assert(false);
    }
}       

