using Prop = pair<PLL, PLL>;
const ll INF = 5e15;

V<bool> written;
V<ll> numbers;
VV<pair<ll, Prop>> to_prop;
VV<ll> edges;
V<ll> ans;
bool success = true;

bool check_poss(const PLL &p) {
    return p.second == -INF || p.first >= p.second;
}

bool check_poss(const Prop &p) {
    return check_poss(p.first) && check_poss(p.second);
}

ll calc_indicator(const PLL &a) { return (a.second == -INF ? INF : a.first - a.second); }

bool comp(const PLL &a, const PLL &b) {
    ll dica = calc_indicator(a);
    ll dicb = calc_indicator(b);
    return dica > dicb;
}

void update(Prop &prop, const PLL &plus, const PLL &minus) {
    auto &pplus = prop.first;
    auto &pminus = prop.second;
    if(comp(pplus, plus)) pplus = plus;
    if(comp(pminus, minus)) pminus = minus; 
}

void update(Prop &prop, ll proped) {
    auto &pv = prop.first.second;
    auto &mv = prop.second.second;
    ll tmpp = (pv == -INF ? -INF : pv - proped);
    ll tmpm = (mv == -INF ? -INF : mv + proped);
    pv = mv = -INF;
    if(tmpp != -INF) {
        if(tmpp > 0) chmax(pv, tmpp);
        else chmax(mv, -tmpp);
    }
    if(tmpm != -INF) {
        if(tmpm > 0) chmax(mv, tmpm);
        else chmax(pv, -tmpm);
    }
}

Prop calc_prop(ll num, ll lnum, ll dist) {
    Prop ret(PLL(dist, -INF), PLL(dist, -INF));
    ll dic = abs(num - lnum);
    (num > lnum ? ret.first : ret.second) = PLL(dist, dic);
    return move(ret);
}

Prop dfs0(ll now, ll pre, ll lnum) {
    Prop ret = make_pair(PLL(0, -INF), PLL(0, -INF)); 
    for(ll nxt : edges[now]) {
        if(nxt == pre) continue;
        PLL plus, minus;
        tie(plus, minus) = dfs0(nxt, now, (written[now] ? numbers[now] : lnum));
        plus.first++;
        minus.first++;
        success &= (check_poss(plus) && check_poss(minus));
        to_prop[now].emplace_back(nxt, Prop(plus, minus));
        update(ret, plus, minus);
    }
    if(written[now]) return calc_prop(numbers[now], lnum, (ll)0);
    else return ret;
}

void dfs1(ll now, ll pre, ll proped, ll pnum) {
    if(written[now]) {
        DEBUG(proped, pnum);
        if(numbers[now] != proped + pnum) success = false;
    } else {
        numbers[now] = proped + pnum;
    }
    DEBUG(now, proped, success, numbers[now]);
    if(!success) return;
    for(const auto &ipr : to_prop[now]) {
        ll nxt;
        Prop pr;
        tie(nxt, pr) = ipr;
        update(pr, proped);
        success &= check_poss(pr);
        if(!success) return;
        PLL ppr, mpr;
        tie(ppr, mpr) = pr;
        dfs1(nxt, now, proped + (comp(ppr, mpr) ? -1 : 1), (written[now] ? numbers[now] : pnum));
    }
}

int main() {
    ll N;
    cin >> N;
    written = V<bool>(N, false);
    numbers = V<ll>(N);
    to_prop = VV<pair<ll, Prop>>(N);
    edges = VV<ll>(N);
    for(ll i = 1; i < N; i++) {
        ll a, b;
        cin >> a >> b;
        a--;
        b--;
        edges[a].push_back(b);
        edges[b].push_back(a);
    }

    ll K;
