    ll root = -1;
    for(ll i = 0; i < K; i++) {
        ll a, b;
        cin >> a >> b;
        a--;
        root = a;
        written[a] = true;
        numbers[a] = b;
    }
    dfs0(root, -1, numbers[root]);
    DEBUG(to_prop);
    dfs1(root, -1, 0, numbers[root]);
    if(success) {
        cout << "Yes\n";
        for(ll e : numbers) cout << e << endl;
    } else {
        cout << "No\n";
    }
    return 0;
}

