const int MAXN = 200005;

int n;
int dep[MAXN], dfn[MAXN], piv;
int val[MAXN], par[MAXN];
vector<int> gph[MAXN];
int minv[MAXN], actually[MAXN];

void solve(int x, int p){
	minv[x] = 2e9;
	if(x != p && val[x] != -1){
		minv[x] = val[x];
		return;
	}
	for(auto &i : gph[x]){
		if(i != par[x]){
			solve(i, p);
			minv[x] = min(minv[x], minv[i]);
		}
	}
}

void go(int x, int p){
	for(auto &i : gph[x]){
		if(i != par[x]){
			if(actually[i]) continue;
			if(minv[i] > minv[x]){
				val[i] = val[x] + 2;
			}
			else val[i] = val[x];
			go(i, p);
		}
	}
}

void dfs(int x, int p){
	dfn[x] = ++piv;
	for(auto &i : gph[x]){
		if(i != p){
			par[i] = x;
			dep[i] = dep[x] + 1;
			dfs(i, x);
		}
	}
}

int main(){
	scanf("%d",&n);
	for(int i=1; i<n; i++){
		int s, e; scanf("%d %d",&s,&e);
		gph[s].push_back(e);
		gph[e].push_back(s);
	}
	dfs(1, -1);
	memset(val, -1, sizeof(val));
	int q; scanf("%d",&q);
	int chk[2] = {};
	vector<int> cnd;
	int dap = 2e9;
	while(q--){
		int x, v; scanf("%d %d",&x,&v);
		val[x] = v + dep[x];
		dap = min(dap, v + dep[x]);
		chk[val[x] % 2] = 1;
		actually[x] = 1;
		cnd.push_back(x);
	}
	if(chk[0] && chk[1]){
		puts("No");
		return 0;
	}
	if(val[1] > dap){
		puts("No");
		return 0;
	}
	if(val[1] == -1){
		val[1] = dap;
		cnd.push_back(1);
		actually[1] = 1;
	}
	sort(cnd.begin(), cnd.end(), [&](const int &a, const int &b){
		return dfn[a] < dfn[b];
	});
	for(int i=0; i<cnd.size(); i++){
		solve(cnd[i], cnd[i]);
		go(cnd[i], cnd[i]);
	}
	for(int i=1; i<=n; i++){
		for(auto &j : gph[i]){
			if(par[i] == j) continue;
			if(val[j] - val[i] != 2 && val[j] != val[i]){
				puts("No");
				return 0;
			}
		}
	}
	puts("Yes");
	for(int i=1; i<=n; i++) printf("%d\n", val[i] - dep[i]);
}

