bool dfs(int V,int S,int L, int flag){
   //cout << V << ": " << S << "-" << L <<", "<< flag<<endl;
   if( arrived[V] || used[V] ) return true;
   if( S!=L && large[V]==small[V] ){
      if( S<=large[V] && large[V] <= L ) return true;
      return false;
   }
   arrived[V] = true;
   L=min(large[V],L);
   S=max(small[V],S);
   if( L%2!=flag ) L--;
   if (S%2!=flag ) S++;
   if( L < S ) return false;
   if( mod2[V] != -1 && mod2[V] != flag ) return false;
   //cout << V << ": " << S << "-" << L <<", "<< flag<<endl;
   large[V]=L;
   small[V]=S;
   mod2[V]=flag;
   for( int i = 0 ; i < (int)edge[V].size(); i++ ){
      if( arrived[edge[V][i]]!=true ){
         if( dfs( edge[V][i], S-1, L+1, 1-flag ) == false ){
            return false;
         }
      }
   }
   return true;
}
void dfs2(int V, int P){
   if( arrived[V] ) return ;
   arrived[V] = true;
   large[V]=P;
   small[V]=P;
   for( int i = 0 ; i < (int) edge[V].size(); i++ ){
      if( arrived[edge[V][i]] != true ){
         int next = edge[V][i];
         if( large[next] >= P+1 && small[next] <= P+1 ){
            dfs2(next,P+1);
         }
         else if( large[next] >= P-1 && small[next] <= P-1 ){
            dfs2(next,P-1);
         }
         else{
            cout <<" ERROR" << endl;
         }
      }
   }
}
