bool cansolve(int x)
{
    int l = -1000000, r = 1000000;
    for(int i = 0; i < graph[x].size(); i++){
        int nextnode = graph[x][i];
        if(parent[nextnode] != -1) continue;
        parent[nextnode] = x;
        bool tmp = cansolve(nextnode);
        if(!tmp) return false;
        l = max(l, range[nextnode].first - 1);
        r = min(r, range[nextnode].second + 1);
    }
    if(node[x] != -1){
        l = max(l, node[x]);
        r = min(r, node[x]);
    }
    if(r - l < 0 || r - l == 1) return false;
    // cout << x << " " << l << " " << r << endl;
    range[x] = make_pair(l, r);
    return true;
}

void definenode(int x)
{
    // cout << x << endl;
    int tmp = node[x];
    for(int i = 0; i < graph[x].size(); i++){
        int nextnode = graph[x][i];
        // cout << nextnode << " " << parent[nextnode] << endl;
        int l = range[nextnode].first, r = range[nextnode].second;
        if(parent[nextnode] != x) continue;
        if(l <= tmp - 1 && tmp - 1 <= r) node[nextnode] = tmp - 1;
        else if(l <= tmp + 1 && tmp + 1 <= r) node[nextnode] = tmp + 1;
        definenode(nextnode);
    }
    return;
}

