    if(!b)return ch[i] = false;
    lb = max(L[e] - 1, lb);
    if(g.dis[e] > R[e]){
      rb = min(R[e], rb);
    }else{
      rb = min(R[e] - 1, rb);
    }
  }
  if(lb > rb)return ch[i] = false;
  if(p[i] == - inf){
    L[i] = lb, R[i] = rb;
  }else{
    int t = (p[r] + g.dis[i] - p[i]) / 2;
    if(!(lb <= t && t <= rb))return ch[i] = false;
    L[i] = t, R[i] = t;
  }
  return ch[i] = true;
}

