	memset(id, -1, sizeof(id));
	int m;
	scanf("%d", &m);
	for (int i = 0; i < m; i++){
		int v, p;
		scanf("%d%d", &v, &p);
		v--, id[v] = p;
	}
	ans = 1;
	solve();
	if (!ans){
		puts("No");
		return 0;
	}
	make();
	puts("Yes");
	for (int i = 0; i < n; i++){
		printf("%d\n", id[i]);
	}
	return 0;
}

