const int maxn = 1e5 + 5;

int n, k, a, b, v, p, mi[maxn], ma[maxn], reqparity[2][maxn];
vector<int> adj[maxn];
vector<pii> mivals[maxn], mavals[maxn]; // {mi / ma, from}

void up(int x, int p)
{
    for(auto v : adj[x])
        if(v != p)
        {
            up(v, x);
            mivals[x].push_back({mi[v] - 1, v});
            mavals[x].push_back({ma[v] + 1, v});
            for(int j = 0; j < 2; j++)
                reqparity[j][x] |= reqparity[j ^ 1][v];
        }
    sort(mivals[x].begin(), mivals[x].end(), greater<pii>());
    sort(mavals[x].begin(), mavals[x].end());
    if(!mivals[x].empty())
        mi[x] = max(mi[x], mivals[x][0].first);
    if(!mavals[x].empty())
        ma[x] = min(ma[x], mavals[x][0].first);
}

void down(int x, int p, int parmi, int parma)
{
    if(p != -1)
    {
        mivals[x].push_back({parmi - 1, p});
        mavals[x].push_back({parma + 1, p});
        for(int j = 0; j < 2; j++)
            reqparity[j][x] |= reqparity[j ^ 1][p];
        sort(mivals[x].begin(), mivals[x].end(), greater<pii>());
        sort(mavals[x].begin(), mavals[x].end());
    }
    if(!mivals[x].empty())
        mi[x] = max(mi[x], mivals[x][0].first);
    if(!mavals[x].empty())
        ma[x] = min(ma[x], mavals[x][0].first);
    for(auto v : adj[x])
        if(v != p)
        {
            int takemi = -2e9, takema = 2e9;
            for(auto y : mivals[x])
                if(y.second != v)
                {
                    takemi = y.first;
                    break;
                }
            for(auto y : mavals[x])
                if(y.second != v)
                {
                    takema = y.first;
                    break;
                }
            down(v, x, takemi, takema);
        }
}

