inline bool include(int x,int y){
	return y>=f[x].fi&&y<=f[x].se&&(t[x]!=2||(y&1)==(f[x].fi&1));
}

void dfs(int x,int fa){
	f[x]={-N*2,N*2};
	for(int v:e[x])if(v!=fa){
		dfs(v,x);
		if(t[x]==0){
			t[x]=t[v];
			f[x]={f[v].fi-1,f[v].se+1};
		}else if(t[x]==1){
			t[x]=t[v];
			f[x].fi=max(f[x].fi,f[v].fi-1);
			f[x].se=min(f[x].se,f[v].se+1);
			if(t[v]==2){
				int fb=f[v].fi&1;
				if((f[x].fi&1)==fb)f[x].fi++;
				if((f[x].se&1)==fb)f[x].se--;
			}
		}else{
			int fb=~f[x].fi&1;
			if(t[v]==2&&(f[v].fi&1)!=fb)puts("No"),exit(0);
			f[x].fi=max(f[x].fi,f[v].fi-1);
