			int	to=v[from][i];
			if (ans[to]==ans[0])
			{
				ans[to]=ans[from]+1;
				qu.push(make_pair(ans[to],to));
			}
			if (abs(ans[to]-ans[from])!=1)
			{
				cout<<"No"<<endl;
				return 0;
			}
		} 
	}
	cout<<"Yes"<<endl;
	for (i=1;i<=n;i++)
	{
		cout<<ans[i]<<endl;
	}
	return 0;	
}

