const int INF = 1e8;

vector<int> g[100000];
vector<pair<int, int>> v(100000, make_pair(INF, -INF));
bool impossible;

void __dfs(int cur, int pre, int num){
	for(auto to : g[cur]){
		if(to == pre) continue;
		if(v[to].first != INF and v[to].first % 2 != (num + 1) % 2){
			impossible = true;
			return;
		}
		__dfs(to, cur, num + 1);
	}
}

pair<int, int> dfs(int cur, int pre){
	if(impossible) return pair<int, int>();

	pair<int, int> res(v[cur]);
	for(auto to : g[cur]){
		if(to == pre) continue;

		pair<int, int> d = dfs(to, cur);
		res.first = min(res.first, d.first + 1);
		res.second = max(res.second, d.second - 1);
	}

	if(res.first < res.second){
		impossible = true;
		return pair<int, int>();
	}

	//cout << res.first << ' '  << res.second << endl;
	return v[cur] = res;
}

void _dfs(int cur, int pre){
	for(auto to : g[cur]){
		if(to == pre) continue;
		if(v[to].first == INF){
			v[to] = make_pair(v[cur].first + 1, v[cur].second - 1);
		}
		_dfs(to, cur);
	}
}

int main(){
	int n;
	cin >> n;

	rep(i,n - 1){
		int a, b;
		cin >> a >> b;
		a--; b--;
		g[a].emplace_back(b);
		g[b].emplace_back(a);
	}

	int k;
	cin >> k;

	int s;
	rep(i,k){
		int V, p;
		cin >> V >> p;
		V--;
		v[V] = make_pair(p, p);
		s = V;
	}

	impossible = false;
	__dfs(s, -1, v[s].first);
	dfs(0, -1);

	if(impossible){
		cout << "No" << endl;
		return 0;
	}

	_dfs(0, -1);

	cout << "Yes" << endl;
	rep(i,n){
		cout << v[i].first << endl;
	}
}

#include <bits/stdc++.h>

using namespace std;
typedef long long ll;

const int MAXN = 100005;

int n, m;
vector<int> g[MAXN];

bool hv[MAXN];
int val[MAXN];
bool rng[MAXN];
int L[MAXN], R[MAXN];

void input()
{
	scanf("%d", &n);
	for(int i = 1; i < n; i++)
	{
		int x, y;
		scanf("%d%d", &x, &y);
		g[x].push_back(y);
		g[y].push_back(x);
	}
	scanf("%d", &m);
	for(int i = 1; i <= m; i++)
	{
		int x, v;
		scanf("%d%d", &x, &v);
		hv[x] = 1;
		val[x] = v;
	}
}

bool getrng(int x, int p)
{
	for(auto y: g[x])
	{
		if(y == p) continue;
		if(!getrng(y, x))
			return 0;
		if(rng[y])
		{
			int l = L[y] - 1;
			int r = R[y] + 1;
			if(rng[x])
			{
				if(R[x] < l || L[x] > r || ((L[x] + l) & 1))
					return 0;
				L[x] = max(l, L[x]);
				R[x] = min(r, R[x]);
			}
			else
			{
				rng[x] = 1;
				L[x] = l;
				R[x] = r;
			}
		}
	}
	if(hv[x])
	{
		if(rng[x] && (L[x] > val[x] || val[x] > R[x] || ((L[x] + val[x]) & 1)))
			return 0;
		rng[x] = 1;
		L[x] = R[x] = val[x];
	}
	return 1;
}

void getval(int x, int p)
{
	if(x == 1)
		val[x] = L[x];
	else
	{
		if(L[x] <= val[p] - 1)
			val[x] = val[p] - 1;
		else
			val[x] = val[p] + 1;
	}
	for(auto y: g[x])
		if(y != p)
			getval(y, x);
}

bool ok;

void solve()
{
	ok = getrng(1, 0);
	if(ok) getval(1, 0);
}

void output()
{
	if(ok)
	{
		puts("Yes");
		for(int i = 1; i <= n; i++)
			printf("%d\n", val[i]);
	}
	else puts("No");
}

int main()
{
	input();
	solve();
	output();

	return 0;
}

