		}
		curl=max(curl,l[y]-1);
		curr=min(curr,r[y]+1);
		if(curl>curr){
			puts("No");
			exit(0);
		}
	}
	if(have[x]){
		if(curl>l[x]||curr<r[x]||(curodd&&curodd!=odd[x])){
			puts("No");
			exit(0);
		}
	}
	else{
		l[x]=curl;
		r[x]=curr;
		odd[x]=curodd;
	}
	rep(i,edge[x].size()){
		int y=edge[x][i];
		if(y==par||have[y])continue;
		dfs(y,x);
		if(curodd&&odd[y]==curodd){
			puts("No");
