void dijkstra(int s){
    fill(d, d + 100010, INF);//V, INF
    d[s] = 0;
    priority_queue<P, vector<P>, greater<P> > q;
    q.push(P(d[s], s));
    while(!q.empty()){
        P p = q.top(); q.pop();
        int from = p.second;
        int cost = p.first;
        if(d[from] < cost) continue;
        rep(i, 0, G[from].size()){
            edge e = G[from][i];
            int next = e.to;
            int newCost = e.cost + cost;
            if(d[next] > newCost){
                d[next] = newCost;
                q.push(P(newCost, next));
            }
        }
    }
}

void dfs(int now, int pre){
    if(pre != -1){
        if(abs(d[now] - d[pre]) != 1) f = false;
    }
    // cout << now << " " << pre << endl;
    rep(i, 0, G[now].size()){
        int next = G[now][i].to;
        if(next == pre) continue;
        if(next == n) continue;
        if(abs(d[next] - d[now]) != 1) f = false;
        dfs(next, now);
    }

}


