class Graph{
	private:
	int V,root;
	vvi List;
	vi rank,a,L,R;
	void Rank(){
		queue<P> q;
		q.push({root,0});
		rank[root]=0;
		while(!q.empty()){
			P p=q.front();
			q.pop();
			int u=p.first;
			for(int i=0;i<List[u].size();i++){
				int w=List[u][i];
				if(rank[w]==-1){
					rank[w]=p.second+1;
					q.push({w,p.second+1});
				}
			}
		}
	}
	void BFS(){
		queue<int> q;
		vb used(V,0);
		for(int i=0;i<V;i++){
			bool flag=1;
			for(int j=0;j<List[i].size();j++){
				int v=List[i][j];
				if(rank[v]>rank[i]) flag=0;
			}
			if(flag){
				used[i]=1;
				q.push(i);
			}
		}
		while(!q.empty()){
			int v=q.front();
			q.pop();
			int l=-inf,r=inf;
			for(int i=0;i<List[v].size();i++){
				int u=List[v][i];
				if(rank[v]<rank[u]){
					l=max(l,L[u]-1);
					r=min(r,R[u]+1);
				}
				else q.push(u);
			}
			if(a[v]!=-1){
				l=max(l,a[v]);
				r=min(r,a[v]);
			}
			int eo=a[root]%2^rank[v]%2;
			if(l%2!=eo) l++;
			if(r%2!=eo) r--;
			L[v]=l;
			R[v]=r;
		}
	}
	bool bfs_f(int v,int x){
		if(R[v]<x||x<L[v]) return 1;
		a[v]=x;
		return 0;
	}
	bool bfs(){
		queue<int> q;
		q.push(root);
		if(bfs_f(root,a[root])) return 1;
		while(!q.empty()){
			int v=q.front();
			q.pop();
			for(int i=0;i<List[v].size();i++){
				int u=List[v][i];
				if(rank[v]<rank[u]){
					q.push(u);
					if(bfs_f(u,a[v]-1)&&bfs_f(u,a[v]+1)) return 1;
				}
			}
		}
		return 0;
	}
	public:
	Graph(int v){
		V=v;
		List=vvi(v);
	}
	void add_edge(int s,int t){
		List[s].push_back(t);
		List[t].push_back(s);
	}
	void solve(){
		L=R=vi(V);
		a=rank=vi(V,-1);
		int k;
		cin>>k;
		for(int i=0;i<k;i++){
			int v,p;
			cin>>v>>p;
			a[v-1]=p;
			if(!i) root=v-1;
		}
		Rank();
		BFS();
		if(bfs()) cout<<"No"<<endl;
		else{
			cout<<"Yes"<<endl;
			for(int i=0;i<V;i++) cout<<a[i]<<endl;
		}
	}
};

