void dfs(int p, int par=-1) {
    bool leaf = true;
    for(auto to : G[p]) {
        if(to == par) continue;
        leaf = false;
        dfs(to, p);
        L[p] = max(L[p], L[to] - 1);
        R[p] = min(R[p], R[to] + 1);
    }
}

void printans(int p, int val, int par=-1, int oe=-1) {
    if(oe < 0) oe = (val % 2);
    ans[p] = val;
    for(auto to : G[p]) {
        if(to == par) continue;
        int cur = val - 1;
        for(int i=0; i<3; i++) {
            int nval = cur + i;
            if(oe != (nval % 2) && L[to] <= nval && nval <= R[to]) {
                printans(to, nval, p, nval % 2);
                break;
            }
        }
    }
}

