    // either par_val-1 or par_val+1.

    bool can = false;
    int val;
    for(int t=par_val-1;t<=par_val+1;t+=2) {
        if (range[u].first <= t && range[u].second >= t) {
            can=true;
            val=t;
            break;
        }
    }

    if (!can)
        return false;

    answer[u]=val;
    for(int j=0;j<edges[u].size();j++) {
        int v=edges[u][j];
        if (v == par)
            continue;
        if (!dfs2(u,v,val))
            return false;
    }
    return true;

}

