ostream& operator<<(ostream& ostr, __float128& obj) { ostr << static_cast<double>(obj); return ostr; };

const int INF = 1e7;

struct node {
	pii rn;
	bool orig;

	node() {
		rn = pii(-INF,INF);
		orig = false;
	}
};

vector<node> V;
vector<vector<int> > E;
bool vis[100100];

pii dfs(int u, int pre, int parity) {
	vis[u] = true;
	if(V[u].orig) {
		if(parity == V[u].rn.fi % 2)
			return V[u].rn;
		return pii(1,-1);
	}
	pii res = V[pre].rn;
	res.fi--; res.se++;
	rep(i,E[u].size()) {
		int v;
		v = E[u][i];
		if(v == pre) continue;
		pii tmp;
		tmp = dfs(v,u, !parity);
		res.fi = max(res.fi, tmp.fi-1);
		res.se = min(res.se, tmp.se+1);
	}
	if(res.fi > res.se || (res.fi == res.se && res.fi % 2 != parity))
			res = pii(1,-1);
	return V[u].rn = res;
}

bool solve(int u, int pre) {
	if(V[u].orig) {
		//cout << "abs:" << (V[u].rn.fi) << "," << (V[pre].rn.fi) << endl;
		return abs(V[u].rn.fi - V[pre].rn.fi) == 1;
	}
	if(V[u].rn.fi <= V[pre].rn.fi+1 && V[pre].rn.fi+1 <= V[u].rn.se) {
		V[u].rn.fi = V[u].rn.se = V[pre].rn.fi+1;
	}
	else if(V[u].rn.fi <= V[pre].rn.fi-1 && V[pre].rn.fi-1 <= V[u].rn.se) {
		V[u].rn.fi = V[u].rn.se = V[pre].rn.fi-1;
	}
	else {
		//cout << u << endl;
		return false;
	}
	rep(i,E[u].size()) {
		if(E[u][i] == pre) continue;
		if(!solve(E[u][i], u)) {
			//cout <<"*"<< u << endl;
			return false;
		}
	}
	return true;
}

int main() {
	int N;
	cin >> N;
	V.resize(N);
	E.resize(N);
	rep(i,N-1) {
		int A, B;
		cin >> A >> B;
		A--; B--;
		E[A].push_back(B);
		E[B].push_back(A);
	}
	int K;
	cin >> K;
	vector<pii> cost;
	rep(i,K) {
		int v, p;
		cin >> v >> p;
		v--;
		cost.push_back(pii(v,p));
		V[v].rn = pii(p,p);
		V[v].orig = true;
	}

	bool ok = true;
	rep(i,cost.size()) {
		rep(j,E[cost[i].fi].size()) {
			int v;
			v = E[cost[i].fi][j];
			if(!vis[v]) {
				pii tmp;
				tmp = dfs(v,cost[i].fi, !(cost[i].se % 2));
				if(tmp.fi > tmp.se) {
					ok = false;
				}
				else {
					if(!solve(v,cost[i].fi)) {
						ok = false;
					}
				}
			}
		}
	}
	if(ok) {
		cout << "Yes" << endl;
		rep(i,N) {
			cout << V[i].rn.fi << endl;
		}
	}
	else {
		cout << "No" << endl;
	}

	return 0;
}

