void dfs(int index, int par) {
	int odd = 0, ev = 0;
	if (p[index] != -1) {
		l[index] = r[index] = p[index];
		if (p[index] % 2) odd++;
		else ev++;
	} else {
		l[index] = -1e9;
		r[index] = 1e9;
	}

	for (int neigh : tree[index]) {
		if (neigh == par)
			continue;
		dfs(neigh, index);
		if (l[neigh] == -1e9 and r[neigh] == 1e9) continue;
		if (l[neigh]-1 > r[index] or r[neigh]+1 < l[index]) {
			ok = 0;
		} else {
			if ((r[neigh]+1) % 2) odd++;
			else ev++;

			l[index] = max(l[index], l[neigh]-1);
			r[index] = min(r[index], r[neigh]+1);
		}
	}

	if (odd > 0 and ev > 0) {
		ok = 0;
	}
}

void solve(int index, int par, int a, int b) {
	val[index] = max(a, l[index]);
	for (int neigh : tree[index]) {
		if (neigh == par)
			continue;
		solve(neigh, index, val[index]-1, val[index]+1);
	}
}

