lli MOD = 1000000007;
#define MAX 100005
struct node {
    lli v, d;
    node(lli v, lli d) : v(v), d(d) {}
    bool operator<(const node& n) const { return d > n.d; }
};
struct edge {
    lli to, d;
    edge(int to,int d) : to(to), d(d) {}
};
lli V;
struct Graph {
    vector<edge> G[MAX];
    lli dist[MAX];  // shortest distance
    Graph()
    {
        rep(i, MAX)
        {
            G[i].clear();
            dist[i] = -1;
        }
    }
    void dijkstra(int s)
    {
        priority_queue<node> que;
        que.push(node(s, 0));
        while (!que.empty()) {
            lli v = que.top().v, d = que.top().d;
            que.pop();
            if (dist[v] >= 0 and dist[v] <= d)
                continue;
            dist[v] = d;
            for (int i = 0; i < G[v].size(); i++)
                que.push(node(G[v][i].to, d + G[v][i].d));
        }
    }
};
int main()
{
    lli a,b,n,v,p,k;
    cin >> n;
    Graph g1{};
    rep(i, n - 1)
    {
        cin >> a >> b;
        a--, b--;
        g1.G[a].push_back(edge(b,1));
        g1.G[b].push_back(edge(a,1));
    }
    cin >> k;
    rep(i, k)
    {
        cin >> v >> p;
        v--;
        g1.G[n].push_back(edge(v,p));
        g1.G[v].push_back(edge(n,p));
    }
    g1.dijkstra(n);
    queue<int> que;
    rep(i,n)cerr << i << ' ' << g1.dist[i]<<endl;
    que.push(0);
    while (!que.empty()) {
        int now = que.front();
        que.pop();
        for(int i = 0;i<g1.G[now].size();i++){
            edge s = g1.G[now][i];
            if (s.to == n || now == n)
                continue;
            if (abs(g1.dist[now] - g1.dist[s.to]) != 1) {
                cout << "No" << endl;
                return 0;
            }
        }
    }
    cout << "Yes" << endl;
    rep(i, n)
    {
        cout << g1.dist[i] << endl;
    }
}

