class Graph {
public:
	int vn;
	int sumcost = 0;
	vector<vector<pii>> g;

	Graph(int n) {
		vn = n;
		g.resize(n);
	}
	virtual void con(int a, int b, int w) = 0;
	int getWeight(int f, int t) {
		auto itr = lower_bound(ALL(g[f]), make_pair(t, INT_MIN));
		if (itr != g[f].end())
			return itr->second;
		return INT_MIN;
	}
	int Costsum() {
		return sumcost;
	}
	void scan(int edcount, bool oindexed, bool w) {
		REP(i, edcount) {
			int a, b, c = 1;
			scanf("%d %d", &a, &b);
			if (w)scanf("%d", &c);
			con(a - oindexed, b - oindexed, c);
		}
	}
};
class BiDGraph : public Graph {//無向
public:
	BiDGraph(int n) : Graph(n) {}

	void con(int a, int b, int w = 1) {
		g[a].push_back({ b,w });
		g[b].push_back({ a, w });
		sumcost++;
	}
};

signed main() {
	int n;
	cin >> n;
	BiDGraph g(n);
	REP(i, n-1) {
		int a, b;
		scanf("%d %d", &a, &b);
		g.con(a - 1, b - 1);
	}

	vector<int> depth(n),par(n);
	function<void(int, int)> dfs = [&](int c, int p) {
		par[c] = p;
		depth[c] = p == -1 ? 0 : depth[p] + 1;
		for (auto itr : g.g[c])
			if (itr.first != p)
				dfs(itr.first, c);
	};
	dfs(0, -1);

	vector<pii> num(n, {INT_MAX, INT_MAX});

	int m;
	cin >> m;
	priority_queue<pii, vector<pii> , greater<pii>> pq;
	REP(i, m) {
		int a, b;
		scanf("%d %d", &a, &b);
		--a;
		num[a] = { b,b };
		pq.push(MP(depth[a], a));
	}

	while (pq.size()) {
		auto cur = pq.top();
		pq.pop();

		if (cur.second == 0)
			continue;

		if (num[par[cur.second]] == MP(INT_MAX, INT_MAX)) {
			num[par[cur.second]] = MP(num[cur.second].first - 1, num[cur.second].second + 1 );
		}
		else {
			int cl = num[cur.second].first - 1, cr = num[cur.second].second + 1, l = num[par[cur.second]].first, r = num[par[cur.second]].second;

			num[par[cur.second]] = { max(cl,l), min(cr,r) };
			if (num[par[cur.second]].first > num[par[cur.second]].second) {
				printf("No\n");
				return 0;
			}
		}
		if(par[cur.second] != 0)
			pq.push(MP( depth[par[cur.second]],par[cur.second] ));
	}

	printf("Yes\n");
	vector<int> out(n);
	function<void(int, int)> ans = [&](int c, int p) {

		if (p == -1) 
			out[c] = num[c].first;
		else 
			out[c] = num[c].first <= (out[p]-1) ? out[p]-1 : out[p]+1;


		for (auto itr : g.g[c]) {
			if(itr.first != p)
				ans(itr.first, c);
		}
	};
	ans(0, -1);
	for (auto itr : out)
		printf("%d\n", itr);

	return 0;
}

