const int MAXN=110000;
const int INF=1E7;
vector<int> g[MAXN];
int w[MAXN], l[MAXN], r[MAXN];
bool c[MAXN];
bool dfs1(int u, int f, bool t)
{
	c[u]=t;
	if (~w[u]&&w[u]%2!=t) return 0;
	for (int i=0; i<g[u].size(); i++)
	{
		int v=g[u][i];
		if (v!=f&&!dfs1(v, u, t^1)) return 0;
	}
	return 1;
}
int dfs2(int u, int f)
{
	if (~w[u]) l[u]=r[u]=w[u];
	for (int i=0; i<g[u].size(); i++)
	{
		int v=g[u][i];
		if (v==f) continue;
		if (!dfs2(v, u)) return 0;
		l[u]=max(l[u], l[v]-1);
		r[u]=min(r[u], r[v]+1);
	}
	return l[u]<=r[u];
}
void dfs3(int u, int f, int k)
{
	w[u]=k;
	for (int i=0; i<g[u].size(); i++)
	{
		int v=g[u][i];
		if (v==f) continue;
		if (l[v]<=k-1&&k-1<=r[v]) dfs3(v, u, k-1);
		else dfs3(v, u, k+1);
	}
}
