	scanf("%d", &n);
	for (int i=1; i<n; i++)
	{
		int u, v;
		scanf("%d%d", &u, &v);
		g[u].push_back(v);
		g[v].push_back(u);
	}
	scanf("%d", &k);
	memset(w, -1, sizeof w);
	for (int i=1; i<=k; i++)
	{
		int v, p;
		scanf("%d%d", &v, &p);
		w[v]=p;
	}
	for (int i=1; i<=n; i++)
		if (~w[i])
		{
			if (!dfs1(i, 0, w[i]%2))
			{ puts("No"); return 0; }
			break;
		}
	for (int i=1; i<=n; i++) l[i]=-INF, r[i]=INF;
	if (!dfs2(1, 0)) { puts("No"); return 0; }
	puts("Yes");
	dfs3(1, 0, l[1]);
	for (int i=1; i<=n; i++) printf("%d\n", w[i]);
	return 0;
}

