struct pret_t{
	int min;
	int max;
	int bl;
};

pret_t search(int x,vvi& graph, vi& vec, vi& come,vector<pret_t>& pretvec){
	int i;
	int flag;
	pret_t pret;
	pret_t ptemp;

	come[x]=1;

	//xに数字が書いてある場合とない場合で分ける

	if(vec[x]!=-1){
		pret.max=vec[x];
		pret.min=vec[x];
		pret.bl=1;
	}else{
		pret.max=0;
		pret.min=0;
		pret.bl=0;
	}

	for(i=0;i<graph[x].size();i++){
		if(come[graph[x][i]]!=0) continue;

		ptemp=search(graph[x][i],graph,vec,come,pretvec);
		ptemp.max++;
		ptemp.min--;

		if(ptemp.bl==-1){
			pret=ptemp;
			break;
		}else if(pret.bl==0){
			if(ptemp.bl==0) continue;
			pret=ptemp;
		}else if(ptemp.bl==1){
			if((pret.max-ptemp.max)%2!=0) pret.bl=-1;
			pret.max=min(pret.max,ptemp.max);
			pret.min=max(pret.min,ptemp.min);
			if(pret.max<pret.min) pret.bl=-1;
		}
	}

	pretvec[x]=pret;
	return pret;
}

int inverse(int x,int num,vvi& graph,vi& vec, vi& come,vector<pret_t>& pretvec){
	int i;

	come[x]=1;
	if(pretvec[x].min<=num+1&&num+1<=pretvec[x].max){
		vec[x]=num+1;
	}else{
		vec[x]=num-1;
	}

	for(i=0;i<graph[x].size();i++){
		if(come[graph[x][i]]!=0) continue;
		inverse(graph[x][i],vec[x],graph,vec,come,pretvec);
	}

	return 0;
}

