const int maxn = 100010;

struct seg {
    int l, r, op;
    seg move() {
        seg ret;
        if (op != -1) ret.op = op^1;
        else ret.op = -1;
        if (op == 3) ret.op = 3;
        ret.l = l-1;
        ret.r = r+1;
        return ret;
    }
    int contain(int x) {
        if (op == -1) return 0;
        return x >= l && x <= r && ((op==3)||(x&1)==op);
    }
    seg(int v=0) {l=r=v; op=v&1;}
} full, dp[maxn];

struct Edge {
    int v, x;
} E[maxn<<1];

int l[maxn], e = 0;
int p[maxn], n, K;

inline void insert(int u, int v) {
    E[e].v = v; E[e].x = l[u]; l[u] = e++;
    E[e].v = u; E[e].x = l[v]; l[v] = e++;
}

seg operator*(const seg &x, const seg &y) {
    seg ret;
    if (x.op == -1 || y.op == -1) {
        ret.op = -1;
        return ret;
    }
    if (x.op == 3 && y.op != 3) {
        ret.op = y.op;
    } else if (x.op != 3 && y.op == 3) {
        ret.op = x.op;
    } else if (x.op != y.op) {
        ret.op = -1;
        return ret;
    } else ret.op = x.op;
    ret.l = max(x.l, y.l);
    ret.r = min(x.r, y.r);
    if (ret.l > ret.r) ret.op = -1;
    return ret;
}

void dfs(int u, int f) {
    dp[u] = full;
    if (p[u]) dp[u] = seg(p[u]);
    for (int p = l[u]; p >= 0; p = E[p].x) {
        int v = E[p].v;
        if (v != f) {
            dfs(v, u);
            dp[u] = dp[u]*dp[v].move();
        }
    }
}

void dfs_fill(int u, int f) {
    if (u == 1) p[u] = dp[u].l;
    else if (dp[u].contain(p[f]-1)) {
        p[u] = p[f]-1;
    } else if (dp[u].contain(p[f]+1)) {
        p[u] = p[f]+1;
    } else while (1) puts("ole");
    for (int p = l[u]; p >= 0; p = E[p].x) {
        int v = E[p].v;
        if (v != f) {
            dfs_fill(v, u);
        }
    }
}

int main() {
    memset(l, -1, sizeof(l));
    full.l = -1e6; full.r = 1e6; full.op = 3;
    scanf("%d", &n);
    for (int i = 1; i < n; i++) {
        int u, v; scanf("%d%d", &u, &v);
        insert(u, v);
    }
    scanf("%d", &K);
    for (int i = 1; i <= K; i++) {
        int v, x; scanf("%d%d", &v, &x);
        p[v] = x;
    }
    dfs(1, 0);
    if (dp[1].op == -1) {
        puts("No");
    } else {
        puts("Yes");
        dfs_fill(1, 0);
        for (int i = 1; i <= n; i++) {
            printf("%d\n", p[i]);
        }
        puts("");
    }
    return 0;
}

