int const MAXN = 1e5 + 5;
struct Edges { int to, next; } e[MAXN * 2];
int head[MAXN], tot;
int l[MAXN], r[MAXN], a[MAXN], vis[MAXN];

inline void addedge(int from, int to) {
  e[++tot] = (Edges){to, head[from]};
  head[from] = tot;
  e[++tot] = (Edges){from, head[to]};
  head[to] = tot;
}

void Put(int now, int fa, int num) {
  vis[now] = 1;
  ++l[now], --r[now];
  if (l[now] > r[now]) Cannot;
  if (r[now] < num - 1) Cannot;
  if (l[now] > num + 1) Cannot;
  if ((l[now] & 1) ^ (num & 1)) Cannot;
  if (r[now] == num - 1) a[now] = r[now];
  else a[now] = num + 1;
  for (RI i = head[now]; i; i = e[i].next)
    if (e[i].to != fa && !vis[e[i].to])
      Put(e[i].to, now, a[now]);
}

void Dfs(int now, int fa) {
  if (vis[now]) l[now] = r[now] = a[now];
  else l[now] = -1e6, r[now] = 1e6;
  for (RI i = head[now]; i; i = e[i].next)
    if (e[i].to != fa) {
      Dfs(e[i].to, now);
      l[now] = max(l[now], l[e[i].to]);
      r[now] = min(r[now], r[e[i].to]);
    }
  if (l[now] > r[now]) Cannot;
  if (vis[now]) {
    if (l[now] > a[now] || r[now] < a[now]) Cannot;
    if ((a[now] & 1) ^ (l[now] & 1)) Cannot;
    l[now] = r[now] = a[now];
    for (RI i = head[now]; i; i = e[i].next)
      if (e[i].to != fa)
        Put(e[i].to, now, a[now]);
  }
  --l[now], ++r[now];
}

