        while (!h.empty()) {
            pii o = h.top(); h.pop();
            if (s[t][o.yy] != o.xx)
                continue;
            for (int i = fir[o.yy]; i; i = ne[i])
                if (s[t][to[i]] < o.xx - 1)
                    s[t][to[i]] = o.xx - 1, h.push(make_pair(s[t][to[i]], to[i]));
        }
    } else {
        priority_queue<pii, vector<pii>, greater<pii> > h;
        for (int i = 1; i <= K; i++)
            h.push(make_pair(P[i], V[i]));
        while (!h.empty()) {
            pii o = h.top(); h.pop();
            if (s[t][o.yy] != o.xx)
                continue;
            for (int i = fir[o.yy]; i; i = ne[i])
                if (s[t][to[i]] > o.xx + 1)
                    s[t][to[i]] = o.xx + 1, h.push(make_pair(s[t][to[i]], to[i]));
        }
    }
}

void dfs(int o, int fa) {
    for (int i = fir[o], t; i; i = ne[i])
        if ((t = to[i]) != fa) {
            v[t] = v[o] + 1 <= s[1][t] ? v[o] + 1 : v[o] - 1;
            dfs(t, o);
        }
}

