const int maxn = 100010;
int n, m, tot, head[maxn], ans[maxn];
struct node {
    int num, val;
    node(){}
    node(int a, int b) {
        num = a, val = b;
    }
    bool operator < (const node & a) const {
        return val > a.val;
    }
};
struct line {
    int to, nxt;
} edge[maxn * 2];

void add(int u, int v) {
    edge[++tot].to = v, edge[tot].nxt = head[u], head[u] = tot;
}

int main()
{
    scanf("%d", &n);
    for(int u, v, i = 1; i < n; i++) {
        scanf("%d %d", &u, &v);
        add(u, v), add(v, u);
    }
    memset(ans, -1, sizeof(ans));
    scanf("%d", &m);
    priority_queue <node> pq;
    for(int u, p, i = 1; i <= m; i++) {
        scanf("%d %d", &u, &p);
        ans[u] = p;
        pq.push(node(u, p));
    }
    while(!pq.empty()) {
        node u = pq.top();
        pq.pop();
        for(int i = head[u.num]; i; i = edge[i].nxt) {
            int v = edge[i].to;
            if(ans[v] == -1) {
                ans[v] = u.val + 1;
                pq.push(node(v, ans[v]));
            }
        }
    }
    for(int i = 1; i <= n; i++)
        for(int j = head[i]; j; j = edge[j].nxt)
            if(abs(ans[i] - ans[edge[j].to]) != 1) {
                puts("No");
                return 0;
            }
    puts("Yes");
    for(int i = 1; i <= n; i++) printf("%d\n", ans[i]);
    return 0;
}

