vector<ll> minval,maxval;

void dfs2(vector<vector<ll>> &g, ll v, ll p,ll d) {
	if(minval[v]!=-INF && minval[v]%2!=d%2){
		cout<<"No"<<endl;exit(0);
	}
	for(ll nextv : g[v]){
		if(nextv==p) continue;
		dfs2(g, nextv, v,d+1);
	}
}



void dfs(vector<vector<ll>> &g, ll v, ll p) {
	if(p!=-1){
		chmax(minval[v],minval[p]-1);
		chmin(maxval[v],maxval[p]+1);
	}

	//更新
	for(ll nextv : g[v]){
		if(nextv==p) continue;
		dfs(g, nextv, v);
	}
	//反映
	for(ll nextv : g[v]){
		if(nextv==p) continue;
		chmax(minval[v],minval[nextv]-1);
		chmin(maxval[v],maxval[nextv]+1);
	}

	if(minval[v]>maxval[v]){
		cout<<"No"<<endl;exit(0);
	}
}

void dfs3(vector<vector<ll>> &g, ll v, ll p,vector<ll> &ans) {
	if(p!=-1){
		ll t=ans[p]-1;
		if(minval[v]<=t)ans[v]=t;
		else ans[v]=t+2;
	}

	for(ll nextv : g[v]){	
		if(nextv==p) continue;
		dfs3(g, nextv, v, ans);
	}

}

