int N, K;
vector<vector<int>> G;
vector<pair<int, int>> LR;
bool ng = false;
vector<int> ans;

void merge(pair<int, int> &x, pair<int, int> y){
    if(x.second == 1<<30){
        x.first = y.first-1;
        x.second = y.second+1;
        return;
    }
    if((x.first+(1<<20))%2 == (y.first+(1<<20))%2){
        ng = true;
        return;
    }
    x.first = max(x.first, y.first-1);
    x.second = min(x.second, y.second+1);
    if(x.first > x.second){
        ng = true;
        return;
    }
}

void dfs(int cur, int prv){
    for(int nxt : G[cur]){
        if(nxt == prv) continue;
        dfs(nxt, cur);
        if(LR[nxt].second==(1<<30)) continue;
        merge(LR[cur], LR[nxt]);
    }
    if(ng) return;
}

void dfs2(int cur, int prv){
    if(ans[cur] == 1<<30){
        ans[cur] = ans[prv] + 1;
    }
    for(int nxt : G[cur]){
        if(nxt == prv) continue;
        dfs2(nxt, cur);
    }
}

