        V--;
        LR[V] = make_pair(P, P);
    }

    dfs(0, -1);
    if(ng){
        cout << "No" << endl;
        return 0;
    }
    REP(i, N){
        if(LR[i].second != 1<<30){
            ans[i] = LR[i].first;
        }
    }

    dfs2(0, -1);
    cout << "Yes" << endl;
    REP(i, N){
        cout << ans[i] << endl;
    }

    return 0;
}

