int main() {
  int N;
  scanf("%d", &N);
  vector<vector<int>> G(N, vector<int>());
  for (int i = 0; i < N - 1; i++) {
    int a, b;
    scanf("%d%d", &a, &b);
    a--, b--;
    G[a].push_back(b);
    G[b].push_back(a);
  }

  vector<int> V(N, -1);
  priority_queue<pii, vector<pii>, greater<pii>> P;

  int K;
  cin >> K;
  for (int i = 0; i < K; i++) {
    int a, v;
    scanf("%d%d", &a, &v);
    a--;
