inline int rd()
{
	int x=0,f=1;char ch=getchar();
	for (;ch<'0'||ch>'9';ch=getchar()) if (ch=='-') f=-1;
	for (;ch>='0'&&ch<='9';ch=getchar()) x=x*10+ch-'0';
	return x*f;
}

inline void add(int x,int y) { a[++tot].t=y;a[tot].next=head[x];head[x]=tot; }

inline void dfs(int x,int y,int z)
{
	if (~num[x]&&(((num[x]&1)^(num[rt]&1))!=z)) { flag=false;return; }
	int h1=-2123333333,h2=2123333333;
	for (int i=head[x];i;i=a[i].next)
	{
		int t=a[i].t;
		if (t==y) continue;
		dfs(t,x,z^1);
		if (!flag) return;
		h1=max(h1,l[t]-1);
		h2=min(h2,r[t]+1);
	}
	if (~num[x]&&(h1>num[x]||h2<num[x])) { flag=false;return; }
	if (h1>h2) { flag=false;return; }
	if (!~num[x]) l[x]=h1,r[x]=h2;
}

inline void work(int x,int y)
{
	for (int i=head[x];i;i=a[i].next)
	{
		int t=a[i].t;
		if (t==y) continue;
		if (num[x]-1>=l[t]&num[x]-1<=r[t]) num[t]=num[x]-1;
		else num[t]=num[x]+1;
		work(t,x);
	}
}

int main()
{
	n=rd();tot=0;
	for (int i=1;i<n;i++)
	{
		int x=rd(),y=rd();
		add(x,y);add(y,x);
	}
	memset(num,-1,sizeof(num));
	for (int i=1;i<=n;i++) l[i]=-2123333333,r[i]=2123333333;
	m=rd();rt=0;
	while (m--)
	{
		int x=rd(),y=rd();
		num[x]=l[x]=r[x]=y;rt=x;
	}
	flag=true;
	dfs(rt,0,0);
	if (!flag) { puts("No");return 0; }
	work(rt,0);
	puts("Yes");
	for (int i=1;i<=n;i++) printf("%d\n",num[i]);
	return 0;
}

