template<class t,class u> void chmax(t&a,u b){if(a<b)a=b;}
template<class t,class u> void chmin(t&a,u b){if(b<a)a=b;}

const int INF = 1e9;
int N, K;
bool ok;
vvl edges;
vl mns, mxs;

bool isFixed(int node) {
    return mns[node] == mxs[node];
}
bool isFree(int node) {
    return mxs[node] == INF;
}
bool isFloating(int node) {
    return !isFixed(node) and !isFree(node);
}

void dfs(int parent, int pre) {
    for (auto child : edges[parent]) {
        if (child == pre) continue;
        if (isFixed(parent) and isFixed(child)) {
            if (abs(mxs[parent] - mxs[child]) != 1) {
                ok = false;
                return;
            }
        }
        chmax(mns[child], mns[parent] - 1);
        chmin(mxs[child], mxs[parent] + 1);

        dfs(child, parent);

        if (mxs[child] % 2 == mxs[parent] % 2 or
             mxs[child] < mns[parent]-1 or mxs[parent] < mns[child]-1) {
            ok = false;
            return;
        }
        chmax(mns[parent], mns[child] - 1);
        chmin(mxs[parent], mxs[child] + 1);
    }
}


int main() {
    cin >> N;
    ok = true;
    edges.resize(N);
    mxs.assign(N, INF);
    mns.assign(N, -INF);
    rep(i,N-1) {
        int a, b; cin >> a >> b;
        a--; b--;
        edges[a].push_back(b);
        edges[b].push_back(a);
    }
    cin >> K;
    int parent = 0, pre = -1;
    rep(i,K) {
        int v, p; cin >> v >> p;
        v--;
        mns[v] = mxs[v] = p;
        parent = v;
    }

    dfs(parent, pre);
    dfs(parent, pre);

    if (!ok) {
        cout << "No" << endl;
        return 0;
    }
    cout << "Yes" << endl;
    rep(node, N) {
        cout << mxs[node] << endl;
    }
    return 0;
}

