int n,m,val[maxn],x=-2,l[maxn],r[maxn],ans[maxn];
bool vis[maxn];
vector<int> G[maxn];
void dfs1(int u,int fa,int dep)
{
	if(vis[u])
	{
		if(x==-2) x=(dep^(val[u]&1));
		else if(x!=(dep^(val[u]&1)))
		{
			printf("No\n"); exit(0);
		}
	}
	for(int i=0;i<G[u].size();i++)
	{
		int v=G[u][i];
		if(v==fa) continue;
		dfs1(v,u,dep^1);
	}
}
void dfs2(int u,int fa)
{
	l[u]=-INF,r[u]=INF;
	if(vis[u]) l[u]=r[u]=val[u];
	for(int i=0;i<G[u].size();i++)
	{
		int v=G[u][i];
		if(v==fa) continue;
		dfs2(v,u);
		if(l[v]>r[u]||r[v]<l[u])
		{
			printf("No\n"); exit(0);
		}
		l[u]=max(l[v]-1,l[u]);
		r[u]=min(r[v]+1,r[u]);
	}
}
void dfs3(int u,int fa,int t)
{
    if(t+1<=r[u]) ans[u]=t+1;
    else if(t-1>=l[u]) ans[u]=t-1;
    for(int i=0;i<G[u].size();i++)
	{
        int v=G[u][i];
        if(v==fa) continue;
        dfs3(v,u,ans[u]);
    }
}
