void inter(set<int>& sup, set<int>& sub){
    set<int> nsup;
    if(sup.size() <= sub.size()){
        for(int e : sup){
            if(sub.find(e - 1) != end(sub) or sub.find(e + 1) != end(sub)){
                nsup.insert(e);
            }
        }
    }
    else {
        for(int e : sub){
            if(sup.find(e - 1) != end(sup)){
                nsup.insert(e - 1);
            }
            if(sup.find(e + 1) != end(sup)){
                nsup.insert(e + 1);
            }
        }
    }
    sup = nsup;
}

bool dfs(int v){
    used[v] = true;

    if(num[v] != inf) cand[v].insert(num[v]);
    bool fst = (cand[v].size() == 0);

    for(int nv : graph[v]){
        if(used[nv]) continue;

        if(not dfs(nv)){
            return false;
        }
        if(fst and cand[nv].size() >= 1){
            for(auto & e : cand[nv]){
                cand[v].insert(e - 1);
                cand[v].insert(e + 1);
            }
            fst = false;
        }
        else if(cand[nv].size() >= 1){
            inter(cand[v], cand[nv]);
            if(cand[v].size() == 0) return false;
        }
    }

    return true;
}

void dfs2(int v, int prev){
    if(prev == -1){
        if(cand[v].size() == 0){
            assert(num[v] == inf);
            num[v] = 0;
        }
        else num[v] = *begin(cand[v]);
    }
    else {
        if(cand[v].size() == 0) num[v] = num[prev] - 1;
        else {
            for(int p : cand[v]){
                if(p == num[prev] - 1 or p == num[prev + 1]){
                    num[v] = p;
                    break;
                }
            }
        }
    }
    for(auto nv : graph[v]){
        if(nv == prev) continue;
        dfs2(nv, v);
    }
}

