    if(vis[u] && c[u] != val[u]) return false;
    for(int i = head[u] ; i ; i = E[i].next) {
	int v = E[i].to;
	if(v != fa) {
	    int t = d;
	    if(mv[v] - d > 0) ++t;
	    if(!dfs2(v,u,t)) return false;
	}
    }
    return true;
}

