int solve(){
	queue<int> qu,que;
	qu.push(a[0]); li[a[0]]=b[0]%2;
	while(!qu.empty()){
		auto p=qu.front(); qu.pop();

		int c=0;
		for(auto e:g[p]){
			if(li[e]) continue;
			li[e]=li[p]+1;
			qu.push(e);
			c++;
		}
		if(!c) que.push(p);
	}
