#define inf 1000000000
const int maxn = 1e5 + 5;
vector<int> G[maxn];
int l[maxn],r[maxn];
int id[maxn];
bool flag;
void solve(int v = 0,int p = -1)
{
	l[v] = -inf - 1;
	r[v] = inf + 1;
	if(id[v] != -1)
	{
		l[v] = r[v] = id[v];
	}
	for(int i = 0;i < G[v].size(); ++i)
	{
		int to = G[v][i];
		if(to != p)
		{
			solve(to,v);
			if(l[to] < -inf / 2)
			{
				continue;
			}
			if(l[v] < -inf / 2)
			{
				l[v] = l[to] - 1;
				r[v] = r[to] + 1;
			}
			else
			{
				if(abs(l[to]) % 2 == abs(l[v]) % 2)
				{
					flag = 0;
					return;
				}
				l[v] = max(l[v],l[to] - 1);
				r[v] = min(r[v],r[to] + 1);
			}
		}
	}
	if(l[v] > r[v])
	{
		flag = 0;
	}
}
void make(int v = 0,int p = -1)
{
	if(v == 0 && id[v] == -1)
	{
		id[v] = l[v];
	}
	for(int i = 0;i < G[v].size(); ++i)
	{
		int to = G[v][i];
		if(to != p)
		{
			if(id[to] == -1)
			{
				if(l[to] <= id[v] - 1
					&& id[v] - 1 <= r[to])
				{
					id[to] = id[v] - 1;
				}
				else
				{
					id[to] = id[v] + 1;
				}
			}
			make(to,v);
		}
	}
}
