	if(f) return ;
	for(auto i:v[u]){
		if(i!=fa){
			if(vis[i]){
				if((a[i]&1)==odd||a[i]<l[u]-1||a[i]>r[u]+1){ f=1;return;}
			}
			else l[i]=l[u]-1,r[i]=r[u]+1;
			dfs(i,u,odd^1);
			l[u]=max(l[i]-1,l[u]);   //对称
			r[u]=min(r[i]+1,r[u]);
		}
	}
	if(r[u]<l[u]) f=1;
}
