int solve(){
	queue<int> qu,que;
	qu.push(a[0]); li[a[0]]=b[0]%2;
	while(!qu.empty()){
		auto p=qu.front(); qu.pop();

		int c=0;
		for(auto e:g[p]){
			if(li[e]) continue;
			li[e]=li[p]+1;
			qu.push(e);
			c++;
		}
		if(!c) que.push(p);
	}
	REP(i,0,m) if(li[a[i]]%2!=b[i]%2){cout << "No" << endl; return 0;}

	while(!que.empty()){
		auto p=que.front(); que.pop();
		if(used[p]) continue; used[p]=true;

		int mi=dp[p][0],ma=dp[p][1];
		for(auto e:g[p]){
			mi=max(mi,dp[e][0]);
			ma=min(ma,dp[e][1]);
			que.push(e);
		}

		mi=max(mi-1,-INF); ma=min(ma+1,INF);
		if(mi>ma){cout << "No" << endl; return 0;}
		dp[p][0]=mi,dp[p][1]=ma;
	}

	REP(i,0,n) used[i]=false;
	qu.push(a[0]); ans[a[0]]=b[0];
	while(!qu.empty()){
		auto p=qu.front(); qu.pop();
		if(used[p]) continue; used[p]=true;

		for(auto e:g[p]){
			if(dp[e][0]<=ans[p]-1&&ans[p]-1<=dp[e][1]) ans[e]=ans[p]-1;
			else if(dp[e][0]<=ans[p]+1&&ans[p]+1<=dp[e][1]) ans[e]=ans[p]+1;
			else{cout << "No" << endl; return 0;}
			qu.push(e);
		}
	}

	cout << "Yes" << endl;
	REP(i,0,n) cout << ans[i] << endl;
	return 0;
}

