vector<int> parent(100001, -1);
vector<pair<int, int> > range(100001);

bool cansolve(int x)
{
    int l = -1000000, r = 2000000;
    for(int i = 0; i < graph[x].size(); i++){
        int nextnode = graph[x][i];
        if(parent[nextnode] != -1) continue;
        parent[nextnode] = x;
        bool tmp = cansolve(nextnode);
        if(!tmp) return false;
        if(!(l == -1000000 && r == 2000000) && (l - range[nextnode].first) % 2 != (r - range[nextnode].second) % 2) return false;
        l = max(l, range[nextnode].first - 1);
        r = min(r, range[nextnode].second + 1);
        if((r - l) % 2 == 1) return false;
    }
    if(node[x] != -1){
        l = max(l, node[x]);
        r = min(r, node[x]);
    }
    if(r - l < 0 || (r - l) % 2 == 1) return false;
    // cout << x << " " << l << " " << r << endl;
    range[x] = make_pair(l, r);
    return true;
}

bool definenode(int x)
{
    // cout << x << endl;
    int tmp = node[x];
    for(int i = 0; i < graph[x].size(); i++){
        int nextnode = graph[x][i];
        // cout << nextnode << " " << parent[nextnode] << endl;
        int l = range[nextnode].first, r = range[nextnode].second;
        if(l == -1000000 && r == 2000000) continue;
        if(parent[nextnode] != x) continue;
        if(l <= tmp - 1 && tmp - 1 <= r){
            node[nextnode] = tmp - 1;
            if(definenode(nextnode)) continue;
        }
        if(l <= tmp + 1 && tmp + 1 <= r){
            node[nextnode] = tmp + 1;
            if(definenode(nextnode)) continue;
        }
        return false;
    }
    return true;
}

