{   
    cin >> n;    
    for(int i = 0; i < n - 1; i++){
        int a, b;
        cin >> a >> b;
        graph[a].push_back(b);
        graph[b].push_back(a);
    }
    int k;
    cin >> k;
    int v, p;
    for(int i = 0; i < k; i++){
        cin >> v >> p;
        node[v] = p;
    }
    parent[v] = 0;
    bool result = cansolve(v), ans = definenode(v);
    if(result && ans){
        cout << "Yes" << endl;
        for(int i = 1; i <= n; i++){
            cout << node[i] << endl;
        }
    } else {
        cout << "No" << endl;
    }
    return 0;
}

