const int N=1e5+19;

struct Edge{
	int y,nxt;
} E[N*2];
int las[N],val[N],mx[N],dep[N];
int n,cnt,m,x,y;

void Link(int x,int y){
	E[cnt]=(Edge){y,las[x]};las[x]=cnt++;
	E[cnt]=(Edge){x,las[y]};las[y]=cnt++;
}
void dfs(int x,int fa){
	if (~val[x]) mx[x]=val[x]-dep[x];
	for (int i=las[x],y;~i;i=E[i].nxt)
		if ((y=E[i].y)!=fa){
			dep[y]=dep[x]+1;
			dfs(y,x);
			mx[x]=max(mx[x],mx[y]);
		}
}
void work(int x,int fa){
	if (val[x]==-1){
		if (val[fa]-1>=mx[x]+dep[x]){
			val[x]=val[fa]-1;
		} else{
			val[x]=val[fa]+1;
		}
	}
	for (int i=las[x],y;~i;i=E[i].nxt)
		if ((y=E[i].y)!=fa){
			work(y,x);
		}
}
void check(int x,int fa){
	if (x>1&&abs(val[x]-val[fa])!=1){
		puts("No");
		exit(0); 
	}
	for (int i=las[x],y;~i;i=E[i].nxt)
		if ((y=E[i].y)!=fa){
			check(y,x);
		}
}

int main(){
	memset(las,-1,sizeof(las));
	memset(val,-1,sizeof(val));
	n=IN();
	For(i,1,n) Link(IN(),IN());
	m=IN();
	while (m--){
		x=IN(),y=IN();
		val[x]=y;
	}
	memset(mx,200,sizeof(mx));
	dfs(1,-1);
	if (val[1]==-1){
		val[1]=mx[1]+dep[1];
	}
	work(1,-1);
	check(1,-1);
	puts("Yes");
	For(i,1,n+1) printf("%d\n",val[i]);
}

