vector<vector<int> > tree;
vector<int> weight;
vector<vector<int> >ret;

void foo(int root)
{
	ret[root].resize(4);
	ret[root][0] = 0; ret[root][1] = INT;
	ret[root][2] = 1; ret[root][3] = INT + 1;
	for (int i = 0; i < tree[root].size(); ++i) {
		int tmp = tree[root][i];
		foo(tmp);
		if (ret[tmp][0] > ret[tmp][1] && ret[tmp][2] > ret[tmp][3]) {
			ret[root] = ret[tmp];
			return;
		}
		if (ret[tmp][2] <= ret[tmp][3]) {
            ret[root][0] = max(ret[root][0], ret[tmp][2] - 1);
            ret[root][1] = min(ret[root][1], ret[tmp][3] + 1);
		} else {
		    ret[root][0] = 0;
		    ret[root][1] = -2;
		}
		if (ret[tmp][0] <= ret[tmp][1]) {
            ret[root][2] = max(ret[root][2], ret[tmp][0] - 1);
            ret[root][3] = min(ret[root][3], ret[tmp][1] + 1);
		} else {
		    ret[root][2] = 1;
		    ret[root][3] = -1;
		}
	}

	if (weight[root] != INT) {
		if (weight[root] % 2 == 0) {
			ret[root][2] = 1; ret[root][3] = -1;
			if (!(ret[root][0] <= weight[root] && weight[root] <= ret[root][1])) {
				ret[root][0] = 0; ret[root][1] = -2;
			} else {
				ret[root][0] = ret[root][1] = weight[root];
			}
		} else {
			ret[root][0] = 0; ret[root][1] = -2;
			if (!(ret[root][2] <= weight[root] && weight[root] <= ret[root][3])) {
				ret[root][2] = 1; ret[root][3] = -1;
			} else {
				ret[root][2] = ret[root][3] = weight[root];
			}
		}
	}
	//printf("foo %d: %d %d %d %d\n", root, ret[root][0], ret[root][1], ret[root][2], ret[root][3]);
}

void result(int root, int prev)
{
	int f;
	if (prev == INT) {
		if (ret[root][0] <= ret[root][1]) f = ret[root][0];
		else f = ret[root][2];
	} else {
		if (prev % 2 == 0) {
			if (ret[root][2] <= prev - 1) f = prev - 1;
			else f = prev + 1;
		} else {
			if (ret[root][0] <= prev - 1) f = prev - 1;
			else f = prev + 1;
		}
	}
	weight[root] = f;
	for (int i = 0; i < tree[root].size(); ++i) {
		int tmp = tree[root][i];
		result(tmp, f);
	}
}

int main()
{
	//freopen("test", "r", stdin);
	int n; cin >> n;
	tree.resize(n + 1);
	ret.resize(n + 1);
	weight.resize(n + 1, INT);
	for (int i = 1; i < n; ++i) {
		int a, b; cin >> a >> b;
		if (a > b) swap(a, b);
		tree[a].push_back(b);
	}

	int k; cin >> k;
	for (int i = 0; i < k; ++i) {
		int a, b; cin >> a >> b;
		weight[a] = b;
	}

	foo(1);
	if (ret[1][0] > ret[1][1] && ret[1][2] > ret[1][3]) cout << "No\n";
	else {
		cout << "Yes\n";
		result(1, INT);
		for (int i = 1; i <= n; ++i) cout << weight[i] << '\n';
	}
	return 0;
}

