pll dfs1(int v, int p)
{
    forr(x,adj[v])
    {
        if(x!=p)
        {
            auto cur=dfs1(x,v);
            lim[v].ff=max(lim[v].ff,cur.ff);
            lim[v].ss=min(lim[v].ss,cur.ss);
        }
    }
    return make_pair(lim[v].ff-1,lim[v].ss+1);
}

bool flag=0;

void dfs2(int v, int p)
{
    if(val[v]==mod)
    {
        if(val[p]+1>=lim[v].ff&&val[p]+1<=lim[v].ss)
            val[v]=val[p]+1;
        if(val[p]-1>=lim[v].ff&&val[p]-1<=lim[v].ss) 
            val[v]=val[p]-1;
        else flag=1;
    }
    forr(x,adj[v]) if(x!=p) dfs2(x,v);
}

