using namespace std;
using lint = long long int;
template<class T = int> using V = vector<T>;
template<class T = int> using VV = V< V<T> >;
template<class T> void assign(V<T>& v, int n, const T& a = T()) { v.assign(n, a); }
template<class T, class... U> void assign(V<T>& v, int n, const U&... u) { v.resize(n); for (auto&& i : v) assign(i, u...); }

const int inf = 1e9;
struct edge { int to, cost; edge(int to, int cost) : to(to), cost(cost) {} };

template<class T> V<T> dijkstra(int s, const VV<edge>& g) {
  V<T> d(g.size(), inf);
  using P = pair<T, int>;
  priority_queue<P, V<P>, greater<P> > pq;
  pq.emplace(d[s] = 0, s);
  while (!pq.empty()) {
    T dv; int v; tie(dv, v) = pq.top(); pq.pop();
    if (dv > d[v]) continue;
    for (auto&& e : g[v]) {
      if (d[e.to] <= d[v] + e.cost) continue;
      pq.emplace(d[e.to] = d[v] + e.cost, e.to);
    } 
  }
  return d;
}

int main() {
  cin.tie(NULL); ios::sync_with_stdio(false);
  int n; cin >> n;
  VV<edge> g(n + 1);
  for (int i = 0; i < n - 1; i++) {
    int a, b; cin >> a >> b, a--, b--;
    g[a].emplace_back(b, 1);
    g[b].emplace_back(a, 1);
  }
  int k; cin >> k;
  for (int i = 0; i < k; i++) {
    int v, p; cin >> v >> p, v--;
    g[n].emplace_back(v, p);
    g[v].emplace_back(n, p);
  }
  auto d = dijkstra<int>(n, g);
  bool ok = true;
  for (int i = 0; i < n; i++) for (auto&& e : g[i]) if (e.to != n) {
    if (abs(d[i] - d[e.to]) != 1) ok = false;
  }
  for (auto&& e : g[n]) if (d[e.to] != e.cost) ok = false;
  if (ok) {
    cout << "Yes" << '\n';
    for (int i = 0; i < n; i++) cout << d[i] << '\n';
  } else cout << "No" << '\n';
}

