#define INF 1010001000

using namespace std;

int main()
{
    int n, a, b;
    cin >> n;

    vector<vector<int> > tree(n);

    for (int i = 0; i < n-1; i++) {
        cin >> a >> b;
        tree[--a].push_back(--b);
        tree[b].push_back(a);
    }

    vector<int> data(n, INF);
    priority_queue<pair<int, int> > priQue;

    int k;
    cin >> k;
    for (int i = 0; i < k; i++) {
        cin >> a >> b;
        data[--a] = b;
        priQue.push(pair<int, int>(b, a));
    }

    while (!priQue.empty()) {
        pair<int, int> p = priQue.top();
        priQue.pop();
        for (int i = 0; i < tree[p.second].size(); i++) {
            if (data[tree[p.second][i]] == INF) {
                data[tree[p.second][i]] = data[p.second] - 1;
                priQue.push(pair<int, int>(data[tree[p.second][i]], 
                            tree[p.second][i]));
            }
        }
    }

    for (int i = 0; i < n; i++) {
        for (int j = 0; j < tree[i].size(); j++) {
            if (abs(data[i] - data[tree[i][j]]) != 1) {
                cout << "No" << endl;
                return 0;
            }
        }
    }
    cout << "Yes" << endl;
    for (int i = 0; i < n; i++) {
        cout << data[i] << endl;
    }
    return 0;
}

