#include <algorithm>

using namespace std;

constexpr int INF = 0x3f3f3f3f;

vector<int> edges[100001];

struct Range {
	int lowerBound, upperBound;

	Range(int lb = -INF, int ub = INF): lowerBound(lb), upperBound(ub) {}

	bool have(int v) const {
		return lowerBound <= v && v <= upperBound;
	}

	void intersectWith(const Range &other) {
		lowerBound = max(lowerBound, other.lowerBound);
		upperBound = min(upperBound, other.upperBound);
	}

	Range extend() const {
		return {lowerBound - 1, upperBound + 1};
	}

	bool isValid() const {
		return lowerBound <= upperBound;
	}
} ranges[100001];

bool qinDing[100001];
int value[100001];

bool checkValidity(int x, int parent, int parity) {
	if (qinDing[x] && ranges[x].lowerBound % 2 != parity) return false;
	for (int child: edges[x])
		if (child != parent) {
			if (!checkValidity(child, x, 1 - parity)) return false;
			ranges[x].intersectWith(ranges[child].extend());
		}
	return ranges[x].isValid();
}

void fill(int x, int parent) {
	for (int child: edges[x])
		if (child != parent) {
			if (ranges[child].have(value[x] + 1)) value[child] = value[x] + 1; else value[child] = value[x] - 1;
			fill(child, x);
		}
}

int main() {
	int n;
	cin >> n;
	for (int i = 1; i < n; ++i) {
		int a, b;
		cin >> a >> b;
		edges[a].push_back(b);
		edges[b].push_back(a);
	}

	int k, r;
	cin >> k;
	for (int i = 0; i < k; ++i) {
		int v, p;
		cin >> v >> p;
		qinDing[v] = true;
		ranges[v] = Range(p, p);
		r = v;
	}

	if (!checkValidity(r, 0, ranges[r].lowerBound % 2)) {
		cout << "No" << endl;
		return 0;
	}

	value[r] = ranges[r].lowerBound;
	fill(r, 0);

	cout << "Yes" << endl;
	for (int i = 1; i <= n; ++i) cout << value[i] << '\n';

	return 0;
}

