	while(isdigit(ch))x=(x<<3)+(x<<1)+(ch^48),ch=getchar();
	return w?-x:x;
}
vector<int>G[maxn];
int n,k;
int L[maxn],R[maxn],dp[maxn],a[maxn];
inline void dfs(int u,int f,int l,int r)
{
    reg int i,sz=G[u].size();
    if(a[u])if(dp[u]!=(L[u]&1)){puts("No");exit(0);}
    if(a[u])l=L[u],r=R[u];else L[u]=l,R[u]=r;
    for(i=0;i<sz;++i)
    {
        if(G[u][i]==f)continue;
        dp[G[u][i]]=dp[u]^1;
        dfs(G[u][i],u,l-1,r+1);
    }
}
inline void dfs1(int u,int f)
{
    reg int i,sz=G[u].size();
    for(i=0;i<sz;++i)
    {
        if(G[u][i]==f)continue;
        dfs1(G[u][i],u);
        L[u]=max(L[u],L[G[u][i]]-1);
        R[u]=min(R[u],R[G[u][i]]+1);
        if(L[u]>R[u]){puts("No");exit(0);}
    }
}
inline void solve(int u,int f)
{
    reg int i,sz=G[u].size();
    if(L[u]>R[u]){puts("No");exit(0);}
    for(i=0;i<sz;++i)
    {
        if(G[u][i]==f)continue;
        L[G[u][i]]=max(L[G[u][i]],L[u]-1);
        R[G[u][i]]=min(R[G[u][i]],R[u]+1);
        solve(G[u][i],u);
    }
}
