    {
        x=read();a[x]=1;
        L[x]=R[x]=read();
    }
    dp[x]=L[x]&1;dfs(x,0,L[x],R[x]);
    dfs1(x,0);solve(x,0);puts("Yes");
    for(i=1;i<=n;++i)printf("%d\n",L[i]);
	return 0;
}

