		G::add(b,a);
	}
	G::dfs_dep(1);
	for(int q=nxi(),i=1; i<=q; ++i){
		const int x=nxi(),v=nxi();
		lim_l[x]=lim_r[x]=v;
		if(i==1) dif=(v&1)^(G::dep[x]&1);
		else if(((v&1)^(G::dep[x]&1))!=dif){
			puts("No");
			return 0;
		}
	}
	if(!G::dfs_vld(1)){
		puts("No");
		return 0;
	}
	ans[1]=lim_l[1];
	G::dfs_ans(1);
	puts("Yes");
	for(int i=1; i<=n; ++i){
		printf("%d\n",ans[i]);
	}
	return 0;
}

