il void link(int x,int y){nxt[++num]=head[x];to[num]=y;head[x]=num;}
il void dfs(int x,int last){
	if(mark[x] && (v[x]^(a[x]&1))){flag=0;return ;}
	for(int i=head[x];i;i=nxt[i]){
		int u=to[i];if(u==last)continue;
		v[u]=v[x]^1;dfs(u,x);
	}
}

