il void dfs2(int x,int last){
	if(mark[x])L[x]=R[x]=a[x];
	else L[x]=-2e8,R[x]=2e8;
	for(int i=head[x];i;i=nxt[i]){
		int u=to[i];if(u==last)continue;
		dfs2(u,x);
		L[x]=Max(L[x],L[u]-1);
		R[x]=Min(R[x],R[u]+1);
	}
	if(L[x]>R[x])flag=0;
}

il void dfs3(int x,int last){
	for(int i=head[x];i;i=nxt[i]){
		int u=to[i];if(u==last)continue;
		a[u]=a[x]+(a[x]+1<=R[u]?1:-1);
		dfs3(u,x);
	}
}

