			exit(0 * puts("No"));
		assert((l + r) % 2 == 0);
		now[u] = (l + r) >> 1, dif[u] = r - now[u];
	}
	else
		if(~dif[v])
			now[u] = now[v], dif[u] = dif[v] + 1;
}
inline void Solve(int u) {
	for(auto v : G[u])
		if(v != fa[u])
			fa[v] = u, Solve(v), Add(u, v);
}
inline void Work(int u) {
	val[u] = now[u] - (dif[u] % 2), now[u] = val[u], dif[u] = 0;
	for(auto v : G[u])
		if(v != fa[u])
			Add(v, u), Work(v);
}
int main() {
	scanf("%d", &n);
	for(int i = 1; i <= n; ++ i)
		dif[i] = val[i] = -1;
	for(int i = 1, x, y; i < n; ++ i)
		scanf("%d%d", &x, &y), G[x].push_back(y), G[y].push_back(x);
	scanf("%d", &k);
	for(int i = 1, x, y; i <= k; ++ i)
		scanf("%d%d", &x, &y), now[x] = y, dif[x] = 0;
	Solve(1), Work(1), puts("Yes");
	for(int i = 1; i <= n; ++ i)
		printf("%d\n", val[i]);
}

