#define INFG INFL
using Weight = ll;//int;

class Edge {
public:
	int s; //source
	int d; //destination
	Weight w; //weight
	Edge(int s = 0, int d = 0, Weight w = INFG) : s(s), d(d), w(w) {};
	bool operator<(const Edge &e)const { return w < e.w; }
};
using Edges = vector<Edge>;
//辺の挿入: g[u].push_back(Edge(u, v, c));
//無向木は両方向の辺をグラフに挿入する必要がある
using Graph = vector<Edges>;
using Array = vector<Weight>;
using Matrix = vector<Array>;

//未探索, 探索中, 探索済
enum { WHITE, GRAY, BLACK };
//単一始点最短路(負閉路なし) Single Source Shortest Path
//Dijkstra O( |E|log|V| )
//dist: 始点から各頂点までの最短距離
//戻り値: 最短路木の親頂点(根は-1)
vector<int> dijkstra(const Graph &g, int s, vector<Weight> &dist) {
	typedef tuple<Weight, int, int> State; //始点からの最小コスト 子 親
	priority_queue<State, vector<State>, greater<State> >PQ;
	int n = g.size();
	vector<int> color(n, WHITE);
	vector<int> prev(n, -1);
	dist.assign(n, INFG); //distance
	dist[s] = 0; PQ.push(State(0, s, -1)); color[s] = GRAY; //始点
	while (!PQ.empty()) {
		Weight d; int v; int u;
		tie(d, v, u) = PQ.top(); PQ.pop(); //distが最小値となる要素を取り出し
		if (dist[v] < d) continue; //すでに最短でなければ無視
		color[v] = BLACK;
		prev[v] = u;
		for (auto &e : g[v]) { //隣接する頂点が存在する限り		
			if (color[e.d] == BLACK)continue; //探索済は無視
			if (dist[e.d] > dist[v] + e.w) {
				dist[e.d] = dist[v] + e.w;
				PQ.push(State(dist[e.d], e.d, v));
				color[e.d] = GRAY;
			}
		}
	}
	return prev;
}

//単一始点最短路(負閉路あり) Single Source Shortest Path
//Bellman Ford O(|V||E|)
//dist: 始点から各頂点までの最短距離
//prev: 最短路木の親頂点
//戻り値: 負閉路なし:true あり:false
bool bellmanFord(const Graph &g, int s, vector<Weight> &dist, vector<int> &prev) {
	int n = g.size();
	Edges es; for (int i = 0; i < n; i++) for (auto &e : g[i]) es.emplace_back(e);
	dist.assign(n, INFG); dist[s] = 0;
	prev.assign(n, -1);
	bool negative_cycle = false;
	for (int i = 0;; i++) {
		bool update = false;
		for (auto &e : es) {
			if (dist[e.s] != INFG && dist[e.d] > dist[e.s] + e.w) {
				dist[e.d] = dist[e.s] + e.w;
				prev[e.d] = e.s;
				update = true;
			}
		}
		if (!update) break;
		if (i > n) { negative_cycle = true; break; }
	}
	return !negative_cycle;
}

//始点から終点までの経路を取得
//終点から親を再帰的に辿り始点に着くまでの経路を反転している
vector<int> getPath(int s, int g, vector<int> prev) {
	vector<int> path;
	path.push_back(g);
	for (int i = g; i != s; ) path.push_back(i = prev[i]);
	reverse(path.begin(), path.end());
	return path;
}

//全点対間最短経路 All Pairs Shortest Path
//Warshall Floyd O(|V|^3)
//戻り値: 負閉路なし:true あり:false
bool warshallFloyd(const Graph &g, Matrix &dist) {
	bool negative_cycle = false;
	int n = g.size();
	dist.assign(n, Array(n, INFG));
	for (int i = 0; i < n; i++) dist[i][i] = 0;
	for (int i = 0; i < n; i++)
		for (auto e : g[i])
			dist[e.s][e.d] = min(dist[e.s][e.d], e.w);
	for (int i = 0; i < n; i++)
		for (int j = 0; j < n; j++)
			for (int k = 0; k < n; k++)
				if (dist[j][i] != INFG&&dist[i][k] != INFG)
					dist[j][k] = min(dist[j][k], dist[j][i] + dist[i][k]);
	for (int i = 0; i < n; i++)
		if (dist[i][i] != 0)
			negative_cycle = true;
	return !negative_cycle;
}

