const int MAX_N = 128000;

int P[MAX_N];
int l[MAX_N], r[MAX_N], res[MAX_N];
vector<int> graph[MAX_N], g[MAX_N];
bool visited[MAX_N];

void make_graph(int v) {
  visited[v] = true;
  for (int i: graph[v]) {
    if (visited[i]) continue;
    g[v].push_back(i);
    make_graph(i);
  }
}

bool dfs(int v) {
  for (int i: g[v]) {
    if (!dfs(i)) return false;
  }
  l[v] = -1e9; r[v] = 1e9;
  for (int i: g[v]) {
    if (l[v] > -1e8 && l[i] > -1e-8 && ((l[v] ^ l[i]) & 1) == 0) return false;
    chmax(l[v], l[i] - 1);
    chmin(r[v], r[i] + 1);
  }
  if (l[v] > r[v]) return false;
  if (P[v] >= 0) {
    if (l[v] > -1e8 && ((l[v] + P[v]) & 1)) return false;
    if (P[v] < l[v] || P[v] > r[v]) return false;
    l[v] = P[v];
    r[v] = P[v];
  }
  // cout << v << " " << l[v] << " " << r[v] << endl;
  return true;
}

void dfs2(int v, int val) {
  res[v] = val;
  for (int i: g[v]) {
    if (val + 1 <= r[i]) dfs2(i, val + 1);
    else dfs2(v, val - 1);
  }
}

void solve() {
  int N, K;
  cin >> N;
  REP(i,N-1) {
    int A, B;
    cin >> A >> B;
    graph[A-1].push_back(B-1);
    graph[B-1].push_back(A-1);
  }
  memset(P, -1, sizeof(P));
  cin >> K;
  REP(i,K) {
    int V, C;
    cin >> V >> C;
    P[V-1] = C;
  }
  make_graph(0);
  if (!dfs(0)) { cout << false << endl; return; }
  dfs2(0, l[0]);
  cout << true << endl;
  REP(i,N) cout << res[i] << endl;
  return;
}

#include <bits/stdc++.h>

#define MAXN (100010)

int n, k;
int l[MAXN], r[MAXN];
bool has[MAXN];
std::vector<int> mat[MAXN];

bool union_seg(int &lu, int &ru, int lv, int rv, int odd, bool &mark){
	if(!mark){
		lu = lv;
		ru = rv;
		mark = true;
	}
	else{
		lu = std::max(lu, lv);
		ru = std::min(ru, rv);
	}
	if(lu > ru || lu == ru && (lu & 1) != odd) return false;
	return true;
}

bool dfs1(int u, int fa, int odd){
	if(has[u] && (l[u] & 1) != odd){
		return false;
	}
	for(auto v : mat[u]){
		if(v == fa) continue;
		if(!dfs1(v, u, !odd)){
			return false;
		}
		if(!union_seg(l[u], r[u], l[v] - 1, r[v] + 1, odd, has[u])){
			return false;
		}
	}
	if(!has[u]){
		l[u] = - 1e9;
		r[u] =   1e9;
	}
	return true;
}

bool inseg(int x, int l, int r){
	return l <= x && x <= r;
}

bool dfs2(int u, int fa){
	for(auto v : mat[u]){
		if(v == fa) continue;
		if(inseg(l[u] + 1, l[v], r[v])){
			l[v] = l[u] + 1;
			if(!dfs2(v, u)){
				return false;
			}
		}
		else if(inseg(l[u] - 1, l[v], r[v])){
			l[v] = l[u] - 1;
			if(!dfs2(v, u)){
				return false;
			}
		}
		else{
			return false;
		}
	}
	return true;
}

int main(){
	scanf("%d", &n);
	for(int i = 1; i < n; ++ i){
		int u, v;
		scanf("%d%d", &u, &v);
		mat[u].push_back(v);
		mat[v].push_back(u);
	}
	scanf("%d", &k);
	for(int i = 1; i <= k; ++ i){
		int v, p;
		scanf("%d%d", &v, &p);
		l[v] = r[v] = p;
		has[v] = true;
	}
	int root;
	for(root = 1; !has[root]; ++ root);
	if(!dfs1(root, 0, l[root] & 1)){
		return printf("No\n"), 0;
	}
	if(!dfs2(root, 0)){
	    return printf("No\n"), 0;
	}
	printf("Yes\n");
	for(int i = 1; i <= n; ++ i){
		printf("%d\n", l[i]);
	}
	return 0;
}

