const int N = 1e5 + 10;
const int oo = 1e9;

int n, k;
int val[N], Lmax[N], Rmax[N];
vector<int> vi[N];

void dfs(int pre, int u)    {
    int lmax = -oo, rmax = oo;
    if(val[u] != -1) lmax = rmax = val[u];
    for(int v: vi[u])   if(v != pre)    {
        dfs(u, v);
        lmax = max(lmax, Lmax[v] - 1);
        rmax = min(rmax, Rmax[v] + 1);
    }
    if(lmax > rmax) {
        cout << "No"; exit(0);
    } else Lmax[u] = lmax, Rmax[u] = rmax;
}

void solve(int pre, int u, int spm) {
    int nex = 0;
    if(Lmax[u] <= spm + 1 && spm + 1 <= Rmax[u]) nex = spm + 1;
    else nex = spm - 1;
    val[u] = nex;
    for(int v: vi[u])   if(v != pre){
        solve(u, v, nex);
    }
}

signed main()
{
    ios_base::sync_with_stdio(false);
    cin.tie(0); cout.tie(0);

