void getara(int x,int prev)
{
	if(a[x]!=-1)
		l[x]=r[x]=a[x];
	for(int i=0;i<edge[x].size();i++)
	{
		int y=edge[x][i];
		if(y!=prev)
		{
			getara(y,x);
			if(l[y]==-INF)
				continue;
			if(l[x]==-INF)
			{
				l[x]=l[y]-1;
				r[x]=r[y]+1;
			}
			else
			{
				if(abs(l[x]%2)==abs(l[y]%2))
				{
					cout<<"No";
					exit(0);
				}
				l[x]=max(l[x],l[y]-1);
				r[x]=min(r[x],r[y]+1);
			}
		}
	}
	if(l[x]>r[x])
	{
		cout<<"No";
		exit(0);
	}
}
void getans(int x,int prev)
{
	for(int i=0;i<edge[x].size();i++)
	{
		int y=edge[x][i];
		if(y!=prev)
		{
			if(a[y]==-1)
			{
				if(l[y]<=a[x]+1&&r[y]>=a[x]+1)
					a[y]=a[x]+1;
				else
					a[y]=a[x]-1;
			}
			getans(y,x);
		}
	}	
}
