const int maxn = 1e5 + 5;
vector<int>G[maxn];
int n, k, val[maxn], fa[maxn], now[maxn], dif[maxn], vis[maxn];
inline void Add(int u, int v) {
	if(~dif[u]) {
		int x = dif[v] + 1;
		if((now[u] + dif[u]) % 2 != (now[v] + x) % 2)
			exit(0 * puts("No"));
		int l = max(now[u] - dif[u], now[v] - x), r = min(now[u] + dif[u], now[v] + x);
		if(l > r)
			exit(0 * puts("No"));
		assert((l + r) % 2 == 0);
		now[u] = (l + r) >> 1, dif[u] = r - now[u];
	}
	else
		if(~dif[v])
			now[u] = now[v], dif[u] = dif[v] + 1;
}
inline void Solve(int u) {
	for(auto v : G[u]) {
		if(v == fa[u])
			continue;
		fa[v] = u;
		Solve(v);
		// cerr << u << " -> " << v <<" " << now[u] <<" " << dif[u] <<" " << now[v] <<" " << dif[v] << endl;
		Add(u, v);
	}
	if(~val[u]) {
		if(~dif[u] && (val[u] < now[u] - dif[u] || val[u] > now[u] + dif[u]))
			exit(0 * puts("No"));
		now[u] = val[u], dif[u] = 0;
	}
}
inline void Work(int u) {
	val[u] = now[u] - dif[u];
	for(auto v : G[u]) {
		if(v == fa[u])
			continue;
		Add(v, u), Work(v);
	}
}
int main() {
	scanf("%d", &n);
	for(int i = 1; i <= n; ++ i)
		dif[i] = val[i] = -1;
