	scanf("%d", &k);
	for(int i = 1, x, y; i <= k; ++ i)
		scanf("%d%d", &x, &y), val[x] = y;
	Solve(1), Work(1), puts("Yes");
	for(int i = 1; i <= n; ++ i)
		printf("%d\n", val[i]);
}

