int N, __K__, head[100001], next[199999], to[199999], E, q[100001], fa[100001];
int p[100001], w[100001], g[100001], L[100001], R[100001];
int main()
{
	scanf("%d", &N);
	for (int i = 1, u, v; i < N; i++)
	{
		scanf("%d%d", &u, &v);
		next[++E] = head[u], to[E] = v, head[u] = E;
		next[++E] = head[v], to[E] = u, head[v] = E;
	}
	for (scanf("%d", &__K__); __K__--; )
	{
		int x, y;
		scanf("%d%d", &x, &y);
		p[x] = 1;
		w[x] = y;
	}
	int H = 0, T = 1, u;
	q[1] = 1;
	while (H < T)
		for (int e = head[u = q[++H]]; e; e = next[e])
			if (to[e] != fa[u])
				fa[q[++T] = to[e]] = u;
	for (int i = N; i; i--)
	{
		int u = q[i];
		int appear_0 = 0, L_0 = -1000000000, R_0 = 1000000000;
		int appear_1 = 0, L_1 = -1000000000, R_1 = 1000000000;
		for (int e = head[u]; e; e = next[e])
			if (to[e] != fa[u] && g[to[e]])
			{
				if (L[to[e]] & 1)
				{
					appear_1 = 1;
					L_1 = std::max(L_1, L[to[e]]);
					R_1 = std::min(R_1, R[to[e]]);
				}
				else
				{
					appear_0 = 1;
					L_0 = std::max(L_0, L[to[e]]);
					R_0 = std::min(R_0, R[to[e]]);
				}
			}
		if (appear_0 && appear_1)
		{
			puts("No");
			return 0;
		}
		if (!appear_0 && !appear_1)
		{
			if (p[u])
			{
				g[u] = 1;
				L[u] = R[u] = w[u];
			}
			else
				g[u] = 0;
		}
		else
		{
			if (appear_0)
			{
				L[u] = L_0 - 1;
				R[u] = R_0 + 1;
			}
			else
			{
				L[u] = L_1 - 1;
				R[u] = R_1 + 1;
			}
			if (L[u] > R[u])
			{
				puts("No");
				return 0;
			}
			if (p[u])
			{
				if (w[u] < L[u] || w[u] > R[u] || !(w[u] ^ L[u] & 1))
				{
					puts("No");
					return 0;
				}
				L[u] = R[u] = w[u];
			}
			g[u] = 1;
		}
	}
	for (int i = 1; i <= N; i++)
	{
		int u = q[i];
		if (p[u])
			continue;
		if (u == 1)
			w[u] = L[u];
		else if (!g[u])
			w[u] = w[fa[u]] + 1;
		else if (L[u] <= w[fa[u]] + 1 && w[fa[u]] + 1 <= R[u])
			w[u] = w[fa[u]] + 1;
		else
			w[u] = w[fa[u]] - 1;
	}
	puts("Yes");
	for (int i = 1; i <= N; i++)
		printf("%d\n", w[i]);
	return 0;
}

