#include <bits/stdc++.h>

using namespace std;

const int MAX_V = 100000;
const int INF = 100000000;

int root;
vector<int> G[MAX_V];
int depth[MAX_V], l[MAX_V], r[MAX_V], num[MAX_V];

bool dfs(int v, int p, int d) {
	bool res = true;
	if (num[v] != INF) {
		l[v] = max(l[v], num[v]);
		r[v] = min(r[v], num[v]);
	}
	for (int i = 0; i < G[v].size(); i++) {
		if (G[v][i] == p) continue;
		res &= dfs(G[v][i], v, d + 1);
		if (!res) return false;
		l[v] = max(l[v], l[G[v][i]] - 1);
		r[v] = min(r[v], r[G[v][i]] + 1);
	}
	if (l[v] == r[v]) {
		res &= (abs(num[root] - l[v]) % 2 == d % 2);
	}
	res &= (l[v] <= r[v]);

	return res;
}

void dfs2(int v, int p, int n) {
	num[v] = n;
	for (int i = 0; i < G[v].size(); i++) {
		if (G[v][i] == p) continue;
		if (l[G[v][i]] <= n + 1 && r[G[v][i]] >= n + 1) {
			dfs2(G[v][i], v, n + 1);
		} else {
			dfs2(G[v][i], v, n - 1);
		}
	}	
}

int main() {
	cin.tie(0);
	ios::sync_with_stdio(false);
	int N;
	cin >> N;
	for (int i = 0; i < N; i++) {
		l[i] = -INF;
		r[i] = INF;
		num[i] = INF;
		if (i == N - 1) break;
		int A, B;
		cin >> A >> B;
		A--;
		B--;
		G[A].push_back(B);
		G[B].push_back(A);
	}

	int K;
	cin >> K;

	for (int i = 0; i < K; i++) {
		int V, P;
		cin >> V >> P;
		V--;
		num[V] = P;
		if (i == 0) root = V;
	}

	if (!dfs(root, -1, 0)) {
		cout << "No" << endl;
		return 0;
	}

	dfs2(root, -1, num[root]);

	cout << "Yes" << endl;
	for (int i = 0; i < N; i++) {
		cout << num[i] << endl;
	}

	return 0;
}

