pair<int,int> get(pair<int,int> a,pair<int,int> b){
	if (a.first==-1e9 || b.first==-1e9){
		return make_pair(-1e9,-1e9);
	}
	if (a.first>b.first){
		swap(a,b);
	}
	if (a.second<b.first){
		return make_pair(-1e9,-1e9);
	}
	else{
		return make_pair(b.first,min(a.second,b.second));
	}
}
