using namespace std;

typedef long long ll;

vector<int> e[100003];
int eo[100003];
int p[100003];
pair<int, int> range[100003];
bool visited[100003];

pair<int, int> func(int pos) {
	visited[pos] = true;
	for (int i = 0; i < (int)e[pos].size(); ++i) {
		if (visited[e[pos][i]]) continue;
		pair<int, int> ret = func(e[pos][i]);
		range[pos].first = max(range[pos].first, ret.first - 1);
		range[pos].second = min(range[pos].second, ret.second + 1);
	}
	return range[pos];
}

int main() {
	int n; cin >> n;
	for (int i = 0; i < n - 1; ++i) {
		int a, b; cin >> a >> b;
		--a; --b;
		e[a].push_back(b);
		e[b].push_back(a);
	}
	for (int i = 0; i < n; ++i) {
		range[i].first = -1e9;
		range[i].second = 1e9;
		p[i] = -1;
	}

	int k; cin >> k;
	int tp;
	deque<pair<int, int>> st;
	for (int i = 0; i < k; ++i) {
		int v, p_; cin >> v >> p_;
		--v;
		p[v] = p_;
		tp = v;
		range[v].first = p_;
		range[v].second = p_;
	}

	st.push_back({ tp,  p[tp]%2});
	for (int i = 0; i < n; ++i) eo[i] = -1;
	while (!st.empty()) {
		int pos = st.back().first;
		int evod = st.back().second;
		st.pop_back();
		eo[pos] = evod;
		for (int i = 0; i < (int)e[pos].size(); ++i) {
			if (eo[e[pos][i]] != -1) continue;
			st.push_back({ e[pos][i], 1 - evod });
		}
	}
	func(tp);
	for (int i = 0; i < n; ++i) {
		bool flag = false;
		for (int j = range[i].first; j <= range[i].second; ++j) {
			if ((j % 2 + 2)%2 == eo[i]) {
				flag = true;
				break;
			}
		}
		if (!flag) {
			cout << "No" << endl;
			return 0;
		}
	}
	cout << "Yes" << endl;
	vector<int> ans(n, -1);
	deque<pair<int, int>> st2;
	st2.push_back({ tp, p[tp] - 1 });
	while (!st2.empty()) {
		int pos = st2.back().first;
		int v = st2.back().second;
		st2.pop_back();
		if (range[pos].first <= v + 1 && v + 1 <= range[pos].second) {
			ans[pos] = v + 1;
		}
		else if (range[pos].first <= v - 1 && v - 1 <= range[pos].second) {
			ans[pos] = v - 1;
		}

		for (int i = 0; i < (int)e[pos].size(); ++i) {
			if (ans[e[pos][i]] != - 1) continue;
			st2.push_back({ e[pos][i], ans[pos] });
		}
	}
	for (int i = 0; i < n; ++i) cout << ans[i] << endl;
	return 0;
}

