int n, k, root = 0;
vector<vector<int>> g;
vector<int> res, l, r;

bool solve();
bool dfs(int now, int par, int dist);

int main() {
  cin >> n;
  g.resize(n);
  l.assign(n, -3000000);
  r.assign(n, 3000000);
  res.resize(n, -1);
  for (int i = 0; i < n - 1; ++i) {
    int a, b;
    cin >> a >> b;
    g[--a].push_back(--b);
    g[b].push_back(a);
  }
  cin >> k;
  for (int i = 0; i < k; ++i) {
    int node, p;
    cin >> node >> p;
    --node;
    l[node] = r[node] = res[node] = p;
    root = node;
  }
  if (solve()) {
    cout << "Yes" << endl;
    for (auto &p : res) cout << p << endl;
  } else
    cout << "No" << endl;
  return 0;
}

bool solve() {
  if (!dfs(root, -1, res[root] & 1)) return 0;
  for (int i = 0; i < n; ++i) {
    if (l[i] > r[i]) return 0;
    res[i] = l[i];
  }
  return 1;
}
bool dfs(int now, int par, int dist) {
  if (res[now] >= 0 && ((res[now] ^ dist) & 1)) return 0;
  if (par >= 0)
    l[now] = max(l[now], l[par] - 1), r[now] = min(r[now], r[par] + 1);
  for (auto to : g[now])
    if (to != par) {
      if (!dfs(to, now, dist ^ 1)) return 0;
      l[now] = max(l[now], l[to] - 1);
      r[now] = min(r[now], r[to] + 1);
    }
  for (auto to : g[now]) {
    l[to] = max(l[to], l[now] - 1);
    r[to] = min(r[to], r[now] + 1);
  }
  if (l[now] > r[now]) return 0;
  return 1;
}

