using namespace std;

bool dfs(const vector< vector<int> > &g, const int root, vector<int> &ans, int v, int d=0, int p=-1) {
    bool res = true;
    if(ans[v] != numeric_limits<int>::max() && ((ans[v]-ans[root]-d)%2 || (ans[v]-ans[root]) > d)) {
        res = false;
    } else if(ans[v] == numeric_limits<int>::max()) {
        ans[v] = ans[p] + 1;
    }
    for(auto u: g[v]) {
        if(u == p) continue;
        res &= dfs(g, root, ans, u, d+1, v);
    }
    return res;
}

void dfs2(const vector< vector<int> > &g, vector<int> &ans, int v, int p=-1) {
    int mn = numeric_limits<int>::max();
    for(auto u: g[v]) {
        if(u == p) continue;
        dfs2(g, ans, u, v);
        mn = min(mn, ans[u]);
    }
    if(mn == numeric_limits<int>::max()) return;
    if(ans[v]-mn > 1) {
        ans[v] = mn+1;
    }
}

int main(void) {
    int N;
    cin >> N;
    vector< vector<int> > g(N);
    for(int i=0; i<N-1; i++) {
        int A, B;
        cin >> A >> B;
        --A; --B;
        g[A].emplace_back(B);
        g[B].emplace_back(A);
    }

    vector<int> ans(N, numeric_limits<int>::max());
    int K;
    cin >> K;
    while(K--) {
        int V, P;
        cin >> V >> P;
        --V;
        ans[V] = P;
    }

    int root = distance(ans.begin(), min_element(ans.begin(), ans.end()));

    if(dfs(g, root, ans, root)) {
        cout << "Yes" << endl;
        dfs2(g, ans, root);
        for(auto e: ans) {
            cout << e << endl;
        }
    } else {
        cout << "No" << endl;
    }
    return 0;
}

