	if (M + 1 <= PM[A]) kotae[A] = M + 1;
	else kotae[A] = M - 1;
	for (int i = H[A]; i; i = ne[i]) {
		if (to[i] != prev) sagasu2(to[i], kotae[A], A);
	}
}

