using namespace utils;

class solver{
    istream& is;
    ostream& os;
    E_Set E;
    vector<ll> vL, vR;

public:
    solver(istream& I, ostream& O) :is(I), os(O) {}

    bool dfs(int v, int p){
        for (auto &&u : E[v]) {
            if(u == p) continue;
            if(!dfs(u, v)) return false;
            auto r = vR[u];
            auto l = vL[u];
            min_update(vR[v], r+1);
            max_update(vL[v], l-1);
        } // end i

        return vL[v] <= vR[v];
    }

    bool det_answer(int v, ll l, ll r, int p = -1){
        vL[v] = max(l, vL[v]);
        vR[v] = min(r, vR[v]);
        if(vL[v] > vR[v]) return false;
        for (auto &&u : E[v]) {
            if(u == p) continue;
            if(!det_answer(u, vL[v]-1, vR[v]+1, v)) return false;
        } // end u
        return true;
    }


    void run(){
        ll N;
        is >> N;
        if(!is) return;
        vL.resize(N, -INF);
        vR.resize(N, INF);
        for (int i = 0; i < N - 1; ++i) {
            int a, b; is >> a >> b; a--;b--;
            E[a].insert(b); E[b].insert(a);
        } // end i
        ll K;
        is >> K;
        for (int i = 0; i < K; ++i) {
            int v, p;
            is >> v >> p; v--;
            vL[v] = vR[v] = p;
        } // end i
        if(dfs(0, -1)){
            if(det_answer(0, -INF, INF)){
                cout << "Yes\n";
                for (int i = 0; i < N; ++i) {
                    cout << vL[i] << endl;
                } // end i
                return;
            }
        }
        cout << "No\n";

    }
};

