#include <algorithm>
#include <cassert>
#include <cstdio>
#include <vector>
#define MAXN 100000

using namespace std;

int N, K;
vector <int> adj[MAXN];
vector <int> val_idx;
int val[MAXN];
int par[MAXN];

int parity[MAXN];
int minval[MAXN], maxval[MAXN];

void dfs(int i, int prv) {
    par[i] = prv;
    for (int j : adj[i])
        if (j != prv)
            dfs(j, i);
}

void dfs_set(int i) {
    int prv = par[i];
    if (prv == -1) {
        val[i] = minval[i];
        assert((val[i] % 2 + 2) % 2 == parity[i]);
    }
    else if (val[i] == -1) {
        if (val[prv] - 1 >= minval[i] && val[prv] - 1 <= maxval[i])
            val[i] = val[prv] - 1;
        else
            val[i] = val[prv] + 1;
    }
    for (int j : adj[i])
        if (j != prv)
            dfs_set(j);
}

bool solve() {
    for (int i = 0; i < N; i++) {
        if (adj[i].size() > 1)
            continue;
        int prv = i;
        int cur = par[i];
        while (cur != -1) {
            if (parity[prv] != -1) {
                if (parity[cur] != -1) {
                    if (parity[cur] != 1 - parity[prv])
                        return false;
                    minval[cur] = max(minval[cur], minval[prv] - 1);
                    maxval[cur] = min(maxval[cur], maxval[prv] + 1);
                    if (minval[cur] > maxval[cur])
                        return false;
                }
                else {
                    parity[cur] = 1 - parity[prv];
                    minval[cur] = minval[prv] - 1;
                    maxval[cur] = maxval[prv] + 1;
                }
            }
            prv = cur;
            cur = par[cur];
        }
    }
    return true;
}

int main() {
    scanf("%d", &N);
    for (int i = 0; i < N - 1; i++) {
        int u, v;
        scanf("%d%d", &u, &v);
        u--, v--;
        adj[u].push_back(v);
        adj[v].push_back(u);
    }

    for (int i = 0; i < N; i++) {
        val[i] = -1;
        parity[i] = -1;
    }
    scanf("%d", &K);
    for (int i = 0; i < K; i++) {
        int v, p;
        scanf("%d%d", &v, &p);
        v--;
        val_idx.push_back(v);
        val[v] = p;
        parity[v] = p % 2;
        minval[v] = maxval[v] = p;
    }

    int root = val_idx[0];
    dfs(root, -1);

    if (solve()) {
        dfs_set(root);
        printf("Yes\n");
        for (int i = 0; i < N; i++)
            printf("%d\n", val[i]);
    }
    else {
        printf("No\n");
    }
}

#include <bits/stdc++.h>

#include <boost/range/adaptors.hpp>
#include <boost/range/irange.hpp>

using namespace std;
using namespace boost;
using namespace boost::adaptors;

constexpr auto INVALID = 1L << 30;

bool calc_range(const vector<vector<int64_t>>& adjs, const vector<int64_t>& p,
                vector<pair<int64_t, int64_t>>& range, int64_t v,
                int64_t prev) {
    auto& r = range[v];
    if (p[v] != -1) {
        r.first = r.second = p[v];
    }

    for (auto u : adjs[v]) {
        if (u == prev) {
            continue;
        }

        if (!calc_range(adjs, p, range, u, v)) {
            return false;
        }

        const auto& r2 = range[u];
        if (r2.first != INVALID) {
            if (r.first == INVALID) {
                r.first = r2.first - 1;
                r.second = r2.second + 1;
            } else if ((r.first - (r2.first - 1)) % 2 != 0) {
                return false;
            } else {
                r.first = max(r.first, r2.first - 1);
                r.second = min(r.second, r2.second + 1);
            }
        }
    }

    return r.first <= r.second;
}

void assign_value(const vector<vector<int64_t>>& adjs,
                  const vector<pair<int64_t, int64_t>>& range,
                  vector<int64_t>& values, int64_t v, int64_t prev) {
    for (auto u : adjs[v]) {
        if (u == prev) {
            continue;
        }

        values[u] = values[v] - 1;
        if (range[u].first != INVALID && values[u] < range[u].first) {
            values[u] = values[v] + 1;
        }
        assert(range[u].second == INVALID || values[u] <= range[u].second);
        assign_value(adjs, range, values, u, v);
    }
}

int main() {
    int64_t n;
    cin >> n;

    vector<vector<int64_t>> adjs(n);
    for (auto _ : irange(0L, n - 1)) {
        int64_t a, b;
        cin >> a >> b;
        --a;
        --b;
        adjs[a].push_back(b);
        adjs[b].push_back(a);
    }

    int64_t k;
    cin >> k;

    vector<int64_t> p(n, -1);
    for (auto _ : irange(0L, k)) {
        int64_t v;
        cin >> v;
        --v;
        cin >> p[v];
    }

    vector<pair<int64_t, int64_t>> range(n, make_pair(INVALID, INVALID));
    if (!calc_range(adjs, p, range, 0, -1)) {
        cout << "No" << endl;
        return 0;
    }

    vector<int64_t> ans(n);
    ans[0] = range[0].first;
    assign_value(adjs, range, ans, 0, -1);

    cout << "Yes" << endl;
    for (auto a : ans) {
        cout << a << "\n";
    }
}

