using namespace std;

typedef pair<int, int> P;
const int INF = 1e9;

int main() {
	int n; cin >> n;
	vector<vector<int>>graph(n);
	for (int i = 0, a, b; i < n; i++) {
		cin >> a >> b; a--; b--;
		graph[a].push_back(b); graph[b].push_back(a);
	}
	int k; cin >> k;
	vector<int>num(k, -1);
	for (int i = 0, v, p; i < k; i++) {
		cin >> v >> p; num[v - 1] = p;
	}

	vector<int>dist(n, INF);
	priority_queue<P, vector<P>, greater<P>>que;
	for (int i = 0; i < n; i++)if(num[i]>=0) {
		dist[i] = num[i];
		que.push({ dist[i],i });
	}
	while (que.size()) {
		int v = que.top().second; que.pop();
		for (int u : graph[v])	if (dist[u] > dist[v] + 1) {
			dist[u] = dist[v] + 1;
			que.push({ dist[u],u });
		}
	}

	bool ok = true;
	for (int i = 0; i < n; i++) {
		if (num[i] >= 0 && dist[i] != num[i])ok = false;
		for (int j : graph[i])if (dist[i] == dist[j])ok = false;
	}
	cout << (ok ? "Yes" : "No") << endl;
	if (ok)for (auto&& x : dist)cout << x << endl;

	return 0;
}

