constexpr int MAX_N = 100010, INF = 1<<30;

int N, K;
std::vector<int> G[MAX_N];
int L[MAX_N], R[MAX_N], A[MAX_N];
bool used[MAX_N];
bool fl = true;
int r;

void dfs( int v, int prv )
{
  used[v] = true;

  //printf( "(%d,%d)\n", v, prv );

  for( auto &u : G[v] ) if( !used[u] )
  {
    if( R[u] < L[v]-1 || R[v]+1 < L[u] )
    { fl = false; return; }

    L[u] = std::max( L[u], L[v]-1 );
    R[u] = std::min( R[u], R[v]+1 );

    dfs( u, v );
  }

  if( R[prv] < L[v]-1 || R[v]+1 < L[prv] )
  { fl = false; return; }

  L[prv] = std::max( L[prv], L[v]-1 );
  R[prv] = std::min( R[prv], R[v]+1 );

  return;
}

bool calc( int v )
{
  used[v] = true;

  //printf( "{%d}\n", v+1 );

  bool children = true;

  for( auto &u : G[v] ) if( !used[u] )
  {
    bool child = false;

    if( !A[u] )
    {
      if( L[u] <= A[v]+1 && A[v]+1 <= R[u] )
      {
        A[u] = A[v]+1;

        child |= calc( u );
      }

      if( !child && L[u] <= A[v]-1 && A[v]-1 <= R[u] )
      {
        A[u] = A[v]-1;

        child |= calc( u );
      }
    }

    child |= calc( u );

    children &= child;
  }

  if( !children )
    fl = false;

  return children;
}

