void addedge(int x,int y){
	edge[++cnt].to=y;
	edge[cnt].nxt=head[x];
	head[x]=cnt;
}
void dfs1(int x,int fa){
	for(int i=head[x];i;i=edge[i].nxt){
		int upup=edge[i].to;
		if(upup==fa)continue;
		dfs1(upup,x);
		point[x].maxn=min(point[x].maxn,point[upup].maxn+1);
		point[x].minn=max(point[x].minn,point[upup].minn-1);
		if(point[upup].opt!=-1){
			if(point[x].opt==-1)point[x].opt=point[upup].opt^1;
			else if(point[x].opt==point[upup].opt)Exit();
		}
	}
}
void dfs2(int x,int fa){
	if(fa){
		point[x].maxn=min(point[x].maxn,point[fa].maxn+1);
		point[x].minn=max(point[x].minn,point[fa].minn-1);
		if(point[x].opt!=-1)point[x].opt=point[fa].opt^1;
	}
	if(point[x].minn>point[x].maxn)Exit();
	if(point[x].minn==point[x].maxn&&(point[x].minn&1)!=point[x].opt)Exit();
	for(int i=head[x];i;i=edge[i].nxt){
		int upup=edge[i].to;
		if(upup==fa)continue;
		dfs2(upup,x);
	}
}
void getans(int x,int fa){
	if(!fa){
		if(point[x].minn%2==point[x].opt)point[x].ans=point[x].minn;
		else point[x].ans=point[x].minn+1;
	}
	else{
		point[x].ans=point[fa].ans-1;
		if(point[x].ans<point[x].minn)point[x].ans+=2;
	}
	for(int i=head[x];i;i=edge[i].nxt){
		int upup=edge[i].to;
		if(upup==fa)continue;
		getans(upup,x);
	}
}
