typedef vector<E> Graph;
const LL INF = 1e9;


E dijkstra(int s, Graph &g){
    int n = g.size();
    E dist(n,edge{-1,INF});
    priority_queue<edge, E, greater<edge>> que;
    que.push(edge{s,0});
    while (que.empty() == false){
        auto e = que.top(); que.pop();
        int v=e.to; 
        if (dist[v].cost < e.cost)continue;
	for (auto& d : g[e.to]){
            int u=d.to;
            int nc=e.cost+d.cost;
	    if (dist[u].cost <= nc)continue;
	    dist[u] = edge{v,nc};
	    que.push(edge{u,nc});
	}
    }
    return dist;
}

