#define N 100005

vector<int> adj[N];

int P[N];
bool hasValue[N];
int maxi[N],mini[N],myParent[N];
int dfsOrd[N], dfsPos = 0;

bool dfs(int node,int parent) {
  int parity;
  if(hasValue[node]) {
    maxi[node] = mini[node] = P[node];
    parity = P[node]&1;
  }
  dfsOrd[dfsPos++] = node;
  int sz = adj[node].size();
  for(int i=0;i<sz;++i) {
    int ch = adj[node][i];
    if(ch==parent) continue;
    if(!dfs(ch,node)) {
      return false;
    }
    if(!hasValue[ch]) {
      continue;
    } else {
      int tmpParity = maxi[ch]%2 ==0 ? 1 : 0;
      if(hasValue[node]) {
        if(tmpParity!=parity) {
          return false;
        }
        maxi[node] = min(maxi[node],maxi[ch]+1);
        mini[node] = max(mini[node],mini[ch]-1);
      } else {
        maxi[node] = maxi[ch] + 1;
        mini[node] = mini[ch] -1;
      }
      parity = tmpParity;
      hasValue[node] = true;
    }
  }
  if(mini[node]>maxi[node]) {
    return false;
  }
  return true;
}
int ret[N];
void construct(int node,int parent,int value) {
  ret[node] = value;
  for(int i=0;i<adj[node].size();++i) {
    int ch = adj[node][i];
    if(ch==parent) continue;
    if(!hasValue[ch]) {
      construct(ch,node,value-1);
    } else {
      int tmp = value-1;
      if(mini[ch]<=tmp && tmp<=maxi[ch]) {
        construct(ch,node,tmp);
      } else {
        construct(ch,node,tmp+2);
      }
    }
  }
}
void solve() {
  int n;scanf("%d ", &n);
  for(int i=0;i<n-1;++i) {
    int a,b;scanf("%d %d ", &a,&b);
    adj[a].push_back(b);
    adj[b].push_back(a);
  }
  int k;scanf("%d ",&k);
  int root = -1;
  for(int i=0;i<k;++i) {
    int num,v;
    scanf("%d %d ", &v,&num);
    P[v] = num;
    hasValue[v] = true;
    root = v;
  }
  assert(root!=-1);
  if(!dfs(root,0)) {
    printf("No\n");
    return;
  }
  construct(root,0,P[root]);
  printf("Yes\n");
  for(int i=1;i<=n;++i) {
    printf("%d\n", ret[i]);
  }
}

