vector<vector<int> > al;
vector<int> labels;
vector<pii> constraints;


pii gather(int from, int up) {
    int low = -1000111;
    int high = 1000111;
    ii (len(al[from])) {
        if (al[from][i] == up)
            continue;

        pii below = gather(al[from][i], from);
        if (below.vv == 1000111)    //No constraint.
            continue;
        if (below.uu == INFint)
            return pp(INFint, INFint);
        if (high != 1000111 && (high - below.vv) % 2 == 0)
            return pp(INFint, INFint);
        low = max(low, below.uu-1);
        high = min(high, below.vv+1);
    }

    if (low > high)
        return pp(INFint, INFint);
    if (-1 != labels[from]) {
        if (high != 1000111 && (high - labels[from]) % 2 == 1)
            return pp(INFint, INFint);
        if (!(low <= labels[from] && labels[from] <= high))
            return pp(INFint, INFint);
        return constraints[from] = pii(labels[from], labels[from]);
    }
    return constraints[from] = pii(low, high);

}

void push(int from, int up, int here) {
    labels[from] = here;

    ii (len(al[from])) {
        if (al[from][i] == up)
            continue;
        int nei = al[from][i];
        pii c = constraints[nei];
        if (c.vv == 1000111) {
            push(nei, from, here + 1);
        } else {
            if (c.uu <= here+1 && here+1 <= c.vv)
                push(nei, from, here + 1);
            else
                push(nei, from, here - 1);
        }
    }
}


