    cin>>n;
    int u, v;
    for(int i = 1;i < n; i++){
        scanf("%d%d", &u, &v);
        add(u, v); add(v, u);
    }
    int k;
    scanf("%d", &k);
    memset(L, -127, sizeof(L));
    memset(R, 127, sizeof(R));
    memset(ans, -127, sizeof(ans));
    memset(mark, -1, sizeof(mark));
    for(int i = 1;i <= k; i++){
        scanf("%d", &u);
        scanf("%d", &ans[u]);
        mark[u] = ans[u] & 1;
    }
    dfs(u, u);
    get(u, u);
    puts("Yes");
    for(int i = 1;i <= n; i++){
        //printf("i=%d L=%d R=%d ans=%d mark=%d\n", i, L[i], R[i], ans[i], mark[i]);
        printf("%d\n", ans[i]);
    }
    return 0;
}

