int ff;
void dfs(int u,int from,int d){
	if(ff) return ;
	if(p[u]) l[u]=r[u]=a[u];
	for(auto i:v[u]){
		if(i==from)continue;
		if(p[i]){
			if(a[i]<l[u]+1||a[i]>r[u]+1||(a[i]&1)==d){
			 ff=1;
			 return;
	   	}
	   	dfs(i,u,d^1);
	  }
	  else{
	  	l[i]=l[u]-1;
	  	r[i]=r[u]+1;
	  	dfs(i,u,d^1);
	  }
		l[u]=max(l[i]-1,l[u]);
		r[u]=min(r[i]+1,r[u]);
	}
	if(l[u]>r[u]) ff=1;
}
bool solve(int u,int from,int x){
   a[u]=x;
	 for(auto i:v[u]){
	   if(i==from) continue;
		 if(x+1>=l[i]&&x+1<=r[i]){
		  if(!solve(i,u,x+1))solve(i,u,x-1) ;
		 }
		 else solve(i,u,x-1);
	}
	return 1;
}
