const int inf=1<<28;
bool ok[N];
set<int> s[N],temp;
void add(int x,int y){
	cnt++;
	e[cnt].k=y;
	e[cnt].next=home[x];
	home[x]=cnt;
}
void dfs(int k,int F){
	if(F&&e[home[k]].next==-1){
		if(w[k]==inf) ok[k]=1;
		else{
			s[k].insert(w[k]);
		}
		return;
	}
	int son=0;
	for(int i=home[k];~i;i=e[i].next) if(e[i].k!=F){
		dfs(e[i].k,k);
		if(s[e[i].k].size()>s[son].size()||!son) son=e[i].k;
	}
	ok[k]=1;
	if(w[k]!=inf) ok[k]=0,s[k].insert(w[k]);
	set<int>::iterator t;
	for(int i=home[k];~i;i=e[i].next) if(e[i].k!=F&&e[i].k!=son){
		int x=e[i].k;
		if(ok[x]) continue;
		temp.clear();
		for(t=s[x].begin();t!=s[x].end();++t){
			if((ok[k]||s[k].find((*t)-1)!=s[k].end())) temp.insert((*t)-1);
			if(ok[k]||s[k].find((*t)+1)!=s[k].end()) temp.insert((*t)+1);
		}
		ok[k]=0;
		s[k]=temp;
	}
	if(!ok[son]&&son){
		if(ok[k]){
			ok[k]=0;
			for(t=s[son].begin();t!=s[son].end();++t) s[k].insert((*t)-1),s[k].insert((*t)+1);
		}
		else{
			for(t=s[k].begin();t!=s[k].end();){
				if(s[son].find((*t)-1)!=s[son].end()||s[son].find((*t)+1)!=s[son].end()){
					++t;continue;
				}
				s[k].erase(t++);
			}
		}
	}
}
void dfs1(int k,int F){
	if(F&&w[k]==inf){
		if(ok[k]||s[k].find(w[F]+1)!=s[k].end()) w[k]=w[F]+1;
		else w[k]=w[F]-1;
	}
	else if(w[k]==inf){
		if(!ok[k]&&s[k].size()==0) return;
		if(!ok[k]) w[k]=*s[k].begin();
		else w[k]=1;
	}
	for(int i=home[k];~i;i=e[i].next) if(e[i].k!=F){
		dfs1(e[i].k,k);
	}
}
