  rep(i,t){
    int x,y;
    cin>>x>>y; --x;
    poyo=x;
    vs[x]=1;
    nums[x]=y;
    MX(lb[x],nums[x]);
    MN(rb[x],nums[x]);
  }
  rep(hoge,2) dfs(g,vs,poyo,-1,nums[poyo],nums[poyo]);
  rep(i,n) dat[nn-1+i]=Seg(rb[i]-lb[i],i);
  if(query(0,n).mn<0){
    cout<<"No"<<endl;
    return 0;
  }
  rrep(i,nn-1) dat[i]=dat[2*i+1]+dat[2*i+2];
  vector<int> f(n);
  vector<int> re(n);
  rep(hoge,n){
    auto q=query(0,n);
    if(q.mn<0){
      return 1;
      cout<<"No"<<endl;
