void init(int v, int p)
{
  SL[v] = -INF;
  SR[v] = INF;
  if (V[v] != -1)
  {
    SL[v] = SR[v] = V[v];
  }

  FOR (i,0,SZ(G[v]))
  {
    int to = G[v][i];
    if (to == p) continue;
    init(to, v);
    SL[v] = max(SL[v], SL[to]-1);
    SR[v] = min(SR[v], SR[to]+1);
  }
}

void dfs(int v, int p, int l, int r)
{
  {
    int ll = max(l, SL[v]);
    int rr = min(r, SR[v]);

    if (ll > rr)
    {
      res = 0;
    }

    V[v] = ll;
  }

  if (T[v] != -1)
  {
    l = max(l, T[v]);
    r = min(r, T[v]);
  }

  multiset<int> L;
  multiset<int> R;
  FOR (i,0,SZ(G[v]))
  {
    int to = G[v][i];
    if (to == p) continue;
    L.insert(SL[to]);
    R.insert(SR[to]);
  }

  FOR (i,0,SZ(G[v]))
  {
    int to = G[v][i];
    if (to == p) continue;

    L.erase(L.find(SL[to]));
    R.erase(R.find(SR[to]));

    int ll = L.empty() ? -INF : *L.rbegin();
    int rr = R.empty() ? INF : *R.begin();

    ll -= 2;
    rr += 2;

    ll = max(ll, l-1);
    rr = min(rr, r+1);

    dfs(to, v, ll, rr);

    L.insert(SL[to]);
    R.insert(SR[to]);
  }

}

