const int MN=100000;
int N,K;
vector<int> G[MN];
int val[MN];
typedef pair<int,int> P;
P len[MN];
int inf=1e9;
P fre(-inf,inf);
void change(P& x,P y){
	if(y==fre) return;
	chmax(x.fs,y.fs-1);
	chmin(x.sc,y.sc+1);
}
void dfs(int v,int p,bool even){
	if(val[v]!=-1){
		if((val[v]%2==0)^even){
			puts("No");
			exit(0);
		}
		len[v]=P(val[v],val[v]);
	}else{
		len[v]=fre;
	}
	for(int u:G[v]) if(u!=p) dfs(u,v,!even);
	for(int u:G[v]) if(u!=p){
		change(len[v],len[u]);
	}
	if(len[v].fs>len[v].sc){
		puts("No");
		exit(0);
	}
}
bool in(P p,int now){
	return p.fs<=now && now<=p.sc;
}
int ans[MN];
void dfs2(int v,int p,int now){
	if(!in(len[v],now)) now+=2;
	assert(in(len[v],now));
	ans[v]=now;
	for(int u:G[v]) if(u!=p){
		dfs2(u,v,now-1);
	}
}
