const int INF = 1e8;

vector<int> g[100000];
vector<pair<int, int>> v(100000, make_pair(INF, -INF));
bool impossible;

pair<int, int> dfs(int cur, int pre){
	if(impossible) return pair<int, int>();

	pair<int, int> res(INF, -INF);
	for(auto to : g[cur]){
		if(to == pre) continue;

		pair<int, int> d = dfs(to, cur);
		if(d.first == INF) continue;

		d.first++;
		d.second--;
		//show(cur)
		//show(to)
		//cout << res.first << ' ' << res.second << endl;
		//cout << d.first << ' ' << d.second << endl;
		if(res.first == INF){
			res = d;
		}else{
			if(res.first % 2 != d.first % 2){
				impossible = true;
				return pair<int, int>();
			}
			res.first = min(res.first, d.first);
			res.second = max(res.second, d.second);
		}
	}

	int nh = min(v[cur].first, res.first);
	int nl = max(v[cur].second, res.second);

	if(nh < nl){
		impossible = true;
		return pair<int, int>();
	}

	v[cur] = make_pair(nh, nl);
	//rep(i,5){ cout << v[i].first << ' '; } cout << endl;
	//rep(i,5){ cout << v[i].second << ' '; } cout << endl;

	//show("res")
	//cout << res.first << ' ' << res.second << endl;
	return v[cur] = make_pair(nh, nl);
}

void _dfs(int cur, int pre){
	for(auto to : g[cur]){
		if(to == pre) continue;
		if(v[to].first == INF){
			v[to] = make_pair(v[cur].first + 1, v[cur].second - 1);
		}
		_dfs(to, cur);
	}
}

int main(){
	int n;
	cin >> n;

	rep(i,n - 1){
		int a, b;
		cin >> a >> b;
		a--; b--;
		g[a].emplace_back(b);
		g[b].emplace_back(a);
	}

	int k;
	cin >> k;

	rep(i,k){
		int V, p;
		cin >> V >> p;
		V--;
		v[V] = make_pair(p, p);
	}

	impossible = false;
	dfs(0, -1);

	if(impossible){
		cout << "No" << endl;
		return 0;
	}

	_dfs(0, -1);

	cout << "Yes" << endl;
	rep(i,n){
		cout << v[i].first << endl;
	}
}

