		else{
			if(w.size()==1){
				return d[x]=pii(w[0].F,w[0].S+1);
			}
			else{
				bool f = true;
				int t = (w[0].F+w[0].S)%2;
				reep(i,1,w.size()){
					if(t != (w[i].F+w[i].S)%2) f=false;
				}
				if(!f){
					ok=false;
					return d[x]=pii(-1,1);
				}
				int l=-INF;
				int r=INF;
				rep(i,w.size()){
					maxs(l,w[i].F-w[i].S);
					mins(r,w[i].F+w[i].S);
				}
				if(r<l) ok=false;
				pii ret(l+(r-l)/2,(r-l)/2);
				return d[x]=ret;
			}
		}
	}
}

void dfs2(int x, int pre, int val){
	if(v[x]<0){
		if(d[x].F-d[x].S<=val-1&&val-1<=d[x].F+d[x].S){
			v[x]=val-1;
		}
		else{
			assert(d[x].F-d[x].S<=val+1&&val+1<=d[x].F+d[x].S);
			v[x]=val+1;
		}
	}
	for(int y:vv[x]){
		if(pre==y) continue;
		dfs2(y,x,v[x]);
	}
}

