using namespace std;
typedef pair<int, int> P;

int N, K;
vector<int> G[100005];
int p[100005];
P val[100005];
int ans [100005];

bool check(int v, int prev, int r)
{
	if(p[v] != -1 && p[v] % 2 != r) return false;
	for(int i = 0; i < G[v].size(); i++){
		if(G[v][i] == prev) continue;
		if(!check(G[v][i], v, (r+1)%2)) return false;
	}
	return true;
}

P dfs(int v, int prev)
{
	P ret = make_pair(-inf, inf), res;
	for(int i = 0; i < G[v].size(); i++){
		if(G[v][i] == prev) continue;
		res = dfs(G[v][i], v);
		if(res.first == inf) return make_pair(inf, -inf);
		ret.first = max(ret.first, res.first-1);
		ret.second = min(ret.second, res.second+1);
	}
	if(ret.first > ret.second) return make_pair(inf, -inf);

	if(p[v] != -1){
		if(p[v] < ret.first || p[v] > ret.second) return make_pair(inf, -inf);
		else ret = make_pair(p[v], p[v]);
	}
	return val[v] = ret;
}

void dfs2(int v, int prev, int x)
{
	if(x == inf) ans[v] = val[v].first;
	else ans[v] = max(val[v].first, x-1);
	for(int i = 0; i < G[v].size(); i++){
		if(G[v][i] == prev) continue;
		dfs2(G[v][i], v, ans[v]);
	}
}

