		scanf("%d%d", &v, &p);
		ans[v] = p;
		vis[v] = 1;
	}

	DP(v, 0, p & 1, p, p);
	DFS(v, 0, p & 1);

	puts("Yes");
	for (int i = 1; i <= n; ++i) printf("%d\n", ans[i]);

	return 0;
}

