void pull(int u,int par){
  dw[u] = make_pair(-oo,oo);
  if(v[u] != -1)dw[u] = make_pair(v[u],v[u]);
  for(auto v : g[u]){
    if(v == par)continue;
    pull(v,u);
    dw[u].first = max(dw[u].first,dw[v].first-1);
    dw[u].second = min(dw[u].second,dw[v].second+1);
  }
}
void push(int u , int par){
  up[u] = make_pair(-oo,oo);
  if(par != -1)up[u] = make_pair(up[par].first-1,up[par].second+1);
  up[u] = make_pair(max(up[u].first,dw[u].first),min(up[u].second,dw[u].second));
  for(auto v : g[u]){
    if(v == par)continue;
    push(v,u);
  }
}
