void dfs1(int n,int mod){
	visited[n] = 1;
	even[n] = mod;
	if(A[n]!=-inf && A[n]%2!=mod) judge = false;
	for(int i=0;i<v[n].size();i++){
		int s = v[n][i];
		if(visited[s]==0){
			dfs1(s,1-mod);
		} 
	}
}

void dfs2(int n){
	visited[n] = 1;
	int ma = B[n],mi = A[n];
	for(int i=0;i<v[n].size();i++){
		int s = v[n][i];
		if(visited[s]==0){
			int s = v[n][i];
			dfs2(s);
			if(ma<A[s]-1 || B[s]+1<mi) judge = false;
			else if(A[s]-1<=mi && ma<=B[s]+1) continue;
			else if(mi<=A[s]-1 && B[s]+1<=ma){
				ma = B[s]+1;
				mi = A[s]-1;
			}
			else if(ma>=B[s]+1 && B[s]+1>=mi){
//				mi = max(A[s]-1,mi);
				ma = B[s]+1;
//				ma = min(B[s]+1,ma);
			}else{
				mi = A[s]-1;
			}
			if(ma<mi) judge = false;
		}
	}
	if(ma==mi && ma%2!=even[n]) judge = false; 
//	if(ma!=inf){
		B[n] = ma;
		A[n] = mi;
//	}
}

