			puts("No"),exit(0);
		info=node(v[x],v[x],v[x]&1);
	}
//	printf("dfs %d\n",x);
	for(int y:e[x])
		if(y!=fa)
			info=merge(info,dfs(y,x,info.rev()));
	if(v[x]!=-1){
		if(!info.check(v[x]))
			puts("No"),exit(0);
	}
	q[x]=info;
