#include <bits/stdc++.h>
using namespace std;

const int INF = 1 << 30;

int main() {
    int N; cin >> N;
    vector<vector<int>> G(N);
    for(int i = 0; i < N - 1; ++i) {
        int a, b; cin >> a >> b;
        a--, b--;
        G[a].emplace_back(b);
        G[b].emplace_back(a);
    }

    int K; cin >> K;
    vector<int> P(N, -1); // P[i] : 頂点 i に書き込む整数
    int v, p;
    for(int i = 0; i < K; ++i) {
        cin >> v >> p; v--;
        P[v] = p;
    }

    vector<int> parity(N); // 頂点 i の偶奇

    // 整数が書き込まれている頂点から dfs で各頂点の偶奇を決定する
    auto pfs = [&](auto &&pfs, int cur, int pre, int p) -> bool {
        parity[cur] = p;
        if(P[cur] != -1 and P[cur] % 2 != parity[cur]) return false;
        bool res = true;
        for(auto &to : G[cur]) {
            if(to == pre) continue;
            res &= pfs(pfs, to, cur, 1 - p);
        }
        return res;
    };

    // 既に書き込まれている整数と偶奇が矛盾していたら NG
    if(!pfs(pfs, v, v, p % 2)) return cout << "No" << '\n', 0;

    vector<pair<int, int>> rng(N, {INF, INF});

    // 頂点 i に書くことができる整数の範囲を返す([l, r])
    auto dfs = [&](auto &&dfs, int cur, int pre) -> pair<int, int> {
        if(rng[cur] != make_pair(INF, INF)) return rng[cur];
        int l = P[cur] == -1 ? -INF : P[cur];
        int r = P[cur] == -1 ? INF : P[cur];
        for(auto &to : G[cur]) {
            if(to == pre) continue;
            int tl, tr; tie(tl, tr) = dfs(dfs, to, cur);
            tl--, tr++;
            l = max(l, tl), r = min(r, tr);
        }
        if(parity[cur] == 0) l += l % 2, r -= r % 2;
        else l += (1 - l % 2), r -= (1 - r % 2);
        return rng[cur] = {l, r};
    };

    for(int i = 0; i < N; ++i) {
        int l, r; tie(l, r) = dfs(dfs, i, i);
        if(l > r) return cout << "No" << '\n', 0;
    }

    // 頂点 i に書かれる整数を決定していく
    auto efs = [&](auto &&efs, int cur, int pre, int n) -> void {
        P[cur] = n;
        for(auto &to : G[cur]) {
            if(to == pre) continue;
            int l, r; tie(l, r) = rng[to];
            if(l <= n - 1 and n - 1 <= r) efs(efs, to, cur, n - 1);
            else efs(efs, to, cur, n + 1);
        }
    };
    efs(efs, v, v, p);

    cout << "Yes" << '\n';
    for(int i = 0; i < N; ++i) cout << P[i] << '\n';
    return 0;
}

