} rem[N], tmp[N];
void add(int x, int y) {
    to[++sz] = y; nex[sz] = las[x]; las[x] = sz;
}
bool dfs(int now) {
    int cnt = 0, flag = 0;
    for (int i = las[now]; i; i = nex[i])
    if(!visit[to[i]]) {
        //printf("%d %d\n", now, to[i]);
        visit[to[i]] = true;
        if(!dfs(to[i])) {
            rem[now].empty = true;
            return false;
        }

    }
    else fa[now] = to[i];
    for (int  i = las[now]; i; i = nex[i])
    if(to[i] != fa[now]) {
        //printf("%d %d\n", now, to[i]);
        tmp[++cnt] = rem[to[i]];
       //printf("???? %d %d\n", tmp[cnt].l, tmp[cnt].r);
        tmp[cnt].l -= 1;
        tmp[cnt].r += 1;
        //printf("??? %d %d\n",tmp[cnt].l, tmp[cnt].r);
    }
    //for (int i = 1; i <= cnt; i++) 
        //printf("QAQ for now = %d %d %d\n",now, tmp[i].l, tmp[i].r);
    if(!rem[now].all)
    {
        tmp[++cnt] = rem[now];
    }
    //for (int i = 1; i <= cnt; i++) 
        //printf("laalala for now = %d %d %d\n",now, tmp[i].l, tmp[i].r);
    if(cnt == 0) return true;
    flag = abs(tmp[1].l & 1);
    for (int i = 1; i <= cnt; i++) {
        if(tmp[i].all) continue;
        //else if(tmp[i].empty) flag = -1;
        else if(abs(tmp[i].l & 1) != flag) flag = -1;
    }
    if(flag == -1) return false; 
    //sort(tmp + 1, tmp + cnt + 1, cmp);
    int maxl = -(1e9), minr = 1e9;
    for (int i = 1; i <= cnt; i++) {
