void init_ranges(t4 ranges[], const V<t2> vplist)
{
    for (auto vp : vplist) {
        ll v = get<0>(vp);
        ll p = get<1>(vp);
        ranges[v] = t4(p, p, !(p & 1LL), p & 1LL);
    }
}

void make_ranges(t4 ranges[], const V<ll> &leaves,
                 const ll parents[], const V<ll> children[], ll n)
{
    ll children_counts[n+1];
    rep (i, n+1) children_counts[i] = children[i].size();

    queue<ll> q;
    for (auto leaf : leaves) q.push(leaf);

    while (!q.empty()) {
        ll node = q.front(); q.pop();
        ll parent = parents[node];

        if (node == parent) continue;

        ll next_floor = get<0>(ranges[node]) - 1LL;
        ll next_ceil = get<1>(ranges[node]) + 1LL;
        ll next_even, next_odd;
        if (!(get<2>(ranges[node])) && !(get<3>(ranges[node]))) {
            next_even = next_odd = 0LL;
        }
        else {
            next_even = !(get<2>(ranges[node]));
            next_odd = !(get<3>(ranges[node]));
        }

        ll parent_floor = get<0>(ranges[parent]);
        ll parent_ceil = get<1>(ranges[parent]);
        ll parent_even = get<2>(ranges[parent]);
        ll parent_odd = get<3>(ranges[parent]);

        if ((next_even && parent_odd) || (next_odd && parent_even)) {
            cout << "No";
            exit(0);
        }

        ll new_floor = max(next_floor, parent_floor);
        ll new_ceil = min(next_ceil, parent_ceil);
        ll new_even = (next_even || parent_even);
        ll new_odd = (next_odd || parent_odd);
        assert((!new_even) || (!new_odd));

        debug_printf("---- updating ranges[%lld]\n", parent);
        debug_print(t4(new_floor, new_ceil, new_even, new_odd));

        if (new_floor > new_ceil) {
            cout << "No";
            exit(0);
        }
        if (new_floor == new_ceil) {
            if ((new_floor & 1LL) && new_even) {
                cout << "No";
                exit(0);
            }
            if (!(new_floor & 1LL) && new_odd) {
                cout << "No";
                exit(0);
            }
        }

        ranges[parent] = t4(new_floor, new_ceil, new_even, new_odd);
        if (--children_counts[parent] == 0LL) {
            q.push(parent);
        }
    }

    rep (i, n+1) {
        debug_printf("---- ranges[%lld]\n", i);
        debug_print(ranges[i]);
    }
}

void make_ans(ll ans[], const t4 ranges[], const V<ll> children[], ll n)
{
    queue<t3> q;
    q.push(t3(1LL, 0LL, false));

    while (!q.empty()) {
        t3 node_parentval_flag = q.front(); q.pop();
        ll node = get<0>(node_parentval_flag);
        ll parentval = get<1>(node_parentval_flag);
        ll flag = get<2>(node_parentval_flag);

        debug_printf("---- node=%lld\n", node);

        t4 range = ranges[node];
        ll floor = get<0>(range);
        ll ceil = get<1>(range);
        ll even = get<2>(range);
        ll odd = get<3>(range);

        if (!even && !odd) even = odd = 1LL;

        srep (val, max(floor, parentval - 1LL), ceil+1LL) {
            if ((val & 1LL) && odd && (!flag || abs(parentval - val) == 1LL)) {
                ans[node] = val;
                break;
            }
            if (!(val & 1LL) && even && (!flag || abs(parentval - val) == 1LL)) {
                ans[node] = val;
                break;
            }
        }

        for (auto child : children[node]) q.push(t3(child, ans[node], true));
    }
}

