    V<ll> leaves;
    make_leaves(leaves, children, n);

    t4 ranges[n+1];
    rep (i, n+1) ranges[i] = t4(-(ll)pow(10LL, 18LL), (ll)pow(10LL, 18LL),
                                0LL, 0LL);
    init_ranges(ranges, vplist);
    make_ranges(ranges, leaves, parents, children, n);

    ll ans[n+1];
    make_ans(ans, ranges, children, n);

    cout << "Yes" << endl;
    srep (i, 1LL, n+1) cout << ans[i] << endl;

    return 0;
}

