pair<int, int> visit1(const vector<set<int>>& e, vector<pair<int, int>>& b, int v)
{
    for (int i : e[v])
    {
        auto p = visit1(e, b, i);
        if (p.first == -1)
            continue;
        if (p.first == -2)
            b[v].first = -2;
        ++p.first;
        --p.second;
        if (b[v].first == -1)
            b[v] = p;
        else
            if ((b[v].first & 1) != (p.first & 1) || (b[v].second & 1) != (p.second & 1))
                b[v].first = -2;
            else
            {
                b[v].first = min(b[v].first, p.first);
                b[v].second = max(b[v].second, p.second);
            }
    }
    return b[v];
}

bool visit2(const vector<set<int>>& e, vector<pair<int, int>>& b, int v, pair<int, int> p)
{
    if (p.first != -1)
    {
        if (p.first == -2)
            b[v].first = -2;
        ++p.first;
        --p.second;
        if (b[v].first == -1)
            b[v] = p;
        else
            if ((b[v].first & 1) != (p.first & 1) || (b[v].second & 1) != (p.second & 1))
                b[v].first = -2;
            else
            {
                b[v].first = min(b[v].first, p.first);
                b[v].second = max(b[v].second, p.second);
            }
    }
    bool r = true;
    for (int i : e[v])
        r = r && visit2(e, b, i, b[v]);

    return r && (b[v].first == -1 || (b[v].first != -2 && b[v].first >= b[v].second));
}

