}

bool dfs2(int v,int parent,vector<int> &mn,vector<int> &mx,const vector<vector<int>> &g,const vector<int> &num){
    for(int u:g[v]){
        if(u==parent)continue;
        if(!dfs2(u,v,mn,mx,g,num)){
            return false;
        }
        mn[v]=max(mn[v],mn[u]-1);
        mx[v]=min(mx[v],mx[u]+1);
        if(mx[v]<mn[v])return false;
    }
    return true;
}

void construct(int v,int parent,vector<int> &mn,vector<int> &mx,const vector<vector<int>> &g,vector<int> &num){
    for(int u:g[v]){
        if(u==parent)continue;
        if(mn[u]<=num[v]-1){
            num[u]=num[v]-1;
        }
        else{
            num[u]=num[v]+1;
        }
        construct(u,v,mn,mx,g,num);
    }
}

