void merge(int &l, int &r, int ll, int rr) {
    l = max(l, ll), r = min(r, rr);
    if (l > r) puts("No"), exit(0);
}

void dfs(int u, int p) {
    if (w[u] != INF) return L[u] = R[u] = w[u], void();
    L[u] = -INF, R[u] = INF;
    for (int i = fir[u], v; i; i = nxt[i]) {
        v = to[i];
        if (v == p) continue;
        dfs(v, u);
        merge(L[u], R[u], L[v] - 1, R[v] + 1);
    }
}

void dfs2(int u, int p) {
    if (p) {
        if (L[u] <= w[p] - 1 && w[p] - 1 <= R[u]) w[u] = w[p] - 1;
        if (L[u] <= w[p] + 1 && w[p] + 1 <= R[u]) w[u] = w[p] + 1;
        if (w[u] == INF) puts("No"), exit(0);
    }
    for (int i = fir[u]; i; i = nxt[i])
        if (to[i] != p && w[to[i]] == INF) dfs2(to[i], u);
}

inline int Abs(int x) { return x < 0 ? -x : x; }

void getok(int u, int p) {
    if (p && Abs(w[p] - w[u]) != 1) puts("No"), exit(0);
    for (int i = fir[u]; i; i = nxt[i])
        if (to[i] != p) getok(to[i], u);
}

