    int r;
    function<bool(int,int)> rec=[&](int u,int d){
        used[u]=true;
        if(p[u]!=-1) lb[u]=ub[u]=p[u];
        for(int v:graph[u]){
            if(used[v]){
                if(p[u]!=-1 and abs(p[u]-p[r])%2!=d%2) return false;
                continue;
