                cout << "No" << endl;
                return;
            }
            break;
        }
    }

    vector<int> ans(n);
    function<void(int,int)> write=[&](int u,int parent){
        if(p[u]!=-1) ans[u]=p[u];
        else{
            if(lb[u]<=ans[parent]-1 and ans[parent]-1<=ub[u]) ans[u]=ans[parent]-1;
            if(lb[u]<=ans[parent]+1 and ans[parent]+1<=ub[u]) ans[u]=ans[parent]+1;
        }
        for(int v:graph[u]){
            if(v==parent) continue;
            write(v,u);
        }
    };
    rep(i,0,n){
        if(p[i]!=-1){
            write(i,-1);
            break;
        }
    }
