inline void dfs(int x){
//	cerr<<"XXX:    "<<x<<endl;
	int i,tx,ty,t;
	for(i=0;i<v[x].size();++i){
		t=v[x][i];
		tx=low[x]-1;
		ty=up[x]+1;
		if(max(tx,low[t])>min(ty,up[t])){
			puts("NO");
			exit(0);
		}
		if(tx>=low[t] and ty<=up[t]){
			low[t]=tx; 
			up[t]=ty;
			dfs(t);
		}else continue;
	}
}
inline void check(int x,int dist){
	if(use[x]) return;
	if(~odd[x]){
		if((base_col+dist)&1!=odd[x]){
//			cerr<<"AFDSFSDGG:    "<<base_col<<' '<<dist<<' '<<x<<endl;
			puts("NO");
			exit(0);
		}
	}
	use[x]=1;
	for(int i=0;i<v[x].size();++i) check(v[x][i],dist+1);
}
inline void go(int x){
	if(use[x]) return;
	use[x]=1;
	col[x]=low[x];
	for(int i=0;i<v[x].size();++i) go(v[x][i]);
}
