    for(int i = 1; i <= N; i++)
        rng[i].l = 0x80808080, rng[i].r = 0x7F7F7F7F, rng[i].oe = -1;
    for(int i = 1; i <= K; i++)
        cin >> pnt[i].first >> pnt[i].second, rng[pnt[i].first].l = pnt[i].second, rng[pnt[i].first].r = pnt[i].second, rng[pnt[i].first].oe = pnt[i].second & 1;

    DFSPushUp(1, 0);
    DFSPushDown(1, 0);

    if(noSolution)
        puts("No");
    else
    {
        puts("Yes");
        for(int i = 1; i <= N; i++)
            cout << rng[i].l << endl ;
    }

    return 0;
}

