using namespace std;
#define Inf 0x7f7f7f7f
int dist[100005];
int head[100005],arrive[200005],nxt[200005],tot;
void add_edge(int from,int to){
	arrive[++tot]=to;
	nxt[tot]=head[from];
	head[from]=tot;
}
int mx(int a,int b){
	return a>b?a:b;
}
int mn(int a,int b){
	return a<b?a:b;
}
int left[100005],right[100005];
int father[100005];
bool visit[100005];
bool get_ans;
int ab(int a){
	return a<0?-a:a;
}
vector<int> ord;
void dfs(int root){
	if(!get_ans){
		return;
	}
	left[root]=-Inf;
	right[root]=Inf;
	if(visit[root]){
		left[root]=right[root]=dist[root];
	}
	for(int i=head[root];i;i=nxt[i]){
		if(arrive[i]==father[root]){
			continue;
		}
		father[arrive[i]]=root;
		dfs(arrive[i]);
		if(!get_ans){
			return;
		}
		if(left[arrive[i]]>-Inf/2){
			if(left[root]<-Inf/2){
				left[root]=left[arrive[i]]-1;
				right[root]=right[arrive[i]]+1;
			}
			else{
				if((ab(left[arrive[i]])&1)==(ab(left[root])&1)){
					get_ans=0;
					return;
				}
				left[root]=mx(left[root],left[arrive[i]]-1);
				right[root]=mn(right[root],right[arrive[i]]+1);
				if(left[root]>right[root]){
					get_ans=0;
					return;
				}
			}
		}
	}
	ord.push_back(root);
}
void find_val(int root){
	if(visit[root]){
		return;
	}
	if(father[root]==0){
		dist[root]=left[root];
		visit[root]=1;
	}
	else{
		if(dist[father[root]]-1>=left[root]&&dist[father[root]]-1<=right[root]){
			dist[root]=dist[father[root]]-1;
		}
		else{
			dist[root]=dist[father[root]]+1;
		}
		visit[root]=1;
	}
}
int main(){
	int n;
	scanf("%d",&n);
	int u,v;
	for(int i=1;i<n;i++){
		scanf("%d%d",&u,&v);
		add_edge(u,v);
		add_edge(v,u);
	}
	int k;
	scanf("%d",&k);
	for(int i=1;i<=k;i++){
		scanf("%d%d",&u,&v);
		dist[u]=v;
		visit[u]=1;
	}
	get_ans=1;
	dfs(1);
	if(!get_ans){
		puts("No");
	}
	else{
		reverse(ord.begin(),ord.end());
		for(int i=0;i<(int)ord.size();i++){
			find_val(ord[i]);
		}
		puts("Yes");
		for(int i=1;i<=n;i++){
			printf("%d\n",dist[i]);
		}
	}
	return 0;
}

