using namespace std;

using pii = pair<int, int>;

int absolut(const int vodka){
	return max(vodka, -vodka); }

pii intersect(const pii a, const pii b){
	return pii { max(a.first, b.first), min(a.second, b.second) }; }

pii enlarge(const pii a){
	return pii { a.first - 1, a.second + 1 }; }

bool inside(const pii a, const int x){
	return a.first <= x && x <= a.second; }

constexpr pii universal { (int)-1e6 - 10, (int)1e6 + 10 };
constexpr int unknown = -1;

vector<vector<int>> vec;
vector<pii> good_intervals;

bool dfs(const int cur, const int prev){
	for(const auto next : vec[cur]){
		if(next == prev) continue;
		if(!dfs(next, cur)) return false;
		good_intervals[cur] = intersect(good_intervals[cur], enlarge(good_intervals[next])); }
	return good_intervals[cur].first <= good_intervals[cur].second; }

vector<int> rez;

bool build(const int cur, const int prev){
	for(const auto next : vec[cur]){
		if(next == prev) continue;
		if(inside(good_intervals[next], rez[cur]+1)){
			rez[next] = rez[cur] + 1; }
		else if(inside(good_intervals[next], rez[cur]-1)){
			rez[next] = rez[cur] - 1; }
		else return false;
		if(!build(next, cur)) return false; }
	return true; }

int main(){
	int n, k;
	cin >> n;
	vec.resize(n), good_intervals.resize(n, universal), rez.resize(n);
	for(int i = n-1, x, y; i; --i){
		cin >> x >> y;
		vec[--x].push_back(--y);
		vec[y].push_back(x); }

	cin >> k;

	int root = 0;
	for(int i = k, v, p; i; --i){
		cin >> v >> p;
		root = --v;
		rez[v] = p;
		good_intervals[v] = make_pair(p, p); }

	if(!dfs(root, -1) || !build(root, -1)){
		cout << "No\n";
		return 0; }

	cout << "Yes\n";
	for(const auto x : rez){
		cout << x << '\n'; }

	return 0; }

