bool loop(int v, int p) {
	int tminv = -1, tmaxv = inf;
	if(A[v] != -inf) {
		tminv = A[v];
		tmaxv = A[v];
	}
	rep(i, 0, sz(G[v])) {
		int n = G[v][i];
		if(n == p) continue;
		if(!loop(n, v)) return false;
		int pminv = minv[n], pmaxv = maxv[n];
		pminv--; pmaxv++;
		if(tminv == -1) {
			tminv = pminv;
			tmaxv = pmaxv;
		}
		else {
			if(pminv == -1) continue;
			if(abs(tminv - pminv) % 2 == 1) {
				return false;
			}
			else {
				MAX(tminv, pminv);
				MIN(tmaxv, pmaxv);
			}
		}
	}
	if(tminv > tmaxv) {
		return false;
	}
	else {
		minv[v] = tminv;
		maxv[v] = tmaxv;
		return true;
	}
}

void loop2(int v, int p) {
	if(p == -1) {
		ans[v] = minv[v];
	}
	else {
		int tmp = ans[p]; tmp--;
		MAX(tmp, minv[v]);
		ans[v] = tmp;
	}
	rep(i, 0, sz(G[v])) {
		int n = G[v][i];
		if(n == p) continue;
		loop2(n, v);
	}
}

