int val[N],mn[N],mx[N];
void dfs2(int u,int fa){
    if(val[u]==-1)
        mn[u]=-INF,mx[u]=INF;
    else
        mn[u]=mx[u]=val[u];
    for(int i=0,sz=edge[u].size();i<sz;i++){
        int v=edge[u][i];
        if(v==fa)
            continue;
        dfs2(v,u);
        if(mx[v]<mn[u]-1||mn[v]>mx[u]+1)
            nosolution();
        mn[u]=max(mn[u],mn[v]-1);
        mx[u]=min(mx[u],mx[v]+1);
    }
}
int ans[N];
void dfs3(int u,int fa,int t){
    if(t+1<=mx[u])
        ans[u]=t+1;
    else if(t-1>=mn[u])
        ans[u]=t-1;
    for(int i=0,sz=edge[u].size();i<sz;i++){
        int v=edge[u][i];
        if(v==fa)
            continue;
        dfs3(v,u,ans[u]);
    }
}
