void dfs(int v, int p = -1) {
	l[v] = -inf, r[v] = inf;
	for(int to : g[v]) {
		if(to != p) {
			d[to] = d[v] + 1;
			dfs(to, v);
			Max(l[v], l[to] - 1);
			Min(r[v], r[to] + 1);
		}
	}
	if(a[v] != -1) {
		if(!lie(l[v], a[v], r[v]))
			no();
		Max(l[v], a[v]);
		Min(r[v], a[v]);
		if(d[v] % 2 != abs(a[root] - a[v]) % 2)
			no();
	}
	if(l[v] > r[v])
		no();
}

void build(int v, int p = -1) {
	for(int to : g[v]) {
		if(to != p) {
			if(lie(l[to], a[v] - 1, r[to]))
				a[to] = a[v] - 1;
			else if(lie(l[to], a[v] + 1, r[to]))
				a[to] = a[v] + 1;
			else
				no();
			build(to, v);
		}
	}
}

