using namespace std;
const int N = 1e5 + 10;
const int M = 2e5 + 10;
const int maxn = 1e9 + 1e5;
int las[N], nex[M], to[M], sz, val[N], n, K, fa[N], ans[N];
bool visit[N];
struct node {
    int l, r;
    bool all;
    bool empty;
} rem[N], tmp[N];
void add(int x, int y) {
    to[++sz] = y; nex[sz] = las[x]; las[x] = sz;
}
bool dfs(int now) {
    int cnt = 0, flag = 0;
    for (int i = las[now]; i; i = nex[i])
    if(!visit[to[i]]) {
        visit[to[i]] = true;
        if(!dfs(to[i])) {
            rem[now].empty = true;
            return false;
        } 
    }
    else fa[now] = to[i];
    for (int  i = las[now]; i; i = nex[i])
    if(to[i] != fa[now]) {
        tmp[++cnt] = rem[to[i]];
        tmp[cnt].l -= 1;
        tmp[cnt].r += 1;
    }
    if(!rem[now].all) {
        tmp[++cnt] = rem[now];
    }
    flag = (tmp[1].l & 1);
    for (int i = 1; i <= cnt; i++) {
        if(tmp[i].all) continue;
        else if(tmp[i].l & 1 != flag) flag = -1;
    }
    if(flag == -1) return false; 
    int maxl = -maxn, minr = maxn;
    for (int i = 1; i <= cnt; i++) {
        if(tmp[i].l > maxl) maxl = tmp[i].l;
        if(tmp[i].r < minr) minr = tmp[i].r;
    }
    if(maxl > minr) return false;
    rem[now].l = maxl;
    rem[now].r = minr;
    return true;
}
void calc(int now) {
    visit[now] = true;
    int L = max(ans[fa[now]] - 1, rem[now].l);
    int R = min(ans[fa[now]] + 1, rem[now].r);
    ans[now] = L;
    for (int i = las[now]; i; i = nex[i])
    if(!visit[to[i]]) {
        calc(to[i]);
    }
}
int main()
{
    scanf("%d", &n);
    for (int i = 1, x, y; i < n; i++) {
        scanf("%d%d", &x, &y);
        add(x, y);
        add(y, x);
    }
    memset(val, -1, sizeof(val));
    for (int i = 1; i <= n; i++) {
        rem[i].l = -maxn;
        rem[i].r = maxn;
        rem[i].empty = false;
        rem[i].all = true;
    }
    scanf("%d", &K);
    for (int i = 1, x; i <= K; i++) {
        scanf("%d", &x);
        scanf("%d", &val[x]);
        rem[x].l = rem[x].r = val[x];
        rem[x].all = false;
    }
    visit[2] = true;
    if(dfs(2)) {
        memset(ans, 0, sizeof(ans));
        fa[2] = 0;
        ans[0] = rem[2].l - 1;
        memset(visit, 0, sizeof(visit));
        printf("Yes\n");
        calc(2);
        for (int i = 1; i <= n; i++)
            printf("%d\n", ans[i]);
        return 0;
    }
    else printf("No\n");
}

