/*--------main part---------*/

vector<int> edg[100005];
int dat[100005];
int r[100005];
int l[100005];
bool ans=true;
void solve(int x,int p)
{
	r[x]=INF+1;
	l[x]=-INF-1;
	if(dat[x]!=-1)
	{
		l[x]=dat[x];
		r[x]=dat[x];
	}
	for(int i=0;i<edg[x].size();i++)
	{
		int nx=edg[x][i];
		if(nx!=p)
		{
			solve(nx,x);
			if(l[nx]<=-INF/2)
			{
				continue;
			}
			if(l[x]<-INF/2)
			{
				l[x]=l[nx]-1;
				r[x]=r[nx]+1;
			}
			else
			{
				if(abs(l[nx])%2==abs(l[x])%2)
				{
					ans=false;
					return;
				}
				l[x]=max(l[x],l[nx]-1);
				r[x]=min(r[x],r[nx]+1);
			}
		}
	}
	if(l[x]>r[x])
		ans=false;
}
void make(int x,int p)
{
	if(x==1 and dat[x]==-1)
	{
		dat[x]=l[x];
	}
	for(int i=0;i<edg[x].size();i++)
	{
		int nx=edg[x][i];
		if(nx!=p)
		{
			if(dat[nx]==-1)
			{
				if(l[nx]<=dat[x]-1 and dat[x]-1<=r[nx])
				{
					dat[nx]=dat[x]-1;
				}
				else
				{
					dat[nx]=dat[x]+1;
				}
			}
			make(nx,x);
		}
	}
}
