	cin>>m;
	for(int i=0;i<m;i++)
	{
		int x,y;
		cin>>x>>y;
		dat[x]=y;
	}
	solve(1,-1);
	if(!ans)
	{
		cout<<"No"<<endl;
	}
	else
	{
		make(1,-1);
		cout<<"Yes"<<endl;
		for(int i=1;i<=n;i++)
		{
			cout<<dat[i]<<endl;
		}
	}
	return 0;
}

