void dfs(int rt, int pre) {
	for(edge *p=adj[rt];p!=NULL;p=p->nxt) {
		if( p->to == pre ) continue;
		dfs(p->to, rt);
		if( a[p->to].flag ) {
			if( !a[rt].flag ) {
				a[rt].lb = a[p->to].lb - 1;
				a[rt].ub = a[p->to].ub + 1;
			}
			else {
				if( (a[rt].lb & 1) == (a[p->to].lb & 1) ) {
					flag = false;
					break;
				}
				else {
					int lb = a[p->to].lb - 1;
					int ub = a[p->to].ub + 1;
					if( lb > a[rt].ub ) {
						flag = false;
						break;
					}
					else if( a[rt].lb > ub ) {
						flag = false;
						break;
					}
					else {
						a[rt].lb = max(a[rt].lb, lb);
						a[rt].ub = min(a[rt].ub, ub);
					}
				}
			}
			a[rt].flag = true;
		}
		if( !flag ) break;
	}
}
void dfs2(int rt, int pre) {
	if( pre != -1 ) {
		if( a[rt].lb <= a[pre].key + 1 && a[pre].key + 1 <= a[rt].ub )
			a[rt].key = a[pre].key + 1;
		else a[rt].key = a[pre].key - 1;
	}
	else {
		if( !a[rt].flag ) a[rt].key = 0;
		else a[rt].key = a[rt].lb;
	}
	for(edge *p=adj[rt];p!=NULL;p=p->nxt)
		if( p->to != pre ) 
			dfs2(p->to, rt);
}
