void link(int x, int y) {
	e[++tot] = (edge) { y, head[x] }, head[x] = tot;
	e[++tot] = (edge) { x, head[y] }, head[y] = tot;
}

int p[N], rec, l[N], r[N];
void dfs0(int x, int f = 0, bool dep = 0) {
	if (p[x] != -1) {
		l[x] = r[x] = p[x];
		if ((rec |= 1 << ((dep ^ p[x]) & 1)) == 3)
			std::cout << "No\n", std::exit(0);
	} else l[x] = -100000, r[x] = 100000;
	if (f) l[x] = std::max(l[x], l[f] - 1), r[x] = std::min(r[x], r[f] + 1);
	for (int i = head[x]; i; i = e[i].nxt)
		if (e[i].to != f) {
			dfs0(e[i].to, x, dep ^ 1);
			l[x] = std::max(l[x], l[e[i].to] - 1);
			r[x] = std::min(r[x], r[e[i].to] + 1);
		}
	if (l[x] > r[x]) std::cout << "No\n", std::exit(0);
}
void dfs1(int x, int f = 0) {
	if (p[x] == -1) {
		if (p[f] - 1 >= l[x])
			p[x] = p[f] - 1;
		else
			p[x] = p[f] + 1;
	}
	for (int i = head[x]; i; i = e[i].nxt)
		if (e[i].to != f) dfs1(e[i].to, x);
}

