void AddEdge(int u, int v) {
	next[++ed] = head[u]; head[u] = ed; to[ed] = v;
}

pii dp[100005];

pii DP(int now, int fa, bool odd, int L, int R) {
	if (vis[now]) {
		if (ans[now] < L || ans[now] > R || (ans[now] & 1) != odd) {
			puts("No"); exit(0);
		}
		L = R = ans[now];
	}
	pii tmp;
	for (int i = head[now]; i; i = next[i]) {
		if (to[i] == fa) continue;
		tmp = DP(to[i], now, odd ^ 1, L - 1, R + 1);
		L = std::max(L, tmp.first - 1);
		R = std::min(R, tmp.second + 1);
		if (L > R) {
			puts("No"); exit(0);
		}
	}
	return dp[now] = mp(L, R);
}

void DFS(int now, int fa, int L, int R) {
	dp[now].first = std::max(dp[now].first, L);
	dp[now].second = std::min(dp[now].second, R);
	ans[now] = dp[now].first;
	for (int i = head[now]; i; i = next[i]) {
		if (to[i] == fa) continue;
		DFS(to[i], now, dp[now].first - 1, dp[now].second + 1);
	}
}

