inline std::pair<int, int> merge(std::pair<int, int> a, std::pair<int, int> b) {
    return std::make_pair(std::max(a.first, b.first), std::min(a.second, b.second));
}

void build(int cur) {
    for (int i : to[cur])
        if (i != f[cur]) {
            c[cur].push_back(i);
            f[i] = cur;
            d[i] = !d[cur];
            build(i);
        }
}

void dfs(int cur) {
    if (cur != rt)
        r[cur] = merge(r[cur], std::make_pair(r[f[cur]].first - 1, r[f[cur]].second + 1));
    for (int i : c[cur]) {
        dfs(i);
        r[cur] = merge(r[cur], std::make_pair(r[i].first - 1, r[i].second + 1));
    }
}

void query(int cur) {
    p[cur] = r[cur].first;
    if (cur != rt && p[cur] == p[f[cur]])
        p[cur]++;
    for (int i : c[cur]) {
        r[i] = merge(r[i], std::make_pair(p[cur] - 1, p[cur] + 1));
        query(i);
    }
}

