  if(L[a] == -IINF){
    L[a] = l;
    R[a] = r;
  }
  if((L[a]^l)&1 || L[a]>r || l>R[a]){
    cout << "No" << endl;
    exit(0);
  }
  maxs(L[a], l); l = L[a];
  mins(R[a], r); r = R[a];
  for(int b:e[a]) if(b != p){
    dfs(b, a);
    l = L[b]-1;
    r = R[b]+1;
    if((L[a]^l)&1 || L[a]>r || l>R[a]){
      cout << "No" << endl;
      exit(0);
    }
    maxs(L[a], l); l = L[a];
    mins(R[a], r); r = R[a];
  }
}
main(){
  cin.tie(0);
  ios::sync_with_stdio(false);
  cin >> n;
  FOR(i, 0, n-1){
    int a, b;
