int main(){
  cin.tie(0);
  ios::sync_with_stdio(false);
  ll N;
  cin>>N;
  vector<vector<ll>> edge(N);
  for(int i=1;i<N;i++){
    ll a,b;
    cin>>a>>b;
    a--; b--;
    edge[a].push_back(b);
    edge[b].push_back(a);
  }
  ll K;
  cin>>K;
  vector<pll> A(K);
  cin>>A;
  priority_queue<pll,vector<pll>,greater<pll>> Q;
  vector<ll> dp(N,MOD);
  auto dpdo=
    [&](ll u,ll p){
      if(dp[u]>p){dp[u]=p; Q.push({p,u});}
    };
  for(auto &I:A){
    I.F--;
    dpdo(I.F,I.S);
  }
  while(!Q.empty()){
    pll tp=Q.top(); Q.pop();
    if(dp[tp.S]!=tp.F){continue;}
    ll u=tp.S;
    for(auto &I:edge[u]){
      dpdo(I,dp[u]+1);
    }
  }
  for(int i=0;i<N;i++){
    for(auto &I:edge[i]){
      if(abs(dp[i]-dp[I])!=1){cout<<"No"<<endl; return 0;}
