typedef long long ull;

ull n;
ull k;
vector<vector<ull> >tree;
vector<ull>vec;
vector<bool>visited;
vector<ull>trace;

bool dfs(ull node,ull lastV,ull co){
 //   cout<<"node: "<<node+1<<endl;
    if(visited[node]){
        return true;
    }
    if(vec[node]!=666666666666&&abs(vec[node]-vec[lastV])>co){
        return false;
    }
    if(vec[node]!=666666666666){
        ull cur=vec[lastV];
        for(int i=0;i<trace.size();i++){
            if(cur<vec[node]){
                cur++;
            } else {
                cur--;
            }
            vec[trace[i]]=cur;
        }
        trace.clear();
    } else {
        trace.push_back(node);
    }
    bool ok=true;
    int lastTraceSize = trace.size();
    for(int i=0;i<tree[node].size();i++){
        if(vec[node]!=666666666666){
            visited[tree[node][i]]=true;
            ok=ok&&dfs(tree[node][i],node,1);
            visited[tree[node][i]]=false;
        }
        else{
            visited[tree[node][i]]=true;
            ok=ok&&dfs(tree[node][i],lastV,co+1);
            visited[tree[node][i]]=false;
        }
        while(trace.size()>lastTraceSize){
            trace.pop_back();
        }
    }

    return ok;
}
void df(ull node){
    for(int i=0;i<tree[node].size();i++){
        if(vec[tree[node][i]]==666666666666){
            vec[tree[node][i]] = vec[node]+1;
            df(tree[node][i]);
        }
    }
}
