        vec[v]=p;
        fir=v;
    }
    bool ok=true;
    visited[fir]=true;
    for(int i=0;i<tree[fir].size();i++){
        ok=ok&&dfs(tree[fir][i],fir,1);
    }
    if(ok){
        cout<<"Yes"<<endl;
        for(int i=0;i<n;i++){
            if(vec[i]!=666666666666){
                df(i);
            }
        }
        for(int i=0;i<n;i++){
            cout<<vec[i]<<endl;
        }
    } else {
        cout<<"No"<<endl;
