[[noreturn]] void impossible() {
    PRINTLN("No");
    EXIT();
}

constexpr Int PARITY(Int x) {
    return x%2==0 ? 0 : 1;
}

auto udgraph_list(Int n, const vector<pair<Int,Int>>& es) {
    vector<vector<Int>> g(n);
    for(const auto& e : es) {
        Int a,b; tie(a,b) = e;
        g[a].emplace_back(b);
        g[b].emplace_back(a);
    }
    return g;
}

pair<Int,Int> interval_merge(const pair<Int,Int>& a, const pair<Int,Int>& b) {
    Int al,ar; tie(al,ar) = a;
    Int bl,br; tie(bl,br) = b;
    return {MAX(al,bl), MIN(ar,br)};
}

bool interval_contains(const pair<Int,Int>& z, Int x) {
    Int l,r; tie(l,r) = z;
    return l <= x && x < r;
}

bool interval_is_empty(const pair<Int,Int>& z) {
    Int l,r; tie(l,r) = z;
    return l > r;
}

void solve() {
    Int N = RD();
    auto E = RD_VEC<pair<Int1,Int1>>(N-1);
    auto G = udgraph_list(N, E);

    Int root = -1;
    vector<Int> P(N, INF);
    Int K = RD();
    LOOP(K) {
        Int v = RD1();
        Int p = RD();
        P[v] = p;
        root = v;
    }

    vector<Int> paritys(N, -1);
    vector<pair<Int,Int>> intervals(N);
    auto dfs = FIX([&](auto&& self, Int v, Int p, Int d) -> void {
        paritys[v] = PARITY(P[root]+d);
        intervals[v] = P[v]==INF ? make_pair(-INF,INF) : make_pair(P[v],P[v]+1);
        for(Int to : G[v]) {
            if(to == p) continue;
            self(to, v, d+1);
            pair<Int,Int> z = intervals[to];
            --z.first;
            ++z.second;
            intervals[v] = interval_merge(intervals[v], z);
        }
    });
    dfs(root, -1, 0);
    DBG(paritys);
    DBG(intervals);

    if(interval_is_empty(intervals[root])) impossible();

    auto dfs2 = FIX([&](auto&& self, Int v, Int p) -> void {
        if(P[v] == INF) {
            if(interval_contains(intervals[v], P[p]-1))
                P[v] = P[p]-1;
            else if(interval_contains(intervals[v], P[p]+1))
                P[v] = P[p]+1;
            ASSERT(P[v] != INF);
        }
        if(PARITY(P[v]) != paritys[v]) impossible();

        for(Int to : G[v]) {
            if(to == p) continue;
            self(to, v);
        }
    });
    dfs2(root, -1);

    PRINTLN("Yes");
    ALL(for_each, P, LIFT(PRINTLN));
}

signed main() {
    Int T = 1; //RD();
    LOOP(T) {
        solve();
    }

    EXIT();
}

