      }
      maxi(lb[v], lb[u] - 1);
      mini(ub[v], ub[u] + 1);
    }
  }
  if (lb[v] > ub[v]) return false;
  return true;
}

void dfs2(int v, int p) {
  if (a[v] < 0) {
    if (p < 0) a[v] = lb[v];
    else if (a[p] - 1 >= lb[v] && a[p] - 1 <= ub[v]) {
      a[v] = a[p] - 1;
    } else {
      a[v] = a[p] + 1;
      assert(a[p] + 1 >= lb[v] && a[p] + 1 <= ub[v]);
    }
  } else {
    if (p >= 0) {
      assert(a[v] == a[p] + 1 || a[v] == a[p] - 1);
    }
  }

  for (int u: adj[v]) {
    if (u != p) {
      dfs2(u, v);
    }
  }
}

