const int inf = 0x3f3f3f3f;

vector <int> g[N];
int n, k, dist[N];
priority_queue <pair <int, int>, vector <pair <int, int> >, greater <pair <int, int> > > pq;

void input(){
    scanf("%d", &n);
    for (int i = 1; i <= n - 1; i++) {
        int u, v;
        scanf("%d %d", &u, &v);
        g[u].push_back(v);
        g[v].push_back(u);
    }

    scanf("%d", &k);
    memset(dist, 0x3f, sizeof(dist));
    for (int i = 1; i <= k; i++) {
        int u, x;
        scanf("%d %d", &u, &x);
        dist[u] = x;
        pq.push(make_pair(dist[u], u));
    }
}

void dijkstra(){
    while (!pq.empty()) {
        int d = pq.top().first;
        int u = pq.top().second;
        pq.pop();

        for (int v: g[u]) {
            if (dist[v] == inf) {
                dist[v] = dist[u] + 1;
                pq.push(make_pair(dist[v], v));
            }
            else if (abs(dist[v] - dist[u]) != 1) {
                printf("No");
                return;
            }
        }
    }

    puts("Yes");
    for (int i = 1; i <= n; i++) printf("%d\n", dist[i]);
}

void solve(){
    dijkstra();
}

signed main(){
    input();
    solve();
    return 0;
}

