int n;
vector<vector<int> > graph(100001);
vector<int> node(100001, -1);
vector<int> parent(100001, -1);
vector<pair<int, int> > range(100001);

bool cansolve(int x)
{
    int l = -1000000, r = 2000000;
    for(int i = 0; i < graph[x].size(); i++){
        int nextnode = graph[x][i];
        if(parent[nextnode] != -1) continue;
        parent[nextnode] = x;
        bool tmp = cansolve(nextnode);
        if(!tmp) return false;
        l = max(l, range[nextnode].first - 1);
        r = min(r, range[nextnode].second + 1);
        if((r - l) % 2 == 1) return false;
    }
    if(node[x] != -1){
        l = max(l, node[x]);
        r = min(r, node[x]);
    }
    if(r - l < 0 || (r - l) % 2 == 1) return false;
    // cout << x << " " << l << " " << r << endl;
    range[x] = make_pair(l, r);
    return true;
}

bool definenode(int x)
{
    // cout << x << endl;
    int tmp = node[x];
    for(int i = 0; i < graph[x].size(); i++){
        int nextnode = graph[x][i];
        // cout << nextnode << " " << parent[nextnode] << endl;
        int l = range[nextnode].first, r = range[nextnode].second;
        if(parent[nextnode] != x) continue;
        if(l <= tmp - 1 && tmp - 1 <= r){
            node[nextnode] = tmp - 1;
            if(definenode(nextnode)){
                continue;
            } else if(l <= tmp + 1 && tmp + 1 <= r) {
                node[nextnode] = tmp + 1;
                if(definenode(nextnode)) continue;
                else return false;
            }
        } else if(l <= tmp + 1 && tmp + 1 <= r){
            node[nextnode] = tmp + 1;
            if(definenode(nextnode)) continue;
            else return false;
        } else return false;
    }
    return true;
}

int main()
{   
    cin >> n;    
    for(int i = 0; i < n - 1; i++){
        int a, b;
        cin >> a >> b;
        graph[a].push_back(b);
        graph[b].push_back(a);
    }
    int k;
    cin >> k;
    int v, p;
    for(int i = 0; i < k; i++){
        cin >> v >> p;
        node[v] = p;
    }
    parent[v] = 0;
    bool result = cansolve(v), ans = definenode(v);
    if(result && ans){
        cout << "Yes" << endl;
        for(int i = 1; i <= n; i++){
            cout << node[i] << endl;
        }
    } else {
        cout << "No" << endl;
    }
    return 0;
}

