typedef long long ll;
typedef pair<int,int> pii;
#define rep(i,n) for(ll i=0;i<(ll)(n);i++)
#define all(a)  (a).begin(),(a).end()
#define pb push_back
#define INF (1e9+1)
//#define INF (1LL<<59)

#define MAX_V 100000
vector<int> G[MAX_V];


pii mergeSegment(pii a,pii b){	//returns pii(1,-1) when two segments don't crossed.
	if(a.first<=-INF) return b;
	if(b.first<=-INF) return a;
	if(abs(a.first)%2!=abs(b.first)%2) return pii(1,-1);

	if(a.second<b.first || b.second<a.first)	return pii(1,-1);
	if(a.first<=b.first && b.second<=a.second)	return b;
	if(b.first<=a.first && a.second<=b.second)	return a;
	if(a.first<b.first && a.second<b.second)	return pii(b.first,a.second);
	if(b.first<a.first && b.second<a.second)	return pii(a.first,b.second);

	assert(0);
	return pii(1,-1);
}

vector<pii> dp;

pii dfs(int cur,vector<bool> &used){
	pii res = dp[cur];
	for(auto &e:G[cur]){
		if(used[e])continue;
		used[e]=true;
		pii p = dfs(e,used);
		p.first--,p.second++;
		res = mergeSegment(res,p);
	}
	return (dp[cur] = res);
}


int main(){
	int v;
	cin>>v;
	rep(i,v-1){
		int a,b;
		cin>>a>>b;
		a--,b--;
		G[a].pb(b);
		G[b].pb(a);
	}
	int k;
	cin>>k;


	int root=-1;
	dp.resize(v,pii(-INF,INF));
	rep(i,k){
		int a,b;
		cin>>a>>b;
		a--;
		dp[a] = pii(b,b);
		root = a;
	}

	vector<bool> used(v,false);
	used[root] = true;


	dfs(root,used);

	rep(i,v)if(dp[i]==pii(1,-1)){cout<<"No"<<endl;return 0;}

	cout<<"Yes"<<endl;

	queue<int> que;
	que.push(root);

	vector<int> ans(v,-INF);
	ans[root] = dp[root].first;

	while(que.size()){
		int q = que.front();
		que.pop();

		int p=ans[q];
		for(auto &e:G[q]){
			if(ans[e]!=-INF)continue;

			if(dp[e].first<=p-1&&p-1<=dp[e].second)ans[e] = p-1;
			else ans[e] = p+1;
			que.push(e);
		}
	}
	rep(i,v)cout<<ans[i]<<endl;
}

#include <bits/stdc++.h>

using namespace std;

typedef pair<long long, long long> range;

bool ok = true;
#define l first
#define r second

int n, k;	
vector<int> g[100005];
range a[100005];
bool vis[100005];
int h[100005];

bool mergerange(range &a, range &b) {
	if (a.l > b.r+1 || a.r < b.l-1) return false;
	if (b.l > a.r+1 || b.r < a.l-1) return false;
	range na, nb;
	na = {max(a.l, b.l-1), min(a.r, b.r+1)};
	nb = {max(b.l, a.l-1), min(b.r, a.r+1)};
	a = na;
	if ((a.r - a.l)%2 != 0) {
		ok = false;
	}
	b = nb;
	if ((b.r - b.l)%2 != 0) {
		ok = false;
	}
	return true;
}

void dfs(int u) {
	vis[u] = 1;
	for (auto v : g[u]) {
		if (!vis[v]) {
			if (h[v] != -100001 && h[u] != -100001) {
				if (abs(h[v]-h[u]) != 1) ok = false;
			}
			dfs(v);
			if (a[v].l != -100001) ok &= mergerange(a[v], a[u]);
		}
	}
}

void getres(int u) {
	vis[u] = 1;
	for (auto v : g[u]) {
		if (!vis[v]) {
			if (h[u]-1 >= a[v].l && h[u]-1 <= a[v].r) {
				h[v] = h[u]-1;
			}
			else {
				h[v] = h[u]+1;
			}
			getres(v);
		}
	}
}

signed main() {
	scanf("%d", &n);
	int x, y;
	for (int i = 1; i < n; i++) {
		scanf("%d%d", &x, &y);
		g[x].push_back(y);
		g[y].push_back(x);
	}	
	for (int i = 1; i <= n; i++) {
		a[i] = {-INT_MAX, INT_MAX};
	}
	memset(vis, 0, sizeof(vis));
	scanf("%d", &k);
	for (int i = 1; i <= n; i++) {
		h[i] = -100001;
	}
	for (int i = 1; i <= k; i++) {
		scanf("%d%d", &x, &y);
		a[x] = {y, y};
		h[x] = y;
	}
	for (int i = 1; i <= k; i++) {
		if (h[i] != -100001) {
			dfs(i);
			break;
		}
	}
	if (!ok) {
		cout << "No";
		return 0;
	}
	else {
		cout << "Yes\n";
		memset(vis, 0, sizeof(vis));
		for (int i = 1; i <= n; i++) {
			if (h[i] != -100001) {
				getres(i);
				break;
			}
		}
		for (int i = 1; i<= n; i++) {
			cout << h[i] << "\n";
		}
	}
}

