using namespace std;
const int N=100005,INF=1000000000;
bool jdg;
int n,m,x,c[N],h[N],L[N],R[N],siz[N],cnt;
struct edge{int v,n;} e[N<<1];

int getint()
{
	char ch;
	while(!isdigit(ch=getchar()));
	int x=ch-48;
	while(isdigit(ch=getchar())) x=x*10+ch-48;
	return x;
}

void addedge(int u,int v)
{
	e[cnt]=(edge){v,h[u]},h[u]=cnt++;
	e[cnt]=(edge){u,h[v]},h[v]=cnt++;
}

void get_siz(int x,int fa)
{
	siz[x]=c[x]>-1;
	for(int i=h[x]; i!=-1; i=e[i].n)
		if(e[i].v!=fa)
			get_siz(e[i].v,x),siz[x]+=siz[e[i].v];
}

void dfs2(int x,int fa)
{
	for(int i=h[x]; i!=-1; i=e[i].n)
		if(e[i].v!=fa) c[e[i].v]=c[x]+1,dfs2(e[i].v,x);
}

void dfs1(int x,int fa)
{
	if(siz[x]==0) {L[x]=-INF,R[x]=INF; return;}
	if(siz[x]==1 && c[x]>-1) {L[x]=R[x]=c[x],dfs2(x,fa); return;}
	for(int i=h[x]; i!=-1; i=e[i].n)
		if(e[i].v!=fa)
		{
			dfs1(e[i].v,x);
			if(!siz[e[i].v]) continue;
			if(L[x]==-INF) L[x]=L[e[i].v]-1;
			else if((L[x]&1)^(L[e[i].v]&1)) L[x]=max(L[x],L[e[i].v]-1);
			else jdg=1;
			if(R[x]==-INF) R[x]=R[e[i].v]+1;
			else if((R[x]&1)^(R[e[i].v]&1)) R[x]=min(R[x],R[e[i].v]-1);
			else jdg=1;
			if(L[x]>R[x]) jdg=1;
		}
	if(c[x]>-1)
	{
		if(c[x]>R[x] || c[x]<L[x] || (c[x]&1)^(L[x]^1)) jdg=1;
		L[x]=R[x]=c[x];
	}
}

void dfs3(int x,int fa)
{
	if(siz[x]==1 && c[x]>-1) return;
	if(c[x]==-1)
	{
		if(!fa) c[x]=L[x];
		else if(L[x]<=c[fa]+1 && c[fa]+1<=R[x]) c[x]=c[fa]+1;
		else c[x]=c[fa]-1;
	}
	for(int i=h[x]; i!=-1; i=e[i].n)
		if(e[i].v!=fa)
			dfs3(e[i].v,x);
}

int main()
{
	n=getint();
	memset(h,-1,sizeof(h));
	memset(c,-1,sizeof(c));
	rep(i,1,n) L[i]=R[i]=-INF;
	rep(i,1,n-1) addedge(getint(),getint());
	m=getint();
	rep(i,1,m) x=getint(),c[x]=getint();
	get_siz(1,0),dfs1(1,0),dfs3(1,0);
	if(jdg) puts("No");
	else
	{
		puts("Yes");
		rep(i,1,n) printf("%d\n",c[i]);
	}
	return 0;
}

#include <cstdio>
