#define N 200010
using namespace std;

int n, k;
const int INF[2] = {2000000, 2000001};
vector<int> edge[N];

bool vis[N];
int val[N];

void simpleDfs(int u, int fa) {
	val[u] = val[fa] + 1;
	for (int i = 0; i < edge[u].size(); ++i) {
		int v = edge[u][i];
		if (v != fa) {
			simpleDfs(v, u);
		}
	}
}

int up[N], down[N];
bool dfs(int u, int fa, bool odd) {
	up[u] = INF[odd]; down[u] = -INF[odd];
	for (int i = 0; i < edge[u].size(); ++i) {
		int v = edge[u][i];
		if (v != fa) {
			if (!dfs(v, u, odd ^ 1)) return false;
			up[u] = min(up[v] + 1, up[u]);
			down[u] = max(down[v] - 1, down[u]);
		}
	}

	if (down[u] > up[u]) return false;
	if (vis[u]) {
		if (down[u] > val[u] || up[u] < val[u]) return false;
		down[u] = up[u] = val[u];
	}
	if ((down[u] & 1) != odd || (up[u] & 1) != odd) return false;
	return true;
}

void getAns(int u, int fa) {
	for (int i = 0; i < edge[u].size(); ++i) {
		int v = edge[u][i];
		if (v != fa) {
			if (val[u] + 1 <= up[u] && val[u] + 1 >= down[u]) val[v] = val[u] + 1;
			else val[v] = val[u] - 1;
			getAns(v, u);
		}
	}
}

int a[N], b[N];
int main() {
	scanf("%d", &n);
	for (int i = 1; i < n; ++i) {
		int u, v;
		scanf("%d%d", &u, &v);
		edge[u].push_back(v);
		edge[v].push_back(u);
	}

	scanf("%d", &k);
	for (int i = 1; i <= k; ++i) {
		scanf("%d%d", &a[i], &b[i]);
		val[a[i]] = b[i];
		vis[a[i]] = 1;
	}
	if (!k) {
		simpleDfs(1, 0);
		puts("Yes");
		for (int i = 1; i <= n; ++i) printf("%d\n", val[i]);
	}
	else {
		if (!dfs(a[1], 0, (b[1] & 1))) {
			puts("No");
		}
		else {
			puts("Yes");
			val[a[1]] = down[a[1]];
			getAns(a[1], 0);
			for (int i = 1; i <= n; ++i) printf("%d\n", val[i]);
		}
	}
}

#include <bits/stdc++.h>

using namespace std;

vector<int> adj[100010];
int arr[100010];
int meml[100010];
int memr[100010];
const int INF = 1000000;

bool f(int x, int p, int l, int r, int d)
{
    if(arr[x] != -1)
    {
        if(arr[x] % 2 != d % 2 || arr[x] < l || arr[x] > r)
            return 0;
        l = r = arr[x];
    }

    for(int y : adj[x])
    {
        if(y == p)
            continue;

        if(!f(y, x, l - 1, r + 1, d + 1))
            return 0;

        l = max(l, meml[y] - 1);
        r = min(r, memr[y] + 1);
        if(r < l)
            return 0;
    }

    meml[x] = l;
    memr[x] = r;

    for(int y : adj[x])
    {
        if(y == p)
            continue;

        if(!f(y, x, l - 1, r + 1, d + 1))
            return 0;
    }

    return 1;
}

void g(int x, int p, int l, int r)
{
    l = max(l, meml[x]);
    r = min(r, memr[x]);
    if(arr[x] == -1)
    {
        arr[x] = l;
        r = l;
    }

    for(int y : adj[x])
    {
        if(y == p)
            continue;

        g(y, x, l - 1, r + 1);
    }
}

int main()
{
    int n, k, i;
    scanf("%d", &n);
    for(i = 0; i < n - 1; i++)
    {
        int x, y;
        scanf("%d%d", &x, &y);
        adj[x].push_back(y);
        adj[y].push_back(x);
    }

    memset(arr, -1, sizeof arr);
    scanf("%d", &k);
    int s;
    for(i = 0; i < k; i++)
    {
        int x, p;
        scanf("%d%d", &x, &p);
        arr[x] = p;
        s = x;
    }

    bool ok = f(s, s, -INF, INF, arr[s] % 2);
    if(!ok)
    {
        puts("No");
        return 0;
    }

    puts("Yes");
    g(s, s, -INF, INF);

    for(i = 1; i <= n; i++)
        printf("%d\n", arr[i]);

    return 0;
}

