{
	scanf("%d",&N);
	for(int i=0;i<N;i++){
		ans[i]=-1;
		P[i].resize(100);
	}
	for(int i=0;i<N-1;i++){
		int A,B;
		scanf("%d%d",&A,&B);A--;B--;
		G[A].pb(B);
		G[B].pb(A);
	}
	scanf("%d",&K);
	for(int i=0;i<K;i++){
		int v,p;
		scanf("%d%d",&v,&p);v--;
		P[p].pb(v);ans[v]=p;
	}
	for(int i=0;i<1111111;i++){
		for(int j=0;j<(int)P[i].size();j++){
			//P[i][j]
			int now=P[i][j];
