			if(ans[now]==-1){
				ans[now]=i;
			}
			for(int k=0;k<(int)G[now].size();k++){
				//printf("%d ",G[now][k]);
				if(ans[G[now][k]]==-1){
					P[i+1].pb(G[now][k]);
				}
				else if(abs(ans[G[now][k]]-i)!=1){
