using namespace std;
typedef pair<int,int> D;
int P[100005];
vector<int> G[100005];
int arrived[100005];
D dd[100005];
D dfs( int v, int st, int n, int th )
{
  arrived[v]++;
  if( th > 1 ){
    int nst = dd[v].first;
    int nn = dd[v].second;
    if( st < nst ){
      n -= (nst-st)/2;
      st = nst;
    } else if( st > nst ){
      nn -= (st-nst) / 2;
    }
    if( n > nn ) n = nn;
  }
  if( P[v] >= 0 ){
    if( P[v] < st ) return D(0,0);
    if( P[v] > st + (n-1) * 2 ) return D(0,0);
    if( ( P[v] - st ) % 2 != 0 ) return D(0,0);
    st = P[v];
    n = 1;
  }
  for( int i=0; i<G[v].size(); i++ ){
    int vv = G[v][i];
    if( arrived[vv] < th ){
      D d = dfs( G[v][i], st-1, n+1, th );
      if( d.second == 0 ) return D(0,0);
      int nst = d.first - 1;
      int nn = d.second + 1;
      if( st < nst ){
        n -= (nst-st)/2;
        st = nst;
      } else if( st > nst ){
        nn -= (st-nst) / 2;
      }
      if( n > nn ) n = nn;
    }
  }
  dd[v] = D(st, n);
  return dd[v];
}
