  for( int i=0; i<=N; i++ ) P[i] = -1;
  cin >> K;
  int vv;
  for( int i=0; i<K; i++ ){
    int v, p;
    cin >> v >> p;
    P[v] = p;
    if( i == 0 ) vv = v;
  }
  D d = dfs( vv, P[vv], 1, 1 );
  if( d.second == 0 ){
    cout << "No" << endl;
    return 0;
  }
  dfs( vv, P[vv], 1, 2 );
  cout << "Yes" << endl;
  for( int i=1; i<=N; i++ ){
    cout << dd[i].first << endl;
  }
}

