void dfs(int now, int par, int level, int mini, int maks){
	if(nilai[now] != -1){
		if((level + nilai[now]) % 2 > 0){
			cout << "No\n";
			exit(0);
		}
		if(nilai[now] < mini || nilai[now] > maks){
			cout << "No\n";
			exit(0);
		}
		mini = maks = nilai[now];
	}
	kecil[now] = max(kecil[now], mini);
	besar[now] = min(besar[now], maks);
	P[now] = par;
	lev[now] = level;
	for(int i : g[now]){
		if(i != par)
			dfs(i, now, level + 1, mini - 1, maks + 1);
	}
	for(int i : g[now]){
		if(i != par){
			int a = kecil[i] - 1;
			int b = besar[i] + 1;
			besar[now] = min(besar[now], b);
			kecil[now] = max(kecil[now], a);
		}
	}
}

