int main() {
	cin >> N;
	for (int i = 0; i < N - 1; i++) {
		cin >> s >> e;
		connect[s].push_back(e);
		connect[e].push_back(s);
	}
	for (int i = 1; i <= N; i++) {
		num[i] = -1;
		bottom[i] = -1;
		top[i] = -1;
	}
	cin >> K;
	for (int i = 0; i < K; i++) {
		cin >> a;
		cin >> num[a];
		bottom[a] = num[a];
		top[a] = num[a];
	}
	for (int i = 1; i <= N; i++) {
		if (num[i] != -1) {
			for (int j = 1; j <= N; j++) {
				dis[j] = INT_MAX;
			}
			dis[i] = 0;
			Q.push(i);
			while (!Q.empty()) {
				for (auto j = connect[Q.front()].begin(); j != connect[Q.front()].end(); ++j) {
					if (num[(*j)]==-1) {
						if ((dis[Q.front()] + 1) < dis[(*j)]) {
							dis[(*j)] = dis[Q.front()] + 1;
							if (bottom[(*j)] == -1) {
								bottom[(*j)] = bottom[i] - dis[(*j)];
								if (bottom[(*j) < 0]) {
									bottom[(*j)] *= -1;
									bottom[(*j)] = bottom[(*j)] % 2;
								}
								top[(*j)] = top[i] + dis[(*j)];
							}
							else {
								bottom[(*j)] = max(bottom[i] - dis[(*j)], bottom[(*j)]);
								if (bottom[(*j) < 0]) {
									bottom[(*j)] *= -1;
									bottom[(*j)] = bottom[(*j)] % 2;
								}
								top[(*j)] = min(top[i] + dis[(*j)], top[(*j)]);
								if (top[(*j)] < bottom[(*j)]) {
									cout << "No\n";
									return 0;
								}
								if (top[(*j)] - bottom[(*j)] % 2 == 0) {
									cout << "No\n";
									return 0;
								}
							}
							Q.push((*j));
						}
					}
					else {
						if (abs(num[i] - num[(*j)]) > dis[(*j)]) {
							cout << "No\n";
							return 0;
						}
					}
				}
				Q.pop();
			}

		}
	}
	cout << "Yes\n";
	for (int i = 1; i <= N; i++) {
		cout << bottom[i] << "\n";
	}
	return 0;
}

