int ehead[maxn],ecnt;
struct edge {
	int u,v,next;
}edg[maxn*2];
void add(int u,int v) {
	edg[++ecnt]=(edge){u,v,ehead[u]};
	ehead[u]=ecnt;
	edg[++ecnt]=(edge){v,u,ehead[v]};
	ehead[v]=ecnt;
}
int a[maxn],mi[maxn],mx[maxn],n,m,rt,tag=true;
void dfs(int u,int fa,int oe)
{
	if (a[u]!=-1&&((a[u]^oe)&1)) tag=false;
	for (int v,j=ehead[u];j;j=edg[j].next)
		if ((v=edg[j].v)!=fa) dfs(v,u,oe^1);
}
void dp(int u,int fa)
{
	mi[u]=0;mx[u]=inf;
	for (int v,j=ehead[u];j;j=edg[j].next)
	if ((v=edg[j].v)!=fa) {
		dp(v,u);
		mi[u]=max(mi[u],mi[v]-1);
		mx[u]=min(mx[u],mx[v]+1);
	}
	if (a[u]!=-1) mi[u]=max(mi[u],a[u]),mx[u]=min(mx[u],a[u]);
}
void mk(int u,int fa,int val)
{
	val=max(mi[u],val);a[u]=val;
	for (int v,j=ehead[u];j;j=edg[j].next)
		if ((v=edg[j].v)!=fa) mk(v,u,val-1);
}
