const int INF = 1e9;

int n, minv[100005], maxv[100005], color[100005];
vector<int> G[100005];

void dfs1(int x, int px, int dep){

  color[x] = dep % 2;

  for(int nx : G[x]){

    if( nx == px ) continue;

    dfs1( nx, x, dep + 1 );

    if( minv[x] == maxv[x] ) continue;

    minv[x] = max( minv[x], minv[nx] - 1 );

    maxv[x] = min( maxv[x], maxv[nx] + 1 );

  }

}

void dfs2(int x, int px){

  for(int nx : G[x]){

    if( nx == px && minv[x] != maxv[px] ){

      minv[x] = max( minv[x], minv[px] - 1 );

      maxv[x] = min( maxv[x], maxv[px] + 1 );

    }

    if( nx == px ) continue;

    dfs2( nx, x );

  }

}

int ans[100005];

int flag = 1;

void dfs3(int x, int px){

  if( minv[x] == maxv[x] ){

    if( color[x] != minv[x] % 2 ) flag = 0;
    else ans[x] = minv[x];

    if( px != -1 ){

      if( minv[x] + 1 != ans[px] && minv[x] - 1 != ans[px] ) flag = 0;

    }

  }

  if( minv[x] != maxv[x] ){

    if( ans[px] % 2 == color[x] ) flag = 0;

    if( minv[x] <= ans[px] + 1 && ans[px] + 1 <= maxv[x] ) ans[x] = ans[px] + 1;

    if( minv[x] <= ans[px] - 1 && ans[px] - 1 <= maxv[x] ) ans[x] = ans[px] -1;

  }

  for(int nx : G[x]){
    if( nx != px )  dfs3( nx, x );
  }

}

