#define gc getchar

bool chkmin(int &x, int y) { return x > y ? x = y, 1 : 0; }
bool chkmax(int &x, int y) { return x < y ? x = y, 1 : 0; }

int rd() {
	int ret = 0; bool fl = 0; char ch = 0;
	while (!isdigit(ch)) fl |= (ch == '-'), ch = gc();
	while (isdigit(ch)) ret = (ret << 1) + (ret << 3) + (ch ^ 48), ch = gc();
	return fl ? -ret : ret;
}
#define go(i, v, x) for (int i = head[x], v = e[i].to; i; i = e[i].nxt, v = e[i].to)
struct edge { int nxt, to; } e[N << 1];
int head[N], odd[N], l[N], r[N], t[N], v[N], p[N], ecnt;

void add(int u, int v) {
	e[++ecnt] = (edge) {head[u], v}, head[u] = ecnt;
	e[++ecnt] = (edge) {head[v], u}, head[v] = ecnt;
}

void dfs1(int u, int fa) {
	go(i, v, u) {
		if (v == fa) continue;
		dfs1(v, u);
		if (odd[v] == -1) continue;
		if (odd[u] == -1)  odd[u] = (odd[v] ^ 1);
		else if (odd[v] == odd[u]) puts("No"), exit(0);
		l[u] = max(l[u], l[v] - 1), r[u] = min(r[u], r[v] + 1);
		if (l[u] > r[u]) puts("No"), exit(0);
	}
}

void dfs2(int u, int fa) {
	go(i, v, u) {
		if (v == fa) continue;
		l[v] = max(l[v], l[u] - 1), r[v] = min(r[v], r[u] + 1);
		if (~odd[v]) {
			if ((odd[v] == odd[u]) || (l[v]  > r[v])) 
				puts("No"), exit(0);
		}
		else odd[v] = (odd[u] ^ 1);
		dfs2(v, u);
	}
}

void get(int u, int fa) {
	if (~fa) t[u] = t[fa] - 1;
	else t[u] = l[u];
	if ((t[u] - odd[u]) & 1) t[u]--;
	if (t[u] < l[u]) t[u] += 2;
	go(i, v, u) if (v != fa) get(v, u);
}

void _wrk(int u, int fa) { 
	go(i, v, u) 
		if (v != fa) {
		t[v] = t[u] - 1;
		if (t[v] < l[v]) t[v] += 2;
		_wrk(v, u);
	} 
}

int main() {
	int n = rd();
	inc(i, 1, n - 1) add(rd(), rd());
	int k = rd();
	if (k) {
		inc(i, 1, k) 
			v[i] = rd(), p[i] = rd(), t[v[i]] = p[i], l[v[i]] = r[v[i]] = p[i], odd[v[i]] = (abs(p[i]) & 1);
		inc(i, 1, n) if (!t[i]) l[i] = -inf, r[i] = inf, odd[i] = -1;
		dfs1(1, -1), dfs2(1, -1), get(1, -1);
	}
	else t[1] = 1, _wrk(1, -1);
	puts("Yes");
	inc(i, 1, n) printf("%d\n", t[i]);
}

#include <stdio.h>
#include <algorithm>
#include <string.h>
#include <iostream>
using namespace std;
const int MAXN = 100005;
const int INF = 2000000000;
int numEdge, n, k;
int head[MAXN], id[MAXN];
int L[MAXN], R[MAXN];
struct Edge
{
    int v, next;
}edge[MAXN << 1];
void addEdge(int u, int v)
{
    edge[numEdge].v = v;
    edge[numEdge].next = head[u];
    head[u] = numEdge++;
}
void dfs(int u, int pre)
{
    for(int i = head[u]; i != -1; i = edge[i].next)
    {
        int v = edge[i].v;
        if(v == pre) continue;
        dfs(v, u);
        if(R[v] + 1 < L[u] || L[v] - 1 > R[u]) id[u] = 2;
        L[u] = max(L[u], L[v] - 1);
        R[u] = min(R[u], R[v] + 1);
        if(id[u] == -1) id[u] = id[v] ^ 1;
        else if(id[u] == id[v]) id[u] = 2;
    }
}
void dfs(int u, int pre, int nxtL, int nxtR)
{
    if(pre != -1)
    {
        if(nxtR < L[u] || nxtL > R[u]) id[u] = 2;
        L[u] = max(L[u], nxtL);
        R[u] = min(R[u], nxtR);
    }
    int max1 = nxtL, max2 = -INF;
    int min1 = nxtR, min2 =  INF;
    for(int i = head[u]; i != -1; i = edge[i].next)
    {
        int v = edge[i].v;
        if(v == pre) continue;
        if(L[v] - 1 >= max1) max2 = max1, max1 = L[v] - 1;
        else if(L[v] - 1 > max2) max2 = L[v] - 1;

        if(R[v] + 1 <= min1) min2 = min1, min1 = R[v] + 1;
        else if(R[v] + 1 < min2) min2 = R[v] + 1;
    }
    for(int i = head[u]; i != -1; i = edge[i].next)
    {
        int v = edge[i].v;
        if(v == pre) continue;
        int tmpL = max1 - 1, tmpR = min1 + 1;
        if(L[v] - 1 == tmpL + 1) tmpL = max2 - 1;
        if(R[v] + 1 == tmpR - 1) tmpR = min2 + 1;
        dfs(v, u, tmpL, tmpR);
    }
}
int main()
{
    scanf("%d", &n);
    numEdge = 0;
    memset(head, -1, sizeof(head));
    memset(id, -1, sizeof(id));
    for(int u, v, i = 1; i < n; i++)
    {
        scanf("%d%d", &u, &v);
        addEdge(u, v);
        addEdge(v, u);
    }
    for(int i = 1; i <= n; i++) L[i] = -INF, R[i] = INF;
