        return false;


    if (isset[u])
        return true;


    if (done.find(make_pair(u,make_pair(u,range[u]))) != done.end())
        return done[make_pair(u,make_pair(u,range[u]))];

    bool retval = true;
    for(int j=0;j<unset_edges[u].size();j++) {
        int v = unset_edges[u][j];
        if (v == par)
            continue;
        if (!dfs(u,v,range[u])) {
            retval=false;
            break;
        }
    }
    done[make_pair(u,make_pair(u,range[u]))]=retval;
    return retval;

}

