            if(r[v] > r[u] + 1) wl.push(v);
            r[v] = min(r[v], r[u] + 1);
        }
    }
    for(int i = 1; i <= n; i++) {
        if(l[i] == r[i]) had_val[i] = true, val[i] = l[i];
        if(had_val[i]) wl.push(i);
    }
    while(not wl.empty()) {
        u = wl.front(); had_val[u] = true; wl.pop();
        for(int v : graph[u]) {
            if(had_val[v] && abs(val[v] - val[u]) % 2 == 0) return !printf("No");
            else if(not had_val[v]) {
                int L = val[u]-1, R = val[u]+1;
                if(l[v] <= L && L <= r[v]) val[v] = L;
                else if(l[v] <= R && R <= r[v]) val[v] = R;
                else return !printf("No");
                wl.push(v);
            }
        }
    }
    printf("Yes\n");
    for(int i = 1; i <= n; i++) printf("%d\n", val[i]);
}

