const int maxn = (int)(1e5) + 5;
int a[maxn], l[maxn], r[maxn], T[maxn];
vector<int> nxt[maxn], g[maxn];
int n;

void dfs(int x, int f) {
	for (int i = 0; i < (int)nxt[x].size(); ++i) if (nxt[x][i] ^ f) {
		dfs(nxt[x][i], x); 
		int L = l[nxt[x][i]], R = r[nxt[x][i]];
		if (L == R) g[x].push_back(L);
		l[x] = max(l[x], L - 1); r[x] = min(r[x], R + 1);
	} if (a[x] >= 0) l[x] = max(l[x], a[x]), r[x] = min(r[x], a[x]);
	int mx = g[x].size(); for (int i = 0; i < mx; ++i) T[i] = g[x][i];
	sort(T, T + mx); mx = unique(T, T + mx) - T; g[x].clear();
	for (int i = 0; i < mx; ++i) if (T[i] >= l[x] && T[i] <= r[x]) g[x].push_back(T[i]);
}

void gen(int x, int f) {
	for (int i = 0; i < (int)nxt[x].size(); ++i) if (nxt[x][i] ^ f) {
		int L = l[nxt[x][i]], R = r[nxt[x][i]];
		if (L <= a[x] - 1 && a[x] - 1 <= R && find(g[nxt[x][i]].begin(), g[nxt[x][i]].end(), a[x] - 1) == g[nxt[x][i]].end()) a[nxt[x][i]] = a[x] - 1; 
		else a[nxt[x][i]] = a[x] + 1;
		gen(nxt[x][i], x);
	}
}

inline bool chk() {
	for (int i = 1; i <= n; ++i) if (l[i] + (int)g[i].size() > r[i]) return 0; return 1;
}

