	scanf("%d", &K);
	memset(a, -1, sizeof(a));
	for (int i = 1; i <= K; ++i) {
		int x, v; scanf("%d%d", &x, &v); a[x] = v;
	}
	memset(l, 0x80, sizeof(l));
	memset(r, 0x3f, sizeof(r));
	dfs(1, 0);
	if (chk()) {
		printf("Yes\n"); 
		if (a[1] < 0) {
			if (!g[1].size() || g[1][0] > l[1]) a[1] = l[1];
			else for (int i = 1; i < (int)g[1].size(); ++i) if (g[1][i] != g[1][i - 1] + 1) {
				a[1] = g[1][i - 1] + 1; break;
			}
		}
		gen(1, 0);
		for (int i = 1; i <= n; ++i) printf("%d\n", a[i]);
	} else printf("No\n");
	return 0;
}

