struct Graph
{
    Graph(const int v)
        : V{ v }, edge(v), rev_edge(v) {}
    void addEdge(const int from, const int to)
    {
        edge[from].push_back(to);
        rev_edge[to].push_back(from);
    }
    const int V;
    vector<vector<int>> edge;
    vector<vector<int>> rev_edge;
};
using S = unordered_set<int>;
using P = pair<bool, S>;
void dfs(const Graph& g, const int s, vector<bool>& used, vector<int>& node, vector<P>& sets)  // a or b or c
{
    used[s] = true;
    S st;
    bool first = true;
    if (node[s] != -1) {
        st.insert(node[s]);
        first = false;
    }
    for (const int to : g.edge[s]) {
        if (not first and st.empty()) {
            break;
        }
        if (not used[to]) {
            dfs(g, to, used, node, sets);
            if (not sets[to].first) {
                if (first) {
                    P sub = sets[to];
                    for (const int e : sub.second) {
                        st.insert(e - 1);
                        st.insert(e + 1);
                    }
                    first = false;
                } else {
                    P sub = sets[to];
                    S tmp;
                    for (const int e : sub.second) {
                        if (st.find(e - 1) != st.end()) {
                            tmp.insert(e - 1);
                        }
                        if (st.find(e + 1) != st.end()) {
                            tmp.insert(e + 1);
                        }
                    }
                    swap(tmp, st);
                }
            }
        }
    }
    if (first) {
        sets[s] = { true, st };
    } else {
        if (st.size() == 1) {
            node[s] = *st.begin();
        }
        sets[s] = { false, st };
    }
}

void dfs(const Graph& g, const int s, const int par, vector<bool>& used, vector<int>& node, const vector<P>& sets)  // a or b or c
{
    used[s] = true;
    int ans = -1;
    if (sets[s].first or sets[s].second.find(par - 1) != sets[s].second.end()) {
        ans = par - 1;
    }
    if (sets[s].first or sets[s].second.find(par + 1) != sets[s].second.end()) {
        ans = par + 1;
    }
    node[s] = ans;
    for (const int to : g.edge[s]) {
        if (not used[to]) {
            dfs(g, to, ans, used, node, sets);
        }
    }
}

int main()
{
    cin.tie(0);
    ios::sync_with_stdio(false);
    int N;
    cin >> N;
    Graph g(N);
    vector<int> node(N, -1);
    for (int i = 0; i < N - 1; i++) {
        int u, v;
        cin >> u >> v;
        u--, v--;
        g.addEdge(u, v);
        g.addEdge(v, u);
    }
    int K;
    cin >> K;
    for (int i = 0; i < K; i++) {
        int v, p;
        cin >> v >> p;
        v--;
        node[v] = p;
    }
    vector<bool> used(N, false);
    vector<P> sets(N);
    dfs(g, 0, used, node, sets);
    //    show(sets);
    if (sets[0].first) {
        node[0]       = 0;
        sets[0].first = false;
        sets[0].second.insert(0);
    } else if (sets[0].second.empty()) {
        cout << "No" << endl;
        return 0;
    } else {
        node[0] = *sets[0].second.begin();
        sets[0].second.clear();
        sets[0].second.insert(node[0]);
    }
    cout << "Yes" << endl;
    fill(used.begin(), used.end(), false);
    dfs(g, 0, node[0] - 1, used, node, sets);
    for (int i = 0; i < N; i++) {
        cout << node[i] << endl;
    }
    return 0;
}

