void addedge(int u, int v)
{
	e[++ cnt].next = p[u].first;
	p[u].first = cnt;
	e[cnt].to = v;
	e[++ cnt].next = p[v].first;
	p[v].first = cnt;
	e[cnt].to = u;
}

void dfs1(int i)
{
	p[i].visited = true;
	if (~p[i].num && p[i].odd != (p[i].num & 1))
	{
		printf("No\n");
		exit(0);
	}
	for (int j = p[i].first; j; j = e[j].next)
	{
		int x = e[j].to;
		if (p[x].visited)
			continue;
		p[x].odd = !p[i].odd;
		dfs1(x);
		p[i].left = max(p[i].left, p[x].left - 1);
		p[i].right = min(p[i].right, p[x].right + 1);
	}
	if (p[i].left > p[i].right)
	{
		printf("No\n");
		exit(0);
	}
}

void dfs2(int i)
{
	p[i].visited = true;
	for (int j = p[i].first; j; j = e[j].next)
	{
		int x = e[j].to;
		if (p[x].visited)
			continue;
		if (p[i].num - 1 >= p[x].left && p[i].num - 1 <= p[x].right)
			p[x].num = p[i].num - 1;
		else
			p[x].num = p[i].num + 1;
		dfs2(x);
	}
}

