int level;
int ansFlag = true;
int l[MAXN], r[MAXN];
int ans[MAXN];

void DFS1(int u, int pre){
	if (val[u] >= 0){
		ansFlag &= ((dep[u] ^ val[u]) & 1) == level;
		l[u] = val[u], r[u] = val[u];
	}
	else
		l[u] = -1E7, r[u] = 1E7;
	for (int v, i = 0; i < E[u].size(); ++i){
		if ((v = E[u][i]) == pre)
			continue;
		dep[v] = dep[u] + 1;
		DFS1(v, u);

		l[u] = max(l[u], l[v] - 1);
		r[u] = min(r[u], r[v] + 1);
	}
	if (l[u] > r[u])
		ansFlag = false;
}

void DFS2(int u, int pre){
//	printf("%d %d %d, %d\n", u, l[u], r[u], ans[u]);
	for (int v, i = 0; i < E[u].size(); ++i){
		if ((v = E[u][i]) == pre)
			continue;
		ans[v] = ans[u] + 1 <= r[v] ? ans[u] + 1 : ans[u] - 1;
		DFS2(v, u);
	}
}

