int jiou[100007][2];
vector<int> ord;
int fa[100007];
int ans[100007];
bool fuck;

void dfs(int now,int lst){
	l[now]=-Inf;
	r[now]=Inf;
	for(int i=0;i<SZ(nei[now]);i++){
		int to=nei[now][i];
		if(to==lst){
			continue;
		}
		dfs(to,now);
		fa[to]=now;
		if(jiou[to][0]){
			jiou[now][1]=1;
		}
		if(jiou[to][1]){
			jiou[now][0]=1;
		}
		l[now]=max(l[now],l[to]-1);
		r[now]=min(r[now],r[to]+1);
	}
	if(numed[now]){
		l[now]=max(l[now],num[now]);
		r[now]=min(r[now],num[now]);
		jiou[now][num[now]%2]=1;
	}
	if(jiou[now][0]&&jiou[now][1]){
		fuck=1;
	}
	if(l[now]>r[now]){
		fuck=1;
	}
	ord.pb(now);
}

int gao(int now,int lst){
	if(!lst){
		return l[now];
	}
	l[now]=max(l[now],ans[lst]-1);
	r[now]=min(r[now],ans[lst]+1);
	if(l[now]%2==ans[lst]%2){
		l[now]++;
	}
	return l[now];
}

