	}
	fio>>k;
	for(int i=0;i<k;i++){
		int a,b;
		fio>>a>>b;
		numed[a]=1;
		num[a]=b;
	}
	dfs(1,0);
	if(fuck){
		OVER("No\n");
	}
	reverse(ALL(ord));
	fio<<"Yes\n";
	for(int i=0;i<SZ(ord);i++){
		int x=ord[i];
		ans[x]=gao(x,fa[x]);
	}
	for(int i=1;i<=n;i++){
		fio<<ans[i]<<endl;
	}
	return 0;
}

