bool build_tree(int p)
{
	vis[p]=1;
	for(unsigned int i=0;i<G[p].size();i++)
	{
		int t=G[p][i];
		if(!vis[t])
		{
			C[p].push_back(t);
			if(eoro[t]!=-1 && eoro[t]==eoro[p]) return 1;
			eoro[t]=(eoro[p]+1)%2;
			bool o=build_tree(t);
