void depth_dfs(int now, int par, int d) {
  depth[now] = d;
  rep (i, G[now].size()) {
    if (G[now][i] == par) continue;
    depth_dfs(G[now][i], now, d + 1);
  }
}

pii merge(pii a, pii b) {
  pii res(max(a.first, b.first), min(a.second, b.second));
  if (res.first >= res.second) {
    return pii(-1, -1);
  }
  else return res;
}

pii dfs(int now, int par) {
  pii range = value[now];
  rep (i, G[now].size()) {
    if (G[now][i] == par) continue;
    pii temp = dfs(G[now][i], now);
    temp.first--; temp.second++;
    if (even == (depth[now] % 2 == 0)) {
      if (temp.first % 2 != 0) temp.first++;
      if (temp.second % 2 == 0) temp.second--;
    }
    else {
      if (temp.first % 2 == 0) temp.first++;
      if (temp.second % 2 != 0) temp.second--;
    }

    range = merge(range, temp);
    if (range.first >= range.second) {
      cout << "No" << endl;
      exit(0);
    }
  }
  if (even == (depth[now] % 2 == 0)) {
    if (range.first % 2 != 0) range.first++;
    if (range.second % 2 == 0) range.second--;
  }
  else {
    if (range.first % 2 == 0) range.first++;
    if (range.second % 2 != 0) range.second--;
  }

  if (range.first >= range.second) {
    cout << "No" << endl;
    exit(0);
  }

  if (value[now] != pii(-inf, inf)) {
    assert(value[now].first == value[now].second - 1);
    if (not in(value[now].first, range.first, range.second)) {
      cout << "No" << endl;
      exit(0);
    }
    return value[now];
  }
  value[now] = range;
  return range;
}

void decide(int now, int par) {
  if (par == -1) {
    value[now] = pii(value[now].first, value[now].first + 1);
  }
  else {
    vi ko = {value[par].first - 1, value[par].first + 1};
    rep (i, 2) {
      if (in(ko[i], value[now].first, value[now].second)) {
        value[now].first = ko[i];
        value[now].second = ko[i] + 1;
        break;
      }
    }
  }

  rep (i, G[now].size()) {
    if (G[now][i] == par) continue;
    decide(G[now][i], now);
  }
}


