void dfs (int node , int par , int exp) {
    in[node] = t++;
    if(val[node] == -1){
        v.push_back(INF - exp);
    }else{
        v.push_back(val[node]-exp);
    }
    for(int nxt : adj[node])
        if(nxt != par)
            dfs(nxt , node , exp == 1 ? 2 : exp-1);
    out[node] = t-1;
}

