void dfs(int x,int f){
	for(int i=0;i<a[x].size();i++){
		int u=a[x][i];
		if(u==f)
			continue;
		dfs(u,x);
		if(minl[u]==-INF)
			continue;
		if(minl[x]==-INF){
			minl[x]=minl[u]-1;
			maxl[x]=maxl[u]+1;
		}
		else{
			if(maxl[x]%2==maxl[u]%2)
				flag=0;
			maxl[x]=min(maxl[x],maxl[u]+1);
			minl[x]=max(minl[x],minl[u]-1);	
		}
	}
	if(p[x]!=-1){
		if(check(minl[x],maxl[x],p[x])==0)
			flag=0;
		minl[x]=maxl[x]=p[x];
	}
}
void dfs1(int x,int f,int minv,int maxv){
	if(maxv!=INF){
		if(maxl[x]==INF){
			maxl[x]=maxv+1;
			minl[x]=minv-1;
		}
		else{
			if(maxv%2==maxl[x]%2)
				flag=0;
			if(p[x]!=-1){
				if(check(minl[x],maxl[x],p[x])==0)
					flag=0;
			}
			else{
				minl[x]=max(minl[x],minv-1);
				maxl[x]=min(maxl[x],maxv+1);
			}
		}
	}
	for(int i=0;i<a[x].size();i++){
		int u=a[x][i];
		if(u==f)
			continue;
		dfs1(u,x,minl[x],maxl[x]);
	}
	if(minl[x]>maxl[x])
		flag=0;
}

