const int INF = 1e9;

inline bool IsAny(const pair<int, int>& p) {
    return p.first == INF && p.second == INF;
}

inline pair<int, int> GetAny() {
    return make_pair(INF, INF);
}

inline bool Merge(pair<int, int> lhs, pair<int, int> rhs, pair<int, int>& result) {
    if (IsAny(lhs)) {
        result = rhs;
        return true;
    }
    if (IsAny(rhs)) {
        result = lhs;
        return true;
    }
    if ((abs(lhs.first) & 1) != (abs(rhs.first) & 1)) {
        return false;
    }
    result.first = max(lhs.first, rhs.first);
    result.second = min(lhs.second, rhs.second);
    if (result.first > result.second) {
        return false;
    }
    return true;
}

inline pair<int, int> Extend(pair<int, int> p) {
    if (IsAny(p)) {
        return p;
    }
    --p.first;
    ++p.second;
    return p;
}

int n;
vector<vector<int>> g;

vector<int> values;

vector<pair<int, int>> possible;

bool BuildPossible(int v, int pr) {
    possible[v].first = possible[v].second = values[v];
    for (int u : g[v]) {
        if (u == pr) {
            continue;
        }
        if (!BuildPossible(u, v)) {
            return false;
        }
        if (!Merge(possible[v], Extend(possible[u]), possible[v])) {
            return false;
        }
    }
    return true;
}

vector<int> result;

void BuildResult(int v, int pr, const pair<int, int>& up) {
    pair<int, int> cur;
    bool ok = Merge(possible[v], up, cur);
    assert(ok);
    result[v] = cur.first;
    cur.second = cur.first;
    cur = Extend(cur);
    for (int u : g[v]) {
        if (u != pr) {
            BuildResult(u, v, cur);
        }
    }
}

int main() {
