    if( num[i] != -(1<<28) ) {
      fillRange(i, Range(num[i], num[i]));
    }
  }
  if( ansIsNo() ) {
    printf("No\n");
    return 0;
  }
  else {
    printf("Yes\n");
  }

  // step 2
  for(int i = 1; i <= n; ++i) {
    printf("%d\n", range[i].lower);
  }

  return 0;
}

#include<iostream>
#include<queue>
#include<utility>
#include<algorithm>
using namespace std;
const int MAXn=100001;
const int INFTY=1<<21;

int n,col[MAXn],d[MAXn];
vector<pair<int,int>> Q[MAXn];

void dijkstra(int s)
{
	priority_queue<pair<int,int>> PQ;//weight,id
	for(int i=0;i<n;i++)
	{
		d[i]=INFTY;
		col[i]=0;
	}
	d[s]=0;
	PQ.push(make_pair(0,s));
	col[s]=1;

	while(!PQ.empty())
	{
		pair<int,int> f=PQ.top();PQ.pop();
		int u=f.second;
		col[u]=2;
		if(d[u]<f.first*(-1))continue;
		for(int j=0;j<Q[u].size();j++)
		{
			int v=Q[u][j].first;
			if(col[v]==2)continue;
			if(d[u]+Q[u][j].second<d[v])
			{
				d[v]=d[u]+Q[u][j].second;
				PQ.push(make_pair(d[v]*(-1),v));
				col[v]=1;
			}
		}
	}

	return;
}

int main()
{
	cin>>n;
	int a,b;
	int old[MAXn];
	for(int i=0;i<n;i++)old[i]=-1;
	for(int i=1;i<n;i++)
	{
		cin>>a>>b;
		a--;b--;
		Q[a].push_back(make_pair(b,1));
		Q[b].push_back(make_pair(a,1));
	}
	int k,v,p;cin>>k;
	for(int i=0;i<k;i++)
	{
		cin>>v>>p;v--;
		old[v]=p;
		Q[n].push_back(make_pair(v,p));
	}
	dijkstra(n);

	for(int i=0;i<n;i++)
	{
		if(old[i]!=-1)
		{
			if(old[i]!=d[i])
			{
				cout<<"No"<<endl;
				return 0;
			}
		}
	}

	for(int i=0;i<n;i++)
	{
		for(int j=0;j<Q[i].size();j++)
		{
			if(abs(d[i]-d[Q[i][j].first])!=1)
			{
				cout<<"No"<<endl;
				return 0;
			}
		}
	}

	cout<<"Yes"<<endl;

	for(int i=0;i<n;i++)
	{
		cout<<d[i]<<endl;
	}
	return 0;
}

