typedef long long ll;
typedef long double ld;

const ll SIZE = 1e6 + 10, S2 = 1e7 * 2, MOD = 1e9 + 7, INF = 1e9 * 1e9;

vector<vector<ll>> graph;
ll col[SIZE], dist[SIZE], par[SIZE];
pair<ll, ll> bst[SIZE];
bool used[SIZE];

pair<ll, ll> dfs(int v, int par = -1) {
    used[v] = 1;

    if (col[v] != -1) {
        if (abs(col[par] - col[v]) % 2 != abs(dist[par] - dist[v]) % 2) {
            cout << "No";
            exit(0);
        }
    }
    pair<ll, ll> pr = { -INF, INF };
    if (col[v] != -1) {
        pr = { col[v], col[v] };
    }
    for (auto to : graph[v]) {
        if (!used[to]) {
            dist[to] = dist[v] + 1;
            if (col[v] == -1) {
                pair<ll, ll> q = dfs(to, par);
                pr.first = max(pr.first, q.first - 1);
                pr.second = min(pr.second, q.second + 1);
            }
            else {
                pair<ll, ll> q = dfs(to, v);
                pr.first = max(pr.first, q.first - 1);
                pr.second = min(pr.second, q.second + 1);
            }
        }
    }

    bst[v] = pr;
    return pr;
}

void ch(int v, int par = -1) {
    used[v] = 1;

    if (col[v] != -1 && !(bst[v].first <= col[v] && bst[v].second >= col[v])) {
        cout << "No";
        exit(0);
    }

    bool flag = true;
    if (col[v] == -1) {
        if (bst[v].first <= col[par] - 1 && bst[v].second >= col[par] - 1) {
            col[v] = col[par] - 1;
            flag = false;
        }
        if (flag && bst[v].first <= col[par] + 1 && bst[v].second >= col[par] + 1) {
            flag = false;
            col[v] = col[par] + 1;
        }
    }
    else {
        flag = false;
    }

    if (flag) {
        cout << "No";
        exit(0);
    }
    for (auto to : graph[v]) {
        if (!used[to]) {
            ch(to, v);
        }
    }
}

int main() {
    fastInp;

    ll n;
    cin >> n;

    graph.resize(n);
    for (int i = 0; i < n - 1; i++) {
        ll u, v;
        cin >> u >> v;
        u--; v--;
        graph[u].push_back(v);
        graph[v].push_back(u);
    }

    ll q;
    cin >> q;

    for (int i = 0; i < n; i++) col[i] = -1;
    while (q--) {
        ll p, v;
        cin >> v >> p;
        v--;

        col[v] = p;
    }


    for (int i = 0; i < n; i++) {
        if (col[i] != -1) {
            dfs(i);
            break;
        }
    }

    for (int i = 0; i < n; i++) used[i] = 0;

    for (int i = 0; i < n; i++) {
        if (col[i] != -1) {
            ch(i);
            break;
        }
    }

    cout << "Yes\n";
    for (int i = 0; i < n; i++) cout << col[i] << "\n";
    return 0;
}

