int rd() {
	int ret = 0; bool fl = 0; char ch = 0;
	while (!isdigit(ch)) fl |= (ch == '-'), ch = gc();
	while (isdigit(ch)) ret = (ret << 1) + (ret << 3) + (ch ^ 48), ch = gc();
	return fl ? -ret : ret;
}
#define go(i, v, x) for (int i = head[x], v = e[i].to; i; i = e[i].nxt, v = e[i].to)
struct edge { int nxt, to; } e[N << 1];
int head[N], odd[N], l[N], r[N], t[N], v[N], p[N], ecnt;

void add(int u, int v) {
	e[++ecnt] = (edge) {head[u], v}, head[u] = ecnt;
	e[++ecnt] = (edge) {head[v], u}, head[v] = ecnt;
}

void dfs1(int u, int fa) {
	go(i, v, u) {
		if (v == fa) continue;
		dfs1(v, u);
		if (odd[v] == -1) continue;
		if (odd[u] == -1)  odd[u] = (odd[v] ^ 1);
		else if (odd[v] == odd[u]) puts("No"), exit(0);
		l[u] = max(l[u], l[v] - 1), r[u] = min(r[u], r[v] + 1);
		if (l[u] > r[u]) puts("No"), exit(0);
	}
}

void dfs2(int u, int fa) {
	go(i, v, u) {
		if (v == fa) continue;
		l[v] = max(l[v], l[u] - 1), r[v] = min(r[v], r[u] + 1);
		if (~odd[v]) {
			if (odd[v] == odd[u] || (l[v] - 1 > r[u]) || (r[v] + 1 < l[u])) 
				puts("No"), exit(0);
		}
		else odd[v] = (odd[u] ^ 1);
		dfs2(v, u);
	}
}

void get(int u, int fa) {
	if (~fa) t[u] = t[fa] - 1;
	else t[u] = l[u];
	if ((t[u] - odd[u]) & 1) t[u]--;
	if (t[u] < l[u]) t[u] += 2;
	go(i, v, u) if (v != fa) get(v, u);
}

void _wrk(int u, int fa) { go(i, v, u) if (v != fa) t[v] = (t[u] ^ 1), _wrk(v, u); }

int main() {
	int n = rd();
	inc(i, 1, n - 1) add(rd(), rd());
	int k = rd();
	if (k) {
		inc(i, 1, k) 
			v[i] = rd(), p[i] = rd(), t[v[i]] = p[i], l[v[i]] = r[v[i]] = p[i], odd[v[i]] = (abs(p[i]) & 1);
		inc(i, 1, n) if (!t[i]) l[i] = -inf, r[i] = inf, odd[i] = -1;
		dfs1(1, -1), dfs2(1, -1), get(1, -1);
	}
	else t[1] = 1, _wrk(1, -1);
	puts("Yes");
	inc(i, 1, n) printf("%d\n", t[i]);
}

