[[noreturn]] void impossible() {
    PRINTLN("No");
    EXIT();
}

constexpr Int PARITY(Int x) {
    return x%2==0 ? 0 : 1;
}

auto udgraph_list(Int n, const vector<pair<Int,Int>>& es) {
    vector<vector<Int>> g(n);
    for(const auto& e : es) {
        Int a,b; tie(a,b) = e;
        g[a].emplace_back(b);
        g[b].emplace_back(a);
    }
    return g;
}

pair<Int,Int> interval_merge(const pair<Int,Int>& a, const pair<Int,Int>& b) {
    Int al,ar; tie(al,ar) = a;
    Int bl,br; tie(bl,br) = b;
    return {MAX(al,bl), MIN(ar,br)};
}

bool interval_contains(const pair<Int,Int>& z, Int x) {
    Int l,r; tie(l,r) = z;
    return l <= x && x < r;
}

bool interval_is_empty(const pair<Int,Int>& z) {
    Int l,r; tie(l,r) = z;
    return l >= r;
}

void solve() {
    Int N = RD();
    auto E = RD_VEC<pair<Int1,Int1>>(N-1);
    auto G = udgraph_list(N, E);

    Int root = -1;
    vector<Int> P(N, INF);
    Int K = RD();
    LOOP(K) {
        Int v = RD1();
        Int p = RD();
        P[v] = p;
        root = v;
    }

    vector<Int> paritys(N, -1);
    vector<pair<Int,Int>> intervals(N);
    auto dfs = FIX([&](auto&& self, Int v, Int p, Int d) -> void {
        paritys[v] = PARITY(P[root]+d);
        intervals[v] = P[v]==INF ? make_pair(-INF,INF) : make_pair(P[v],P[v]+1);
        for(Int to : G[v]) {
            if(to == p) continue;
            self(to, v, d+1);
            pair<Int,Int> z = intervals[to];
            --z.first;
            ++z.second;
            intervals[v] = interval_merge(intervals[v], z);
        }
    });
    dfs(root, -1, 0);
    //DBG(paritys);
    //DBG(intervals);

    REP(v, N) {
        if(P[v] == INF) continue;
        if(PARITY(P[v]) != paritys[v]) impossible();
        if(interval_is_empty(intervals[v])) impossible();
    }

    auto dfs2 = FIX([&](auto&& self, Int v, Int p) -> void {
        if(P[v] == INF) {
            if(interval_contains(intervals[v], P[p]-1))
                P[v] = P[p]-1;
            else if(interval_contains(intervals[v], P[p]+1))
                P[v] = P[p]+1;
            ASSERT(P[v] != INF);
            if(PARITY(P[v]) != paritys[v]) impossible();
        }

        for(Int to : G[v]) {
            if(to == p) continue;
            self(to, v);
        }
    });
    dfs2(root, -1);

    PRINTLN("Yes");
    ALL(for_each, P, LIFT(PRINTLN));
}

signed main() {
    Int T = 1; //RD();
    LOOP(T) {
        solve();
    }

    EXIT();
}

#include <cstdio>
#include <cstring>
#include <algorithm>
using namespace std;
const int maxn=1e5+10;
int n,k;
int head[maxn],v[maxn],a[maxn],mark[maxn],L[maxn],R[maxn];
struct Edge
{
    int v,nx;
}edge[maxn<<1];
int cnt;
bool flag;

void _init() {
    cnt=0;
    memset(head,-1,sizeof(head));
}

void add(int u,int v) {
    edge[cnt].v=v; edge[cnt].nx=head[u];
    head[u]=cnt++;
    edge[cnt].v=u; edge[cnt].nx=head[v];
    head[v]=cnt++;
}

void dfs1(int u,int fa) {
    if (mark[u] && (v[u]^(a[u]&1))) {
        flag=0; return;
    }
    for (int i=head[u];i!=-1;i=edge[i].nx) {
        int to=edge[i].v;
        if (to==fa) continue;
        v[to]=v[u]^1;
        dfs1(to,u);
    }
}

void dfs2(int u,int fa) {
    if (mark[u]) L[u]=R[u]=a[u];
    else L[u]=-1e9,R[u]=1e9;
    for (int i=head[u];i!=-1;i=edge[i].nx) {
        int to=edge[i].v;
        if (to==fa) continue;
        dfs2(to,u);
        L[u]=max(L[to]-1,L[u]);
        R[u]=min(R[to]+1,R[u]);
    }
    if (L[u]>R[u]) flag=0;
}

void dfs3(int u,int fa) {
    for (int i=head[u];i!=-1;i=edge[i].nx) {
        int to=edge[i].v;
        if (to==fa) continue;
        a[to]=a[u]+(a[u]+1>R[to]?-1:1);
        dfs3(to,u);
    }
}

int main() {
    _init();
    flag=1;
    scanf("%d",&n);
    int x,y;
    for (int i=1;i<n;i++) {
        scanf("%d%d",&x,&y);
        add(x,y);
    }
    scanf("%d",&k);
    for (int i=1;i<=k;i++) {
        scanf("%d%d",&x,&y);
        a[x]=y; mark[x]=1;
    }
    for (int i=1;i<=n;i++) {
        if (!mark[i]) continue;
        v[i]=a[i]&1; dfs1(i,i);
        break;
    }
    if (!flag) { puts("No"); return 0; }
    dfs2(1,1);
    if (!flag) { puts("No"); return 0; }
    L[1]+=((L[1]&1)^v[1]);
    a[1]=L[1];
    dfs3(1,1);
    puts("Yes");
    for (int i=1;i<=n;i++) printf("%d\n", a[i]);
    return 0;
}

