int inf = 4e18, mod = 1e9+7;
vector<vi> g;
vi res;
vector<ii> rng;
bool parity(int cur, int p,int f){
    if(res[cur] != inf && res[cur] % 2 != f) return false;
    bool ans = true;
    if(res[cur] != inf) rng[cur].first = rng[cur].second = res[cur];
    for(auto &v:g[cur]){
        if(v == p) continue;
        ans &= parity(v, cur, 1-f);
        rng[cur].first = max(rng[cur].first, rng[v].first - 1);
        rng[cur].second= min(rng[cur].second, rng[v].second + 1);
    }
    return ans && (rng[cur].x <= rng[cur].y);
}

void setValue(int cur, int p = -1){
    if(p != -1 && res[cur] == inf){
        if(res[p] + 1 <= rng[cur].y && res[p] + 1 >= rng[cur].x) res[cur] = res[p] + 1;
        else res[cur] = res[p] - 1;
    }
    for(auto &v:g[cur]){
        if(v == p) continue;
        setValue(v,cur);
    }
}

