  memset(P, 0x3f, sizeof P);
  for (int i = 1, v, p; i <= K; ++i) {
    scanf("%d%d", &v, &p);
    P[v] = p, rt = v;
  }

  flag = 1;
  dfs(rt, 0, 0);

  if (!flag) {
    puts("No");
    return 0;
  }

  puts("Yes");

  dfs2(rt, 0);

  for (int i = 1; i <= N; ++i)
    printf("%d\n", P[i]);

  return 0;
}

