	cin >> m; REP(i,0,n) dp[i][0]=-INF,dp[i][1]=INF;
	REP(i,0,m) cin >> a[i] >> b[i],a[i]--,dp[a[i]][0]=dp[a[i]][1]=b[i],used[a[i]]=true;

