int solve(){
	queue<int> qu;
	stack<int> st;
	qu.push(a[0]);
	REP(i,0,n) usedd[i]=false;
	while(!qu.empty()){
		auto p=qu.front(); qu.pop();
		if(usedd[p]) continue; usedd[p]=true;

		for(auto e:g[p]) qu.push(e);
		st.push(p);
	}

	while(!st.empty()){
		auto p=st.top(); st.pop();
		if(used[p]) continue;

		int mi=dp[p][0],ma=dp[p][1];
		for(auto e:g[p]){
			mi=max(mi,dp[e][0]);
			ma=min(ma,dp[e][1]);
		}

		mi=max(mi-1,-INF),ma=min(ma+1,INF);
		if(mi>ma){cout << "No" << endl; return 0;}
		dp[p][0]=mi,dp[p][1]=ma;
	}

	REP(i,0,n) used[i]=false;
	qu.push(a[0]); ans[a[0]]=b[0];
	while(!qu.empty()){
		auto p=qu.front(); qu.pop();
		used[p]=true;

		for(auto e:g[p]){
			if(used[e]) continue;
			if(dp[e][0]<=ans[p]-1&&ans[p]-1<=dp[e][1]) ans[e]=ans[p]-1;
			else if(dp[e][0]<=ans[p]+1&&ans[p]+1<=dp[e][1]) ans[e]=ans[p]+1;
			else{cout << "No" << endl; return 0;}
			qu.push(e);
		}
	}

	cout << "Yes" << endl;
	REP(i,0,n) cout << ans[i] << endl;
	return 0;
}

