const int maxn = 1e5 + 5;
const int inf = 1e9;
vector<int> E[maxn];
int n , odd[maxn];
bool ok;
// 判断奇偶性
void dfs1 (int u , int fa)
{
    for (auto v : E[u]){
        if (v == fa) continue;
        dfs1(v , u);
     //   cout << "现在在" << u << "点，它的奇偶性为 " << odd[u] << " 它的儿子" << v << "的奇偶性为" << odd[v] << endl;
        if (odd[v] == -1) continue;
        if (odd[u] == -1) odd[u] = (!odd[v]);
        else if (odd[u] == odd[v]) ok = false;
    }
}
int l[maxn] , r[maxn];
// 自下而上得到合法区间
void dfs2 (int u , int fa)
{
    for (auto v : E[u]){
        if (v == fa) continue;
        dfs2(v , u);
        if (r[v] == inf) continue;
        l[u] = max (l[u] , l[v] - 1);
        r[u] = min (r[u] , r[v] + 1);
    }
    if (l[u] > r[u]) ok = false;
}
int ans[maxn];
void dfs3 (int u , int fa)
{
    if ( ans[fa] <  r[u] ) ans[u] = ans[fa] + 1;
    else ans[u] = ans[fa] - 1;
    for (auto v : E[u]){
        if (v == fa) continue;
        dfs3(v , u);
    }
}
