        r[i] = inf;
        odd[i] = -1;
    }
    int k; cin >> k;
    for (int i = 1 ; i <= k ; i++) {
        int x , y ; cin >> x >> y;
        l[x] = r[x] = y;
        odd[x] = (y & 1);
    }
    ok = true;
    dfs1(1 , 0);
    if (!ok){
        cout << "No" << endl;
        return 0;
    }
   // for (int i = 1 ; i <= n ; i++) cout << l[i] << " " << r[i] << endl;
    dfs2(1 , 0);
    if (!ok){
        cout << "No" << endl;
        return 0;
    }
    ans[0] = l[1] + 1;
    dfs3(1 , 0);
    cout << "Yes" << endl;
   /* cout << endl;
