using namespace std;
const int N=1e5+10;
const int inf=1e9;
int n;
struct edge{int to,Next;}ed[N<<1];
int edcnt,head[N];
void addedge(int u,int v){ed[++edcnt]=(edge){v,head[u]};head[u]=edcnt;}
int le[N],ri[N];
void dfslr(int u,int Fa)
{
	for(int i=head[u];i;i=ed[i].Next)
	if(ed[i].to!=Fa)
	{
		int v=ed[i].to;
		le[v]=max(le[v],le[u]-1);
		ri[v]=min(ri[v],ri[u]+1);
		dfslr(v,u);
	}
	if(Fa)
	{
		le[Fa]=max(le[Fa],le[u]-1);
		ri[Fa]=min(ri[Fa],ri[u]+1);
	}
}
int ans[N];bool used[N*3];
bool dfsans(int u,int Fa)
{
	for(int i=head[u];i;i=ed[i].Next)
	if(le[ed[i].to]==ri[ed[i].to]) used[le[ed[i].to]+n]=true;
	int l=le[u];
	while(l<=ri[u]&&used[l+n]) l++;
	if(l>ri[u]) return false;
	le[u]=ri[u]=ans[u]=l;
	for(int i=head[u];i;i=ed[i].Next)
	if(le[ed[i].to]==ri[ed[i].to]) used[le[ed[i].to]+n]=false;
	for(int i=head[u];i;i=ed[i].Next)
	if(ed[i].to!=Fa)
	{
		int v=ed[i].to;
		le[v]=max(le[v],le[u]-1);
		ri[v]=min(ri[v],ri[u]+1);
		if(!dfsans(v,u)) return false;
	}
	return true;
}
int main()
{
	scanf("%d",&n);
	for(int i=1;i<n;i++)
	{
		int u,v;scanf("%d%d",&u,&v);
		addedge(u,v);addedge(v,u);
	}
	for(int i=1;i<=n;i++)
	{
		le[i]=-n;
		ri[i]=n*2;
	}
	int K;scanf("%d",&K);
	for(int i=1;i<=K;i++)
	{
		int Id,Val;scanf("%d%d",&Id,&Val);
		le[Id]=ri[Id]=Val;
	}
	dfslr(1,0);dfslr(1,0);
	bool flag=true;
	for(int i=1;i<=n;i++)
	if(le[i]>ri[i])
	{
		flag=false;
		break;
	}
	if(flag) flag=dfsans(1,0);
	if(!flag) printf("No\n");
	else{
		printf("Yes\n");
		for(int i=1;i<=n;i++) printf("%d\n",ans[i]);
	}
	return 0;
}

#include <bits/stdc++.h>

#define pb push_back

using namespace std;

const int MAXN = 1e5+5;

vector <int> adj[MAXN];

int L[MAXN], R[MAXN];

int ans[MAXN];

int n, k;

void bye() {
    printf("No");
    exit(0);
}

void dfs(int v, int pr) {
    for (int to : adj[v]) {
        if (to == pr) {
            continue;
        }

        dfs(to, v);

        L[v] = max(L[v], L[to] - 1);
        R[v] = min(R[v], R[to] + 1);
    }
}

void rec(int v, int pr) {
    if (L[v] > R[v]) {
        bye();
    }

    for (int to : adj[v]) {
        if (to == pr) {
            continue;
        }

        L[to] = max(L[to], L[v] - 1);
        R[to] = min(R[to], R[v] + 1);

        if (ans[to] == -1000000) {
            if (L[to] <= ans[v] - 1 && ans[v] - 1 <= R[to]) {
                ans[to] = ans[v] - 1;
            }
            else {
                ans[to] = ans[v] + 1;
            }
        }

        if (abs(ans[v] - ans[to]) != 1) {
            bye();
        }

        rec(to, v);
    }
}

void solve() {
    scanf("%d", &n);

    for (int i = 1, l, r; i < n; ++i) {
        scanf("%d %d", &l, &r);

        adj[l].pb(r);
        adj[r].pb(l);
    }

    for (int i = 1; i <= n; ++i) {
        ans[i] = -1000000;
        L[i] = -500000;
        R[i] = 500000;
    }

    scanf("%d", &k);

    int root = -1;

    for (int i = 1, ps, x; i <= k; ++i) {
        scanf("%d %d", &ps, &x);
        L[ps] = R[ps] = x;
        ans[ps] = x;
        root = ps;
    }

    dfs(root, -1);
    rec(root, -1);

    for (int i = 1; i <= n; ++i) {
        if (ans[i] < L[i] || ans[i] > R[i]) {
            bye();
        }
    }

    printf("Yes\n");

    for (int i = 1; i <= n; ++i) {
        printf("%d\n", ans[i]);
    }
}

int main() {
    #ifdef BThero
        freopen("input.txt", "r", stdin);
        freopen("output.txt", "w", stdout);
    #endif // BThero

    int tt = 1;

    while (tt--) {
        solve();
    }

    return 0;
}

