vector<int> g[N];
int n, k, num[N], ans[N];

pii merge(pii p1, pii p2){
	if(p1.fi > p2.fi) swap(p1,p2);
	if(p1.se >= p2.fi) return {max(p1.fi,p2.fi), min(p1.se,p2.se)};
	else cout << "No", exit(0);
}

void dfs(int p, int u){
	for(auto v:g[u]){
		if(v!=p){
			dfs(u,v);
			range[u] = merge(range[u],{range[v].fi-1,range[v].se+1});
		}
	}
}

void build(int p,int u){
	for(auto v:g[u]){
		if(v!=p){
			range[v] = merge({range[u].fi-1,range[u].se+1},range[v]);
			build(u,v);
		}
	}
}

