int main() {
  ios_base::sync_with_stdio(0); cin.tie(0);

  int n; cin >> n;
  vec<int, 2> adjEdge(n);
  for (int i = 1; i < n; ++i) {
    int u, v; cin >> u >> v; --u; --v;
    adjEdge[u].emplace_back(v);
    adjEdge[v].emplace_back(u);
  }
  vec<int, 1> a(n, -1);
  int k; cin >> k;
  while (k--) {
    int u, val; cin >> u >> val; --u;
    a[u] = val;
  }

  int root = static_cast<int>(find_if(all(a), [&](int i) { return ~i; }) - a.begin());
  vec<int, 1> prt(n); prt[root] = a[root] & 1;
  function<void(int, int)> calPrt = [&](int u, int par) {
    for (auto& v : adjEdge[u]) {
      if (v != par) {
        prt[v] = prt[u] ^ 1;
        calPrt(v, u);
      }
    }
  };
  calPrt(root, -1);
  for (int i = 0; i < n; ++i) {
    if (~a[i] && prt[i] != (a[i] & 1)) {
      cout << "No\n";
      return 0;
    }
  }

  vec<pair<int, int>, 1> range(n);
  function<void(int, int)> solve = [&](int u, int par) {
    range[u] = ~a[u] ? pair<int, int>{a[u], a[u]} : pair<int, int>{-INF, INF};
    if ((range[u].first & 1) != prt[u]) {
      ++range[u].first;
    }
    if ((range[u].second & 1) != prt[u]) {
      --range[u].second;
    }
    for (auto& v : adjEdge[u]) {
      if (v != par) {
        solve(v, u);
        asMx(range[u].first, range[v].first - 1);
        asMn(range[u].second, range[v].second + 1);
      }
    }
  };
  solve(root, -1);
  for (int i = 0; i < n; ++i) {
    if (range[i].first > range[i].second) {
      cout << "No\n";
      return 0;
    }
  }

  function<void(int, int)> trace = [&](int u, int par) {
    for (auto& v : adjEdge[u]) {
      if (v != par) {
        if (range[v].first <= a[u] - 1 && a[u] - 1 <= range[v].second) {
          a[v] = a[u] - 1;
        } else {
          a[v] = a[u] + 1;
        }
        trace(v, u);
      }
    }
  };
  trace(root, -1);
  cout << "Yes\n";
  for (auto& i : a) {
    cout << i << '\n';
  }

  return 0;
}

