#include<bits/stdc++.h>
#define INF (1e9)
#define N 100005
using namespace std;
typedef pair<int,int> P;
int n,a,b,k,v,p,ans[N];
vector<int> e[N];
P R[N];
bool flag=true;

P rmerge(P A,P B){
  return P(max(A.first,B.first),min(A.second,B.second));
}

P dfs(int x,int px){
  P res=R[x];
  for(int i=0;i<(int)e[x].size();i++)
    if(e[x][i]!=px)res=rmerge(res,dfs(e[x][i],x));
  return R[x]=res;
}

void dfs2(int x,int px,int v){
  if(!flag)return;
  ans[x]=v;
  for(int i=0;i<(int)e[x].size();i++){
    int nx=e[x][i];
    int minv=R[nx].first;
    int maxv=R[nx].second;
    if(nx!=px){
      if(ans[nx]!=-INF&&minv<=ans[nx]&&ans[nx]<=maxv&&(abs(ans[x]-ans[nx])==1)){
	dfs2(e[x][i],x,ans[nx]);
      }
      else if(minv<=ans[x]+1&&ans[x]+1<=maxv)dfs2(e[x][i],x,ans[x]+1);
      else if(minv<=ans[x]-1&&ans[x]-1<=maxv)dfs2(e[x][i],x,ans[x]-1);
      else{
	flag=false;
	break;
      }
    }
  }
}

