    cin>>v>>p;
    ans[v-1]=p;
  }
  for(int i=0;i<n;i++){
    R[i].first=-INF;
    R[i].second=INF;
    if(ans[i]!=-INF){
      R[i].first=ans[i]-1;
      R[i].second=ans[i]+1;
    }
  }
  dfs(0,-1);
  int f=0;
  for(int i=0;i<n;i++){
    if(ans[i]!=-INF){
      int minv=R[i].first;
      int maxv=R[i].second;
      if(minv<=ans[i]&&ans[i]<=maxv)dfs2(i,-1,ans[i]);
      else flag=false;
      f=1;
