bool findAns(vector<vector<int>>& e_list, vector<int>& v_val, vector<int>& pos){
	if(pos.empty()){
		cout << "YES" << endl;
		for(int i=1; i<v_val.size();i++){
			cout << v_val[i] << endl;
		}
		return true;
	}

	else{
		int v = pos.back();
		for(int i=0;i<e_list[v].size();i++){
			int ne = e_list[v][i];
			if(v_val[ne] != -1){
				if(v_val[ne]-v_val[v] != 1 && v_val[ne]-v_val[v] != -1)
					return false;
			}
			else{
				if(v_val[v] == 0){
					v_val[ne] = 1;
					pos.push_back(ne);
					if(findAns(e_list,v_val,pos))
						return true;
					else{
						pos.pop_back();
						return false;
					}
				}else{
					v_val[ne] = v_val[v] + 1;
					pos.push_back(ne);
					if(findAns(e_list,v_val,pos))
						return true;
					else{
						v_val[ne] = v_val[v] - 1;
						if(findAns(e_list,v_val,pos))
							return true;
						pos.pop_back();
						return false;
					}
				}
			}
		}
	}
	pos.pop_back();

	return findAns(e_list,v_val,pos);
}


int main(){
	int n,k;
	while(cin >> n){
		vector<vector<int>> e_list;
		vector<int> v_val(n+1,-1);

		vector<int> pos;

		for(int i=0;i<n+1;i++){
			e_list.push_back(vector<int>());
		}
		for(int i=0;i<n-1;i++){
			int a,b;
			cin >> a >> b;
			e_list[a].push_back(b);
			e_list[b].push_back(a);
		}
		cin >> k;
		if(k == 0){
			pos.push_back(1);
			v_val[1] = 0;
		}else{
			for(int i=0;i<k;i++){				
				int v,p;
				cin >> v >>	p;
				pos.push_back(v);
				v_val[v] = p;
			}
		}

		bool r = findAns(e_list, v_val, pos);
		if(!r)
			cout << "NO" << endl;
	}

	return 0;
}

