void dfs1(int v, int p, int guuki) {
    if(l[v] == u[v] && l[v] % 2 != guuki) {
        cout << "No" << endl;
        exit(0);
    }
    for(int x : G[v]) {
        if(x != p) {
            dfs1(x, v, 1 - guuki);
            chmax(l[v], l[x] - 1);
            chmin(u[v], u[x] + 1);
        }
    }
}

void dfs2(int v, int p) {
    if(l[v] == u[v])
        ans[v] = l[v];
    else if(l[v] <= ans[p] + 1 && ans[p] + 1 <= u[v])
        ans[v] = ans[p] + 1;
    else
        ans[v] = ans[p] - 1;
    for(int i : G[v])
        if(i != p) dfs2(i, v);
}

