	for(int i = 1; i <= n; i++)
		cout << val[i] << endl;
	exit(0);
}

void update(int x, int l, int r)
{
	L[x] = max(L[x], l);
	R[x] = min(R[x], r);
}

bool dfs1(int x, int fa, int c)
{
	if(spe[x] && c != (val[x] & 1))
		return false;
	for(int i = 0; i < edg[x].size(); i++)
		if(edg[x][i] != fa)
			if(!dfs1(edg[x][i], x, c ^ 1))
				return false;
	return true;
}

bool dfs2(int x, int fa)
{
	if(spe[x])
		update(x, val[x], val[x]);
	for(int i = 0; i < edg[x].size(); i++)
		if(edg[x][i] != fa)
		{
			int y = edg[x][i];
			if(!dfs2(y, x))
				return false;
			update(x, L[y] - 1, R[y] + 1);
		}
	// cerr << x << ' ' << L[x] << ' ' << R[x] << endl;
	return L[x] <= R[x];
}

void dfs3(int x, int fa)
{
	for(int i = 0; i < edg[x].size(); i++)
		if(edg[x][i] != fa)
		{
			int y = edg[x][i];
			if(!spe[y])
				val[y] = (val[x] + 1 <= R[y] ? val[x] + 1 : val[x] - 1);
			dfs3(y, x);
		}
}

