#include<iostream>
#include<cstdio>
using namespace std;
const int N=1e5+10;
const int inf=1e9;
int n;
struct edge{int to,Next;}ed[N<<1];
int edcnt,head[N];
void addedge(int u,int v){ed[++edcnt]=(edge){v,head[u]};head[u]=edcnt;}
bool vis[N];
int total,root,sz[N],mxson[N];
void dfsroot(int u,int Fa)
{
	sz[u]=1;mxson[u]=0;
	for(int i=head[u];i;i=ed[i].Next)
	if(!vis[ed[i].to]&&ed[i].to!=Fa)
	{
		int v=ed[i].to;dfsroot(v,u);
		sz[u]+=sz[v];mxson[u]=max(mxson[u],sz[v]);
	}
	mxson[u]=max(mxson[u],total-sz[u]);
	if(mxson[u]<mxson[root]) root=u;
}
bool Flag;
int le[N],ri[N],mark[N];
bool check(int a,int b,int len)
{
	if((mark[a]^mark[b])!=(len&1)) return false;
	if(le[a]>ri[b]+len||ri[a]<le[b]-len) return false;
	return true;
}
int present;
void recalc(int u,int Fa,int dep)
{
	sz[present]++;
	if(mark[u]!=-1)
	{
		if(mark[root]==-1)
		{
			le[root]=le[u]-dep;
			ri[root]=ri[u]+dep;
			mark[root]=(le[root]%2!=0);
		}
		else{
			if(!check(root,u,dep))
			{
				Flag=false;
				return;
			}
			le[root]=max(le[root],le[u]-dep);
			ri[root]=min(ri[root],ri[u]+dep);
		}
	}
	for(int i=head[u];i;i=ed[i].Next)
	if(!vis[ed[i].to]&&ed[i].to!=Fa) recalc(ed[i].to,u,dep+1);
}
void div(int u)
{
	vis[u]=true;
	for(int i=head[u];i;i=ed[i].Next)
	if(!vis[ed[i].to])
	{
		present=ed[i].to;
		sz[present]=0;
		recalc(present,u,1);
		if(!Flag) return;
	}
	for(int i=head[u];i;i=ed[i].Next)
	if(!vis[ed[i].to])
	{
		int v=ed[i].to;
		mark[v]=mark[u]^1;
		le[v]=le[u]+1;ri[v]=ri[u]+1;
	}
	for(int i=head[u];i;i=ed[i].Next)
	if(!vis[ed[i].to])
	{
		int v=ed[i].to;
		total=sz[v];root=0;
		dfsroot(v,0);div(root);
		if(!Flag) return;
	}
}
void redfscheck(int u,int Fa)
{
	int Left=-inf,Right=inf;
	for(int i=head[u];i;i=ed[i].Next)
	if(ed[i].to!=Fa)
	{
		int v=ed[i].to;redfscheck(v,u);
		if(!Flag) return;
		if(Left>ri[v]||Right<le[v])
		{
			Flag=false;
			return;
		}
		Left=max(Left,le[v]);
		Right=min(Right,ri[v]);
	}
	if(Left>ri[u]+1||Right<le[u]-1)
	{
		Flag=false;
		return;
	}
	le[u]=max(le[u],Left-1);
	ri[u]=min(ri[u],Right+1);
}
int ans[N];
void dfsans(int u,int Fa)
{
	for(int i=head[u];i;i=ed[i].Next)
	if(ed[i].to!=Fa)
	{
		int v=ed[i].to;
		if(ans[u]-1>=le[v]&&ans[u]-1<=ri[v]) ans[v]=ans[u]-1;
		else ans[v]=ans[u]+1;
		dfsans(v,u);
	}
}
int main()
{
	scanf("%d",&n);
	for(int i=1;i<n;i++)
	{
		int u,v;scanf("%d%d",&u,&v);
		addedge(u,v);addedge(v,u);
	}
	for(int i=1;i<=n;i++)
	{
		le[i]=-inf;ri[i]=inf;
		mark[i]=-1;
	}
	int K;scanf("%d",&K);
	for(int i=1;i<=K;i++)
	{
		int Id,Val;scanf("%d%d",&Id,&Val);
		le[Id]=ri[Id]=Val;mark[Id]=Val%2;
	}
	total=mxson[root=0]=n;
	dfsroot(1,0);
	Flag=true;div(root);
	if(Flag) redfscheck(1,0);
	if(!Flag) printf("No\n");
	else{
		printf("Yes\n");
		ans[1]=le[1];dfsans(1,0);
		for(int i=1;i<=n;i++) printf("%d\n",ans[i]);
	}
	return 0;
}

