const int N=100005;

int L[N],R[N],v[N],fst[N],tot,rt;
bool flag=1;
struct Edge{
	int to,nxt;
}e[N*2];

void addedge(int x,int y){
	e[++tot].to=y;e[tot].nxt=fst[x];fst[x]=tot;
}

void dfs(int x,int father){
	for (int i=fst[x];i && flag;i=e[i].nxt){
		int y=e[i].to;
		if (y!=father){
			dfs(y,x);
			L[x]=std::max(L[x],L[y]-1);
			R[x]=std::min(R[x],R[y]+1);
			if (L[x]>R[x]) flag=0;
		}
	}
}

void dfs2(int x,int father){
	if (L[x]>R[x]) return;
	v[x]=L[x];
	for (int i=fst[x];i && flag;i=e[i].nxt){
		int y=e[i].to;
		if (y!=father){
			L[y]=std::max(L[y],v[x]-1);
			R[y]=std::min(R[y],v[x]+1);
			dfs2(y,x);
		}
	}
}

