   Graph G(N);
   for(int i=0;i<N-1;i++){
      int a,b; cin>>a>>b;
      a--; b--;
      G[a].push_back(b);
      G[b].push_back(a);
   }
   int K; cin>>K;
   vector<int> num(N,-1);
   for(int i=0;i<K;i++){
      int v,p; cin>>v>>p;
      num[v-1]=p;
   }

   priority_queue<P,vector<P>,greater<P>> Q;
   vector<int> dist(N,INF);
   for(int i=0;i<N;i++) if(num[i]>=0){
      dist[i]=num[i];
