void solve(int x,int par=-1){
	l[x]=-inf;r[x]=inf;
	if(id[x]!=-1)l[x]=r[x]=id[x];
	for(int i=0;i<g[x].size();i++){
		if(g[x][i]==par)continue;
		solve(g[x][i],x);
		if(l[g[x][i]]<-inf/2)continue;
		if(l[x]<-inf/2){
			l[x]=l[g[x][i]]-1;
			r[x]=r[g[x][i]]+1;
		}
		else{
		if(id[x]!=-1&&id[g[x][i]]!=-1&&id[x]%2==id[g[x][i]]%2){
			ans=false;
			return;
		}
		l[x]=max(l[x],l[g[x][i]]-1);
		r[x]=min(r[x],r[g[x][i]]+1);
		}
	}
	if(l[x]>r[x])ans=false;
}
void make(int x,int par=-1){
	if(x==1&&id[x]==-1)id[x]=l[x];
	for(int i=0;i<g[x].size();i++){
		if(g[x][i]==par)continue;
