    pair<int,int> nx_val = {val.first-1, val.second+1};
    for(auto i : range(G[pos].size()) ){
      int nx = G[pos][i];
      if(nx == last || E[pos][i] == 0) continue;
      auto res_val = dfs_2(nx, pos, nx_val);
      val.first  = max(val.first, res_val.first);
      val.second = min(val.second, res_val.second);
    }

    if(val.first > val.second || (w[pos] != -1 && (val.first > w[pos] || val.second < w[pos])) ){
      ok = false;
      return pair<int,int>{-1, -1};
    }

    values[pos] = val;
    return pair<int,int>{val.first-1, val.second+1};
  };
  dfs_2(root, -1, {w[root], w[root]});

  function<pair<int,int>(int, int, pair<int,int>)> dfs_3 = [&](int pos, int last, pair<int,int> val) -> pair<int,int>{
    if( values[pos] != pair<int,int>{-1,-1} ){
      val = values[pos];
    }

    if(w[pos] != -1 && (val.first > w[pos] || val.second < w[pos]) ){
      ok = false;
      return {-1,-1};
    }

    pair<int,int> nx_val = {val.first-1, val.second+1};
    for(auto i : range(G[pos].size()) ){
      int nx = G[pos][i];
      if(nx == last) continue;
      auto res_val = dfs_3(nx, pos, nx_val);
      val.first  = max(val.first, res_val.first);
      val.second = min(val.second, res_val.second);
    }

    if(val.first > val.second || (w[pos] != -1 && (val.first > w[pos] || val.second < w[pos])) ){
      ok = false;
      return pair<int,int>{-1, -1};
    }

    w[pos] = val.first;
    return pair<int,int>{val.first-1, val.second+1};
  };
  dfs_3(root, -1, values[root]);

  for(auto i : range(n) ){
    for(auto j : G[i] ){
      if( abs(w[i]-w[j]) != 1 ){
        ok = false;
        break;
      }
    }
  }

  if(!ok){
    println("No");
    return 0;
  }else{
    println("Yes");
    println(join(w, "\n"));
  }

  return 0;
}

