int has[maxn];

bool flex[maxn];
int pari[maxn];

int lb[maxn], rb[maxn];

int ans[maxn];

int n, k;

bool solve(int u, int p)
{
	// printf("solving %d\n", u);
	for(int v : adj[u])
	{
		if(v == p) continue;
		if(!solve(v, u)) return false;
	}
	lb[u] = -1e9, rb[u] = 1e9;
	bool allflex = true;
	pari[u] = -1;
	for(int v : adj[u])
	{
		if(v == p) continue;
		if(flex[v]) continue;
		allflex = false;
		if(pari[v] != -1 && pari[u] == -1)
		{
			pari[u] = 1-pari[v];
		}
		else if(pari[v] != -1 && pari[u] == pari[v])  return false;
		lb[u] = max(lb[u], lb[v]-1);
		rb[u] = min(rb[u], rb[v]+1);
	}
	// printf("fin %d: [%d, %d] (%d)\n", u, lb[u], rb[u], pari[u]);
	if(lb[u]> rb[u]) return false;
	if(has[u])
	{
		if(!(lb[u]<= has[u] && has[u]<= rb[u])) return false;
		if(pari[u] != -1 && has[u]%2 != pari[u]) return false;
		lb[u] = rb[u] = has[u];
		return true;
	}
	if(allflex) flex[u] = true;
	return true;
}

void recon(int u, int p)
{
	if(p)
	{
		if(lb[u]<= ans[p]-1 && ans[p]-1<= rb[u]) ans[u] = ans[p]-1;
		else if(lb[u]<= ans[p]+1 && ans[p]+1<= rb[u]) ans[u] = ans[p]+1;
		else assert(false);
	}
	for(int v : adj[u])
	{
		if(v == p) continue;
		recon(v, u);
	}
}

