	for(int i = 1; i<= k; i++)
	{
		int v, p; scanf("%d %d", &v, &p);
		has[v] = p;
	}
	if(!solve(1, 0))
	{
		puts("No"); return 0;
	}
	ans[1] = lb[1];
	recon(1, 0);
	puts("Yes");
	for(int i = 1; i<= n; i++) printf("%d\n", ans[i]);
}

