int n,K;
int head[maxn],nxt[maxn*2],to[maxn*2],tot;
void add(int u,int v)
{
    tot++;
    nxt[tot]=head[u];
    head[u]=tot;
    to[tot]=v;
}
int book[maxn],val[maxn],L[maxn],R[maxn],rt;
void dfs(int x,int las,int op)
{
    if(las)
    {
        L[x]=max(L[x],L[las]-1);
        R[x]=min(R[x],R[las]+1);
    }
    if(book[x])
    {
        if(op!=((val[x]^val[rt])&1))
        {
            puts("No");
            exit(0);
        }
    }
    for(int i=head[x];i;i=nxt[i])
    {
        if(to[i]==las)  continue;
        dfs(to[i],x,op^1);
        L[x]=max(L[x],L[to[i]]-1);
        R[x]=min(R[x],R[to[i]]+1);
    }
    if(L[x]>R[x])
    {
        puts("No");
        exit(0);
    }
}
void solve(int x,int las)
{
    for(int i=head[x];i;i=nxt[i])
    {
        if(to[i]==las)  continue;
        if(val[x]-1>=L[to[i]]&&val[x]-1<=R[to[i]])  val[to[i]]=val[x]-1;
        else                                        val[to[i]]=val[x]+1;
        solve(to[i],x);
    }
}
