	}
	scanf("%d", &K);
	for(int i=1;i<=K;i++) {
		int V, P;
		scanf("%d%d", &V, &P);
		a[V].flag = true;
		a[V].lb = a[V].ub = a[V].key = P;
	}
	dfs(1, -1);
	if( !flag ) {
		puts("No");
		return 0;
	}
	else puts("Yes");
	dfs2(1, -1);
	for(int i=1;i<=N;i++)
		printf("%d\n", a[i].key);
}

