const int N = 100000 + 10;
const int oo = 0x3f3f3f3f;

int n, k;
int aa[N];
vector<int> g[N];
int dp[N][2], dep[N], root;

void no() {
	printf( "No\n" );
	exit(0);
}
void dfs( int u, int fa, int odd ) {
	if( aa[u] != oo ) {
		dp[u][0] = dep[u] - aa[u];
		dp[u][1] = dep[u] + aa[u];
		if( (aa[u] & 1) != odd ) no();
	} else {
		dp[u][0] = dp[u][1] = oo;
	}
	for( int t = 0; t < (int)g[u].size(); t++ ) {
		int v = g[u][t];
		if( v == fa ) continue;
		dep[v] = dep[u] + 1;
		dfs( v, u, odd ^ 1 );
		dp[u][0] = min( dp[u][0], dp[v][0] );
		dp[u][1] = min( dp[u][1], dp[v][1] );
		if( aa[u] != oo 
			&& (dp[u][0] < dep[u] - aa[u] || dp[u][1] < dep[u] + aa[u]) ) no();
	}
}
void dfs2( int u, int fa ) {
	for( int t = 0; t < (int)g[u].size(); t++ ) {
		int v = g[u][t];
		if( v == fa ) continue;
		if( aa[v] == oo ) {
			if( dp[u][0] < dp[u][1] ) {
				aa[v] = aa[u] + 1;
			} else {
				aa[v] = aa[u] - 1;
			}
		}
		dfs2( v, u );
	}
}
int main() {
	scanf( "%d", &n );
	for( int i = 1; i < n; i++ ) {
		int u, v;
		scanf( "%d%d", &u, &v );
		g[u].push_back( v );
		g[v].push_back( u );
	}
	scanf( "%d", &k );
	memset( aa, 0x3f, sizeof(aa) );
	for( int i = 1; i <= k; i++ ) {
		int v, p;
		scanf( "%d%d", &v, &p );
		aa[v] = p;
		if( i == 1 ) root = v;
	}
	for( int i = 1; i <= n; i++ ) {
		dp[i][0] = dp[i][1] = oo;
	}
	dep[root] = 1;
	dfs( root, root, aa[root] & 1 );
	dfs2( root, root );
	for( int u = 1; u <= n; u++ ) {
		for( int t = 0; t < (int)g[u].size(); t++ ) {
			int v = g[u][t];
			if( aa[u] - aa[v] > 1 || aa[u] - aa[v] < -1 ) no();
		}
	}
	printf( "Yes\n" );
	for( int u = 1; u <= n; u++ ) {
		printf( "%d\n", aa[u] );
	}
}

