  pr(a, b);
  if(a.first == INF) return b;
  if(b.first == INF) return a;
  auto res = P(max(a.first, b.first), min(a.second, b.second));
  if((a.first&1) != (b.first&1) || (a.second&1) != (b.second&1) || res.first > res.second){
    cout<<"No"<<endl;
    exit(0);
  }

  return res;
}

P dfs(Int pos, Int pre){
  if(pre != -1 && G[pos].size() == 1) return mem[pos] = P(V[pos], V[pos]);

  P res = P(V[pos], V[pos]);
  for(Int to:G[pos]){
    if(to == pre) continue;
    auto p = dfs(to, pos);
    if(p.first != INF) p.first--, p.second++;
    res = merge(res, p);
  }
  mem[pos] = res;
  return res;
}

vector<Int> ans;
void dfs2(Int pos, Int pre, Int v){
  ans[pos] = v;
  pr(pos, pre, v);
  //assert(mem[pos].first <= v && v <= mem[pos].second);
  for(Int to:G[pos]){
    if(to == pre) continue;
    if(mem[to].first <= v + 1 && v + 1 <= mem[to].second) dfs2(to, pos, v + 1);
    else dfs2(to, pos, v - 1);
  }
}

