int h[100005];

bool mergerange(range &a, range &b) {
	if (a.l > b.r+1 || a.r < b.l-1) return false;
	if (b.l > a.r+1 || b.r < a.l-1) return false;
	range na, nb;
	na = {max(a.l, b.l-1), min(a.r, b.r+1)};
	nb = {max(b.l, a.l-1), min(b.r, a.r+1)};
	a = na;
	b = nb;
	return true;
}

void dfs(int u) {
	vis[u] = 1;
	for (auto v : g[u]) {
		if (!vis[v]) {
			if (h[v] != -100001 && h[u] != -100001) {
				if (abs(h[v]-h[u]) != 1) ok = false;
			}
			ok &= mergerange(a[v], a[u]);
			dfs(v);
			ok &= mergerange(a[v], a[u]);
		}
	}
}

void getres(int u) {
	vis[u] = 1;
	for (auto v : g[u]) {
		if (!vis[v]) {
			if (h[u]+1 >= a[v].l && h[u]+1 <= a[v].r) {
				h[v] = h[u]+1;
			}
			else {
				h[v] = h[u]-1;
			}
			getres(v);
		}
	}
}

signed main() {
	scanf("%d", &n);
	int x, y;
	for (int i = 1; i < n; i++) {
		scanf("%d%d", &x, &y);
		g[x].push_back(y);
		g[y].push_back(x);
	}	
	for (int i = 1; i <= n; i++) {
		a[i] = {-INT_MAX, INT_MAX};
	}
	memset(vis, 0, sizeof(vis));
	scanf("%d", &k);
	for (int i = 1; i <= n; i++) {
		h[i] = -100001;
	}
	for (int i = 1; i <= k; i++) {
		scanf("%d%d", &x, &y);
		a[x] = {y, y};
		h[x] = y;
	}
	dfs(1);
	if (!ok) {
		cout << "No";
		return 0;
	}
	else {
		cout << "Yes\n";
		memset(vis, 0, sizeof(vis));
		for (int i = 1; i <= n; i++) {
			if (h[i] != -100001) {
				getres(i);
				break;
			}
		}
		for (int i = 1; i<= n; i++) {
			cout << h[i] << "\n";
		}
	}
}

