using namespace std;
ll odev[114514],mi[114514],ma[114514],deg[114514],used[114514];
vector<ll> pat[114514];
signed main(){
	ll n; cin>>n;
	vector<ll> a,b;
	for(ll i=0;i<n-1;i++){
		ll ta,tb;
		cin>>ta>>tb;
		a.pb(ta-1);b.pb(tb-1);
		pat[ta-1].pb(tb-1);pat[tb-1].pb(ta-1);
		deg[ta-1]++;
		deg[tb-1]++;
	}
	ll k; cin>>k;
	ll st=-1;
	for(ll i=0;i<n;i++){
		mi[i]=0;
		ma[i]=inf;
	}
	for(ll i=0;i<k;i++){
		ll tv,tp;
		cin>>tv>>tp;
		odev[tv-1] = 2-(tp)%2;
		st = tv-1;
		mi[tv-1]=tp;
		ma[tv-1]=tp;
	}
	queue<ll> que;
	que.push(st);
	while(!que.empty()){
		ll ci = que.front();que.pop();
		for(ll i=0;i<pat[ci].size();i++){
			ll cd = pat[ci][i];
			if( odev[cd] == 0){
				odev[cd] = 3-odev[ci];
				que.push(cd);
			}
			else if(odev[ci] + odev[cd] != 3){
				cout<<"No"<<endl;
				return 0;
			}
		}
	}
	queue<ll> q;
	for(ll i=0;i<n;i++){
		if(deg[i]==1){
			q.push(i);
		}
	}
	while(!q.empty()){
		ll ci = q.front(); q.pop();
		for(ll i=0;i<pat[ci].size();i++){
			ll cd = pat[ci][i];
			if( ma[ci]+1<mi[cd] || ma[cd]<mi[ci]-1){
				cout<<"No"<<endl;
				return 0;
			}
			mi[cd] = max(0LL, max(mi[cd],mi[ci]-1));
			ma[cd] = max(0LL, min(ma[cd],ma[ci]+1));
			if(deg[cd]>1){
				deg[cd]--;
				if(deg[cd]==1){
					que.push(cd);
				}
			}
		}
	}
	q.push(st);
	used[st]=1;
	while(!q.empty()){
		ll ci = q.front();q.pop();
		for(ll i=0;i<pat[ci].size();i++){
			ll cd=pat[ci][i];
			if(used[cd]==0){
				used[cd]=1;
				if( ma[ci]+1<mi[cd] || ma[cd]<mi[ci]-1){
					cout<<"No"<<endl;
					return 0;
				}
				mi[cd] = max(0LL,max(mi[cd],mi[ci]-1));
				ma[cd] = max(0LL,min(ma[cd],ma[ci]+1));
				q.push(cd);
			}
		}
	}
	vector<ll> ans;
	for(ll i=0;i<n;i++){
		bool fl = false;
		for(ll j=mi[i];j<=ma[i];j++){
			if(2-(abs(j))%2 == odev[i]){
				ans.pb(j);
				fl = true;
				j=ma[i]+1;
			}
		}
		if(fl == false){
			cout<<"No"<<endl;
			return 0;
		}
	}
	cout<<"Yes"<<endl;
	for(ll i=0;i<n;i++){
		cout<<ans[i]<<endl;
	}
	return 0;
}

