using namespace std;
typedef long long ll;
const int N = 110000;
const int MX = 1e9;

int to[N * 2], adj[N * 2], eh[N], tot;
int l[N], r[N], c[N];
int n, fl;

void addedge(int a, int b){
	to[++tot] = b;
	adj[tot] = eh[a];
	eh[a] = tot;
	to[++tot] = a;
	adj[tot] = eh[b];
	eh[b] = tot;
}

void dfs(int now, int pre){
	if (fl) return;
	int tl, tr;
	tl = MX;
	fore(p, now) if (to[p] != pre){
		dfs(to[p], now);
		if (l[to[p]] != MX){
			if (c[now] != -1){
				if ((c[now] % 2) == (l[to[p]] % 2) || c[now] < l[to[p]] - 1 || c[now] > r[to[p]] + 1){
					fl = 1;
					return;
				}
			}
			else{
				if (tl == MX){
					tl = l[to[p]] - 1;
					tr = r[to[p]] + 1;
				}
				else if ((tl % 2) == (l[to[p]] % 2)){
					fl = 1;
					return;
				}
				else{
					tl = max(tl, l[to[p]] - 1);
					tr = min(tr, r[to[p]] + 1);
					if (tr < tl){
						fl = 1;
						return;
					}
				}
			}
		}
	}
	if (c[now] == -1){
		l[now] = tl;
		r[now] = tr;
	}
	else{
		l[now] = r[now] = c[now];
	}
}

void dfs2(int now, int pre){
	if (c[now] == -1){
		if (l[now] == MX) c[now] = c[pre] + 1;
		else{
			if (pre == 0) c[now] = l[now];
			else if (c[pre] + 1 > r[now]) c[now] = c[pre] - 1;
			else c[now] = c[pre] + 1;
		}
		//printf("%d %d\n", now, c[now]);
	}
	fore(p, now) if (to[p] != pre) dfs2(to[p], now);
}

int main(){
	scanf("%d", &n);
	rep(i, 1, n - 1){
		int a, b;
		scanf("%d%d", &a, &b);
		addedge(a, b);
	}
	memset(c, -1, sizeof(c));
	int k;
	scanf("%d", &k);
	rep(i, 1, k){
		int v, p;
		scanf("%d%d", &v, &p);
		c[v] = p;
	}
	fl = 0;
	dfs(1, 0);
	if (fl){
		puts("No");
		return 0;
	}
	//rep(i, 1, n) printf("%d %d\n", l[i], r[i]);
	dfs2(1, 0);
	puts("Yes");
	rep(i, 1, n) printf("%d\n", c[i]);
	return 0;
}

