const int MAX_N = 100005;
const int MAX_P = 1000005;
const int INF = 2 * MAX_P;
int n, k;

struct Node {
	vector<int> adjs;
	int low = -INF; // close range [low, high]
	int high = INF;
};
Node nodes[MAX_N];

// return: 条件を満たせるか？
bool dfs(int rootI, int parentI) {
	auto& rootNode = nodes[rootI];
	for (int childI : rootNode.adjs) {
		if (childI == parentI) continue;
		bool childCond = dfs(childI, rootI);
		if (childCond == false) 
			return false;
		if (nodes[childI].low == -INF || nodes[childI].high == INF) continue;

		int newLow = nodes[childI].low - 1;
		int newHigh = nodes[childI].high + 1;
		if (rootNode.low == -INF && rootNode.high == INF) {
			rootNode.low = newLow; rootNode.high = newHigh;
		}
		else {
			bool ismod2 =
				((rootNode.low - newLow) % 2 == 0) &&
				((rootNode.high - newHigh) % 2 == 0);
			if (ismod2 == false) 
				return false;
			rootNode.low = max(rootNode.low, newLow);
			rootNode.high = min(rootNode.high, newHigh);
			if (rootNode.high < rootNode.low) 
				return false;
		}
	}

	return true;
}
void decideTree(int rootI, int parentI) {
	if (parentI == -1) {
		nodes[rootI].high = nodes[rootI].low;
	}
	else {
		int parentV = nodes[parentI].low;
		int l = parentV - 1;
		int h = parentV + 1;
		if (nodes[rootI].low <= l && l <= nodes[rootI].high) {
			nodes[rootI].low = nodes[rootI].high = l;
		}
		else {
			nodes[rootI].low = nodes[rootI].high = h;
		}
	}
	for (int childI : nodes[rootI].adjs) {
		if (childI == parentI) continue;
		decideTree(childI, rootI);
	}
}
