class Union_find{
private:
	vector<int> par;
	vector<int> rank;
	int n;

public:
	Union_find(int a){
		n = a;
		for(int i = 0;i < n;i++){
			par.push_back(i);
			rank.push_back(0);
		}
	}

	int find(int x){
		if(par[x] == x){
			return x;
		}else{
			return par[x] = find(par[x]);
		}
	}

	void unite(int x, int y){
		x = find(x);
		y = find(y);
		if(x == y) return;

		if(rank[x] < rank[y]){
			par[x] = y;
		}else{
			par[y] = x;
			if(rank[x] == rank[y]) rank[x]++;
		}
	}

	bool same(int x, int y){
		return find(x) == find(y);
	}
};

ll n, k;
vector<ll> e[1000000];
vector<ll> v(1000000, INF_LL);

bool dfs(int id, int bf){
	if(bf != -1 && v[id] != INF && abs(v[id] - v[bf]) != 1) return false;
	if(bf != -1 && e[id].size() == 1) return true;
	REP(i, e[id].size()){
		if(e[id][i] == bf) continue;
		if(v[e[id][i]] != INF){
			if(abs(v[id] - v[e[id][i]]) != 1) return false;
			if(dfs(e[id][i], id)) continue;
			return false;
		}else{
			v[e[id][i]] = v[id] + 1;
			if(dfs(e[id][i], id)) continue;
			v[e[id][i]] = v[id] - 1;
			if(dfs(e[id][i], id)) continue;
			return false;
		}
	}
	return true;
}

int main(void){
