	int a, b;
	REP(i, n-1){
		cin >> a >> b;
		e[a-1].push_back(b-1);
		e[b-1].push_back(a-1);
	}
	cin >> k;
	REP(i, k){
		cin >> a >> b;
		v[a-1] = b;
	}
	if(dfs(a-1, -1)){
		cout << "Yes" << endl;
		REP(i, n){
			cout << v[i] << endl;
		}
	}else{
		cout << "No" << endl;
	}
	return 0;
}

