inline int getint()
{
	int num=0,flag=1;char c;
	while((c=getchar())<'0'||c>'9')if(c=='-')flag=-1;
	while(c>='0'&&c<='9')num=num*10+c-48,c=getchar();
	return num*flag;
}

int n;
int fir[maxn],nxt[2*maxn],to[2*maxn],cnt;
int ans[maxn],l[maxn],r[maxn];

inline void newnode(int u,int v)
{to[++cnt]=v,nxt[cnt]=fir[u],fir[u]=cnt;}

inline bool check(int u,int fa,int st)
{
	if(ans[u]>-INF&&ans[u]%2!=st)return 1;
	for(int i=fir[u];i;i=nxt[i])
		if(to[i]!=fa)
			if(check(to[i],u,st^1))return 1;
	return 0;
}

inline bool dfs(int u,int fa)
{
	if(ans[u]>-INF)l[u]=r[u]=ans[u];
	for(int i=fir[u];i;i=nxt[i])
		if(to[i]!=fa)
		{
			if(dfs(to[i],u))return 1;
			l[u]=max(l[to[i]]-1,l[u]);
			r[u]=min(r[to[i]]-1,r[u]);
			if(l[u]>r[u])return 1;
		}
	return 0;
}

inline void color(int u,int fa)
{
	if(ans[u]<=-INF)ans[u]=r[u]=l[u];
	for(int i=fir[u];i;i=nxt[i])
		if(to[i]!=fa)
		{
			l[to[i]]=max(l[u]-1,l[to[i]]);
			r[to[i]]=min(r[u]+1,r[to[i]]);
			color(to[i],u);
		}
}

int main()
{
	memset(ans,-0x3f,sizeof ans);
	memset(l,-0x3f,sizeof l);
	memset(r,0x3f,sizeof r);
	n=getint();
	for(int i=1;i<n;i++)
	{
		int u=getint(),v=getint();
		newnode(u,v),newnode(v,u);
	}
