	while(t--)
	{
		x=getint();
		ans[x]=getint();
	}
	if(check(x,x,ans[x]%2)){puts("No");return 0;}
	if(dfs(1,1)){puts("No");return 0;}
	color(1,1);
	puts("Yes");
	for(int i=1;i<=n;i++)printf("%d\n",ans[i]);
}

