const int  maxn=200008;

int n,m,t; 
int b[maxn][3];
int p[maxn];
int a[maxn],l[maxn],r[maxn],sign[maxn];
void build(int x,int y)
{
  t++; b[t][0]=p[x]; p[x]=t; b[t][1]=y;
}
void dfs(int u,int fa)
{
   if (a[u]>=0)
     {
       l[u]=r[u]=a[u];
       sign[u]=a[u] % 2;
     }
   else 
     {
       l[u]=-1e8; r[u]=1e8;
       sign[u]=-1;
     }
   int t=p[u];
   while (t) 
   {
     int y=b[t][1];
     if (y!=fa) 
     {
       dfs(y,u);
       if (sign[y] != -1)
       {
         if (sign[u]==sign[y])
           {
             puts("No");
             exit(0);
           }
       sign[u]=sign[y] ^ 1;
       l[u]=max(l[u],l[y]-1);
       r[u]=min(r[u],r[y]+1);
       if (l[u]>r[u])
         {
           puts("No");
             exit(0);
         }
       }
     }
     t=b[t][0];
   }
}
void redfs(int x,int fa)
{
  if (sign[x]==-1) a[x]=a[fa]+1;
  else
  {
    if (fa)
      if (a[fa]+1>=l[x] && a[fa]+1<=r[x])
        a[x]=a[fa]+1;
       else
        a[x]=a[fa]-1;
    else
      a[x]=l[x];
  }
  int t=p[x];
  while (t)
    {
      int y=b[t][1];
      if (y!=fa) redfs(y,x);
      t=b[t][0];
    }

}
int main(){
  cin>>n;
  memset(p,0,sizeof(p));
  memset(a,-1,sizeof(a));
  t=0;
  int x,y;
  for (int i=1;i<=n-1;i++)
    {
      scanf("%d%d",&x,&y);
      build(x,y);
      build(y,x); 
    }
  cin>>m;
  int dis=1000006;
  for (int i=1;i<=n;i++)
    {
      l[i]=-dis;
      r[i]=dis;
    }

  for (int i=1;i<=m;i++)
    {
      scanf("%d%d",&x,&y);
      a[x]=y; 
    }

  dfs(1,0);
  redfs(1,0);
  puts("Yes");
  for (int i=1;i<=n;i++)
    printf("%d\n",a[i]);
  return 0;
}

