constexpr int IINF = INT_MAX;

vector<vector<int> > g;
vector<int> p, lo, up, ans;

void dfs(int v, int pre){
    if(p[v] >= 0){
        lo[v] = max(lo[v], p[v]);
        up[v] = min(up[v], p[v]);
    }
    for(auto u : g[v]){
        if(u==pre) continue;
        lo[u] = lo[v]-1;
        up[u] = up[v]+1;
        dfs(u,v);
        lo[v] = max(lo[v], lo[u]-1);
        up[v] = min(up[v], up[u]+1);
    }
}

bool bfs(int root){
    if(lo[root] > up[root]) return false;
    ans[root] = lo[root];
    vector<bool> visited(g.size(),false);
    queue<int> que;
    que.push(root);
    while(!que.empty()){
        int v = que.front();
        que.pop();
        visited[v] = true;
        for(auto u : g[v]){
            if(visited[u]) continue;
            if(lo[u] <= ans[v]-1 && up[u] >= ans[v]-1){
                ans[u] = ans[v]-1;
                que.push(u);
            }
            else if(lo[u] <= ans[v]+1 && up[u] >= ans[v]+1){
                ans[u] = ans[v]+1;
                que.push(u);
            }
            else{
                return false;
            }
        }
    }
    return true;
}

int main() {
    int n, k, root = -1;
    cin >> n;
    g.resize(n);
    lo.resize(n,-IINF/2);
    up.resize(n,IINF/2);
    ans.resize(n,-1);
    p.resize(n,-1);
    for(int i=0;i<n-1;i++){
        int a, b;
        cin >> a >> b;
        a--; b--;
        g[a].push_back(b);
        g[b].push_back(a);
    }
    cin >> k;
    for(int i=0;i<k;i++){
        int v;
        cin >> v;
        cin >> p[--v];
        root = v;
    }
    dfs(root, -1);
    if(bfs(root)){
        cout << "Yes" << endl;
        for(int i=0;i<n;i++){
            cout << ans[i] << endl;
        }
    }
    else{
        cout << "No" << endl;
    }

    return 0;
}

