class Tree {
public:
	int N, MAX_bit;
	vector<vector<int>> edge;
	vector<int> depth;
	vector<int> order;
	vector<vector<int>> parent;
	vector<vector<int>> child;
	vector<vector<int>> descendant;


	Tree(int N, int MAX_bit = 20) :N(N), MAX_bit(MAX_bit), edge(N), depth(N, -1), order(N, -1), parent(N, vector<int>(MAX_bit)), child(N), descendant(N){
		//do nothing
	}

	//O(1)
	void make_edge(int from, int to) {
		edge[from].push_back(to);
	}

	//O(N)
	void make_depth(int root) {
		queue<int> q;
		depth[root] = 0;
		q.push(root);
		while (q.size()) {
			int from = q.front();
			q.pop();
			for (auto to : edge[from]) {
				if (depth[to] != -1) continue;
				depth[to] = depth[from] + 1;
				q.push(to);
			}
		}
	}

	//O(NlogN)
	void make_order(){
		vector<pair<int,int>> tmp(N);
		for (int i = 0; i < N; ++i) tmp[i] = {depth[i],i};
		sort(tmp.begin(),tmp.end(),greater<>());
		for (int i = 0; i < N; ++i) order[i] = tmp[i].second;
	}

	//O(MAX_bit*N)
	void make_parent() {
		for (int i = 0; i < N; ++i) parent[i][0] = i;
		for (int i = 0; i < N; ++i) for (auto j : edge[i]) if (depth[i] > depth[j]) parent[i][0] = j;
		for (int bit = 1; bit < MAX_bit; ++bit) for (int i = 0; i < N; ++i) parent[i][bit] = parent[parent[i][bit - 1]][bit - 1];
	}

	//O(N)
	void make_child() {
		for (int i = 0; i < N; ++i) for (auto j : edge[i]) if (depth[i] < depth[j]) child[i].push_back(j);
	}

	//O(N^2)
	void make_descendant() {
		for (int i = 0; i < N; ++i) descendant[i].push_back(i);
		for (int i = 0; i < N; ++i) for (auto j : edge[order[i]]) if (depth[order[i]] < depth[j]) for(auto k: descendant[j]) descendant[order[i]].push_back(k);
	}

	//O(MAX_bit*logN) Lowest_Common_Ancestor
	int LCA(int l, int r) {
		if (depth[l] < depth[r]) swap(l, r);
		int diff = depth[l] - depth[r];
		for (int bit = 0; bit < MAX_bit; ++bit) if (diff & (1 << bit)) l = parent[l][bit];
		int ok = (1 << MAX_bit), ng = -1, md;
		while (ok - ng>1) {
			md = (ok + ng) / 2;
			int x = l, y = r;
			for (int bit = 0; bit < MAX_bit; ++bit) if (md & (1 << bit)) x = parent[x][bit];
			for (int bit = 0; bit < MAX_bit; ++bit) if (md & (1 << bit)) y = parent[y][bit];
			(x == y ? ok : ng) = md;
		}
		for (int bit = 0; bit < MAX_bit; ++bit) if (ok & (1 << bit)) l = parent[l][bit];
		return l;
	}

	void print() {
		cout << " depth { " << depth[0];
		for (int i = 1; i < N; ++i) cout << ", " << depth[i];
		cout << " }" << endl;

		cout << "parent { " << parent[0][0];
		for (int i = 1; i < N; ++i) cout << ", " << parent[i][0];
		cout << " }" << endl;

		cout << " child { " << child[0];
		for (int i = 1; i < N; ++i) cout << ", " << child[i];
		cout << " }" << endl;

		cout << "descen { " << descendant[0];
		for (int i = 1; i < N; ++i) cout << ", " << descendant[i];
		cout << " }" << endl;
	}

};
int main() {
	int N; cin >> N;
	Tree tree(N);
	for(int i = 0; i < N-1; ++i){
		int A,B; cin >> A >> B;
		A--,B--;
		tree.make_edge(A,B);
		tree.make_edge(B,A);
	}
	int K,root; cin >> K;
	V<int> val(N,-1000000);
	V<int> prt(N,-1);
	V<P<int,int>> rng(N,{0,0});

	for(int i = 0; i < K; ++i){
		cin >> root;
		root--;
		cin >> val[root];
		prt[root] = val[root]%2;
		rng[root] = {val[root],val[root]};
	}

	tree.make_depth(root);
	tree.make_order();
	tree.make_child();
	tree.make_parent();
	for(int i = N-1; 0 <= i; --i){
		int from = tree.order[i];
		for(auto to:tree.child[from]){
			if(val[to] == -1000000){
				rng[to].first = rng[from].first-1;
				rng[to].second = rng[from].second+1;
				prt[to] = !prt[from];
			}
			else{
				corner(prt[to] == prt[from],"No");
				corner(val[to]<rng[from].first||rng[from].second<val[to],"No");
			}
		}
	}

	for(int i = 0; i < N; ++i){
		int from = tree.order[i];
		for(auto to:tree.child[from]){
			chmax(rng[from].first,rng[to].first-1);
			chmin(rng[from].second,rng[to].second+1);
		}
		corner(rng[from].first>rng[from].second,"No");
	}

	for(int i = N-1; 0 <= i; --i){
		int from = tree.order[i];
		int x = val[from];
		for(auto to:tree.child[from]){
			if(val[to]!=-1000000){
				corner(val[to] < rng[to].first || rng[to].second < val[to], "No");
			}
			if(rng[to].first <= x + 1 && x + 1 <= rng[to].second){
				val[to] = x + 1;
				continue;
			}
			if(rng[to].first <= x - 1 && x - 1 <= rng[to].second){
				val[to] = x - 1;
				continue;
			}
			corner(1,"No");
		}
	}
	cout << "Yes" << endl;
	for(auto x:val) cout << x << endl;

	return 0;
}

