bool check;

void dfs(int node, int p) {
    int cnt[2] = {0, 0};
    if(value[node] != -1) {
        li[node] = ri[node] = value[node];
        defined[node] = true;
    }


    for(int i:g[node]) {
        if(i!=p) {
            dfs(i, node);

            if(defined[i]) {
                cnt[li[i]%2]++;
            }
        }
    }

    if(cnt[0] > 0 && cnt[1] > 0) {
        check = true;
        return;
    }

    if(value[node] == -1) {
        li[node] = INT_MIN;
        ri[node] = INT_MAX;
    }

    for(int i:g[node]) {
        if(i!=p) {
            if(defined[i]) {
                li[node] = max(li[node], li[i]-1);
                ri[node] = min(ri[node], ri[i]+1);
                defined[node] = true;
            }
        }
    }

    if(li[node] > ri[node]) {
        check = true;
        return;
    }
}

void dfs2(int node, int p) {

    if(value[node] == -1) {
        int x = value[p] - 1;
        if(x >= li[node] && x <= ri[node]) value[node] = x;

        x = value[p] + 1;
        if(x >= li[node] && x <= ri[node]) value[node] = x;


        if(value[node] == -1) {
            check = true;
            return;
        }
    }

    for(int i:g[node]) {
        if(i!=p) {
            dfs2(i, node);
        }
    }
}

