            L[v] = max(L[v], L[u] - 1);
            R[v] = min(R[v], R[u] + 1);
            dfs(v, u);
            L[u] = max(L[u], L[v] - 1);
            R[u] = min(R[u], R[v] + 1);
        }
    }
    if (L[u] > R[u]) {
