#include <bits/stdc++.h>

typedef std::pair <int, int> pr;
const int N = 100054, M = N * 2, INF = 0x3f3f3f3f;

int n, E = 0;
int to[M], first[N], next[M];
int d[N];
std::priority_queue <pr, std::vector <pr>, std::greater <pr> > pq;

inline void addedge(int u, int v) {
	to[++E] = v, next[E] = first[u], first[u] = E;
	to[++E] = u, next[E] = first[v], first[v] = E;
}

bool Dakstrij() {
	int i, x, y, D;
	for (; !pq.empty(); ) {
		std::tie(D, x) = pq.top(), pq.pop();
		if (d[x] != D) return false;
		for (i = first[x]; i; i = next[i])
			if (d[y = to[i]] >= INF)
				pq.emplace(d[y] = D + 1, y);
			else if (d[y] > D + 1) return false;
	}
}

int main() {
	int i, u, v, m; bool succ;
	scanf("%d", &n);
	for (i = 1; i < n; ++i) scanf("%d%d", &u, &v), addedge(u, v);
	memset(d, 63, sizeof d);
	for (scanf("%d", &m); m; --m) scanf("%d%d", &u, &v), pq.emplace(d[u] = v, u);
	succ = Dakstrij();
	for (i = 1; i <= E && succ; i += 2) succ &= abs(d[to[i]] - d[to[i + 1]]) == 1;
	puts(succ ? "Yes" : "No");
	for (i = 1; i <= n && succ; ++i) printf("%d\n", d[i]);
	return 0;
}

