pair<int, int> cros_rng(pair<int, int> r1, pair<int, int> r2) {
    int a = max(r1.first, r2.first);
    int b = min(r1.second, r2.second);
    return make_pair(a, b);
};

pair<int, int> dfs2(int v, pair<int, int> cur_rng) {
    usd[v] = true;
    rng[v] = cros_rng(cur_rng, rng[v]);
    if (rng[v].first > rng[v].second) {
        cout << "No" << endl;
        exit(0);
    }
    pair<int, int> next_rng;
    next_rng.first = cur_rng.first - 1;
    next_rng.second = cur_rng.second + 1;
    for (int i = 0; i < (int)lst[v].size(); ++i) {
        int u = lst[v][i];
        if (!usd[u]) {
            rng[v] = cros_rng(rng[v], dfs2(u, next_rng));
        }
    }
    if (rng[v].first > rng[v].second) {
        cout << "No" << endl;
        exit(0);
    }
    next_rng = {rng[v].first - 1, rng[v].second + 1};
    return next_rng;
}

void dfs3(int v, pair<int, int> cur_rng) {
    usd[v] = true;
    rng[v] = cros_rng(cur_rng, rng[v]);
    rng[v].second = rng[v].first;
    pair<int, int> next_rng;
    next_rng.first = cur_rng.first - 1;
    next_rng.second = cur_rng.second + 1;
    for (int i = 0; i < (int)lst[v].size(); ++i) {
        int u = lst[v][i];
        if (!usd[u])
            dfs3(u, next_rng);
    }
}

