void dfs(int now,int parent,auto &E){
	int l=-Inf,r=Inf;
	if(P[now]!=-1){
		l = P[now];
		r = l;
	}

	for(int i=0;i<E[now].size();i++){
		int to = E[now][i];
		if(parent==to)continue;
		dfs(to,now,E);
		if(range[to]!=make_pair(-Inf,Inf)){
			auto p = range[to];
			p.first--;
			p.second++;
			if(l==-Inf){
				l=p.first;
				r=p.second;
				continue;
			}
			if((p.first%2==0)!=(l%2==0))f=false;
			l = max(l,p.first);
			r = min(r,p.second);
		}
	}

	range[now] = make_pair(l,r);
	if(l>r)f=false;
}

void dfs2(int now,int parent,auto &E){
	P[now] = range[now].first;
	pair<int,int> p = make_pair(range[now].first-1,range[now].first+1);

	for(int i=0;i<E[now].size();i++){
		int to = E[now][i];
		if(parent==to)continue;
		if(range[to].first==-Inf){
			range[to].first=p.first;
			range[to].second=p.second;
		}
		else{
			range[to].first = max(range[to].first,p.first);
			range[to].second = min(range[to].second,p.second);
		}
		dfs2(to,now,E);
	}	
}

