}

void fill(int x){
  if (rng[x].f != -INF){
    for (auto i : adjList[x]){
      if (p[x] == i)continue;
      rng[i] = unionpair(rng[i], mp(rng[x].f - 1, rng[x].s +1));
    }
  }
  if (ans[x] == -INF){ans[x] = rng[x].f;}
  for (auto i : adjList[x]){
    if (p[x] == i)continue;
    rng[i] = unionpair(rng[i], mp(ans[x] - 1, ans[x] + 1));
    fill(i);
  }
}

