struct I {
	int l, r, o;
	I(int _l = 0, int _r = 0, int _o = -1): l(_l), r(_r), o(_o) {}
	I tr() { return I(l-1, r+1, o^1); }
	void comb(I a) {
		if (a.l == -1 && a.r == 1) return;
		if (o == -1) return l = a.l, r = a.r, o = a.o, void();
		l = max(l, a.l), r = min(r, a.r);
		if (l > r) FAIL;
	}
	int In(int x) { return l <= x && x <= r; }
}it[N];
