  while (cin >> N) {
    for (int i = 0; i < MAX; ++i) tree[i].clear(), P[i] = NON;
    for (int i = 0; i < N-1; ++i) {
      int a, b;
      scanf("%d %d", &a, &b);
      --a, --b;
      tree[a].push_back(b);
      tree[b].push_back(a);
    }
    cin >> K;
    for (int i = 0; i < K; ++i) {
      int v, p;
      scanf("%d %d", &v, &p);
      --v;
      P[v] = p;
    }
    bool can = dfs(0, -1);
    reconstruct(0, -1);

    if (can) {
      puts("Yes");
      for (int i = 0; i < N; ++i) cout << res[i] << endl;
    }
    else puts("No");
  }
}

