class Graph{
	private:
	int V,root;
	vvi List;
	vi rank,a,L,R;
	void Rank(){
		queue<P> q;
		q.push({root,0});
		rank[root]=0;
		while(!q.empty()){
			P p=q.front();
			q.pop();
			int u=p.first;
			for(int i=0;i<List[u].size();i++){
				int w=List[u][i];
				if(rank[w]==-1){
					rank[w]=p.second+1;
					q.push({w,p.second+1});
				}
			}
		}
	}
	void BFS(){
		vp b(V);
		for(int i=0;i<V;i++) b[i]={rank[i],i};
		sort(b.begin(),b.end(),[](P p,P q){
			return p.first>q.first;
		});
		for(int i=0;i<V;i++){
			int v=b[i].second,l=-inf,r=inf;
			for(int i=0;i<List[v].size();i++){
				int u=List[v][i];
				if(rank[v]<rank[u]){
					l=max(l,L[u]-1);
					r=min(r,R[u]+1);
				}
			}
			if(a[v]!=-1){
				l=max(l,a[v]);
				r=min(r,a[v]);
			}
			int eo=a[root]%2^rank[v]%2;
			if(l%2!=eo) l++;
			if(r%2!=eo) r--;
			L[v]=l;
			R[v]=r;
		}
	}
	bool bfs_f(int v,int x){
		if(R[v]<x||x<L[v]) return 1;
		a[v]=x;
		return 0;
	}
	bool bfs(){
		queue<int> q;
		q.push(root);
		if(bfs_f(root,a[root])) return 1;
		while(!q.empty()){
			int v=q.front();
			q.pop();
			for(int i=0;i<List[v].size();i++){
				int u=List[v][i];
				if(rank[v]<rank[u]){
					q.push(u);
					if(bfs_f(u,a[v]-1)&&bfs_f(u,a[v]+1)) return 1;
				}
			}
		}
		return 0;
	}
	public:
	Graph(int v){
		V=v;
		List=vvi(v);
	}
	void add_edge(int s,int t){
		List[s].push_back(t);
		List[t].push_back(s);
	}
