struct data
{
	int first,siz;
	inline data work()
	{
		data ret;
		ret.first=first-1;
		ret.siz=siz+1;
		return ret;
	}
	inline void merge(data x)
	{
		if (first==-1&&siz==-1) {first=x.first;siz=x.siz;return;}
		if (((x.first+2*n)%2)!=((first+2*n)%2)) {first=0;siz=0;return;}
		int min1=first,max1=first+(siz-1)*2,min2=x.first,max2=x.first+(x.siz-1)*2;
		int mn=max(min1,min2),mx=min(max1,max2);
		if (mn>mx) {first=0,siz=0;return;}
		first=mn;
		siz=(mx-mn)/2+1;
		return;
	}
	inline void Print()
	{
		write(first),putchar(' '),write(siz),putchar('\n');
