bool dfs(int c, int p, int oe) {

    if(v[c] != INT_MIN) {
        if(v[c]%2 != oe) {
            return 0;
        }
    }

    for(int u:g[c]) {
        if(u != p) {
            if(not dfs(u, c, oe^1)) return 0;
            llimit[c] = max(llimit[u]-1, llimit[c]);
            ulimit[c] = min(ulimit[u]+1, ulimit[c]);
        }
    }

    if(v[c] != INT_MIN) {
        llimit[c] = max(v[c], llimit[c]);
        ulimit[c] = min(v[c], ulimit[c]);
    }

    if(llimit[c] > ulimit[c]) return 0;
    return 1;
}

bool dfs2(int c, int p, int lv, int uv) {
    llimit[c] = max(lv, llimit[c]);
    ulimit[c] = min(uv, ulimit[c]);

    if(llimit[c] > ulimit[c]) return 0;
    v[c] = ulimit[c];

    for(int u:g[c]) {
        if(u != p) {
            if(not dfs2(u, c, ulimit[c]-1, ulimit[c]+1)) return 0;
        }
    }

    return 1;
}

