            if (odds[c] == 1 && maxi[c] % 2 == 0)
                maxi[c]--;
            else if (odds[c] == -1 && maxi[c] % 2 == 1)
                maxi[c]--;
            if (odds[c] == 1 && mini[c] % 2 == 0)
