			int ll = l[go[i]] - 1, rr = r[go[i]] + 1;
			if (R < ll || L > rr) ok = 1;
			L = max(L, ll);
			R = min(R, rr);
			if (R < L) ok = 1;
		}
	l[now] = L; r[now] = R;
}
