const int MAXN=102018;
int N,k,root,u,v,val[MAXN],eoro[MAXN];
bool vis[MAXN],ol[MAXN];
vector<int> G[MAXN];
vector<int> C[MAXN];

bool build_tree(int p)
{
	vis[p]=1;
	for(unsigned int i=0;i<G[p].size();i++)
	{
		int t=G[p][i];
		if(!vis[t])
		{
			C[p].push_back(t);
			if(eoro[t]!=-1 && eoro[t]==eoro[p]) return 1;
			eoro[t]=(eoro[p]+1)%2;
			bool o=build_tree(t);
			if(o) return 1;
		}
	}
	return 0;
}


bool ed;
void draw(int p)
{
	if(ed) return;
	if(C[p].size()==0)
	{
		bool cnt=0;
		for(int i=1;i<=N && !cnt;i++)
			if(val[i]==-1) cnt=1;

		if(!cnt)
		{
			for(int i=1;i<=N;i++)
				printf("%d\n",val[i]);
			ed=1;
		}
		return ;
	}
	for(unsigned int i=0;i<C[p].size() && !ed;i++)
	{
		int t=C[p][i];
		if(ol[t]) 
		{ 
			if(val[t]-val[p]>1 || val[p]-val[t]>1)
			{
				if(ol[p]) ed=1,puts("No");
				return ;
			}
			else draw(t);
			continue;
		}
		val[t]=val[p]+1,draw(t);
		if(val[t]>=1) val[t]=val[p]-1,draw(t);
	}
	if(ed) return ;
}

