int n,k,a[100005],l[100005],r[100005],d[100005]={0};
int even[100005];//0 undetermined 1 even 2 odd
vector<int> v[100005];

bool tree1(int t)
{
	rep_(i,v[t],vector<int>)
		if (d[*i]==0)
		{
			d[*i]=d[t]+1;
			if (!tree1(*i)) return false;
			l[t]=max(l[t],l[*i]-1);
			r[t]=min(r[t],r[*i]+1);
			if (even[*i]!=0)
			{
				if (even[*i]==even[t]) return false;
				else even[t]=3-even[*i];
			}
			if (l[t]>r[t]) return false;
		}
	return true;
}

bool tree2(int t)
{
	rep_(i,v[t],vector<int>)
		if (d[*i]==d[t]+1)
			l[*i]=max(l[*i],l[t]-1),tree2(*i);
}

