		if(!ff[x]){
			L[x] = L[y] - 1;
			R[x] = R[y] + 1;
			ff[x] = true;
		}else{
			if((bool)(L[x] % 2) != (bool)((L[y]-1) % 2)){
				puts("No");
				exit(0);
			}
			L[x] = max(L[x], L[y]-1);
			R[x] = min(R[x], R[y]+1);
			if(L[x] > R[x]){
				puts("No");
				exit(0);
			}
		}
	}
	if(g[x]){
		if(ff[x] && !(L[x] <= f[x] && f[x] <= R[x] && bool(f[x] % 2) == bool(L[x]%2))){
			puts("No");
			exit(0);
		}
		L[x] = R[x] = f[x];
		ff[x] = true;
	}
}
void dfs2(int x,int fat){
	f[x] = L[x];
	R[x] = L[x];
	for(vector<int>::iterator it = e[x].begin(); it != e[x].end(); it++){
		int y = *it;
		if(y == fat)continue;
		if(!ff[y]){
			L[y] = L[x] - 1;
			R[y] = R[x] + 1;
			ff[y] = true;
		}else{
			L[y] = max(L[y], L[x] - 1);
			R[y] = min(R[y], R[x] + 1);
		}
		dfs2(y,x);
	}
}
