		vec[a].push_back(b);
		vec[b].push_back(a);
	}
	memset(id,-1,sizeof(id));
	int Q;
	scanf("%d",&Q);
	while(Q--)
	{
		int v,p;
		scanf("%d %d",&v,&p);v--;
		id[v]=p;
	}
	ans=true;
	solve();
	if(!ans)
	{
		puts("No");
	}
	else
	{
		make();
		puts("Yes");
		for(int i=0;i<n;i++) printf("%d\n",id[i]);
	}
	return 0;
}

