    for (auto v : E[u]){
        if (v == fa) continue;
        dfs2(v , u);
        if (r[v] == inf) continue;
        l[u] = max (l[u] , l[v] - 1);
        r[u] = min (r[u] , r[v] + 1);
    }
    if (l[u] > r[u]) ok = false;
}
