bool OK = true;
pair<int, int> sagasu(int A, int pre) {
	bool OE[2] = {};
	if (PM[A] < 1e6) OE[PM[A] & 1] = 1;
	for (int i = H[A]; i; i = ne[i]) {
		if (to[i] != pre) {
			auto p = sagasu(to[i], A);
			if (p.first < 1e6) OE[p.first & 1] = 1;
			PM[A] = min(PM[A], p.first);
			Pm[A] = max(Pm[A], p.second);
		}
	}
	if (OE[0] && OE[1]) OK = false;
	if (PM[A] < Pm[A]) OK = false;
	return mp(PM[A] + 1, Pm[A] - 1);
}
void sagasu2(int A, int M, int prev) {
	if (M + 1 <= PM[A]) PM[A] = M + 1;
	else PM[A] = M - 1;
	for (int i = H[A]; i; i = ne[i]) {
		if (to[i] != prev) sagasu2(to[i], PM[A], A);
	}
}

