		cin>>a>>b;
		known[a]=1;
		val[a]=b;
	}
	dfs(1);
	if(shit)
	{
		cout<<"No"<<endl;
		return 0;
	}
	reverse(order.begin(),order.end());
	cout<<"Yes"<<endl;
	for(int i=0;i<order.size();i++)
	{
		int v=order[i];
		ans[v]=solve_val(v,par[v]);
