typedef int Weight;
struct Edge{
    int from, to;
    Weight weight;
    int rev;     // ネットワークフロー時の逆辺
    Edge(int from, int to, Weight weight) :
        from(from), to(to), weight(weight) { }
    Edge(int from, int to, Weight weight, int rev) :
        from(from), to(to), weight(weight), rev(rev){ }
};
bool operator < (const Edge &a, const Edge &b){
    if(a.weight != b.weight) return a.weight > b.weight;
    if(a.from != b.from) return a.from > b.from;
    return  a.to > b.to;
}
typedef vector<Edge> Edges;
typedef vector<Edges> Graph;

typedef vector<Weight> Array;
typedef vector<Array> Matrix;

void addFlowEdge(Graph &g, int a, int b, Weight c){
    g[a].push_back(Edge(a, b, c, g[b].size()));
    g[b].push_back(Edge(b, a, 0, g[a].size() - 1));
}
void addUndirectedEdge(Graph &g, int a, int b, Weight c){
    g[a].push_back(Edge(a, b, c, g[b].size()));
    g[b].push_back(Edge(b, a, c, g[a].size() - 1));
}

bool dfs(const Graph &g, int v, int u, vector<vector<int>> &Q, vector<bool> &B) {
	int any = 0;
	map<int,int> mp;
	for(const Edge e: g[v]) {
		if(e.to == u) continue;
		if(!dfs(g, e.to, v, Q, B)) {
			return false;
		}
		if(B[e.to]) {
			++any;
		} else {
			for(int t: Q[e.to]) {
				mp[t+1]++;
				mp[t-1]++;
			}
		}
	}
	if(Q[v].size() > 0) {
		return mp[Q[v][0]] + any == g[v].size() - 1;
	} else if(any == g[v].size() - 1) {
		B[v] = true;
		return true;
	} else {
		for(pair<int,int> p: mp) {
			if(p.second + any == g[v].size() - 1) {
				Q[v].push_back(p.first);
			}
		}
		return Q[v].size() > 0;
	}
}

void color(const Graph &g, int v, int u, vector<int> &C, const vector<vector<int>> &Q, const vector<bool> &B) {
	for(Edge e: g[v]) {
		if(e.to == u) continue;
		if(B[e.to]) {
			C[e.to] = C[v] + 1;
		} else {
			for(int t: Q[e.to]) {
				if(abs(t - C[v]) == 1) {
					C[e.to] = t;
					break;
				}
			}
		}
		color(g, e.to, v, C, Q, B);
	}
}

