void dfs1(int x, int n) {
    if (decided[n] && ans[n] % 2 != x) no();
    visited1[n] = true;
    odd[n] = x;
    for (int i = 0; i < G[n].size(); i++) {
        if (visited1[G[n][i]]) continue;
        dfs1((x + 1) % 2, G[n][i]);
    }
}

P dfs2(int n) {
    visited2[n] = true;
    if (decided[n]) return seg[n] = P(ans[n], ans[n]);
    int l = -1e9, r = 1e9;
    for (int i = 0; i < G[n].size(); i++) {
        if (visited2[G[n][i]]) continue;
        P p = dfs2(G[n][i]);
        l = max(l, p.first);
        r = min(r, p.second);
    }
    l--; r++;
    if (abs(l) % 2 != odd[n]) l++;
    if (abs(r) % 2 != odd[n]) r--;
    if (l > r) no();
    return seg[n] = P(l, r);
}

void dfs3(int x, int n) {
    visited3[n] = true;
    decided[n] = true;
    ans[n] = seg[n].first <= x - 1 ? x - 1 : x + 1;
    for (int i = 0; i < G[n].size(); i++) {
        if (visited3[G[n][i]]) continue;
        dfs3(ans[n], G[n][i]);
    }
}

