int main() {
  int N, K;
  cin >> N;
  UnWeightedGraph g(N);
  for(int i = 1; i < N; i++) {
    int x, y;
    cin >> x >> y;
    --x, --y;
    g[x].emplace_back(y);
    g[y].emplace_back(x);
  }
  cin >> K;
  vector< int > A(N, inf);
  priority_queue< pair< int, int > > que;
  for(int i = 0; i < K; i++) {
    int v, k;
    cin >> v >> k;
    --v;
    A[v] = k;
    que.emplace(k, v);
  }
  while(que.size()) {
    auto p = que.top();
    que.pop();
    for(auto to : g[p.second]) {
      if(A[to] == inf) {
        A[to] = A[p.second] - 1;
        que.emplace(A[to], to);
      } else if(abs(A[to] - A[p.second]) != 1) {
        cout << "No" << endl;
        return 0;
      }
    }
  }
  cout << "Yes" << endl;
  for(auto &p : A) cout << p << endl;

}

