const int inf = -10E8;
int n;
int sets[100001];
bool visit[100001];
vector< vector<int> > st(100001);
bool dfs(int index)
{
    visit[index] = true;
    for(int i = 0; i < st[index].size(); ++i)
    {
        if(sets[st[index][i]] != inf && sets[st[index][i]] != sets[index] - 1 && sets[st[index][i]] != sets[index] + 1)
            return false;
    }
    bool f = false;
    for(int i = 1; i < n; ++i)
    {
        if(!visit[i])
        {
            f = true;
            break;
        }
    }
    if(f)
    {
        for(int i = 0; i < st[index].size(); ++i)
        {
            if(sets[st[index][i]] == inf && !visit[st[index][i]])
            {
                sets[st[index][i]] = sets[index] + 1;
                visit[st[index][i]] = true;
                if(dfs(st[index][i]))
                return true;
                sets[st[index][i]] = inf;
                visit[st[index][i]] = false;
                sets[st[index][i]] = sets[index] - 1;
                visit[st[index][i]] = true;
                if(dfs(st[index][i]))
                return true;
                sets[st[index][i]] = inf;
                visit[st[index][i]] = false;
            }
        }
    }
    else
        return true;
}
