int dp[100010];

void rec(int node,ll low,ll high){
    //printf("%d %d %d\n",node,low,high);
    dp[node] = 1;
    if (wrotevertex[node]){
        if (vertexnum[node] < low || high < vertexnum[node]){
            noresult();
        }
        // has value
        low = high = vertexnum[node];
    }else{
        low--;
        high++;
    }
    for (int idx:vertex[node]){
        if (dp[idx]==0){
            rec(idx,low,high); // suggest[node][_]が書き換わる
            low  = max(low ,suggest[idx][0]-1);
            high = min(high,suggest[idx][1]+1);
            //printf("%d %d %d %d %d\n",idx,low,high,node,0);
            if (high<low){
                noresult();
            }
        }
    }
    suggest[node][0]=low;
    suggest[node][1]=high;

}


