pair<int, int> getInterval(const pair<int, int> &a, const pair<int, int> &b) {
	return make_pair(max(a.first, b.first), min(a.second, b.second));
}

bool isOdd(int x) {
	return (abs(x) & 1);
}

bool dfs2(int u, int fa) {
	if (fa) {
		pair<int, int> nv = getInterval(val[u], make_pair(val[fa].first - 1, val[fa].second + 1));
		if (nv.first > nv.second || isOdd(nv.first) != isOdd(val[u].first)) return false;
		val[u] = nv;
	}
	if (~p[u]) {
		pair<int, int> nv = getInterval(make_pair(p[u], p[u]), val[u]);
		if (nv.second < nv.first || isOdd(p[u]) != isOdd(val[u].first)) return false;
		val[u] = nv;
	}
	for (int v: edge[u]) {
		if (v == fa) continue;
		if (!dfs2(v, u)) return false;
	}
