bool dfs(int u, int fa) {
	if (fa) {
		val[u] = make_pair(val[fa].first - 1, val[fa].second + 1);
	}
	if (~p[u]) {
		pair<int, int> nv = getInterval(make_pair(p[u], p[u]), val[u]);
		if (nv.second < nv.first || isOdd(p[u]) != isOdd(val[u].first)) return false;
		val[u] = nv;
	}
	for (int v: edge[u]) {
		if (v == fa) continue;
		if (!dfs(v, u)) return false;;
		pair<int, int> nv = getInterval(make_pair(val[v].first - 1, val[v].second + 1), val[u]);
		if (nv.second < nv.first || isOdd(val[u].first) == isOdd(val[v].first)) return false;
		val[u] = nv;
	}

	for (int v: edge[u]) {
		if (v == fa) continue;
		if (!dfs2(v, u)) return false;
	}

	ans[u] = val[u].first;
