vector <int> adj[MAXN];

int L[MAXN], R[MAXN];

int ans[MAXN];

int n, k;

void bye() {
    printf("No\n");
    exit(0);
}

void dfs(int v, int pr) {
    for (int to : adj[v]) {
        if (to == pr) {
            continue;
        }

        dfs(to, v);

        L[v] = max(L[v], L[to] - 1);
        R[v] = min(R[v], R[to] + 1);
    }
}

void dfs2(int v, int pr) {
    for (int to : adj[v]) {
        if (to == pr) {
            continue;
        }

        L[to] = max(L[to], L[v] - 1);
        R[to] = min(R[to], R[v] + 1);

        dfs2(to, v);
    }
}

void rec(int v, int pr) {
    if (L[v] > R[v]) {
        bye();
    }

    for (int to : adj[v]) {
        if (to == pr) {
            continue;
        }

        if (ans[to] == -INF) {
            if (L[to] <= ans[v] - 1 && ans[v] - 1 <= R[to]) {
                ans[to] = ans[v] - 1;
            }
            else {
                ans[to] = ans[v] + 1;
            }
        }

        if (abs(ans[v] - ans[to]) != 1) {
            bye();
        }

        rec(to, v);
    }
}

void solve() {
    scanf("%d", &n);

    for (int i = 1, l, r; i < n; ++i) {
        scanf("%d %d", &l, &r);

        adj[l].pb(r);
        adj[r].pb(l);
    }

    for (int i = 1; i <= n; ++i) {
        ans[i] = -INF;
        L[i] = -INF;
        R[i] = INF;
    }

    int root = 1;

    scanf("%d", &k);

    for (int i = 1, ps, x; i <= k; ++i) {
        scanf("%d %d", &ps, &x);
        L[ps] = R[ps] = ans[ps] = x;
        root = ps;
    }

    dfs(root, -1);
    dfs2(root, -1);
    rec(root, -1);

    printf("Yes\n");

    for (int i = 1; i <= n; ++i) {
        printf("%d\n", ans[i]);
    }
}

