    g[--a].push_back(--b);
    g[b].push_back(a);
  }
  cin >> k;
  for (int i = 0; i < k; ++i) {
    int node, p;
    cin >> node >> p;
    --node;
    l[node] = r[node] = res[node] = p;
    root = node;
  }
  if (solve()) {
    cout << "Yes" << endl;
    for (auto &p : res) cout << p << endl;
  } else
    cout << "No" << endl;
