typedef pair<int,int>pi;

const int N=100005,inf=0x3f3f3f3f;

int n,m,col[N],t[N],a[N],num[N];
vector<int>e[N];
pi f[N];

void build(int x,int fa){
	num[x]=col[x]!=inf;f[x]={-inf,inf};
	for(int v:e[x])if(v!=fa)build(v,x),num[x]+=num[v];
}

inline bool ok(int x,int y){
	if(!num[x])return true;return y>=f[x].fi&&y<=f[x].se&&(y&1)==(f[x].fi&1);
}

void dfs(int x,int fa){
	if(!num[x])return;
	int cur=0;
	for(int v:e[x])if(v!=fa&&num[v]){
		dfs(v,x);
		if(cur){
			int fb=~f[x].fi&1;
			if((f[v].fi&1)!=fb)puts("No"),exit(0);
			f[x].fi=max(f[x].fi,f[v].fi-1);
			f[x].se=min(f[x].se,f[v].se+1);
			if((f[x].fi&1)==fb)f[x].fi++;
			if((f[x].se&1)==fb)f[x].se--;
			if(f[x].fi>f[x].se)puts("No"),exit(0);
		}else f[x]={f[v].fi-1,f[v].se+1};
		cur+=num[v];
	}
	if(col[x]!=inf){
		if(cur&&!ok(x,col[x]))puts("No"),exit(0);
		f[x]={col[x],col[x]};
	}
}

void check(int x,int fa,int r){
	a[x]=r;
	for(int v:e[x])if(v!=fa){
		if(ok(v,r-1))check(v,x,r-1);else check(v,x,r+1);
	}
}

