	memset(col,0x3f,(n+1)<<2);
	for(int i=1,p;i<=m;i++)scanf("%d",&p),scanf("%d",&col[p]);
	build(1,0);
	dfs(1,0);
	puts("Yes");
	check(1,0,f[1].fi);
	for(int i=1;i<=n;i++)printf("%d\n",a[i]);
	return 0;
}

