pair<bool,pll> dfs(ll where,ll parent,pll lmt,bool F){
    if(de[where].F){
        if(de[where].S%2!=F?1:0){return {false,{0,0}};}
        if(lmt.F<de[where].S || lmt.S>de[where].S){return {false,{0,0}};}
        lmt={de[where].S,de[where].S};
    }
    for(int i=0;i<e[where].size();i++){
        ll to=e[where][i];
        if(to==parent){continue;}
        pair<bool,pll> ret=dfs(to,where,{lmt.F+1,lmt.S-1},!F);
        lmt.F=min(lmt.F,ret.S.F);
        lmt.S=max(lmt.S,ret.S.S);
        if(lmt.F<lmt.S || !ret.F){return {false,{0,0}};}
    }
    v[where].F=lmt.F; v[where].S=lmt.S;
    lmt.F++; lmt.S--;
    return {true,lmt};
}




