int ll[maxn],rr[maxn];

bool dfs(int u,int fa,int sg){
	ll[u]=-INF;
	rr[u]=INF;
	if(mark[u]){
		if(sg!=(val[u]&1)){
			return 0;
		}
	}
	for(int i=0;i<(int)G[u].size();i++){
		int v=G[u][i];
		if(v==fa)
			continue;
		if(!dfs(v,u,sg^1))
			return 0;
		ll[u]=max(ll[u],ll[v]-1);
		rr[u]=min(rr[u],rr[v]+1);
	}
	if(mark[u]){
		ll[u]=max(ll[u],val[u]);
		rr[u]=min(rr[u],val[u]);
	}
	if(ll[u]>rr[u])
		return 0;
	return 1;
}

bool setcolor(int u,int fa,int L,int R){
	L=max(L,ll[u]);
	R=min(R,rr[u]);
	if(L>R)
		return 0;
	val[u]=L;
	for(int i=0;i<(int)G[u].size();i++){
		int v=G[u][i];
		if(v==fa)
			continue;
		if(!setcolor(v,u,L-1,L+1))
			return 0;
	}
	return 1;
}

