unordered_set<int> ms(unordered_set<int> a, unordered_set<int> b) {
    unordered_set<int> temp;
    for (int i : b) {
        temp.emplace(i + 1);
        temp.emplace(i - 1);
    }
    if (a.empty()) return temp;
    if (a.size() < temp.size()) swap(a, temp);
    unordered_set<int> g;
    for (int i : temp) if (a.find(i) != a.end()) g.emplace(i);
    return g;
}
