pair<int, int> dfs(int v, int par) {
    if(g[v].size() == 1 && g[v][0] == par) {
        if(p[v] == -inf) {
            constraints[v] = {-inf, inf};
            return P{-inf, inf};
        } else {
            constraints[v] = {p[v], p[v]};
            return P{p[v], p[v]};
        }
    }
    int mx = inf, mi = -inf;
    if(p[v] != -inf) {
        mx = p[v], mi = p[v];
    }
    for(auto nv: g[v]) {
        if(nv == par) continue;
        P cst = dfs(nv, v);
        chmin(mx, cst.sc + 1);
        chmax(mi, cst.fr - 1);
    }
    if(mx < mi) {
        cout << "No" << endl;
        exit(0);
    }
    return constraints[v] = {mi, mx};
}

