ll Pow(ll a, ll b, ll md, ll ans = 1) {
    for (; b; b >>= 1, a = a * a % md)
        if (b & 1)
            ans = ans * a % md;
    return ans % md;
}

const ll MAXN = 1e6 + 10;
const ll INF = 8e18;
const ll MOD = 1e9 + 7;
vector<ll> adj[MAXN];
ll mark[MAXN], val[MAXN], ans[MAXN], mrk[MAXN], n, k;

void BFS() {
    priority_queue<pll> pq;
    for (ll i = 1; i <= n; i++) {
        if (mrk[i]) pq.push({val[i], i}), ans[i] = val[i];
    }
    while (sz(pq)) {
        ll v = pq.top().S; pq.pop();
        if (mark[v]) continue;
        mark[v] = 1;
        for (ll u : adj[v]) {
            if (mark[u]) continue;
            ans[u] = ans[v] - 1;
            pq.push({ans[u], u});
        }
    }
}

