const int N = 1e5 + 10;
const int M = 2e5 + 10;
int las[N], nex[M], to[M], sz, val[N], n, K, fa[N], ans[N];
bool visit[N];
struct node {
    int l, r;
    bool all;
    bool empty;
    //bool flag;// contain l & r;
} rem[N], tmp[N];
void add(int x, int y) {
    to[++sz] = y; nex[sz] = las[x]; las[x] = sz;
}
bool dfs(int now) {
    int cnt = 0, flag = 0;
    for (int i = las[now]; i; i = nex[i])
    if(!visit[to[i]]) {
        //printf("%d %d\n", now, to[i]);
        visit[to[i]] = true;
        if(!dfs(to[i])) {
            rem[now].empty = true;
            return false;
        }

    }
    else fa[now] = to[i];
    for (int  i = las[now]; i; i = nex[i])
    if(to[i] != fa[now]) {
        //printf("%d %d\n", now, to[i]);
        tmp[++cnt] = rem[to[i]];
       //printf("???? %d %d\n", tmp[cnt].l, tmp[cnt].r);
        tmp[cnt].l -= 1;
        tmp[cnt].r += 1;
        //printf("??? %d %d\n",tmp[cnt].l, tmp[cnt].r);
    }
    //for (int i = 1; i <= cnt; i++) 
        //printf("QAQ for now = %d %d %d\n",now, tmp[i].l, tmp[i].r);
    if(!rem[now].all)
    {
        tmp[++cnt] = rem[now];
    }
    //for (int i = 1; i <= cnt; i++) 
        //printf("laalala for now = %d %d %d\n",now, tmp[i].l, tmp[i].r);
    flag = (tmp[1].l & 1);
    for (int i = 1; i <= cnt; i++) {
        if(tmp[i].all) break;
        //else if(tmp[i].empty) flag = -1;
        else if(tmp[i].l & 1 != flag) flag = -1;
    }
    if(flag == -1) return false; 
    //sort(tmp + 1, tmp + cnt + 1, cmp);
    int maxl = -(1e9), minr = 1e9;
    for (int i = 1; i <= cnt; i++) {
        //printf("for now = %d %d %d\n",now, tmp[i].l, tmp[i].r);
        if(tmp[i].l > maxl) maxl = tmp[i].l;
        if(tmp[i].r < minr) minr = tmp[i].r;
    }
    if(maxl > minr) return false;
    rem[now].l = maxl;
    rem[now].r = minr;
    //printf("node = %d %d %d\n",now,  maxl, minr);
    return true;
}
void calc(int now) {
    visit[now] = true;
    int L = max(ans[fa[now]] - 1, rem[now].l);
    int R = min(ans[fa[now]] + 1, rem[now].r);
    ans[now] = L;
    for (int i = las[now]; i; i = nex[i])
    if(!visit[to[i]]) {
        calc(to[i]);
    }
}
int main()
{
    scanf("%d", &n);
    for (int i = 1, x, y; i < n; i++) {
        scanf("%d%d", &x, &y);
        add(x, y);
        add(y, x);
    }
    memset(val, -1, sizeof(val));
    for (int i = 1; i <= n; i++) {
        rem[i].l = -1e9;
        rem[i].r = 1e9;
        rem[i].empty = false;
        rem[i].all = true;
    }
    scanf("%d", &K);
    for (int i = 1, x; i <= K; i++) {
        scanf("%d", &x);
        scanf("%d", &val[x]);
        rem[x].l = rem[x].r = val[x];
        rem[x].all = false;
    }
    visit[1] = true;
    if(dfs(1)) {
        memset(ans, 0, sizeof(ans));
        fa[1] = 0;
        ans[0] = rem[1].l - 1;
        memset(visit, 0, sizeof(visit));
        printf("Yes\n");
        calc(1);
        //printf("%d\n", n);
        for (int i = 1; i <= n; i++)
            printf("%d\n", ans[i]);
        return 0;
    }
    else printf("No\n");
}

