pii dfs(int idx,int par,vector<int> &up,vector<int> &down,Graph &g){

    for(int to:g[idx]){
        if(to==par) continue;
        pii x=dfs(to,idx,up,down,g);
        //cout<<idx<<" "<<x<<endl;

        chmax(down[idx],x.second); chmin(up[idx],x.first);
    }
    return pii(up[idx]+1,down[idx]-1);
}

vector<int> ret;

void dfs2(int idx,int par,vector<int> &up,vector<int> &down,Graph &g){
    if(par==-1) ret[idx]=up[idx];
    else{
        if(ret[par]>up[idx]) ret[idx]=ret[par]-1;
        else if(ret[par]<down[idx]) ret[idx]=ret[par]+1;
        else ret[idx]=ret[par];
    }
    for(int to:g[idx]){
        if(to==par) continue;
        dfs2(to,idx,up,down,g);
    }
}

