const double INF = 1e9;

vi G[100010];
int dist[100010];

bool dijk(vi starts){
    priority_queue< pii, vector<pii>, greater<pii> > pq;
    for(int s : starts) pq.push(pii(dist[s], s));

    while(!pq.empty()){
        int u, buf;
        std::tie(buf, u) = pq.top(); pq.pop();
        for(int v : G[u]){
            if(dist[v] == INF){
                dist[v] = dist[u] + 1;
                pq.push(pii(dist[v], v));
            }else if(abs(dist[v]-dist[u]) != 1){
                return false;
            }
        }
    }
    return true;
}

