		graph[b].push_back(a);
	}

	label = vi (N, -1);
	cin >> K;
	F0R(i, K) {
		int v, l; cin >> v >> l; --v;
		label[v] = l;
	}

	// T/F -> B/W
	dfs1(0, -1, 0);
	if ((isW[0] && isW[1]) || (isB[0] && isB[1])) {
		print("No"); return 0;
	}

	if (isW[0]) isB[1] = true;
	if (isB[1]) isW[0] = true;
	if (isW[1]) isB[0] = true;
	if (isB[0]) isW[1] = true;

	lo.resize(N); hi.resize(N);
	dfs2(0, -1, isB[0]);
	if (fail) {
		print("No"); return 0;
	}

	dfs3(0, -1, lo[0]+1);
	print("Yes");
	F0R(i, N) print(label[i]);
}

