void dfs(int x,int S,int E){
	if(x != root){
		if(g[x]){
			if(f[x] < S || f[x] > E || (E-S)%2 != (f[x]-S)%2){
				puts("No");
				exit(0);
			}

			int en = (E+S)/2, now = f[x];
			for(int y = fat[x]; !g[y]; y = fat[y]){
				g[y] = true;
				if(now > en)now--;else
					now++;
				f[y] = now;
			}
			S = E = f[x];

		}
	}
	for(vector<int>::iterator it = e[x].begin(); it != e[x].end(); it++){
		int y = *it;
		if(y == fat[x])continue;
		fat[y] = x;
		dfs(y, S-1, E+1);
	}

	if(!g[x]){
		int en = (E+S)/2, now = f[x] = E;
		g[x] = true;
		for(int y = fat[x]; !g[y]; y = fat[y]){
			g[y] = true;
			if(now > en)now--;else
				now++;
			f[y] = now;
		}
	}
}
