int main() {
  cin >> n;
  g.resize(n);
  l.assign(n, -3000000);
  r.assign(n, 3000000);
  res.resize(n, -1);
  for (int i = 0; i < n - 1; ++i) {
    int a, b;
    cin >> a >> b;
    g[--a].push_back(--b);
    g[b].push_back(a);
  }
  cin >> k;
  for (int i = 0; i < k; ++i) {
    int node, p;
    cin >> node >> p;
    --node;
    l[node] = r[node] = res[node] = p;
    root = node;
  }
  if (solve()) {
    cout << "Yes" << endl;
    for (auto &p : res) cout << p << endl;
  } else
    cout << "No" << endl;
  return 0;
}

bool solve() {
  if (!dfs(root, -1, res[root] & 1)) return 0;
  queue<int> qu;
  qu.push(root);
  res.assign(n, -100000000);
  res[root] = l[root];
  while (qu.size()) {
    int now = qu.front();
    qu.pop();
    for (auto to : g[now])
      if (res[to] == -100000000) {
        int num = res[now] - 1;
        if (l[to] <= num && num <= r[to])
          res[to] = num;
        else
          res[to] = num + 2;
        qu.push(to);
      }
  }
  return 1;
}
bool dfs(int now, int par, int dist) {
  if (res[now] >= 0 && ((res[now] ^ dist) & 1)) return 0;
  for (auto to : g[now])
    if (to != par) {
      if (!dfs(to, now, dist ^ 1)) return 0;
      l[now] = max(l[now], l[to] - 1);
      r[now] = min(r[now], r[to] + 1);
    }
  return l[now] <= r[now];
}

