using namespace std;

int nNode;
int vs[100000+10];
int parity[100000+10];
int lbs[100000+10];
int ubs[100000+10];
vector<int> g[100000+10];

bool go(int u, int p) {
  REP(i, g[u].size()) {
    int v = g[u][i];
    if(v == p)
      continue;
    if(!go(v, u))
      return false;
  }
  if(lbs[u] > ubs[u] || parity[u] == 0) { // 無理
    return false;
  }
  if(lbs[u] == ubs[u] && (parity[u] & (1 << (lbs[u] % 2))) == 0) {
    return false;
  }
  if(p >= 0) {
    REP(i, 2) {
      if((parity[u] & (1 << i)) == 0) {
        parity[p] &= ~(1 << !i);
      }
    }
    lbs[p] = max(lbs[p], lbs[u]-1);
    ubs[p] = min(ubs[p], ubs[u]+1);
  }
  return true;
}

void go2(int u, int p) {
  int value;
  if(p < 0) {
    value = lbs[u];
    if((parity[u] & (1 << (value%2))) == 0) {
      ++value;
    }
  } else {
    value = lbs[p]-1;
    if(value < lbs[u]) {
      value += 2;
    }
  }
  lbs[u] = ubs[u] = value;

  REP(i, g[u].size()) {
    int v = g[u][i];
    if(v == p)
      continue;
    go2(v, u);
  }
}

