using namespace std;
#define inf 100000000
vector<int> g[100001];
int L[100001],R[100001],id[100001],n,k;
bool ans=1;
void solve(int v=0,int p=-1){
    L[v]=-inf-1;
    R[v]=inf+1;
    if(id[v]!=-1)
        L[v]=R[v]=id[v];
    for(int i=0;i<g[v].size();i++){
        int to=g[v][i];
        if(to!=p){
            solve(to,v);
            if(L[to]<-inf/2)
                continue;
            if(L[v]<-inf/2){
                L[v]=L[to]-1;
                R[v]=R[to]+1;
            }
            else{
                if(abs(L[to])%2==abs(L[v])%2){
                    ans=0;
                    return;
                }
                L[v]=max(L[to]-1,L[v]);
                R[v]=min(R[to]+1,R[v]);
            }
        }
    }
    if(L[v]>R[v])
        ans=0;
}
void make(int v=0,int p=-1){
    if(v==0 && id[v]==-1)
        id[v]=L[v];
    for(int i=0;i<g[v].size();i++){
        int to=g[v][i];
        if(to!=p){
            if(id[to]==-1){
                if(L[to]<=id[v]-1 && id[v]-1<=R[to])
                    id[to]=id[v]-1;
                else
                    id[to]=id[v]+1;
            }
            make(to,v);
        }
    }
}
int main(){
