    }
    cin>>k;
    for(int i=0;i<k;i++){
        int x,y;
        cin>>x>>y;
        x--;
        id[x]=y;        
    }
    solve();
    if(!ans){
        puts("No");
        return 0;
    }
    make();
    puts("Yes");
    for(int i=0;i<n;i++)
        cout<<id[i]<<endl;
    return 0;
}

