struct Interval { int min, max; };
Interval intersection(const Interval a, const Interval b) { return {max(a.min, b.min), min(a.max, b.max)}; }
bool contains(const Interval a, const int x) { return a.min <= x && x <= a.max; }

int main()
{
    ios::sync_with_stdio(false);

    int N; cin >> N;
    auto adjacency_list = vector<vector<int>>(N);
    for (auto i = 0; i < N-1; i++)
    {
        int a, b; cin >> a >> b;
        a--; b--;

        adjacency_list[a].push_back(b);
        adjacency_list[b].push_back(a);
    }

    int K; cin >> K;
    auto root = -1;
    auto marked = vector<bool>(N);
    auto marks = vector<int>(N);
    for (auto i = 0; i < K; i++)
    {
        int v, p; cin >> v >> p;
        v--;

        root = v;
        marked[v] = true;
        marks[v] = p;
    }

    auto constraints = vector<Interval>(N);
    function<void(int, int)> preprocess = [&](const int v, const int parent)
    {
        const auto infinity = int(1e9);
        if (marked[v]) constraints[v] = {marks[v], marks[v]};
        else constraints[v] = {-infinity, infinity};

        for (const auto w : adjacency_list[v]) if (w != parent)
        {
            preprocess(w, v);
            constraints[v] = intersection(constraints[v], {constraints[w].min-1, constraints[w].max+1});
        }
    };
    preprocess(root, -1);

    function<bool(int, int)> process = [&](const int v, const int parent)
    {
        auto ok = false;
        if (marked[v]) ok = contains(constraints[v], marks[v]);
        else
        {
            for (const auto x : {marks[parent]-1, marks[parent]+1})
            {
                if (contains(constraints[v], x))
                {
                    marks[v] = x;
                    ok = true;
                }
            }
        }

        for (const auto w : adjacency_list[v]) if (w != parent)
            ok &= process(w, v);

        return ok;
    };

    if (process(root, -1))
    {
        cout << "Yes" << "\n";
        for (const auto x : marks) cout << x << "\n";
    }
    else cout << "No" << "\n";
}

