  cin>>a>>b;
  Tree[a-1]=b;
  S.insert(a-1);
  for(int i=1;i<K;i++){
    cin>>a>>b;
    Tree[a-1]=b;
    //  S.insert(a-1);
  }
  root=*S.begin();
  init();
  mk_tree(root,root);

  if(!flg)cout<<"No"<<endl;
  else {
    cout <<"Yes"<<endl;
    for(int i=0;i<n;i++) cout << Tree[i]<<endl;
  }

  return 0;
}

