#include <cstdio>
#include <cstring>
#define Inf 0x7f7f7f7f
int dist[100005];
int head[100005],arrive[200005],nxt[200005],tot;
void add_edge(int from,int to){
	arrive[++tot]=to;
	nxt[tot]=head[from];
	head[from]=tot;
}
int mx(int a,int b){
	return a>b?a:b;
}
int mn(int a,int b){
	return a<b?a:b;
}
int left[100005],right[100005];
int father[100005];
bool get_ans;
void dfs(int root){
	if(!get_ans){
		return;
	}
	left[root]=-Inf;
	right[root]=Inf;
	if(dist[root]!=-1){
		left[root]=right[root]=dist[root];
	}
	for(int i=head[root];i;i=nxt[i]){
		if(arrive[i]==father[root]){
			continue;
		}
		father[arrive[i]]=root;
		dfs(arrive[i]);
		if(!get_ans){
			return;
		}
		if(left[arrive[i]]!=-Inf){
			if(left[root]==-Inf){
				left[root]=left[arrive[i]]-1;
				right[root]=right[arrive[i]]+1;
			}
			else{
				if((left[arrive[i]]&1)==(left[root]&1)){
					get_ans=0;
					return;
				}
				left[root]=mx(left[root],left[arrive[i]]-1);
				right[root]=mn(right[root],right[arrive[i]]+1);
				if(left[root]>right[root]){
					get_ans=0;
					return;
				}
			}
		}
	}
}
void find_ans(int root){
	if(dist[root]==-1){
		dist[root]=left[root];
	}
	for(int i=head[root];i;i=nxt[i]){
		if(arrive[i]==father[root]){
			continue;
		}
		if(dist[arrive[i]]==-1){
			if(dist[root]-1>=left[arrive[i]]&&dist[root]-1<=right[arrive[i]]){
				dist[arrive[i]]=dist[root]-1;
			}
			else{
				dist[arrive[i]]=dist[root]+1;
			}
		}
		find_ans(arrive[i]);
	}
}
int main(){
	int n;
	scanf("%d",&n);
	memset(dist,-1,sizeof dist);
	int u,v;
	for(int i=1;i<n;i++){
		scanf("%d%d",&u,&v);
		add_edge(u,v);
		add_edge(v,u);
	}
	int k;
	scanf("%d",&k);
	for(int i=1;i<=k;i++){
		scanf("%d%d",&u,&v);
		dist[u]=v;
	}
	get_ans=1;
	dfs(1);
	if(!get_ans){
		puts("No");
	}
	else{
		find_ans(1);
		for(int i=1;i<=n;i++){
			printf("%d\n",dist[i]);
		}
	}
	return 0;
}

