			ans[0] = MIN;
		}
	}
	for (int i = n - 1; i >= 0;i--) {
		int MIN = -(1 << 29), MAX = 1 << 29;//OKな最小値、最大値
		for (int j : ::MIN[c[i].second]) {
			MIN = max(MIN, j);
		}
		for (int j : ::MAX[c[i].second]) {
			MAX = min(MAX, j);
		}
		if (ans[c[i].second] < INT_MAX) {
			MIN = MAX = ans[c[i].second];
		}
		for (int j : r[c[i].second]) {
			::MIN[j].push_back(MAX - 1);
			::MAX[j].push_back(MIN + 1);
		}
		ans[c[i].second] = MIN;
	}
	puts("Yes");
	for (int i = 0; i < n; i++) {
		cout << ans[i] << endl;
	}
}

