int N, K, val[100000], mxs[100000], mns[100000];
vector<vector<int>> e;

void rec(int c, int p, int d, int &mx, int &mn, int &flag){

	if(val[c] != -1){
		if(flag == -1) flag = (val[c] ^ d) & 1;
		else if(flag != ((val[c] ^ d) & 1)){
			cout << "No" << endl;
			exit(0);
		}
	}

	int nmx = 1e9, nmn = -1e9;
	for(int i : e[c]) if(i != p){
		int tmx, tmn;
		rec(i, c, d + 1, tmx, tmn, flag);
		nmx = min(nmx, tmx + 1);
		nmn = max(nmn, tmn - 1);
	}
	if(val[c] != -1){
		nmx = min(nmx, val[c]);
		nmn = max(nmn, val[c]);
	}

	if(nmx < nmn){
		cout << "No" << endl;
		exit(0);
	}
	mns[c] = mn = nmn;
	mxs[c] = mx = nmx;
}
void pro(int c, int p){
	if(c == p) val[c] = mns[c];
	else{
		if(val[p] + 1 <= mxs[c]) val[c] = val[p] + 1;
		else{
			assert(val[p] - 1 >= mns[c]);
			val[c] = val[p] - 1;
		}
	} 
	for(int i : e[c]) if(i != p) pro(i, c);
}


