pii dfs(int x, int p){
	// cout<<"dfs "<<x<<" "<<p<<endl;
	pii ret(-INF,INF);
	bool odd = false;
	bool even = false;
	for(int y: vv[x]){
		if(y==p) continue;
		pii t = dfs(y, x);
		if(t.fi>t.se) ret = pii(0,-11111111);
		if(t.fi&1) even = true;
		else odd = true;
		maxs(ret.fi, t.fi-1);
		mins(ret.se, t.se+1);
	}
	if(v[x]>=0){
		// if(v[x]&1) odd = true;
		// else even = true;
		maxs(ret.fi, v[x]);
		mins(ret.se, v[x]);
	}
	if(ret.fi>ret.se){
		ret = pii(0,-11111111);
	}
	if(ret.fi<=ret.se && (ret.se-ret.fi)%2){
		ret = pii(0,-11111111);
	}
	if(odd && even){
		ret = pii(0,-11111111);
	}
	seg[x] = ret;
	// cout<<"x "<<x<<" "<<seg[x].fi<<" "<<seg[x].se<<endl;
	return ret;
}

void dfs2(int x, int p, int l, int r){
	maxs(l, seg[x].fi);
	mins(r, seg[x].se);
	ans[x] = l;
	for(int y: vv[x]){
		if(y==p) continue;
		dfs2(y, x, l-1, l+1);
	}
}

