static const int MAXN = 100005;
static const int INF = 0x3fffffff;

int n, k;
std::vector<int> e[MAXN];
int val[MAXN];

bool feasible = true;
int min[MAXN], max[MAXN];

void dfs_traverse(int u, int p = -1)
{
    min[u] = -INF, max[u] = INF;
    for (std::vector<int>::iterator v = e[u].begin(); v != e[u].end(); ++v) if (*v != p) {
        dfs_traverse(*v, u);
        min[u] = std::max(min[u], min[*v] - 1);
        max[u] = std::min(max[u], max[*v] + 1);
    }
    if (min[u] > max[u]) feasible = false;
    if (val[u] != INF) {
        if (val[u] < min[u] || val[u] > max[u]) feasible = false;
        min[u] = max[u] = val[u];
    }
}

void dfs_fill(int u, int p, int val)
{
    if (min[u] == -INF) min[u] = val;
    for (std::vector<int>::iterator v = e[u].begin(); v != e[u].end(); ++v) if (*v != p) {
        dfs_fill(*v, u, min[u] + 1);
    }
}

