#include <bits/stdc++.h>
using namespace std;

const int INF = 1 << 30;

int main() {
    int N; cin >> N;
    vector<vector<int>> G(N);
    for(int i = 0; i < N - 1; ++i) {
        int a, b; cin >> a >> b;
        a--, b--;
        G[a].emplace_back(b);
        G[b].emplace_back(a);
    }

    int K; cin >> K;
    vector<int> P(N, -1);
    int v, p;
    for(int i = 0; i < K; ++i) {
        cin >> v >> p; v--;
        P[v] = p;
    }

    vector<int> parity(N);

    auto pfs = [&](auto &&pfs, int cur, int pre, int p) -> bool {
        parity[cur] = p;
        if(P[cur] != -1 and P[cur] % 2 != parity[cur]) return false;
        bool res = true;
        for(auto &to : G[cur]) {
            if(to == pre) continue;
            res &= pfs(pfs, to, cur, 1 - p);
        }
        return res;
    };

    if(!pfs(pfs, v, v, P[v] % 2)) return cout << "No" << '\n', 0;

    vector<pair<int, int>> rng(N);

    auto dfs = [&](auto &&dfs, int cur, int pre) -> pair<int, int> {
        int l = -INF, r = INF;
        for(auto &to : G[cur]) {
            if(to == pre) continue;
            int tl, tr; tie(tl, tr) = dfs(dfs, to, cur);
            tl--, tr++;
            l = max(l, tl), r = min(r, tr);
        }
        if(P[cur] != -1) l = max(l, P[cur]), r = min(r, P[cur]);
        while(abs(l) % 2 != parity[cur]) l++;
        while(abs(r) % 2 != parity[cur]) r--;
        return rng[cur] = {l, r};
    };

    dfs(dfs, v, v);
    for(int i = 0; i < N; ++i) {
        if(rng[i].first > rng[i].second) return cout << "No" << '\n', 0;
    }

    auto efs = [&](auto &&efs, int cur, int pre, int n) -> void {
        P[cur] = n;
        assert(rng[cur].first <= n and n <= rng[cur].second);
        for(auto &to : G[cur]) {
            if(to == pre) continue;
            int l, r; tie(l, r) = rng[to];
            if(l <= n + 1 and n + 1 <= r) efs(efs, to, cur, n + 1);
            else efs(efs, to, cur, n - 1);
        }
    };
    efs(efs, v, v, P[v]);

    cout << "Yes" << '\n';
    for(int i = 0; i < N; ++i) {
        cout << P[i] << '\n';
    }
    return 0;
}

