const int maxn = 1e5;

vi a(maxn, -1);
vb e(maxn, 1), o(maxn, 1);
vi g[maxn];
vi l(maxn, -2e9), r(maxn, 2e9);

void dfs(int v, int p = -1) {
    for (int u : g[v]){
        if (u != p) dfs(u, v);
    }
    for (int u : g[v]){
        if (u == p) continue;
        l[v] = max(l[v], l[u] - 1);
        r[v] = min(r[v], r[u] + 1);
        if (!e[u]) o[v] = 0;
        if (!o[u]) e[v] = 0;
        if (!e[v] && !o[v]){
            cout << "No\n";
            exit(0);
        }
    }
    if (l[v] > r[v]){
        cout << "No\n";
        exit(0);
    }
    if (a[v] != -1){
        if (a[v] % 2 == 0){
            if (!e[v]) {
                cout << "No\n";
                exit(0);
            }
            o[v] = false;
        }
        if (a[v] % 2 == 1){
            if (!o[v]) {
                cout << "No\n";
                exit(0);
            }
            e[v] = false;
        }
        if (a[v] < l[v] || a[v] > r[v]){
            cout << "No\n";
            exit(0);
        }
        l[v] = r[v] = a[v];
    }
}

vi ans(maxn);

void go(int v, int p = -1, int L = -2e9, int R = 2e9){
    L = max(L, l[v]);
    R = min(R, r[v]);
    ans[v] = L;
    if (L % 2 == 0 && !e[v]) ans[v]++;
    if (L % 2 == 1 && !o[v]) ans[v]++;
    for (int u : g[v]){
        if (u == p) continue;
        if (ans[v] % 2 == 0) e[u] = 0; else o[u] = 0;
        go(u, v, L - 1, R + 1);
    }
}

void solve() {
    int n;
    cin >> n;
    forn1(i, n) {
        int v, u;
        cin >> v >> u;
