		if (p != -1 && es2[a].size() == 1) used[a] = true;
		if (used[a]) {
			st.pop();
			REP(i, es2[a].size()) {
				int b = es2[a][i];
				if (b == p) continue;
				l[a] = max(l[b] - 1, l[a]);
				h[a] = min(h[b] + 1, h[a]);
			}
		}
		else {
			REP(i, es2[a].size()) {
				int b = es2[a][i];
				if (b == p) continue;
				if (h[b] != -1) {
					if (h[a] % 2 == h[b] % 2) {
						res = false;
						break;
					}
					l[b] = max(l[a] - 1, l[b]);
					h[b] = min(h[a] + 1, h[b]);
					l[a] = max(l[b] - 1, l[a]);
					h[a] = min(h[b] + 1, h[a]);
					if (l[a] > h[a] || l[b] > h[b]) {
						res = false;
						break;
					}
				}
				else {
					l[b] = l[a] - 1;
					h[b] = h[a] + 1;
				}
				st.emplace(b, a);
			}
		}
		used[a] = true;
	}
	if (!res) {
		cout << NO << endl;
		return 0;
	}
	cout << YES << endl;
	CLEAR(used);
	queue<int> q;
	q.push(V[0]);
	used[V[0]] = true;
	while (!q.empty()) {
		int t = q.front(); q.pop();
		int c = h[t];
		REP(i, es2[t].size()) {
			int s = es2[t][i];
			if (used[s]) continue;
			if (l[s] <= c + 1 && c + 1 <= h[s]) l[s] = h[s] = c + 1;
			else h[s] = h[s] = c - 1;
			q.push(s);
			used[s] = true;
		}
	}
	REP(i, N) cout << h[i] << endl;
	return 0;
}

