	int n, m, L[N], R[N], A[N];
	vector<int> E[N];

	void dfs(const int u, const int f)
	{
		for (int v : E[u])
			if (v != f)
			{
				dfs(v, u);
				int l = max(-INF, L[v] - 1);
				int r = min(INF, R[v] + 1);
				if (R[u] < l || L[u] > r)
				{
					puts("No");
					exit(0);
				}
				L[u] = max(L[u], l);
				R[u] = min(R[u], r);
			}
		if (L[u] > R[u])
		{
			puts("No");
			exit(0);
		}
	}

	void getans(const int u, const int f)
	{
		for (int v : E[u])
			if (v != f)
			{
				if (A[v] == -1)
				{
					if (L[v] <= A[u] - 1 && A[u] - 1 <= R[v])
						A[v] = A[u] - 1;
					else
						A[v] = A[u] + 1;
				}
				getans(v, u);
			}
	}

