void dfs1(int v, int c){
    eo[v] = c;

    for(auto to : g[v]){
        if(eo[to] < 0){
            dfs1(to, c ^ 1);
        }
    }

    return;
}

P dfs2(int v, int prev){
    P res = make_pair(ma[v], mi[v]);

    for(auto to : g[v]){
        if(to == prev){
            continue;
        }

        P tmp = dfs2(to, v);
        chmin(res.first, tmp.first + 1);
        chmax(res.second, tmp.second - 1);
    }

    ma[v] = res.first;
    mi[v] = res.second;

    if(res.first < res.second || ans[v] != -1 && (res.first < ans[v] || ans[v] < res.second)){
        return make_pair(-IINF, IINF);
    }

    return res;
}

void dfs3(int v, int prev, int val){
    if(ans[v] == -1){
        ans[v] = val < ma[v] ? val + 1 : val - 1;
    }

    for(auto to : g[v]){
        if(to == prev){
            continue;
        }

        dfs3(to, v, ans[v]);
    }

    return;
}

