inline void dfs(int k,int fa) {
	for (int i=head[k];i;i=nxt[i])
		if (to[i]!=fa) {
			dfs(to[i],k);
			L[k]=max(L[k],L[to[i]]-1);
			R[k]=min(R[k],R[to[i]]+1);
		}
}
bool check(int k) { return L[k]<=val[k]&&val[k]<=R[k]; }
inline void solve(int k,int fa) {
	if (!check(k)) val[k]-=2;
	if (!check(k)) puts("No"),exit(0);
	for (int i=head[k];i;i=nxt[i])
		if (to[i]!=fa) {
			val[to[i]]=val[k]+1;
			solve(to[i],k);
		}
}
