bool dfs(int id, int bf){
	if(bf != -1 && v[id] != INF && abs(v[id] - v[bf]) != 1) return false;
	if(bf != -1 && e[id].size() == 1) return true;
	REP(i, e[id].size()){
		if(e[id][i] == bf) continue;
		if(v[e[id][i]] != INF){
			if(abs(v[id] - v[e[id][i]]) != 1) return false;
			if(dfs(e[id][i], id)) continue;
			return false;
		}else{
			v[e[id][i]] = v[id] + 1;
			if(dfs(e[id][i], id)) continue;
			v[e[id][i]] = v[id] - 1;
			if(dfs(e[id][i], id)) continue;
			return false;
		}
	}
	return true;
}

