using namespace std;
int n,num,k,head[MN],l[MN],r[MN],val[MN];bool flag=0;
struct edge{int to,next;}g[MN<<1];
void ins(int u,int v){g[++num].next=head[u];head[u]=num;g[num].to=v;}
void dfs(int u,int f){
	for(int i=head[u];i;i=g[i].next)if(g[i].to!=f){
		dfs(g[i].to,u);if(flag)return ;
		if(l[g[i].to]==-inf)continue;
		if(l[u]==-inf){
			l[u]=l[g[i].to]-1,r[u]=r[g[i].to]+1;
		}else if(!((l[g[i].to]^l[u])&1)){flag=1;return;}
		else l[u]=max(l[g[i].to]-1,l[u]),r[u]=min(r[u],r[g[i].to]+1);
	}
	if(l[u]>r[u])flag=1;
}
void calc(int u,int f){
	for(int i=head[u];i;i=g[i].next)if(g[i].to!=f){
		if(val[u]+1>=l[g[i].to]&&val[u]+1<=r[g[i].to])val[g[i].to]=val[u]+1,calc(g[i].to,u);
		else val[g[i].to]=val[u]-1,calc(g[i].to,u);
	}
}
int main(){
	scanf("%d",&n);int x,y;
	for(int i=1;i<n;i++)scanf("%d%d",&x,&y),ins(x,y),ins(y,x);
	scanf("%d",&k);
	for(int i=1;i<=n;i++)l[i]=-inf,r[i]=inf;
	for(int i=1;i<=k;i++)scanf("%d%d",&x,&y),l[x]=r[x]=y;dfs(1,1);
	if(flag)puts("No");
	else {
		puts("Yes");
		val[1]=l[1];calc(1,1);
		for(int i=1;i<=n;i++)printf("%d\n",val[i]);
	}
}

