void add_edge(int a, int b) { edge[++ num] = (Edge){b, head[a]}, head[a] = num;}

int tl[N], tr[N], p[N];
bool flag = false;

void dfs(int x, int fa)
{
	tl[x] = -1e9, tr[x] = 1e9;
	RepG(i, x) if (v != fa) {
		dfs(v, x);
		tl[x] = max(tl[x], tl[v] - 1), tr[x] = min(tr[x], tr[v] + 1);
	}
	if (tl[x] > tr[x]) flag = true;
	else if (p[x] != -1) {
		if (tl[x] <= p[x] && p[x] <= tr[x]) tl[x] = tr[x] = p[x];  
		else flag = true;
	}
	//printf("%d %d %d\n", x, tl[x], tr[x]);
}

void dfs1(int x, int fa)
{
	for (int i = -1; i <= 1; i ++)
		if (tl[x] <= p[fa] + i && p[fa] + i <= tr[x]){
			p[x] = p[fa] + i;
			break;
		}
	if (!fa) p[x] = tl[x];
	RepG(i, x) if (v != fa) dfs1(v, x);
}

