const int maxn=100010;

int n,k,val[maxn],l[maxn],r[maxn],par[maxn],ans[maxn];
vector<int> e[maxn],order;
bool vis[maxn],know[maxn],known[maxn][2],ok;

inline void dfs(int v)
{
	vis[v]=1;

	l[v]=-INF;r[v]=INF;
	repV(i,e[v]) if(!vis[i])
	{
		dfs(i);
		par[i]=v;

		if(known[i][0]) known[v][1]=1;
		if(known[i][1]) known[v][0]=1;

		l[v]=max(l[v],l[i]-1);
		r[v]=min(r[v],r[i]+1);
	}

	if(know[v])
	{
		l[v]=max(l[v],val[v]);
		r[v]=min(r[v],val[v]);
		known[v][val[v]%2]=1;
	}

	if(known[v][0]&&known[v][1]) ok=1;
	if(l[v]>r[v]) ok=1;

	order.push_back(v);
}

inline int sol(int v,int p)
{
	if(!p) return l[v];

	l[v]=max(l[v],ans[p]-1);
	r[v]=min(r[v],ans[p]+1);

	while(l[v]%2==ans[p]%2) l[v]++;
	return l[v];
}

int main()
{
	SF("%d",&n);
	rep1(i,n-1)
	{
		int x,y;SF("%d%d",&x,&y);
		e[x].push_back(y);
		e[y].push_back(x);
	}

	SF("%d",&k);
	rep(i,k)
	{
		int v,p;SF("%d%d",&v,&p);
		know[v]=1;
		val[v]=p;
	}

	dfs(1);
	if(ok) return !PF("No");

	reverse(All(order));
	PF("Yes\n");
	repV(i,order) ans[i]=sol(i,par[i]);

	rep1(i,n) PF("%d\n",ans[i]);

	return 0;
}
