void dfs1(int x,int f,int p)
{
	if(val[x]!=-inf&&(val[x]&1)!=p)fl=1;
	if(fl)return ;
	for(auto v:V[x])
		if(v!=f)dfs1(v,x,p^1);
}
void dfs2(int x,int f)
{
	if(fl)return ;
	if(val[x]==-inf)mx[x]=mx[f]+1,mn[x]=mn[f]-1;
	for(auto v:V[x])
		if(v!=f)
		{
			dfs2(v,x);
			if(val[x]==-inf)mx[x]=min(mx[x],mx[v]+1),mn[x]=max(mn[x],mn[v]-1);
		}
	if(mx[x]<mn[x])fl=1;
}
void dfs3(int x,int f)
{
	if(val[x]==-inf)
	{
		if(val[f]+1<=mx[x])val[x]=val[f]+1;
		else val[x]=val[f]-1;
	}
	for(auto v:V[x])
		if(v!=f)dfs3(v,x);
}
