vector<int> g[100000];
vector<pair<int, int>> v(100000, make_pair(1e7, -1e7));

pair<int, int> dfs(int cur, int high, int low, int pre){
	//show(cur)
	//rep(i,5){ cout << v[i].first << ' '; } cout << endl;
	//rep(i,5){ cout << v[i].second << ' '; } cout << endl;


	pair<int, int> res(1e7, -1e7);
	for(auto to : g[cur]){
		if(to == pre) continue;

		int nh = min(high + 1, v[to].first);
		int nl = max(low - 1, v[to].second);

		if(nh < nl){
			return pair<int, int>(-1e7, 1e7);
		}

		pair<int, int> d = dfs(to, nh, nl, cur);
		res.first = min(res.first, d.first);
		res.second = max(res.second, d.second);
	}

	res.first++;
	res.second--;

	//show("res")
	//cout << res.first << ' ' << res.second << endl;
	return v[cur] = make_pair(min(res.first, high), max(res.second, low));
}

