const int INF=1e9;

int main()
{
   int N; cin>>N;
   Graph G(N);
   for(int i=0;i<N-1;i++){
      int a,b; cin>>a>>b;
      a--; b--;
      G[a].push_back(b);
      G[b].push_back(a);
   }

   int K; cin>>K;
   vector<int> num(N,-1);
   for(int i=0;i<K;i++){
      int v,p; cin>>v>>p;
      num[v-1]=p;
   }

   int root=-1;
   for(int i=0;i<N;i++) if(num[i]>=0) root=i;

   bool ok=true;
   function<void(int,int,int)> parity_check=[&](int v,int p,int d)
   {
      if(num[v]>=0 and abs(num[v]-num[root])%2!=d%2) ok=false;
      for(int u:G[v]) if(u!=p){
         parity_check(u,v,d+1);
      }
   }; parity_check(root,-1,0);
   if(!ok){
      cout<<"No"<<endl;
      return 0;
   }

   vector<int> L(N,-INF),R(N,INF);
   function<P(int,int)> calc=[&](int v,int p)
   {
      for(int u:G[v]) if(u!=p){
         P child=calc(u,v);
         L[v]=max(L[v],child.first-1);
         R[v]=min(R[v],child.second+1);
      }
      if(num[v]>=0){
         L[v]=max(L[v],num[v]);
         R[v]=min(R[v],num[v]);
      }
      if(L[v]>R[v]) ok=false;
      // cout<<v+1<<' '<<L[v]<<' '<<R[v]<<endl;
      return make_pair(L[v],R[v]);
   };
   calc(root,-1);
   if(!ok){
      cout<<"No"<<endl;
      return 0;
   }

   function<void(int,int)> write=[&](int v,int p)
   {
      for(int u:G[v]) if(u!=p){
         if(L[u]<=num[v]-1 and num[v]-1<=R[u]) num[u]=num[v]-1;
         else num[u]=num[v]+1;
         write(u,v);
      }
   };
   write(root,-1);
   cout<<"Yes"<<endl;
   for(int i=0;i<N;i++) cout<<num[i]<<endl;
   return 0;
}

