#include<bits/stdc++.h>

using namespace std;

int N, M, a[100009], ans[100009], st[100009], dr[100009];
bool type[100009];
vector < int > v[100009];

void Bad ()
{
    printf ("No\n");
    exit (0);
}

void dfs (int nod, int tata)
{
    vector < pair < pair < int, int >, bool > > curr;
    bool free = 1;
    for (auto it = v[nod].begin (); it != v[nod].end (); it ++)
        if (*it != tata)
        {
            dfs (*it, nod), curr.push_back ({{st[*it], dr[*it]}, type[*it]});
            if (type[*it] != 0) free = 0;
        }
    if (free)
    {
        if (a[nod] != -1) st[nod] = dr[nod] = a[nod], type[nod] = 1;
        else st[nod] = dr[nod] = type[nod] = 0;
    }
    else
    {
        bool initialized = 0;
        int mini, maxi;
        type[nod] = 1;
        for (auto it = curr.begin (); it != curr.end (); it ++)
        {
            int l = it->first.first, r = it->first.second;
            bool t = it->second;
            if (t == 0) continue;
            if (!initialized) mini = l, maxi = r, initialized = 1;
            else
            {
                if (l % 2 != mini % 2) Bad ();
                if (l > mini) mini = l;
                if (r < maxi) maxi = r;
            }
        }
        mini --, maxi ++;
        if (mini > maxi) Bad ();
        if (a[nod] != -1)
        {
            if (a[nod] < mini || a[nod] > maxi || a[nod] % 2 != mini % 2) Bad ();
            st[nod] = dr[nod] = a[nod];
        }
        else st[nod] = mini, dr[nod] = maxi;
    }
}

void solve (int nod, int tata)
{
    if (st[nod] <= ans[tata] + 1 && ans[tata] + 1 <= dr[nod]) ans[nod] = ans[tata] + 1;
    else ans[nod] = ans[tata] - 1;
    for (auto it = v[nod].begin (); it != v[nod].end (); it ++)
        if (*it != tata)
            solve (*it, nod);
}

