for (int i=1; i<N; i++)
{
    int x, y;
    scanf ("%d %d", &x, &y);
    v[x].push_back (y);
    v[y].push_back (x);
}
scanf ("%d", &M);
while (M --)
{
    int x, y;
    scanf ("%d %d", &x, &y);
    a[x] = y;
}
dfs (1, -1);
ans[1] = st[1];
for (auto it = v[1].begin (); it != v[1].end (); it ++)
    solve (*it, 1);
printf ("Yes\n");
for (int i=1; i<=N; i++)
    printf ("%d\n", ans[i]);
return 0;
