	for (int u,v,i=1;i<n;i++)
		scanf("%d %d",&u,&v),add(u,v);
	scanf("%d",&m);
	for (int u,v,i=1;i<=m;i++)
		scanf("%d %d",&u,&v),a[u]=v,rt=u;
	if (rt) dfs(rt,0,a[rt]&1);else rt=1;dp(rt,0);
	if (mi[rt]<=mx[rt]&&tag) {
		puts("Yes");mk(rt,0,a[rt]!=-1?a[rt]:0);
		for (int i=1;i<=n;i++) printf("%d\n",a[i]);
	}
	else puts("No");
	return 0;
}

