    if (mark[u]) L[u]=R[u]=a[u];
    else L[u]=-1e9,R[u]=1e9;
    for (int i=head[u];i!=-1;i=edge[i].nx) {
        int to=edge[i].v;
        if (to==fa) continue;
        dfs2(to,u);
        L[u]=max(L[to]-1,L[u]);
        R[u]=min(R[to]+1,R[u]);
    }
