		if(a.p == 2 and b.p == 2 and abs(a.x%2) != abs(b.x%2)) x = 0, y = -1, p = 1;
		else{
			if(a.p == b.p) x = max(a.x, b.x), y = min(a.y, b.y);
			else{
				if(a.p == 2) swap(a, b);
				if(abs(a.x%2) != abs(b.x%2)) a.x++;
				if(abs(a.y%2) != abs(b.y%2)) a.y--;
				x = max(a.x, b.x), y = min(a.y, b.y), p = 2;
			}
		}
		//printf("[%d %d %d] (%d %d %d)\n", x, y, p, b.x, b.y, b.p);
	}
};
RG Range[MAX_N]; // [min, max];
bool getCan(int v, int p) {
	for(int w : Ed[v]) if(w != p) if(!getCan(w, v)) return false;
	if(Fix[v] == -1) {
		Range[v] = RG(-INF, +INF, 1);
		for(int w : Ed[v]) if(w != p) Range[v].update(Range[w]);
	}else Range[v] = RG(Fix[v], Fix[v], 2);
	if(Fix[p] != -1) Range[v].update(RG(Fix[p], Fix[p], 2));
	if(Range[v].x > Range[v].y) return false;
	//printf("%d : [%d %d, %d]\n", v, Range[v].x, Range[v].y, Range[v].p);
	return true;
}
void getAns(int v, int p) {
	Ans[v] = Range[v].x;
	for(int w : Ed[v]) if(w != p) Range[w].update(RG(Ans[v], Ans[v], 2)), getAns(w, v);
}
int main() {
	cin >> N; for(int i=1; i<N; i++) {int x, y; scanf("%d%d", &x, &y);Ed[x].push_back(y); Ed[y].push_back(x);}
	for(int i=0; i<=N; i++) Fix[i] = -1;
	int K; cin >> K; for(int i=0; i<K; i++) {int v, p; scanf("%d%d", &v, &p);Fix[v] = p;}

	bool isCan = getCan(1, 0);
	puts(isCan ? "Yes" : "No");
	if(isCan) {
		getAns(1, 0);
		for(int i=1; i<=N; i++) printf("%d\n", Ans[i]);
	}
	return 0;
}

