void prep(int u, int p)
{
	if(p == -1) h[u] = 0;
	else h[u] = h[p]+1;
	if(p == -1) color[u] = 0;
	else color[u] = (color[p]^1);
	for(int i = 0; i < adj[u].size(); i++)
	{
		int v = adj[u][i];
		if(v==p) continue;
		prep(v,u);
		if(hh[v] < hh[u])
		{
			hh[u] = hh[v];
			best[u] = best[v];
			mini[u] = mini[v];
			maxi[u] = maxi[v];
		}
		else if(hh[v] == hh[u])
		{
			mini[u] = min(mini[u],mini[v]);
			maxi[u] = max(maxi[u],maxi[v]);
		}
		minn[u]=min(minn[u],minn[v]);
		maxx[u]=max(maxx[u],maxx[v]);
	}
	if(ans[u] < INF)
	{
		hh[u] = h[u];
		best[u] = u;
		mini[u] = ans[u];
		maxi[u] = ans[u];
		maxx[u]=ans[u]-h[u];
		minn[u]=ans[u]+h[u];
	}
	mini[u]=minn[u];
	maxi[u]=maxx[u];
}

bool dfs(int u, int p)
{
	for(int i = 0; i < adj[u].size(); i++)
	{
		int v = adj[u][i];
		if(v==p) continue;
		if(mini[v]>maxi[v]) //means free
		{
			ans[v] = ans[u]+1;
		}
		else
		{
			int val = ans[u];
			if(ans[u]<mini[v])
			{
				val++;
			}
			else if(ans[u]>maxi[v])
			{
				val--;
			}
			else
			{
				int l = abs(mini[v]-ans[u]);
				int r = abs(maxi[v]-ans[u]);
				if(l>r) val--;
				else if(l<r) val++;
				else
				{
					l = abs(minn[v]-ans[u]);
					r = abs(maxx[v]-ans[u]);
					if(l>r) val--;
					else val++;
				}
			}
			//cerr<<v+1<<' '<<val<<'\n';
			if(ans[v]<INF&&val!=ans[v])
			{
				return false;
			}
			ans[v]=val;
		}
		if(!dfs(v, u)) return false;
	}
	return true;
}

