using namespace std;

struct NODE
{
	int l, r;
	NODE () {l = -oo, r = +oo;}
	NODE (int l0, int r0) : l(l0), r(r0) {}
	NODE operator + (const NODE& t)
	{
		if(l <= -oo) return t;
		else if(t.l <= -oo) return *this;
		else if((l&1) != (t.l&1)) return NODE(1, 0);
		else return NODE(max(l, t.l), min(r, t.r));
	}
	NODE expand()
	{
		return NODE(l-1, r+1);
	}
} ;

int n, m;
int fst[MX], nxt[MX*2], v[MX*2], lnum;
NODE rag[MX];

void addeg(int nu, int nv)
{
	nxt[++lnum] = fst[nu];
	fst[nu] = lnum;
	v[lnum] = nv;
}

void updfs(int x, int f)
{
	for(int i=fst[x]; i; i=nxt[i])
		if(v[i] != f)
		{
			updfs(v[i], x);
			rag[x] = rag[x] + rag[v[i]].expand();
		}
}

void downdfs(int x, int f)
{
	rag[x] = rag[x] + rag[f].expand();
	for(int i=fst[x]; i; i=nxt[i])
		if(v[i] != f)
			downdfs(v[i], x);
}

