	}
	scanf("%d", &m);
	for(int i=1; i<=m; i++)
	{
		scanf("%d%d", &a, &b);
		rag[a] = NODE(b, b);
	}
	updfs(1, 0);
	bool flg = 1;
	for(int i=1; i<=n; i++)
		if(rag[i].l > rag[i].r)
			flg = 0;
	if(!flg) printf("No\n");
	else
	{
		printf("Yes\n");
		rag[1].r = rag[1].l;
		downdfs(1, 0);
		for(int i=1; i<=n; i++) printf("%d\n", rag[i].l);
	}
	return 0;
}

