inline char nc() {
    static char ibuf[RLEN],*ib,*ob;
    (ib==ob) && (ob=(ib=ibuf)+fread(ibuf,1,RLEN,stdin));
    return (ib==ob) ? -1 : *ib++;
}
inline int rd() {
    char ch=nc(); int i=0,f=1;
    while(!isdigit(ch)) {if(ch=='-')f=-1; ch=nc();}
    while(isdigit(ch)) {i=(i<<1)+(i<<3)+ch-'0'; ch=nc();}
    return i*f;
}

const int N=1e5+50, INF=0x3f3f3f3f;
int n, k, li[N], ri[N], odd[N], ans[N];
#define L li
#define R ri
vector <int> edge[N];
inline void getans(int x,int f) {
    if(!f) {ans[x]=((li[x]&1)==odd[x]) ? li[x] : (li[x]+1);}
    else {ans[x]=ans[f]-1; if(ans[x]<li[x]) ans[x]+=2;}
    for(int e=edge[x].size()-1;e>=0;e--) {
        int v=edge[x][e]; if(v==f) continue;
        getans(v,x);
    }
}
inline void dfs_son(int x,int f) {
    for(int e=edge[x].size()-1;e>=0;e--) {
        int v=edge[x][e]; if(v==f) continue;
        dfs_son(v,x);
        R[x]=min(R[x],R[v]+1); L[x]=max(L[x],L[v]-1);
        if(~odd[v]) {
            if(!~odd[x]) odd[x]=(!odd[v]);
            else if(odd[x]==odd[v]) {
                puts("No");
                exit(0);
            }
        }
    }
}
inline void dfs_fa(int x,int f) {
    if(f) {
        R[x]=min(R[x], R[f]+1);
        L[x]=max(L[x], L[f]-1);
        if(~odd[x]) odd[x]=(!odd[f]);
    } 
    if((L[x]>R[x]) || (L[x]==R[x] && ((L[x]&1)!=odd[x]))) {
        puts("No"); exit(0);
    }
    for(int e=edge[x].size()-1;e>=0;e--) {
        int v=edge[x][e]; if(v==f) continue;
        dfs_fa(v,x);
    }
}
int main() {
    n=rd();
    for(int i=1;i<=n;i++) li[i]=-INF, ri[i]=INF, odd[i]=-1;
    for(int i=1;i<n;i++) {
        int x=rd(), y=rd();
        edge[x].push_back(y);
        edge[y].push_back(x);
    }
    k=rd();
    for(int i=1;i<=k;i++) {
        int x=rd(), v=rd();
        li[x]=ri[x]=v;
        odd[x]=(v&1);
    }
    if(!k) {
        li[1]=ri[1]=0; odd[1]=0;
        getans(1,0); puts("Yes");
        for(int i=1;i<=n;i++) printf("%d\n",ans[i]);
    } else {
        dfs_son(1,0); 
        dfs_fa(1,0);
        getans(1,0);
        puts("Yes");
        for(int i=1;i<=n;i++) printf("%d\n",ans[i]);    
    }
}

