const long long int MOD = 1000000007;

long long int N, M, K, H, W, L, R;

void Calculate_Depth(vector<vector<int>>&edge, vector<int>&depth, int stnode) {
	depth[stnode] = 0;
	queue<int>Q;
	Q.push(stnode);
	while (!Q.empty()) {
		int cn = Q.front();
		Q.pop();
		for (auto i : edge[cn]) {
			if (depth[i] > depth[cn] + 1) {
				depth[i] = depth[cn] + 1;
				Q.push(i);
			}
		}
	}
	return;
}

void TopDown(vector<int>&depth, vector<int>&l, vector<int>&r, vector<vector<int>>&edge, int node) {
	for (auto i : edge[node]) {
		if (depth[i] > depth[node]) {
			if (l[i] == l[node])l[i]++;
			l[i] = max(l[i], l[node] - 1);
			if (r[i] == r[node])r[i]--;
			r[i] = min(r[i], r[node] + 1);
			TopDown(depth, l, r, edge, i);
		}
	}
	return;
}

void BottomUp(vector<int>&depth, vector<int>&l, vector<int>&r, vector<vector<int>>&edge, int node) {
	for (auto i : edge[node]) {
		if (depth[i] > depth[node]) {
			BottomUp(depth, l, r, edge, i);
			if (l[node] == l[i])l[node]++;
			l[node] = max(l[node], l[i] - 1);
			if (r[node] == r[i])r[node]--;
			r[node] = max(r[node], r[i] + 1);
		}
	}
	return;
}

int main() {
	ios::sync_with_stdio(false);
	cin.tie(0);

	cin >> N;
	vector<vector<int>>edge(N);
	for (int i = 1; i < N; i++) {
		cin >> L >> R;
		L--;
		R--;
		edge[L].push_back(R);
		edge[R].push_back(L);
	}
	vector<int>l(N,-MOD);
	vector<int>r(N,MOD);
	cin >> K;
	for (int i = 0; i < K; i++) {
		cin >> L >> M;
		L--;
		l[L] = M;
		r[L] = M;
	}
	vector<int>depth(N,MOD);
	Calculate_Depth(edge, depth, L);
	TopDown(depth, l, r, edge, L);
	BottomUp(depth, l, r, edge, L);
	for (int i = 0; i < N; i++) {
		if (l[i] > r[i]) {
			cout << "No\n";
			return 0;
		}
	}
	cout << "Yes\n";
	for (auto i : l)cout << i << endl;
	return 0;
}

