const int maxn=100010;
int n,m;
int fa[maxn];
int ans[maxn];
bool has[maxn];
int l[maxn],r[maxn];
int a[maxn];
struct Edge
{
	int v,next;
}	e[maxn<<1];
int g[maxn],tot;
void addedge(int x,int y)
{
	tot++;
	e[tot].v=y;
	e[tot].next=g[x];
	g[x]=tot;
}
void dfs(int t)
{
	if (a[t]!=-1)
	{
		l[t]=a[t];
		r[t]=a[t];
		has[t]=true;
	}
	for (int i=g[t];i;i=e[i].next)
	if (e[i].v!=fa[t])
	{
		fa[e[i].v]=t;
		dfs(e[i].v);
		if (!has[e[i].v])	continue;
		if (!has[t])
		{
			has[t]=true;
			l[t]=l[e[i].v]-1;
			r[t]=r[e[i].v]+1;
		}
		else
		{
			int _l=l[e[i].v]-1;
			int _r=r[e[i].v]+1;
			if ((_l%2 != l[t]%2) || (_r%2 != r[t]%2))
			{
				printf("No\n");
				exit(0);
			}
			l[t]=max(l[t],_l);
			r[t]=min(r[t],_r);
			if (l[t]>r[t])
			{
				printf("No\n");
				exit(0);
			}
		}
	}
	return;
}
void get_em(int t)
{
	ans[t]=ans[fa[t]]+1;
	for (int i=g[t];i;i=e[i].next)
	if (e[i].v!=fa[t])
		get_em(e[i].v);
	return;
}
void getans(int t)
{
	for (int i=g[t];i;i=e[i].next)
	if (e[i].v!=fa[t])
	{
		if (!has[e[i].v])
		{
			get_em(e[i].v);
			continue;
		}
		int _a=ans[t]-1;
		if (_a>=l[e[i].v] && _a<=r[e[i].v])
			ans[e[i].v]=_a;
		else
			ans[e[i].v]=ans[t]+1;
		getans(e[i].v);
	}
}
int main()
{
	scanf("%d",&n);
	for (int i=1;i<n;i++)
	{
		int x,y;
		scanf("%d%d",&x,&y);
		addedge(x,y);
		addedge(y,x);
	}
	scanf("%d",&m);
	for (int i=1;i<=n;i++)
		a[i]=-1;
	for (int i=1;i<=m;i++)
	{
		int v,x;
		scanf("%d%d",&v,&x);
		a[v]=x;
	}
	dfs(1);
	if (!has[1])
		get_em(1);
	else
	{
		ans[1]=l[1];
		getans(1);
	}
	printf("Yes\n");
	for (int i=1;i<=n;i++)	printf("%d\n",ans[i]);
	return 0;
}

