int N, K, root = -1;
vi G[100001];
int nextVal[100001];
int value[100001], ans[100001];
bool no;

void dfs1(int u, int pre) {
    each(v, G[u]) if(v!=pre){
        dfs1(v, u);
        if(nextVal[v] != -1)nextVal[u] = nextVal[v];
    }
    each(v, G[u]) if(v != pre) {
        if(value[v] != -1)nextVal[u] = value[v];
    }
}

void dfs2(int u, int pre, int x) {
    if(value[u] != -1 && value[u] != x) {
        no = true;
        return;
    }

    ans[u] = x;

    each(v, G[u]) if(v != pre) {
        if(value[v] != -1) {
            if(value[v] >= x)dfs2(v, u, x + 1);
            else dfs2(v, u, x - 1);
        } else {
            if(nextVal[v] >= x)dfs2(v, u, x + 1);
            else dfs2(v, u, x - 1);
        }
    }
}

