const int N=1e5+5;
const int INF=123456789;
int n,k;
int ver[N],L[N],R[N];
bool ok=true;
vector<int> nei[N];

void check(int x,int p){
	if(ver[x]!=-INF) L[x]=R[x]=ver[x];
	for(int i=0;i<nei[x].size();i++){
		int to=nei[x][i];
		if(to==p) continue;
		check(to,x);
		if(L[to]!=-INF){
			if(L[x]==-INF){
				L[x]=L[to]-1;
				R[x]=R[to]+1;
			}else{
				L[x]=max(L[x],L[to]-1);
				R[x]=min(R[x],R[to]+1);
			}
		}
	}
	if(L[x]>R[x]) ok=false;
}

void make(int x,int p){
	if(p==-1){
		if(ver[x]==-INF) ver[x]=L[x];
	}
	for(int i=0;i<nei[x].size();i++){
		int to=nei[x][i];
		if(to==p) continue;
		if(ver[to]==-INF){
			if(L[to]<=ver[x]-1&&ver[x]-1<=R[to]) ver[to]=ver[x]-1;
			else ver[to]=ver[x+1];
		}
		make(to,x);
	}
}

int main(){
	scanf("%d",&n);
	for(int i=1;i<=n;i++) ver[i]=L[i]=-INF,R[i]=INF;
	for(int i=1;i<n;i++){
		int x,y;
		scanf("%d%d",&x,&y);
		nei[x].push_back(y);
		nei[y].push_back(x);
	}
	scanf("%d",&k);
	while(k--){
		int x,val;
		scanf("%d%d",&x,&val);
		ver[x]=val;
	}
	check(1,-1);
	if(ok){
		puts("Yes");
		make(1,-1);
		for(int i=1;i<=n;i++) printf("%d\n",ver[i]);
	}else{
		puts("No");
	}
	return 0;
}

