using namespace std;

typedef long long ll;
typedef pair<ll, ll> P;
typedef pair<P, ll> T;

vector<int> edge[101000];
int p[101000];
P hist[101000];
int resV[101000];

P mergeP(P x, P y){
    return P(max(x.fs, y.fs), min(x.sc, y.sc));
}


P dfs(int s, int prev, int index){
    P x;
    if(p[s] != -1){
        if(p[s] % 2 != index){
            return P(1000001, -1);
        }
        else {
            x = P(p[s]-1, p[s]+1);
        }

    }
    else if(index == 0){
        x = P(-2000000, 2000000);
    }
    else{
        x = P(-1999999, 1999999);
    }

    for(auto v: edge[s]){
        if(v == prev){
            continue;
        }
        x = mergeP(x, dfs(v, s, 1-index));
    }
    hist[s] = x;
    return x;
}


bool dfs2(int s, int prev, int prevValue){
    bool res = true;
    if(prevValue + 1 >= hist[s].fs && prevValue + 1 <= hist[s].sc){
        resV[s] = prevValue + 1;
    }
    else if(prevValue - 1 >= hist[s].fs && prevValue - 1 <= hist[s].sc){
        resV[s] = prevValue - 1;
    }
    else{
        return false;
    }

    for(auto v: edge[s]){
        if(v == prev){
            continue;
        }
        if(!dfs2(v, s, resV[s])){
            res = false;
        }
    }
    return res;
}


int main(){
    ll N, K;
    cin >> N;
    for(int i = 0; i < N-1; i++){
        int a, b;
        cin >> a >> b;
        a--; b--;
        edge[a].push_back(b);
        edge[b].push_back(a);
    }
    fill(p, p+N, -1);
    cin >> K;
    int root = -1;
    for(int i = 0; i < K; i++){
        int v, p2;
        cin >> v >> p2;
        v--;
        p[v] = p2;
        if(root == -1){
            root = v;
        }
    }

    dfs(root, root, p[root] % 2);
//    for(int i = 0; i < N; i++){
//        cout << i << " " << hist[i].fs << " " << hist[i].sc << endl;
//    }
    bool res = dfs2(root, root, p[root]+1);
    if(res){
        cout << "Yes" << endl;
        for(int i = 0; i < N; i++){
            cout << resV[i] << endl;
        }
    }
    else{
        cout << "No" << endl;
    }


    return 0;
}

#include <bits/stdc++.h>
using namespace std;
const int N = 1e5+20;
struct edge { int ver,next; } e[N*2];
int n,k,v[N],t,Head[N],sum[N],mark[N],up[N],v_[N],pp[N];
inline void insert(int x,int y) { e[++t] = (edge){y,Head[x]} , Head[x] = t; }
inline void input(void)
{
    scanf("%d",&n);
    for (int i=1;i<n;i++)
    {
        int x,y;
        scanf("%d%d",&x,&y);
        insert( x , y );
        insert( y , x );
    }
    scanf("%d",&k);
    for (int i=1;i<=k;i++)
    {
        int ver,p;
        scanf("%d%d",&ver,&p);
        v[ver] = p;
    }
    for (int i=1;i<=n;i++)
        if ( v[i] == -1 )
            v_[++v_[0]] = i;
        else pp[++pp[0]] = i;
}
inline void dfs1(int x,int fa)
{
    sum[x] = v[x] > -1 , mark[x] = true;
    for (int i=Head[x];i;i=e[i].next)
    {
        int y = e[i].ver;
        if ( y == fa ) continue;
        dfs1( y , x );
        sum[x] += sum[y];
    }
    if ( !sum[x] ) mark[x] = false;
    //printf("mark[%d] = %d\n",x,mark[x]);
}
inline void dfs2(int x,int fa,int p)
{
    if ( v[x] > -1 ) p = v[x];
    for (int i=Head[x];i;i=e[i].next)
    {
        int y = e[i].ver;
        if ( y == fa || !mark[y] ) continue;
        up[y] = p , dfs2( y , x , p );
    }
    //printf("up[%d] = %d\n",x,up[x]);
}
inline void dfs3(int x,int fa)
{
    for (int i=Head[x];i;i=e[i].next)
    {
        int y = e[i].ver;
        if ( y == fa || !mark[y] ) continue;
        dfs3( y , x );
        if ( v[x] > -1 ) continue;
        if ( up[y] > v[y] ) v[x] = v[y] + 1;
        else v[x] = v[y] - 1;
    }
    //printf("v[%d] = %d\n",x,v[x]);
}
inline void dfs4(int x,int fa)
{
    for (int i=Head[x];i;i=e[i].next)
    {
        int y = e[i].ver;
        if ( y == fa ) continue;
        if ( v[y] == -1 ) v[y] = v[x] + 1;
        dfs4( y , x );
    }
}
inline bool check(void)
{
    for (int i=1;i<=n;i++)
        for (int j=Head[i];j;j=e[j].next)
            if ( abs( v[e[j].ver] - v[i] ) != 1 )
                return false;
    return true;
}
int main(void)
{
    memset( v , 0xff , sizeof v );
    input();
    int cnt = 1;
    random_shuffle(pp+1,pp+pp[0]+1);
    do {
        int root = pp[cnt];
        if ( root == 0 ) v[root=1] = 1;
        dfs1( root , 0 );
        dfs2( root , 0 , v[root] );
        dfs3( root , 0 );
        dfs4( root , 0 );
        if ( check() )
        {
            puts("Yes");
            for (int i=1;i<=n;i++)
                printf("%d\n",v[i]);
            return 0;
        }
        else
        {
            memset( sum , 0 , sizeof sum );
            memset( mark , 0 , sizeof mark );
            memset( up , 0 , sizeof up );
            for (int i=1;i<=v_[0];i++)
                v[v_[i]] = -1;
        }
    } while ( ++cnt < min(200,k) );
    puts("No");
    return 0;
}

// 解き直し.
// https://img.atcoder.jp/data/arc/063/editorial.pdf
#include <bits/stdc++.h>
using namespace std;
using vvi = vector<vector<int>>;
using P = pair<int, int>;
#define repex(i, a, b, c) for(int i = a; i < b; i += c)
#define repx(i, a, b) repex(i, a, b, 1)
#define rep(i, n) repx(i, 0, n)
#define repr(i, a, b) for(int i = a; i >= b; i--)
#define pb push_back
#define a first
#define b second
const int LIMIT = 101010;
int d[LIMIT];   // 根 からの 距離 を 保存.
int p[LIMIT];   // 頂点に書き込んだ整数(0以上).
int l[LIMIT];   // 頂点に書き込める最小値.
int r[LIMIT];   // 頂点に書き込める最大値.
int ans[LIMIT]; // 頂点に書き込み整数.

// グラフを幅優先探索する.
// https://ja.wikipedia.org/wiki/幅優先探索
// ※bfsの動作確認用.
// @param G: グラフ.
// @param s: グラフの探索開始頂点.
// @param d: 探索開始地点からの距離.
// @return: 特に無し.
void bfs(vvi &G, int s, int* d){
    // 1. 空のキュー.
    queue<int> q;

    // 2. 訪問済みフラグ設定.
    // ※スタート地点は, 距離ゼロを指定.
    d[s] = 0;

    // 3. 探索地点 s をキュー q に追加.
    q.push(s);
    while(!q.empty()){
        // 4. キューから取り出す.
        int u = q.front();
        q.pop();

        // 5. 取り出した要素を処理.
        for(auto &e : G[u]){
            // 6. 訪問済であれば, 処理をスキップ.
            if(d[e])            continue;
            if(!d[e] && e != s) d[e] = d[u] + 1, q.push(e);
        }
    }
    return;
}

int main(){

    // 1. 入力情報.
    int N;
    scanf("%d", &N);
    vvi G(N);
    rep(i, N - 1){
        int a, b;
        scanf("%d %d", &a, &b);
        a--, b--;
        G[a].pb(b);
        G[b].pb(a);
    }
    int K, root = -1;
    scanf("%d", &K);
    rep(i, LIMIT) p[i] = -1;
    rep(i, K){
        int a, b;
        scanf("%d %d", &a, &b);
        a--;
        p[a] = b;
        if(root == -1) root = a; // 根を取得.
    }
    assert(root != -1);

    // 2. 区間初期化.
    rep(i, N) l[i] = -1010101010, r[i] = 1010101010;
    rep(i, N) if(p[i] != -1) l[i] = p[i], r[i] = p[i];

    // 3. 根 から 各頂点までの距離を計算.
    bfs(G, root, d);
    // rep(i, N) printf("%d ", d[i]);
    // puts("");

    // 4. 偶奇の制約を満たすか確認.
    int sign = p[root] & 1;
    bool f = true;
    rep(i, N){
        // すでに書き込みある頂点で確認.
        if(p[i] != -1){
            // 根 からの 距離の偶奇で分岐.
            if(d[i] & 1){
                // 根からの距離が, 奇数の場合に, 根に書かれた整数の偶奇と同じ場合.
                if((p[i] & 1) == sign){
                    f = false;
                    break;
                }
            }else{
                // 根からの距離が, 偶数の場合に, 根に書かれた整数の偶奇と異なる場合.
                if((p[i] & 1) != sign){
                    f = false;
                    break;
                }
            }
        }
    }
    if(!f){
        puts("No");
        return 0;
    }

    // 5. 根 から 遠い順, 近い順 に並び替え.
    // {距離, 頂点番号}
    priority_queue<P> fPq;
    priority_queue<P, vector<P>, greater<P>> nPq;
    rep(i, N){
        // {距離, 頂点番号}
        fPq.push({d[i], i});
        nPq.push({d[i], i});
    }

    // 6. 区間更新.
    while(!fPq.empty()){
        // 6-1. 頂点 v を一つ取り出す.
        P x = fPq.top();
        fPq.pop();

        // 6-2. 頂点 v の 頂点番号は？
        int v = x.b;

        // 6-4. 頂点 v の 親頂点 の 区間 を 更新.
        for(auto &u : G[v]){
            // 頂点 v の 親頂点 u を 選択.
            if(d[u] < d[v]){
                // 区間を更新.
                l[u] = max(l[u], l[v] - 1);
                r[u] = min(r[u], r[v] + 1);
            }
        }
    }
    // rep(i, N) printf("%d %d %d\n", i, l[i], r[i]);

    // 7. 根の区間を確認.
    if(l[root] > r[root]){
        puts("No");
        return 0;
    }

    // 8. 各頂点に書き出す整数を保存.
    while(!nPq.empty() && f){
        // 7-1. 頂点 v を一つ取り出す.
        P x = nPq.top();
        nPq.pop();

        // 7-2. 頂点 v の 頂点番号は？
        int v = x.b;

        // 7-3. 頂点 v の 値 を 設定.
        if(p[v] != -1) ans[v] = p[v];

        // 7-4. 頂点 v の 親頂点 の 区間 から, 子頂点 に 書き込む値を絞り込む.
        if(p[v] == -1){
            int pVal = 1010101010;
            for(auto &u : G[v]){
                // 頂点 v の 親頂点 u の 整数 を 保存(※親頂点は, 一つの筈).
                if(d[u] < d[v]){
                    pVal = ans[u];
                    break;
                }
            }
            assert(pVal != 1010101010);

            // 区間と照合して, 条件に合うものを設定.
            // なければ, false.
            int pLVal = pVal - 1;
            int pRVal = pVal + 1;
            if(pLVal >= l[v] && pLVal <= r[v])      ans[v] = pLVal;
            else if(pRVal >= l[v] && pRVal <= r[v]) ans[v] = pRVal;
            else                                    f = false;
        }
    }

    // 9. 出力.
    if(f){
        puts("Yes");
        rep(i, N) printf("%d\n", ans[i]);
    }else{
        puts("No");
    }
    return 0;

}

#include<cstdio>
#include<cstring>
#include<cctype>
#include<algorithm>
#include<vector>
#define maxn 100005
#define lim 18
#define inf 0x3f3f3f3f
using namespace std;

int n ,ERROR, info[maxn] , Prev[maxn * 2] , to[maxn * 2] , cnt_e , val[maxn] , sta[maxn] , rfa[maxn] , pt[maxn] , Min[maxn] , Max[maxn];
inline void Node(int u,int v){ Prev[++cnt_e] = info[u] , info[u] =cnt_e,to[cnt_e] = v; }

void dfs(int now,int ff)
{
    Min[now] = -inf , Max[now] = inf;
    if(val[now]!=0x3f3f3f3f) Min[now] = Max[now] = val[now];
	for(int i=info[now];i;i=Prev[i])
		if(to[i]!=ff)
		{
			dfs(to[i],now);
            Min[now] = max(Min[now] , Min[to[i]] - 1);
            Max[now] = min(Max[now] , Max[to[i]] + 1);
		}
	if(Min[now] > Max[now]) ERROR=1;
}

void ser(int now,int ff)
{
	if(ff) Min[now] = max(Min[now] , Min[ff] - 1) ,Max[now] = min(Max[now] , Max[ff] + 1);
	for(int i=info[now];i;i=Prev[i])
		if(to[i]!=ff)
			ser(to[i] , now);
}

int main()
{

	memset(val,0x3f,sizeof val);

	int u,v;
    scanf("%d",&n);
    for(int i=1;i<n;i++)
	{
		scanf("%d%d",&u,&v);
		Node(u,v),Node(v,u);
	}
	int k;
	scanf("%d",&k);
	for(int i=1;i<=k;i++)
	{
		scanf("%d%d",&u,&v);
		val[u] = v;
		pt[i] = u;
	}

	dfs(u , 0);
	if(ERROR) puts("No");
	else
	{
		puts("Yes");
        ser(u , 0);
        for(int i=1;i<=n;i++)
			printf("%d\n",Min[i]);
	}
}

