        if(mi[to]<=ans[x]+1&&ans[x]+1<=mx[to])ans[to]=ans[x]+1;
        else if(mi[to]<=ans[x]-1&&ans[x]-1<=mx[to])ans[to]=ans[x]-1;
        else {
            cout<<NO<<endl;
            exit(0);
        }
        dfs2(to,x);
    }
