        if(to==p)continue;
        dfs(to,x);
        chmin(mx[x],mx[to]+1);
        chmax(mi[x],mi[to]-1);
    }
    if(a[x]==-1&&x!=0)return;
    if(a[x]!=-1){
        ans[x]=a[x];
        mx[x]=mi[x]=a[x];
    }else{
        ans[x]=mx[x];
    }
    dfs2(x,p);
}

// ll N, vl A, vl B, ll K, vl V, vl P
// 残りのすべての頂点に書き込む整数を工夫することで木が条件を満たすようにできるならば Yes を、できないならば No を出力せよ。
// 条件を満たせる場合、追加で N 行出力せよ。このうちの v (1 ≦ v ≦ N) 行目には、頂点 v に書かれる整数を出力せよ。条件を満たすような整数の書き込み方が複数ある場合、そのうちいずれかひとつを出力すればよい。
void solve(){
    g.resize(N);
    rep(i,N-1){
        g[A[i]-1].push_back(B[i]-1);
        g[B[i]-1].push_back(A[i]-1);
    }

    mx.resize(N,INF);
    mi.resize(N,0);
    a.resize(N,-1);
    ans.resize(N,-1);
    rep(i,K)a[V[i]-1]=P[i];
    dfs();

    cout<<YES<<endl;
    rep(i,N)cout<<ans[i]<<endl;
}

