int n, k;
vector<int> G[100010];
int ma[100010], mi[100010], p[100010], depth[100010], up[100010];
bool seen[100010];

void boo() {
    cout << "No" << endl;
    exit(0);
}

struct node {
    int v, par;
};

typedef pair<int, int> pii;
queue<node> q1;
priority_queue<pii> pq;

void bfs() {
    while (!q1.empty()) {
        int v = q1.front().v;
        int par = q1.front().par;
        q1.pop();

        for (const int& w : G[v]) {
            if (w == par) continue;

            up[w] = v;
            depth[w] = depth[v] + 1;

            if (p[w] != MOD) {
                pq.push({depth[w], w});
                ma[w] = p[w];
                mi[w] = p[w];
            } else {
                // free
                ma[w] = ma[v] + 1;
                mi[w] = mi[v] - 1;
            }

            q1.push({w, v});
        }
    }
}

int main() {
    cin >> n;
    rep(i, n - 1) {
        int a, b;
        cin >> a >> b;
        a--;
        b--;
        G[a].push_back(b);
        G[b].push_back(a);
    }

    rep(i, n) p[i] = MOD;

    int vv;
    cin >> k;
    rep(i, k) {
        int x;
        cin >> vv;
        cin >> x;
        ma[vv] = mi[vv] = p[vv] = x;
        seen[vv] = true;
    }

    depth[vv] = 0;
    q1.push({vv, -1});
    bfs();

    while (!pq.empty()) {
        int w = pq.top().second;
        int v = up[w];
        //cout << pq.top().first << " " << w << endl;

        pq.pop();

        if(ma[v] % 2 == ma[w] % 2) boo();
        if(mi[v] % 2 == mi[w] % 2) boo();

        ma[v] = min(ma[v], ma[w] + 1);
        mi[v] = max(mi[v], mi[w] - 1);

        if(ma[v] < mi[v]) boo();
        if(seen[v]) continue;
        if(v == vv) continue;
        pq.push({depth[v], v});
        seen[v] = true;
    }

    rep(i, n) {
        if(ma[i] < mi[i]) boo();
        if(p[i] != MOD){
            if(ma[i] != p[i]) exit(1);
        }
    }
    cout << "Yes" << endl;
    rep(i, n) cout << ma[i] << endl;
}

