	Range(const std::pair<T, T>& pair, bool inf_inclusive = true, bool sup_inclusive = false);	// T, Tでなくてもいい
	Range(const Range& other);

	Range& operator=(const Range& other);
	Range& operator&=(const Range& other);

	bool Is_empty() const;
	std::string To_string() const;
	T Width() const;

	bool Has(const T& point) const;
	bool Includes(const Range& other) const;
};

template<class T>
bool operator==(const Range<T>& left, const Range<T>& right);
template<class T>
bool operator!=(const Range<T>& left, const Range<T>& right);
template<class T>
const Range<T> operator&(const Range<T>& left, const Range<T>& right);
template<class T>
std::ostream& operator<<(std::ostream& ost, const Range<T>& range);

/* ここを Range(0, 0) とすると無限ループなので注意 */
template<class T>
inline Range<T> Range<T>::Empty_range() {
	return Range();
}

/* 空集合であったら [0, 0) の基本形に直す */
template<class T>
inline void Range<T>::Reduce() {
	if (Is_empty()) {
		*this = Empty_range();
	}
}

template<class T>
inline bool Range<T>::Equal(const Range& left, const Range& right) {
	return left.inf_m == right.inf_m
		&& left.sup_m == right.sup_m
		&& left.inf_inclusive_m == right.inf_inclusive_m
		&& left.sup_inclusive_m == right.sup_inclusive_m;
}

template<class T>
inline Range<T>::Range()
	:inf_m(0), sup_m(0), inf_inclusive_m(true), sup_inclusive_m(false) {
}

template<class T>
inline Range<T>::Range(const T& inf, const T& sup, bool inf_inclusive, bool sup_inclusive)
	: inf_m(inf), sup_m(sup), inf_inclusive_m(inf_inclusive), sup_inclusive_m(sup_inclusive) {
	Reduce();
}

template<class T>
inline Range<T>::Range(const std::pair<T, T>& pair, bool inf_inclusive, bool sup_inclusive)
	: inf_m(pair.first), sup_m(pair.second), inf_inclusive_m(inf_inclusive), sup_inclusive_m(sup_inclusive) {
	Reduce();
}

template<class T>
inline Range<T>::Range(const Range& other)
	: inf_m(other.inf_m), sup_m(other.sup_m),
	inf_inclusive_m(other.inf_inclusive_m), sup_inclusive_m(other.sup_inclusive_m) {
}

template<class T>
inline Range<T>& Range<T>::operator=(const Range& other) {
	inf_m = other.inf_m;
	sup_m = other.sup_m;
	inf_inclusive_m = other.inf_inclusive_m;
	sup_inclusive_m = other.sup_inclusive_m;
	return *this;
}

template<class T>
inline Range<T>& Range<T>::operator&=(const Range& other) {
	if (inf_m < other.inf_m || (inf_m == other.inf_m && !other.inf_inclusive_m)) {
		inf_m = other.inf_m;
		inf_inclusive_m = other.inf_inclusive_m;
	}
	if (sup_m > other.sup_m || (sup_m == other.sup_m && !other.sup_inclusive_m)) {
		sup_m = other.sup_m;
		sup_inclusive_m = other.sup_inclusive_m;
	}
	Reduce();
	return *this;
}

template<class T>
inline bool Range<T>::Is_empty() const {
	return inf_m > sup_m || (inf_m == sup_m && (!inf_inclusive_m || !sup_inclusive_m));
}

template<class T>
inline std::string Range<T>::To_string() const {
	if (Is_empty()) return "(Empty)";
	std::ostringstream sst;
	sst << (inf_inclusive_m ? '[' : '(')
		<< inf_m
		<< ", "
		<< sup_m
		<< (sup_inclusive_m ? ']' : ')');
	return sst.str();
}

template<class T>
inline T Range<T>::Width() const {
	return sup_m - inf_m;
}

template<class T>
inline bool Range<T>::Has(const T& point) const {
	return (inf_inclusive_m ? point >= inf_m : point > inf_m)
		&& (sup_inclusive_m ? point <= sup_m : point < sup_m);
}

/* other == (*this) & other の判定でもいいかも */
/* 逆の判定も使いたい */
template<class T>
inline bool Range<T>::Includes(const Range& other) const {
	if (other.Is_empty()) return true;
	return (inf_inclusive_m || !other.inf_inclusive_m ? other.inf_m >= inf_m : other.inf_m > inf_m)
		&& (sup_inclusive_m || !other.sup_inclusive_m ? other.sup_m <= sup_m : other.sup_m < sup_m);
}

template<class T>
inline bool operator==(const Range<T>& left, const Range<T>& right) {
	return Range<T>::Equal(left, right);
}

template<class T>
inline bool operator!=(const Range<T>& left, const Range<T>& right) {
	return !Range<T>::Equal(left, right);
}

template<class T>
inline const Range<T> operator&(const Range<T>& left, const Range<T>& right) {
	Range<T> ret(left);
	ret &= right;
	return ret;
}

template<class T>
inline std::ostream& operator<<(std::ostream& ost, const Range<T>& range) {
	ost << range.To_string();
	return ost;
}

