using namespace std;
typedef long long llint;

struct Node {
    int lower, count;
    Node() : lower(0), count(0) {}
    Node(int lower, int count) : lower(lower), count(count) {}
};

bool update(int n, int v, vector<vector<int> > &tree, vector<Node> &nodes) {
    stack<pair<int, int> >  st;
    vector<bool>    visited(n+1, false);

    for(auto it=tree[v].begin(); it!=tree[v].end(); ++it) {
        st.push(pair<int, int>(*it, v));
    }
    visited[v] = true;

    while(!st.empty()) {
        int cur = st.top().first, prev = st.top().second; st.pop();
        for(auto it=tree[cur].begin(); it!=tree[cur].end(); ++it) {
            if(visited[*it])    continue;
            else {
                st.push(pair<int, int>(*it, cur));
                visited[*it] = true;
            }
        }
        if(nodes[cur].count == 0) {
            nodes[cur].count = nodes[prev].count + 1;
            nodes[cur].lower = nodes[prev].lower - 1;
        }
        else {
            if(max(nodes[cur].lower, nodes[prev].lower-1)
               <= min(nodes[cur].lower+nodes[cur].count*2-2,
                      nodes[prev].lower-1+nodes[prev].count*2)) {
                nodes[cur].lower = max(nodes[cur].lower, nodes[prev].lower-1);
                nodes[cur].count =
                    (min(nodes[cur].lower+nodes[cur].count*2-2,
                        nodes[prev].lower-1+nodes[prev].count*2)
                    - max(nodes[cur].lower, nodes[prev].lower-1))/2 + 1;
            }
            else    return false;
        }
    }
    return true;
}

bool solve(int n, int k, vector<vector<int> > &tree, vector<Node> &nodes,
           vector<int> &written) {
    for(auto it=written.begin(); it!=written.end(); ++it) {
        if(!update(n, *it, tree, nodes))   return false;
    }
    return true;
}

int main() {
    int n, a, b;
    cin >> n;

    vector<vector<int> >    tree(n+1);
    vector<Node>    nodes(n+1);

    repeat(i, n-1) {
        cin >> a >> b;
        tree[a].push_back(b);
        tree[b].push_back(a);
    }

    int k, v, p;
    cin >> k;
    vector<int> written(k);
    repeat(i, k) {
        cin >> v >> p;
        nodes[v].lower = p;
        nodes[v].count = 1;
        written[i] = v;
    }

    bool ret = solve(n, k, tree, nodes, written);

    cout << (ret?"Yes":"No") << endl;
    if(ret) {
        for(auto it=nodes.begin(); it!=nodes.end(); ++it) {
            cout << it->lower << endl;
        }
    }
    return 0;
}

