const int maxn = 100005;
const int inf = 1e9;
int n, m, ed;
int he[maxn], L[maxn], R[maxn], ans[maxn];
struct Edge{
  int v, nx;
  Edge(){;}
  Edge(int _v, int _nx){v = _v, nx = _nx;}
}e[maxn << 1];
void Add(int u, int v){
  e[++ed] = Edge(v, he[u]);he[u] = ed;
}

void Dfs(int x, int fa){
  for(int i = he[x], v;i;i = e[i].nx){
    v = e[i].v;
    if(v == fa)continue;
    Dfs(v, x);
    L[x] = max(L[x], L[v] - 1);
    R[x] = min(R[x], R[v] + 1);
  }
}
void Dfss(int x, int fa){
  for(int i = he[x], v;i;i = e[i].nx){
    v = e[i].v;
    if(v == fa)continue;
    L[v] = max(L[v], L[x] - 1);
    R[v] = min(R[v], R[x] + 1);
    Dfss(v, x);
  }
}
void Solve(int x, int fa){
  for(int i = he[x], v;i;i = e[i].nx){
    v = e[i].v;
    if(v == fa)continue;
    if(ans[x] + 1 <= R[v])ans[v] = ans[x] + 1;
    else ans[v] = ans[x] - 1;
    Solve(v, x);
  }
}

int main(){
  scanf("%d", &n);
  for(int i = 1;i <= n;++i){
    L[i] = -inf;
    R[i] = inf;
  }
  for(int i = 1, u, v;i < n;++i){
    scanf("%d%d", &u, &v);
    Add(u, v);Add(v, u);
  }
  scanf("%d", &m);
  for(int i = 1, x, y;i <= m;++i){
    scanf("%d%d", &x, &y);
    L[x] = R[x] = y;
  }
  Dfs(1, 1);Dfss(1, 1);
  for(int i = 1;i <= n;++i){
    // cout<<"get "<<i<<' '<<L[i]<<' '<<R[i]<<endl;
    if(L[i] > R[i]){
      puts("No");
      return 0;
    }
  }
  ans[1] = L[1];
  Solve(1, 1);
  puts("Yes");
  for(int i = 1;i <= n;++i)printf("%d\n", ans[i]);
  return 0;
}

