static const int INF = 0x3f3f3f3f; static const long long INFL = 0x3f3f3f3f3f3f3f3fLL;
typedef vector<int> vi; typedef pair<int, int> pii; typedef vector<pair<int, int> > vpii; typedef long long ll;
template<typename T, typename U> static void amin(T &x, U y) { if(y < x) x = y; }
template<typename T, typename U> static void amax(T &x, U y) { if(x < y) x = y; }


vector<int> t_parent;
vector<int> t_ord;

void tree_getorder(const vector<vi> &g, int root) {
	int n = g.size();
	t_parent.assign(n, -1);
	t_ord.clear();

	vector<int> stk; stk.push_back(root);
	while(!stk.empty()) {
		int i = stk.back(); stk.pop_back();
		t_ord.push_back(i);
		for(int j = (int)g[i].size() - 1; j >= 0; j --) {
			int c = g[i][j];
			if(t_parent[c] == -1 && c != root) {
				t_parent[c] = i;
				stk.push_back(c);
			}
		}
	}
}

int main() {
	int N;
	while(~scanf("%d", &N)) {
		vector<vector<int> > g(N);
		for(int i = 0; i < N - 1; ++ i) {
			int u, v;
			scanf("%d%d", &u, &v), -- u, -- v;
			g[u].push_back(v);
			g[v].push_back(u);
		}
		int K;
		scanf("%d", &K);
		vector<pair<int, int>> ranges(N, make_pair(-INF, INF));
		vector<int> parity(N, 3);
		rep(i, K) {
			int u; int p;
			scanf("%d%d", &u, &p), -- u;
			ranges[u] = { p, p };
			parity[u] = 1 << (p & 1);
		}
		tree_getorder(g, 0);
		for(int ix = (int)t_ord.size() - 1; ix > 0; -- ix) {
			int i = t_ord[ix], p = t_parent[i];
			amax(ranges[p].first, ranges[i].first - 1);
			amin(ranges[p].second, ranges[i].second + 1);
			parity[p] &= (parity[i] & 1) << 1 | (parity[i] & 2) >> 1;
		}
		vector<int> ans(N, -INF);
		bool ok = true;
		for(int ix = 0; ix < (int)t_ord.size(); ++ ix) {
			int i = t_ord[ix], p = t_parent[i];
			auto r = ranges[i];
			ok &= r.first <= r.second;
			ok &= parity[i] != 0;
			if(!ok) break;
			if(p != -1) {
				amax(r.first, ans[p] - 1);
				amin(r.second, ans[p] + 1);
			}
			assert(r.first <= r.second && (p == -1 || (ans[p] & 1) != (r.first & 1)));
			ans[i] = r.first;
		}
		puts(ok ? "Yes" : "No");
		if(ok) {
			for(int i = 0; i < N; ++ i)
				printf("%d\n", ans[i]);
		}
	}
	return 0;
}

