p dfs(ll v,p fcap,ll from){
	if(fcap.second+1<cap[v].first || cap[v].second< fcap.first-1 || (odd[v]!=-1&&from!=-1&&odd[v]==odd[from]) ){
		puts("No");
		return p(-INF,-INF);
	}
	cap[v].first=max(cap[v].first,fcap.first-1);
	cap[v].second=min(cap[v].second,fcap.second+1);
	odd[v]=(cap[v].first%2+2)%2;
	if(cap[v].first>cap[v].second || (cap[v].first%2+2)%2 != (cap[v].second%2+2)%2 ){
		puts("No");
		return p(-INF,-INF);
	}
	for(ll i=0;i<G[v].size();i++){
		if(G[v][i]==from) continue;
		p gen=dfs( G[v][i],cap[v],v );
		if(gen.first==-INF&&gen.second==-INF) return gen;
		cap[v].first=max(cap[v].first,gen.first-1);
		cap[v].second=min(cap[v].second,gen.second+1);
		if(gen.second+1<cap[v].first || cap[v].second< gen.first-1 || (odd[v]==odd[G[v][i]]) ){
			puts("No");
			return p(-INF,-INF);
		}
	}
	return cap[v];
}

