vector<P> sec;
vector<bool> col;
bool ok = true;

P dfs(int now, int prev, bool nowc, const vvi &tr, const vi &d) {
  col[now] = nowc;
  P p = {-INF, INF};
  REP(i, SZ(tr[now])) {
    int nxt = tr[now][i];
    if(nxt == prev) continue;
    P tmp = dfs(nxt, now, !nowc, tr, d);
    chmax(p.first, tmp.first);
    chmin(p.second, tmp.second);
  }
  if(p.second < p.first) ok = false;

  if(d[now] != -1) {
    ok &= p.first <= d[now] && d[now] <= p.second;
    sec[now] = {d[now], d[now]};
    return {d[now]-1, d[now]+1};
  } else {
    sec[now] = p;
    return {p.first-1, p.second+1};
  }
}

vector<int> ans;

void dfs2(int now, int prev, int l, int r, const vvi &tr) {
  P tmp = {max(l, sec[now].first), min(r, sec[now].second)};
  ans[now] = tmp.first;
  REP(i, SZ(tr[now])) {
    int nxt = tr[now][i];
    if(nxt == prev) continue;
    dfs2(nxt, now, tmp.first-1, tmp.first+1, tr);
  }
}

