int dfs( int u, int p )
{
	vis[u] = 1;
	if( val[u] != -1 ) { rang[u] = {val[u], val[u]}; return 0; }
	rang[u] = {INT_MIN, INT_MAX};
	for( auto v : adj[u] )
	{
		if( v != p ) {
			if( dfs(v, u) )
				return 1;
			if( rang[v].first == INT_MIN )
				continue;
			if( rang[u].first == INT_MIN ) {
				rang[u] = {rang[v].first - 1, rang[v].first + 1};
			}
			if( ( rang[u].first - (rang[v].first-1) ) %2 != 0 )
				return 1;
			rang[u].first = max(rang[u].first, rang[v].first-1);
			rang[u].second = min(rang[u].second, rang[v].second+1);
			if( rang[u].second < rang[u].first )
				return 1;
		}
	}
	return 0;
}

void assign( int u, int p ) {
	if( val[u] != -1 ) return;
	if( p == 0 ) {
		val[u] = rang[u].first;
	} else {
		if( val[p] - 1 <= rang[u].first ) val[u] = val[p] - 1;
		else val[u] = val[p] + 1;
	}
	for( auto v : adj[u] )
	{
		if( v != p ) {
			assign(v, u);
		}
	}
}

