        lmt.S=max(lmt.S,ret.S.S);
        if(lmt.F<lmt.S || !ret.F){return {false,{0,0}};}
    }
    v[where].F=lmt.F; v[where].S=lmt.S;
    lmt.F++; lmt.S--;
    return {true,lmt};
}

