		if(f(c-1,child[k][i])==0 && f(c+1,child[k][i])==0) {
			return d[k][c]=0;
		}
	}
	return d[k][c]=1;
}

void trace(int c, int k) {
	res[k]=c;
	for(int i=0;i<child[k].size();i++)  {
		if(f(c-1,child[k][i])) {
			trace(c-1,child[k][i]);
		} else {
			trace(c+1,child[k][i]);
		}
	}
}

bool visit[100001];

void dfs(int k) {
	visit[k]=true;
	for(int i=0;i<con[k].size();i++) {
		int v=con[k][i];
		if(!visit[v]) {
			child[k].push_back(v);
			dfs(v);
		}
	}
}

