vector < int > G[N];

void dfs(int ,int);
void solve(int ,int);

int main(){
	scanf("%d", &n);
	for(int i = 1; i < n; ++i){
		int u, v; scanf("%d%d", &u, &v);
		G[u].pb(v); G[v].pb(u);
	}
	scanf("%d", &k); memset(ty, -1, sizeof ty);
	int pos;
	for(int i = 1; i <= k; ++i){
		int p; scanf("%d%d", &pos, &p);
		res[pos] = l[pos] = r[pos] = p; ty[pos] = p & 1;
	}
	for(int i = 1; i <= n; ++i){
		if(ty[i] != -1) continue;
		l[i] = -(N + N); r[i] = N + N;
	}
	dfs(pos, 0); solve(pos, 0); puts("Yes");
	for(int i = 1; i <= n; ++i)
		printf("%d\n", l[i]);
	return 0;
}

void dfs(int u, int fa){
	if(ty[fa] != -1){
		l[u] = max(l[fa] - 1, l[u]); 
		r[u] = min(r[u], r[fa] + 1);
		ty[u] = ty[fa] ^ 1;
	}
	int sz = G[u].size();
	for(int i = 0; i < sz; ++i){
		int v = G[u][i];
		if(v == fa) continue;
		dfs(v, u);
		l[u] = max(l[v] - 1, l[u]);
		r[u] = min(r[u], r[v] + 1);
		if(ty[u] == -1) ty[u] = ty[v] ^ 1;
		else if(ty[u] != (ty[v] ^ 1)){
			puts("No"); exit(0);
		}
	}
	if(l[u] > r[u]){
		puts("No"); exit(0);
	}
	return ;
}

void solve(int u, int fa){
	if((l[u] & 1) != ty[u]) ++l[u];
	l[u] = r[u]; int sz = G[u].size();
	for(int i = 0; i < sz; ++i){
		int v = G[u][i];
		if(v == fa) continue;
		l[v] = max(l[u] - 1, l[v]); r[v] = min(r[u] + 1, r[v]);
		solve(v, u);
	}
	return ;
}

