	ans[u]=x;
	for(int p=now[u],v=son[p];p;p=pre[p],v=son[p])
		if(v!=fa) {
			if(x-1>=l[v]&&x-1<=r[v])check(u,v,x-1);
			else check(u,v,x+1);
		}
}

