using namespace std;
struct range
{
    // 0 represents normal one; 1 represents empty one; 2 represents the universal one
    int tp,begin,end;
    range():tp(2),begin(),end(){}
    range(int _tp,int _begin,int _end):tp(_tp),begin(_begin),end(_end){}
    range& operator&=(const range &rhs)
    {
        if (rhs.tp==1)
            tp=1;
        else if (rhs.tp==0)
        {
            if (tp==2)
                *this=rhs;
            else if (tp==0)
            {
                if ((begin&1)!=(rhs.begin&1)||end<rhs.begin||begin>rhs.end)
                    tp=1;
                else
                {
                    begin=max(begin,rhs.begin);
                    end=min(end,rhs.end);
                }
            }
        }
        return *this;
    }
    bool inrange(int val)
    {
        if (tp==1)
            return false;
        if (tp==2)
            return true;
        return (val&1)==(begin&1)&&val>=begin&&val<=end;
    }
};
range dp[100001];
vector<int> mp[100001];
int val[100001],ans[100001];
bool vst[100001],has[100001];
void dfs(int k)
{
    vst[k]=true;
    for (auto adj:mp[k])
    {
        if (has[adj])
            dp[k]&=range(0,val[adj]-1,val[adj]+1);
        else if (!vst[adj])
        {
            dfs(adj);
            dp[k]&=range(dp[adj].tp,dp[adj].begin-1,dp[adj].end+1);
        }
    }
}
void recover(int k,int p)
{
    if (p==-1)
        val[k]=dp[k].tp==2?0:dp[k].begin;
    else
        val[k]=dp[k].inrange(val[p]-1)?val[p]-1:val[p]+1;
    has[k]=true;
    for (auto adj:mp[k])
    {
        if (!has[adj])
            recover(adj,k);
    }
}
int main()
{
    int n;
    scanf("%d",&n);
    for (int i=1;i<n;++i)
    {
        int u,v;
        scanf("%d%d",&u,&v);
        mp[u].push_back(v);
        mp[v].push_back(u);
    }
    int k;
    scanf("%d",&k);
    while (k--)
    {
        int v,p;
        scanf("%d%d",&v,&p);
        val[v]=p;
        has[v]=true;
    }
    for (int i=1;i<=n;++i)
        if (!has[i]&&!vst[i])
        {
            dfs(i);
            if (dp[i].tp==1)
            {
                printf("NO\n");
                return 0;
            }
            recover(i,-1);
        }
    printf("YES\n");
    for (int i=1;i<=n;++i)
        printf("%d\n",val[i]);
    return 0;
}

