struct Node{
    vector<Node*> nodes;
    int mini = -M, maxi = M;
    bool even;
    void dfs(Node* from = nullptr){
        for(Node* n : nodes){
            if(n == from){ continue; }
            n -> dfs(this);
            mini = max(mini, n -> mini - 1);
            maxi = min(maxi, n -> maxi + 1);
        }
    }
    void dfs2(Node* from = nullptr){
        for(Node* n : nodes){
            if(n == from){ continue; }
            n -> mini = max(n -> mini, mini - 1);
            n -> maxi = min(n -> maxi, maxi + 1);
            n -> dfs2(this);
        }
    }
    bool judge(Node* from = nullptr, bool fb = false){
        if(mini > maxi){ return false; }
        even = mini % 2 == 0;
        if(from && fb == even){
            return false;
        }
        for(Node* n : nodes){
            if(n == from){ continue; }
            if(!n -> judge(this, even)){
                return false;
            }
        }
        return true;
    }
    void propagate(Node* from = nullptr){
        if(mini == -M && !from){ return; }
        auto size = maxi - mini;
        if(mini == -M){
            even = !from -> even;
            mini = from -> mini - 1;
            maxi = from -> maxi + 1;
        }else if(from){
            mini = max(mini, from -> mini - 1);
            maxi = min(maxi, from -> maxi + 1);
            if(even == from -> even || mini > maxi){
                cout << "No" <<endl;
                exit(0);
            }
        }

        if(from && size == maxi - mini){ return; }
        for(Node* n : nodes){
            n -> propagate(this);
        }
    }
    void set(int num){
        mini = maxi = num;
        even = !(num % 2);
    }
    void print(){
        cout << mini << endl;
    }
};
