bool possible = true;

void dfs(int s, int p, bool up) {

    for(int i=0;i<g[s].size();i++) {
        if(g[s][i] != p) {
            if(v[g[s][i]] != INT_MIN) {
                if(abs(v[g[s][i]]-v[s]) != 1) {
                    possible = false;
                    return;
                }
                dfs(g[s][i], s, not up);
                if(not possible) return;
            } else {
                if(up) {
                    v[g[s][i]] = v[s]+1;
                } else v[g[s][i]] = v[s]-1;
                dfs(g[s][i], s, not up);
                if(not possible) return;
            }
        }
    }
}

