#include<bits/stdc++.h>
using namespace std;
#define int long long 

const int MAX_N = 101000;
const int inf = 1e18;
// 先ずはTLEを投げる
int low[MAX_N];
int high[MAX_N];

signed main(void){

  int N; cin >> N;

  vector<bool> given(N,false);
  vector<vector<int>> to(N);
  for(int i = 0; i < MAX_N; i++){ low[i] = inf; high[i] = inf;}
  // infは未確定
  for(int i = 1; i < N; i++){ 
    int a,b; cin >> a >> b; a--; b--;
    to[a].push_back(b); to[b].push_back(a);
  }
  int K; cin >> K;
  int pos;
  for(int i = 0; i < K; i++){
    int v,p; cin >> v >> p; v--; pos = v;
    given[v] = true;
    low[v] = p; high[v] = p;
  } 
  bool contradiction = false;
  //ある確定した１つの頂点posからBFSで、残りの点と矛盾なく構成できるかを調べていく
  queue<tuple<int,int,int>> Q; Q.push(make_tuple(pos,low[pos],high[pos]));

  vector<bool> examined(N,false);
  examined[pos] = true;

  while(!Q.empty()){ 
    auto p = Q.front(); Q.pop();
    int now = get<0>(p);
    for(auto next : to[now]){ 

      if(examined[next]){ continue;}

      if( low[next] != inf ){ //整合するかを確かめる
        int l = get<1>(p); int r = get<2>(p);
        if( !(l-1 <= low[next] && high[next] <= r+1 && (l%2 != low[next]) && (r%2 != high[next]) )){ //この時矛盾
          contradiction = true;
        }
        //整合していた場合には,一応そこから出発
        Q.push(make_tuple(next,low[next],high[next]));
        examined[next] = true;
      }
      else{ //まだ未到達だった場合

        low[next] = low[now]-1LL; high[next] = high[now]+1LL;
        Q.push(make_tuple(next,low[next],high[next]));
        examined[next] = true;
      }
    }//for-u
  }//while

  if(contradiction){ cout << "No" << endl; return 0;}
  // 以下、必ず構成できる場合に具体的に構成していく
  cout << "Yes" << endl;


  for(int i = 0; i < N; i++){ 
    if(!given[i]){ continue;}
    // vから範囲を狭めていく
    vector<bool> visited(N,false); visited[i] = true;
    queue<int> Q; Q.push(i);
    while(!Q.empty()){ 
      auto p = Q.front(); Q.pop();
      for(auto u : to[p]){
        if(visited[u]){ continue;}
        visited[u] = true;
        low[u] = max(low[u],low[p]-1);
        high[u] = min(high[u],high[p]+1);
      }
    }
  }

  for(int i = 0; i < N; i++){ 
    cout << low[i] << endl; 
    //ここで最小値だけを取ってしまうと、偶奇が合わない場合が存在しうる
  }


  return 0;
}

#include <cstdio>
#include <queue>
#include <vector>
#include <algorithm>
#include <iostream>
using namespace std;
const int SIZE=100005;
const int INF=100000005;
vector<int> mp[SIZE];
int id[SIZE],L[SIZE],R[SIZE];
bool ok=true;
void solve(int v,int p){
    if(id[v]==-1){
        L[v]=-INF;
        R[v]=INF;
    }
    else{
        L[v]=R[v]=id[v];
    }
    for(int i=0;i<mp[v].size();i++){
        int to=mp[v][i];
        if(to==p) continue;
        solve(to,v);
        if(L[to]<-INF/2) continue;
        if(!(L[v]<-INF/2)){
            if(L[to]%2==L[v]%2){
                ok=false;
                return;
            }
        }
        L[v]=max(L[to]-1,L[v]);
        R[v]=min(R[to]+1,R[v]);
        if(L[v]>R[v]){
            ok=false;
            return;
        }
    }
}
void make(int v,int p){
    for(int i=0;i<mp[v].size();i++){
        int to=mp[v][i];
        if(to==p) continue;
        if(id[to]==-1){
            if(L[to]<=id[v]+1 && id[v]+1<=R[to]){
            	id[to]=id[v]+1;
			}
			else id[to]=id[v]-1;
        }
        make(to,v);
    }
}
int main(){
    int n,k;
    cin>>n;
    for(int i=0;i<n-1;i++){
        int a,b;
        cin>>a>>b;
        a--,b--;
        mp[a].push_back(b);
        mp[b].push_back(a);
        id[i]=-1;
    }
    id[n-1]=-1;
    cin>>k;
    for(int i=0;i<k;i++){
        int v,p;
        cin>>v>>p;
        v--;
        id[v]=p;
    }
    solve(0,-1);
    if(!ok) puts("No");
    else{
        puts("Yes");
        id[0]=L[0];
        make(0,-1);
    }
    return 0;
}

