#include<bits/stdc++.h>
using namespace std;
const int maxn=1e5+5,inf=0x3f3f3f3f;
int n,k,len=0,lin[maxn]={},val[maxn];
priority_queue< pair<int,int> > q;
struct edge
{
	int y,next;
}e[2*maxn];
inline void insert(int xx,int yy)
{
	e[++len].next=lin[xx];
	lin[xx]=len;
	e[len].y=yy;
}
inline bool vol()
{
	while(!q.empty())
	{
		int seat=q.top().second;q.pop();
		for(int i=lin[seat];i;i=e[i].next)
		{
			if(val[e[i].y]<inf&&abs(val[e[i].y]-val[seat])==1) continue;
			else if(val[e[i].y]<inf) return 0;
			val[e[i].y]=val[seat]-1;q.push(make_pair(val[e[i].y],e[i].y));
		}
	}
	return 1;
}
inline int dread()
{
	int x=0,f=1;
	char ch=getchar();
	while(ch<'0'||ch>'9')
	{
		if(ch=='-') f=-1;
		ch=getchar();
	}
	while(ch>='0'&&ch<='9')
	{
		x=(x<<1)+(x<<3)+(ch^48);
		ch=getchar();
	}
	return x*f;
}
inline void in()
{
	n=dread();
	for(int i=1,a,b;i<n;i++) a=dread(),b=dread(),insert(a,b),insert(b,a);
	k=dread();
	memset(val,inf,sizeof(val));
	for(int i=1;i<=k;i++) val[dread()]=dread(); 
}
inline void work()
{
	for(int i=1;i<=n;i++) if(val[i]<inf) q.push(make_pair(val[i],i));
}
inline void out()
{
	if(vol()) puts("Yes");
	else {puts("No");return;}
	for(int i=1;i<=n;i++) printf("%d\n",val[i]);
}
int main()
{
//	freopen(".in","r",stdin);
//	freopen(".out","w",stdout);
	in();
	work();
	out();
	return 0;
}

#pragma GCC target ("avx2")
