#pragma GCC optimize ("O3")
#include "bits/stdc++.h"
#include <unordered_set>
#include <unordered_map>
#include <random>
using namespace std;
typedef long long ll;
const ll MOD = 1'000'000'007LL; /*998'244'353LL;*/
#define pb push_back
#define mp make_pair
#define all(x) (x).begin(), (x).end()
#define rep(i, n) for(int (i)=0; (i)<(n); (i)++)
const int dx[4]={ 1,0,-1,0 };
const int dy[4]={ 0,1,0,-1 };

int N;
vector<int> e[100000];
int K;
int P[100000];

int siz[100000];
bool vis[100000] ={};

int size(int v, int p){
    siz[v] = 1;
    rep(i, e[v].size()){
        if(e[v][i] == p || vis[e[v][i]]) continue;
        siz[v] += size(e[v][i], v);
    }
    return siz[v];
}

int find_centroid(int v, int p, int s){
    int M = s-siz[v]; int idx = v;
    rep(i, e[v].size()){
        if(e[v][i] == p || vis[e[v][i]]) continue;
        if(siz[e[v][i]] > M){
            M = siz[e[v][i]];
            idx = e[v][i];
        }
    }
    if(M <= s/2) return v;
    else return find_centroid(idx, v, s);
}

pair<int, int> range[100000];
pair<int,int> dfs(int v, int p){
    if(vis[v]) return range[v];
    pair<int, int> ret ={ -1e7, 1e7 };
    if(P[v] != -1) ret ={ P[v],P[v] };
    rep(i, e[v].size()){
        if(e[v][i] == p) continue;
        pair<int,int> t = dfs(e[v][i], v);
        t.first--; t.second++;
        if(t.second < ret.first || ret.second < t.first){
            cout << "No" << endl;
            exit(0);
        }
        ret ={ max(ret.first,t.first),min(ret.second, t.second) };
    }
    return ret;
}

void solve(int v){
    size(v, -1);
    int c = find_centroid(v, -1, size(v,-1));
    P[c] = dfs(c, -1).first;
    range[c] ={ P[c], P[c] };
    vis[c] = true;
    rep(i, e[c].size()){
        if(vis[e[c][i]]) continue;
        solve(e[c][i]);
    }
}

void binary_check(int v, int p, int d){
    if(P[v] != -1 && d != P[v]&1){
        cout << "No" << endl;
        exit(0);
    }
    rep(i, e[v].size()){
        if(e[v][i] == p) continue;
        binary_check(e[v][i], v, d^1);
    }
}

signed main(){
    cin >> N;
    rep(i, N-1){
        int a, b;
        cin >> a >> b;
        a--; b--;
        e[a].pb(b);
        e[b].pb(a);
    }
    memset(P, -1, sizeof(P));
    cin >> K;
    rep(i, K){
        int v, p;
        cin >> v >> p;
        P[v-1] = p;
    }

    rep(i, N){
        if(P[i] != -1){
            binary_check(i, -1, P[i]&1);
            break;
        }
    }

    solve(0);
    cout << "Yes" << endl;
    rep(i, N) cout << P[i] << endl;
}

