template<class T> T gcd(T a, T b) { return b ? gcd(b, a % b) : a; }
template<class T> T lcm(T a, T b) { return a / gcd(a, b) * b; }
ll mod_pow(ll a, ll n, ll mod) {
	ll ret = 1;
	ll p = a % mod;
	while (n) {
		if (n & 1) ret = ret * p % mod;
		p = p * p % mod;
		n >>= 1;
	}
	return ret;
}
template<class T> T extgcd(T a, T b, T& x, T& y) { for (T u = y = 1, v = x = 0; a;) { T q = b / a; swap(x -= q * u, u); swap(y -= q * v, v); swap(b -= q * a, a); } return b; }
template<class T> T mod_inv(T a, T m) { T x, y; extgcd(a, m, x, y); return (m + x % m) % m; }

using Pii = pair<int, int>;
using Pll = pair<ll, ll>;

const Pii INVALID(-ten(9), -ten(9));
bool ok = true;
vector<int> e[ten(5)];

Pii merge(Pii parent, Pii child) {
	if (parent == INVALID || child == INVALID) return INVALID;
	if (parent.first == ten(9)) return child;
	if (child.first == ten(9)) return parent;
	if (parent.second < child.first) {
		ok = false;
		return INVALID;
	}
	if (child.second < parent.first) {
		ok = false;
		return INVALID;
	}
	Pii ret(max(parent.first, child.first), min(parent.second, child.second));
	if ((ret.second - ret.first) % 2 != 0) {
		ok = false;
		return INVALID;
	}
	return ret;
}

int origin[ten(5)];
Pii memo[ten(5)];
Pii dfs(int v, int par) {
	Pii& cur = memo[v];
	if (origin[v] != -1) {
		cur.first = cur.second = origin[v];
	}
	for (auto to : e[v]) {
		if (to == par) continue;
		Pii ch = dfs(to, v);
		if (abs(ch.first) != ten(9)) {
			ch.first--;
			ch.second++;
		}
		cur = merge(cur, ch);
	}
	return cur;
}

int ans[ten(5)];
void dfs2(int v, int par, int pval) {
	if (memo[v].first <= pval - 1 && pval - 1 <= memo[v].second) {
		ans[v] = pval - 1;
	} else {
		ans[v] = pval + 1;
	}
	for (auto to : e[v]) {
		if (to == par) continue;
		dfs2(to, v, ans[v]);
	}
}

int main() {
	int n; reader(n);
	FOR(i, n - 1) {
		int a, b; reader(a, b);
		a--; b--;
		e[a].push_back(b);
		e[b].push_back(a);
	}
	FOR(i, n) memo[i].first = ten(9);
	int k; reader(k);
	FOR(i, n) origin[i] = -1;
	FOR(i, k) {
		int v, p; reader(v, p); v--;
		origin[v] = p;
	}

	dfs(0, -1);
	if (!ok) {
		puts("No");
		return 0;
	}

	dfs2(0, -1, memo[0].first - 1);
	puts("Yes");
	FOR(i, n) writerLn(ans[i]);

	return 0;
}

