const int N=1e5+5;
const int INF=123456789;
int n,k;
int par[N],ver[N],L[N],R[N];
bool ok=true;
vector<int> nei[N],order;

void check(int x,int p){
	par[x]=p;
	if(ver[x]!=-INF) L[x]=R[x]=ver[x];
	for(int i=0;i<nei[x].size();i++){
		int to=nei[x][i];
		if(to==p) continue;
		check(to,x);
		if(L[to]!=-INF){
			if(L[x]==-INF){
				L[x]=L[to]-1;
				R[x]=R[to]+1;
			}else{
				if(abs(L[x])%2==abs(L[to])%2) ok=false;
				L[x]=max(L[x],L[to]-1);
				R[x]=min(R[x],R[to]+1);
			}
		}
	}
	if(L[x]>R[x]) ok=false;
	order.push_back(x);
}

void make(int x){
	if(par[x]==-1){
		ver[x]=L[x];
		return;
	}
	int p=par[x];
//	cout<<x<<" "<<p<<endl;
	L[x]=max(L[x],ver[p]-1);
	R[x]=max(R[x],ver[p]+1);
//	cout<<x<<" "<<L[x]<<" "<<R[x]<<endl;
	while(abs(L[x])%2==abs(ver[p])%2) L[x]++;
	ver[x]=L[x];
}

int main(){
	scanf("%d",&n);
	for(int i=1;i<=n;i++) ver[i]=L[i]=-INF,R[i]=INF;
	for(int i=1;i<n;i++){
		int x,y;
		scanf("%d%d",&x,&y);
		nei[x].push_back(y);
		nei[y].push_back(x);
	}
	scanf("%d",&k);
	while(k--){
		int x,val;
		scanf("%d%d",&x,&val);
		ver[x]=val;
	}
	check(1,-1);
	if(ok){
		puts("Yes");
		reverse(order.begin(),order.end());
		for(int i=0;i<order.size();i++) make(order[i]);
		for(int i=1;i<=n;i++) printf("%d\n",ver[i]);
	}else{
		puts("No");
	}
	return 0;
}

