void solv2(int64_t a,int64_t c,int64_t b){//b->aへcがきた。(P[b]=c)
    if(b==-1){
        P[a]=v[a][0];
        for(int i=0;i<G[a].size();i++){
            solv2(G[a][i],P[a],a);
        }
    }else{
        if(P[a]==INF){
            if(v[a].size()==0){
                P[a]=c-1;
            }else if(v[a].size()==1){
                P[a]=v[a][0];
            }else{
                if(v[a][0]<= c-1 && c-1<= v[a][1]){
                    P[a]=c-1;
                }
                if(v[a][0]<= c+1 && c+1 <= v[a][1]){
                    P[a]=c+1;
                }
            }
        }
        for(int i=0;i<G[a].size();i++){
            if(G[a][i]!=b){
                solv2(G[a][i],P[a],a);
            }
        }
    }
}



