using namespace std;

const int INF = 99999999;
const int MAX_N = 100000;

struct edge {
    int ans, lower, upper;
    vector<int> next;

    edge() {
        lower = -INF;
        upper = INF;
    }
};

void print_G(const vector<edge>& G, int N) {
    for (int i = 1; i <= N; i++) {
        cout << "G[" << i << "]: lower = " << G[i].lower
             << ", upper = " << G[i].upper << endl;
        for (auto x : G[i].next) {
            cout << x << " ";
        }
        cout << endl;
    }
}

bool used[MAX_N+1];
bool dfs(vector<edge>& G, int now, int lower, int upper) {
    // cout << "# now = " << now << ", lower = " << lower << ", upper = " << upper << endl;
    if (G[now].upper < lower || G[now].lower > upper)
        if (G[now].upper != INF || G[now].lower != INF) return false;
    if (used[now]) return true;

    used[now] = true;
    if (G[now].lower < lower) G[now].lower = lower;
    if (G[now].upper > upper) G[now].upper = upper;
    for (auto x: G[now].next) {
        if (!dfs(G, x, lower-1, upper+1)) {
            used[now] = false;
            return false;
        }
    }
    used[now] = false;

    return true;
}

void dfs2(vector<edge>& G, int now, int prev_value) {
    if (used[now]) return;

    used[now] = true;
    for (int i = G[now].lower; i <= G[now].upper; i++) {
        if (prev_value-1 == i || prev_value+1 == i) {
            G[now].ans = i;
            break;
        }
    }
    for (auto x: G[now].next) {
        dfs2(G, x, G[now].ans);
    }
    used[now] = false;
}

int main(void) {

    int N; cin >> N;
    vector<edge> G(N+1);
    for (int i = 0; i < N-1; i++) {
        int A, B; cin >> A >> B;
        G[A].next.push_back(B);
        G[B].next.push_back(A);
    }

    int K; cin >> K;
    vector<int> vs(K);
    for (int i = 0; i < K; i++) {
        int V, P; cin >> V >> P;
        vs[i] = V;
        G[V].lower = G[V].upper = P;
        G[V].ans = P;
    }
    fill(used, used+N+1, false);

    bool flag = false;
    for (int i = 0; i < K; i++) {
        int p = vs[i];
        if (!dfs(G, p, G[p].lower, G[p].upper)) {
            flag = true;
            break;
        }
    }

    if (flag) {
        cout << "No" << endl;
    } else {
        // print_G(G, N);
        cout << "Yes" << endl;
        int r = vs[0]; used[r] = true;
        for (auto w: G[r].next) {
            dfs2(G, w, G[r].ans);
        }
        for (int i = 1; i <= N; i++) {
            cout << G[i].ans << endl;
        }
    }

    return 0;
}

