bool dfs(const vector<vint>& g,int v,vector<Pii>& p,vint& par,bool odd){
  if(used[v]) return true;
  used[v]=true;
  bool ret=true;
  for(int u:g[v]){
    if(used[u])continue;
    ret &= dfs(g,u,p,par,!odd);
    par[u]=v;
    p[v].first = max(p[v].first,p[u].first-1);
    p[v].second = min(p[v].second,p[u].second+1);
  }
  ret &= p[v].first<p[v].second||(p[v].first==p[v].second&&((p[v].first&1)==odd));
  return ret;
}

void dfs2(const vector<vint>& g,int v,vector<Pii>& p,vint& par){
  if(par[v]<0){
    p[v].second = p[v].first;
  }else{
    if(p[v].first<=p[par[v]].first-1){
      p[v].first = p[v].second = p[par[v]].first-1;
    }else{
      p[v].first = p[v].second = p[par[v]].first+1;
    }
  }
  for(int u:g[v]){
    if(par[v]==u)continue;
    dfs2(g,u,p,par);
  }
}

