pair<int, int> sagasu(int A) {
	if (V[A]) return mp((int)1e7, 0);
	V[A] = true;
	PM[A] = 5e6;
	Pm[A] = -5e6;
	bool odd = false;
	bool even = false;
	if (P[A] != -1) {
		PM[A] = P[A];
		Pm[A] = P[A];
		if (P[A] & 1) odd = true;
		else even = true;
	}
	for (int i = H[A]; i; i = E[i].second) {
		auto p = sagasu(E[i].first);
		if (p != mp((int)1e7, 0)) {
			if (p.first < 4e6) {
				if (p.first & 1) odd = true;
				else even = true;
			}
			PM[A] = min(PM[A], p.first);
			Pm[A] = max(Pm[A], p.second);
		}
	}
	if (odd && even) OK = false;
	if (PM[A] < Pm[A]) OK = false;
	return mp(PM[A] + 1, Pm[A] - 1);
}
void sagasu2(int A, int M) {
