       << ">";
    return os;
}

void dfs(const Graph& g, const int s, vector<bool>& used, vector<PP>& cand, const vector<int>& node)
{
    used[s] = true;
    PP ans  = { true, { 0, 0 } };
    if (node[s] != -1) {
        ans = merge(ans, { false, { node[s], node[s] } });
    }
    for (const int to : g.edge[s]) {
        if (not used[to]) {
            dfs(g, to, used, cand, node);
            if (not cand[to].first) {
                ans = merge(ans, next(cand[to]));
                if (ng(ans)) {
                    ans = { false, { 0, -2 } };
                }
            }
        }
    }
    cand[s] = ans;
}

void dfs(const Graph& g, const int s, const int par, vector<bool>& used, const vector<PP>& cand, vector<int>& node)
{
    used[s]        = true;
    const auto tmp = merge(cand[s], { false, { par - 1, par + 1 } });
    node[s]        = tmp.second.first;
    for (const int to : g.edge[s]) {
        if (not used[to]) {
            dfs(g, to, node[s], used, cand, node);
        }
    }
}
int main()
{
    cin.tie(0);
    ios::sync_with_stdio(false);
    int N;
    cin >> N;
    Graph g(N);
    vector<int> node(N, -1);
    for (int i = 0; i < N - 1; i++) {
        int u, v;
        cin >> u >> v;
        u--, v--;
        g.addEdge(u, v);
        g.addEdge(v, u);
    }
    int K;
    cin >> K;
    for (int i = 0; i < K; i++) {
        int v, p;
        cin >> v >> p;
        v--;
        node[v] = p;
    }
    vector<PP> cand(N);
    vector<bool> used(N, false);
    dfs(g, 0, used, cand, node);
    if (ng(cand[0])) {
        cout << "No" << endl;
        return 0;
    } else if (cand[0].first) {
        node[0] = 0;
        cand[0] = { false, { 0, 0 } };
    } else {
        node[0] = cand[0].second.first;
        cand[0] = { false, { cand[0].second.first, cand[0].second.first } };
    }
    fill(used.begin(), used.end(), false);
    dfs(g, 0, cand[0].second.first + 1, used, cand, node);
    cout << "Yes" << endl;
    for (int i = 0; i < N; i++) {
        cout << node[i] << endl;
    }
    return 0;
}

