bool DFS1(int at, int parent = -1) {
  //cerr << "Before visitng children: At = " << at << ", Parent = " << parent << "\n";
  for (int nxt : G[at]) {
    if (nxt == parent) continue;
    if (DFS1(nxt, at) == false) {
      return false;
    }
  }
  //cerr << "Afer visiting children: At = " << at << ", Parent = " << parent << "\n";
  if (range[at].first != -INF) {
    //cerr << "Case finite range\n";
    for (int nxt : G[at]) {
      if (nxt == parent) continue;
      if (range[nxt].first != -INF && (!isNonEmptyIntersection(range[nxt].first-1, range[nxt].second+1, range[at].first, range[at].first))) {
        return false;
      }
    }
  }
  else {
    //cerr << "Case infinite range\n";
    for (int nxt : G[at]) {
      //cerr << "nxt = " << nxt << "\n";
