      //cerr << "Nxt range = (" << range[nxt].first << ", " << range[nxt].second << ")" << "\n";
      if (nxt == parent) {
        continue;
      }
      if (range[nxt].first != -INF) {
        if (range[at].first == -INF) {
          range[at].first = range[nxt].first-1;
          range[at].second = range[nxt].second+1;
        } else {
          if (!isNonEmptyIntersection(range[nxt].first-1, range[nxt].second+1, range[at].first, range[at].second)) {
            //cerr << "Range 1 = (" << range[nxt].first-1 << ", " << range[nxt].second+1 << ")" << "\n";
            //cerr << "Range 2 = (" << range[at].first << ", " << range[at].second << ")" << "\n";
            //cerr << "Returning false\n";
            return false;
          }
          range[at] = getIntersectingRange(range[nxt].first-1, range[nxt].first+1, range[at].first, range[at].second);
        }
      }
    }
  }
  //cerr << "Good before parity check\n";
  if (range[at].first != -INF) {
    if (range[at].first > range[at].second) return false;
    if (((range[at].first % 2) + 2) % 2 != ((range[at].second % 2) + 2) % 2) return false;
    int nxtMod = (((range[at].first + 1) % 2) + 2) % 2;
    for (int nxt : G[at]) {
      if (nxt == parent) continue;
      if (range[nxt].first != -INF) {
        if (((range[nxt].first % 2) + 2) % 2 != nxtMod) {
          return false;
        }
      }
    }
  }
  //cerr << "Returning true with Range = " << range[at].first << ", " << range[at].second << "\n\n";
  return true;
}


void DFS2(int at, int parent = -1) {
  if (range[at].first == -INF) {
    val[at] = 1;
  }
  else {
    val[at] = range[at].first;
  }
  for (int nxt : G[at]) {
    if (nxt == parent) continue;
    range[nxt] = getIntersectingRange(val[at]-1, val[at]+1, range[nxt].first, range[nxt].second);
    DFS2(nxt, at);
  }
}


