    if( nx == px && minv[x] != maxv[px] ){

      minv[x] = max( minv[x], minv[px] - 1 );

      maxv[x] = min( maxv[x], maxv[px] + 1 );

    }

    if( nx == px ) continue;

    dfs2( nx, x );

  }

