typedef long long ll;
const int INF = 1e9;

vector<int> G[100010];
pair<int, int> mem[100010];

void dfs(int v, int p){
  int l, r;
  tie(l, r) = mem[v];

  for(int u : G[v])if(u != p){
    dfs(u, v);

    int a, b;
    tie(a, b) = mem[u];

    --a, ++b;

    if (a <= -INF) continue;
    if (l <= -INF) {
      l = a, r = b;
      continue;
    }

    if (l % 2 != a % 2) throw 1;

    l = max(l, a);
    r = min(r, b);
    if (l > r) throw 1;
  }

  mem[v] = make_pair(l, r);
}

int res[100010];

void fill(int v, int p){
  int l, r;
  tie(l, r) = mem[v];

  if (p < 0) {
    res[v] = l;
  } else {
    if (l <= res[p] + 1 && res[p] + 1 <= r) {
      res[v] = res[p] + 1;
    } else {
      res[v] = res[p] - 1;
    }
  }

  for(int u : G[v])if(u != p){
    fill(u, v);
  }
}

int main(){
  int N;
  cin >> N;

  for(int i=0;i<N-1;i++){
    int u, v;
