  }

  try {
    dfs(0, -1);
  } catch (int e) {
    cout << "No" << endl;
    return 0;
  }

  cout << "Yes" << endl;
  fill(0, -1); 
  for(int i=0;i<N;i++)cout << res[i] << endl;

  return 0;
}

