#include <bits/stdc++.h>
using namespace std;

const int N = 100005;
const int inf = 1e6;

int n, k;
vector<int> G[N];
int L[N], R[N], a[N];
int parity[N];

void dfs(int u, int p) {
	L[u] = -inf, R[u] = inf;
	if (a[u] != -1) L[u] = R[u] = a[u], parity[u] = (a[u] & 1);
	for (int v : G[u]) if (v != p) {
		dfs(v, u);
		if (parity[v] != -1) {
			if (parity[u] == -1) parity[u] = parity[v] ^ 1;
			else if (parity[u] != parity[v] ^ 1) { printf("No\n"); exit(0); }
		}
		L[u] = max(L[u], L[v] - 1);
		R[u] = min(R[u], R[v] + 1);
	}
	if (L[u] > R[u]) { printf("No\n"); exit(0); }
}

void fill(int u, int p) {
	for (int v : G[u]) if (v != p) {
		int val = a[u] + 1;
		if (!(val >= L[v] && val <= R[v])) val = a[u] - 1;
		if (!(val >= L[v] && val <= R[v])) { printf("No\n"); exit(0); }
		a[v] = val;
		fill(v, u);
	}
}

int main() {
	ios_base::sync_with_stdio(false); cin.tie(0);
	cin >> n;
	memset(parity, -1, sizeof parity);
	memset(a, -1, sizeof a);
	for (int i = 1; i < n; ++i) {
		int u, v; cin >> u >> v;
		G[u].push_back(v); G[v].push_back(u);
	}
	cin >> k;
	while(k--) {
		int v, p; cin >> v >> p; a[v] = p;
	}

	dfs(1,-1);
	a[1] = L[1];
	fill(1,-1);

	printf("Yes\n");
	for (int i = 1; i <= n; ++i) printf("%d\n", a[i]);
}

