constexpr int MOD = 1000000007;

typedef long long LL;
typedef pair<int, int> P;
typedef pair<LL, LL> PLL;

constexpr int INF = MOD;

int N, K;
vector<vector<int>> graph;
int p[101010];

PLL rmemo[101010];

PLL dfs(int x, int prev = -1) {
    LL minR = -INF, maxR = INF;
    for (const int& v: graph[x]) {
        if (v == prev) { continue; }
        PLL r = dfs(v, x);
        if (r.first > r.second) {
            return make_pair(INF, -INF);
        }
        if (p[x] == -1) {
            minR = max(minR, r.first);
            maxR = min(maxR, r.second);
        } else {
            if (p[x] < r.first - 1 || r.second + 1 < p[x]) {
                return make_pair(INF, -INF);
            }
        }
    }

    if (p[x] != -1) {
        return rmemo[x] = make_pair(p[x], p[x]);
    }
    return rmemo[x] = make_pair(minR-1, maxR+1);
}

LL ret[101010];

void dfs_set(int x, LL minR, LL maxR, int prev = -1) {
    ret[x] = max(minR, rmemo[x].first);
    for (const int& v : graph[x]) {
        if (v == prev) { continue; }
        dfs_set(v, ret[x]-1, ret[x]+1, x);
    }
}

int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);

    cin >> N;
    graph.resize(N);
    fill(p, p+N, -1);
    for (int j = 0; j < N-1; ++j) {
        int a, b;
        cin >> a >> b;
        --a; --b;
        graph[a].push_back(b);
        graph[b].push_back(a);
    }

    cin >> K;
    for (int j = 0; j < K; ++j) {
        int v, w;
        cin >> v >> w;
        p[--v] = w;
    }

    PLL result = dfs(0);

    if (result.first > result.second) {
        cout << "No" << endl;
        return 0;
    }

    dfs_set(0, -INF, INF);

    cout << "Yes" << endl;
    for (int j = 0; j < N; ++j) {
        cout << ret[j] << endl;
    }

    return 0;
}

