const int MAXN = 1e5 + 5;

int N, K, rt;
vector<int> G[MAXN];
int val[MAXN];

void input()
{
    read(N);
    for (int i = 1; i < N; ++i) {
        int u, v;
        read(u); read(v);
        G[u].push_back(v);
        G[v].push_back(u);
    }
    read(K);
    std::fill(val + 1, val + N + 1, -1);
    for (int i = 1; i <= K; ++i) {
        int u, x;
        read(u); read(x);
        val[u] = x;
        rt = u;
    }
}

int req[MAXN], minreq[MAXN];
int fadd[MAXN];

void dfs1(int u, int f, int cur)
{
    cur += fadd[u];
    if (~val[u]) {
        if (val[u] > cur || ((cur - val[u]) & 1)) {
            puts("No");
            exit(0);
        }
        req[u] = (cur - val[u]) / 2;
    } else
        req[u] = +oo;
    minreq[u] = req[u];
    for (int i = 0; i < SZ(G[u]); ++i) {
        int v = G[u][i];
        if (v == f)
            continue;
        dfs1(v, u, cur);
        chkmin(minreq[u], minreq[v]);
    }
}

void dfs2(int u, int f, int x)
{
    if (u != rt) {
        if (minreq[u] > x) {
            fadd[u] = -1;
            ++x;
        }
        if (req[u] != +oo && req[u] != x) {
            puts("No");
            exit(0);
        }
        val[u] = val[f] + fadd[u];
    }
    for (int i = 0; i < SZ(G[u]); ++i) {
        int v = G[u][i];
        if (v == f)
            continue;
        dfs2(v, u, x);
    }
}

void solve()
{
    std::fill(fadd + 1, fadd + N + 1, +1);
    fadd[rt] = 0;
    dfs1(rt, 0, val[rt]);
    dfs2(rt, 0, 0);

    puts("Yes");
    for (int i = 1; i <= N; ++i) {
        printf("%d\n", val[i]);
    }
}

int main()
{
#ifdef __DEBUG
    freopen("E.in", "r", stdin);
    freopen("E.out", "w", stdout);
#endif

    input();
    solve();
}

