    for (const ll& i : g[num]) {
      if (ub[num] != INF) {
        if (ub[i] == INF) {
          lb[i] = lb[num]-1, ub[i] = ub[num]+1;
        } else {
          ll l = lb[num] - 1, u = ub[num] + 1;
          if (lb[i] > u || l > ub[i] || (ub[i] + u) % 2 == 1) {
            printf("No\n");
            return 0;
          }
          lb[i] = max(lb[i], l);
          ub[i] = max(ub[i], u);
        }
      }
      c[i]--;
      if (!used[i] && c[i] <= 1) que.push(i), used[i] = true;
    }
  }
  assert(stc.size() == n);
  while (!stc.empty()) {
    ll num = stc.top(); stc.pop();
    ans[num] = lb[num];
    ll la = lb[num]-1, ua = ub[num]+1;
    for (const ll& i : g[num]) {
      lb[i] = max(lb[i], la);
      ub[i] = min(ub[i], ua);
    }
  }
  printf("Yes\n");
  for (ll i = 0; i < n; i++) printf("%lld\n", ans[i]);
}

