#include <bits/stdc++.h>
using namespace std;

typedef pair<int,int> P;
const int INF = INT_MAX / 2;    //int_max->2*e+9 LLの時はLLONG_MAX
#define MP make_pair
const P pINF=MP(-INF,INF);
const P fail=MP(INF,-INF);

vector<P> range;
vector<int> graph[100001];
bool visited[100001];

P dfs(int v){
    if(visited[v])	
        return pINF;
    visited[v]=true;
    for(int i=0;i<graph[v].size();i++){
        int to=graph[v][i];
        P result=dfs(to);
        if(result==MP(pINF.first-1,pINF.second+1))	result=pINF;
        if(result==fail){
            return fail;
        }
        else if(range[v]==pINF){
            range[v]=result;
        }else if(result==pINF){
            continue;
        }else if(range[v].first%2!=result.first%2){
            return fail;
        }else if(range[v].second<result.first) {
            return fail;
        }else if(result.second<range[v].first){
            return fail;
        }else{
            range[v].second=min(range[v].second,result.second);
            range[v].first=max(range[v].first,result.first);
        }
    }
    if(range[v].second<range[v].first)
        return fail;
    return MP(range[v].first-1,range[v].second+1);
}

void decide(int v){
    if(visited[v])	return;
    visited[v]=true;
    range[v]=MP(range[v].first,range[v].first);
    for(int i=0;i<graph[v].size();i++){
        int to=graph[v][i];
        if(visited[to])	continue;
        range[to]=MP(max(range[to].first,range[v].first-1),
                            min(range[to].second,range[v].second+1));
        decide(to);
    }
    return;
}

int main(){
    int n;	cin>>n;
    for(int i=0;i<n-1;i++){
        int a,b;	
        cin>>a>>b;	a--;	b--;
        graph[a].push_back(b);
        graph[b].push_back(a);
    }
    for(int i=0;i<n;i++)	visited[i]=false;
    range=vector<P>(n,pINF);
    int k;	cin>>k;
    for(int i=0;i<k;i++){
        int v,p;	
        cin>>v>>p;	v--;
        range[v]=MP(p,p);
    }
    P ret=dfs(0);
    if(ret==fail){
        cout<<"No"<<endl;
        return 0;
    }
    cout<<"Yes"<<endl;
    for(int i=0;i<n;i++)	
        visited[i]=false;
    decide(0);
    for(int i=0;i<n;i++)	
        cout<<range[i].first<<endl;
    return 0;
}

