bool solve(int parent, int now) {
	int m = -inf, M = inf;
	for (int i = 0; i < G[now].size(); i++) {
		if (G[now][i] != parent) {
			int child = G[now][i];
			if (solve(now, child)) {
				if (m != -inf && (mM[child].first - 1 > M || mM[child].second + 1 < m || abs(mM[child].first + 1) % 2 != abs(m) % 2)) {
					return false;
				}
				else {
					m = max(m, mM[child].first - 1);
					M = min(M, mM[child].second + 1);
				}
			}
			else {
				return false;
			}
		}
	}
	if (mM[now].first > M || mM[now].second < m) {
		return false;
	}
	else {
		mM[now].first = max(m, mM[now].first);
		mM[now].second = min(M, mM[now].second);
		return true;
	}
}

void answer(int parent, int now, int parent_value) {
	if (parent == -1) {
		value[now] = mM[now].first;
