	else {
		if (parent_value + 1 >= mM[now].first && parent_value + 1 <= mM[now].second) {
			value[now] = parent_value + 1;
		}
		else {
			value[now] = parent_value - 1;
		}
	}
	for (int i = 0; i < G[now].size(); i++) {
		if (G[now][i] != parent) {
			int child = G[now][i];
			answer(now, child, value[now]);
		}
	}
