template <class Cost = int>
struct Edge {
    int src, dst;
    Cost cost;
    Edge(int src = -1, int dst = -1, Cost cost = 1)
        : src(src), dst(dst), cost(cost){};

    bool operator<(const Edge<Cost>& e) const { return this->cost < e.cost; }
    bool operator>(const Edge<Cost>& e) const { return this->cost > e.cost; }
};

template <class Cost = int>
using Graph = std::vector<std::vector<Edge<Cost>>>;

constexpr int INF = 1 << 30;

Graph<> tree;
std::vector<int> ls, rs, vs;

void dfs(int v, int p = -1) {
    for (auto e : tree[v]) {
        int u = e.dst;
        if (u == p) continue;

        ls[u] = std::max(ls[u], ls[v] - 1);
        rs[u] = std::min(rs[u], rs[v] + 1);

        dfs(u, v);

        ls[v] = std::max(ls[v], ls[u] - 1);
        rs[v] = std::min(rs[v], rs[u] + 1);
    }
}

void fdfs(int v, int p = -1) {
    int x = vs[v];
    for (auto e : tree[v]) {
        int u = e.dst;
        if (u == p) continue;

        vs[u] = (x - 1 >= ls[u] ? x - 1 : x + 1);
        fdfs(u, v);
    }
}

void solve() {
