#define MAXN 1000007

int n ;
vector < int > v[ MAXN ] ;
int val[ MAXN ] ;

int root ;

pair < int , int > aux[ MAXN ] ;
bool bad = false ;

void init ( int vertex , int prv ) {
    int sz = v[ vertex ].size ( ) ;
    aux[ vertex ] = { - 5 * MAXN , 5 * MAXN } ;
    for ( int i = 0 ; i < sz ; ++ i ) {
        if ( v[ vertex ][ i ] == prv ) { continue ; }
        init ( v[ vertex ][ i ] , vertex ) ;
        aux[ vertex ].first = max ( aux[ vertex ].first , aux[ v[ vertex ][ i ] ].first - 1 ) ;
        aux[ vertex ].second = min ( aux[ vertex ].second , aux[ v[ vertex ][ i ] ].second + 1 ) ;
    }
    if ( val[ vertex ] >= 0 ) {
        aux[ vertex ].first = max ( aux[ vertex ].first , val[ vertex ] ) ;
        aux[ vertex ].second = min ( aux[ vertex ].second , val[ vertex ] ) ;
    }
    if ( aux[ vertex ].first > aux[ vertex ].second ) {
        bad = true ;
    }
}

void dfs ( int vertex , int prv ) {
    int sz = v[ vertex ].size ( ) ;
    for ( int i = 0 ; i < sz ; ++ i ) {
        if ( v[ vertex ][ i ] == prv ) { continue ; }
        if ( val[ v[ vertex ][ i ] ] >= 0 ) {
            if ( abs ( val[ vertex ] - val[ v[ vertex ][ i ] ] ) != 1 ) { bad = true ; }
            dfs ( v[ vertex ][ i ] , vertex ) ;
        }
        else {
            int sr = val[ vertex ] - 1 ;
            if ( aux[ v[ vertex ][ i ] ].first <= sr && sr <= aux[ v[ vertex ][ i ] ].second ) {
                val[ v[ vertex ][ i ] ] = sr ;
                dfs ( v[ vertex ][ i ] , vertex ) ;
            }
            else {
                sr = val[ vertex ] + 1 ;
                if ( aux[ v[ vertex ][ i ] ].first <= sr && sr <= aux[ v[ vertex ][ i ] ].second ) {
                    val[ v[ vertex ][ i ] ] = sr ;
                    dfs ( v[ vertex ][ i ] , vertex ) ;
                }
                else { bad = true ; }
            }
        }
    }
}

void input ( ) {
    scanf ( "%d" , &n ) ;
    for ( int i = 1 ; i <= n ; ++ i ) {
        val[ i ] = -1 ;
    }
    for ( int i = 1 ; i < n ; ++ i ) {
        int x , y ;
        scanf ( "%d%d" , &x , &y ) ;
        v[ x ].push_back ( y ) ;
        v[ y ].push_back ( x ) ;
    }
    int mx = -1 ;
    int k ;
    scanf ( "%d" , &k ) ;
    for ( int i = 1 ; i <= k ; ++ i ) {
        int x , y ;
        scanf ( "%d%d" , &x , &y ) ;
        val[ x ] = y ;
        if ( mx < y ) {
            mx = y ;
            root = x ;
        }
    }
}

void solve ( ) {
    printf ( "root = %d\n" , root ) ;
    init ( root , -1 ) ;
    dfs ( root , -1 ) ;
    if ( bad == true ) {
        printf ( "No\n" ) ;
        return ;
    }
    printf ( "Yes\n" ) ;
    for ( int i = 1 ; i <= n ; ++ i ) {
        printf ( "%d\n" , val[ i ] ) ;
    }
}


