void DFS2(ll v, ll p = 0, ll c = 0){
	if (dp[v].F == 0 && dp[v].S == 0) num[v] = c + 1;
	else if (v == 1){
		if (num[v] == -1){
			num[v] = dp[v].F;
		}
	}else{
		if (c == dp[v].S + 1){
			num[v] = dp[v].S;
		}else if(c == dp[v].F - 1){
			num[v] = dp[v].F;
		}else{
			num[v] = c - 1;
		}
	}
	for (auto u:G[v]){
		if (u == p) continue;
		DFS2(u, v, num[v]);
	}
	return;
}


