	for(int i = 0; i < k; i++) {
		int v,p;
		cin >> v >> p;
		V[v-1] = p;
	}

	P res = dfs(0,g);
// 	cout << res.first << ":" << res.second << endl;
	if(res.first > res.second) {
		cout << "No" << endl;
	}else {
		cout << "Yes" << endl;
		retraversal(0,g,res.second);
		for(int i = 0; i < n;i++)
			cout << V[i] << endl;
	}
}

