void foo(int root)
{
	ret[root].resize(2);
	int mi = -INT, ma = INT;
	int tmp;
	for (int i = 0; i < tree[root].size(); ++i) {
		tmp = tree[root][i];
		//cout << "   foo " << tmp << '\n';
		foo(tmp);
		if (ret[tmp][0] > ret[tmp][1]) {
			ret[root] = ret[tmp];
			return;
		}
		mi = max(mi, ret[tmp][0] - 1);
		ma = min(ma, ret[tmp][1] + 1);
	}
	ret[root][0] = mi; ret[root][1] = ma;
	if (weight[root] != INT) {
		if (!(mi <= weight[root] && weight[root] <= ma)) {
			ret[root][0] = 0; ret[root][1] = -1;
		} else {
			ret[root][0] = ret[root][1] = weight[root];
		}
	}
	//cout << "ret " << ret[root][0] << ' ' << ret[root][1] << '\n';
}

void result(int root, int prev)
{
	weight[root] = (prev == -INT ? 1 : prev);
	for (int i = 0; i < tree[root].size(); ++i) {
		int tmp = tree[root][i];
		int mi = prev - 1, ma = prev + 1;
		mi = max(mi, ret[tmp][0]);
		ma = min(ma, ret[tmp][1]);
		result(tmp, mi);
	}
}

