    auto x = queue.front();
    used[x] = true;
    order[o++] = x;
    queue.pop();
    for (auto &e : G0[x]) {
      if (!used[e]) { queue.push(e); }
    }
  }
  for (unsigned i = 0; i < N; ++i) {
    for (auto &e : G0[i]) {
      if (order[i] < order[e]) {
        G[i].push_back(e);
      }
    }
  }

  std::vector<int> even_odd(N, -1);
  for (unsigned t = 0; t < N; ++t) {
    auto i = order[t];
