      color[i].first = std::max(color[i].first, color[e].first - 1);
      color[i].second = std::min(color[i].second, color[e].second + 1);
    }
    if (color[i].first % 2 != even_odd[i]) {
      ++color[i].first;
    }
    if (color[i].second % 2 != even_odd[i]) {
      --color[i].second;
    }
    if (color[i].first > color[i].second) {
