vector <int> gr[100005];

pii res[100005];
int used[100005];
int sz[100005];

int unreal;

int dfsSz(int v, int pr)
{
	sz[v] = 1;

	for(auto it:gr[v])
	{
		if (used[it] == 0 && it != pr)
		{
			sz[v] += dfsSz(it, v);
		}
	}

	return sz[v];
}

int getCentroid(int v, int pr, int tn)
{
	for (auto it : gr[v])
	{
		if (used[it] == 0 && it != pr && sz[it] * 2 > tn)
		{
			return getCentroid(it, v, tn);
		}
	}

	return v;
}

pii dfs(int v, int pr)
{
	if (res[v].first != -MOD)
	{
		return{ res[v].first - 1, res[v].second + 1 };
	}

	pii tr = { -MOD, MOD };

	for (auto it : gr[v])
	{
		if (it != pr)
		{
			pii tr2 = dfs(it, v);

			if (tr2.first == -MOD)
			{
				continue;
			}

			if (tr2.first < 0)
			{
				tr2.first += 2;
			}

			if (tr.first == -MOD)
			{
				tr = tr2;
			}
			else
			{
				if (tr.first % 2 != tr2.first % 2)
				{
					unreal = 1;
				}
				else
				{
					pii tr3 = { max(tr.first, tr2.first), min(tr.second, tr2.second) };

					if (tr3.first > tr3.second)
					{
						unreal = 1;
					}

					tr = tr3;
				}
			}
		}
	}

	return{ max(-MOD, tr.first - 1), min(MOD, tr.second + 1) };
}

void buildCentroidDecomposition(int v)
{
	int tn = dfsSz(v, -1);

	int centroid = getCentroid(v, -1, sz[v]);

	if (res[centroid].first == -MOD)
	{
		res[centroid] = dfs(centroid, -1);
		res[centroid].first++;
		res[centroid].second--;
	}

	used[centroid] = 1;
	for (auto it : gr[centroid])
	{
		if (used[it] == 0)
		{
			buildCentroidDecomposition(it);
		}
	}
}


