int ans[MAX_N];

void dfs(int v, int parent) {
  for (int nxt : g[v]) if (nxt != parent) {
    dfs(nxt, v);
    c[v] = max(c[v], c[nxt] - 1);
    d[v] = min(d[v], d[nxt] + 1);
  }
}

void check(int v, int parent, int parent_value) {
  ans[v] = INF;
  for (int i = parent_value - 1; i <= parent_value + 1; i += 2) {
    if (c[v] <= i && i <= d[v]) {
      ans[v] = i;
      break;
    }
  }
  for (int nxt : g[v]) if (nxt != parent) {
    check(nxt, v, ans[v]);
  }
}

