using namespace std;
inline int read()
{
    int x=0,f=1;char ch=getchar();
    while (ch<'0'||ch>'9'){if(ch=='-')f=-1;ch=getchar();}
    while (ch>='0'&&ch<='9'){x=x*10+ch-'0';ch=getchar();}
    return x*f;
}
int n,head[MN+5],cnt=0,b[MN+5],s[MN+5],l[MN+5],r[MN+5],flag=1;
struct edge{int to,next;}e[MN*2+5];
inline void ins(int f,int t)
{
    e[++cnt]=(edge){t,head[f]};head[f]=cnt;
    e[++cnt]=(edge){f,head[t]};head[t]=cnt;
}
void dfs(int x,int fa)
{
    l[x]=b[x]?s[x]:-1e6;r[x]=b[x]?s[x]:1e6;
    for(int i=head[x];i;i=e[i].next) if(e[i].to!=fa)
    {
        dfs(e[i].to,x);
        l[x]=max(l[x],l[e[i].to]-1);
        r[x]=min(r[x],r[e[i].to]+1);
    }
}
void Solve(int x,int fa,int lt,int rt)
{
    int ll=max(lt,l[x]),rr=min(rt,r[x]);
    if(ll>rr) flag=0; else lt=rt=s[x]=ll;
    for(int i=head[x];i;i=e[i].next) if(e[i].to!=fa) Solve(e[i].to,x,lt-1,rt+1);
}
int main()
{
    n=read();
    for(int i=1;i<n;++i) ins(read(),read());
    for(int K=read(),j;K--;) j=read(),b[j]=1,s[j]=read();
    dfs(1,0);Solve(1,0,-1e6,1e6);
    if(!flag) return 0*puts("No"); else puts("Yes");
    for(int i=1;i<=n;++i) printf("%d\n",s[i]);
    return 0;
}

