typedef long long llint;

struct Node {
    int lower, count;
    Node() : lower(0), count(0) {}
    Node(int lower, int count) : lower(lower), count(count) {}
};

bool update(int n, int v, vector<vector<int> > &tree, vector<Node> &nodes) {
    stack<pair<int, int> >  st;
    vector<bool>    visited(n+1, false);

    for(auto it=tree[v].begin(); it!=tree[v].end(); ++it) {
        st.push(pair<int, int>(*it, v));
    }

    while(!st.empty()) {
        int cur = st.top().first, prev = st.top().second; st.pop();
        // cout << "visiting " << cur << " from " << prev << " with flag " << visited[cur] <<endl;
        // for(auto it=nodes.begin()+1; it!=nodes.end(); ++it) {
        //     cout << it->lower << " ";
        // }
        // cout << endl;
        if(!visited[cur]) {
            visited[cur] = true;
            st.push(pair<int, int>(cur, prev));
            for(auto it=tree[cur].begin(); it!=tree[cur].end(); ++it) {
                if(*it == prev)    continue;
                else {
                    st.push(pair<int, int>(*it, cur));
                }
            }
        }
        else {
            if(tree[cur].size() > 1) {
                for(auto it=tree[cur].begin(); it!=tree[cur].end(); ++it) {
                    if(*it == prev || nodes[*it].count == 0) continue;
                    if(nodes[cur].count == 0) {
                        nodes[cur].count = nodes[*it].count + 1;
                        nodes[cur].lower = nodes[*it].lower - 1;
                    }
                    else {
                        if(max(nodes[cur].lower, nodes[*it].lower-1)
                           <= min(nodes[cur].lower+nodes[cur].count*2-2,
                                  nodes[*it].lower-1+nodes[*it].count*2)
                           && (nodes[cur].lower-nodes[*it].lower)%2 == 1) {
                            nodes[cur].lower = max(nodes[cur].lower, nodes[*it].lower-1);
                            nodes[cur].count =
                                (min(nodes[cur].lower+nodes[cur].count*2-2,
                                    nodes[*it].lower-1+nodes[*it].count*2)
                                - max(nodes[cur].lower, nodes[*it].lower-1))/2 + 1;
                        }
                        else    return false;
                    }
                }
            }
        }
    }
    return true;
}

void finalize(int n, int v, vector<vector<int> > &tree, vector<Node> &nodes) {
    stack<pair<int, int> >  st;
    vector<bool>    visited(n+1, false);

    for(auto it=tree[v].begin(); it!=tree[v].end(); ++it) {
        st.push(pair<int,int>(*it, v));
    }

    while(!st.empty()) {
        int cur = st.top().first, prev = st.top().second;
        st.pop();

        if(nodes[cur].count == 0) {
            nodes[cur].count = nodes[prev].count + 1;
            nodes[cur].lower = nodes[prev].lower - 1;
        }
        for(auto it=tree[cur].begin(); it!=tree[cur].end(); ++it) {
            if(*it != prev) st.push(pair<int,int>(*it, cur));
        }
    }
}

bool solve(int n, int k, vector<vector<int> > &tree, vector<Node> &nodes,
           vector<int> &written) {
    // for(auto it=written.begin(); it!=written.end(); ++it) {
    //     if(!update(n, *it, tree, nodes))   return false;
    // }
    bool ret = update(n, written[0], tree, nodes);
    finalize(n, written[0], tree, nodes);
    return ret;
}

