tuple<int,int,bool,bool> dfs(
    const vector<vecint>& g,
    const vecint& num,
    vector<tuple<int,int,bool,bool>>& vr,
    int i, int p = -1) {
  if (num[i] >= 0) {
    vr[i] = make_tuple(num[i], num[i], num[i] % 2 == 0, num[i] % 2 == 1);
    return vr[i];
  }
  int mn = 0;
  int mx = 1000000;
  bool ise = false, iso = false;
  for (auto&& to:g[i]) {
    if (to == p) continue;
    int cn, cx;
    bool ce, co;
    tie(cn, cx, ce, co) = dfs(g, num, vr, to, i);
    mn = max(mn, cn-1);
    mx = min(mx, cx+1);
    if (ce) iso = true;
    else if (co) ise = true;
  }
  if (ise && iso) {
    cout<<"No\n";
    exit(0);
  }
  if (ise) {
    mn += mn % 2;
    mx -= mx % 2;
  } else if (iso) {
    mn += (mn+1) % 2;
    mx -= (mx+1) % 2;
  }
  if (mn > mx) {
    cout<<"No\n";
    exit(0);
  }
  vr[i] = make_tuple(mn, mx, ise, iso);
  return vr[i];
}

void dfs2(
    const vector<vecint>& g,
    vecint& num,
    const vector<tuple<int,int,bool,bool>>& vr,
    int pnum, int i, int p = -1) {
  if (num[i] >= 0) return;
  int mn, mx;
  bool ise, iso;
  tie(mn, mx, ise, iso) = vr[i];
  int candi = pnum-1;
  if (mn <= candi && candi <= mx) {
    num[i] = candi;
  } else {
    num[i] = pnum+1;
  }
  for (auto&& to : g[i]) {
    if (to == p) continue;
    dfs2(g, num, vr, num[i], to, i);
  }
}

