void solve(int v=0,int p=-1){
	L[v]=-INF-1,R[v]=INF+1;
	if(id[v]!=-1)L[v]=R[v]=id[v];
	for(auto to:G[v]){
		if(to!=p){
			solve(to,v);
			if(L[to]<-INF/2)continue;
			if(L[v]<-INF/2){
				L[v]=L[to]-1;
				R[v]=R[to]+1;
			}else{
				if(abs(L[to])%2==abs(L[v])%2){
					ok=0;
					return;
				}
				L[v]=max(L[v],L[to]-1);
				R[v]=min(R[v],R[to]+1);
			}
		}
	}
	if(L[v]>R[v])ok=0;
}
void make(int v=0,int p=-1){
	if(v==0&&id[v]==-1)id[v]=L[v];
	for(auto to:G[v]){
		if(to!=p){
			if(id[to]==-1){
				if(L[to]<=id[v]-1&&id[v]-1<=R[to])id[to]=id[v]-1;
				else id[to]=id[v]+1;
			}
			make(to,v);
		}
	}
}
