#include <bits/stdc++.h>
using namespace std;
const int INF = 1<<30;
struct Hoge {
	int a, b;
};
int N, K;
vector<vector<int>> G;
vector<int> P;
vector<Hoge> hoge;

void f(int p, int q) {
	if (P[p] != INF) {
		hoge[p].a = hoge[p].b = P[p];
	} else {
		hoge[p].a = hoge[q].a - 1;
		hoge[p].b = hoge[q].b + 1;
	}
	for (int x : G[p]) if (x != q) {
		f(x, p);
		hoge[p].a = max(hoge[p].a, hoge[x].a - 1);
		hoge[p].b = min(hoge[p].b, hoge[x].b + 1);
	}
}

bool g(int p, int q) {
	if (P[p] == INF) {
		if (hoge[p].a <= P[q]-1 && P[q]-1 <= hoge[p].b) {
			P[p] = P[q]-1;
		} else if (hoge[p].a <= P[q]+1 && P[q]+1 <= hoge[p].b) {
			P[p] = P[q]+1;
		} else {
			return false;
		}
	}
	if (q >= 0 && abs(P[p] - P[q]) != 1) return false;
	for (int x : G[p]) if (x != q) {
		if (!g(x, p)) return false;
	}
	return true;
}

int main() {
	cin >> N;
	G.resize(N);
	for (int i = 1; i < N; ++ i) {
		int x, y;
		cin >> x >> y;
		-- x; -- y;
		G[x].push_back(y);
		G[y].push_back(x);
	}
	cin >> K;
	P.resize(N, INF);
	int v0 = -1;
	for (int i = 0; i < K; ++ i) {
		int v, p;
		cin >> v >> p;
		P[v-1] = p;
		if (i == 0) v0 = v-1;
	}
	hoge.resize(N);
	f(v0, -1);
	//for (int i = 0; i < N; ++ i) cout << hoge[i].a << " " << hoge[i].b << endl;
	if (g(v0, -1)) {
		cout << "Yes" << endl;
		for (auto x : P) {
			cout << x << endl;
		}
	} else {
		cout << "No" << endl;
	}
}

