using namespace std;
typedef pair<int, int> P;

int N, K;
vector<int> G[100005];
int p[100005];
P val[100005];
int ans [100005];

bool check(int v, int prev, int r)
{
	if(p[v] != -1 && p[v] % 2 != r) return false;
	for(int i = 0; i < G[v].size(); i++){
		if(G[v][i] != prev) continue;
		if(!check(G[v][i], v, (r+1)%2)) return false;
	}
	return true;
}

P dfs(int v, int prev)
{
	P ret = make_pair(-inf, inf), res;
	for(int i = 0; i < G[v].size(); i++){
		if(G[v][i] == prev) continue;
		res = dfs(G[v][i], v);
		if(res.first == inf) return make_pair(inf, -inf);
		ret.first = max(ret.first, res.first-1);
		ret.second = min(ret.second, res.second+1);
	}
	if(ret.first > ret.second) return make_pair(inf, -inf);

	if(p[v] != -1){
		if(p[v] < ret.first || p[v] > ret.second) return make_pair(inf, -inf);
		else ret = make_pair(p[v], p[v]);
	}
	end:;
	return val[v] = ret;
}

void dfs2(int v, int prev, int x)
{
	ans[v] = max(val[v].first, x-1);
	for(int i = 0; i < G[v].size(); i++){
		if(G[v][i] == prev) continue;
		dfs2(G[v][i], v, ans[v]);
	}
}

int main(void)
{
	cin >> N;
	int a, b;
	for(int i = 0; i < N-1; i++){
		cin >> a >> b;
		G[a].push_back(b);
		G[b].push_back(a);
	}

	cin >> K;
	for(int i = 1; i <= N; i++) p[i] = -1;
	for(int i = 0; i < K; i++){
		cin >> a >> b;
		p[a] = b;
	}

	if(!check(1, -1, 0) && !check(1, -1, 1)){
		cout << "No" << endl;
		return 0;
	}

	if(dfs(1, -1).first == inf){
		cout << "No" << endl;
		return 0;
	}

	dfs2(1, -1, (val[1].first + val[1].second) / 2);
	cout << "Yes" << endl;
	for(int i = 1; i <= N; i++){
		cout << ans[i] << endl;
	}

	return 0;
}

#include<bits/stdc++.h>
using namespace std;
const int maxn = 1e5 + 5;
vector<int>G[maxn];
int n, k, val[maxn], fa[maxn], now[maxn], dif[maxn], vis[maxn];
inline void Add(int u, int v) {
	if(~dif[u]) {
		int x = dif[v] + 1;
		if((now[u] + dif[u]) % 2 != (now[v] + x) % 2)
			exit(0 * puts("No"));
		int l = max(now[u] - dif[u], now[v] - x), r = min(now[u] + dif[u], now[v] + x);
		if(l > r)
			exit(0 * puts("No"));
		assert((l + r) % 2 == 0);
		now[u] = (l + r) >> 1, dif[u] = r - now[u];
	}
	else
		if(~dif[v])
			now[u] = now[v], dif[u] = dif[v] + 1;
}
inline void Solve(int u) {
	for(auto v : G[u]) {
		if(v == fa[u])
			continue;
		fa[v] = u;
		Solve(v);
		// cerr << u << " -> " << v <<" " << now[u] <<" " << dif[u] <<" " << now[v] <<" " << dif[v] << endl;
		Add(u, v);
	}
	if(~val[u]) {
		if(~dif[u] && (val[u] < now[u] - dif[u] || val[u] > now[u] + dif[u]))
			exit(0 * puts("No"));
		now[u] = val[u], dif[u] = 0;
	}
}
inline void Work(int u) {
	val[u] = now[u] - dif[u];
	for(auto v : G[u]) {
		if(v == fa[u])
			continue;
		Add(v, u);
		if(~val[v])
			now[v] = val[v], dif[v] = 0;
		Solve(v);
	}
}
int main() {
	scanf("%d", &n);
	for(int i = 1; i <= n; ++ i)
		dif[i] = val[i] = -1;
	for(int i = 1, x, y; i < n; ++ i)
		scanf("%d%d", &x, &y), G[x].push_back(y), G[y].push_back(x);
	scanf("%d", &k);
	for(int i = 1, x, y; i <= k; ++ i)
		scanf("%d%d", &x, &y), val[x] = y;
	Solve(1), Work(1), puts("Yes");
	for(int i = 1; i <= n; ++ i)
		printf("%d\n", val[i]);
}

