using namespace std;

using i64 = int64_t;

const i64 MOD = 1e9+7;

const i64 INF = 1e18+7;

signed main(){
    int n;
    cin >> n;
    vector<vector<int>> edges(n);
    for(int i = 0; i < n - 1; ++i){
        int a, b;
        cin >> a >> b;
        edges[--a].emplace_back(--b);
        edges[b].emplace_back(a);
    }
    vector<int> par(n, -2);
    vector<vector<int>> chi(n);
    vector<int> siz(n, 0);
    function<void(int,int)> f = [&](int x, int y){
        par[x] = y;
        if(x)
            siz[x] = siz[y] + 1;
        for(auto& ed : edges[x]){
            if(par[ed] == -2)
                f(ed, x);
            if(par[ed] == x)
                chi[x].push_back(ed);
        }
    };
    f(0, -1);
    vector<i64> mi(n, -MOD);
    vector<i64> ma(n, MOD);
    int q, qq;
    cin >> q;
    for(int i = 0; i < q; ++i){
        int a, b;
        cin >> a >> b;
        mi[--a] = b;
        ma[a] = b;
        qq = a;
    }
    vector<int> out(n);
    queue<int> que;
    for(int i = 0; i < n; ++i)
        if(!(out[i] = chi[i].size()))
            que.emplace(i);

    int fl = (siz[qq] ^ mi[qq]) & 1;
    for(int i = 0; i < n; ++i)
        siz[i] = (siz[i] ^ fl) & 1;

    auto g = [&]{

        while(!que.empty()){
            int t = que.front();
            que.pop();
            if(par[t] != -1 && !(--out[par[t]]))
                que.emplace(par[t]);

            for(auto& c : chi[t]){
                mi[t] = max(mi[t], mi[c] - 1);
                ma[t] = min(ma[t], ma[c] + 1);
            }
            if(mi[t] > ma[t]){
                cout << "No" << endl;
                return false;
            }
        }

        vector<i64> ans(n, INF);
        if((ma[0] & 1) != siz[0]){
            --ma[0];
        }
        if(ma[0] < mi[0]){
            cout << "No" << endl;
            return false;
        }
        ans[0] = ma[0];
        function<void(int)> gg = [&](int x){
            if(x){
                ma[x] = min(ma[x], ans[par[x]] + 1);
                mi[x] = max(mi[x], ans[par[x]] - 1);
                if((ma[x] & 1) != siz[x]){
                    --ma[x];
                }
                if(ma[x] < mi[x]){
                    cout << "No" << endl;
                    exit(0);
                }
                ans[x] = ma[x];
            }
            for(auto& c : chi[x])
                gg(c);
        };
        gg(0);
        // [mi[i], ma[i]]の範囲内なら子が条件を満たすように置ける
        for(int i = 0; i < n; ++i)
            if(mi[i] > ma[i]){
                cout << "No" << endl;
                return false;
            }

        cout << "Yes" << endl;
        for(int i = 0; i < n; ++i)
            cout << ans[i] << endl;
    };
    g();
}

