const int MAXN =  100005;

int n, k;
vector<int> adj[MAXN];
int p[MAXN];
vector<pair<int, int>> edge;

int main() {
  ios::sync_with_stdio(0);
  cin.tie(0), cout.tie(0);

  cin >> n;
  for (int i = 1; i < n; i++) {
    int u, v;
    cin >> u >> v;
    u--, v--;
    adj[u].emplace_back(v);
    adj[v].emplace_back(u);
    edge.emplace_back(u, v);
  }

  for (int i = 0; i < n; i++) {
    p[i] = 1e9;
  }

  vector<int> vis(n, 0);
  priority_queue<pair<int, int>, vector<pair<int, int>>, greater<pair<int, int>>> pq;

  cin >> k;
  for (int i = 0; i < k; i++) {
    int v;
    cin >> v; v--;
    cin >> p[v];
    pq.emplace(p[v], v);
    vis[v] = 1;
  }

  while (!pq.empty()) {
    int u = pq.top().second;
    pq.pop();

    for (auto &i : adj[u]) if (!vis[i]) {
      vis[i] = 1;
      p[i] = p[u] + 1;
      pq.emplace(p[i], i);
    }
  }

  for (auto &e : edge) {
    if (abs(p[e.first] - p[e.second]) != 1) {
      cout << "No\n";
