#include <cstdlib>
using namespace std;
const int MAXN = 100005,INF=0x3f3f3f3f;
struct Edge{
    int to,next;
}e[MAXN<<1];
int val[MAXN],n,cnt,k,head[MAXN];
inline void insert(int u,int v)
{
    e[++cnt].to=v,e[cnt].next=head[u],head[u]=cnt;
    e[++cnt].to=u,e[cnt].next=head[v],head[v]=cnt;
}
bool flag=true;
int l[MAXN],r[MAXN],sta[MAXN];
#define EXIT {puts("No");exit(0);}
void dfs_up(int x,int fa)
{
    if(val[x]<INF)sta[x]=(val[x]&1);
    for(int i=head[x];i;i=e[i].next){
        int v=e[i].to;
        if(v==fa)continue;
        dfs_up(v,x);
        if(sta[x]<INF){
            if(sta[v]<INF && sta[x]^(sta[v]^1))EXIT;
        }else{
            if(sta[v]<INF)sta[x]=(sta[v]^1);
        }
        l[x]=max(l[x],l[v]-1),r[x]=min(r[x],r[v]+1);
    }
    if(l[x]>r[x])EXIT;
}
void dfs_down(int x,int fa)
{
    if(fa){
        l[x]=max(l[x],l[fa]-1),r[x]=min(r[x],r[fa]+1);
        if(sta[x]<INF){
            if(sta[x]^(sta[fa]^1))EXIT;
        }
    }
    if(l[x]>r[x])EXIT;
    if(l[x]==r[x] && (sta[x])^(l[x]&1))EXIT;
    for(int i=head[x];i;i=e[i].next){
        int v=e[i].to;
        if(v==fa)continue;
        dfs_down(v,x);
    }
}
int ans[MAXN];
void getans(int x,int fa)
{
    if(!fa){
        if((l[x]&1)^sta[x])ans[x]=l[x]+1;
        else ans[x]=l[x];
    }else ans[x]=ans[fa]-1,ans[x]+=(ans[x]<l[x])*2;
    for(int i=head[x];i;i=e[i].next){
        int v=e[i].to;
        if(v==fa)continue;
        getans(v,x);
    }
}
int main()
{
    scanf("%d",&n);
    for(int i=1;i<n;++i){
        int u,v;
        scanf("%d%d",&u,&v);
        insert(u,v);
    }
    memset(val,0x3f,sizeof(val));
    memset(l,128,sizeof(l));
    memset(r,127,sizeof(r));
    memset(sta,0x3f,sizeof(sta));
    scanf("%d",&k);
    int x,y,root=1;
    while(k--){
        scanf("%d%d",&x,&y);
        val[x]=y;
        l[x]=r[x]=y;
        root=x;
    }
    dfs_up(root,0);
    dfs_down(root,0);
    puts("Yes");
    getans(root,0);
    for(int i=1;i<=n;++i)
        printf("%d ",ans[i]);
    return 0;
}

