void build(int v, int p = -1) {
	if(!lie(l[v], a[v], r[v]) || (d[v] ^ abs(a[root] - a[v])) % 2 || l[v] > r[v])
		no();
	for(int to : g[v]) {
		if(to != p) {
			if(lie(l[to], a[v] - 1, r[to]))
				a[to] = a[v] - 1;
			else if(lie(l[to], a[v] + 1, r[to]))
				a[to] = a[v] + 1;
			else
				no();
			build(to, v);
		}
	}
}

