int ans[100000];
int a[100000];
int b[100000];
vector <int> v[100000];

void dfs(int x, int y, int l, int r) {
    int i;

    if (ans[x] != 1e9) {
        if (ans[x] < l || ans[x] > r || (r - ans[x]) % 2 == 1) {
            puts("No");

            exit(0);
        }

        a[x] = b[x] = ans[x];

        for (i = 0; i < v[x].size(); i++) {
            if (v[x][i] == y) continue;

            dfs(v[x][i], x, ans[x] - 1, ans[x] + 1);
        }
    } else {
        a[x] = l;
        b[x] = r;

        for (i = 0; i < v[x].size(); i++) {
            if (v[x][i] == y) continue;

            dfs(v[x][i], x, l - 1, r + 1);
        }
    }
}

pair <int, int> dfs2(int x, int y) {
    int i;

    for (i = 0; i < v[x].size(); i++) {
        pair <int, int> p;

        if (v[x][i] == y) continue;

        p = dfs2(v[x][i], x);

        a[x] = max(a[x], p.first);
        b[x] = min(b[x], p.second);
    }

    if (a[x] > b[x]) {
        puts("No");

        exit(0);
    }

    return make_pair(a[x] - 1, b[x] + 1);
}

void dfs3(int x, int y, int z) {
    int i;

    if (a[x] <= z - 1 && b[x] >= z - 1) {
        ans[x] = z - 1;
    } else {
        ans[x] = z + 1;
    }

    for (i = 0; i < v[x].size(); i++) {
        if (v[x][i] == y) continue;

        dfs3(v[x][i], x, ans[x]);
    }
}

