void dfs(int u) {
	for (int i = point[u]; i; i = E[i].nxt) {
		int v = E[i].to;
		if (v == fa[u]) continue;
		fa[v] = u;
		dep[v] = dep[u] + 1;
		dfs(v);
		l[u] = max(l[u], l[v] - 1);
		r[u] = min(r[u], r[v] + 1);
	}
}

void dfs2(int u) {
	for (int i = point[u]; i; i = E[i].nxt) {
		int v = E[i].to;
		if (v == fa[u]) continue;
		num[v] = num[u] + 1;
		if (!(l[v] <= num[v] && num[v] <= r[v]))
			num[v] = num[u] - 1;
		dfs2(v);
	}
}

