				bool r = findAns(e_list,v_val,edge, avg);
				if(r)
					return true;
				edge.push_back(e);
				return false;
			}

		}
		else{
			int f = e.first;
			int ne = e.second; 

			edge.pop_back();
			for(int i=0;i<e_list[ne].size();i++){
				edge.push_back(pair<int,int>(ne,e_list[ne][i]));
			}

			if(v_val[f] > avg){
				v_val[ne] = v_val[f] - 1;

				bool r = findAns(e_list,v_val,edge,avg);
				if(r)
