				v_val[ne] = v_val[f] + 1;

				r = findAns(e_list,v_val,edge,avg);
				if(r)
					return true;

			}else if(v_val[f] == 0){
				v_val[ne] = v_val[f] + 1;

				bool r = findAns(e_list,v_val,edge,avg);
				if(r)
					return true;
			}else{
				v_val[ne] = v_val[f] + 1;

				bool r = findAns(e_list,v_val,edge,avg);
				if(r)
					return true;
				v_val[ne] = v_val[f] - 1;

				r = findAns(e_list,v_val,edge,avg);
				if(r)
					return true;

			}

			v_val[ne] = -2;

			for(int i=0;i<e_list[ne].size();i++){
				edge.pop_back();
			}
			edge.push_back(e);
			return false;
		}
	}
	return findAns(e_list,v_val,edge,avg);
}


