using namespace std;

int main(){

    const int INF = 10000000;

    int N;
    cin >> N;
    vector<vector<int>> E(N);
    vector<int> cnt(N, 0);
    int a, b;
    for(int i = 0; i < N - 1; i++){
        cin >> a >> b;
        E[a - 1].push_back(b - 1);
        E[b - 1].push_back(a - 1);
        cnt[a - 1]++;
        cnt[b - 1]++;
    }

    vector<int> parity(N, 0);
    pair<int, int> infPair = make_pair(INF, INF);
    vector<pair<int, int>> P(N, infPair);
    int K;
    cin >> K;
    int v, p;
    for(int i = 0; i < K; i++){
        cin >> v >> p;
        if(p % 2 == 0){
            parity[v - 1] = 1;
        }
        else{
            parity[v - 1] = -1;
        }
        P[v - 1] = make_pair(p, p);
    }

    vector<bool> checkDfs(N, false);
    queue<int> q1;
    q1.push(v - 1);
    checkDfs[v - 1] = true;
    while(!q1.empty()){
        int temp = q1.front();
        q1.pop();
        int tempParity = parity[temp];

        for(auto node: E[temp]){
            if(checkDfs[node]){
                continue;
            }

            if(parity[node] == 0){
                parity[node] = (tempParity * -1);
            }
            else{
                if(parity[node] == tempParity){
                    cout << "No" << endl;
                    exit(0);
                }
            }

            q1.push(node);
            checkDfs[node] = true;
        }
    }

    vector<bool> check(N, false);
    queue<int> q;
    for(int i = 0; i < N; i++){
        if(cnt[i] == 1){
            cnt[i]--;
            q.push(i);
        }
    }

    int lastNode = 0;
    while(!q.empty()){
        int temp = q.front();
        lastNode = temp;
        q.pop();
        auto tempRange = P[temp];
        check[temp] = true;

        for(auto node: E[temp]){
            if(check[node]){
                continue;
            }

            auto nodeRange = P[node];
            if(nodeRange == infPair && tempRange != infPair){
                P[node] = make_pair(tempRange.first - 1, tempRange.second + 1);
            }
            else if(tempRange != infPair){
                int left = max(nodeRange.first, tempRange.first - 1);
                int right = min(nodeRange.second, tempRange.second + 1);
                if(left > right){
                    cout << "No" << endl;
                    exit(0);
                }
                P[node] = make_pair(left, right);
            }

            cnt[node]--;
            if(cnt[node] == 1){
                q.push(node);
            }
        }
    }

    queue<int> q2;
    vector<bool> checkAns(N, false);
    vector<int> ans(N);
    q2.push(lastNode);
    checkAns[lastNode] = true;

    while(!q2.empty()){
        int temp = q2.front();
        q2.pop();
        auto tempRange = P[temp];
        ans[temp] = tempRange.first;

        for(auto node: E[temp]){
            if(checkAns[node]){
                continue;
            }
            auto nodeRange = P[node];
            if(nodeRange == infPair){
                P[node] = make_pair(tempRange.first - 1, tempRange.first + 1);
            }
            else{
                int f = tempRange.first;
                if(nodeRange.first <= f - 1 && f - 1 <= nodeRange.second){
                    P[node] = make_pair(f - 1, f - 1);
                }
                else if(nodeRange.first <= f + 1 && f + 1 <= nodeRange.second){
                    P[node] = make_pair(f + 1, f + 1);
                }
                else{
                    cout << "No" << endl;
                    exit(0);
                }
            }
            q2.push(node);
            checkAns[node] = true;
        }
    }

    cout << "Yes" << endl;
    for(int i = 0; i < N; i++){
        cout << ans[i] << endl;
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;
vector<int> v[100005];
pair<int,int> r[100005];
int dep[100005],sz[100005];
bool del[100005];
void get(int node,int p)
{
	dep[node]=dep[p]+1;
	r[node]={-1e9,1e9};
	for (int u:v[node])
	{
		if (u!=p)
		get(u,node);
	}
}
int pre(int node,int p)
{
	sz[node]=1;
	for (int u:v[node])
	{
		if (u!=p && !del[u])
		sz[node]+=sz[u];
	}
	return sz[node];
}
int find(int node,int p,int nn)
{
	for (int u:v[node])
	{
		if (u!=p && !del[u] && sz[u]>nn/2)
		return find(u,node,nn);
	}
	return node;
}
void update1(int node,int p)
{
	for (int u:v[node])
	{
		if (u!=p && !del[u])
		{
			update1(u,node);
			r[node].first=max(r[node].first,r[u].first-1);
			r[node].second=min(r[node].second,r[u].second+1);
		}
	}
	if (r[node].first>r[node].second)
	{
		printf("No");
		exit(0);
	}
}
void update2(int node,int p)
{
	if (p)
	{
		r[node].first=max(r[node].first,r[p].first-1);
		r[node].second=min(r[node].second,r[p].second+1);
	}
	for (int u:v[node])
	{
		if (u!=p && !del[u])
		update2(u,node);
	}
}
void dfs(int node)
{
	int c=find(node,0,pre(node,0));
	update1(c,0);
	r[c].second=r[c].first;
	update2(c,0);
	del[c]=1;
	for (int u:v[c])
	{
		if (!del[u])
		dfs(u);
	}
}
int main()
{
	int n,q;
	scanf("%d",&n);
	for (int i=1;i<n;i++)
	{
		int a,b;
		scanf("%d%d",&a,&b);
		v[a].push_back(b);
		v[b].push_back(a);
	}
	get(1,0);
	scanf("%d",&q);
	set<int> s;
	while (q--)
	{
		int a,b;
		scanf("%d%d",&a,&b);
		r[a]={b,b};
		s.insert((dep[a]+b)%2);
	}
	if (s.size()!=1)
	{
		printf("No");
		return 0;
	}
	dfs(1);
	printf("Yes");
	for (int i=1;i<=n;i++)
	printf("\n%d",r[i].first);
}

