			if (!(L[ch]-1 <= L[v] && L[v] < R[ch]+1)) return false;
			if (evenOdd[v] == 1) if ((evenOdd[ch]&2) == 0) return false;
			if (evenOdd[v] == 2) if ((evenOdd[ch]&1) == 0) return false;
		}
	} else {
		R[v] = 1e9;
		for (int ch : G[v]) if (ch != p) {
			L[v] = max(L[v], L[ch]-1);
			R[v] = min(R[v], R[ch]+1);
			int tmp = 0;
			if (evenOdd[ch] == 1) tmp = 2;
			else if (evenOdd[ch] == 2) tmp = 1;
			else if (evenOdd[ch] == 3) tmp = 3;
			else assert(0);
			evenOdd[v] &= tmp;
			if (evenOdd[v] == 0) return false;
			if (evenOdd[v] == 1) {
				if (L[v]%2 == 1) L[v]++;
				if ((R[v]-1)%2 == 1) --R[v];
			} else if (evenOdd[v] == 2) {
				if (L[v]%2 == 0) L[v]++;
				if ((R[v]-1)%2 == 0) --R[v];
			}
			if (L[v] >= R[v]) return false;
		}
	}
	return true;
}

void dfs2(int v, int p, int pNum) {
	int num = pNum-1;
	if (L[v] > num || num >= R[v]) num = pNum+1;
	ans[v] = num;
	for (int ch : G[v]) if (ch != p) {
		dfs2(ch, v, num);
	}
}

