		G[A[i]].push_back(B[i]);
		G[B[i]].push_back(A[i]);
	}
	for (int i = 0; i < N; i++) {
		evenOdd[i] = 3;
	}
	cin >> K;
	for (int i = 0; i < K; i++) {
		cin >> V[i] >> P[i];
		--V[i];
		L[V[i]] = P[i];
		R[V[i]] = P[i]+1;
		if (P[i] % 2 == 0) evenOdd[V[i]] = 1;
		else evenOdd[V[i]] = 2;
	}
	if (!dfs(0, -1)) {
		cout << "No" << endl;
	} else {
		cout << "Yes" << endl;
		dfs2(0, -1, L[0]-1);
