void combine(int x, int v)
{
    int takev = (mi[0][v].second == x);
    if(mi[takev][v].first - 1 > mi[0][x].first)
    {
        mi[1][x] = mi[0][x];
        mi[0][x] = {mi[takev][v].first - 1, v};
    }
    else if(mi[takev][v].first - 1 > mi[1][x].first)
        mi[1][x] = {mi[takev][v].first - 1, v};

    if(ma[takev][v].first + 1 < ma[0][x].first)
    {
        ma[1][x] = ma[0][x];
        ma[0][x] = {ma[takev][v].first + 1, v};
    }
    else if(ma[takev][v].first + 1 < ma[1][x].first)
        ma[1][x] = {ma[takev][v].first + 1, v};
}

void up(int x, int p)
{
    for(auto v : adj[x])
        if(v != p)
        {
            up(v, x);
            combine(x, v);
            for(int j = 0; j < 2; j++)
                reqparity[j][x] |= reqparity[j ^ 1][v];
        }
}

void down(int x, int p)
{
    if(p != -1)
    {
        combine(x, p);
        for(int j = 0; j < 2; j++)
            reqparity[j][x] |= reqparity[j ^ 1][p];
    }
    for(auto v : adj[x])
        if(v != p)
            down(v, x);
}

