bool pr[100010][2];
void die(string st){
	cout<<st<<endl;
	exit(0);
}
void dfs(int x=1){
	vis[x]=1;
	ll[x]=-INF-1;
	rr[x]=INF+1;
	for(auto to:G[x]){
		if(vis[to])continue;
		dfs(to);
		par[to]=x;
		if(pr[to][0])pr[x][1]=1;
		if(pr[to][1])pr[x][0]=1;
		ll[x]=max(ll[x],ll[to]-1);
		rr[x]=min(rr[x],rr[to]+1);
	}
	if(known[x]){
		ll[x]=max(ll[x],val[x]);
		rr[x]=min(rr[x],val[x]);
		pr[x][val[x]%2]=1;
	}
	if(pr[x][0]==1&&pr[x][1]==1)die("No");
	if(ll[x]>rr[x])die("No");
	ord.pb(x);
}
void make(int x=1){
	vis[x]=1;
	if(x==1&&!known[x])val[x]=ll[x];
	for(auto to:G[x]){
		if(vis[to])continue;
		if(!known[to]){
			if(ll[to]<=val[x]-1&&val[x]-1<=rr[to])val[to]=val[x]-1;
			else val[to]=val[x]+1;
		}
		make(to);
	}
}
