const int INF = 1e9;
using Graph = vector<vector<int>>;
void recur(const Graph &G, vector<int> &A, vector<int> &B, int node, int prv) {
    for (auto nxt : G[node]) if (nxt != prv) {
        A[nxt] = max(A[nxt], A[node] - 1);
        B[nxt] = min(B[nxt], B[node] + 1);
    }
    for (auto nxt : G[node]) if (nxt != prv) {
        recur(G, A, B, nxt, node);
    }
    for (auto nxt : G[node]) if (nxt != prv) {
        A[node] = max(A[node], A[nxt] - 1);
        B[node] = min(B[node], B[nxt] + 1);
    }
}
int main() {
    int N; cin >> N;
    Graph G(N);
    vector<int> A(N, -INF), B(N, INF);
    for (int i = 0; i < N-1; i++) {
        int a, b; cin >> a >> b; a--, b--;
        G[a].push_back(b);
        G[b].push_back(a);
    }
    int K; cin >> K;
    for (int i = 0; i < K; i++) {
        int v, p; cin >> v >> p; v--;
        A[v] = B[v] = p;
    }
    recur(G, A, B, 0, -1);
    recur(G, A, B, 0, -1);
    for (int i = 0; i < N; i++) {
        if (A[i] > B[i]) {
            cout << "No\n";
            return 0;
        }
    }
    cout << "Yes\n";
    for (int i = 0; i < N; i++) {
        cout << A[i] << '\n';
    }
    return 0;
}

