void dfs1(int u,int p)
{
    for(int i=Adj[u];i;i=nxt[i])
    {
        int v=V[i];
        if(v==p) continue;
        dfs1(v,u);
        R[u]=min(R[v]+1,R[u]);
        L[u]=max(L[v]-1,L[u]);
        if(odd[v]!=-1)
        {
            if(odd[u]==-1) odd[u]=!odd[v];
            else if(odd[v]==odd[u])
            {
                printf("No\n");
                exit(0);
            }
        }
    }
}
void dfs2(int u,int p)
{
    if(p)
    {
        R[u]=min(R[u],R[p]+1);
        L[u]=max(L[u],L[p]-1);
        if(odd[u]==-1) odd[u]=!odd[p];
    }
    if(L[u]>R[u]||(L[u]==R[u]&&odd[u]!=(L[u]&1)))
    {
        printf("No\n");
