void dfs3(int u, int fa){
    if(!fa){
        if(r[u] < l[u]) flag = true;
        if(l[u] == r[u] && ((l[u] & 1) != col[u])) flag = true;
        if((l[u] & 1) != col[u]) val[u] = l[u] + 1;
