int c0,c1,dep[maxn],fa[maxn];
int tote,TO[maxm],NEXT[maxm],FIR[maxn];

void addedge(int u,int v)
{
	TO[++tote]=v;
	NEXT[tote]=FIR[u];
	FIR[u]=tote;
}

void prework(int u)
{
	dep[u]=dep[fa[u]]+1;
	for (int p=FIR[u];p;p=NEXT[p])
	{
		int v=TO[p];
		if (v==fa[u]) continue;
		fa[v]=u;
		prework(v);
	}
}

bool solve1(int u)
{
	bool flag=1;
	for (int p=FIR[u];p;p=NEXT[p])
	{
		int v=TO[p];
		if (v==fa[u]) continue;
		flag&=solve1(v);
	}
	if (L[u]>-1e7||R[u]<1e7)
	{
		L[fa[u]]=max(L[fa[u]],L[u]);
		R[fa[u]]=min(R[fa[u]],R[u]+2);
	}
	return flag&(L[u]<=R[u]);
}

void solve2(int u)
{
	if (L[u]<=-1e7&&R[u]>=1e7)
		L[u]=R[u]=L[fa[u]];
	else
	{
		if (!fa[u]) R[u]=L[u];
		else
		{
			if (L[u]<=L[fa[u]]&&L[fa[u]]<=R[u])
				L[u]=R[u]=L[fa[u]];
			else
				L[u]=R[u]=L[fa[u]]-2;
		}
	}
	for (int p=FIR[u];p;p=NEXT[p])
		if (TO[p]!=fa[u]) solve2(TO[p]);
}

