using namespace std;

int large[100001];
int small[100001];
int mod2[100001];
bool arrived[100001];
bool used[100001];
vector<int> edge[100001];
bool dfs(int V,int S,int L, int flag){
   //cout << V << ": " << S << "-" << L <<", "<< flag<<endl;
   if( arrived[V] || used[V] ) return true;
   arrived[V] = true;
   L=min(large[V],L);
   S=max(small[V],S);
   if( L%2!=flag ) L--;
   if (S%2!=flag ) S++;
   if( L < S ) return false;
   if( mod2[V] != -1 && mod2[V] != flag ) return false;
   //cout << V << ": " << S << "-" << L <<", "<< flag<<endl;
   large[V]=L;
   small[V]=S;
   mod2[V]=flag;
   for( int i = 0 ; i < (int)edge[V].size(); i++ ){
      if( arrived[edge[V][i]]!=true ){
         if( dfs( edge[V][i], S-1, L+1, 1-flag ) == false ){
            return false;
         }
      }
   }
   return true;
}
void dfs2(int V, int P){
   if( arrived[V] ) return ;
   arrived[V] = true;
   large[V]=P;
   small[V]=P;
   for( int i = 0 ; i < (int) edge[V].size(); i++ ){
      if( arrived[edge[V][i]] != true ){
         int next = edge[V][i];
         if( large[next] >= P+1 && small[next] <= P+1 ){
            dfs2(next,P+1);
         }
         else if( large[next] >= P-1 && small[next] <= P-1 ){
            dfs2(next,P-1);
         }
         else{
            cout <<" ERROR" << endl;
         }
      }
   }
}
int main(){
   int N;
   cin >> N;
   for( int i = 0 ; i < N+1; i++ ){
      large[i] = INT_MAX/2;
      small[i] = INT_MAX/-2;
   }
   for( int i = 0 ; i+1 < N ; i++ ){
      int A,B;
      cin >> A >> B;
      edge[A].push_back(B);
      edge[B].push_back(A);
   }
   int K;
   cin >> K;
   bool ok = true;
   int lastV=0,lastP=0;
   memset( used, false,sizeof(used));
   memset( mod2, -1, sizeof(mod2));
   for( int i = 0 ; i <K; i++ ){
      int V,P;
      cin >> V>>P;
      lastV=V;lastP=P;
      if( small[V] > P || large[V] < P ){
         ok = false;
      }
      if(ok){
         memset(arrived,false,sizeof(arrived));
         ok= dfs(V,P,P,P%2);
         used[V]=true;
      }
   }
   if( ok == false ){
      cout<< "No"<<endl;
      return 0;
   }
   else{
      cout << "Yes" << endl;
      memset(arrived,false,sizeof(arrived));
      dfs2(lastV, lastP);
   }
   for( int i = 1 ; i <= N; i++ ){
      cout << large[i] << endl;
   }
   return 0;
}

