using namespace std;

const int MAXN = 1e5+5;

vector <int> adj[MAXN];

int L[MAXN], R[MAXN];

int ans[MAXN];

bool d[MAXN];

int n, k;

void dfs(int v, int pr) {
    for (int to : adj[v]) {
        if (to == pr) {
            continue;
        }

        d[to] = (d[v] ^ 1);

        L[to] = max(L[to], L[v] - 1);
        R[to] = min(R[to], R[v] + 1);

        dfs(to, v);
    }

    for (int to : adj[v]) {
        if (to == pr) {
            continue;
        }

        L[v] = max(L[v], L[to] - 1);
        R[v] = min(R[v], R[to] + 1);
    }
}

void rec(int v, int pr) {
    while (L[v] % 2 != d[v]) {
        ++L[v];
    }

    while (R[v] % 2 != d[v]) {
        --R[v];
    }

    for (int to : adj[v]) {
        if (to == pr) {
            continue;
        }

        L[to] = max(L[to], L[v] - 1);
        R[to] = min(R[to], R[v] + 1);

        rec(to, v);
    }
}

void solve() {
    scanf("%d", &n);

    for (int i = 1, l, r; i < n; ++i) {
        scanf("%d %d", &l, &r);

        adj[l].pb(r);
        adj[r].pb(l);
    }

    for (int i = 1; i <= n; ++i) {
        L[i] = -500000;
        R[i] = 500000;
    }

    scanf("%d", &k);

    int root = -1;

    for (int i = 1, ps, x; i <= k; ++i) {
        scanf("%d %d", &ps, &x);
        L[ps] = R[ps] = x;
        root = ps;
    }

    d[root] = L[root] % 2;

    dfs(root, -1);
    rec(root, -1);

    for (int i = 1; i <= n; ++i) {
        if (L[i] > R[i]) {
            printf("No\n");
            return;
        }
    }

    printf("Yes\n");

    for (int i = 1; i <= n; ++i) {
        printf("%d\n", L[i]);
    }
}

int main() {
    int tt = 1;

    while (tt--) {
        solve();
    }

    return 0;
}

