#define MAXN 100000
const int INF=1e9;
using namespace std;
vector<int> G[MAXN+5];
int d[MAXN+5],val[MAXN+5];
int L[MAXN+5],R[MAXN+5];
bool vis[MAXN+5];
void Init()
{
	memset(vis,0,sizeof(vis));
	for(int i=0;i<=MAXN+3;i++)
		L[i]=-INF,R[i]=INF;
}
bool DFS(int u,int fa,bool typ)
{
	if(vis[u]==true&&typ!=val[u]%2)
		return false;
	for(int i=0;i<G[u].size();i++)
	{
		int v=G[u][i];
		if(v==fa)
			continue;
		if(DFS(v,u,!typ)==false)
			return false;
	}
	return true;
}
bool DFS2(int u,int fa)
{
	if(vis[u]==true)
		L[u]=R[u]=val[u];
	for(int i=0;i<G[u].size();i++)
	{
		int v=G[u][i];
		if(v==fa)
			continue;
		if(DFS2(v,u)==false)
			return false;
		L[u]=max(L[v]-1,L[u]);
		R[u]=min(R[v]+1,R[u]);
	}
	if(L[u]>R[u])
		return false;
	return true;
}
void DFS3(int u,int fa,int vn)
{
	val[u]=vn;
	for(int i=0;i<G[u].size();i++)
	{
		int v=G[u][i];
		if(v==fa)
			continue;
		if(L[v]<=vn-1&&vn-1<=R[v])
			DFS3(v,u,vn-1);
		else 
			DFS3(v,u,vn+1);
	}
}
int main()
{
	Init();
	int n,u,v;
	scanf("%d",&n);
	for(int i=1;i<n;i++)
	{
		scanf("%d %d",&u,&v);
		G[u].push_back(v);
		G[v].push_back(u);
		d[u]++,d[v]++;
	}
	int maxd=0,rt,k;
	scanf("%d",&k);
	for(int i=1;i<=k;i++)
	{
		scanf("%d %d",&u,&v);
		val[u]=v;
		vis[u]=true;
		if(d[u]>maxd)
			maxd=d[u],rt=u;
	}
	if(DFS(rt,-1,val[rt]%2)==false)
		printf("No\n");
	else if(DFS2(rt,-1)==false)
		printf("No\n");
	else
	{
		DFS3(rt,-1,val[rt]);
		printf("Yes\n");
		for(int i=1;i<=n;i++)
			printf("%d\n",val[i]);
	}
	return 0;
}
