	for(int i=1;i<=k;i++)
	{
		scanf("%d %d",&u,&v);
		val[u]=v;
		vis[u]=true;
		if(d[u]>maxd)
			maxd=d[u],rt=u;
	}
	if(DFS(rt,-1,val[rt]%2)==false)
		printf("No\n");
	else if(DFS2(rt,-1)==false)
		printf("No\n");
	else
	{
		DFS3(rt,-1,val[rt]);
		printf("Yes\n");
		for(int i=1;i<=n;i++)
			printf("%d\n",val[i]);
	}
	return 0;
}
