const int INF = 1e9;
const int MOD = INF + 7;
const LL LLINF = 1e18;

int N, K;
vector<set<int>> graph;
VPII edge; //(min, max)
PII edef = MP(-INF, INF);
bool ng = false;
VI ans;

void dfs(int nowPoint, int backPoint) {
    PII &e = edge[nowPoint];
    FORE(el, graph[nowPoint]) {
        if (el == backPoint) continue;
        dfs(el, nowPoint);
        if (e.first != e.second) {
            e.first = max(e.first, edge[el].first - 1);
            e.second = min(e.second, edge[el].second + 1);
        } else {
            int num = e.first;
            if (!(edge[el].first - 1 <= num && num <= edge[el].second + 1)) {
                ng = true;
            }
        }
        if (e.first > e.second) ng = true;
    }
}

void dfs2(int nowPoint, int backPoint, bool isOdd) {
    PII &e = edge[nowPoint];
    if (e.first == e.second) {
        ans[nowPoint] = e.first;
        if (e.first % 2 != isOdd) {
            ng = true;
        }
    } else {
        if (backPoint != -1) {
            int backnum = ans[backPoint];
            if (backnum + 1 <= e.second && (backnum + 1) %2 == isOdd) {
                ans[nowPoint] = backnum + 1;
            } else if (backnum - 1 >= e.first && (backnum - 1) % 2 == isOdd) {
                ans[nowPoint] = backnum - 1;
            } else {
                ng = true;
            }
        }
    }
    FORE(el, graph[nowPoint]) {
        if (el == backPoint) continue;
        dfs2(el, nowPoint, !isOdd);
    }
}

int main(void) {
    scanf("%d", &N);
    graph.resize(N);
    edge.resize(N, edef);
    ans.resize(N, 0);
    REP(i, N - 1) {
        int a, b;
        scanf("%d%d", &a, &b);
        a--;b--;
        graph[a].insert(b);
        graph[b].insert(a);
    }
    scanf("%d", &K);
    VPII vp(K);
    REP(i, K) {
        int v, p;
        scanf("%d%d", &v, &p);
        v--;
        edge[v] = MP(p, p);
        vp[i] = MP(v, p);
    }
    dfs(vp[0].first, -1);
    // REP(i, edge.size()) {
    //     cerr << i << " " << edge[i].first << " " << edge[i].second << endl;
    // }
    dfs2(vp[0].first, -1, vp[0].second % 2);
    if (ng) {
        cout << "No" << endl;
        return 0;
    } else {
        cout << "Yes" << endl;
    }
    FORE(el, ans) {
        printf("%d\n", el);
    }
}

#include <bits/stdc++.h>
#define LL long long
#define pb push_back
#define mp make_pair
#define INF 0x3f3f3f3f
#define Inf 1000000000000000000LL
using namespace std;
typedef pair<int,int>pii;
int n,k;
bool ok=1;
vector<int>G[100010];
int id[100010];
int L[100010],R[100010];
void solve(int v=0,int p=-1){
	L[v]=-INF-1,R[v]=INF+1;
	for(auto to:G[v]){
		if(to!=p){
			solve(to,v);
			if(L[to]<-INF/2)continue;
			if(L[v]<-INF/2){
				L[v]=L[to]-1;
				R[v]=R[to]+1;
			}else{
				if(abs(L[to])%2==abs(L[v])%2){
					ok=0;
					return;
				}
				L[v]=max(L[v],L[to]-1);
				R[v]=min(R[v],R[to]+1);
			}
		}
	}
	if(L[v]>R[v])ok=0;
}
void make(int v=0,int p=-1){
	if(v==0&&id[v]==-1)id[v]=L[v];
	for(auto to:G[v]){
		if(to!=p){
			if(id[to]==-1){
				if(L[to]<=id[v]-1&&id[v]-1<=R[to])id[to]=id[v]-1;
				else id[to]=id[v]+1;
			}
			make(to,v);
		}
	}
}
int main(){
	cin>>n;
	for(int i=1,x,y;i<n;i++){
		cin>>x>>y;
		G[x].pb(y);
		G[y].pb(x);
	}
	cin>>k;
	for(int i=1,x,y;i<=k;i++){
		cin>>x>>y;
		id[x]=y;
	}
	solve();
	if(!ok){
		puts("No");
		return 0;
	}else{
		make();
		puts("Yes");
		for(int i=1;i<=n;i++)cout<<id[i]<<endl;
	}
	return 0;
}

