int get()
{
		int res = 1, Q = 1; char c;
		while( (c = getchar()) < 48 || c > 57)
			if(c == '-') Q = -1;
		if(Q) res = c - 48;
		while( (c = getchar()) >= 48 && c <= 57)
			res = res * 10 + c - 48;
		return res * Q;
}

struct power
{
		int l, r;
}val[ONE];

int n, k;
int x, y;
int pd[ONE];
int next[ONE], first[ONE], go[ONE], tot;

void Add(int u, int v)
{
		next[++tot] = first[u], first[u] = tot, go[tot] = v;
		next[++tot] = first[v], first[v] = tot, go[tot] = u;
}

void dfs(int u, int father)
{
		if(val[u].l == val[u].r) pd[u] = val[u].l % 2;
		for(int e = first[u]; e; e = next[e])
		{
			int v = go[e];
			if(v == father) continue;
			dfs(v, u);
			int x = 2;
			if(pd[v] == 0) x = 1; if(pd[v] == 0) x = 1;
			if(pd[u] != 2 && x != 2 && pd[u] != x) {printf("No"); exit(0);}
			if(x != 2) pd[u] = x;
		}
}

void dfs1(int u, int father)
{
		for(int e = first[u]; e; e = next[e])
		{
			int v = go[e];
			if(v == father) continue;
			dfs1(v, u);
			val[u].l = max(val[u].l, val[v].l - 1);
			val[u].r = min(val[u].r, val[v].r + 1);
			if(val[u].l > val[u].r) {printf("No"); exit(0);}
		}
}

int A[ONE];

void dfs2(int u, int father)
{
		if(u != 1)
			if(val[u].l <= A[father] - 1 && A[father] - 1 <= val[u].r) A[u] = A[father] - 1;
			else if(val[u].l <= A[father] + 1 && A[father] + 1 <= val[u].r) A[u] = A[father] + 1;
			else {printf("No"); exit(0);}

		for(int e = first[u]; e; e = next[e])
		{
			int v = go[e];
			if(v == father) continue;
			dfs2(v, u);
		}
}

int main()
{
		n = get();
		for(int i = 1; i < n; i++) x = get(), y = get(), Add(x, y);
		for(int i = 1; i <= n; i++) val[i] = (power){0, INF}, pd[i] = 2;
		k = get();
		for(int i = 1; i <= k; i++) x = get(), y = get(), val[x] = (power){y, y};

		dfs(1, 0);
		dfs1(1, 0);

		A[1] = val[1].l;
		if(A[1] % 2 != pd[1]) A[1]++;
		if(!(val[1].l <= A[1] && A[1] <= val[1].r)) {printf("No"); exit(0);}

		dfs2(1, 0);

		printf("Yes\n");
		for(int i = 1; i <= n; i++)
			printf("%d\n", A[i]);
}

