typedef vector<vi> vvi;
typedef vector<pii> vp;
typedef vector<vp> vvp;
typedef vector<string> vs;
typedef vector<double> vd;
typedef pair<int,pii> pip;
typedef vector<pip>vip;
const double PI=acos(-1);
const double EPS=1e-8;
const int inf=1e8;
class DIJ{
	public:
	struct edge{
		int to,cost;
	};
	vector<vector<edge> >G;
	vp in;
	int n;
	vi d;//distance
	DIJ(int size){
		n=size;
		G=vector<vector<edge> >(n);
	}
	void add_edge(int a,int b,int c){
		edge e={b,c},ee={a,c};
		G[a].pb(e);
		G[b].pb(ee);
	}
	void dij(){
		d=vi(n,inf);
		priority_queue<pii>q;
		rep(i,m){
			int a=in[i].first,b=in[i].second
			q.push(pii(-b,a-1));
			d[a-1]=b;
		}
		while(!q.empty()){
			pii p=q.top();
			q.pop();
			int pos=p.second,cost=-p.first;
			if(cost>d[pos])continue;
			rep(i,G[pos].size()){
				edge e=G[pos][i];
				int to=e.to;
				int nowcost=cost+e.cost;
				if(nowcost<d[to]){
					d[to]=nowcost;
					q.push(pii(-d[to],to));
				}
			}
		}
	}
	void solve(){
		rep(i,n-1){
			int a,b;
			cin>>a>>b;
			a--;b--;
			add_edge(a,b,1);
			add_edge(b,a,1);
		}
		int m;
		cin>>m;
		in=vp(m);
		rep(i,m)cin>>in[i].first>>in[i].second;
		dij();
		bool h=true;
		rep(i,n)rep(j,G[i].size()){
			int to=G[i][j].to;
			if(abs(d[i]-d[to])!=G[i][j].cost)h=false;
		}
		rep(i,m)if(in[i].second!=d[in.first-1])h=false;
		if(h){
			cout<<"Yes"<<endl;
			rep(i,n)cout<<d[i]<<endl;
		}else cout<<"No"<<endl;
	}
};
int main(){
	int n;
	cin>>n;
	DIJ dij(n);
	dij.solve();
}

