#include<bits/stdc++.h>
#define Rint register int
using namespace std;
const int N = 100003, INF = 0x3f3f3f3f;
int n, k, fa[N], head[N], to[N << 1], nxt[N << 1], p[N], v[N], val[N];
inline void add(int a, int b){
	static int cnt = 0;
	to[++ cnt] = b; nxt[cnt] = head[a]; head[a] = cnt;
}
bool odd[N];
inline void dfs(int x){
	for(Rint i = head[x];i;i = nxt[i])
		if(to[i] != fa[x]){
			fa[to[i]] = x;
			odd[to[i]] = odd[x] ^ 1;
			dfs(to[i]);
		}
}
int l[N], r[N];
inline void dfs2(int x){
	if(val[x] < INF) l[x] = r[x] = val[x];
	else l[x] = -INF, r[x] = INF;
	for(Rint i = head[x];i;i = nxt[i])
		if(to[i] != fa[x]){
			dfs2(to[i]);
			l[x] = max(l[x], l[to[i]] - 1);
			r[x] = min(r[x], r[to[i]] + 1);
		}
}
inline void dfs3(int x){
	for(Rint i = head[x];i;i = nxt[i])
		if(to[i] != fa[x]){
			if(val[to[i]] == INF && val[x] + 1 >= l[to[i]] && val[x] + 1 <= r[to[i]]) val[to[i]] = val[x] + 1;
			else if(val[to[i]] == INF && val[x] - 1 >= l[to[i]] && val[x] - 1 <= r[to[i]]) val[to[i]] = val[x] - 1;
			else if(val[to[i]] == INF){puts("No"); exit(0);}
			dfs3(to[i]);
		}
}
int main(){
	scanf("%d", &n);
	for(Rint i = 1;i < n;i ++){
		int a, b;
		scanf("%d%d", &a, &b);
		add(a, b); add(b, a);
	}
	scanf("%d", &k);
	dfs(1);
	memset(val, 0x3f, sizeof val);
	for(Rint i = 1;i <= k;i ++){
		scanf("%d%d", p + i, v + i);
		val[p[i]] = v[i];
		if(i > 1 && (v[i] % 2 + odd[p[i]] % 2 + 4) % 2 != (v[i - 1] % 2 + odd[p[i - 1]] % 2 + 4) % 2){
			puts("No"); return 0;
		}
	}
	dfs2(1); val[1] = l[1];
	for(Rint i = 1;i <= n;i ++)
		if(l[i] > r[i]){puts("No"); return 0;}
	dfs3(1);
	puts("Yes");
	for(Rint i = 1;i <= n;i ++) printf("%d\n", val[i]);
}

#include <bits/stdc++.h>
