#define Inf 1000000000000000000LL
using namespace std;
typedef pair<int,int>pii;
int n,m;
vector<int>G[100010];
int id[100010],ll[100010],rr[100010];
bool ok=1;
void dfs(int x,int p=-1){
	ll[x]=-INF-1;
	rr[x]=INF+1;
	if(id[x]!=-1)ll[x]=rr[x]=id[x];
	for(auto to:G[x]){
		if(to==p)continue;
		dfs(to,x);
		if(ll[to]<-INF/2)continue;
		if(ll[x]<-INF/2){
			ll[x]=ll[to]-1;
			rr[x]=rr[to]+1;
		}else{
			if(abs(ll[x])%2==abs(ll[to])%2){
				ok=0;
				return;
			}
			ll[x]=max(ll[x],ll[to]-1);
			rr[x]=min(rr[x],rr[to]+1);
		}
	}
	if(ll[x]>rr[x])ok=0;
}
void make(int x,int p=-1){
	if(x==1&&id[x]==-1)id[x]=ll[x];
	for(auto to:G[x]){
		if(to==p)continue;
		if(id[to]==-1){
			if(ll[to]<=id[x]-1&&id[x]-1<=rr[to])id[to]=id[x]-1;
			else id[to]=id[x]+1;
		}
		make(to,x);
	}
}
int main(){
	memset(id,-1,sizeof(id));
	cin>>n;
	for(int i=1,x,y;i<n;i++){
		cin>>x>>y;
		G[x].pb(y);
		G[y].pb(x);
	}
	cin>>m;
	for(int i=1,x,y;i<=m;i++){
		cin>>x>>y;
		id[x]=y;
	}
	dfs(1);
	if(ok){
		make(1);
		puts("Yes");
		for(int i=1;i<=n;i++)cout<<id[i]<<endl;
		// for(int i=1;i<=n;i++)cout<<ll[i]<<' '<<rr[i]<<endl;
	}else puts("No");
	return 0;
}

