using namespace std;
const int V=100000;
const int E=200000;
const int INF=0x3f3f3f3f;
int n,k,v[V+10],l[V+10],r[V+10];
int fir[V+10],nxt[E+10],to[E+10],tote;
void adde(int u,int v){to[++tote]=v;nxt[tote]=fir[u];fir[u]=tote;}
bool build(int u,int fa)
{
	if(~v[u])l[u]=r[u]=v[u];
	else{l[u]=-INF;r[u]=INF;}
	bool flag=true;
	for(int i=fir[u],v;i;i=nxt[i])
	{
		if((v=to[i])==fa)continue;
		flag&=build(v,u);
		l[u]=max(l[u],l[v]-1);
		r[u]=min(r[u],r[v]+1);
	}
	return flag&&l[u]<=r[u];
}
void solve(int u,int fa)
{
	if(u==1)v[u]=l[u];
	else if(l[u]<=v[fa]-1&&v[fa]-1<=r[u])v[u]=v[fa]-1;
	else v[u]=v[fa]+1;
	for(int i=fir[u],v;i;i=nxt[i])if((v=to[i])!=fa)solve(v,u);
}
bool check(int u,int fa)
{
	bool flag=((u==1)||(abs(v[u]-v[fa])==1));
	for(int i=fir[u],v;i;i=nxt[i])if((v=to[i])!=fa)flag&=check(v,u);
	return flag;
}
int main()
{
	scanf("%d",&n);
	for(int i=1,a,b;i<n;++i)
	{
		scanf("%d%d",&a,&b);
		adde(a,b);adde(b,a);
	}
	memset(v,-1,sizeof v);
	scanf("%d",&k);
	for(int i=1,a,b;i<=k;++i)
	{
		scanf("%d%d",&a,&b);
		v[a]=b;
	}
	if(build(1,0)&&(solve(1,0),check(1,0)))
	{
		puts("Yes");
		for(int i=1;i<=n;++i)printf("%d\n",v[i]);
	}
	else puts("No");
	return 0;
}

