vector<int>ans;

array<int, 2>dfs1(int pos, int lb, int ub, int prevpos) {
	int nextlb, nextub;
	if (bound[pos][0] == -1) {
		nextlb = lb - 1;
		nextub = ub + 1;
	}
	else {
		int fixnum = bound[pos][0];
		if (fixnum < lb || ub < fixnum || (fixnum - lb) % 2 != 0) {
			return{ intmax,intmax };
		}
		lb = fixnum;
		ub = fixnum;
		nextlb = fixnum-1;
		nextub = fixnum+1;
	}

	for (auto x : g[pos])if (x != prevpos) {
		auto re = dfs1(x, nextlb, nextub, pos);
		if (re[0] == intmax)return{ intmax,intmax };
		lb = max(lb, re[0]);
		ub = min(ub, re[1]);
	}
	assert(lb <= ub);
	bound[pos] = { lb,ub };
	return{ lb - 1,ub + 1 };
}

void dfs2(int pos, int lb, int ub, int prevpos) {
	assert((bound[pos][0] <= lb && lb <= bound[pos][1]) || (bound[pos][0] <= ub && ub <= bound[pos][1]));
	if (bound[pos][0] <= lb && lb <= bound[pos][1])ans[pos] = lb;
	else ans[pos] = ub;
	for (auto x : g[pos])if (x != prevpos) {
		dfs2(x, ans[pos] - 1, ans[pos] + 1, pos);
	}
}


