bool dfs(int r , int e){
	b[e] = 1;
	if(r >= 0 && P[e] >= 0){
		if((w[e][0] + P[e]) % 2 == 1 || (P[e] < w[e][0] || w[e][1] < P[e])) return 0;
		w[e][0] = w[e][1] = P[e];
		return dfs(-1 , e);
