		w[*it][0] = w[e][0] - 1;
		w[*it][1] = w[e][1] + 1;
		if(!dfs(e,*it)) return 0;
		w[e][0] = max(w[e][0] , w[*it][0] - 1);
		w[e][1] = min(w[e][1] , w[*it][1] + 1);
		if(w[e][0] > w[e][1]) return 0;
	}
	return 1;
}

