ll N, K;
std::vector<ll> G[MAX_N];
ll L[MAX_N], R[MAX_N], A[MAX_N];
bool used[MAX_N];
bool fl = true;

bool dfs( int v, int prv )
{
  used[v] = true;

  //printf( "(%d,%d)\n", v, prv );

  for( auto &u : G[v] ) if( !used[u] )
  {
    if( R[u] < L[v]-1 || R[v]+1 < L[u] )
    { fl = false; return false; }

    L[u] = std::max( L[u], L[v]-1 );
    R[u] = std::min( R[u], R[v]+1 );

    if( !dfs( u, v ) )
      return false;
  }

  if( R[prv] < L[v]-1 || R[v]+1 < L[prv] )
  { fl = false; return false; }

  L[prv] = std::max( L[prv], L[v]-1 );
  R[prv] = std::min( R[prv], R[v]+1 );

  return true;
}

void calc( int v, int prv )
{
  used[v] = true;

  //printf( "{%d}\n", v+1 );

  if( v == prv )
    A[v] = std::max( 0ll, L[v] );
  else if( L[v] <= A[prv]+1 && A[prv]+1 <= R[v] )
    A[v] = A[prv]+1;
  else if( L[v] <= A[prv]-1 && A[prv]-1 <= R[v] )
    A[v] = A[prv]-1;
  else
    fl = false;

  for( auto &u : G[v] ) if( !used[u] )
    calc( u, v );

  return;
}

