const int N = 1e5+1;
vector<int> adj[N];
int root = 0;
int closest[N];
int dist[N];
int val[N];
int assval[N];
int many[N];
int minvalue[N];
int maxvalue[N];
int n,k;

void dfs1(int u,int p){
	minvalue[u] = -INF;
	maxvalue[u] = INF;
	if(val[u] != INF){
		many[u]++;
 		minvalue[u] = val[u]-dist[u];
 		maxvalue[u] = val[u]+dist[u];
 	}
	for(int v:adj[u]){
		if(v == p)continue;
		dist[v] = dist[u]+1;
		dfs1(v,u);
		many[u] += many[v];
		minvalue[u] = max(minvalue[u],minvalue[v]);
		maxvalue[u] = min(maxvalue[u],maxvalue[v]);
//		if(dist[closest[v]] < dist[closest[u]])closest[u] = closest[v];
	}
}

void dfs2(int u,int p,int cur){
	assval[u] = cur;
	for(int v:adj[u]){
		if(v == p)continue;
		if(cur-1 >= minvalue[v])dfs2(v,u,cur-1);
		else dfs2(v,u,cur+1);
	}
}

void solve(){
  	cin >> n;
  	RE(i,n-1){
  		int a,b;cin >> a >> b;
  		adj[a].pb(b);
  		adj[b].pb(a);
  	}
  	cin >> k;
  	RE(i,n)val[i] = INF;
  	RE(i,k){
  		int v,p;cin >> v >> p;
  		val[v] = p;
  		root = v;
  	}
  	dist[root] = 1;
  	dist[0] = INF;
  	dfs1(root,root);
  	RE(i,n){
  		minvalue[i] += dist[i];
  		maxvalue[i] -= dist[i];
  		//cout << i << " " << minvalue[i] << " " << maxvalue[i] << endl;
  	}
  	dfs2(root,root,val[root]);
  	RE(i,n){
  		if(val[i] == INF)continue;
  		if(val[i] != assval[i]){
  			cout << "No";
  			return;
  		}
  	}
  	cout << "Yes\n";
  	RE(i,n)cout << assval[i] << endl;
}

