		if (it != pr)
		{
			pii tr2 = dfs(it, v);

			if (tr2.first == -MOD)
			{
				continue;
			}

			if (tr2.first < 0)
			{
				tr2.first += 2;
			}

			if (tr.first == -MOD)
			{
				tr = tr2;
			}
			else
			{
				if (tr.first % 2 != tr2.first % 2)
				{
					unreal = 1;
				}
				else
				{
					pii tr3 = { max(tr.first, tr2.first), min(tr.second, tr2.second) };

					if (tr3.first > tr3.second)
					{
						unreal = 1;
					}

					tr = tr3;
				}
			}
		}
	}

	return{ max(-MOD, tr.first - 1), min(MOD, tr.second + 1) };
}

void buildCentroidDecomposition(int v)
{
	int tn = dfsSz(v, -1);

	int centroid = getCentroid(v, -1, sz[v]);

	if (res[centroid].first == -MOD)
	{
		res[centroid] = dfs(centroid, -1);
		res[centroid].first++;
		res[centroid].second--;
	}

	used[centroid] = 1;
	for (auto it : gr[centroid])
	{
		if (used[it] == 0)
		{
			buildCentroidDecomposition(it);
		}
	}
}


