VV<PLL> cranges;
PLL error = make_pair(INF, -INF);

void merge(PLL &ro, const PLL rm) {
    if(rm == error || ro == error) {
        ro = error;
        return;
    }
    chmax(ro.first, rm.first);
    chmin(ro.second, rm.second);
    if(ro.first >= ro.second) ro = error;
}

PLL dfs(ll now, ll pre, PLL npar) {
    DEBUG(now);
    if(written[now]) npar = make_pair(Pv[now], Pv[now] + 1);
    PLL range = npar;
    npar.first--;
    npar.second++;
    for(ll nxt : edges[now]) {
        if(nxt == pre) {
            cranges[now].push_back(error);
            continue;
        }
        auto cr = dfs(nxt, now, npar);
        cranges[now].push_back(cr);
        merge(range, cr);
    }
    range.first--;
    range.second++;
    return range;
}

bool in_range(const PLL &range, ll v) { return range.first <= v && v < range.second; }

void dfs(ll now, ll pre, ll val, bool &suc) {
    Pv[now] = val;
    for(ll i = 0; i < edges[now].size(); i++) {
        ll nxt = edges[now][i];
        if(nxt == pre) continue;
        PLL range = cranges[now][i];
        if(in_range(range, val + 1)) dfs(nxt, now, val + 1, suc);
        else if(in_range(range, val - 1)) dfs(nxt, now, val - 1, suc);
        else suc = false;
    }
}

bool solve() {
