bool solve(int N, vi& a, vi& b, int K, vi& v, vi& p) {
    priority_queue<ii, vector<ii>, greater<ii>> pq;

    vvi nxt(N);
    rep(i,N-1) {
        nxt[a[i]].pb(b[i]);
        nxt[b[i]].pb(a[i]);
    }
    vi fixed(N, -1);
    rep(i,K){
        fixed[v[i]] = p[i];
        pq.emplace(p[i], v[i]);
    }

    while (!pq.empty()) {
        ii t = pq.top(); pq.pop();
        int value = t.first, u = t.second;
        for (int v: nxt[u]) {
            if (fixed[v] == -1) {
                fixed[v] = value+1;
                pq.emplace(value+1, v);
            } else {
                if (abs(fixed[v] - value) != 1) return false;
            }
        }
    }

    printf("Yes\n");
    rep(i,N){
        printf("%d\n", fixed[i]);
    }
    return true;
}

