    }

    struct State { int vertex, mark; };
    const auto compare = [](const State a, const State b) { return a.mark < b.mark; };
    auto queue = priority_queue<State, vector<State>, decltype(compare)>(compare);

    auto seen = vector<bool>(N);
    auto marks = vector<int>(N);
