    while (!queue.empty())
    {
        const auto s = queue.top(); queue.pop();
        if (!seen[s.vertex])
        {
            seen[s.vertex] = true;
            marks[s.vertex] = s.mark;
            for (const auto w : adjacency_list[s.vertex])
                queue.push({w, s.mark-1});
        }
    }

    auto ok = true;
