int tail[maxn], l[maxn], r[maxn], pa[maxn], val[maxn];
struct edge
{
    int v, next;
}e[maxn << 1];

void ins(int u, int v)
{
    e[++cnt] = (edge){v, tail[u]};
    tail[u] = cnt;
}

void dfs(int u)
{
    if(val[u] != -1)
	l[u] = r[u] = val[u];
    for(int i = tail[u]; i; i = e[i].next)
	if(e[i].v != pa[u])
	{
	    int v = e[i].v, s, t;
	    pa[v] = u;
	    dfs(v);
	    s = l[v] - 1, t = r[v] + 1;
	    if(l[v] == -inf)
		continue;
	    if(l[u] != -inf && (s & 1) != (l[u] & 1))
	    {
		puts("No");
		exit(0);
	    }
	    l[u] = max(l[u], s);
	    r[u] = min(r[u], t);
	    if(l[u] > r[u])
	    {
		puts("No");
		exit(0);
	    }	
	}
}

void solve(int u, int x)
{
    val[u] = x;
    for(int i = tail[u]; i; i = e[i].next)
	if(e[i].v != pa[u])
	{
	    if(x + 1 >= l[e[i].v] && x + 1 <= r[e[i].v])
		solve(e[i].v, x + 1);
	    else
		solve(e[i].v, x - 1);
	}
}

