    makeTree(st,N);
    REP(i,N) edge[i].resize(0);


    //　偶奇のチェック
    REP(i,N) {
        if(num[i]!=INF) {
            if(level[i]%2) {
                if(num[i]%2==num[st]%2) {
                    cout << "No" << endl;
                    return 0;
                }
            }
            else {
                if(num[i]%2!=num[st]%2) {
                    cout << "No" << endl;
                    return 0;
                }
            }
        }
    }

    // 区間を決める
    fill(level,level+N+1,0);
    sec.resize(N);
    REP(i,N) {
        if(num[i]!=INF) sec[i]=p(num[i],num[i]);
