			g.t++;
			if(r.any){
				r.any=false;
				r.s=g.s;
				r.t=g.t;
			}else{
				if((r.s&1)!=(g.s&1))
					return Res{true};
				if((r.t&1)!=(g.t&1))
					return Res{true};
				chmax(r.s,g.s);
				chmin(r.t,g.t);
				if(r.t<r.s)
					return Res{true};
			}
		}
	}
	return z[v]=r;
}

int ans[Nmax];
void dfs1(int v,int p,Res r){
	if(!z[v].any){
		chmax(r.s,z[v].s);
		chmin(r.t,z[v].t);
	}
	ans[v]=r.s;
	r.s--;
	r.t=r.s+2;
	for(auto c:tree[v])if(c!=p)
		dfs1(c,v,r);
}

