const int INF = (1 << 28);
const int MAX_N = 100010;

int lb[MAX_N], ub[MAX_N];
vector<int> graph[MAX_N];

int vid[MAX_N];

int main() {
    int n, k;
    cin >> n;

    for (int i = 0; i < n - 1; i++) {
        int a, b;
        cin >> a >> b;
        a--; b--;
        graph[a].push_back(b);
        graph[b].push_back(a);
    }

    fill(lb, lb + n, -INF);
    fill(ub, ub + n, INF);

    queue<P> que1, que2;
    cin >> k;
    for (int i = 0; i < k; i++) {
        int v, p;
        cin >> v >> p;
        v--;
        lb[v] = p; ub[v] = p;
        que1.push(make_pair(v, p));
        que2.push(make_pair(v, p));
    }

    int start;
    while (!que1.empty()) {
        P elt = que1.front(); que1.pop();
        int v = elt.first,
            p = elt.second;
        if (lb[v] > p) continue;
        for (auto nv : graph[v]) {
            if (lb[nv] < p - 1) {
                lb[nv] = p - 1;
                que1.push(make_pair(nv, p - 1));
            }
        }
        start = v;
    }

    while (!que2.empty()) {
        P elt = que2.front(); que2.pop();
        int v = elt.first,
            p = elt.second;
        if (ub[v] < p) continue;
        for (auto nv : graph[v]) {
            if (ub[nv] > p + 1) {
                ub[nv] = p + 1;
                que1.push(make_pair(nv, p + 1));
            }
        }
    }

    for (int v = 0; v < n; v++) {
        if (lb[v] > ub[v]) {
            cout << "No" << endl;
            return 0;
        }
    }
    fill(vid, vid + n, INF);

    queue<P> que;
    que.push(make_pair(start, lb[start]));
    vid[start] = lb[start];
    while (!que.empty()) {
        P elt = que.front(); que.pop();
        int v = elt.first,
            p = elt.second;
        for (auto nv : graph[v]) {
            for (int diff = -1; diff <= 1; diff += 2) {
                if (vid[nv] != INF) continue;
                int np = p + diff;
                if (np < lb[nv] || np > ub[nv]) continue;
                que.push(make_pair(nv, np));
                vid[nv] = np;
            }
        }
    }
    for (int i = 0; i < n; i++) {
        if (vid[i] == INF) {
            cout << "No" << endl;
            return 0;
        }
    }
    cout << "Yes" << endl;
    for (int i = 0; i < n; i++) {
        cout << vid[i] << endl;
    }

    return 0;
}

