const int inf = 1000000000;
struct Solver{
    int Min, Max;
    Solver(int mi = -inf, int ma = inf) : Min(mi), Max(ma) {}
    bool unchanged(){ return Min <= -inf && Max >= inf; }
    bool change(Solver sol){
        if(!unchanged() && !sol.unchanged()){
            if((Min - sol.Min) & 1)return false;
            if(max(Min, sol.Min) > min(Max, sol.Max))return false;
        }
        chmax(Min, sol.Min);
        chmin(Max, sol.Max);
        return true;
    }
    Solver plus(){
        if(unchanged())return *this;
        else return Solver(Min - 1, Max + 1);
    }
};

