		G[B[i]].push_back(A[i]);
		cap[i]=p(-INF,INF);
		odd[i]=-1;
	}
	odd[N-1]=-1;
	cap[N-1]=p(-INF,INF);
	cin>>K;
	for(ll i=0;i<K;i++){
		cin>>V[i]>>P[i];
		V[i]--;
		cap[V[i]]=p(P[i],P[i]);
		odd[V[i]]=P[i]%2;
	}
	if(dfs(V[0],p(-INF,INF),-1).second!=-INF){
