using namespace std;

using Weight = long long;
class Edge{
public:
	int src,dest;
	Edge(int src, int dest): src(src),dest(dest){};
	virtual Weight get_weight()const {return 1;};
	virtual bool operator<(const Edge& other) const {
		return get_weight() < other.get_weight();
	}
};

class WeightedEdge : public Edge{
public:
	Weight weight;
	WeightedEdge(size_t src, size_t dest,Weight weight): Edge(src,dest),weight(weight){};
	virtual Weight get_weight()const {return weight;};
};

class Graph{
private:
	size_t n;
public:
	Graph(size_t n):n(n),adj_lst(n),rev_adj_lst(n){};
	vector<std::unique_ptr<Edge>> edges;
	vector<vector<Edge*>> adj_lst;
	vector<vector<Edge*>> rev_adj_lst;
	vector<Edge*>& get_outgoing(int index);
	vector<Edge*>& get_incoming(int index);

	virtual void add_edge(unique_ptr<Edge>&& e);
	size_t size()const {return n;};

};

void Graph::add_edge(std::unique_ptr<Edge>&& e){
	adj_lst[e->src].push_back(e.get());
	rev_adj_lst[e->dest].push_back(e.get());
	edges.push_back(move(e));
}

vector<Edge*>& Graph::get_outgoing(int index){
	return adj_lst[index];
}
vector<Edge*>& Graph::get_incoming(int index){
	return rev_adj_lst[index];
}

using namespace std;
using P = pair<int,int>;
const int N = 1e+5+7;
const int INF = 1e+7;
int V[N] = {-1};

P dfs(int r,Graph& g) {
	int myminmax = -INF;
	int mymaxmin = INF;
	for(auto e: g.get_outgoing(r)) {
		P child = dfs(e->dest,g);
		if(child.first == INF && child.second == -INF)
			return P(INF,-INF);

		myminmax = max(myminmax,child.first);
		mymaxmin = min(mymaxmin,child.second);
	}

// 	cout << r << endl;
// 	cout << myminmax << ":" << mymaxmin << endl;

	if(myminmax > -INF && mymaxmin < INF && abs(mymaxmin - myminmax) > 2)
		return P(INF,-INF);

	if(V[r] >= 0)
		return P(V[r],V[r]);

	if(myminmax == -INF && mymaxmin == INF)
		return P(-INF,INF);

	return P(min(myminmax,mymaxmin)-1,max(myminmax,mymaxmin)+1);
}

void retraversal(int r,Graph& g, int num) {
	if(V[r] < 0)
		V[r] = num;

	for(auto e: g.get_outgoing(r)) {
		P child = dfs(e->dest,g);
		if(abs(num+1 - child.first) <= 1 || abs(num+1 - child.second) <=1)
			retraversal(e->dest,g,num+1);
		else
			retraversal(e->dest,g,num-1);
	}
}

int main() {
	int n;
	cin >> n;
	Graph g(n);
	for(int i = 0; i < n-1; i++) {
		int a,b;
		cin >> a >> b;
		g.add_edge(unique_ptr<Edge>(new Edge(min(a-1,b-1),max(a-1,b-1))));
	}

	for(int i = 0; i < n; i++) {
		V[i] = -1;
	}

	int k;
	cin >> k;
	for(int i = 0; i < k; i++) {
		int v,p;
		cin >> v >> p;
		V[v-1] = p;
	}

	P res = dfs(0,g);
// 	cout << res.first << ":" << res.second << endl;
	if(res.first > res.second) {
		cout << "NO" << endl;
	}else {
		cout << "YES" << endl;
		retraversal(0,g,res.second);
		for(int i = 0; i < n;i++)
			cout << V[i] << endl;
	}
}

