const int MAX_N = 100005;
const int MAX_P = 1000005;
int n, k;
struct Node {
	vector<int> adjIs;
	int parent = -1;
	int value = 2 * MAX_P;
	int low = 2 * MAX_P;
	int high = -MAX_P;
};
Node vs[MAX_N];

#include <queue>

int main() {
	cin >> n;
	REPCLS(i, n - 1) {
		int a, b;
		cin >> a >> b;
		vs[a].adjIs.push_back(b);
		vs[b].adjIs.push_back(a);
	}
	cin >> k;
	vector<int> valueNodes;
	REP(i, k) {
		int v, p;
		cin >> v >> p;
		vs[v].value = vs[v].low = vs[v].high = p;
		valueNodes.push_back(v);
	}

	queue<int> q;
	q.push(1);

	while (!q.empty()) {
		int v = q.front(); q.pop();
		for (auto node : vs[v].adjIs) {
			if (node == vs[v].parent) continue;
			vs[node].parent = v;
			q.push(node);
		}
	}
	bool isYes = true;
	for (auto node : valueNodes) {
		auto& leaf = vs[node];
		int curNode = vs[node].parent;
		int d = 1;
		while (curNode != -1) {
			auto& v = vs[curNode];
			int low = leaf.value - d;
			int high = leaf.value + d;
			if (v.value == 2 * MAX_P) { // non value node
				if (v.low == 2 * MAX_P || v.high == -MAX_P) { // not defined range
					v.low = low;
					v.high = high;
				}
				else {
					if (((low - v.low) % 2) != 0 || ((high - v.high) % 2) != 0) {
						isYes = false;
						goto endLabel;
					}
					v.low = max(v.low, low);
					v.high = min(v.high, high);
					if (v.high < v.low) {
						isYes = false;
						goto endLabel;
					}
				}
			}
			else { // value node
				if ((v.value - low) % 2 != 0) {
					isYes = false;
					goto endLabel;
				}
				else {
					break;
				}
			}
			curNode = v.parent;
			d++;
		}
	}
endLabel:

	if (isYes) {
		queue<int> p;
		p.push(1);
		while (!p.empty()) {
			int curNode = p.front(); p.pop();
			auto& v = vs[curNode];
			if (v.value == 2 * MAX_P) v.value = v.low;
			for (auto i : v.adjIs) {
				if (v.parent == i) continue;
				int l = v.value - 1;
				int r = v.value + 1;
				auto& w = vs[i];

				if ((w.low <= l && l <= w.high) || w.low == 2 * MAX_P) {
					w.value = l;
				}
				else {
					w.value = r;
				}
				p.push(i);
			}
		}
		cout << "Yes" << endl;
		REPCLS(i, n) {
			cout << vs[i].value << endl;
		}
	}
	else {
		cout << "No" << endl;
	}
	return 0;
}

