void No() {cout << "No"; exit(0);}

void Check(int u, int par, int d) {
    if(val[u] != (ll)1e18 && (d & 1) != (abs(val[root] - val[u]) & 1)) No();
    for(int v: a[u]) if(v != par) Check(v, u, d + 1);
}

void DFS(int u, int par) {
    for(int v: a[u]) {
       if(v == par) continue;
       DFS(v, u);
       l[u] = max(l[v] - 1, l[u]);
       r[u] = min(r[v] + 1, r[u]);
    }
    if(l[u] > r[u]) No();
}

void GetAns(int u, int par) {
    if(val[u] != (ll)1e18) {
        if(val[u] < l[u] || val[u] > r[u]) No();
    } else {
        if(u == par) val[u] = l[u];
        else {
            if(val[par] + 1 >= l[u] && val[par] + 1 <= r[u]) val[u] = val[par] + 1;
            else if(val[par] - 1 >= l[u] && val[par] - 1 <= r[u]) val[u] = val[par] - 1;
            else No();
        }
    }
    for(int v: a[u]) if(v != par) GetAns(v, u);
}

