using namespace std;
const int MAXN = 100000;
struct edge{
	int to;
	edge *nxt;
}edges[2*MAXN + 5], *adj[MAXN + 5];
edge *ecnt = &edges[0];
void addedge(int u, int v) {
	edge *p = (++ecnt);
	p->to = v, p->nxt = adj[u], adj[u] = p;
	p = (++ecnt);
	p->to = u, p->nxt = adj[v], adj[v] = p;
}
struct node{
	int lb, ub;
	bool flag;
	int key;
}a[MAXN + 5];
bool flag = true;
void dfs(int rt, int pre) {
	for(edge *p=adj[rt];p!=NULL;p=p->nxt) {
		if( p->to == pre ) continue;
		dfs(p->to, rt);
		if( a[p->to].flag ) {
			if( !a[rt].flag ) {
				a[rt].lb = a[p->to].lb;
				a[rt].ub = a[p->to].ub;
			}
			else {
				if( (a[rt].lb & 1) == (a[p->to].lb & 1) ) {
					flag = false;
					break;
				}
				else {
					int lb = a[p->to].lb - 1;
					int ub = a[p->to].ub + 1;
					if( lb > a[rt].ub ) {
						flag = false;
						break;
					}
					else if( a[rt].lb > ub ) {
						flag = false;
						break;
					}
					else {
						a[rt].lb = max(a[rt].lb, lb);
						a[rt].ub = min(a[rt].ub, ub);
					}
				}
			}
			a[rt].flag = true;
		}
		if( !flag ) break;
	}
}
void dfs2(int rt, int pre) {
	if( pre != -1 ) {
		if( a[rt].lb <= a[pre].key + 1 && a[pre].key + 1 <= a[rt].ub )
			a[rt].key = a[pre].key + 1;
		else a[rt].key = a[pre].key - 1;
	}
	else {
		if( !a[rt].flag ) a[rt].key = 0;
		else a[rt].key = a[rt].lb;
	}
	for(edge *p=adj[rt];p!=NULL;p=p->nxt)
		if( p->to != pre ) 
			dfs2(p->to, rt);
}
int main() {
	int N, K;
	scanf("%d", &N);
	for(int i=1;i<N;i++) {
		int A, B;
		scanf("%d%d", &A, &B);
		addedge(A, B);
	}
	scanf("%d", &K);
	for(int i=1;i<=K;i++) {
		int V, P;
		scanf("%d%d", &V, &P);
		a[V].flag = true;
		a[V].lb = a[V].ub = a[V].key = P;
	}
	dfs(1, -1);
	if( !flag ) {
		puts("No");
		return 0;
	}
	else puts("Yes");
	dfs2(1, -1);
	for(int i=1;i<=N;i++)
		printf("%d\n", a[i].key);
}

