	function<void(int, int)> dfs = [&](int c, int p) {
		par[c] = p;
		depth[c] = p == -1 ? 0 : depth[p] + 1;
		for (auto itr : g.g[c])
			if (itr.first != p)
				dfs(itr.first, c);
	};
	dfs(0, -1);

