using ll = long long;

const ll INF = static_cast<ll>(1e9) + 7ll;
const ll LINF = INF * INF;
const int MAXN = static_cast<int>(1e6) + 17;

int n, m;
bool ok = true;
vector<int> g[MAXN];
ll col[MAXN], L[MAXN], R[MAXN];
ll kek[2];

bool read() {
    if (!(cin >> n))
        return false;

    forn (i, n - 1) {
        int u, v;
        cin >> u >> v;
        g[u - 1].pb(v - 1);
        g[v - 1].pb(u - 1);
    }

    cin >> m;
    fill(col, col + n, -1);

    forn (i, m) {
        int v, x;
        cin >> v >> x;
        col[v - 1] = x;
    }

    return true;
}

void dfs1(int v, int pr, int h) {
    if (col[v] != -1) {
        if (kek[h] == -1)
            kek[h] = col[v];

        if (1 & (col[v] ^ kek[h]))
            ok = false;

        L[v] = R[v] = col[v];
    }

    for (auto to : g[v])
        if (to != pr) {
            dfs1(to, v, (h ^ 1));
            L[v] = max(L[v], L[to] - 1);
            R[v] = min(R[v], R[to] + 1);
        }
}

void dfs2(int v, int pr, pair<ll, ll> up) {
    multiset<ll> Ls, Rs;
    Ls.insert(-INF * INF);
    Rs.insert(INF * INF);

    for (auto to : g[v])
        if (to != pr) {
            Ls.insert(L[to]);
            Rs.insert(R[to]);
        }

    if (pr != -1) {
        L[v] = max(L[v], up.f - 1);
        R[v] = min(R[v], up.s + 1);
        Ls.insert(up.f);
        Rs.insert(up.s);
    }

    for (auto to : g[v])
        if (to != pr) {
            auto curL = L[to];
            auto curR = R[to];
            Ls.erase(Ls.find(curL));
            Rs.erase(Rs.find(curR));
            dfs2(to, v, mp(*Ls.rbegin() - 1, *Rs.begin() + 1));
            Ls.insert(curL);
            Rs.insert(curR);
        }
}

void dfs(int v, int pr) {
    for (auto to : g[v])
        if (to != pr) {
            if (col[to] == -1) {
                if (L[to] <= col[v] - 1 && col[v] - 1 <= R[to])
                    col[to] = col[v] - 1;
                else
                    col[to] = col[v] + 1;
            }

            dfs(to, v);
        }
}

void solve() {
    kek[0] = kek[1] = -1;
    fill(L, L + n, -INF * INF);
    fill(R, R + n, INF * INF);
    dfs1(0, -1, 0);
    dfs2(0, -1, mp(-INF * INF, INF * INF));

    forn (v, n)
        if (L[v] > R[v])
            ok = false;

    if (!ok || (kek[0] != -1 && kek[1] != -1 && (kek[0] ^ kek[1]) % 2 == 0)) {
        cout << "No\n";
        return ;
    }

    forn (i, n)
        if (col[i] != -1) {
            dfs(i, -1);
            break;
        }

    cout << "Yes\n";

    forn (i, n)
        cout << col[i] << endl;
}

int main() {
    cin.tie(nullptr);
    std::ios_base::sync_with_stdio(false);

    while (read())
        solve();

    return 0;
}

#include<bits/stdc++.h>

using namespace std;

const int INF = 1 << 30;

struct Data
{
  int small, big;
};

int N, K;
int value[100000];
vector< int > tree[100000];
int sz[100000];
int cost[100000];

bool c[100000];

void color(int idx, bool now, int par = -1)
{
  if(~value[idx] && value[idx] % 2 != now) {
    puts("No");
    exit(0);
  }
  c[idx] = now;
  for(int to : tree[idx]) {
    if(to == par) continue;
    color(to, now ^ 1, idx);
  }
}

Data dfs(int idx, Data order, int par = -1)
{
  if(~value[idx]) {
    if(order.big == INF) {
      order.small = order.big = value[idx];
    } else {
      if(order.small <= value[idx] && value[idx] <= order.big) {
        order.small = order.big = value[idx];
      } else {
        puts("No");
        exit(0);
      }
    }
  }

  int top = -1;
  for(int i = 0; i < tree[idx].size(); i++) {
    if(tree[idx][i] == par) continue;
    if(top == -1 || sz[tree[idx][top]] < sz[tree[idx][i]]) top = i;
  }
  if(~top) swap(tree[idx][0], tree[idx][top]);

  for(int to : tree[idx]) {
    if(to == par) continue;
    Data ord = dfs(to, {max(order.small - 1, -1), min(INF, order.big + 1)}, idx);
    order.small = max(order.small, ord.small);
    order.big = min(order.big, ord.big);
  }
  while(order.small < 0) ++order.small;
  while(order.small % 2 != c[idx]) ++order.small;
  if(order.small > order.big) {
    puts("No");
    exit(0);
  }
  if(~value[idx] && order.small != 0) {
    puts("No");
    exit(0);
  }
  value[idx] = order.small;
  order.small = max(value[idx] - 1, -1);
  order.big = min(value[idx] + 1, INF);
  return (order);
}

int calc(int idx, int par)
{
  for(int to : tree[idx]) {
    if(to == par) continue;
    sz[idx] += calc(to, idx);
  }
  if(~value[idx]) ++sz[idx];
  return (sz[idx]);
}

int main()
{
  cin >> N;
  for(int i = 0; i < N - 1; i++) {
    int A, B;
    cin >> A >> B;
    tree[--A].push_back(--B);
    tree[B].push_back(A);
  }
  cin >> K;
  memset(value, -1, sizeof(value));
  for(int i = 0; i < K; i++) {
    int V, P;
    cin >> V >> P;
    value[--V] = P;
  }
  for(int i = 0; i < K; i++) {
    if(~value[i]) {
      color(i, value[i] & 1);
      break;
    }
  }
  calc(0, -1);
  dfs(0, (Data) {-1, INF});
  puts("Yes");
  for(int i = 0; i < N; i++) {
    cout << value[i] << endl;
  }
}

