int dfs(ll coming,ll start,ll value,vector<vector<ll>>A,vector<ll>&V,vector<int> Y){

	cout << coming <<" "<< start << " "<< value << endl;
	if (Y[start] == 1){
		if (V[start] != value){
			return 0;
		}
	}
	V[start] = value;
	for (int i = 0; i < A.size(); i++){
		if (A[start][i] == 1){
			if (i == coming){
				continue;
			}
			int success; 
			success=dfs(start,i, V[start]+1,A, V, Y);
			if (success != 1){
				success=dfs(start,i, V[start] - 1, A, V, Y);
			}
			if (success != 1){
				cout << "not success" << endl;
				return 0;
			}
		}
	}
	return 1;
}

int main(){
	ll N;
	cin >> N;
	vector<vector<ll>> A(N,vector<ll>(N));
	for (int i = 0; i < N - 1; i++){
		ll j, k;
		cin >> j >> k;
		j--;
		k--;
		A[j][k] = 1;
		A[k][j] = 1;
	}
	ll K;
	cin >> K;
	vector<ll> V(N);
	vector<int> Y(N);
	for (int i = 0; i < K; i++){
		ll j, k;
		cin >> j >> k;
		j--;
		V[j] = k;
		Y[j] = 1;
	}
	ll start;
	for (int i = 0; i < N; i++){
		if (Y[i] == 1){
			start = i;
			break;
		}
	}
	int success = dfs(start, start, V[start], A, V, Y);
	cout << success << endl;
