VVI adj;

void combine(int u, int v) {
    if (lb[v] == -INF) {  // child not initialized
        return;
    }
    else if (lb[v] == INF) {
        lb[u] = INF;
    }
    else if (lb[u] == -INF) {  // self not initialized
        lb[u] = lb[v] - 1;
        ub[u] = ub[v] + 1;
    }
    else if (lb[u] == INF || (abs(lb[u] - lb[v]) % 2 != 1)) {  // not valid
        lb[u] = INF;
    }
    else if (lb[v] - 1 > ub[u] || ub[v] + 1 < lb[u]) {  // no overlap
        lb[u] = INF;
    }
    else {
        lb[u] = max(lb[u], lb[v] - 1);
        ub[u] = min(ub[u], ub[v] + 1);
    }
}

void dfs(int u) {
    visited[u] = 1; lb[u] = -INF; ub[u] = INF;

    for (auto& v : adj[u]) {
        if (!visited[v]) {
            dfs(v);
            combine(u, v);
        }
    }

    if (given[u] >= 0) { 
        if (lb[u] == -INF || (given[u] >= lb[u] && given[u] <= ub[u] && (given[u] - lb[u]) % 2 == 0)) {
            lb[u] = ub[u] = given[u];
        }
        else {
            lb[u] = INF;
        }
    }

//    DEBUG(u);
//    DEBUG(lb[u]);
//    DEBUG(ub[u]);
}

void dfs2(int u, int p) {
    visited[u] = 1;

    if (u == 1) {
        res[1] = (lb[1] == -INF) ? 0 : lb[1];
    }
    else if (res[p] - 1 >= lb[u] && res[p] - 1 <= ub[u]) {
        res[u] = res[p] - 1;
    }
    else {
        res[u] = res[p] + 1;
    }

    for (auto& v : adj[u]) {
        if (!visited[v]) {
            dfs2(v, u);
        }
    }
}

int main() {
    GI(n); adj.resize(n+1);

    FORN(i, n-1) {
        GI(a); GI(b);
        adj[a].PB(b);
        adj[b].PB(a);
    }

    GI(k); memset(given, -1, sizeof given);

    FORN(i, k) {
        int v; int p; GI(v); GI(p);
        given[v] = p;
    }

    memset(visited, 0, sizeof visited);
    dfs(1);

    if (lb[1] == INF) {
        printf("No\n");
        return 0;
    }

    memset(visited, 0, sizeof visited);
    dfs2(1, 1);

    printf("Yes\n");
    FOR1(i, n) printf("%d\n", res[i]);

    return 0;
}

