int n;
struct edge{int to,Next;}ed[N<<1];
int edcnt,head[N];
void addedge(int u,int v){ed[++edcnt]=(edge){v,head[u]};head[u]=edcnt;}
int le[N],ri[N];
void dfslr(int u,int Fa)
{
	for(int i=head[u];i;i=ed[i].Next)
	if(ed[i].to!=Fa)
	{
		int v=ed[i].to;
		le[v]=max(le[v],le[u]-1);
		ri[v]=min(ri[v],ri[u]+1);
		dfslr(v,u);
	}
	if(Fa)
	{
		le[Fa]=max(le[Fa],le[u]-1);
		ri[Fa]=min(ri[Fa],ri[u]+1);
	}
}
int ans[N];bool used[N*3];
bool dfsans(int u,int Fa)
{
	for(int i=head[u];i;i=ed[i].Next)
	if(ed[i].to!=Fa&&le[ed[i].to]==ri[ed[i].to]) used[le[ed[i].to]+n]=true;
	int l=le[u];
	while(l<=ri[u]&&used[l+n]) l++;
	if(l>ri[u]) return false;
	ans[u]=l;
	for(int i=head[u];i;i=ed[i].Next)
	if(ed[i].to!=Fa&&le[ed[i].to]==ri[ed[i].to]) used[le[ed[i].to]+n]=false;
	for(int i=head[u];i;i=ed[i].Next)
	if(ed[i].to!=Fa)
	{
		int v=ed[i].to;
		le[v]=max(le[v],ans[u]-1);
		ri[v]=min(ri[v],ans[u]+1);
		if(!dfsans(v,u)) return false;
	}
	return true;
}
