	for(int i=1;i<n;i++)
	{
		int u,v;scanf("%d%d",&u,&v);
		addedge(u,v);addedge(v,u);
	}
	for(int i=1;i<=n;i++)
	{
		le[i]=-n;
		ri[i]=n*2;
	}
	int K;scanf("%d",&K);
	for(int i=1;i<=K;i++)
	{
		int Id,Val;scanf("%d%d",&Id,&Val);
		le[Id]=ri[Id]=Val;
	}
	dfslr(1,0);dfslr(1,0);
	bool flag=true;
	for(int i=1;i<=n;i++)
	if(le[i]>ri[i])
	{
		flag=false;
		break;
	}
	if(flag) flag=dfsans(1,0);
