#include <bits/stdc++.h>

using namespace std;

#define next NEXT

const int N = 100010;
const int M = 2 * N;
const int INF = 1e9;

int e[M], next[M];
int last[N], c[N], dep[N], f[N], g[N], v[N];
int n, k, total;
int invalid;

void Add(int x, int y) {
	e[++total] = y;
	next[total] = last[x];
	last[x] = total;
}

void DFS(int x, int p) {
	dep[x] = dep[p] + 1;
	for (int i = last[x]; i; i = next[i]) {
		if (e[i] == p) continue;
		DFS(e[i], x);
	}
}

void DP(int x, int p) {
	f[x] = -INF;
	g[x] = INF;
	for (int i = last[x]; i; i = next[i]) {
		if (e[i] == p) continue;
		DP(e[i], x);
		f[x] = max(f[x], f[e[i]] - 1);
		g[x] = min(g[x], g[e[i]] + 1);
	}
	if (v[x]) {
		if (c[x] < f[x] || c[x] > g[x]) {
			invalid = 1;
		}
		f[x] = g[x] = c[x];
	}
	if (f[x] > g[x]) invalid = 1;
}

void REDFS(int x, int p) {
	if (!v[x]) {
		if (!p) c[x] = f[x];
		if (p) {
			if (c[p] + 1 >= f[x] && c[p] + 1 <= g[x]) {
				c[x] = c[p] + 1;
			}
			if (c[p] - 1 >= f[x] && c[p] - 1 <= g[x]) {
				c[x] = c[p] - 1;
			}
		}
	}
	for (int i = last[x]; i; i = next[i]) {
		if (e[i] == p) continue;
		REDFS(e[i], x);
	}
}

int main() {
	scanf("%d", &n);
	for (int i = 1; i < n; i++) {
		int x, y;
		scanf("%d %d", &x, &y);
		Add(x, y);
		Add(y, x);
	}
	DFS(1, 0);
	int ans = -1;
	scanf("%d", &k);
	for (int i = 0; i < k; i++) {
		int x, y;
		scanf("%d %d", &x, &y);
		c[x] = y;
		v[x] = 1;
		if (ans == -1) {
			ans = (y & 1) ^ (dep[x] & 1);
		} else if (ans != ((y & 1) ^ (dep[x] & 1))) {
			printf("No\n");
			return 0;
		}
	}
	invalid = 0;
	DP(1, 0);
	if (invalid) {
		printf("No\n");
		return 0;
	}
	printf("Yes\n");
	REDFS(1, 0);
	for (int i = 1; i <= n; i++) {
		printf("%d\n", c[i]);
	}
	return 0;
}

