		if(a[now][i] == par) continue;
		solve(a[now][i], now);
		if(l[a[now][i]] < -INF/2) continue;
		if(l[now] < -INF/2){
			l[now] = l[a[now][i]] - 1;
			r[now] = r[a[now][i]] + 1;
		} else {
			l[now] = max(l[now], l[a[now][i]] - 1);
			r[now] = min(r[now], r[a[now][i]] + 1);
			if(abs(l[now]) % 2 == abs(l[a[now][i]]) % 2) res = false;
		}
	}
	if(l[now] > r[now]) res = false;
}

void make(int now, int par){
	rep(i, a[now].size()){
		if(a[now][i] == par || tag[a[now][i]] != -INF) continue;
		if(tag[now] - 1 <= r[a[now][i]] && tag[now] - 1 >= l[a[now][i]]) tag[a[now][i]] = tag[now] - 1;
		else tag[a[now][i]] = tag[now] + 1;
		make(a[now][i], now);
	}
	return ;
}

