void dfs (int cur, int par, int depth, int t) {
  if (hi[cur] != INF) {
    if (((val[cur] % 2) ^ (depth % 2)) != t) {
      cout << "No\n";
      exit(0);
    }
  }
  for (int child : g[cur]) if (child != par) dfs (child, cur, depth + 1, t);
}
void dfs2 (int cur, int par) {
  for (int child : g[cur]) if (child != par) {
    lo[child] = max(lo[child], lo[cur] - 1);
    hi[child] = min(hi[child], hi[cur] + 1);
    dfs2 (child, cur);
  }
}
void dfs3 (int cur, int par) {
  for (int child : g[cur]) if (child != par) {
    lo[cur] = max(lo[cur], lo[child] - 1);
    hi[cur] = min(hi[cur], hi[child] + 1);
    dfs3 (child, cur);
  }
}
