using namespace std;

struct range {
    int type, left, right;

    range() {}
    range(int _type, int _left, int _right): type(_type), left(_left), right(_right) {}
};

range intersec(range x, range y) {
    if (x.type == 0 || y.type == 0) {
        return range(0, -1, -1);
    }
    if (x.type == 2) {
        return y;
    }
    if (y.type == 2) {
        return x;
    }
    if (x.left % 2 != y.left % 2) {
        return range(0, -1, -1);
    }
    range res(1, max(x.left, y.left), min(x.right, y.right));

    if (res.left > res.right) {
        return range(0, -1, -1);
    }
    return res;
}

void dfs(int u, int p, vector <vector <int> > &G, vector <int> &A, vector <range> &res) {
    res[u] = A[u] == -1 ? range(2, -1, -1) : range(1, A[u], A[u]);

    for (int to: G[u]) {
        if (to != p) {
            dfs(to, u, G, A, res);

            range now = res[to];

            if (now.type == 1) {
                now.left--;
                now.right++;
            }
            res[u] = intersec(res[u], now);
        }
    }
}

void dfs2(int u, int p, int num, vector <vector <int> > &G, vector <int> &A, vector <range> &res) {
    if (A[u] == -1) {
        A[u] = intersec(p == -1 ? range(2, -1, -1) : range(1, num - 1, num + 1), res[u]).left;
    }

    for (int to: G[u]) {
        if (to != p) {
            dfs2(to, u, A[u], G, A, res);
        }
    }
}

