class Node {
public:
    Node() {
        l = -INF, r = -INF, p = -INF, m = 0;
    }
    vector<int> next;
    int l, r, p, m;
}nodeList[MAX_N];

using II = pair<int, int>;

bool dfs(int pos, int L, int R, int M, int pre = -1) 
{
    cerr << pos << " " << M << " " << L << " " << R << endl;
    II ret; ret.first = L; ret.second = R;

    int nextM = (M+1)%2;
    int m = (1 << M);
    Node& node = nodeList[pos];

    if(node.p != -INF) {
        m &= (1 << node.m);
        if(m == 0) {
            return false;
        }
        ret.first = node.p; ret.second = node.p;
    }

    // cerr << pos << " " << m << endl;

    int tmpM = m;

    for(int next : node.next) {
        if(next == pre) {
            continue;
        }
        if(!dfs(next, L-1, R+1, nextM, pos)){
            return false;
        }
        const Node& nextNode = nodeList[next];
        int mm = nextNode.m;
        if(mm == 1) {
            mm = 2;
        } else {
            mm = 1;
        }
        tmpM &= mm;
        ret.first = max(ret.first, nextNode.l-1);
        ret.second = min(ret.second, nextNode.r+1);
    }

    cerr << "ret: " << pos << " " << tmpM << " " << ret.first << " " << ret.second << endl;

    if(tmpM == 0 || ret.second - ret.first < 0) {
        return false;
    }

    node.l = ret.first;
    node.r = ret.second;
    node.m = m;

    return true;
}

void reg(int pos, int kp, int pre = -1) {
    Node& node = nodeList[pos];

    if(node.l <= kp+1 && kp+1 <= node.r && node.m == (1 << ((kp+1)%2))) {
        node.p = kp+1;
    } else {
        node.p = kp-1;
    }

    for(int next : node.next) {
        if(next == pre) {
            continue;
        }
        reg(next, node.p, pos);
    }

}

signed main()
{
    cin >> N;
    for(int i = 0; i < N-1; i++) {
        int a, b; cin >> a >> b; a--; b--;
        nodeList[a].next.push_back(b);
        nodeList[b].next.push_back(a);
    }
    cin >> K;
    int v, p;
    for(int i = 0; i < K; i++) {
        cin >> v >> p; v--; p += 1000000;
        nodeList[v].p = p;
        nodeList[v].m = p%2;
    }

    if(!dfs(v, p, p, p%2)) {
        cout << "No" << endl;
        return 0;
    } else {
        for(int nextNode : nodeList[v].next) {
            reg(nextNode, nodeList[v].p, v);
        }
    }

    cout << "Yes" << endl;
    for(int i = 0; i < N; i++) {
        cout << nodeList[i].p - 1000000 << endl;
    }

    return 0;
}

