bool dfs2(int x,int fa){
	if(a[x]) low[x]=a[x],up[x]=a[x];
	else low[x]=-inf,up[x]=inf;
	for(int i=h[x];i;i=mp[i].next){
		int y=mp[i].to;if(y==fa) continue;
		if(!dfs2(y,x)) return false;
		low[x]=max(low[x],low[y]-1);
		up[x]=min(up[x],up[y]+1);
