void dfs_check(int start, int stt, int flo, int p)
{
	col[start] = stt;
	fl[start] = flo;
	for (int i = 0; i < (int)AdjList[start].size(); i++)
	{
		int u = AdjList[start][i];
		if (u != p)
		{
			dfs_check(u, 1-stt, flo+1, start);
		}
	}
}

void dfs(int start, int p)
{
	parent[start] = p;
	for (int i = 0; i < (int)AdjList[start].size(); i++)
	{
		int u = AdjList[start][i];
		if (u != p)
		{
			dfs(u, start);
		}
	}
}

void dfs_ans(int start, int p)
{
	if (bo)	return;
	for (int i = 0; i < (int)AdjList[start].size(); i++)
	{
		int u = AdjList[start][i];

		if (u != p)
		{
			ans[u] = ans[start] + 1;
			if (ans[u] > r[u])	ans[u] = ans[start] - 2;
			if (ans[u] < l[u])
			{
				bo = true;
			}
			dfs_ans(u, start);
		}
	}
}

