const int N=100005;
const int inf=1000000000;

int n,val[N],l[N],r[N],dep[N],last[N],cnt;
bool vis[N],flag;
struct edge{int to,next;}e[N*2];

int read()
{
	int x=0,f=1;char ch=getchar();
	while (ch<'0'||ch>'9'){if(ch=='-')f=-1;ch=getchar();}
	while (ch>='0'&&ch<='9'){x=x*10+ch-'0';ch=getchar();}
	return x*f;
}

void addedge(int u,int v)
{
	e[++cnt].to=v;e[cnt].next=last[u];last[u]=cnt;
	e[++cnt].to=u;e[cnt].next=last[v];last[v]=cnt;
}

void dfs(int x,int fa)
{
	dep[x]=dep[fa]+1;
	for (int i=last[x];i;i=e[i].next)
		if (e[i].to!=fa) dfs(e[i].to,x);
}

void dp(int x,int fa)
{
	if (vis[x]) l[x]=r[x]=val[x];
	else l[x]=-inf,r[x]=inf;
	for (int i=last[x];i;i=e[i].next)
	{
		if (e[i].to==fa) continue;
		dp(e[i].to,x);
		l[x]=max(l[x],l[e[i].to]-1);
		r[x]=min(r[x],r[e[i].to]+1);
	}
	if (l[x]>r[x]) flag=1;
}

void pri(int x,int fa)
{
	if (!vis[x])
	{
		if (val[fa]+1>=l[x]&&val[fa]+1<=r[x]) val[x]=val[fa]+1;
		else val[x]=val[fa]-1;
	}
	for (int i=last[x];i;i=e[i].next)
		if (e[i].to!=fa) pri(e[i].to,x);
}

int main()
{
	n=read();
	for (int i=1;i<n;i++)
	{
		int x=read(),y=read();
		addedge(x,y);
	}
	dfs(1,0);
	int m=read(),tag;
	for (int i=1;i<=m;i++)
	{
		int x=read(),y=read();
		vis[x]=1;val[x]=y;
		if (i==1) tag=(y&1)^(dep[x]&1);
		else if ((y&1)^(dep[x]&1)) {puts("No");return 0;}
	}
	dp(1,0);
	if (flag) {puts("No");return 0;}
	if (!vis[1]) vis[1]=1,val[1]=l[1];
	pri(1,0);
	puts("Yes");
	for (int i=1;i<=n;i++) printf("%d\n",val[i]);
	return 0;
}

