int main(int argc, char **argv) {
	cin >> N;
	REP(i, N - 1) {
		cin >> es[i].a >> es[i].b;
		--es[i].a;
		--es[i].b;
		es2[es[i].a].push_back(es[i].b);
		es2[es[i].b].push_back(es[i].a);
	}
