	queue<int> q;
	q.push(V[0]);
	while (!q.empty()) {
		int a = q.front(); q.pop();
		int pha = h[a], pla = l[a];
		REP(i, es2[a].size()) {
			int b = es2[a][i];
			int phb = h[b], plb = l[b];
			if (h[b] != -1) {
				if (h[a] % 2 == h[b] % 2) {
					res = false;
					break;
				}
				l[b] = max(l[a] - 1, l[b]);
				h[b] = min(h[a] + 1, h[b]);
				l[a] = max(l[b] - 1, l[a]);
				h[a] = min(h[b] + 1, h[a]);
				if (l[a] > h[a] || l[b] > h[b]) {
					res = false;
					break;
				}
			}
			else {
				l[b] = l[a] - 1;
				h[b] = h[a] + 1;
