pair<int, int> dfs(int v, int p) {
    pair<int, int> res = {l[v], r[v]}, tmp;
    for (int u : g[v]) {
        if (u == p) continue;
        if (l[u] == 1e7) {
            l[u] = l[v] - 1;
            r[u] = r[v] + 1;
        } else {
            if (l[u] % 2 == l[v] % 2) {
                l[u] = 3e7;
            }
        }
        tmp = dfs(u, v);
        res.first = max(res.first, tmp.first - 1);
        res.second = min(res.second, tmp.second + 1);
    }
    l[v] = res.first;
    r[v] = res.second;
    return res;
}

void dfs2(int v, int p) {
