        if (u == p) continue;
        if (l[u] % 2 == l[v] % 2) {
            l[u] = 3e7;
        } else {
            l[u] = max(l[u], l[v] - 1);
            r[u] = min(r[u], r[v] + 1);
            dfs2(u, v);
        }
