struct Graph {
    vector<edge> G[MAX];
    lli dist[MAX];  // shortest distance
    Graph()
    {
        rep(i, MAX)
        {
            G[i].clear();
            dist[i] = -1;
        }
    }
    void dijkstra(lli s)
    {
        priority_queue<node> que;
        que.push(node(s, 0));
        while (!que.empty()) {
            lli v = que.top().v, d = que.top().d;
            que.pop();
            if (dist[v] >= 0 and dist[v] <= d)
                continue;
            dist[v] = d;
            for (lli i = 0; i < G[v].size(); i++)
                que.push(node(G[v][i].to, d + G[v][i].d));
        }
    }
};

