typedef pair<int, int> P;
int n, k, INIT=1e8;
P p[100000];
vector<int> e[100000];
P f(int x, int y, int z){
    int a=-1e7, b=1e7, q=z;
    if(p[x].first<INIT){
        a=max(a, p[x].first);
        b=min(b, p[x].second);
    }
    if(q==-1){
        q=a%2;
    }else{
        if((q+a+INIT)%2==1)a++;
        if((q+b+INIT)%2==1)b--;
    }
    for(int i=0;i<e[x].size();i++){
        int v=e[x][i];
        if(v!=y){
            P u=f(v, x, (q+1)%2);
            if(u.first>u.second){
                return P(INIT, -INIT);
            }
            a=max(a, u.first-1);
            b=min(b, u.second+1);
            if((q+a+INIT)%2==1)a++;
            if((q+b+INIT)%2==1)b--;
        }
    }
    //cout<<x<<" : "<<a<<" - "<<b<<endl;
    return p[x]=P(a, b);
}

void g(int x, int y){
    int q=p[x].first;
    for(int i=0;i<e[x].size();i++){
        int w=e[x][i];
        if(w!=y){
            if(q-1>=p[w].first){
                p[w]=P(q-1, q-1);
            }else{
                p[w]=P(q+1, q+1);
            }
            g(w, x);
        }
    }
}

