        int v, w;
        cin>>v>>w;
        v--;
        p[v]=P(w, w);
        if(i==k-1){
            p[v]=f(v, -1, -1);
            if(p[v].first>p[v].second){
                cout<<"No"<<endl;
                return 0;
            }
            g(v, -1);
        }
    }
