bool f(int i, int p, int l,int h,int e){
	if(vs[i]!=-1){
		l=max(l,vs[i]);
		h=min(h,vs[i]);
		if(vs[i]%2){
			vs[i]|=1;
		}
		else{
			vs[i]|=2;
		}
	}
	for(int c:ed[i]){
		if(c!=p){
			if(h<l||e==3){
				return false;
			}
			if(!f(c,i,l-1,h+1,e*2+e/2)){
				return false;
			}
			l=max(l,ls[c]-1);
			h=min(h,hs[c]+1);
			if(es[c]==1){
				e|=2;
			}
			else if(es[c]==2){
				e|=1;
			}
		}
	}
	if(e==1){
		if(l%2==0){
			l++;
		}
		if(h%2==0){
			h--;
		}
	}
	else if(e==2){
		if(l%2){
			l++;
		}
		if(h%2){
			h--;
		}
	}
	if(h<l||e==3){
		return false;
	}
	es[i]=e;
	ls[i]=l;
	hs[i]=h;
	return true;
}
