const int N = 1e5 + 10, INF = 1e7;
int n, rt, f[N], p[N], k;
std::vector<int> to[N], c[N];
std::pair<int, int> r[N];
bool o1, o2, d[N], h[N];

inline std::pair<int, int> merge(std::pair<int, int> a, std::pair<int, int> b) {
    return std::make_pair(std::max(a.first, b.first), std::min(a.second, b.second));
}

void build(int cur) {
    for (int i : to[cur])
        if (i != f[cur]) {
            c[cur].push_back(i);
            f[i] = cur;
            d[i] = !d[cur];
            build(i);
        }
}

void dfs(int cur) {
    if (cur != rt)
        r[cur] = merge(r[cur], std::make_pair(r[f[cur]].first - 1, r[f[cur]].second + 1));
    for (int i : c[cur]) {
        dfs(i);
        r[cur] = merge(r[cur], std::make_pair(r[i].first - 1, r[i].second + 1));
    }
}

void query(int cur) {
    p[cur] = r[cur].first;
    if (cur != rt && p[cur] == p[f[cur]])
        p[cur]++;
    for (int i : c[cur]) {
        r[i] = merge(r[i], std::make_pair(p[cur] - 1, p[cur] + 1));
        query(i);
    }
}

int main() {
    scanf("%d", &n);
    rt = rand() % n + 1;
    for (int i = 1; i < n; i++) {
        static int t1, t2;
        scanf("%d%d", &t1, &t2);
        to[t1].push_back(t2);
        to[t2].push_back(t1);
    }
    build(rt);
    for (int i = 1; i <= n; i++)
        r[i] = std::make_pair(-INF, INF);
    scanf("%d", &k);
    for (int i = 1; i <= k; i++) {
        static int t1, t2;
        scanf("%d%d", &t1, &t2);
        h[t1] = true;
        p[t1] = t2;
        r[t1] = std::make_pair(t2, t2);
        ((d[t1] ^ (t2 & 1)) ? o1 : o2) = true;
    }
    if (o1 && o2) {
        puts("No");
        return 0;
    }
    dfs(rt);
    if (r[rt].first <= r[rt].second) {
        puts("Yes");
        query(rt);
        for (int i = 1; i <= n; i++)
            printf("%d\n", p[i]);
    } else {
        puts("No");
    }
    return 0;
}

