using namespace std;

vector<int> neig[100001];
int p[100001], l[100001], r[100001];
bool flag = 1;

pi fun(int u, int prev, pi p1)
{
	pi p2 = {p1.first - 1, p1.second + 1};
	if (p[u] != -1)
	{
		if (p[u] < p2.first || p[u] > p2.second)
		{
			flag = 0;
		}
		p2 = {p[u], p[u]};
	}
	l[u] = p2.first;
	r[u] = p2.second;
	for (int v : neig[u])
	{
		if (v != prev)
		{
			pi temp = fun(v, u, p2);
			l[u] = max(l[u], temp.first - 1);
			r[u] = min(r[u], temp.second + 1);
		}
	}
	if (l[u] > r[u])
	{
		flag = 0;
	}
	return {l[u], r[u]};
}

void fill(int u, int prev, int val)
{
	if (p[u] == -1)
	{
		if (val - 1 >= l[u] && val - 1 <= r[u])
		{
			p[u] = val - 1;
		}
		else
		{
			p[u] = val + 1;
		}
		// cout << u << " " << p[u] << endl;
	}
	if (abs(p[u] - val) != 1)
	{
		flag = 0;
	}
	for (int v : neig[u])
	{
		if (v != prev)
		{
			fill(v, u, p[u]);
		}
	}
}

