bool dfs2(int u, int f) {
	if (tag[u]) L[u] = R[u] = a[u];
	else L[u] = -2e8, R[u] = 2e8;
	for (int v, i = 0; i < g[u].size(); ++i) if ((v = g[u][i]) != f) {
