  cin>>n;
  vec = vector<vector<int> >(n, vector<int>());
  num = vector<int>(n, -INF);
  memo = vector<pair<int, int> >(n, pair<int, int>(-INF, INF));
  rep(i,n-1){
    int a,b;
    scanf("%d %d", &a, &b);
    a--; b--;
    vec[a].pb(b);
    vec[b].pb(a);
  }
  int k; cin>>k;
  rep(i,k){
    int a,b;
    scanf("%d %d", &a, &b);
    a--;
    num[a]=b;
    memo[a]=mp(b,b);
    ss=a;
  }

  if(check(-1, ss, 0) && build(-1,ss)){
    cout<<"Yes"<<endl;
    rep(i,n) printf("%d\n", num[i]);
  } else{
    cout<<"No"<<endl;
  }

  return 0;
}

