const int N = 1e5 + 5;
inline int Get() {
	char ch;
	while ((ch = getchar()) < '0' || ch > '9');
	int Num = ch - '0';
	while ((ch = getchar()) >= '0' && ch <= '9')
		Num = (Num << 3) + (Num << 1) + ch - '0';
	return Num;
}
const int inf = 1e9;
int n, m, que[N], qn, sgn[N], xl[N], xr[N], flag, fa[N];
int tot, first[N], next[N << 1], end[N << 1];
inline void AddEdge(int x, int y) {
	next[++tot] = first[x], first[x] = tot, end[tot] = y;
	next[++tot] = first[y], first[y] = tot, end[tot] = x;
}
int main() {
	n = Get();
	for (int i = 1; i < n; ++i) AddEdge(Get(), Get());

	m = Get(), flag = true;
	for (int i = 1; i <= n; ++i) sgn[i] = -1, xl[i] = -inf, xr[i] = inf;
	for (int i = 1; i <= m; ++i) { 
		int x = Get(), val = Get();
		if (val < xl[x] || val > xr[x]) flag = false;
		xl[x] = xr[x] = val, sgn[x] = val & 1;
	}

	que[qn = 1] = 1;
	for (int ql = 1, u; u = que[ql], ql <= qn; ++ql)
		for (int k = first[u], v; v = end[k], k; k = next[k])
			if (v != fa[u]) fa[v] = u, que[++qn] = v;

	for (int qr = qn, u; u = que[qr], qr; --qr) 
		for (int k = first[u], v; v = end[k], k; k = next[k]) 
			if (v != fa[u]) {
				int vl = xl[v] - 1, vr = xr[v] + 1;
				if (vr < xl[u] || xr[u] < vl) flag = false;
				xl[u] = std :: max(xl[u], vl);
				xr[u] = std :: min(xr[u], vr);

				if (sgn[v] >= 0) 
					if (sgn[u] >= 0 && sgn[u] == sgn[v]) flag = false;
					else sgn[u] = sgn[v] ^ 1;
			}

	for (int ql = 1, u; u = que[ql], ql <= qn; ++ql) {
		if (fa[u]) {
			xl[u] = std :: max(xl[u], xl[fa[u]] - 1);
			xr[u] = std :: min(xr[u], xr[fa[u]] + 1);
			sgn[u] = sgn[fa[u]] ^ 1;
		}

		if (xl[u] > xr[u] || xl[u] == xr[u] && sgn[u] >= 0 && (xl[u] & 1) != sgn[u]) flag = false; 

		xl[u] = xr[u] = xl[u] + xr[u] >> 1;
		if (sgn[u] >= 0 && (xl[u] & 1) != sgn[u]) ++xl[u], ++xr[u];
		sgn[u] = xl[u] & 1;
	}

	if (!flag) {
		puts("No");
		return 0;
	}
	else {
		puts("Yes");
		for (int i = 1; i <= n; ++i) printf("%d\n", xl[i]);
	}
}

