}

pii pro(int x)
{
    visit[x] = true;
    pii res = make_pair(INF,-1 * INF);
    if(G[x].size() == 1)
    {
        res.first = D[x].first + 1;
        res.second = D[x].second - 1;
        return res;
    }
    for(int i = 0; i < G[x].size(); i++)
    {
        if(visit[G[x][i]])
        {
            continue;
        }
        pii lim = pro(G[x][i]);
        res.first = min(res.first,lim.first);
        res.second = max(res.second,lim.second);
    }
    if(D[x].first != INF)
    {
        if(D[x].first > res.first || D[x].second < res.second)
        {
            res.first = -1 * INF;
            res.second = INF;
            return res;
        }
        else
        {
            res.first = D[x].first + 1;
            res.second = D[x].second - 1;
            return res;
        }
    }
    D[x] = res;
    if(res.first < res.second)
    {
        res.first = -1 * INF;
            res.second = INF;
            return res;
    }
    res.first++;
    res.second--;
    return res;
}

void drow(int x,bool o)
{
    if(color[x] == true)return;
    color[x] = true;
    if(D[x].first != INF)
    {
        if(O == -1 || O == (int)((bool)(D[x].first % 2) ^ o))
        {
            O = (int)((bool)(D[x].first % 2) ^ o);
        }
        else can = false;
    }
    for(int i = 0; i < G[x].size(); i++)
    {
        drow(G[x][i],!o);
    }
    return;
}

void write(int x,pii now)
{
    pii next;
    if(ans[x] != -1 * INF)return;
    if(D[x].first >= now.first && now.first >= D[x].second)
    {
        ans[x] = now.first;
        next.first = now.first + 1;
        next.second = now.first - 1;
    }
    else
    {
        ans[x] = now.second;
        next.first = now.second + 1;
        next.second = now.second - 1;
    }
    for(int i = 0; i < G[x].size(); i++)
    {
        write(G[x][i],next);
    }
    return;
}

