void dfs1(int v, int pr, int h) {
    if (col[v] != -1) {
        if (kek[h] == -1)
            kek[h] = col[v];

        if (1 & (col[v] ^ kek[h]))
            ok = false;

        L[v] = R[v] = col[v];
    }

    for (auto to : g[v])
        if (to != pr) {
            dfs1(to, v, (h ^ 1));
            L[v] = max(L[v], L[to] - 1);
            R[v] = min(R[v], R[to] + 1);
        }
}

void dfs2(int v, int pr, pair<ll, ll> up) {
    multiset<ll> Ls, Rs;
    Ls.insert(-INF * INF);
    Rs.insert(INF * INF);

    for (auto to : g[v])
        if (to != pr) {
            Ls.insert(L[to]);
            Rs.insert(R[to]);
        }

    if (pr != -1) {
        L[v] = max(L[v], up.f - 1);
        R[v] = min(R[v], up.s + 1);
        Ls.insert(up.f);
        Rs.insert(up.s);
    }

    for (auto to : g[v])
        if (to != pr) {
            auto curL = L[to];
            auto curR = R[to];
            Ls.erase(Ls.find(curL));
            Rs.erase(Rs.find(curR));
            dfs2(to, v, mp(*Ls.rbegin() - 1, *Rs.begin() + 1));
            Ls.insert(curL);
            Rs.insert(curR);
        }
}

void dfs(int v, int pr) {
    for (auto to : g[v])
        if (to != pr) {
            if (col[to] == -1) {
                if (L[to] <= col[v] - 1 && col[v] - 1 <= R[to])
                    col[to] = col[v] - 1;
                else
                    col[to] = col[v] + 1;
            }

            dfs(to, v);
        }
}

void solve() {
    kek[0] = kek[1] = -1;
    fill(L, L + n, -INF * INF);
    fill(R, R + n, INF * INF);
    dfs1(0, -1, 0);
    dfs2(0, -1, mp(-INF * INF, INF * INF));

    forn (v, n)
        if (L[v] > R[v])
            ok = false;

    if (!ok || (kek[0] != -1 && kek[1] != -1 && (kek[0] ^ kek[1]) % 2 == 0)) {
        while (clock() <= 1.5 * CLOCKS_PER_SEC) { }
        cout << "No\n";
        return ;
    }

    forn (i, n)
        if (col[i] != -1) {
            dfs(i, -1);
            break;
        }

    cout << "Yes\n";

    forn (i, n)
        cout << col[i] << endl;
}

