const int N = 1e5 + 10;
const int M = 2e5 + 10;
int las[N], nex[M], to[M], sz, val[N], n, K, fa[N], ans[N];
bool visit[N];
struct node {
    int l, r;
    bool all;
    bool empty;
} rem[N], tmp[N];
void add(int x, int y) {
    to[++sz] = y; nex[sz] = las[x]; las[x] = sz;
}
bool dfs(int now) {
    int cnt = 0, flag = 0;
    for (int i = las[now]; i; i = nex[i])
    if(!visit[to[i]]) {
        visit[to[i]] = true;
        if(!dfs(to[i])) {
            rem[now].empty = true;
            return false;
        }

    }
    else fa[now] = to[i];

    for (int  i = las[now]; i; i = nex[i])
    if(to[i] != fa[now]) {
        tmp[++cnt] = rem[to[i]];
        tmp[cnt].l -= 1;
        tmp[cnt].r += 1;
    }

    if(!rem[now].all)
    {
        tmp[++cnt] = rem[now];
    }
    if(cnt == 0) return true;
    flag = (tmp[1].l & 1);
    for (int i = 1; i <= cnt; i++) {
        if(tmp[i].all) continue;
        else if(tmp[i].l & 1 != flag) flag = -1;
    }
    if(flag == -1) return false; 

    int maxl = -(1e9), minr = 1e9;
    for (int i = 1; i <= cnt; i++) {
        //printf("for now = %d %d %d\n",now, tmp[i].l, tmp[i].r);
        if(tmp[i].l > maxl) maxl = tmp[i].l;
        if(tmp[i].r < minr) minr = tmp[i].r;
    }
    if(maxl > minr) return false;
    rem[now].l = maxl;
    rem[now].r = minr;
    //printf("node = %d %d %d\n",now,  maxl, minr);
    return true;
}
void calc(int now) {
    visit[now] = true;
    int L = max(ans[fa[now]] - 1, rem[now].l);
    int R = min(ans[fa[now]] + 1, rem[now].r);
    ans[now] = L;
    for (int i = las[now]; i; i = nex[i])
    if(!visit[to[i]]) {
        calc(to[i]);
    }
}
