namespace zyt
{
	template<typename T>
	inline bool read(T &x)
	{
		char c;
		bool f = false;
		x = 0;
		do
			c = getchar();
		while (c != EOF && c != '-' && !isdigit(c));
		if (c == EOF)
			return false;
		if (c == '-')
			f = true, c = getchar();
		do
			x = x * 10 + c - '0', c = getchar();
		while (isdigit(c));
		if (f)
			x = -x;
		return true;
	}
	template<typename T>
	inline void write(T x)
	{
		static char buf[20];
		char *pos = buf;
		if (x < 0)
			putchar('-'), x = -x;
		do
			*pos++ = x % 10 + '0';
		while (x /= 10);
		while (pos > buf)
			putchar(*--pos);
	}
	typedef pair<int, int> pii;
	const int N = 1e5 + 10, INF = 0x3f3f3f3f;
	int n, k, l[N], r[N], tag[N];
	vector<int> g[N];
	void dfs(const int u, const int f)
	{
		for (auto v : g[u])
		{
			if (v == f)
				continue;
			dfs(v, u);
			l[u] = max(l[u], l[v] - 1), r[u] = min(r[u], r[v] + 1);
			if ((tag[u] >= 0 && tag[v] != -1 && tag[u] != (tag[v] ^ 1)) || l[u] > r[u])
			{
				puts("No");
				exit(0);
			}
			if (tag[v] != -1)
				tag[u] = (tag[v] ^ 1);
		}
	}
	void dfs2(const int u, const int f)
	{
		if (f)
			l[u] = max(l[u], l[f] - 1), r[u] = min(r[u], r[f] + 1);
		for (auto v : g[u])
		{
			if (v == f)
				continue;
			dfs2(v, u);
		}
	}
	int work()
	{
		read(n);
		for (int i = 1; i <= n; i++)
			l[i] = -INF, r[i] = INF, tag[i] = -1;
		for (int i = 1; i < n; i++)
		{
			int a, b;
			read(a), read(b);
			g[a].push_back(b), g[b].push_back(a);
		}
		read(k);
		while (k--)
		{
			int v, t;
			read(v), read(t);
			l[v] = r[v] = t;
			tag[v] = (t & 1);
		}
		dfs(1, 0);
		dfs2(1, 0);
		puts("Yes");
		for (int i = 1; i <= n; i++)
			write(l[i]), putchar('\n');
		return 0;
	}
}
int main()
{
	return zyt::work();
}

