#include<bits/stdc++.h>
using namespace std;
const int maxn = 1e5 + 5;
vector<int>G[maxn];
int n, k, val[maxn], fa[maxn], now[maxn], dif[maxn];
inline void Add(int u, int v) {
	int x = dif[v] + 1;
	if(dif[u] < 1e7 && dif[v] < 1e7 && ((now[u] + dif[u]) % 2 != (now[v] + x) % 2))
		exit(0 * puts("No"));
	int l = max(now[u] - dif[u], now[v] - x), r = min(now[u] + dif[u], now[v] + x);
	// cerr << "Add " << v << "->" << u <<": " << l <<" " << r << endl;
	if(l > r)
		exit(0 * puts("No"));
	assert((l + r) % 2 == 0);
	now[u] = (l + r) >> 1, dif[u] = r - now[u];
}
inline void Solve(int u) {
	for(auto v : G[u])
		if(v != fa[u])
			fa[v] = u, Solve(v), Add(u, v);
}
inline void Work(int u) {
	val[u] = now[u] - dif[u], now[u] = val[u], dif[u] = 0;
	for(auto v : G[u])
		if(v != fa[u])
			Add(v, u), Work(v);
}
int main() {
	scanf("%d", &n);
	for(int i = 1; i <= n; ++ i)
