st merge(st a, st b){
	if (a.lef == INT_MAX){
		return b;
	}
	if (b.lef == INT_MAX){
		return a;
	}
	if (a.lef % 2 != b.lef % 2){
		return st(INT_MIN, INT_MIN);
	}
	if (a.lef > b.lef){
		swap(a, b);
	}
	if (a.lef <= b.lef&&b.rig <= a.rig){
		return b;
	}
	if (a.rig < b.lef){
		return st(INT_MIN, INT_MIN);
	}
	return st(b.lef, a.rig);
}
