int type[ 2 ] , odd[ N ];
inline bool okay( int now , int prt , int dep ){
  if( st[ now ] ){
    if( type[ dep ] && type[ dep ] - 1 != abs( clr[ now ] ) % 2 )
      return false;
    type[ dep ] = abs( clr[ now ] ) % 2 + 1;
  }
  for( int son : v[ now ] ){
    if( son == prt ) continue;
    if( !okay( son , now , 1 - dep ) )
      return false;
  }
  return true;
}
int lb[ N ] , rb[ N ];
bool got[ N ];
void gogo(){
  priority_queue< PII , vector<PII> , greater<PII> > heap;
  for( int i = 1 ; i <= n ; i ++ )
    if( !st[ i ] )
      heap.push( { rb[ i ] - lb[ i ] , i } );
  while( heap.size() ){
    PII tp = heap.top(); heap.pop();
    int who = tp.second;
    if( st[ who ] ) continue;
    for( int x : v[ who ] )
      if( st[ x ] ){
        lb[ who ] = max( lb[ who ] , lb[ x ] - 1 );
        rb[ who ] = min( rb[ who ] , rb[ x ] + 1 );
      }
    if( lb[ who ] > rb[ who ] ){
      puts( "No" );
      exit( 0 );
    }
    st[ who ] = true;
    clr[ who ] = lb[ who ];
  }
