    puts( "No" );
    exit( 0 );
  }
  queue< int > Q;
  for( int i = 1 ; i <= n ; i ++ )
    if( st[ i ] ){
      got[ i ] = true;
      Q.push( i );
      lb[ i ] = rb[ i ] = clr[ i ];
    }
  while( Q.size() ){
    int tn = Q.front(); Q.pop();
    for( int son : v[ tn ] ){
      if( got[ son ] ){
        lb[ son ] = max( lb[ son ] , lb[ tn ] - 1 );
        rb[ son ] = min( rb[ son ] , rb[ tn ] + 1 );
      }else{
        got[ son ] = true;
        Q.push( son );
        lb[ son ] = lb[ tn ] - 1;
        rb[ son ] = rb[ tn ] + 1;
      }
    }
  }
  for( int i = 1 ; i <= n ; i ++ )
    if( lb[ i ] > rb[ i ] ){
      puts( "No" );
      exit( 0 );
    }
  gogo();
  if( !okay( 1 , 1 , 0 ) ){
    puts( "No" );
    exit( 0 );
  }
  puts( "Yes" );
  for( int i = 1 ; i <= n ; i ++ )
    printf( "%d\n" , clr[ i ] );
}
