map<int, pii> range;
pii rec(int p, int v) {

  pii ret;
  ret = pii(-INF, INF);
  dump(p, v, ret);

  for (int x : G[v]) {
    if (x == p)
      continue;
    pii r = rec(v, x);
    dump(x, r);
    r.fi--,r.se++;
    chmax(ret.fi, r.fi);
    chmin(ret.se, r.se);
    dump(v, ret);
  }
  if (ret.fi > ret.se) {
    ret.fi = INF;
    ret.se = -INF;
    dump(p, v, ret);
    return ret;
  } else if (f[v] != INF) {
    if (ret.fi <= f[v] and f[v] <= ret.se) {
      range[v] = pii(f[v], f[v]);
      dump(p, v, ret);
      return range[v];
    } else {
      dump(p, v, ret);
      return pii(INF, -INF);
    }
  }
  dump(p, v, ret);
  return range[v] = ret;
}
void restore(int p, int v, int w) {

  h[v] = w;

  for (int x : G[v]) {
    if (x == p)
      continue;

    if (range[x].fi <= w - 1 and w - 1 <= range[x].se) {
      restore(v, x, w - 1);
    } else {
      restore(v, x, w + 1);
    }
  }
}
