int f(int c, int k) {
	if(d[k].count(c)) return d[k][c];
	if(wt[k] && a[k]!=c) return 0;
	if(child[k].empty()) return 1;
	for(int i=child[k].size()-1;i>=0;i--) {
		if(f(c+1,child[k][i])==0 && f(c-1,child[k][i])==0) {
			return d[k][c]=0;
		}
	}
	return d[k][c]=1;
}

void trace(int c, int k) {
	res[k]=c;
	for(int i=0;i<child[k].size();i++)  {
		if(f(c-1,child[k][i])) {
			trace(c-1,child[k][i]);
		} else {
			trace(c+1,child[k][i]);
		}
	}
}

