#include <algorithm>
#include <iostream>
#include <utility>
#include <vector>
#include <queue>
using namespace std;
typedef pair<int,int> P;

const int MAX_N = 100000;
const int INF = 100000000;

template <typename T>
struct edge
{
    int from, to;
    T cost;
};

template<typename T>
struct Graph
{
    int n;
    vector<edge<T>> g[MAX_N + 4];
    T d[MAX_N + 4];
    int pre[MAX_N + 4];
    vector<int> tips;

    Graph(int n) : n(n) {};

    void add_edge(int from, int to, int cost){
        g[from].push_back(edge<T>{from, to, cost});
    }

    void Dijkstra(int s){
        typedef pair<T, int> PT;
        queue<PT> que;
        fill(d, d + n, INF);
        fill(pre, pre + n, -1);
        d[s] = 0;
        que.push(PT(0, s));
        while(que.size()){
            PT nowp = que.front();
            que.pop();
            int now = nowp.second;
            if(d[now] < nowp.first) continue;
            if((int)g[now].size() == 1) tips.push_back(now);
            for(edge<T> e : g[now]){
                if(d[e.to] > d[now] + e.cost){
                    d[e.to] = d[now] + e.cost;
                    que.push(PT(d[e.to], e.to));
                    pre[e.to] = e.from;
                }
            }
        }
    }
};

int main()
{
    int n;
    cin >> n;
    Graph<int> g(n);
    int a[100002], b[100002];
    for(int i = 0; i < n - 1; i++){
        cin >> a[i] >> b[i];
        a[i]--;
        b[i]--;
        g.add_edge(a[i], b[i], 1);
        g.add_edge(b[i], a[i], 1);
    }
    g.Dijkstra(0);
    int k;
    cin >> k;
    int lar[100002], les[100002];
    fill(lar, lar + n, INF);
    fill(les, les + n, -INF);
    int v[100002], p[100002];
    int eo;
    for(int i = 0; i < k; i++){
        cin >> v[i] >> p[i];
        v[i]--;
        lar[v[i]] = p[i];
        les[v[i]] = p[i];
        if(i == 0) eo = (g.d[v[i]] + p[i]) % 2;
        if((g.d[v[i]] + p[i]) % 2 != eo){
            cout << "No" << endl;
            return 0;
        }
    }
    P pa[100002];
    for(int i = 0; i < n; i++) pa[i] = P(g.d[i], i);
    sort(pa, pa + n, greater<P>());
    for(int i = 0; i < n - 1; i++){
        lar[g.pre[pa[i].second]] = min(lar[g.pre[pa[i].second]], lar[pa[i].second] + 1);
        les[g.pre[pa[i].second]] = max(les[g.pre[pa[i].second]], les[pa[i].second] - 1);
        if(lar[g.pre[pa[i].second]] < les[g.pre[pa[i].second]]){
            cout << "No" << endl;
            return 0;
        }
    }
    int ans[100002];
    for(int i = 0; i < n; i++) ans[i] = INF;
    queue<int> que;
    ans[0] = les[0];
    que.push(0);
    while(que.size()){
        int now = que.front();
        que.pop();
        for(edge<int> e : g.g[now]){
            if(ans[e.to] == INF){
                if(les[e.to] <= ans[e.from] - 1) ans[e.to] = ans[e.from] - 1;
                else ans[e.to] = ans[e.from] + 1;
                que.push(e.to);
            }
        }
    }
    cout << "Yes" << endl;
    for(int i = 0; i < n; i++) cout << ans[i] << endl;
}

