int main() {
  int n; cin >> n;
  vector<vector<int> > graph(n);
  REP(_, n - 1) {
    int a, b; cin >> a >> b; --a; --b;
    graph[a].emplace_back(b);
    graph[b].emplace_back(a);
  }
  vector<int> p(n, -1);
  int k; cin >> k;
  while (k--) {
    int v; cin >> v; --v;
    cin >> p[v];
  }
  vector<int> lb(n, -INF), ub(n, INF);
  function<void(int)> solve = [&](int root) {
    function<void(int, int)> dfs = [&](int par, int ver) {
      for (int e : graph[ver]) {
        if (e == par) continue;
        dfs(ver, e);
        chmax(lb[ver], lb[e] - 1);
        chmin(ub[ver], ub[e] + 1);
      }
      if (ub[ver] < lb[ver]) {
        cout << "No\n";
        exit(0);
      }
      if (p[ver] != -1) {
        if (lb[ver] <= p[ver] && p[ver] <= ub[ver]) {
          lb[ver] = ub[ver] = p[ver];
        } else {
          cout << "No\n";
          exit(0);
        }
      }
    };
    dfs(-1, root);
    // REP(i, n) cout << lb[i] << ' ' << ub[i] << '\n';
    vector<int> ans(n);
    ans[root] = p[root];
    function<void(int, int)> dfs2 = [&](int par, int ver) {
      for (int e : graph[ver]) {
        if (e == par) continue;
        ans[e] = ans[ver] + (lb[e] <= ans[ver] + 1 && ans[ver] + 1 <= ub[e] ? 1 : -1);
        dfs2(ver, e);
      }
    };
    dfs2(-1, root);
    cout << "Yes\n";
    REP(i, n) cout << ans[i] << '\n';
  };
  REP(i, n) {
    if (p[i] != -1) {
      solve(i);
      break;
    }
  }
  return 0;
}

