  if(~value[idx] && value[idx] % 2 != now) {
    puts("No");
    exit(0);
  }
  c[idx] = now;
  for(int to : tree[idx]) {
    if(to == par) continue;
    color(to, now ^ 1, idx);
  }
}

int main()
{
  cin >> N;
  for(int i = 0; i < N - 1; i++) {
    int A, B;
    cin >> A >> B;
    tree[--A].push_back(--B);
    tree[B].push_back(A);
  }
  cin >> K;
  memset(value, -1, sizeof(value));
  for(int i = 0; i < K; i++) {
    int V, P;
    cin >> V >> P;
    value[--V] = P;
  }
  queue< int > que;
  fill_n(small, 100000, -INF);
  fill_n(big, 100000, INF);

  bool first = false;
  for(int i = 0; i < N; i++) {
    if(~value[i]) {
      que.push(i);
      small[i] = big[i] = value[i];
      if(!first++) color(i, value[i] & 1);
    }
  }

  while(!que.empty()) {
    int p = que.front();
    que.pop();
    for(int to : tree[p]) {
      if(small[to] < small[p] - 1 || big[to] > big[p] + 1) {
        small[to] = max(small[to], small[p] - 1);
        big[to] = min(big[to], big[p] + 1);
        que.push(to);
      }
    }
  }


  for(int i = 0; i < N; i++) {
    if(small[i] > big[i]) {
      puts("No");
      exit(0);
    } else if(small[i] == big[i]) {
      que.push(i);
    }
  }

  while(!que.empty()) {
    int p = que.front();
    que.pop();
    for(int to : tree[p]) {
      if(small[to] != big[to]) {
        if(small[to] <= small[p] - 1 && small[p] - 1 <= small[to]) {
          que.push(to);
          small[to] = big[to] = small[p] - 1;
        } else if(small[to] <= small[p] + 1 <= small[p] - 1 <= small[to]) {
          que.push(to);
          small[to] = big[to] = small[p] + 1;
        } else {
          puts("No");
          exit(0);
        }
      }
    }
  }

  puts("Yes");
  for(int i = 0; i < N; i++) {
    printf("%d\n", small[i]);
  }


}

