#define mp(a, b) make_pair(a, b)
const int INF = 1e9;
typedef pair<int, int> pii;
const int maxn = 1e5 + 10;
vector<int> E[maxn];
int n, k, pos[maxn], val[maxn], dep[maxn], d[maxn];
pii range[maxn];
void no() { puts("No"); exit(0);}
void getdep(int x, int fa)
{
	dep[x] = dep[fa] + 1;
	for(auto v : E[x])
		if(v != fa)
			getdep(v, x);
}
void merge(pii & i, const pii & j)
{
	i = mp(max(i.first, j.first), min(i.second, j.second));
	if(i.first > i.second) no();
}
pii add(const pii & i)
{
	return i.second == INF ? i : mp(i.first, i.second + 2);
}
void getrange(int x, int fa)
{
	for(auto v : E[x])
		if(v != fa)
		{
			getrange(v, x);
			merge(range[x], add(range[v]));
		}
}
void getd(int x, int fa)
{
	for(auto v : E[x])
		if(v != fa)
		{
			if(range[v].first <= d[x] && d[x] <= range[v].second)
				d[v] = d[x];
			else
				d[v] = d[x] - 2;
			getd(v, x);
		}
}
int main()
{
	scanf("%d", &n);
	for(int i = 1; i < n; ++i)
	{
		int u, v;
		scanf("%d%d", &u, &v);
		E[u].push_back(v);
		E[v].push_back(u);
	}
	scanf("%d", &k);
	for(int i = 1; i <= k; ++i) 
		scanf("%d%d", &pos[i], &val[i]);
	getdep(pos[1], 0);
	for(int i = 1; i <= k; ++i)
	{
		d[pos[i]] = val[i] - dep[pos[i]];
		if((d[pos[i]] & 1) != (d[pos[1]] & 1))
			no();
	} 
	for(int i = 1; i <= n; ++i) range[i] = mp(-INF, INF);
	for(int i = 1; i <= k; ++i) range[pos[i]] = mp(d[pos[i]], d[pos[i]]);
	getrange(pos[1], 0);
	getd(pos[1], 0);
	puts("Yes");
	for(int i = 1; i <= n; ++i) printf("%d\n", d[i] + dep[i]);
	return 0;
}

