int dfs(ll coming,ll start,ll value,vector<vector<ll>>A,vector<ll>&V,vector<int> Y){


	if (Y[start] == 1){
		if (V[start] != value){
			return 0;
		}
	}
	V[start] = value;
	for (int i = 0; i < A.size(); i++){
		if (A[start][i] == 1){
			if (i == coming){
				continue;
			}
			int success; 
			success=dfs(start,i, V[start]+1,A, V, Y);
			if (success != 1){
				success=dfs(start,i, V[start] - 1, A, V, Y);
			}
			if (success != 1)
				return 0;
		}
	}
	return 1;
}

