int N, K, Head[Max_N], Total, To[Max_N << 1], Next[Max_N << 1], L[2][Max_N], R[2][Max_N], Ans[Max_N];

inline void Add_Edge(int s, int t)
{
	++Total, To[Total] = t, Next[Total] = Head[s], Head[s] = Total;
}

void dfs(int u, int fa)
{
	for (int i = Head[u], v;i;i = Next[i])
		if ((v = To[i]) != fa)
		{
			dfs(v, u);
			for (int c = 0;c <= 1;++c)
				L[c][u] = max(L[c][u], L[c ^ 1][v] - 1), R[c][u] = min(R[c][u], R[c ^ 1][v] + 1);
		}
	if (L[0][u] > R[0][u] && L[1][u] > R[1][u])
		GG();
}

/*
只考虑一个点的子树，该点能填的数一定是一段连续的奇数和一段连续的偶数的并。可以归纳证明 
*/

void printAns(int u, int fa)
{
	for (int i = Head[u], v;i;i = Next[i])
		if ((v = To[i]) != fa)
		{
			if (L[(Ans[u] & 1) ^ 1][v] <= Ans[u] - 1 && Ans[u] - 1 <= R[(Ans[u] & 1) ^ 1][v])
				Ans[v] = Ans[u] - 1;
			else
				Ans[v] = Ans[u] + 1;
			printAns(v, u);
		}
}

