	for (int i = 1;i <= N;++i)
		L[0][i] = 0, R[0][i] = 1000000, L[1][i] = 1, R[1][i] = 1000001;
	for (int i = 1, u, v;i != N;++i)
		scanf("%d%d", &u, &v), Add_Edge(u, v), Add_Edge(v, u);
	scanf("%d", &K);
	for (int v, p;K--;)
		scanf("%d%d", &v, &p), L[p & 1][v] = R[p & 1][v] = p, L[(p & 1) ^ 1][v] = 100000, R[(p & 1) ^ 1][v] = 0;
	dfs(1, -1);
	puts("Yes");
	Ans[1] = (L[0][1] <= R[0][1] ? L[0][1] : L[1][1]), printAns(1, -1);
	for (int i = 1;i <= N;++i)
		printf("%d\n", Ans[i]);
	return 0;
}

