typedef pair<li, li> PI;

li num[100100];
PI bounds[100100];

vector<li> edges[100100];
li n, k;

inline PI dfs(li now, li from, li lower, li upper) {
    PI res{lower, upper};
    if (num[now] != -1) {
        if (lower != -INF && upper != INF) {
            if (lower % 2 != num[now] % 2 ||
                    upper % 2 != num[now] % 2 ||
                    lower > num[now] ||
                    upper < num[now]) {
                puts("No");
                exit(0);
            }
        }
        res = {num[now], num[now]};
        lower = num[now];
        upper = num[now];
    }
    li next_lower = (lower == -INF ? -INF : lower - 1);
    li next_upper = (upper == INF ? INF : upper + 1);
    for (auto next : edges[now]) {
        if (next == from)continue;
        PI next_bound = dfs(next, now, next_lower, next_upper);
        if (res.F != -INF &&
                next_bound.F != -INF &&
                res.F % 2 != next_bound.F % 2) {
            puts("No");
            exit(0);
        }
        res.F = max(res.F, next_bound.F);
        res.S = min(res.S, next_bound.S);
    }
    if (res.F > res.S) {
        puts("No");
        exit(0);
    }
    bounds[now] = res;
    return {res.F - 1, res.S + 1};
}


inline PI dfs2(li now, li from, li lower, li upper) {
    if (bounds[now].F != -INF &&
            bounds[now].F % 2 != lower % 2) {
        puts("No");
        exit(0);
    }
    if (bounds[now].S != INF &&
            bounds[now].S % 2 != upper % 2) {
        puts("No");
        exit(0);
    }
    if (bounds[now].F == -INF) {
        bounds[now].F = lower;
    } else {
        bounds[now].F = max(bounds[now].F, lower);
    }
    if (bounds[now].S == INF) {
        bounds[now].S = upper;
    } else {
        bounds[now].S = min(bounds[now].S, upper);
    }
    if (bounds[now].F > bounds[now].S) {
        puts("No");
        exit(0);
    }

    for (auto next : edges[now]) {
        if (next == from)continue;
        PI next_bound = dfs2(next, now, bounds[now].F - 1, bounds[now].S + 1);
        if (bounds[now].F % 2 != next_bound.F % 2) {
            puts("No");
            exit(0);
        }
        bounds[now].F = max(bounds[now].F, next_bound.F);
        bounds[now].S = min(bounds[now].S, next_bound.S);
    }

    if (bounds[now].F > bounds[now].S) {
        puts("No");
        exit(0);
    }
    return {bounds[now].F - 1, bounds[now].S + 1};
}

