bool __dfs(int cur, int pre, int num){
	bool res = false;
	for(auto to : g[cur]){
		if(to == pre) continue;
		if(v[to].first != INF and v[to].first % 2 != (num + 1) % 2){
			return true;
		}
		res |= __dfs(to, cur, num + 1);
	}
	return false;
}

void dfs(int cur, int pre){
	for(auto to : g[cur]){
		if(to == pre) continue;

		dfs(to, cur);
		v[cur].first = min(v[cur].first, v[to].first + 1);
		v[cur].second = max(v[cur].second, v[to].second - 1);
	}
}

void _dfs(int cur, int pre){
	for(auto to : g[cur]){
		if(to == pre) continue;
		if(v[to].first == INF){
			v[to] = make_pair(v[cur].first + 1, v[cur].second - 1);
		}
		_dfs(to, cur);
	}
}

