bool seen[100010];

void boo() {
    cout << "No" << endl;
    exit(0);
}

struct node {
    int v, par;
};

typedef pair<int, int> pii;
queue<node> q1;
priority_queue<pii> pq;

void bfs() {
    while (!q1.empty()) {
        int v = q1.front().v;
        int par = q1.front().par;
        q1.pop();

        for (const int& w : G[v]) {
            if (w == par) continue;

            up[w] = v;
            depth[w] = depth[v] + 1;

            if (p[w] != MOD) {
                pq.push({depth[w], w});
                ma[w] = p[w];
                mi[w] = p[w];
            } else {
                // free
                ma[w] = ma[v] + 1;
                mi[w] = mi[v] - 1;
            }

            q1.push({w, v});
        }
    }
}

