        int w = pq.top().second;
        int v = up[w];
        //cout << pq.top().first << " " << w << endl;

        pq.pop();

        if(ma[v] % 2 == ma[w] % 2) boo();
        if(mi[v] % 2 == mi[w] % 2) boo();

        ma[v] = min(ma[v], ma[w] + 1);
        mi[v] = max(mi[v], mi[w] - 1);

        if(ma[v] < mi[v]) boo();
        if(seen[v]) continue;
        if(v == vv) continue;
        pq.push({depth[v], v});
        seen[v] = true;
    }

