void Merge(int& l, int& r, int L, int R){
    if (l == -inf) l = L, r = R;
    else{
        if ((l + r) % 2 != 0) {cout << "No"; exit(0);}
        l = max(l, L);
        r = min(r, R);
        if (l > r) {cout << "No"; exit(0);}
    }
}

void dfs(int u, int p){
    for (int i = 0; i < adj[u].size(); i++){
        int v = adj[u][i];
        if (v == p) continue;
        dfs(v, u);
        if (l[v] != -inf) Merge(l[u], r[u], l[v]-1, r[v]+1);
    }
}

void redfs(int u, int p){
    for (int i = 0; i < adj[u].size(); i++){
        int v = adj[u][i];
        if (v == p) continue;
        if (ans[u]-1 >= l[v]) ans[v] = ans[u] - 1;
        else ans[v] = ans[u] + 1;
        redfs(v, u);
    }
}

