bool maximize (int &a, int b) { if (a < b) a = b; else return false; return true; }
bool minimize (int &a, int b) { if (a > b) a = b; else return false; return true; }
void bfs () {
	queue <int> q; 
	for (int i = 0; i < painted.size(); i++) q.push(painted[i]);
	int Time = 0; 
	while (not q.empty()) {
		//Time++; 
		//if (Time == 1000000) break; 
		int x = q.front(); q.pop();
		foreach (y, tree[x]) {
			if (lo[*y] == -inf) { /// chua duoc tinh
				lo[*y] = max(lo[*y], lo[x] - 1);
				hi[*y] = min(hi[*y], hi[x] + 1);
				q.push(*y);
			}
			else {
				if (lo[*y] % 2 == lo[x] % 2) {
					success = false;
					return; 
				}
				if (hi[x] + 1 < lo[*y] || hi[*y] < lo[x] - 1) {
					success = false; 
					return; 
				}
				bool changed = false; 
				if (maximize(lo[*y], lo[x] - 1)) changed = true; 
				if (minimize(hi[*y], hi[x] + 1)) changed = true;

				if (changed) q.push(*y);
			}
		}
	}
}

void paint () {
	queue <int> q; 
	for (int x = 1; x <= n; x++) {
		if (lo[x] == hi[x]) q.push(x);
	}
	while (not q.empty()) {
		int x = q.front(); q.pop();
		foreach (y, tree[x]) {
			if (lo[*y] == hi[*y]) {
				if (lo[*y] != lo[x] + 1 && lo[*y] != lo[x] - 1) {
					success = false; 
					return; 
				} 
				continue; 
			}
			if (lo[x] + 1 >= lo[*y] && lo[x] + 1 <= hi[*y]) {
				lo[*y] = lo[x] + 1;
				hi[*y] = lo[x] + 1;
				q.push(*y);  
			} else if (lo[x] - 1 >= lo[*y] && lo[x] - 1 <= hi[*y]) {
				lo[*y] = lo[x] - 1; 
				hi[*y] = lo[x] - 1;
				q.push(*y); 
			} else  {
				success = false; 
				return; 
			}

		}
	}
}

