#define maxn 200005
const int INF=1000000;
int n,m,w[maxn],pre[maxn],other[maxn],last[maxn],o,l[maxn],r[maxn];
bool flag[maxn];

void connect(int x,int y)
{
    o++;
    pre[o]=last[x];
    last[x]=o;
    other[o]=y;
}

void dfs(int u,int fa)
{
    l[u]=-INF;r[u]=INF;
    if (flag[u]) l[u]=r[u]=w[u];
    for (int p=last[u];p;p=pre[p]) 
    {
        int v=other[p];
        if (v==fa) continue;
        dfs(v,u);
        l[u]=max(l[u],l[v]-1);
        r[u]=min(r[u],r[v]+1);
    }
    if (l[u]>r[u]) {puts("No");exit(0);}
}

void solve(int u,int fa)
{
    if (u==1) w[u]=l[u];
    else if (w[fa]+1>=l[u]&&w[fa]+1<=r[u]) w[u]=w[fa]+1;
    else if (w[fa]-1>=l[u]&&w[fa]-1<=r[u]) w[u]=w[fa]-1;
    else {puts("No");exit(0);}
    for (int p=last[u];p;p=pre[p]) 
    {
        int v=other[p];
        if (v==fa) continue;
        solve(v,u);    
    }
}

