    //for (int i=1;i<=n;i++) printf("--%d %d %d--\n",i,l[i],r[i]);
    solve(1,-1);
    puts("Yes");
    for (int i=1;i<=n;i++) printf("%d\n",w[i]);
    return 0;
}

