using namespace std;

int P[100000];
int low[100000];
int high[100000];

void search(int pos, int prev, const vector<vector<int>>& g){
	low[pos] = high[pos] = (P[pos] != -1 ? P[pos] : -1);
	for(int next : g[pos]){
		if(next == prev) continue;
		search(next, pos, g);
		if(low[next] == -2 && high[next] == -2){
			low[pos] = high[pos] = -2;
			return;
		} else if(!(low[next] == -1 && high[next] ==-1)){
			if(low[pos] == -1){
				low[pos] = low[next]-1;
				high[pos] = high[next]+1;
			} else {
				if(abs(low[pos]+low[next])%2 != 1){
					low[pos] = high[pos] = -2;
					return;
				}
				low[pos] = max(low[pos], low[next]-1);
				high[pos] = min(high[pos], high[next]+1);
				if(high[pos] < low[pos]){
					low[pos] = high[pos] = -2;
					return;
				}
			}
		}
	}
}

void search2(int pos, int prev, const vector<vector<int>>& g){
	for(int next : g[pos]){
		if(next == prev) continue;
		if(low[next] == -1 && high[next] == -1){
			low[next] = low[pos] - 1;
			high[next] = high[pos] + 1;
		} else {
			low[next] = max(low[next], low[pos]-1);
			high[next] = max(high[next], high[pos]+1);
		}
		search2(next, pos, g);
	}
}

int main(){
	int N;
	while(cin >> N){
		vector<vector<int>> g(N);
		for(int i=0;i<N-1;i++){
			int A, B; cin >> A >> B;
			--A; --B;
			g[A].push_back(B);
			g[B].push_back(A);
		}
		int K; cin >> K;
		memset(P, -1, sizeof(P));
		int start;
		for(int i=0;i<K;i++){
			int V; cin >> V;
			cin >> P[V-1];
			start = V-1;
		}
		search(start, -1, g);
		if(low[start] == -2 && high[start] == -2){
			cout << "No" << endl;
		} else {
			cout << "Yes" << endl;
			search2(start, -1, g);
			for(int i=0;i<N;i++) cout << low[i] << endl;
		}
	}
}

