int n,a[100004],b[100004],k,v[100004],p[100004];
int guki[100004];
vector<int> road[100004];
int sm[100004],bg[100004];
int ans[100004];
bool dfs(int x,int par, int now){
    guki[x]=now;
    bool ok=1;
    for(auto&i:road[x]){
        if (i==par) {
            continue;
        }
        if (guki[i]) {
            if (guki[i]==now) {
                return false;
            }
        }
        ok&=dfs(i,x,(now==1?2:1));
    }
    return ok;
}
void solve(itn x,int par){
    for(auto&i:road[x]){
        if (i==par) {
            continue;
        }
        solve(i, x);
        chmax(sm[x], sm[i]-1);
        chmin(bg[x], bg[i]+1);
    }
}
void solve2(int x, int par, P info){
    chmax(sm[x], info.first);
    chmin(bg[x], info.second);
    vector<int> sm1,sm2,bg1,bg2;
    for(auto&i:road[x]){
        if (i==par) {
            continue;
        }
        sm1.emplace_back(sm[i]-2);
        bg1.emplace_back(bg[i]+2);
    }
    sm2=sm1;
    bg2=bg1;
    REP(i,(int)sm1.size()-1){
        chmax(sm1[i], sm1[i-1]);
        chmin(bg1[i], bg1[i-1]);
    }
    REV_RREP(i, 1, (int)sm2.size()-1){
        chmax(sm2[i-1], sm2[i]);
        chmin(bg2[i-1], bg1[i]);
    }
    int cnt=0;
    rep(i,road[x].size()){
        if (road[x][i]==par) {
            continue;
        }
        P neo={-inf,inf};
        if (cnt) {
            chmax(neo.first, sm1[cnt-1]);
            chmin(neo.second, bg1[cnt-1]);
        }
        if (cnt<(int)sm2.size()-1) {
            chmax(neo.first, sm2[cnt+1]);
            chmin(neo.second, bg2[cnt+1]);
        }
        cnt++;
        solve2(road[x][i], x, neo);
    }
}
void bye(int x, int par, int now){
    ans[x]=now;
    for(auto&i:road[x]){
        if (i==par) {
            continue;
        }
        if (sm[i]<=now+1&&now+1<=bg[i]) {
            bye(i, x, now+1);
        }else if(sm[i]<=now-1&&now-1<=bg[i]){
            bye(i, x, now-1);
        }else{
            No();
            exit(0);
        }
    }
}
signed main() {
    ios::sync_with_stdio(false);
    std::cin.tie(nullptr);
    cin>>n;
    rep(i,n-1){
        cin>>a[i]>>b[i];
        road[a[i]].emplace_back(b[i]);
        road[b[i]].emplace_back(a[i]);
    }
    fill(sm, sm+n+1, -inf);
    fill(bg, bg+n+1, inf);
    cin>>k;
    rep(i,k){
        cin>>v[i]>>p[i];
        guki[v[i]]=(p[i]&1?1:2);
        sm[v[i]]=p[i];
        bg[v[i]]=p[i];
    }
    if (!dfs(v[0],0,guki[v[0]])) {
        No();
        return 0;
    }
    solve(1, 0);
    solve2(1, 0, {-inf,inf});
    bye(v[0], 0, p[0]);
    Yes();
    REP(i,n){
        cout<<ans[i]<<endl;
    }
}

