bool gather(int u, int p) {
    if (a[u] == inf())
        l[u] = -inf(), r[u] = inf();
    for (auto v : e[u])
        if (v != p) {
            if (a[v] == inf())
                if (!gather(v, u))
                    return false;
            if (l[v] == -inf())
                continue;
            if (l[u] == -inf())
                l[u] = l[v] - 1, r[u] = r[v] + 1;
            else {
                if ((l[u] & 1) == (l[v] & 1))
                    return false;
                if (l[u] > r[v] + 1 || l[v] - 1 > r[u])
                    return false;
                l[u] = max(l[u], l[v] - 1);
                r[u] = min(r[u], r[v] + 1);
            }
        }
    return true;
}
