int odd[maxn];

int a[maxn], b[maxn];
int p[maxn];
int lower[maxn], upper[maxn];
vector<int> G[maxn];

bool dfs(int u, int fa){
    bool flag = true;
    for(auto v : G[u]){
        if(v == fa)
            continue;
        flag &= dfs(v, u);
    }
    if(!flag)
        return false;
    bool flag1 = false;
    bool flag0 = false;
    for(auto v : G[u]){
        if(v == fa)
            continue;
        if(odd[v] == 0)
            flag0 = true;
        if(odd[v] == 1)
            flag1 = true;
    }  
    if(flag1 and flag0)
        return false;
    if(p[u] == -1){
        if(flag1)
            odd[u] = 0;
        if(flag0)
            odd[u] = 1;
    }else{
        if(p[u] & 1){
            if(flag1)
                return false;
            odd[u] = 1;
        }else{
            if(flag0)
                return false;
            odd[u] = 0;
        }
    }
    int lo = -1e9;
    int up = 1e9;
    for(auto v : G[u]){
        if(v == fa)
            continue;
        lo = max(lower[v] - 1, lo);
        up = min(upper[v] + 1, up);
    }
    if(odd[u] == 1){
        if(lo % 2 == 0)
            lo++;
        if(up % 2 == 0)
            up--;
    }
    if(odd[u] == 0){
        if(lo % 2)
            lo++;
        if(up % 2)
            up--;
    }
    //cout << u << " " << lo << " " << up << endl;
    if(p[u] == -1){
        if(lo > up)
            return false;
        lower[u] = lo;
        upper[u] = up;
    }else{
        if(p[u] < lo or p[u] > up)
            return false;
        lower[u] = p[u];
        upper[u] = p[u];
    }
    return true;
}

void dfs1(int u, int fa, int val){
    if(p[u] != -1){
        for(auto v : G[u]){
            if(v == fa)
                continue;
            dfs1(v, u, p[u]);
        }
        return;
    }    
    vector<int> cand = {val + 1, val - 1};
    for(int i = 0;i < 2;i++){
        if(cand[i] >= lower[u] and cand[i] <= upper[u]){
            p[u] = cand[i];
            break;
        }
    }
    for(auto v : G[u]){
        if(v == fa)
            continue;
        dfs1(v, u, p[u]);
    }
}

