bool bfs(){
	queue < pair < pii , int > > que;
	que.push(MP(MP(root, -1), num[root]%2));
	while(!que.empty()){
		int u = que.front().FI.FI;
		int p = que.front().FI.SE;
		int bi = que.front().SE;
		que.pop();
		lst.PB(u);
		if(num[u] != -1 && num[u] % 2 != bi) return false;
		for(int v : G[u]){
			if(v == p) continue;
			que.push(MP(MP(v, u), 1 - bi));
		}
	}
	return true;
}

bool vis[N + 5];

void getRange(){
	FORD(i,lst.size()){
		int u = lst[i];
		vis[u] = true;
		if(rang[u].FI > rang[u].SE || (num[u] != -1 && (rang[u].FI > num[u] || rang[u].SE < num[u]))){
			flag = false;
			return;
		}
		if(num[u] != -1){
			rang[u] = MP(num[u], num[u]);
		}
		for(int v : G[u]){
			if(!vis[v]){
				rang[v] = MP(max(rang[v].FI, rang[u].FI-1), min(rang[v].SE, rang[u].SE+1));
			}
		}
	}
}

void bfs2(){
	queue < pair < pii , int > > que;
	que.push(MP(MP(root, -1), num[root]-1));
	while(!que.empty()){
		int u = que.front().FI.FI;
		int p = que.front().FI.SE;
		int val = que.front().SE;
		que.pop();
		if(val + 1 <= rang[u].SE) num[u] = val + 1;
		else num[u] = val - 1;
		for(int v : G[u]){
			if(v == p) continue;
			que.push(MP(MP(v, u), num[u]));
		}
	}
	FOR(i,n){
		if(num[i] > rang[i].SE || num[i] < rang[i].FI){
			flag = false;
			return;
		}
	}
}

void process(){
	if(!bfs()){
		flag = false;
		return;
	}
	rang[root] = MP(num[root], num[root]);
