			return;
		}
		if(rang[i].FI > rang[i].SE){
			flag = false;
			return;
		}
	}
	bfs2();
}

void reset(){
	memset(num,-1,sizeof num);
	memset(vis,0,sizeof vis);
	FOR(i,N+3) rang[i] = MP(-INF,INF);
	flag = true;
}

