void check(int x,int p){
	if(ver[x]!=-INF) L[x]=R[x]=ver[x];
	for(int i=0;i<nei[x].size();i++){
		int to=nei[x][i];
		if(to==p) continue;
		check(to,x);
		if(L[to]!=-1){
			if(L[x]==-1){
				L[x]=L[to]-1;
				R[x]=R[to]+1;
			}else{
				L[x]=max(L[x],L[to]-1);
				R[x]=min(R[x],R[to]+1);
			}
		}
	}
	if(L[x]>R[x]) ok=false;
}

void make(int x,int p){
	if(p==-1){
		if(ver[x]==-INF) ver[x]=L[x];
	}
	for(int i=0;i<nei[x].size();i++){
		int to=nei[x][i];
		if(to==p) continue;
		if(ver[to]==-INF){
			if(L[to]<=ver[x]-1&&ver[x]-1<=R[to]) ver[to]=ver[x]-1;
			else ver[to]=ver[x+1];
		}
		make(to,x);
	}
}

