inline void addedge(int u,int v){
	Next[++tot]=Head[u],Head[u]=tot,Adj[tot]=v;
	Next[++tot]=Head[v],Head[v]=tot,Adj[tot]=u;
}
int L[N],R[N];
bool flag,p[N];
inline void check(int x,int f,bool t){
	p[x]=t;
	if (L[x]==R[x]) {
		if ((L[x]&1)!=t) {
			flag=false;
			return;
		}
	}
	for (int e=Head[x];e;e=Next[e])
		if (Adj[e]!=f) check(Adj[e],x,t^1);
}
inline int Min(int a,int b){
	return a<b?a:b;
}
inline int Max(int a,int b){
	return a>b?a:b;
}
inline void dfs(int x,int f){
	for (int e=Head[x];e;e=Next[e])
		if (Adj[e]!=f){
			dfs(Adj[e],x);
			L[x]=Max(L[Adj[e]]-1,L[x]);
			R[x]=Min(R[Adj[e]]+1,R[x]);
		}
}
inline void dfs2(int x,int f){
	if (f){
		L[x]=Max(L[f]-1,L[x]);
		R[x]=Min(R[f]+1,R[x]);
		if (L[x]>R[x]){
			puts("No");
			exit(0);
		}
		if ((L[x]&1)!=p[x]&&(R[x]&1)!=p[x]&&(L[x]==R[x])) {
			puts("No");
			exit(0);
		}
		return;
	}
	for (int e=Head[x];e;e=Next[e])
		if (Adj[e]!=f)
			dfs2(Adj[e],x);
}
inline void getans(int x,int f,int lst){
	if (L[x]<=lst-1) printf ("%d\n",--lst);
	else printf ("%d\n",++lst);
	for (int e=Head[x];e;e=Next[e])
		if (Adj[e]!=f) getans(Adj[e],x,lst);
}
