int ans[N];
bool ok;
void dfs1(int u, int p) {
  for (int i = 0; i < edges[u].size(); ++i) {
    int v = edges[u][i];
    if (v==p) continue;
    dfs1(v, u);
    L[u] = max(L[u], L[v]-1);
    R[u] = min(R[u], R[v]+1);
    if (odd[v] >= 0) {
      if (odd[u] < 0) odd[u] = !odd[v];
      else if (odd[u] != !odd[v]) {
        ok = false;
        return ;
      }
    }
  }
}
void dfs2(int u, int p) {
  if (p != 0) {
    L[u] = max(L[u], L[p]-1);
    R[u] = min(R[u], R[p]+1);
    if (odd[u] < 0) odd[u] = !odd[p];
    else if (odd[u] != !odd[p]) {
      ok = false;
      return ;
    }
  }
  if (L[u] > R[u] || (L[u]==R[u] && (L[u]%2!=odd[u]))) {
    ok = false;
    return ;
  }
  for (int i = 0; i < edges[u].size(); ++i) {
    int v = edges[u][i];
    if (v != p) {
      dfs2(v, u);
    }
  }
}
void dfsans(int u, int p) {
  if (!p) {
    ans[u] = L[u];
  } else {
    ans[u] = ans[p]-1;
    if (ans[u] < L[u]) {
      ans[u] += 2;
    }
  }
  for (int i =0; i < edges[u].size(); ++i) {
    int v = edges[u][i];
    if (v != p) {
      dfsans(v, u);
    }
  }
}
