  }
  scanf("%d", &k);
  for (int i = 1; i <= n; ++i) {
    L[i] = -inf;
    R[i] = inf;
    odd[i] = -1;
  }
  for (int i = 1; i <= k; ++i) {
    int v,p;
    scanf("%d%d", &v, &p);
    L[v] = p;
    R[v] = p;
    odd[v] = (p%2);
  }
  if (k==0) {
    L[1] = 0, R[1] = 0;
    odd[1] = 0;
  }
  ok = true;
  dfs1(1, 0);
  if (!ok) {
    cout<<"No"<<endl;
    return 0;
  }
  dfs2(1, 0);
  if (!ok) {
    cout<<"No"<<endl;
    return 0;
  }
  dfsans(1, 0);
  if (!ok) {
    cout<<"No"<<endl;
  } else {
    cout<<"Yes"<<endl;
    for (int i = 1; i <= n; ++i) {
      printf("%d\n", ans[i]);
    }
  }
  return 0;
}

