					even=true;
				}else{
					odd=true;
				}

				if(mi==-10000000){
					mi=lb[G[x][i]]-1;
					ma=ub[G[x][i]]+1;
				}else{
					mi=max(lb[G[x][i]]-1,mi);
					ma=min(ub[G[x][i]]+1,ma);
				}
			}
		}
	}
	if(mi>ma)return false;
	//cout<<x<<" "<<ub[x]<<" "<<lb[x]<<"aa"<<mi<<" "<<ma<<endl;
	if(even==true&&odd==true)return false;
	if(ub[x]==-10000000){
