	if(mi==-10000000){
		return true;
	}
	if(mi<=lb[x]&&ub[x]<=ma){
		if(even==true&&lb[x]%2==1){
			return true;
		}
		if(odd==true &&lb[x]%2==0){
			return true;
		}
		if(even==false&&odd==false){
			return true;
		}
		return false;
	}else{
		return false;
	}
}

