#define iter(i, n) for (int i = 1; i <= n; ++i)

typedef pair<int, int> pii;

#define fi first
#define se second

const int inf = 1e9;

#define NR 101000

vector<int> e[NR];
pii f[NR];
int root, dep[NR], a[NR], n, K;

pii dfs(int x, int fa) {
	if (a[x] != -1 && abs(a[x] - a[root]) % 2 != dep[x] % 2) {
		return pii(0, -1);
	}

	int l = -inf, r = inf;

	if (a[x] != -1) l = r = a[x];

	for (int v : e[x]) if (v != fa) {
		dep[v] = dep[x] + 1;
		pii tmp = dfs(v, x);
		if (tmp.fi > tmp.se) return pii(0, -1);
		l = max(l, tmp.fi - 1);
		r = min(r, tmp.se + 1);
	}

	return f[x] = pii(l, r);
}

void dfs1(int x, int fa, int t) {
	if (a[x] == -1) {
		if (f[x].fi <= t - 1 && t - 1 <= f[x].se) a[x] = t - 1;
		else a[x] = t + 1;
	}
	for (int v : e[x]) if (v != fa) dfs1(v, x, a[x]);
}

