	vector<int>l(N,-MOD);
	vector<int>r(N,MOD);
	cin >> K;
	for (int i = 0; i < K; i++) {
		cin >> L >> M;
		L--;
		l[L] = M;
		r[L] = M;
	}
	vector<int>depth(N,MOD);
	Calculate_Depth(edge, depth, L);
	TopDown(depth, l, r, edge, L);
	BottomUp(depth, l, r, edge, L);
	for (int i = 0; i < N; i++) {
		if (l[i] > r[i]) {
			cout << "No\n";
			return 0;
		}
	}
	cout << "Yes\n";
	for (auto i : l)cout << i << endl;
	return 0;
}

