  }
  scanf("%d", &k);
  for(int i = 0; i < k; ++i) {
    int a, b;
    scanf("%d %d", &a, &b);
    num[a] = b;
  }

  // step 1
  for(int i = 1; i <= n; ++i) {
    if( num[i] != -(1<<28) ) {
