			_l = max(_l, l[y] - 1);
			_r = min(_r, r[y] + 1);
		}
	}
	if (f[x] != -1){
		if (_l <= f[x] && _r >= f[x] && (f[x] % 2 == _op % 2 || _op == 0)){
			l[x] = f[x], r[x] = f[x], op[x] = 2 - (f[x] % 2);
