vector<ll> par;
void makeRootedTree(vector<ll> &parentVector, ll root) {
    assert(root < (ll)parentVector.size());
    parentVector[root] = -1;
    queue<ll> que;
    que.push(root);
    while (!que.empty()) {
        ll node = que.front();
        que.pop();
        REP (i, 0, G[node].size()) {
            edge e = G[node][i];
            if (e.to != parentVector[node]) {
                parentVector[e.to] = node;
                que.push(e.to);
            }
        }
    }
}

ll dmin[1000000];
ll dmax[1000000];
ll deven[1000000];
bool ok;

void leafToRoot(vector<ll> &parentVector, ll root) {
    queue<ll> que;
    vector<ll> used(V);
    fill(used.begin(), used.end(), 0);
    REP(i, 0, V) {
        if (i != root && G[i].size() == 1) {
            que.push(i);
            used[i] = 1;
        }
    }
    while (!que.empty()) {
        ll node = que.front();
        que.pop();
        if (node == root) {
            break;
        }
        ll parent = parentVector[node];
        used[parent]++;

        //ここに書く
        if (deven[node] != -1) {
            if (deven[node] == deven[parent]) {
                ok = false;
                // cout << "aaa" << endl;
                break;
            }
            if (deven[parent] != -1) {
                if (dmax[parent] < dmin[node] - 1 || dmax[node] + 1 < dmin[parent]) {
                    ok = false;
                    // cout << "bbb" << endl;
                    break;
                }
            }
            deven[parent] = 1 - deven[node];
            dmin[parent] = max(dmin[parent], dmin[node] - 1);
            if ((deven[parent] == 1 && dmin[parent] % 2 == 1) ||
                (deven[parent] == 0 && dmin[parent] % 2 == 0)) {
                dmin[parent]++;
            }
            dmax[parent] = min(dmax[parent], dmax[node] + 1);
            if ((deven[parent] == 1 && dmax[parent] % 2 == 1) ||
                (deven[parent] == 0 && dmax[parent] % 2 == 0)) {
                dmax[parent]--;
            }
            if (dmin[parent] > dmax[parent]) {
                ok = false;
                // cout << "ccc" << endl;
                break;
            }
        }

        if ((parent == root && used[parent] == (ll)G[parent].size()) ||
            (parent != root && used[parent] == (ll)G[parent].size() - 1)) {
            que.push(parent);
        }
    }
}

