        v--;
        dmin[v] = p;
        dmax[v] = p;
        if (p & 1) {
            deven[v] = 0;
        } else {
            deven[v] = 1;
        }
    }
    leafToRoot(par, 0);
    if (!ok) {
        cout << "No" << endl;
        return 0;
    } else {
        cout << "Yes" << endl;
        ll ans[N];
        queue<ll> que;
        que.push(0);
        ans[0] = dmin[0];
        if ((deven[0] == 1 && dmin[0] % 2 == 1) ||
            (deven[0] == 0 && dmin[0] % 2 == 0)) {
            ans[0]++;
        }
        while(!que.empty()) {
            ll node = que.front();
            que.pop();
            REP(i, 0, G[node].size()) {
                edge e = G[node][i];
                if (e.to != par[node]) {
                    if (dmin[e.to] <= ans[node] - 1 && ans[node] - 1 <= dmax[e.to]) {
                        ans[e.to] = ans[node] - 1;
                    } else {
                        ans[e.to] = ans[node] + 1;
                    }
                    que.push(e.to);
                }
