bool dfs(int par, int curr, int mm_out[3])
{
    int siz=(int)g[curr].size();

    int mmall[3]={0,INF,-1};
    int i;
    for(i=0; i<siz; i++) {
        int next=g[curr][i];
        if(par==next) continue;

        int mm[3]={0,INF,-1};
        if(!dfs(curr, next, mm)) {
            return false;
        }
        mmall[0]=MAX(mmall[0],mm[0]);
        mmall[1]=MIN(mmall[1],mm[1]);
        if(mm[2]>=0) {
            if(mmall[2]>=0 && mmall[2]!=mm[2]) {
                return false;
            }
            if(mmall[2]<0) mmall[2]=mm[2];
        }
    }

    if(pp[curr]>=0) {
        if(pp[curr]<mmall[0] || pp[curr]>mmall[1]) {
            return false;
        }
        if(mmall[2]>=0 && pp[curr]%2!=mmall[2]) {
            return false;
        }
        mmall[0]=mmall[1]=pp[curr];
        mmall[2]=pp[curr]%2;
    }

    minp[curr]=mmall[0];
    maxp[curr]=mmall[1];
    flag[curr]=mmall[2];

    mmall[0]--;
    mmall[1]++;
    mm_out[0]=MAX(mm_out[0],mmall[0]);
    mm_out[1]=MIN(mm_out[1],mmall[1]);
    mm_out[2]=(mmall[2]<0? -1: 1-mmall[2]);

    return true;
}


bool dfs2(int par, int curr, int parval)
{
    int siz=(int)g[curr].size();

    if(pp[curr]>=0) {
        if(pp[curr]<minp[curr] || pp[curr]>maxp[curr]) {
            return false;
        }
        if(parval>=0 && (abs(pp[curr]-parval)!=1)) {
            return false;
        }
    }
    else if(parval>=0) {
        int t;
        for(t=0; t<2; t++) {
            pp[curr]=(t==0? parval-1: parval+1);
            if(pp[curr]>=minp[curr] && pp[curr]<=maxp[curr]) {
                break;
            }
        }
        if(t==2) {
            return false;
        }
    }
    else {
        if(minp[curr]>maxp[curr]) return false;
        pp[curr]=minp[curr];
    }

    int i;
    for(i=0; i<siz; i++) {
        int next=g[curr][i];
        if(par==next) continue;

        if(!dfs2(curr, next, pp[curr])) {
            return false;
        }
    }

    return true;
}

