  }

  for (int i=0; i<=N; i++) D[i] = INF;
  D[0] = 0;

  priority_queue< P, vector<P>, greater<P> > q;
  q.push(P(0, 0));

  bool ok = true;

  while (!q.empty()) {
    int r = q.top().first, s = q.top().second;
    q.pop();
    if (D[s] < r) continue;

    for (auto p2 : G[s]) {
