const int mod = (int)1e9 + 7;

vector<vector<pii>> r;

const int INF = 1<<28;
VI dijkstra(int s){
	priority_queue< pii, vector<pii>, greater<pii> > que;
	VI d(sz(r), INF);
	d[s] = 0; 
	que.push(pii(0, s));
	while(!que.empty()){
		int cost, v; tie(cost, v) = que.top();
		que.pop();
		if(d[v] < cost) continue;
		for(const auto& rp : r[v]){ 
			ll rct, rto; tie(rto, rct) = rp;
			if(d[rto] > d[v] + rct){
				d[rto] = d[v] + rct;
				que.push(pii(d[rto], rto));
			}
		}
	}
	return d;
}




