//Appropriately Changed
inline void add_edge(G &graph,int from,int to){ 
	graph[from].push_back({to});
	graph[to].push_back({from});
}

vector<int> node;

bool check(const auto &graph,int v,int p,int d){
	if(node[v]!=-1 and node[v]%2!=d) return false;
	bool ret=true;
	for(auto &e:graph[v]){
		if(e.to==p) continue;
		ret&=check(graph,e.to,v,d^1);
	}
	return ret;
}

using pii=pair<int,int>;
vector<pii> ret;

pii dfs(const auto &graph,int v,int p){
	if(node[v]!=-1){
		chmax(ret[v].first,node[v]);
		chmin(ret[v].second,node[v]);
	}

	for(auto &e:graph[v]){
		if(e.to==p) continue;
		pii tmp=dfs(graph,e.to,v);
		chmax(ret[v].first,tmp.first-1);
		chmin(ret[v].second,tmp.second+1);
	}

	return ret[v];
}

void rest(const auto &graph,int v,int p,int d){
	if(node[v]==-1){		
		if(p==-1){
			node[v]=ret[v].first;
			if(node[v]%2!=d) node[v]++;
		}else{
			if(ret[v].first<= node[p]-1 and node[p]-1<= ret[v].second) node[v]=node[p]-1;
			if(ret[v].first<= node[p]+1 and node[p]+1<= ret[v].second) node[v]=node[p]+1;
		}
	}

	for(auto &e:graph[v]){
		if(e.to==p) continue;
		rest(graph,e.to,v,d^1);
	}
	return;
}



