    for (int i=1;i<=n;i++)
        if ( v[i] ) root = i;
    //printf("root = %d\n",root);
    if ( root == 0 ) v[root=1] = 1;
    dfs1( root , 0 );
    dfs2( root , 0 , v[root] );
    dfs3( root , 0 );
    dfs4( root , 0 );
    if ( check() )
    {
        puts("Yes");
        for (int i=1;i<=n;i++)
            printf("%d\n",v[i]);
    }
    else puts("No");
    return 0;
}

