P dfs(int cur, int pre) {
    int mn = (p[cur] != -1 ? p[cur] : -INF), mx = (p[cur] != -1 ? p[cur] : INF),
        parity = (p[cur] != -1 ? p[cur] % 2 : -1);
    for (int to : G[cur]) {
        if (to == pre) continue;
        auto pp = dfs(to, cur);
        mn = max(mn, pp.first.first - 1);
        mx = min(mx, pp.first.second + 1);
        if (mx < mn) {
            cout << "No" << endl;
            exit(0);
        }
        if (parity != -1 && parity == pp.second) {
            cout << "No" << endl;
            exit(0);
        }
        if (pp.second != -1) parity = !pp.second;
    }
    return dp[cur] = P(pair<int, int>(mn, mx), parity);
}

