void dfss(int cur, int pre) {
    if (pre != -1) {
        if (dp[cur].first.first <= ans[pre] - 1 &&
            ans[pre] - 1 <= dp[cur].first.second) {
            ans[cur] = ans[pre] - 1;
        } else {
            ans[cur] = ans[pre] + 1;
        }
    }
    for (int to : G[cur]) {
        if (to == pre) continue;
        dfss(to, cur);
    }
}

