		a.r = b.r+1;
		return true;
	}
	if ((a.l + b.l-1) % 2 != 0) ok = false;
	range na, nb;
	na = {max(a.l, b.l-1), min(a.r, b.r+1)};
	a = na;
	return true;
}

void dfs(int u) {
	vis[u] = 1;
	for (auto v : g[u]) {
		if (!vis[v]) {
			dfs(v);
			if (a[v].l != -INT_MAX) ok &= mergerange(a[u], a[v]);
		}
	}
}

void getres(int u) {
	vis[u] = 1;
	for (auto v : g[u]) {
		if (!vis[v]) {
			if (h[u]-1 >= a[v].l) {
				h[v] = h[u]-1;
			}
			else {
				h[v] = h[u]+1;
			}
			getres(v);
		}
	}
}

