using namespace std;

typedef long long ll;
typedef pair<int, int> pii;
typedef long double ld;

const int inf = 1e9;

vector<int> lf, rg;
vector<char> any;

int n;
vector<vector<int> > g;
vector<int> val;

bool lay(int v, int x)
{
	if ((x - lf[v]) % 2) {
		return false;
	}
	return x >= lf[v] && x <= rg[v];
}

void dfs(int v, int p)
{
	if (sz(g[v]) == 1 && g[v][0] == p) {
		if (val[v] == -1) {
			any[v] = true;
		} else {
			any[v] = false;
			lf[v] = rg[v] = val[v];
		}
		return;
	}
	vector<int> sons;
	for (int to : g[v]) {
		if (to != p) {
			dfs(to, v);
			if (!any[to]) {
				sons.pb(to);
			}
		}
	}
	if (sons.empty()) {
		if (val[v] == -1) {
			any[v] = true;
		} else {
			any[v] = false;
			lf[v] = rg[v] = val[v];
		}
		return;
	}
	any[v] = false;
	lf[v] = inf;
	rg[v] = -inf;
	for (int son : sons) {
		if (lf[son] == inf) {
			return;
		}
	}
	for (int i = 1; i < sz(sons); ++i) {
		if ((lf[sons[i]] - lf[sons[0]]) % 2) {
			return;
		}
	}
	if (val[v] != -1 && (val[v] - lf[sons[0]]) % 2 == 0) {
		return;
	}
	lf[v] = lf[sons[0]] - 1;
	rg[v] = rg[sons[0]] + 1;
	for (int i = 1; i < sz(sons); ++i) {
		lf[v] = max(lf[v], lf[sons[i]] - 1);
		rg[v] = min(rg[v], rg[sons[i]] + 1);
	}
	if (val[v] != -1) {
		lf[v] = max(lf[v], val[v]);
		rg[v] = min(rg[v], val[v]);
	}
	if (lf[v] > rg[v]) {
		lf[v] = inf;
		rg[v] = -inf;
	}
}

vector<int> ans;

void dfs_solve(int v, int p, int x)
{
	ans[v] = x;
	for (int to : g[v]) {
		if (to != p) {
			if (lay(to, x - 1)) {
				dfs_solve(to, v, x - 1);
			} else {
				dfs_solve(to, v, x + 1);
			}
		}
	}
}

int main()
{

	ios_base::sync_with_stdio(false);
	cin.tie(0);

