	any.resize(n);

	while (q--) {
		int v;
		cin >> v;
		--v;
		cin >> val[v];
	}

	dfs(0, -1);

	if (lf[0] == inf) {
		cout << "No\n";
		return 0;
	}

	cout << "Yes\n";
	ans.resize(n);

	dfs_solve(0, -1, lf[0]);
	for (int i = 0; i < n; ++i) {
		cout << ans[i] << "\n";
	}

}

