constexpr int INF = 1e9 + 7;

void dfs(int u, int fa = -1) {
    par[u] = fa;
    L[u] = -INF - 1, R[u] = INF + 1;
    for (int to : g[u]) {
        if (to == fa)
            continue;
        dfs(to, u);
        if (known_parity[to][0])
            known_parity[u][1] = 1;
        if (known_parity[to][1])
            known_parity[u][0] = 1;
        L[u] = max(L[u], L[to] - 1);
        R[u] = min(R[u], R[to] + 1);
    }
    if (val[u] != -1) {
        L[u] = max(L[u], val[u]);
        R[u] = min(R[u], val[u]);
        known_parity[u][val[u] % 2] = 1;
    }
    if (known_parity[u][0] && known_parity[u][1]) {
        flag = true;
    }
    if (L[u] > R[u]) {
        flag = true;
    }
    order.push_back(u);
}

int solve_val(int u, int fa = -1) {
    if (fa == -1) {
        return L[u];
    }
    L[u] = max(L[u], val[fa] - 1);
    R[u] = min(R[u], val[fa] + 1);
