		}
	}
	return d[k][c]=1;
}

void trace(int c, int k) {
	res[k]=c;
	for(int i=0;i<child[k].size();i++)  {
		if(f(c-1,child[k][i])) {
			trace(c-1,child[k][i]);
		} else {
			trace(c+1,child[k][i]);
		}
	}
}

