    }
    vector<int> par(n, -2);
    vector<vector<int>> chi(n);
    function<void(int,int)> f = [&](int x, int y){
        par[x] = y;
        for(auto& ed : edges[x]){
            if(par[ed] == -2)
                f(ed, x);
            if(par[ed] == x)
                chi[x].push_back(ed);
        }
    };
    f(0, -1);
    vector<i64> mi(n, -MOD);
    vector<i64> ma(n, MOD);
    int q;
    cin >> q;
    for(int i = 0; i < q; ++i){
        int a, b;
        cin >> a >> b;
        mi[--a] = b;
        ma[a] = b;
    }
    vector<int> out(n);
    queue<int> que;
    for(int i = 0; i < n; ++i)
        if(!(out[i] = chi[i].size()))
            que.emplace(i);

    auto g = [&]{

        while(!que.empty()){
            int t = que.front();
            que.pop();
            if(par[t] != -1 && !(--out[par[t]]))
                que.emplace(par[t]);

            for(auto& c : chi[t]){
                mi[t] = max(mi[t], mi[c] - 1);
                ma[t] = min(ma[t], ma[c] + 1);
                if(mi[t] % 2 == mi[c] % 2)
                    ++mi[t];
                if(ma[t] % 2 == ma[c] % 2)
                    --ma[t];
            }
            if(mi[t] > ma[t]){
                cout << "No" << endl;
                return false;
            }
        }

        vector<i64> ans(n, INF);
        ans[0] = mi[0];
        function<void(int)> g = [&](int x){
            if(x){
                ma[x] = min(ma[x], ans[par[x]] + 1);
                mi[x] = max(ma[x], ans[par[x]] - 1);
                if(mi[x] % 2 == mi[par[x]] % 2)
                    ++mi[x];
                if(ma[x] % 2 == ma[par[x]] % 2)
                    --ma[x];
                ans[x] = ma[x];
            }
            for(auto& c : chi[x])
                g(c);
        };
        g(0);
        // [mi[i], ma[i]]の範囲内なら子が条件を満たすように置ける
        for(int i = 0; i < n; ++i)
            if(mi[i] > ma[i]){
                cout << "No" << endl;
                return false;
            }

        cout << "Yes" << endl;
        for(int i = 0; i < n; ++i)
            cout << ans[i] << endl;
    };
    g();
}

