bool solve(int parent, int now) {
  int m = -inf, M = inf;
  if (mM[now].first == mM[now].second) {
    return true;
  }
  for (int i = 0; i < G[now].size(); i++) {
    if (G[now][i] != parent) {
      int child = G[now][i];
      if (solve(now, child)) {
	if (m != -inf && (mM[child].first - 1 > M || mM[child].second + 1 < m || (mM[child].first + 1) % 2 != m % 2)){
	  return false;
	}
	else {
	  m = max(m, mM[child].first - 1);
	  M = min(M, mM[child].second + 1);
	}
      }
      else {
	return false;
      }
    }
  }
  mM[now].first = m;
  mM[now].second = M;
  return true;
}

void answer(int parent, int now, int parent_value) {
  if (parent == -1) {
    value[now] = mM[now].first;
  }
  else {
    if (parent_value + 1 >= mM[now].first && parent_value + 1 <= mM[now].second) {
      value[now] = parent_value + 1;
    }
    else {
      value[now] = parent_value - 1;
    }
  }
  for (int i = 0; i < G[now].size(); i++) {
    if (G[now][i] != parent) {
      int child = G[now][i];
      answer(now, child, value[now]);
    }
  }
  return;
}


