inline bool okay( int now , int prt , int dep ){
  if( st[ now ] ){
    if( type[ dep ] && type[ dep ] - 1 != clr[ now ] % 2 )
      return false;
    type[ dep ] = clr[ now ] % 2 + 1;
  }
