        rb[ son ] = min( rb[ son ] , rb[ tn ] + 1 );
      }else{
        got[ son ] = true;
        Q.push( son );
        lb[ son ] = lb[ tn ] - 1;
        rb[ son ] = rb[ tn ] + 1;
      }
    }
  }
  for( int i = 1 ; i <= n ; i ++ )
    if( lb[ i ] > rb[ i ] ){
