	bool flag = 0 ;
	int L = -1e9, R = 1e9 ;
	for (int i = 0; i < G[v].size(); i ++) {
		int to = G[v][i] ;
		if (to == fa) continue ;
		flag = 1 ;
		dfs (to, v) ;
		if (l[to] <= -1e9 || r[to] >= 1e9) continue ;
		if (L <= -1e9 || R >= 1e9) L = l[to] - 1, R = r[to] + 1 ;
		else {
			if (L % 2 != (l[to] - 1) % 2) find_ans = 0 ;
			L = max (L, l[to] - 1); R = min (R, r[to] + 1) ;
		}
	}
	if (!flag) {
		if (ans[v] == -1) l[v] = 1e-9, r[v] = 1e9 ;
		else l[v] = r[v] = ans[v] ;
	} else {
		if (L > R) find_ans = 0 ;
		l[v] = L; r[v] = R ;
		if (ans[v] != -1 && (ans[v] % 2 != l[v] % 2 || ans[v] < l[v] || ans[v] > r[v])) find_ans = 0 ;
		if (ans[v] != -1) l[v] = r[v] = ans[v] ;
	}
