  int maxi=-mod,mini=mod;
  set<int> st;
  lol(i,v[e].size()){
    if(v[e][i]==from)continue;
    DFS(v[e][i],e);
    int to=v[e][i];
    maxi=max(maxi,a[to]);
    mini=min(mini,b[to]);
    if(a[to]!=-mod)st.insert(D(a[v[e][i]],2));
  }
  maxi--,mini++;
  maxi=max(maxi,-mod),mini=min(mini,mod);
  if(st.size()>1)maxi=mod,mini=-mod;
  if(p[e]!=mod){
    if(!(maxi<=p[e]&&p[e]<=mini))maxi=mod,mini=-mod;
    else maxi=p[e],mini=p[e];
  }
  a[e]=maxi,b[e]=mini;
}

int ans[N];
void BFS(int e,int from,int cost){
  ans[e]=cost;
  lol(i,v[e].size()){
    if(v[e][i]==from)continue;
    int newcost,to=v[e][i];
    if(a[to]<=cost+1&&cost+1<=b[to])newcost=cost+1;
    if(a[to]<=cost-1&&cost-1<=b[to])newcost=cost-1;
    BFS(to,e,newcost);
  }
}

