      vi &nbru = nbrs[ui];
      for (vi::iterator vit = nbru.begin(); vit != nbru.end(); vit++) {
	if (*vit == uprt) continue;

	int &vi = *vit;
	Node &ndv = nds[vi];
	if (ndv.p >= 0 &&
	    (ndv.p != vp || ndv.minv > vmaxv || ndv.maxv < vminv)) {
	  puts("No");
	  return 0;
	}

	if (ndv.minv < vminv || ndv.maxv > vmaxv) {
	  ndv.minv = max(ndv.minv, vminv);
	  ndv.maxv = min(ndv.maxv, vmaxv);
	  ndv.p = vp;
	  if (ndv.v >= INF) q.push(pii(vi, ui));
	}
      }
    }
  }

  puts("Yes");

  //for (int i = 0; i < n; i++) printf("%d: ", i), nds[i].print();
  for (int i = 0; i < n; i++) printf("%d\n", nds[i].minv);

  return 0;
}

#include <bits/stdc++.h>
using namespace std;

const int INF = 0x3f3f3f3f;

vector <int> from[100010];
int L[100010], R[100010];
int id[100010];
bool ans;

void solve(int u = 0, int p = -1){
	L[u] = -INF - 1, R[u] = INF + 1;
	if (id[u] != -1) L[u] = R[u] = id[u];
	for (int i = 0; i < from[u].size(); i++){
		int v = from[u][i];
		if (v == p) continue;
		solve(v, u);
		if (L[v] < -INF / 2) continue;
		if (L[u] < -INF / 2) L[u] = L[v] - 1, R[u] = R[v] + 1;
		else {
			if (abs(L[v]) % 2 == abs(L[u]) % 2){
				ans = 0;
				return ;
			}
			L[u] = max(L[u], L[v] - 1);
			R[u] = min(R[u], R[v] + 1);
		}
	}
	if (L[u] > R[u]) ans = 0;
}

void make(int v = 0, int p = -1){
	if (v == 0 && id[v] == -1) id[v] = L[v];
	for (int i = 0; i < from[v].size(); i++){
		int to = from[v][i];
		if (to == p) continue;
		if (id[to] == -1){
			if (L[to] <= id[v] - 1 && id[v] - 1 <= R[to]) id[to] = id[v] - 1;
			else id[to] = id[v] + 1;
		}
		make(to, v);
	}
}

