            if (guki[i]==now) {
                return false;
            }
        }
        ok&=dfs(i,x,(now==1?2:1));
    }
    return ok;
}
void solve(itn x,int par){
    for(auto&i:road[x]){
        if (i==par) {
            continue;
        }
        solve(i, x);
        chmax(sm[x], sm[i]-1);
        chmin(bg[x], bg[i]+1);
    }
}
void solve2(int x, int par, P info){
    chmax(sm[x], info.first);
    chmin(bg[x], info.second);
    info.first--;
    info.second++;
    innt zsm=-inf,zbg=inf;
    for(auto&i:road[x]){
        if (i==par) {
            continue;
        }
        chmax(zsm, sm[i]-2);
        chmin(zbg, bg[i]+2);
    }
    chmax(info.first, zsm);
    chmin(info.second, zbg);
    for(auto&i:road[x]){
        if (i==par) {
            continue;
        }
        solve2(i, x, info);
    }
}
void bye(int x, int par, int now){
    ans[x]=now;
    for(auto&i:road[x]){
        if (i==par) {
            continue;
        }
        if (sm[i]<=now+1&&now+1<=bg[i]) {
            bye(i, x, now+1);
        }else if(sm[i]<=now-1&&now-1<=bg[i]){
            bye(i, x, now-1);
        }else{
            No();
            exit(0);
        }
    }
}
