struct Node{
    vector<Node*> nodes;
    int mini = -M, maxi = M;
    bool even;
    void propagate(Node* from = nullptr){
        if(mini == -M && !from){ return; }
        auto size = maxi - mini;
        if(mini == -M){
            even = !from -> even;
            mini = from -> mini - 1;
            maxi = from -> maxi + 1;
        }else if(from){
            mini = max(mini, from -> mini - 1);
            maxi = min(maxi, from -> maxi + 1);
            if(even == from -> even || mini > maxi){
                cout << "No" <<endl;
                exit(0);
            }
        }

        if(from && size == maxi - mini){ return; }
        for(Node* n : nodes){
            n -> propagate(this);
        }
    }
    void set(int num){
        mini = maxi = num;
        even = !(num % 2);
    }
    void print(){
        cout << mini << endl;
    }
};

int main(){
