      if(num[v]>=0 and lst!=-1){
         if(abs(num[lst]-num[v])>d or abs(num[lst]-num[v])%2!=d%2){
            ok=false;
         }
      }
      if(num[v]>=0){
         for(auto u:G[v]) if(u!=p){
            par[u]=v;
            last[u]=v;
            dfs(u,v,v,1);
         }
      }else{
         for(auto u:G[v]) if(u!=p){
            par[u]=v;
            last[u]=lst;
            dfs(u,v,lst,d+1);
         }
      }
   };
   int root=-1;
   for(int i=0;i<N;i++) if(num[i]>=0) root=i;
   dfs(root,-1,-1,0);
   if(!ok){
      cout<<"No"<<endl;
      return 0;
   }

   vector<int> cand;
   for(int i=0;i<N;i++) if(i!=root and num[i]>=0) cand.push_back(i);

   for(int v:cand){
      int curnum=num[v];
      for(int u=par[v];u!=last[v];u=par[u]){
         if(curnum>num[last[v]]) curnum--;
         else if(curnum<num[last[v]]) curnum++;
         else curnum++;
         num[u]=curnum;
      }
   }

   function<void(int,int)> dfs2=[&](int v,int p)
   {
      if(num[v]<0) num[v]=num[p]+1;
      for(int u:G[v]) if(u!=p) dfs2(u,v);
   };

   dfs2(root,-1);
   cout<<"Yes"<<endl;
   for(int i=0;i<N;i++) cout<<num[i]<<endl;
   return 0;
}

