#include<bits/stdc++.h>
using namespace std;

#define SIZE 100005
#define INF 1000000000

vector<int> vec[SIZE];
int R[SIZE],L[SIZE];
int id[SIZE];
bool ans=true;
int N,K;
int a,b;

inline void solve(int v=0,int p=-1)
{
	L[v]=-INF-1,R[v]=INF+1;
	if(id[v]!=-1)	R[v]=L[v]=id[v];
	for(int i=0;i<vec[v].size();i++)
	{
		int to=vec[v][i];
		if(to==p)	continue;
		solve(to,v);
		if(L[to]<-INF/2)	continue;
		if(L[v]<-INF/2)
		{
			L[v]=L[to]-1;
			R[v]=R[to]+1;
		}
		else
		{
			if(abs(L[v])%2==abs(L[to])%2)
			{
				ans=false;
				return;
			}
			L[v]=max(L[v],L[to]-1);
			R[v]=min(R[v],R[to]+1);
		}
	}
	if(L[v]>R[v])	ans=false;
}

inline void make(int v=0,int p=-1)
{
	if(v==0&&id[v]==-1)	id[v]=L[v];
	for(int i=0;i<vec[v].size();i++)
	{
		int to=vec[v][i];
		if(to==p)	continue;
		if(id[to]==-1)
		{
			if(L[to]<=id[v]-1&&R[to]>=id[v]-1) id[to]=id[v]-1;
			else id[to]=id[v]+1;
		}
		make(to,v);
	}
}

