		vec[a].push_back(b);
		vec[b].push_back(a);
	}
	scanf("%d",&K);
	memset(id,-1,sizeof id);
	for(int i=0;i<K;i++)
	{
		scanf("%d %d",&a,&b);
		a--;
		id[a]=b;
	}
	solve();
	if(!ans)
	{
		puts("No");
	}
	else
	{
		make();
		puts("Yes");
		for(int i=0;i<N;i++)
			printf("%d\n",id[i]);
	}
	return 0;
}

