#define INF 1e9
using namespace std;
int l[50000],r[50000];
int id[50000];
vector<int>vec[50000];
bool ans;
void solve(int v=0,int p=-1){
	l[v]=-INF-1,r[v]=INF+1;
	if(id[v]!=-1)l[v]=r[v]=id[v];
	for(int i=0;i<vec[v].size();i++){
		int to=vec[v][i];
		if(to!=p)
		{
			solve(to,v);
			if(l[to]<-INF/2)continue;
			if(l[v]<-INF/2){
				l[v]=l[to]-1;
				r[v]=r[to]+1;
			}
			else{
				if(abs(l[to]%2)==0&&abs(l[v])%2==0)
				{
					ans=false;
					return;
				}
				l[v]=max(l[v],l[to]-1);
				r[v]=min(r[v],r[to]+1);
			}
		}	
	}
	if(l[v]>r[v])ans=false;
}
void make(int v=0,int p=-1){
	if(v==0&&id[v]==-1)id[v]=l[v];
	for(int i=0;i<vec[v].size();i++){
		int to=vec[v][i];
		if(to!=p){
			if(id[to]==-1){
				if(l[to]<=id[v]-1&&id[v]-1<=r[to])id[to]=id[v]-1;
				else id[to]=id[v]+1;
			}
			make(to,v);
		}
	}
}
