typedef pair<int,int> P;

const int MAX_N = 100000;
const int INF = 10000000;

template <typename T>
struct edge
{
    int from, to;
    T cost;
};

template<typename T>
struct Graph
{
    int n;
    vector<edge<T>> g[MAX_N + 4];
    T d[MAX_N + 4];
    int pre[MAX_N + 4];
    vector<int> tips;

    Graph(int n) : n(n) {};

    void add_edge(int from, int to, int cost){
        g[from].push_back(edge<T>{from, to, cost});
    }

    void Dijkstra(int s){
        typedef pair<T, int> PT;
        queue<PT> que;
        fill(d, d + n, INF);
        fill(pre, pre + n, -1);
        d[s] = 0;
        que.push(PT(0, s));
        while(que.size()){
            PT nowp = que.front();
            que.pop();
            int now = nowp.second;
            if(d[now] < nowp.first) continue;
            if((int)g[now].size() == 1) tips.push_back(now);
            for(edge<T> e : g[now]){
                if(d[e.to] > d[now] + e.cost){
                    d[e.to] = d[now] + e.cost;
                    que.push(PT(d[e.to], e.to));
                    pre[e.to] = e.from;
                }
            }
        }
    }
};

