    fill(lar, lar + n, INF);
    fill(les, les + n, -INF);
    int v[100002], p[100002];
    for(int i = 0; i < k; i++){
        cin >> v[i] >> p[i];
        v[i]--;
        lar[v[i]] = p[i];
        les[v[i]] = p[i];
    }
    P pa[100002];
    for(int i = 0; i < n; i++) pa[i] = P(g.d[i], i);
//    for(int i = 0; i < n; i++) cout << i << " " << lar[i] << " " << les[i] << endl;
//    cout << endl;
    sort(pa, pa + n, greater<P>());
    for(int i = 0; i < n - 1; i++){
        lar[g.pre[pa[i].second]] = min(lar[g.pre[pa[i].second]], lar[pa[i].second] + 1);
        les[g.pre[pa[i].second]] = max(les[g.pre[pa[i].second]], les[pa[i].second] - 1);
