void dfs(int v, int p)
{
	if (sz(g[v]) == 1 && g[v][0] == p) {
		if (val[v] == -1) {
			any[v] = true;
		} else {
			any[v] = false;
			s[v].insert(val[v]);
		}
		return;
	}
	vector<int> sons;
	for (int to : g[v]) {
		if (to != p) {
			dfs(to, v);
			if (!any[to]) {
				sons.pb(to);
			}
		}
	}
	if (sons.empty()) {
		if (val[v] == -1) {
			any[v] = true;
		} else {
			any[v] = false;
			s[v].insert(val[v]);
		}
		return;
	}
	any[v] = false;
	for (int x : s[sons[0]]) {
		if (val[v] != -1 && abs(val[v] - x) != 1) {
			continue;
		}
		bool can_1 = true;
		bool can1 = true;
		for (int i = 1; i < sz(sons); ++i) {
			int son = sons[i];
			bool a = (s[son].count(x + 2));
			bool b = (s[son].count(x));
			bool c = (s[son].count(x - 2));
			if (!a && !b) {
				can1 = false;
			}
			if (!b && !c) {
				can_1 = false;
			}
		}
		if (can_1 && (val[v] == -1 || val[v] == x - 1)) {
			s[v].insert(x - 1);
		}
		if (can1 && (val[v] == -1 || val[v] == x + 1)) {
			s[v].insert(x + 1);
		}
	}
}

vector<int> ans;

void dfs_solve(int v, int p, int x)
{
	ans[v] = x;
	for (int to : g[v]) {
		if (to != p) {
			if (any[to] || s[to].count(x - 1)) {
				dfs_solve(to, v, x - 1);
			} else {
				dfs_solve(to, v, x + 1);
			}
		}
	}
}

