            st=max(st,s[to].lef-1);
            ed=min(ed,s[to].rig+1);
        }
    }
    if(s[from].num!=INF){
        if(st<=s[from].num && s[from].num<=ed){
            s[from].lef=s[from].rig=s[from].num;
        }
        else{
