    int cur = 0;
    if(fa != 0){
        if(last % 2 == 0){
            a[c] = merge(a[c] , mp(last - 1 , last + 1));
            b[c] = mp(inf , -inf);
        } else {
            b[c] = merge(b[c] , mp(last - 1 , last + 1));
            a[c] = mp(inf , -inf);
        }
    }
    if(a[c].se > a[c].fi || (a[c].se == a[c].fi && a[c].se % 2 != 0)){
        cur = a[c].fi;if(cur % 2 == 0) ++cur;
    } else {
        cur = b[c].fi;if(cur % 2 != 0) ++cur;
    }
    ans[c] = cur;
    for(auto t : g[c]) if(t != fa) dfs2(t , c , cur);
}

