const ll INF = 1LL << 60;

vector<vector<int>> nxt;
vector<pair<ll, ll>> rng;

enum { HALT, OK, STOP };
int overlap(ll a, ll b, ll s, ll t) {
    if (s <= a && b <= t) return STOP;
    if (a <= s && s <= b) return OK;
    if (a <= t && t <= b) return OK;
    if (s <= a && a <= t) return OK;
    if (s <= b && b <= t) return OK;
    return HALT;
}

bool dfs(int v, int p) {
    ll l = rng[v].first, r = rng[v].second;
    for (int nv : nxt[v]) if (nv != p) {
        ll &nl = rng[nv].first, &nr = rng[nv].second;
        int res = overlap(l, r, nl, nr);
        if (res == HALT) return false;
        nl = max(l - 1, nl); nr = min(r + 1, nr);
        if (res == OK) dfs(nv, v);
    }
    return true;
}

void construct() {
    function<void(int, int)> dfs = [&](int v, int p) {
        ll num = rng[v].first;
        for (int nv : nxt[v]) if (nv != p) {
            ll &nl = rng[nv].first, &nr = rng[nv].second;
            if (nl == nr) continue;
            if (nl <= num + 1 && num + 1 <= nr) {
                nl = nr = num + 1;
            } else {
                nl = nr = num - 1;
            }
            dfs(nv, v);
        }
    };
    for (int i = 0; i < rng.size(); i++) {
        if (rng[i].first != rng[i].second) continue;
        return dfs(i, -1);
    }
}

