struct Graph
{
    Graph(const int v)
        : V{ v }, edge(v), rev_edge(v) {}
    void addEdge(const int from, const int to)
    {
        edge[from].push_back(to);
        rev_edge[to].push_back(from);
    }
    const int V;
    vector<vector<int>> edge;
    vector<vector<int>> rev_edge;
};

inline bool ng(const PP& p)
{
    return (not p.first) and (((((p.second.first + p.second.first) % 2) + 2) % 2 == 1) or p.second.first > p.second.second);
}
inline PP merge(const PP& p1, const PP& p2)
{
    if (p1.first) {
        return p2;
    } else if (p2.first) {
        return p1;
    } else {
        if ((((p1.second.first + p2.second.first) % 2) + 2) % 2 == 0) {
            return { false, { max(p1.second.first, p2.second.first), min(p1.second.second, p2.second.second) } };
        } else {
            return { false, { 0, -2 } };
        }
    }
}

inline PP next(const PP& p) { return (ng(p) ? PP{ false, { 0, -2 } } : PP{ p.first, { p.second.first - 1, p.second.second + 1 } }); }
void dfs(const Graph& g, const int s, vector<bool>& used, vector<PP>& cand, const vector<int>& node)
{
    used[s] = true;
    PP ans  = { true, { 0, 0 } };
    if (node[s] != -1) {
        ans = merge(ans, { false, { node[s], node[s] } });
    }
    for (const int to : g.edge[s]) {
        if (not used[to]) {
            dfs(g, to, used, cand, node);
            if (not cand[to].first) {
                ans = merge(ans, next(cand[to]));
                if (ng(ans)) {
                    ans = { false, { 0, -2 } };
                }
            }
        }
    }
    cand[s] = ans;
}

void dfs(const Graph& g, const int s, const int par, vector<bool>& used, const vector<PP>& cand, vector<int>& node)
{
    used[s]        = true;
    const auto tmp = merge(cand[s], { false, { par - 1, par + 1 } });
    node[s]        = tmp.second.first;
    for (const int to : g.edge[s]) {
        if (not used[to]) {
            dfs(g, to, node[s], used, cand, node);
        }
    }
}
