				chk[v] = true;
				range[v] = {range[u].fi - 1, range[u].se + 1};
				q.push(v);
			}else{
				pii res = merge({range[u].fi-1,range[u].se+1}, range[v]);
				if(res==make_pair(-1,-1)) cout << "No", exit(0);
				else range[v] = res;
			}
