	vector<ll> S;
	for (ll w : g[v]) {
		if (see[w] == 1) { continue; }
		if (dfs(w) == 0) { return 0; };

		if (inf[w] != -INF) { I.push_back(inf[w] - 1); }
		if (sup[w] != INF) { S.push_back(sup[w] + 1); }
	}

	if (num[v] != -1) {
		I.push_back(num[v]);
		S.push_back(num[v]);
	}

	rep(i, I.size()) {
		if (I[0] % 2 != I[i] % 2) { return 0; }
		inf[v] = max(inf[v], I[i]);
	}

	rep(i, S.size()) {
		if (S[0] % 2 != S[i] % 2) { return 0; }
		sup[v] = min(sup[v], S[i]);
	}

	if (inf[v] > sup[v]) { return 0; }

	return 1;

}

