		else if (st.count(1))parity[now] = 0;
		rec[now].first = mi;
		rec[now].second = ma;
	}
	else {
		if ((st.count(1) && parity[now] == 1) || (st.count(0) && parity[now] == 0))err();
		if (ma < num[now] || num[now] < mi)err();
		rec[now].first = num[now];
		rec[now].second = num[now];
	}
}

