		if (~odd[v]) {
			if (odd[v] == odd[u] || (l[v]  > r[v])) 
				puts("No"), exit(0);
		}
		else odd[v] = (odd[u] ^ 1);
		dfs2(v, u);
	}
}

void get(int u, int fa) {
	if (~fa) t[u] = t[fa] - 1;
	else t[u] = l[u];
	if ((t[u] - odd[u]) & 1) t[u]--;
	if (t[u] < l[u]) t[u] += 2;
	go(i, v, u) if (v != fa) get(v, u);
}

