void dfs1(int cur, int par) {
	if (P[cur] != INF)
		L[cur] = R[cur] = P[cur];
	else
		L[cur] = INF;

	for (int to : E[cur]) if (to != par) {
		dfs1(to, cur);

		if (L[to] == INF) {
			// 下が空
			continue;
		} else if (L[cur] == INF) {
			// こっちが空
			L[cur] = L[to] - 1;
			R[cur] = R[to] + 1;
		}
		else {
			// どっちもある
			ll LL = L[to] - 1;
			ll RR = R[to] + 1;

			// 偶奇判定
			if ((LL + L[cur]) % 2 != 0) {
				//printf("A[%d]\n", cur);
				ans = false;
				return;
			}

			// かぶってるか判定
			L[cur] = max(LL, L[cur]);
			R[cur] = min(RR, R[cur]);

			if (R[cur] < L[cur]) {
				//printf("B");
				ans = false;
				return;
			}
		}
	}
}
