    l[v]=lres,r[v]=rres;
    return make_pair(lres,rres);
}
void rdfs(int v,int pre,Graph& g,vector<int> &l,vector<int> &r,int ln,int rn){
    l[v]=max(l[v],ln);
    r[v]=min(r[v],rn);
    if(r[v]<l[v]){
        throw "No";
    }
    for(int i=0;i<g[v].size();i++){
        if(g[v][i]!=pre){
            rdfs(g[v][i],v,g,l,r,l[v]-1,r[v]+1);
        }
    }
    return;
}

void check(int v,int pre,int odd,vector<int>& l,vector<int> &r,Graph& g){
    if(l[v]^odd){
        if(r[v]!=l[v]){
            l[v]=l[v]+1;
        }
        else{
            throw "NoC";
        }
    }
    for(int i=0;i<g[v].size();i++){
        if(g[v][i]!=pre){
            check(g[v][i],v,odd^1,l,r,g);
        }
    }
}
