void dfs(vector<int> &lb, vector<int> &ub, vector<int> &P, vector<vector<int>> &ch, bool &ok, int v = 0){
  for (int w : ch[v]){
    dfs(lb, ub, P, ch, ok, w);
    if (!ok){
      return;
    }
    lb[v] = max(lb[v], lb[w] - 1);
    ub[v] = min(ub[v], ub[w] + 1);
  }
  if (P[v] != -1){
    if(P[v] < lb[v] || ub[v] < P[v]){
      ok = false;
      return;
    }
    lb[v] = P[v];
    ub[v] = P[v];
  }
  return;
}
int main(){
  int N;
  cin >> N;
  vector<vector<int>> E(N);
  for (int i = 0; i < N - 1; i++){
    int A, B;
    cin >> A >> B;
    A--;
    B--;
    E[A].push_back(B);
    E[B].push_back(A);
  }
  int K;
  cin >> K;
  vector<int> P(N, -1);
  for (int i = 0; i < K; i++){
    int V;
    cin >> V;
    V--;
    cin >> P[V];
  }
  vector<int> c(N, -1);
  c[0] = 0;
  queue<int> Q;
  Q.push(0);
  while (!Q.empty()){
    int v = Q.front();
    Q.pop();
    for (int w : E[v]){
      if (c[w] == -1){
        c[w] = 1 - c[v];
        Q.push(w);
      }
    }
  }
  array<bool, 2> ex = {false, false};
  for (int i = 0; i < N; i++){
    if (P[i] != -1){
      ex[(P[i] + c[i]) % 2] = true;
    }
  }
  if (ex[0] && ex[1]){
    cout << "No" << endl;
  } else {
    vector<int> p(N, -1);
    vector<vector<int>> ch(N);
    vector<bool> used(N, false);
    used[0] = true;
    queue<int> Q2;
    Q2.push(0);
    while (!Q2.empty()){
      int v = Q2.front();
      Q2.pop();
      for (int w : E[v]){
        if (!used[w]){
          used[w] = true;
          p[w] = v;
          ch[v].push_back(w);
          Q2.push(w);
        }
      }
    }
    vector<int> lb(N, -100000);
    vector<int> ub(N, 1100000);
    bool ok = true;
    dfs(lb, ub, P, ch, ok);
    if (!ok){
      cout << "No" << endl;
    }
    vector<int> ans(N);
    ans[0] = lb[0];
    queue<int> Q3;
    Q3.push(0);
    while (!Q3.empty()){
      int v = Q3.front();
      Q3.pop();
      for (int w : ch[v]){
        if (ans[v] - 1 < lb[w]){
          if (ans[v] + 1 > ub[w]){
            ok = false;
          } else {
            ans[w] = ans[v] + 1;
          }
        } else {
          ans[w] = ans[v] - 1;
        }
        Q3.push(w);
      }
    }
    for (int i = 0; i < N; i++){
      if (P[i] != -1 & P[i] != ans[i]){
        ok = false;
      }
      for (int j : E[i]){
        if (abs(ans[j] - ans[i]) != 1){
          ok = false;
        }
      }
    }
    if (!ok){
      cout << "No" << endl;
    } else {
      cout << "Yes" << endl;
      for (int i = 0; i < N; i++){
        cout << ans[i] << endl;
      }
    }
  }
}

