int size(int v, int p){
    siz[v] = 1;
    rep(i, e[v].size()){
        if(e[v][i] == p || vis[e[v][i]]) continue;
        siz[v] += size(e[v][i], v);
    }
    return siz[v];
}

int find_centroid(int v, int p, int s){
    int M = s-siz[v]; int idx = v;
    rep(i, e[v].size()){
        if(e[v][i] == p || vis[e[v][i]]) continue;
        if(siz[e[v][i]] > M){
            M = siz[e[v][i]];
            idx = e[v][i];
        }
    }
    if(M <= s/2) return v;
    else return find_centroid(idx, v, s);
}

pair<int, int> range[100000];
pair<int,int> dfs(int v, int p){
    if(vis[v]) return range[v];
    pair<int, int> ret ={ -1e7, 1e7 };
    if(P[v] != -1) ret ={ P[v],P[v] };
    rep(i, e[v].size()){
        if(e[v][i] == p) continue;
        pair<int,int> t = dfs(e[v][i], v);
        t.first--; t.second++;
        if(t.second < ret.first || ret.second < t.first){
            cout << "No" << endl;
            exit(0);
        }
        ret ={ max(ret.first,t.first),min(ret.second, t.second) };
    }
    return ret;
}

void solve(int v){
    size(v, -1);
    int c = find_centroid(v, -1, size(v,-1));
    P[c] = dfs(c, -1).first;
    range[c] ={ P[c], P[c] };
    vis[c] = true;
    rep(i, e[c].size()){
        if(vis[e[c][i]]) continue;
        solve(e[c][i]);
    }
}

