const int N = 2e5 + 7;

vector <int> adj[N];


int l[N], r[N], t[N], ans[N];

int f(int lx, int rx, int v) {
	if(!t[v]) {
		t[v] = 1;
		l[v] = lx;
		r[v] = rx;
	} else {
		if((l[v] - lx) & 1) {
			return 0;
		}
		if(lx > r[v] || rx < l[v]) {
			return 0;
		}
		l[v] = max(l[v], lx);
		r[v] = min(r[v], rx);
	}
	return 1;
}


void dfs(int v, int p) {
	for(int u: adj[v]) if(u ^ p) {
		dfs(u, v);
		if(t[u] && !f(l[u] - 1, r[u] + 1, v)) {
			cout << "No" << endl;
			exit(0);
		}
	}
}

void push(int v, int p) {
	if(!t[v]) {
		ans[v] = ans[p] + 1;
	} else {
		if(ans[p] + 1 >= l[v] && ans[p] + 1 <= r[v]) {
			ans[v] = ans[p] + 1;
		} else {
			assert(ans[p] - 1 >= l[v] && ans[p] - 1 <= r[v]);
			ans[v] = ans[p] - 1;
		}
	}
	for(int u: adj[v]) if(u ^ p) {
		push(u, v);
	}
}

