#include <bits/stdc++.h>

const int N = 1e5 + 5, M = 2 * N;
int adj[N], v[M], nxt[M], e;
__inline void ins(int u0, int v0) {
    v[e] = v0; nxt[e] = adj[u0]; adj[u0] = e ++;
}

int l[N], r[N], color[N];
bool cons[N], colored[N];
int n, k;

bool solve(int u, int p) {
    bool consed = false;
    int cl = -1, cr = -1;
    for (int e = adj[u]; ~e; e = nxt[e]) if (v[e] != p) {
        if (!solve(v[e], u)) return false;
        if (cons[v[e]]) {
            if (!consed) {
                consed = true;
                cl = l[v[e]] - 1, cr = r[v[e]] + 1;
            }
            else {
                if (!((cl ^ l[v[e]]) & 1)) return false;
                cl = std::max(cl, l[v[e]] - 1);
                cr = std::min(cr, r[v[e]] + 1);
            }
        }
    }

    if (cl > cr) return false;

    if (colored[u]) {
        if (consed) {
            if ((color[u] ^ cl) & 1) return false;
            if (color[u] < cl || color[u] > cr) return false;
        }
    }
    else {
        cons[u] = consed;
        l[u] = cl; r[u] = cr;
    }

    return true;
}

void encolor(int u, int p, int cp) {
    if (!cons[u]) {
        color[u] = cp + 1;
    }
    else {
        if (cp + 1 >= l[u] && cp + 1 <= r[u])
            color[u] = cp + 1;
        else
            color[u] = cp - 1;
    }

    for (int e = adj[u]; ~e; e = nxt[e]) if (v[e] != p) {
        encolor(v[e], u, color[u]);
    }
}

int main() {
    std::ios::sync_with_stdio(false);
    std::cin.tie(0);

    std::cin >> n;
    memset(adj + 1, -1, sizeof(*adj) * n);

    for (int i = 0; i < n - 1; ++ i) {
        int a, b; std::cin >> a >> b;
        ins(a, b); ins(b, a);
    }

    std::cin >> k;
    for (int i = 0; i < k; ++ i) {
        int v, p; std::cin >> v >> p;
        colored[v] = cons[v] = true;
        l[v] = r[v] = color[v] = p;
    }

    bool succ = solve(1, 0);
    //std::cout << l[5] << " " << r[5] << std::endl;
    if (succ) {
        std::cout << "Yes\n";
        encolor(1, 0, l[1] - 1);
        for (int i = 1; i <= n; ++ i)
            std::cout << color[i] << '\n';
    }
    else {
        std::cout << "No\n";
    }
}

