void boo() {
    cout << "No" << endl;
    exit(0);
}

struct node {
    int v, par;
};

typedef pair<int, int> pii;
queue<node> q1;
priority_queue<pii> pq;

void bfs() {
    while (!q1.empty()) {
        int v = q1.front().v;
        int par = q1.front().par;
        q1.pop();

        for (const int& w : G[v]) {
            if (w == par) continue;

            up[w] = v;
            depth[w] = depth[v] + 1;
            if (p[w] != MOD) {
                pq.push({depth[w], w});

                if (ma[v] % 2 == p[w] % 2) boo();
                if (ma[v] + 1 < p[w]) boo();
                if (mi[v] - 1 > p[w]) boo();

                ma[w] = mi[w] = p[w];
                ma[v] = ma[w] + 1;
                mi[v] = mi[w] - 1;
            } else {
                // free
                ma[w] = ma[v] + 1;
                mi[w] = mi[v] - 1;
            }

            q1.push({w, v});
        }
    }
}

