      lint R = INF;
      for (auto nxt : g[cur]) {
        if (nxt == par) continue;
        lint chL = l[nxt];
        lint chR = r[nxt];
        L = max(L, chL - 1);
        R = min(R, chR + 1);
      }

      if (num[cur] != -1) {
        L = max(L, num[cur]);
        R = min(R, num[cur]);
      }

      if ((lint)abs(L) % 2 != mod2) {
        L++;
      }

      if ((lint)abs(R) % 2 != mod2) {
        R--;
      }

      if (L > R) {
        L = INF;
        R = -INF;
      }

      l[cur] = L;
      r[cur] = R;
    }
  };

