void go(int v, int p = 0) {

	if (!used[v]) {
		int x = a[p] + 1;
		//if (v == 1) cout << " -> " << t.get(tin[v], tout[v]) << ' ' << x;

		if (x + d[v] <= t.get(tin[v], tout[v])) a[v] = x;
