using P = pair<int,int>;

P merge(P p, P q) {
    if (p > q) swap(p,q);
    if (p == def) return q;
    if ((p.fst-q.fst)&1) quit("No");
    int a = max(p.fst,q.fst);
    int b = min(p.snd,q.snd);
    if (a > b) quit("No");
    return {a,b};
}

void dfs1(int v) {
    used[v] = 1;
    for (int y : g[v]) {
        if (used[y]) continue;
        dfs1(y);
        auto p = pa[y];
        pa[v] = merge(pa[v], p == def ? def : mp(p.fst-1,p.snd+1));
    }
}

void dfs2(int v) {
    used[v] = 1;
    assert(pa[v] != def);
    val[v] = pa[v].snd;
    for (int y : g[v]) {
        if (used[y]) continue;
        pa[y] = merge(pa[y], mp(val[v]-1,val[v]+1));
        dfs2(y);
    }
}

