bool dfs1(int v, int p, int mod) {
	if(X[v] != INF && X[v] % 2 != mod) return false;
	for(auto c : G[v]) {
		if(c == p) continue;
		if(!dfs1(c, v, 1 - mod)) return false;
	}
	return true;
}

bool dfs2(int v, int p) {
	for(auto c : G[v]) {
		if(c == p) continue;
		if(!dfs2(c, v)) return false;
		l[v] = max(l[v], l[c] - 1);
		r[v] = min(r[v], r[c] + 1);
		if(l[v] > r[v]) return false;
	}
	return true;
}

void dfs3(int v, int p) {
	for(auto c : G[v]) {
		if(c == p) continue;
		if(l[c] <= X[v] + 1 && X[v] + 1 <= r[c]) X[c] = X[v] + 1;
		if(l[c] <= X[v] - 1 && X[v] - 1 <= r[c]) X[c] = X[v] - 1;
		assert(X[c] != INF);
		dfs3(c, v);
	}
}

