    mn=d;
    ind=i;
  }
  static Seg e;
};
vector<Seg> dat(2*MAX_N);
Seg Seg::e=Seg();

Seg operator+(Seg l,Seg r){
  if(l.mn>r.mn)
    swap(l,r);
  return l;
}
//ostream& operator<<(ostream &os, const Seg &t) { return os<<"["<<t.mn<<")";}
template<class T=Seg> void upd(int k,T a,vector<T> &dat=dat){
  k+=dat.size()/2-1;
  dat[k]=a;
  while(k>0){
    k=(k-1)/2;
    dat[k]=dat[k*2+1]+dat[k*2+2];
  }
}

//(l,r,0,0,nn)
template<class T=Seg> T query(int a,int b,const vector<T> &dat=dat,int k=0,int l=0,int r=-1){
  if(r<0) r=dat.size()/2;
  if(r<=a || b<=l)return T::e;
  if(a<=l && r<=b) return dat[k];
  T lv=query(a,b,dat,k*2+1,l,(l+r)/2) ,rv= query(a,b,dat,k*2+2,(l+r)/2,r);
  return lv+rv;
}

pii dfs(vv<int> &g,vector<int> &usd,int v,int p,int l,int r){
  MX(lb[v],l);
  MN(rb[v],r);
  for(int w:g[v]) if(w!=p){
      dfs(g,usd,w,v,lb[v]-1,rb[v]+1);
      MX(lb[v],lb[w]-1);
      MN(rb[v],rb[w]+1);
    }
  //cout<<v<<pii(lb[v],rb[v])<<endl;
  return pii(lb[v],rb[v]);
}

