        if(e==par)continue;
        auto d=fn(g,e,now);
        if(d==make_pair(-INF,INF))continue;
        if(l==-INF&&r==INF){
            l=d.first-1;
            r=d.second+1;
        }else{
            if(l%2==d.first%2){
                cout<<"No"<<endl;
                exit(0);
            }else{
                chmax(l,d.first-1);
                chmin(r,d.second+1);
                if(l>r){
                    cout<<"No"<<endl;
                    exit(0);
                }
            }
        }
    }
    return memo[now]=make_pair(l,r);
}
void gn(const auto& g,int now=0,int par=-1,lint par_p=INF){
    if(par_p==INF){
        ans[now]=memo[now].first;
    }else{
        if(memo[now].first<=par_p-1&&par_p-1<=memo[now].second){
            ans[now]=par_p-1;
        }else{
            ans[now]=par_p+1;
        }
    }
    for(auto e:g[now]){
        if(e==par)continue;
        gn(g,e,now,ans[now]);
    }
}
