  function<void(int, int)> dfs_1_fn = [&](int v, int p) {
    int l = xs[v];
    int u = xs[v];
    for (const auto& e : graph[v]) {
      if (e.to == p) continue;
      dfs_1_fn(e.to, v);
      if (fail) return;
      if (l == INVALID) {
        if (ls[e.to] == INVALID) {

        } else {
          l = ls[e.to] - 1;
          u = us[e.to] + 1;
        }
      } else {
        if (ls[e.to] != INVALID && l % 2 == ls[e.to] % 2) {
          fail = true;
          return;
        }
        if (ls[e.to] != INVALID) {
          l = max(ls[e.to] - 1, l);
          u = min(us[e.to] + 1, u);
        }
      }
    }
    if (l > u) {
      if (DEBUG) cout << "v: " << v << " l: " << l << " u: " << u << endl;
      fail = true;
      return;
    }
    ls[v] = l;
