bool update(pair<int, int>& l, const pair<int, int>& r) {
    if(l.second < r.first || r.second < l.first) return false;
    bool ok = false;
    if(l.first <= r.first && r.second <= l.second) ok = true;
    if(r.first <= l.first && l.second <= r.second) ok = true;
    if(!ok) if((l.first & 1) == (r.first & 1)) ok = true;
    l.first = max(l.first, r.first);
    l.second = min(l.second, r.second);
    return ok;
}
bool dfs(int cur, int par) {
    auto& myRange = range[cur];
    bool stRange = (myRange != make_pair(-INF, INF));
    bool res = true;
    if(num[cur] == INF) {
        auto nRange = myRange;
        nRange.first--; nRange.second++;
        for(int nxt : adj[cur]) if(nxt != par) {
            if(stRange) range[nxt] = nRange;
            res &= dfs(nxt, cur);
            auto upRange = range[nxt];
            upRange.first--; upRange.second++;
            res &= update(myRange, upRange);
        }
    }
    else {
        if(stRange) {
            res &= ((myRange.first & 1) == (num[cur] & 1));
            res &= (myRange.first <= num[cur] && num[cur] <= myRange.second);
        }
        if(!res) return res;
        myRange = make_pair(num[cur], num[cur]);
        pair<int, int> nRange(num[cur] - 1, num[cur] + 1);
        for(int nxt : adj[cur]) if(nxt != par) {
            range[nxt] = nRange;
            res &= dfs(nxt, cur);
            auto upRange = range[nxt];
            upRange.first--; upRange.second++;
            res &= update(myRange, upRange);
        }
    }
    return res;
}
void dfs2(int cur, int par) {
    if(num[cur] == INF) {
        num[cur] = range[cur].first;
    }
    pair<int, int> nRange(num[cur] - 1, num[cur] + 1);
    for(int nxt : adj[cur]) if(nxt != par) {
        update(range[nxt], nRange);
        dfs2(nxt, cur);
    }
}
