            }else{
                if(v[a].size()!=0){
                    ret.push_back(v[a][0]-1);
                    ret.push_back(v[a][1]+1);
                }
            }
        }
        if(!flag){
            ret.push_back(INF);
            ret.push_back(INF);
        }
    }
    return ret;
}
