using ll = long long;

const ll INF = static_cast<ll>(1e9) + 7ll;
const ll LINF = INF * INF;
const int MAXN = static_cast<int>(1e6) + 17;

int n, m;
bool ok = true;
vector<int> g[MAXN];
ll col[MAXN], L[MAXN], R[MAXN];
ll kek[2];

bool read() {
    if (!(cin >> n))
        return false;

    forn (i, n - 1) {
        int u, v;
        cin >> u >> v;
        g[u - 1].pb(v - 1);
        g[v - 1].pb(u - 1);
    }

    cin >> m;
    fill(col, col + n, -1);

    forn (i, m) {
        int v, x;
        cin >> v >> x;
        col[v - 1] = x;
    }

    return true;
}

void dfs1(int v, int pr, int h) {
    if (col[v] != -1) {
        if (kek[h] == -1)
            kek[h] = col[v];

        if (1 & (col[v] ^ kek[h]))
            ok = false;

        L[v] = R[v] = col[v];
    }

    for (auto to : g[v])
        if (to != pr) {
            dfs1(to, v, (h ^ 1));
            L[v] = max(L[v], L[to] - 1);
            R[v] = min(R[v], R[to] + 1);
        }
}

void dfs2(int v, int pr, pair<ll, ll> up) {
    multiset<ll> Ls, Rs;
    Ls.insert(-INF * INF);
    Rs.insert(INF * INF);

    for (auto to : g[v])
        if (to != pr) {
            Ls.insert(L[to]);
            Rs.insert(R[to]);
        }

    if (pr != -1) {
        L[v] = max(L[v], up.f - 1);
        R[v] = min(R[v], up.s + 1);
        Ls.insert(up.f);
        Rs.insert(up.s);
    }

    for (auto to : g[v])
        if (to != pr) {
            auto curL = L[to];
            auto curR = R[to];
            Ls.erase(Ls.find(curL));
            Rs.erase(Rs.find(curR));
            dfs2(to, v, mp(*Ls.rbegin() - 1, *Rs.begin() + 1));
            Ls.insert(curL);
            Rs.insert(curR);
        }
}

void dfs(int v, int pr) {
    for (auto to : g[v])
        if (to != pr) {
            if (col[to] == -1) {
                if (L[to] <= col[v] - 1 && col[v] - 1 <= R[to])
                    col[to] = col[v] - 1;
                else
                    col[to] = col[v] + 1;
            }

            dfs(to, v);
        }
}

void solve() {
    kek[0] = kek[1] = -1;
    fill(L, L + n, -INF * INF);
    fill(R, R + n, INF * INF);
    dfs1(0, -1, 0);
    dfs2(0, -1, mp(-INF * INF, INF * INF));

    forn (v, n)
        if (L[v] > R[v])
            ok = false;

    if (!ok || (kek[0] != -1 && kek[1] != -1 && (kek[0] ^ kek[1]) % 2 == 0)) {
        cout << "No\n";
        return ;
    }

    forn (i, n)
        if (col[i] != -1) {
            dfs(i, -1);
            break;
        }

    forn (v, n)
        for (auto to : g[v])
            if (abs(col[v] - col[to]) != 1) {
                cout << "No\n";
                return ;
            }

    cout << "Yes\n";

    forn (i, n)
        cout << col[i] << endl;
}

int main() {
    cin.tie(nullptr);
    std::ios_base::sync_with_stdio(false);

    while (read())
        solve();

    return 0;
}

#include <bits/stdc++.h>

using namespace std;

#define fst(t) std::get<0>(t)
#define snd(t) std::get<1>(t)
#define thd(t) std::get<2>(t)

using ll = long long;
using P = std::tuple<int,int>;

const int dx[8] = {-1, 1, 0, 0, -1, -1, 1, 1}, dy[8] = {0, 0, -1, 1, -1, 1, -1, 1};
const int INF = numeric_limits<int>::max() / 2;

vector<int> graph[100000];
int values[100000];
int N, K, root;
bool visited[100000];
P ranges[100000];

bool isIn(const int x, const P range){
    return fst(range) <= x && x <= snd(range);
}

template <int n>
bool dfs(int u, vector<int> (&graph)[n], bool (&visited)[n]){
    visited[u] = true;
    ranges[u] = std::make_tuple(-INF, INF);

    for(int v : graph[u]){
        if(!visited[v]){
            if(!dfs(v, graph, visited)){return false;}
            P r = ranges[v];
            --fst(r); ++snd(r);
            if(snd(r) < fst(ranges[u]) || snd(ranges[u]) < fst(r)){return false;}
            fst(ranges[u]) = max(fst(ranges[u]), fst(r));
            snd(ranges[u]) = min(snd(ranges[u]), snd(r));
        }
    }

    if(values[u] != -1){
        if(!isIn(values[u], ranges[u])){return false;}
        ranges[u] = std::make_tuple(values[u], values[u]);
    }

    return true;
}

template <int n>
bool dfs2(int u, int value, vector<int> (&graph)[n], bool (&visited)[n]){
    visited[u] = true;

    for(int v : graph[u]){
        if(!visited[v]){
            int v_value = INF;
            if(isIn(value - 1, ranges[v])){
                v_value = value - 1;
            }
            if(isIn(value + 1, ranges[v])){
                v_value = value + 1;
            }

            if(v_value == INF){return false;}
            values[v] = v_value;
            if(!dfs2(v, v_value, graph, visited)){return false;}
        }
    }

    return true;
}

int main(){
    std::cin.tie(nullptr);
    std::ios::sync_with_stdio(false);

    memset(values, -1, sizeof(values));

    std::cin >> N;

    for(int i=0;i<N-1;++i){
        int u, v;
        std::cin >> u >> v;
        --u; --v;

        graph[u].emplace_back(v);
        graph[v].emplace_back(u);
    }

    std::cin >> K;

    for(int i=0;i<K;++i){
        int u, v;
        std::cin >> u >> v;
        --u;

        values[u] = v;
        // std::cout << u << " = " << v << std::endl;
        root = u;
    }

    memset(visited, 0, sizeof(visited));
    if(!dfs(root, graph, visited)){
        std::cout << "No" << std::endl;
        return 0;
    }

    // if(values[root] < fst(ranges[root]) || snd(ranges[root]) < values[root]){
    //     std::cout << "No" << std::endl;
    //     return 0;
    // }

    memset(visited, 0, sizeof(visited));
    if(!dfs2(root, values[root], graph, visited)){
        std::cout << "No" << std::endl;
        return 0;
    }

    std::cout << "Yes" << std::endl;
    for(int i=0;i<N;++i){
        std::cout << values[i] << std::endl;
    }
}

#include <iostream>
