typedef long long lint;
const int N=1e5+5;
int n,lim_l[N],lim_r[N],ans[N];
bool dif;

namespace utils{
	template <class T> inline void apx(T &x,const T y){
		x<y?x=y:0;
	}
	template <class T> inline void apn(T &x,const T y){
		x>y?x=y:0;
	}
	inline int nxi(FILE *fd=stdin){
		int x=0;
		char c;
		while(((c=fgetc(fd))>'9'||c<'0')&&c!='-');
		const bool f=(c=='-')&&(c=fgetc(fd));
		while(x=x*10-48+c,(c=fgetc(fd))>='0'&&c<='9');
		return f?-x:x;
	}
}
using namespace utils;

namespace G{
	int cnt,fir[N],fa[N],dep[N];
	struct edge{
		int to,nx;
	}eg[N<<1];

	inline void add(const int a,const int b){
		//printf("add: %d %d\n",a,b);
		eg[++cnt]=(edge){b,fir[a]};
		fir[a]=cnt;
	}

	void dfs_dep(const int x){
		for(int i=fir[x]; i; i=eg[i].nx){
			const int y=eg[i].to;
			if(y==fa[x]) continue;
			fa[y]=x;
			dep[y]=dep[x]+1;
			dfs_dep(y);
		}
	}

	bool dfs_vld(const int x){
		if(lim_r[x]==-1){
			lim_r[x]=(dep[x]==dif?1e5+2:1e5+1);
			lim_l[x]=(dep[x]==dif?-1e5-2:-1e5-1);
		}
		for(int i=fir[x]; i; i=eg[i].nx){
			const int y=eg[i].to;
			if(y==fa[x]) continue;
			if(!dfs_vld(y)) return 0;
			apn(lim_r[x],lim_r[y]+1);
			apx(lim_l[x],lim_l[y]-1);
		}
		assert(((lim_l[x]^lim_r[x])&1)==0);
		return lim_l[x]<=lim_r[x];
	}

	void dfs_ans(const int x){
		for(int i=fir[x]; i; i=eg[i].nx){
			const int y=eg[i].to;
			if(y==fa[x]) continue;
			ans[y]=ans[x]<lim_l[y]?ans[x]+1:ans[x]-1;
			dfs_ans(y);
		}
	}
}

int main(){
	n=nxi();
	memset(lim_r+1,-1,n*sizeof(int));
	for(int i=1; i<n; ++i){
		const int a=nxi(),b=nxi();
		G::add(a,b);
		G::add(b,a);
	}
	G::dfs_dep(1);
	for(int q=nxi(),i=1; i<=q; ++i){
		const int x=nxi(),v=nxi();
		lim_l[x]=lim_r[x]=v;
		if(i==1) dif=(v&1)^(G::dep[x]&1);
		else if(((v&1)^(G::dep[x]&1))!=dif){
			puts("No");
			return 0;
		}
	}
	if(!G::dfs_vld(1)){
		puts("No");
		return 0;
	}
	ans[1]=lim_l[1];
	G::dfs_ans(1);
	puts("Yes");
	for(int i=1; i<=n; ++i){
		printf("%d\n",ans[i]);
	}
	return 0;
}

#include<iostream>
#include<cstdio>
using namespace std;
const int N=1e5+10;
const int inf=1e9;
int n;
struct edge{int to,Next;}ed[N<<1];
int edcnt,head[N];
void addedge(int u,int v){ed[++edcnt]=(edge){v,head[u]};head[u]=edcnt;}
int le[N],ri[N];
void dfslr(int u,int Fa)
{
	for(int i=head[u];i;i=ed[i].Next)
	if(ed[i].to!=Fa)
	{
		int v=ed[i].to;
		le[v]=max(le[v],le[u]-1);
		ri[v]=min(ri[v],ri[u]+1);
		dfslr(v,u);
	}
	if(Fa)
	{
		le[Fa]=max(le[Fa],le[u]-1);
		ri[Fa]=min(ri[Fa],ri[u]+1);
	}
}
int ans[N];bool used[N*3];
bool dfsans(int u,int Fa)
{
	for(int i=head[u];i;i=ed[i].Next)
	if(ed[i].to!=Fa&&le[ed[i].to]==ri[ed[i].to]) used[le[ed[i].to]+n]=true;
	int l=le[u];
	while(l<=ri[u]&&used[l]) l++;
	if(l>ri[u]) return false;
	ans[u]=l;
	for(int i=head[u];i;i=ed[i].Next)
	if(ed[i].to!=Fa&&le[ed[i].to]==ri[ed[i].to]) used[le[ed[i].to]+n]=false;
	for(int i=head[u];i;i=ed[i].Next)
	if(ed[i].to!=Fa)
	{
		int v=ed[i].to;
		le[v]=max(le[v],ans[u]-1);
		ri[v]=min(ri[v],ans[u]+1);
		if(!dfsans(v,u)) return false;
	}
	return true;
}
int main()
{
	scanf("%d",&n);
	for(int i=1;i<n;i++)
	{
		int u,v;scanf("%d%d",&u,&v);
		addedge(u,v);addedge(v,u);
	}
	for(int i=1;i<=n;i++)
	{
		le[i]=-n;
		ri[i]=n*2;
	}
	int K;scanf("%d",&K);
	for(int i=1;i<=K;i++)
	{
		int Id,Val;scanf("%d%d",&Id,&Val);
		le[Id]=ri[Id]=Val;
	}
	dfslr(1,0);dfslr(1,0);
	bool flag=true;
	for(int i=1;i<=n;i++)
	if(le[i]>ri[i])
	{
		flag=false;
		break;
	}
	if(flag) flag=dfsans(1,0);
	if(!flag) printf("No\n");
	else{
		printf("Yes\n");
		for(int i=1;i<=n;i++) printf("%d\n",ans[i]);
	}
	return 0;
}

#include <iostream>
#include <vector>
#include <map>
#include <cstdio>
#include <cstring>
#include <math.h>
#include <time.h>
#define MAXN 111111
#define Inf 1000000000
using namespace std;


pair<int,int> range[MAXN+1];
vector<int> edges[MAXN+1];
bool isset[MAXN+1];

bool dfs(int par, int u, pair<int,int> rg) {


    rg.first--;
    rg.second++;

    range[u].first = max(range[u].first, rg.first);
    range[u].second = min(range[u].second, rg.second);
    if (range[u].first > range[u].second)
        return false;


    if (isset[u])
        return true;



    bool ret = true;
    for(int j=0;j<edges[u].size();j++) {
        int v = edges[u][j];
        if (v == par)
            continue;
        ret &= dfs(u,v,range[u]);
    }
    return ret;

}

int answer[MAXN+1];

bool dfs2(int par, int u,int par_val) {

    // either par_val-1 or par_val+1.

    bool can = false;
    int val;
    for(int t=par_val-1;t<=par_val+1;t+=2) {
        if (range[u].first <= t && range[u].second >= t) {
            can=true;
            val=t;
            break;
        }
    }

    if (!can)
        return false;

    bool ret = true;
    answer[u]=val;
    for(int j=0;j<edges[u].size();j++) {
        int v=edges[u][j];
        if (v == par)
            continue;
        ret &= dfs2(u,v,val);
    }
    return ret;

}

int main() {
    int N;
    cin>>N;
    for(int i=1;i<=N-1;i++) {
        int u,v;
        cin>>u>>v;
        edges[u].push_back(v);
        edges[v].push_back(u);
    }

    for(int i=1;i<=N;i++) {
        range[i]=make_pair(-Inf,+Inf);
        isset[i]=false;
    }




    int K;
    cin>>K;
    for(int i=1;i<=K;i++) {
        int v,p;
        cin>>v>>p;
        isset[v]=true;
        range[v]=make_pair(p,p);
    }

    bool ok = true;
    for(int v=1;v<=N;v++) {
        if (range[v].first==range[v].second) {
            for(int j=0;j<edges[v].size();j++) {
                ok &= dfs(v,edges[v][j],range[v]);
            }
        }
    }


    if (ok) {
        for(int v=1;v<=N;v++) {
            if (isset[v]) {
                answer[v]=range[v].first;
                for(int j=0;j<edges[v].size();j++) {
                    ok &= dfs2(v,edges[v][j],range[v].first);
                }
                break;
            }
        }
    }


    if (ok) {
        cout << "Yes" << endl;

        for(int v=1;v<=N;v++) {
            cout << answer[v] << endl;
        }


    } else {
        cout << "No" << endl;
    }





}

