const int INF = 1e9;
struct R {
    int l, r;
    void ins(const R &p) {
        l = max(l, p.l);
        r = min(r, p.r);
    }
    bool inside(int x) { return l <= x && x <= r; }
    bool any() const { return r >= INF; }
    bool empty() const { return l > r; }
    void deb() const { fprintf(stderr, "[%d, %d]\n", l, r); }
};

const int MN = 123456;
