bool used[MN];
V<int> g[MN];
R rng[MN];

void imp() {
    puts("No");
    exit(0);
}

void dfs1(int v, int p) {
    if (!used[v]) {
        rng[v] = R{-INF, INF};
    } else {
        rng[v] = R{a[v], a[v]};
    }
    for (int u: g[v]) {
        if (u == p) continue;
        dfs1(u, v);
        if (!rng[v].any() && !rng[u].any() && abs(rng[v].l - rng[u].l) % 2 == 0) imp();
        rng[v].ins(R{rng[u].l - 1, rng[u].r + 1});
    }
    // rng[v].deb();
    if (rng[v].empty()) imp();
//    assert((rng[v].r - rng[v].l) % 2 == 0);
}

void dfs2(int v, int p) {
    if (p == -1) {
        a[v] = rng[v].l;
    }
    for (int u: g[v]) {
        if (u == p) continue;
        a[u] = (rng[u].inside(a[v] - 1)) ? a[v] - 1 : a[v] + 1;
        dfs2(u, v);
    }
}

