int check(ll from, ll now){
  int ret = 0;
  for(int i=0;i<G[now].size();i++){
    if(from==G[now][i]) continue;
    int tmp = check(now, G[now][i]);
    if(ret==0) return oe[now] = -tmp;
    else if(ret==tmp) {
