void back(ll from, ll now, ll l, ll r){
  num[now][0] = max(num[now][0], l);
  num[now][1] = min(num[now][1], r);
  for(int i=0;i<G[now].size();i++){
    if(G[now][i]==from) continue;
    back(now, G[now][i], num[now][0]-1, num[now][1]+1);
  }
}
pair<ll, ll> dfs(ll from, ll now){
  ll l=-INF, r=INF;
  if(num[now][1]!=INF) l = num[now][0], r = num[now][1];
  for(int i=0;i<G[now].size();i++){
    if(from==G[now][i]) continue;
    pair<ll, ll> tmp = dfs(now, G[now][i]);
    l = max(l, tmp.first);
    r = min(r, tmp.second);
  }
  num[now][0] = l, num[now][1] = r;
  return make_pair(l-1, r+1);
}
void an(ll from, ll now){
  if(from==-1) ans[now] = num[now][0];
  else{
    ll p = ans[from];
