constexpr i32 maxn = 100000;

inline i32 in() {
	i32 n;
	scanf("%d", &n);
	return n;
}

std::vector<i32> to[maxn + 1];

inline void lnk(const i32 &u, const i32 &v) {
	to[u].emplace_back(v);
	to[v].emplace_back(u);
}

i32 val[maxn + 1];
bool col[maxn + 1];

bool color(const i32 &u, const i32 &p, const bool &c) {
	if (val[u] != -1 and c != col[u])
		return false;
	for (const i32 &v: to[u])
		if (v != p and color(v, u, not c) == false)
				return false;
	return true;
}

i32 l[maxn + 1],
	r[maxn + 1];

void contract(const i32 &u, const i32 &p) {
	if (val[u] == -1)
		l[u] = -1e9, r[u] = 1e9;
	else l[u] = r[u] = val[u];
	for (const i32 &v: to[u])
		if (v != p)
			contract(v, u),
			l[u] = std::max(l[u], l[v] - 1),
			r[u] = std::min(r[u], r[v] + 1);
}

inline bool vaild(const i32 &u, const i32 &v) {
	return l[u] <= v and v <= r[u];
}

void calc(const i32 &u, const i32 &p) {
	for (const i32 &v: to[u])
		if (v != p) {
			if (vaild(v, val[u] - 1)) 
				val[v] = val[u] - 1;
			else if (vaild(v, val[u] + 1))
				val[v] = val[u] + 1;
			calc(v, u);
		}
}

i32 main() {
	const i32 n = in();
	for (i32 i = 1; i < n; ++i)
		lnk(in(), in());
	std::fill(val + 1, val + n + 1, -1);

	const i32 k = in(); i32 root = 0;
	for (i32 i = 1; i <= k; ++i)	
		root = in(), val[root] = in(), col[root] = (val[root] & 1);

	if (color(root, 0, col[root]) == false)
		return puts("No"), 0;
	contract(root, 0);

	if (l[root] > r[root])
		return puts("No"), 0;
	calc(root, 0);

	puts("Yes");
	for (i32 i = 1; i <= n; ++i)
		printf("%d\n", val[i]);

	return 0;
}

