		for (int j = sp[cur]; j; j = a[j].nxt)
		{
			if (par[a[j].e]) continue;
			par[a[j].e] = cur;
			dep[a[j].e] = dep[cur] + 1;
			q[tl++] = a[j].e;
		}
	}
