	memset(p,-1,sizeof(p));
	For(i,1,k) {
		int pp, v; cin >> pp >> v;
		p[pp] = v;
		root = pp;
	}
}

void fail() {
	cout << "No" << endl;
	exit(0);
}

int stat[maxn];
void preDfs(const int u,const int prev, const int sign) {
	stat[u] = sign;
	for (int v : V[u]) if (v != prev) {
		if (p[v] != -1 && ((p[v] & 1) !=  (sign ^ 1)) ) return fail();
		preDfs(v, u, sign ^ 1);
	}
}

int upper[maxn], lower[maxn];
const int MX = 2e5;
void solveUpper(int p[], int upper[]) {
	priority_queue<pair<int,int> > qu;
	For(i,1,n) if (p[i] == -1) {
		upper[i] = MX;
		for (int j : V[i]) if (p[j] != -1) {
			upper[i] = min(upper[i], p[j] + 1);
			if (upper[i] % 2 != stat[i]) --upper[i];
		}
		if (upper[i] < MX) {
			qu.push(make_pair(-upper[i], i));
		}
	}

	while (!qu.empty()) {
		auto cur = qu.top(); qu.pop();
		int u = cur.second;
		if (upper[u] != -cur.first) {
			continue;
		}

		for (int v : V[u]) if (p[v] == -1) {
			int z = upper[u] + 1;
			if (z % 2 != stat[v]) --z;
			if (z < upper[v]) {
				upper[v] = z;
				qu.push(make_pair(-upper[v], v));
			}
		}
	}
}

bool inrange(const int l, const int r, const int mid) {
	return mid >= l && mid <= r;
}
void dfsCal(const int u, const int prev) {
	for (int v : V[u]) if (v != prev) {
		if (p[v] == -1) {
			if (inrange(lower[v], upper[v], p[u] - 1)) {
				p[v] = p[u] - 1;
			} else p[v] = p[u] + 1;
		}
		dfsCal(v, u);
	}
}

void Process() {
	preDfs(root,-1,p[root] & 1);
	solveUpper(p,upper);
	For(i,1,n) if (p[i] != -1) p[i] = MX - p[i];
	solveUpper(p,lower);
	For(i,1,n) if (p[i] != -1) p[i] = MX - p[i];
	For(i,1,n) lower[i] = MX - lower[i];

	dfsCal(root,-1);
	For(i,1,n) {
		for (int j : V[i]) {
			if (abs(p[i] - p[j]) != 1) {
				return fail();
			}
		}
	}

	cout << "Yes" << endl;
	For(i,1,n) cout << p[i] << "\n";
}

int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(NULL);

	//freopen("input.inp" , "r" , stdin);
	ReadData();
	Process();

	return 0;

}

