vector<int> g[100001];
int val[100001] = {};
int L[100001] = {}, R[100001] = {};
bool known_parity[100001][2] = {};
int par[100001] = {};
vector<int> order;
bool flag = false;

constexpr int INF = 1e9 + 7;

void dfs(int u, int fa = -1) {
    par[u] = fa;
    L[u] = -INF - 1, R[u] = INF + 1;
    for (int to : g[u]) {
        if (to == fa)
            continue;
        dfs(to, u);
        if (known_parity[to][0])
            known_parity[u][1] = 1;
        if (known_parity[to][1])
            known_parity[u][0] = 1;
        L[u] = max(L[u], L[to] - 1);
        R[u] = min(R[u], R[to] + 1);
    }
    if (val[u] != -1) {
        L[u] = R[u] = val[u];
    }
    if (known_parity[u][0] && known_parity[u][1]) {
        flag = true;
    }
    if (L[u] > R[u]) {
        flag = true;
    }
    order.push_back(u);
}

int solve_val(int u, int fa = -1) {
    if (fa == -1) {
        return L[u];
    }
    if (val[u] != -1)
        return val[u];
    L[u] = max(L[u], val[fa] - 1);
    R[u] = min(R[u], val[fa] + 1);
    while (L[u] % 2 == L[fa] % 2)
        L[u]++;
    return L[u];
}

