void dfs1(int u,int p){
	if(val[u] != INF)closest[u] = u;
	else closest[u] = 0;
	for(int v:adj[u]){
		if(v == p)continue;
		dist[v] = dist[u]+1;
		dfs1(v,u);
		if(dist[closest[v]] < dist[closest[u]])closest[u] = closest[v];
	}
}

void dfs2(int u,int p,int cur){
	assval[u] = cur;
	for(int v:adj[u]){
		if(v == p)continue;
		int what = closest[v];
		if(val[what] >= cur)dfs2(v,u,cur+1);
		else dfs2(v,u,cur-1);
	}
}

