#define INF 2147483600

vector<vector<int> > vec;
vector<int> num;
vector<pair<int, int> > memo;

bool check(int from, int d){
  if(num[d]!=-INF){
    memo[d].fi = memo[d].se = num[d];
  }
  for(int to : vec[d]) if(to!=from){
    if( ! check(d, to) ) return false;
    memo[d].fi = max(memo[d].fi, memo[to].fi-1);
    memo[d].se = min(memo[d].se, memo[to].se+1);
    if(memo[d].fi > memo[d].se) return false;
  }
  if(memo[d].fi == memo[d].se){
    num[d] = memo[d].fi;
  }
  return true;
}

bool build(int from, int d){
  int lw, up;
  if(from==-1 || memo[d].fi==memo[d].se) lw = memo[d].fi, up=memo[d].se;
  else lw = num[from]-1, up=num[from]+1;
  for(int i=lw; i<=up; i++){
    num[d] = i;
    if(from!=-1 && abs(num[d]- num[from]) != 1){
      continue;
    }
    bool flg=true;
    for(int to : vec[d]) if(to != from){
      if( ! build(d, to)){
        flg=false;
        continue;
      }
    }
    if(flg) return true;
  }
  return false;
}

