    a--;
    num[a]=b;
    memo[a]=mp(b,b);
    st=a;
  }

  if(check(-1, 0) && build(-1,st)){
    cout<<"Yes"<<endl;
    rep(i,n) printf("%d\n", num[i]);
  } else{
    cout<<"No"<<endl;
  }

  return 0;
}

