    {
        pair<int,int> p=pq.top();pq.pop();
        int u=p.second;
        for (int i=0;i<G[u].size();i++)
        {
            int v=G[u][i];
            if (d[v]==-1)
            {
                d[v]=d[u]+1;
                pq.push({d[v],v});
            }
        }
    }
    for (int u=0;u<n;u++)
    {
        for (int i=0;i<G[u].size();i++)
        {
            int v=G[u][i];
            if (abs(d[u]-d[v])!=1)
            {
                cout << "No" << endl;
                exit(0);
            }
        }
    }
    cout << "Yes" << endl;
    for (int i=0;i<n;i++) cout << d[i] << endl;
    return 0;
}

