{
	if(bk==0) return;

	for(int k=p[x].hou;k>0;k=e[k].g)
	{
		int y=e[k].y;
		if(y==fa) continue;
		dfs(y,x);
		if(p[x].jo!=-1 and p[x].jo==p[y].jo)
		{
			bk=0;
			return;
		}//本来相邻或者递推得来
		p[x].mi=mymax(p[x].mi,p[y].mi-1);
		p[x].mx=mymin(p[x].mx,p[y].mx+1);
		if(p[y].jo!=-1) p[x].jo=p[y].jo^1;//信息的合并
	}

	if(p[x].jo!=-1 and p[x].mi==p[x].mx and p[x].mi%2!=p[x].jo)
