			if(p[x].mi%2==p[x].jo) p[x].val=p[x].mi;
			else p[x].val=p[x].mi+1;
		}
		else
		{
			if(p[x].mi<=p[fa].val-1 and p[fa].val-1<=p[x].mx) p[x].val=p[fa].val-1;//debug
			else p[x].val=p[fa].val+1;
