void dfs(int x, int par){
	for(auto i : adjlist[x]) if(i != par){
		if(l[x] != -inf and r[x] != inf){ // range is set
			l[i] = max(l[i], l[x]-1);
			r[i] = min(r[i], r[x]+1);
			if(p[i] == -1){
				p[i] = 1-p[x];
			}else{
				if(p[i] == 1-p[x]) ans = ans;
				else ans = false;
			}
		}
//		printf("pre %d -> %d: %d %d %d\n", x, i, l[x], r[x], p[x]);
		dfs(i, x);
