	}
}
void cons(int x, int par){
	if(l[x] > r[x]) ans = false;
	ass[x] = l[x];
	if(abs(l[x]%2) != p[x]) ass[x]++;
	if(ass[x] > r[x]) ans = false;
	for(auto i : adjlist[x]) if(i != par){
		l[i] = max(l[i], l[x]-1);
		r[i] = min(r[i], r[x]+1);
		cons(i, x);
	}
}

