		tie(mn,mx)=mt(ps[u],ps[u]);
	}
	for(int v:g[u]) if(v!=p)
		dfs(g,u,v,!odd,ps,rs);
	for(int v:g[u]) if(v!=p){
		mn=max(mn,get<0>(rs[v])-1);
		mx=min(mx,get<1>(rs[v])+1);
	}
	if(mn>mx)
		throw "X";
	rs[u]=mt(mn,mx);
}

void dfs2(const vvi& g,int p,int u,vi& ps,const vector<tuple<int,int>>& rs)
{
	for(int v:g[u]) if(v!=p){
		int p=ps[u]-1;
		if(p<get<0>(rs[v])) p+=2;
		ps[v]=p;
		dfs2(g,u,v,ps,rs);
	}
}

void solve(const vvi& g,vi& ps)
{
	int n=g.size();
	vector<tuple<int,int>> rs(n);
	rep(i,n) if(ps[i]!=-1){
		dfs(g,-1,i,ps[i]%2,ps,rs);
		dfs2(g,-1,i,ps,rs);
		break;
	}
}

int main()
{
	for(int n;cin>>n && n;){
		vvi g(n);
		vi ps(n,-1);
		rep(i,n-1){
			int u,v; cin>>u>>v; u--,v--;
			g[u].push_back(v);
			g[v].push_back(u);
		}
		int k; cin>>k;
		rep(i,k){
			int v,p; cin>>v>>p; v--;
			ps[v]=p;
		}

		try{
			solve(g,ps);
			cout<<"Yes"<<endl;
			for(int p:ps)
				cout<<p<<endl;
		}
		catch(...){
			cout<<"No"<<endl;
		}
	}
}

