void dfs(int v, int p = -1) {
	l[v] = -inf, r[v] = inf;
	for(int to : g[v]) {
		if(to != p) {
			d[to] = d[v] + 1;
			dfs(to, v);
			Max(l[v], l[to] - 1);
			Min(r[v], r[to] + 1);
		}
	}
	if(a[v] != -1) {
		Max(l[v], a[v]);
		Min(r[v], a[v]);
	}
	if(!lie(l[v], a[v], r[v]) || (d[v] ^ abs(a[root] - a[v])) % 2 || l[v] > r[v])
		no();
}

void build(int v, int p = -1) {
	for(int to : g[v]) {
		if(to != p) {
			if(lie(l[to], a[v] - 1, r[to]))
				a[to] = a[v] - 1;
			else if(lie(l[to], a[v] + 1, r[to]))
				a[to] = a[v] + 1;
			else
				no();
			build(to, v);
		}
	}
}

