// Solution for problem: Integers on a Tree 3

#include <bits/stdc++.h>

using namespace std;

// Main segment

vector<int> g[100001];
int val[100001] = {};
int L[100001] = {}, R[100001] = {};
bool known_parity[100001][2] = {};
int par[100001] = {};
vector<int> order;
bool flag = false;

constexpr int INF = 1e9 + 7;

void dfs(int u, int fa = -1) {
    par[u] = fa;
    L[u] = -INF - 1, R[u] = INF + 1;
    for (int to : g[u]) {
        if (to == fa)
            continue;
        dfs(to, u);
        if (known_parity[to][0])
            known_parity[u][1] = 1;
        if (known_parity[to][1])
            known_parity[u][0] = 1;
        L[u] = max(L[u], L[to] - 1);
        R[u] = min(R[u], R[to] + 1);
    }
    if (val[u] != -1) {
        L[u] = R[u] = val[u];
        known_parity[u][val[u] % 2] = 1;
    }
    if (known_parity[u][0] && known_parity[u][1]) {
        flag = true;
    }
    if (L[u] > R[u]) {
        flag = true;
    }
    order.push_back(u);
}

int solve_val(int u, int fa = -1) {
    if (fa == -1) {
        return L[u];
    }
    L[u] = max(L[u], val[fa] - 1);
    R[u] = min(R[u], val[fa] + 1);
    while (L[u] % 2 == val[fa] % 2)
        L[u]++;
    return L[u];
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(NULL);

    int n;
    cin >> n;
    for (int i = 1; i < n; i++) {
        int a, b;
        cin >> a >> b;
        g[a].push_back(b);
        g[b].push_back(a);
    }
    fill(val + 1, val + n + 1, -1);
    int k;
    cin >> k;
    while (k--) {
        int p, v;
        cin >> p >> v;
        val[p] = v;
    }
    dfs(1);
    if (flag) {
        cout << "No" << endl;
        return 0;
    }
    reverse(order.begin(), order.end());
    for (int i = 0; i < order.size(); i++) {
        int to = order[i];
        val[to] = solve_val(to, par[to]);
    }
    cout << "Yes" << endl;
    for (int i = 1; i <= n; i++) {
        cout << val[i] << endl;
    }

#ifdef LOCAL
    system("pause");
#endif
    return 0;
}

