inline int read(){
	int x=0,f=0;char ch=getchar();
	while(ch<'0' || ch>'9') f|=ch=='-',ch=getchar();
	while(ch>='0' && ch<='9') x=x*10+ch-'0',ch=getchar();
	return f?-x:x;
}
int n,k,el,head[maxn],to[maxn*2],nxt[maxn*2],l[maxn],r[maxn],p[maxn],ans[maxn],q[maxn],fr,ba;
int dep[maxn],fa[maxn],sz[maxn],son[maxn],top[maxn],dfn[maxn],cnt;
int stk[maxn],tp,el2,head2[maxn],to2[maxn*2],nxt2[maxn*2],rt,fa2[maxn];
bool isp[maxn];
inline void add(int u,int v){
	to[++el]=v;nxt[el]=head[u];head[u]=el;
}
inline void add2(int u,int v){
	to2[++el2]=v;nxt2[el2]=head2[u];head2[u]=el2;
}
inline bool cmp(int x,int y){return dfn[x]<dfn[y];}
void dfs1(int u,int f){
	dep[u]=dep[fa[u]=f]+1;
	sz[u]=1;
	for(int i=head[u];i;i=nxt[i]){
		int v=to[i];
		if(v==f) continue;
		dfs1(v,u);
		sz[u]+=sz[v];
		if(sz[v]>sz[son[u]]) son[u]=v;
	}
}
void dfs2(int u,int topf){
	top[u]=topf;dfn[u]=++cnt;
	if(son[u]) dfs2(son[u],topf);
	for(int i=head[u];i;i=nxt[i]){
		int v=to[i];
		if(v==fa[u] || v==son[u]) continue;
		dfs2(v,v);
	}
}
int lca(int u,int v){
	while(top[u]!=top[v]){
		if(dep[top[u]]<dep[top[v]]) swap(u,v);
		u=fa[top[u]];
	}
	return dep[u]<dep[v]?u:v;
}
void dfs3(int u){
	for(int i=head2[u];i;i=nxt2[i]){
		int v=to2[i];
		fa2[v]=u;
		dfs3(v);
		int ll=l[u]-(dep[v]-dep[u]),rr=r[u]+(dep[v]-dep[u]);
		if(isp[u]){
			if(abs(r[u])%2!=abs(rr)%2) puts("No"),exit(0);
		}
		else l[u]=-1e9,r[u]=1e9;
		l[u]=max(l[u],ll);r[u]=min(r[u],rr);
		if(l[u]>r[u]) puts("No"),exit(0);
		isp[u]=true;
	}
}
void dfs4(int u){
	for(int i=head2[u];i;i=nxt2[i]){
		int v=to2[i];
		l[v]=max(l[v],l[u]+(dep[v]-dep[u]));
		r[v]=min(r[v],r[u]-(dep[v]-dep[u]));
		dfs4(v);
	}
}
int main(){
	n=read();
	FOR(i,1,n-1){
		int u=read(),v=read();
		add(u,v);add(v,u);
	}
	k=read();
	FOR(i,1,k) isp[p[i]=read()]=true,l[p[i]]=r[p[i]]=read();
	dfs1(1,0);dfs2(1,1);
	sort(p+1,p+k+1,cmp);
	int tmpk=k;
	FOR(i,1,k-1){
		int l=lca(p[i],p[i+1]);
		if(l!=p[i] && l!=p[i+1]) p[++tmpk]=l;
	}
	k=tmpk;
	sort(p+1,p+k+1,cmp);
	FOR(i,1,k){
		while(tp && !(dfn[stk[tp]]<=dfn[p[i]] && dfn[stk[tp]]+sz[stk[tp]]-1>=dfn[p[i]])) tp--;
		if(tp) add2(stk[tp],p[i]);
		stk[++tp]=p[i];
	}
	rt=p[1];
	dfs3(rt);dfs4(rt);
	FOR(i,1,k) ans[p[i]]=l[p[i]];
	ROF(i,k,2){
		int cnt=dep[p[i]]-dep[fa2[p[i]]],dif=ans[p[i]]-ans[fa2[p[i]]];
		int cntp=(cnt+dif)/2,cntn=(cnt-dif)/2;
		int tmp=p[i];
		FOR(j,1,cntp) ans[fa[tmp]]=ans[tmp]-1,tmp=fa[tmp],isp[tmp]=true;
		FOR(j,1,cntn) ans[fa[tmp]]=ans[tmp]+1,tmp=fa[tmp],isp[tmp]=true;
	}
	fr=1;ba=0;
	FOR(i,1,n) if(isp[i]) q[++ba]=i;
	while(fr<=ba){
		int u=q[fr++];
		for(int i=head[u];i;i=nxt[i]){
			int v=to[i];
			if(isp[v]) continue;
			isp[v]=true;
			ans[v]=ans[u]+1;
			q[++ba]=v;
		}
	}
	puts("Yes");
	FOR(i,1,n) printf("%d\n",ans[i]);
}

#ifndef __RANGE_H__
#define __RANGE_H__

#include <utility>
#include <iterator>

#include <string>
