RangeInt dfs(int i, int from) {
	RangeInt ret = (P[i] == -1 ? RangeInt(-INF, INF) : RangeInt(P[i], P[i], true, true));
	for (auto to : G[i]) {
		if (to == from) continue;
		ret &= dfs(to, i);
	}
	if (ret.Is_empty()) ok = false;
	R[i] = ret;
	ret.inf_m--; ret.sup_m++;
	return ret;
}

void dfs2(int i, int from) {
	if (from == -1) {
		ans[i] = R[i].inf_m;
	} else {
		if (P[i] == -1) {
			if (R[i].Has(ans[from] - 1)) {
				ans[i] = ans[from] - 1;
			} else {
				ans[i] = ans[from] + 1;
			}
		} else {
			if (P[i] != ans[from] + 1 && P[i] != ans[from] - 1) {
				ok = false;
				return;
			}
			ans[i] = P[i];
		}
	}
	for (auto to : G[i]) {
		if (to == from) continue;
		dfs2(to, i);
	}
}

int main() {
	cin >> N;
	REP(i, 0, N - 1) {
		int a, b;
		cin >> a >> b;
		--a; --b;
		G[a].push_back(b);
		G[b].push_back(a);
	}
	cin >> K;
	Fill(P, -1);
	REP(i, 0, K) {
		int v, p;
		cin >> v >> p;
		--v;
		P[v] = p;
	}

	dfs(0, -1);
	if (ok) {
		dfs2(0, -1);
	}

	cout << YesNo(ok) << endl;
	if (ok) {
		REP(i, 0, N) {
			cout << ans[i] << endl;
		}
	}
	return 0;
}

