int n,k,val[100005],l[100005],r[100005];
vector<int> g[100005];
void die()
{
	cout<<"No"<<endl;
	exit(0);
}
void solve(int v,int p)
{
	l[v]=-1e9-1;
	r[v]=1e9+1;
	if(val[v]!=-1) l[v]=r[v]=val[v];
	for(int i=0;i<g[v].size();i++)
	{
		int to=g[v][i];
		if(to==p) continue;
		solve(to,v);
		if(l[to]<-1e8) continue;
		if(l[v]<-1e8)
		{
			l[v]=l[to]-1;
			r[v]=r[to]+1;
		}
		else
		{
			if(abs(l[to])%2==abs(l[v])%2)
				die();
			l[v]=max(l[v],l[to]-1);
			r[v]=min(r[v],r[to]+1);
		}
	}
	if(l[v]>r[v]) die();
}
void make(int v,int p)
{
	for(int i=0;i<g[v].size();i++)
	{
		int to=g[v][i];
		if(to==p) continue;
		if(val[to]==-1)
		{
			if(l[to]<=val[v]-1&&val[v]-1<=r[to]) val[to]=val[v]-1;
			else val[to]=val[v]+1;
		}
		make(to,v);
	}
}
