void dfs(int i,int p,vector<vector<int>>& edges,vector<P>& val,vector<bool>& c) {
    if (p != -1) {
        val[i].first = max(val[i].first,val[p].first-1);
        val[i].second = min(val[i].second,val[p].second+1);
        if (val[i].first < val[p].first-1 && val[i].second > val[p].second+1) return;
    }
    for (int j : edges[i]) if (j != p) {
        if (!c[j]) dfs(j,i,edges,val,c);
        else if (val[i].first-1 > val[j].first || val[i].second+1 < val[j].second || val[i].first%2 == val[j].first%2) {
            cout << "No" << endl;
            exit(0);
        }
    }
}

int main() {
    int n;
    cin >> n;
    vector<bool> c(n,false);
    vector<int> sup(n,1e7),inf(n,-1e7);
    vector<vector<int>> edges(n);
    for (int i = 0;i < n-1;++i) {
        int u,v;
        scanf("%d%d", &u, &v);
        u--;v--;
        edges[u].push_back(v);
        edges[v].push_back(u);
    }
    int k;
    cin >> k;
    vector<P> ls(k);
    for (int i = 0;i < k;++i) {
        int v,p;
        cin >> v >> p;
        v--;
        c[v] = true;
        sup[v] = inf[v] = p;
        ls[i] = P(p,v);
    }
    priority_queue<P> q;
    for (int i = 0;i < k;++i) q.push(ls[i]);
    while (!q.empty()) {
        P p = q.top();
        q.pop();
        for (int i : edges[p.second]) {
            if (!c[i] && p.first-1 > inf[i]) {
                q.push(P(p.first-1,i));
                inf[i] = p.first-1;
            }
            if (c[i] && (p.first-1 > inf[i] || p.first%2 == inf[i]%2)) {
                cout << "No" << endl;
                exit(0);
            }
        }
    }
    priority_queue<P,vector<P>,greater<P>> r;
    for (int i = 0;i < k;++i) r.push(ls[i]);
    while (!r.empty()) {
        P p = r.top();
        r.pop();
        for (int i : edges[p.second]) {
            if (!c[i] && p.first+1 < sup[i]) {
                r.push(P(p.first+1,i));
                sup[i] = p.first+1;
            }
            if (c[i] && (p.first+1 < sup[i] || p.first%2 == sup[i]%2)) {
                cout << "No" << endl;
                exit(0);
            }
        }
    }
    cout << "Yes" << endl;
    for (int i = 0;i < n;++i) cout << sup[i] << endl;
    return 0;
