  { fl = false; return false; }

  L[prv] = std::max( L[prv], L[v]-1 );
  R[prv] = std::min( R[prv], R[v]+1 );

  return true;
}

void calc( int v, int prv )
{
  used[v] = true;

  //printf( "{%d}\n", v+1 );

  if( v == prv )
    A[v] = L[v];
  else if( L[v] <= A[prv]+1 && A[prv]+1 <= R[v] )
    A[v] = A[prv]+1;
  else if( L[v] <= A[prv]-1 && A[prv]-1 <= R[v] )
    A[v] = A[prv]-1;
  else
    fl = false;

  for( auto &u : G[v] ) if( !used[u] )
    calc( u, v );

  return;
}

