    pair<ll, ll> tmp = dfs(now, G[now][i]);
    l = max(l, tmp.first);
    r = min(r, tmp.second);
  }
  num[now][0] = l, num[now][1] = r;
  return make_pair(l-1, r+1);
}
void an(ll from, ll now){
  if(from==-1) ans[now] = num[now][0];
  else{
    ll p = ans[from];
    if(num[now][0] <= p+1 && p+1 <= num[now][1]) ans[now] = p+1;
    else if(num[now][0] <= p-1 && p-1 <= num[now][1]) ans[now] = p-1;
    else{
      std::cout << "No" << '\n';
      exit(0);
    }
  }
  for(int i=0;i<G[now].size();i++){
    if(from==G[now][i]) continue;
    an(now, G[now][i]);
  }
}
