inline void add_edge(int from, int to)
{
	static int cnt = 0;
	e[++cnt].nxt = first[from];
	first[from] = cnt;
	e[cnt].to = to;
	e[++cnt].nxt = first[to];
	first[to] = cnt;
	e[cnt].to = from;
}

int ll[maxn], rr[maxn];
int fa[maxn];

inline void dfs(int now)
{
//	cout << "now = " << now << endl;
	for(int i = first[now]; i; i = e[i].nxt)
	{
		int to = e[i].to;
		if(to != fa[now])
