			{
				puts("No");
				exit(0);
			}
			jo[to] = !jo[now];
			fa[to] = now;
			dfs(to);
		}
	}
	ll[fa[now]] = max(ll[now] - 1, ll[fa[now]]);
	rr[fa[now]] = min(rr[now] + 1, rr[fa[now]]);
}

