}

void read(){
	scanf("%d",&n);
	for(int i=0;i<n-1;++i){
		int f, s;
		scanf("%d%d",&f,&s);
		--f;--s;
		e[f].push_back(s);
		e[s].push_back(f);
	}
	for(int i=0;i<n;++i){
		l[i] = -N * 2;
		r[i] = N * 2;
	}
	scanf("%d",&k);
	for(int i=0;i<k;++i){
		int v, p;
		scanf("%d%d",&v,&p);
		--v;
		ans[v] = p;
		l[v] = r[v] = p;
	}
}

void merge(int id1, int id2){
	l[id1] = max(l[id1], l[id2] - 1);
	r[id1] = min(r[id1], r[id2] + 1);
}

void check(int id1){
	if(l[id1] > r[id1]){
		printf("No\n");
		exit(0);
	}
}

void dfs(int u, int p){
	for(int i=0;i<e[u].size();++i){
		int to = e[u][i];
		if(to == p){
			continue;
		}
		dfs(to, u);
		merge(u, to);
		check(u);
	}
}

void dfs1(int u, int p, int fir, int sec){
	if(fir >= l[u] &&  fir <= r[u]){
		ans[u] = fir;
	}else{
		ans[u] = sec;
	}
	for(int i=0;i<e[u].size();++i){
		int to = e[u][i];
		if(to == p){
			continue;
		}
		dfs1(to, u, ans[u] - 1, ans[u] + 1);
	}
}

int main(){
	prepare();
	read();
	dfs(0, 0);
	dfs1(0, 0, l[0], l[0]);

	printf("Yes\n");
	for(int i=0;i<n;++i){
		printf("%d\n",ans[i]);
	}

	return 0;
}

