vector<int> g[100001] = {};
int id[100001] = {};
int L[100001] = {}, R[100001] = {};

constexpr int INF = 1e9 + 7;
bool flag = false;

void solve(int v, int fa = -1) {
    L[v] = -INF - 1, R[v] = INF + 1;
    if (id[v] != -1)
        L[v] = R[v] = id[v];
    for (int x : g[v]) {
        if (x == fa)
            continue;
        solve(x, v);
        if (L[x] < -INF / 2)
            continue;
        if (L[v] < -INF / 2) {
            L[v] = L[x] - 1;
            R[v] = R[x] + 1;
        } else {
            if (abs(L[v]) % 2 == abs(L[x]) % 2) {
                flag = true;
                return;
            }
            L[v] = max(L[x] - 1, L[v]);
            R[v] = min(R[x] + 1, R[v]);
        }
    }
    if (L[v] > R[v]) {
        flag = true;
    }
}

void make(int v, int fa = -1) {
    for (int x : g[v]) {
        if (x == fa)
            continue;
        if (L[x] <= id[v] - 1 && id[v] - 1 <= R[x]) {
            id[x] = id[v] - 1;
        } else {
            id[x] = id[v] + 1;
        }
        make(x, v);
    }
}

