	for(int i = 1; i <= m; i++)
	{
		int x, v;
		scanf("%d%d", &x, &v);
		hv[x] = 1;
		val[x] = v;
		if(!rt) rt = x;
	}
}

bool dfs(int x, int p, int ls)
{
	d[x] = d[p] + 1;
	fa[x] = ls;
	if(hv[x])
	{
		if(hv[ls])
		{
			int dv = abs(val[ls] - val[x]);
			int dis = d[x] - d[ls];
			if(dv > dis || ((dv + dis) & 1))
				return false;
		}
		ls = x;
	}
	for(auto y: g[x])
	{
		if(y == p) continue;
		if(!dfs(y, x, ls))
			return false;
	}
	return true;
}

int color(int x, int p)
{
	for(auto y: g[x])
	{
		if(y == p) continue;
		int t = color(y, x);
		if(t == 0) return 0;
		if(!hv[y]) continue;
		if(!hv[x]) val[x] = val[y] + t, hv[x] = 1;
		else if(val[x] != val[y] + t)
			return 0;
	}
	if(val[fa[x]] < val[x])
		return -1;
	else
		return 1;
}

bool ok;

void fix()
{
	queue<int> q;
	for(int i = 1; i <= n; i++)
	{
		if(hv[i])
		{
			for(auto j: g[i])
			{
				if(!hv[j])
				{
					hv[j] = 1;
					val[j] = val[i] - 1;
					q.push(j);
				}
			}
		}
	}
	while(!q.empty())
	{
		int x = q.front();
		q.pop();
		for(auto y: g[x])
			if(!hv[y])
			{
				hv[y] = 1;
				val[y] = val[x] - 1;
				q.push(y);
			}
	}
}

