const int N=1e5+10,inf=1e9;
bool flag=true,ok[N],fl[N];
struct abc{
	int nxt,to;
}e[N<<2];
int tot,head[N],mn[N],mx[N],ans[N];
void dfs(int x,int fa){
	if(fa!=0&&ok[x]&&fl[fa]==fl[x]){
		flag=0;return;
	}
	fl[x]=fl[fa]^1;
    for(int i=head[x];i;i=e[i].nxt){
    	int u=e[i].to;
        if(u==fa) continue;
        if(!ok[x]&&mx[x]!=inf) mn[u]=mn[x]-1,mx[u]=mx[x]+1;
        dfs(u,x);
        if(!flag) break;
        if(mx[u]==inf) continue;
        if(mx[x]==inf){
            mn[x]=mn[u]-1,mx[x]=mx[u]+1;
            continue;
        }
        if((mn[x]>mx[u]+1)||(mx[x]<mn[u]-1)){
            flag=false;
            break;
        }
        mn[x]=max(mn[x],mn[u]);
        mx[x]=min(mx[x],mx[u]);
    }
    if(mn[x]>mx[x]) flag=false;
}
