int n;
vector<int>graph[123456];
int k;
struct spread
{
	int left;
	int size;
	bool active;
	spread()
	{
		left = -1234567; size = 12345678;
		active = true;
	}
	spread(int le,int sz,bool ac = true)
	{
		left = le; size = sz;
		active = ac;
	}
	spread operator++()
	{
		--left;
		++size;
		return *this;
	}
	spread operator*(const spread& other)
	{
		if (left % 2 != other.left % 2 && left != -1234567 && other.left != -1234567)
		{
			return spread(0, 0, false);
		}
		int top = min((size - 1) * 2 + left, (other.size - 1) * 2 + other.left);
		int btm = max(left, other.left);
		if (top < btm)return spread(0, 0, false);
		return spread(btm, (top - btm) / 2 + 1);
	}
};

spread s[123456];
queue<pair<int, spread>>que;

int main(void)
{
	scanf("%d", &n);
	for (int i = 0; i < n - 1; ++i)
	{
		int a, b;
		scanf("%d %d", &a, &b);
		--a; --b;
		graph[a].push_back(b);
		graph[b].push_back(a);
	}
	scanf("%d", &k);
	for (int j = 0; j < k; ++j)
	{
		int v, p;
		scanf("%d %d", &v, &p);
		--v;
		s[v] = spread(p, 1);
		que.push({ v,s[v] });
	}
	while (!que.empty())
	{
		auto q = que.front(); que.pop();
		auto next = ++q.second;
		for (int vert : graph[q.first])
		{
			auto nsp = next * s[vert];
			if (!nsp.active)
			{
				return 0 * printf("No\n");
			}
			if (!(nsp.left == s[vert].left && nsp.size == s[vert].size))
			{
				s[vert] = nsp;
				que.push({ vert,s[vert] });
			}
		}
	}
	printf("Yes\n");
	for (int i = 0; i < n; ++i)
	{
		printf("%d\n", s[i].left);
	}
	return 0;
}

