const int N=100010;
int l[N],r[N],odd[N];
vector<int> g[N];
int col[N];
int n;
void dfs(int x,int fa){
	int la=-1,av=1;
	for (auto i:g[x]){
		if (i==fa) continue;
		dfs(i,x);
		if (odd[i]!=-1){
			av&=(la==-1||odd[i]==la);
			la=odd[i];
		}
	}
	if (!av){
		puts("No");
		exit(0);
	}
	l[x]=-1e9; r[x]=1e9; odd[x]=-1;
	for (auto i:g[x]){
		if (i==fa) continue;
		l[x]=max(l[x],l[i]-1);
		r[x]=min(r[x],r[i]+1);
		if (odd[i]!=-1) odd[x]=odd[i]^1;
	}
	if (l[x]>r[x]){
		puts("No");
		exit(0);
	}
	if (col[x]!=-1){
		if (odd[x]==-1){
			odd[x]=col[x]&1;
		}
		if ((col[x]&1)!=odd[x]){
			puts("No");
			exit(0);
		}
		if (l[x]>col[x]||r[x]<col[x]){
			puts("No");
			exit(0);
		}
		l[x]=r[x]=col[x];
	}
}
int m;
int val[N];
void color(int x,int fa){
	if (fa==0){
		for (int i=l[x]; i<=r[x]; ++i)
		if (odd[i]==-1||(i&1)==odd[i]){
			val[x]=i;
			break;
		}
	}
	else{
		if (l[x]<=val[fa]-1&&val[fa]-1<=r[x]) val[x]=val[fa]-1;
		else if (l[x]<=val[fa]+1&&val[fa]+1<=r[x]) val[x]=val[fa]+1;
	}
	for (auto i:g[x]){
		if (i==fa) continue;
		color(i,x);
	}
}
int main(){
	memset(col,-1,sizeof(col));
	scanf("%d",&n);
	for (int i=1; i<n; ++i){
		int x,y;
		scanf("%d%d",&x,&y);
		g[x].push_back(y);
		g[y].push_back(x);
	}
	scanf("%d",&m);
	for (int i=1; i<=m; ++i){
		int x,y;
		scanf("%d%d",&x,&y);
		col[x]=y;
	}
	dfs(1,0);
	puts("Yes");
	color(1,0);
	for (int i=1; i<=n; ++i) cout<<val[i]<<'\n';
}

#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
const int INF = 1 << 28;

vector<int> G[100000];
int X[100000];
int l[100000];
int r[100000];

bool dfs1(int v, int p, int mod) {
	if(X[v] != INF && X[v] % 2 != mod) return false;
	for(auto c : G[v]) {
		if(c == p) continue;
		if(!dfs1(c, v, 1 - mod)) return false;
	}
	return true;
}

bool dfs2(int v, int p) {
	for(auto c : G[v]) {
		if(c == p) continue;
		if(!dfs2(c, v)) return false;
		l[v] = max(l[v], l[c] - 1);
		r[v] = min(r[v], r[c] + 1);
		if(l[v] > r[v]) return false;
	}
	return true;
}

void dfs3(int v, int p) {
	for(auto c : G[v]) {
		if(c == p) continue;
		if(l[c] <= X[v] + 1 && X[v] + 1 <= r[c]) X[c] = X[v] + 1;
		if(l[c] <= X[v] - 1 && X[v] - 1 <= r[c]) X[c] = X[v] - 1;
		dfs3(c, v);
	}
}

int main() {
	cin.tie(0);
	ios::sync_with_stdio(false);

	int N, K;
	cin >> N;
	for(int i = 0; i < N - 1; i++) {
		int A, B;
		cin >> A >> B;
		A--, B--;
		G[A].push_back(B);
		G[B].push_back(A);
	}
	cin >> K;
	fill(X, X + N, INF);
	fill(l, l + N, -INF);
	fill(r, r + N, INF);

	int root = -1;
	for(int i = 0; i < K; i++) {
		int V;
		cin >> V;
		V--;
		cin >> X[V];
		l[V] = r[V] = X[V];
		if(root == -1) root = V;
	}

	if(!dfs1(root, -1, 0)) {
		cout << "No" << endl;
		return 0;
	}

	if(!dfs2(root, -1)) {
		cout << "No" << endl;
		return 0;
	}

	dfs3(root, -1);

