int lower = -1000000000;
int upper =  1000000000;

pii DFS(int v,bool isodd){
    used[v]=true;
    pii r = range[v];

    //自身のノードが設定されていて
    //偶奇条件を満たさない
    if(r != make_pair(lower,upper)) if(isodd&&r.second%2==0||!isodd&&r.second%2==1)return {upper,lower};

    REP(i,edge[v].size()){
        if(!used[edge[v][i]]){
            pii rec = DFS(edge[v][i],!isodd);
            r.first = max(r.first,rec.first-1);
            r.second= min(r.second,rec.second+1);
        }
    }
    if(r.first>r.second)return {upper,lower};
    return range[v] = r;
}

void write(int v,int pare){
    used[v]=true;
    num[v] = (pare+1 >=range[v].first && pare+1 <= range[v].second ? pare+1 : pare-1);
    REP(i,edge[v].size())if(!used[edge[v][i]])write(edge[v][i],num[v]);
}

