void dfs(int u, int p, int minp) {
    h[u] = h[p] + 1;
    int nminp = (l[u] == r[u] ? u : minp);
    l[u] = max(l[u], l[minp] - (h[u] - h[minp]) );
    r[u] = min(r[u], r[minp] + (h[u] - h[minp]) );
    for (int v : gr[u]) if(v != p) {
        dfs(v, u, nminp);
    }
}

void dfs2(int u, int p) {
    for (int v : gr[u]) if(v != p) {
        dfs2(v, u);
        if(l[v] == -inf || l[u] == -inf || (l[v] - l[u]) % 2 != 0) {
            l[u] = max(l[u], l[v] - 1);
            r[u] = min(r[u], r[v] + 1);
            if(l[u] > r[u]) { cout << "No"; exit(0); }
        }
        else { cout << "No"; exit(0); }
    }
}

void solve(int u, int p) {
    ans[u] = l[u];
    if(l[u] == -inf) ans[u] = ans[p] + 1;
    for (int v : gr[u]) if(v != p) solve(v, u);
}

