#define se second

#define INF 2147483600

vector<vector<int> > vec;
vector<int> num;
vector<pair<int, int> > memo;

bool check(int from, int d){
  if(num[d]!=-INF){
    memo[d].fi = memo[d].se = num[d];
  }
  if(from !=-1){
    memo[d].fi = memo[from].fi-1;
    memo[d].se = memo[from].se+1;
  }

  for(int to : vec[d]) if(to!=from){
    if( ! check(d, to) ) return false;
    memo[d].fi = max(memo[d].fi, memo[to].fi-1);
    memo[d].se = min(memo[d].se, memo[to].se+1);
    if(memo[d].fi > memo[d].se) return false;
  }
  if(memo[d].fi == memo[d].se){
    num[d] = memo[d].fi;
  }
  return true;
}

bool build(int from, int d){
  int lw, up;
  if(from==-1 || memo[d].fi==memo[d].se) lw = memo[d].fi, up=memo[d].se;
  else lw = num[from]-1, up=num[from]+1;
  for(int i=lw; i<=up; i++){
    num[d] = i;
    if(from!=-1 && abs(num[d]- num[from]) != 1){
      continue;
    }
    bool flg=true;
    for(int to : vec[d]) if(to != from){
      if( ! build(d, to)){
        flg=false;
        continue;
      }
    }
    if(flg){
      return true;
    }
  }
  return false;
}

int main(){
  int n;
  cin>>n;
  vec = vector<vector<int> >(n, vector<int>());
  num = vector<int>(n, -INF);
  memo = vector<pair<int, int> >(n, pair<int, int>(-INF, INF));
  rep(i,n-1){
    int a,b;
    scanf("%d %d", &a, &b);
    a--; b--;
    vec[a].pb(b);
    vec[b].pb(a);
  }
  int k; cin>>k;
  int ss;
  rep(i,k){
    int a,b;
    scanf("%d %d", &a, &b);
    a--;
    num[a]=b;
    memo[a]=mp(b,b);
    ss=a;
  }

  if(check(-1, ss) && build(-1,ss)){
    cout<<"Yes"<<endl;
    rep(i,n) printf("%d\n", num[i]);
  } else{
    cout<<"No"<<endl;
  }

  return 0;
}

