{
	scanf("%d",&n);
	for(int i=1;i<n;++i)
	{
		int u,v;scanf("%d%d",&u,&v);
		V[u].pb(v),V[v].pb(u);
	}
	for(int i=1;i<=n;++i)mx[i]=inf,mn[i]=-inf;
