pi intersect(pi i, pi j){
	return pi(max(i.f,j.f),min(i.s,j.s));
}
bool np = 0;

void dfs(int x,int p){
	par[x] = p;
	aFOR(i,adj[x]){
		if (i != p) dfs(i,x);
	}

	pi curRange = range[x];

	aFOR(i,adj[x]){
		if (range[i] == pi(-INF,INF) || i == p) continue;
		curRange = intersect(curRange,pi(range[i].f-1,range[i].s + 1));
		if (curRange.f > curRange.s) np = 1;
	}

	range[x] = curRange;
}
