void dfs2(int x,int val,int p){
	ans[x] = val;

	aFOR(i,adj[x]){
		if (i != p){
			if (val - 1 >= range[i].f && val - 1 <= range[i].s){
				dfs2(i,val-1,x);
			}else if (val + 1 >= range[i].f && val + 1 <= range[i].s){
				dfs2(i,val+1,x);
			}else{
				np = 1;
			}
		}
	}
}

void dfs3(int x,int p){
	aFOR(i,adj[x]){
		if (i != p) dfs3(i,x);
	}

	if (p != -1){
		range[x] = intersect(range[x],pi(range[par[x]].f-1,range[par[x]].s+1));
		if (range[x].f > range[x].s) np = 1;
	}
}

