void dfs(int r, int p) {
    parent[r] = p;
    for(int c : G[r]) {
        if(c != p) {
            child[r].push_back(c);
            dfs(c, r);
        }
    }
}
void build_rooted_tree(int root) {
    REP(i, N) child[i].clear();
    dfs(root, -1);
}

int ub[MAX_N];
int lb[MAX_N];
void set_bound(int v) {
    for(int c : child[v]) {
        set_bound(c);
    }
    if(value.count(v)) {
        lb[v] = ub[v] = value[v];
    } else {
        for(int c : child[v]) {
            if(lb[c] > INT_MIN) {
                lb[v] = max(lb[v], lb[c]-1);
            }
            if(ub[c] < INT_MAX) {
                ub[v] = min(ub[v], ub[c]+1);
            }
        }
    }
}

