template<class T> inline bool MX(T &l,const T &r){return l<r?l=r,1:0;}
template<class T> inline bool MN(T &l,const T &r){return l>r?l=r,1:0;}
const ll MOD=1e9+7;

struct Seg {
  int l;
  int r;
  int m;
};

int N;
int K;
bool fail = false;
int ans[114514];
int fed[114514];
Seg s[114514];
vector<int> es[114514];

Seg Merge(Seg a, Seg b) {
  if (a.m == 2) return b;
  if (b.m == 2) return a;
  if (a.m != b.m) return Seg{0, 0, 0};
  Seg ret{max(a.l, b.l), min(a.r, b.r), a.m};
  if ((2+ret.l%2)%2 != ret.m) ret.l++;
  return ret;
}

Seg Dfs(int v, int p) {
  s[v] = Seg{-MOD, MOD, 2};
  for (int u : es[v]) {
    if (u == p) continue;
    auto res = Dfs(u, v);
    res.l--;
    res.r++;
    if (res.m != 2) res.m ^= 1;
    s[v] = Merge(s[v], res);
  }

  if (s[v].r - s[v].l <= 0) fail = true;
  if (fed[v] >= 0) {
    if (s[v].m != 2) {
      if (s[v].l > fed[v]) fail = true;
      else if (s[v].r <= fed[v]) fail = true;
      else if (fed[v]%2 != s[v].m) fail = true;
    }
    if (fail) return s[v];

    s[v].l = fed[v];
    s[v].r = fed[v]+1;
    s[v].m = fed[v]%2;
  }

  //printf("v=%d: %d %d %d\n", v+1, s[v].l, s[v].r, s[v].m);
  return s[v];
}

void Dfs2(int v, int p) {
  if (fed[v] < 0) {
    Seg tmp = s[p];
    if (v != p) {
      tmp.m ^= 1;
      tmp.l--;
      tmp.r++;
    }

    s[v] = Merge(s[v], tmp);
    assert(s[v].r - s[v].l >= 1);
    ans[v] = s[v].l;
    if (s[v].m != (2+s[v].l%2)%2) ans[v]++;
    assert(ans[v] < s[v].r);

    s[v].l = ans[v];
    s[v].r = ans[v]+1;
    s[v].m = (2+ans[v]%2)%2;
  } else ans[v] = fed[v];

  for (int u : es[v]) {
    if (u == p) continue;
    Dfs2(u, v);
  }
}

int main() {
  scanf("%d", &N);
  rep(i, N-1) {
    int a, b;
    scanf("%d%d", &a, &b);
    --a;
    --b;
    es[a].eb(b);
    es[b].eb(a);
  }

  fill(fed, fed+N, -MOD);

  scanf("%d", &K);
  rep(i, K) {
    int v, p;
    scanf("%d%d", &v, &p);
    --v;
    fed[v] = p;
  }
  Dfs(0, 0);

  if (fail) {
    puts("No");
    return 0;
  }

  Dfs2(0, 0);

  puts("Yes");
  rep(i, N) {
    printf("%d\n", ans[i]);
  }
}

