		ret retv = check(to, v);
		if (!retv.first) return ret(false, range(-1, -1));
		l = max(l, retv.second.first);
		r = min(r, retv.second.second);
	}
	if (l > r) return ret(false, range(-1, -1));
	if (setv[v]) {
		if (l <= val[v] && val[v] <= r) {
			valr[v] = range(val[v], val[v]);
			return ret(true, range(val[v] - 1, val[v] + 1));
		}
		return ret(false, range(-1, -1));
	}
	valr[v] = range(l, r);
	return ret(true, range(l - 1, r + 1));
}
void assign(int v, int p) {
	if (!setv[v]) {
		if (valr[v].first <= val[p] + 1 && val[p] + 1 <= valr[v].second) val[v] = val[p] + 1;
		else val[v] = val[p] - 1;
	}
	for (int to : T[v]) {
		if (to == p) continue;
		assign(to, v);
	}
}
