	if (!retv.first) {
		cout << "No" << endl;
		return 0;
	}
	assign(root, -1);
	cout << "Yes" << endl;
	for (int i = 0; i < N; i++) {
		cout << val[i] << endl;
	}
}

#include <cstdio>
