using namespace std;

const int N=1e5+10;

struct Edge{ int to,next; };

Edge way[N<<1];
int n,tot,num[N],l[N],r[N],col[N],k;

void Build(int a,int b) { way[++tot]=(Edge){b,num[a]}; num[a]=tot; }

void Init()
{
	scanf("%d",&n);
	int a,b;
	for (int i=2;i<=n;++i)
	{
		scanf("%d%d",&a,&b);
		Build(a,b);
		Build(b,a);
	}
	for (int i=1;i<=n;++i) l[i]=-1e6,r[i]=1e6;
	scanf("%d",&k);
	for (int i=1;i<=k;++i)
	{
		scanf("%d%d",&a,&b);
		l[a]=r[a]=b;col[a]=b;
	}
}

void Dfs(int x,int fa)
{
	for (int i=num[x];i;i=way[i].next)
	{
		int v=way[i].to;
		if (v==fa) continue;
		l[v]=max(l[x]-1,l[v]);
		r[v]=min(r[x]+1,r[v]);
		Dfs(v,x);
	}
	if (fa)
	{
		l[fa]=max(l[x]-1,l[fa]);
		r[fa]=min(r[x]+1,r[fa]);
	}
}

bool use[2000010];
bool FindAns(int x,int fa)
{
	for (int i=num[x];i;i=way[i].next)
	{
		int v=way[i].to;
		if (l[v]==r[v]) use[l[v]+1000000]=1;
	}
	col[x]=l[x];
	while (use[col[x]+1000000] && col[x]<=r[x]) col[x]++;
	if (col[x]>r[x]) { col[x]=-1e7; return 0; }

	l[x]=r[x]=col[x];
	for (int i=num[x];i;i=way[i].next)
	{
		int v=way[i].to;
		if (l[v]==r[v]) use[l[v]+1000000]=0;
	}

	for (int i=num[x];i;i=way[i].next)
	{
		int v=way[i].to;
		if (v==fa) continue;
		l[v]=max(l[x]-1,l[v]);
		r[v]=min(r[x]+1,r[v]);
		if (!FindAns(v,x)) return 0;
	}
	return 1;

}

void Solve()
{
	Dfs(1,0);

	bool fl=1;
	for (int i=1;i<=n;++i) if (l[i]>r[i]) fl=0;

	if (!fl) printf("No\n");
	else 
	{
		fl=FindAns(1,0);
		if (!fl) { printf("No\n"); return ; }
		printf("Yes\n");
		for (int i=1;i<=n;++i) printf("%d\n",col[i]);
	}

}

int main()
{
	Init();
	Solve();
	return 0;
}

