using namespace std;
const int maxn = 1e5 + 5;
vector<int> G[maxn],order;
int n,known[maxn],val[maxn],l[maxn],r[maxn],k,used[maxn],known_parity[maxn][2],shit,par[maxn],ans[maxn];
void dfs(int v)
{
	used[v] = 1;
	l[v] = -1e9;
	r[v] = 1e9;
	for(int i = 0;i < G[v].size(); ++i)
	{
		int to = G[v][i];
		if(used[to]) continue;
		dfs(to);
		par[to] = v;
		if(known_parity[to][0]) known_parity[v][1] = 1;
		if(known_parity[to][1]) known_parity[v][0] = 1;
		l[v] = max(l[v],l[to] - 1);
		r[v] = min(r[v],r[to] + 1);
	}
	if(known[v] == 1)
	{
		l[v] = max(l[v],val[v]);
		r[v] = min(r[v],val[v]);
		known_parity[v][val[v] % 2] = 1;
	}
	if(known_parity[v][0] == 1 && known_parity[v][1] == 1) shit = 1;
	if(l[v] > r[v]) shit = 1;
	order.push_back(v);
}
int solve_val(int v,int par)
{
	if(par == 0) return l[v];
	l[v] = max(l[v],ans[par] - 1);
	r[v] = max(r[v],ans[par] + 1);
	while(l[v] % 2 == ans[par] % 2) ++l[v];
	return l[v];
}
int main(int argc, char const *argv[])
{
	cin>>n;
	for(int i = 0;i < n - 1; ++i)
	{
		int a,b;
		cin>>a>>b;
		G[a].push_back(b);
		G[b].push_back(a);
	}
	cin>>k;
	for(int i = 1;i <= k; ++i)
	{
		int a,b;
		cin>>a>>b;
		known[a] = 1;
		val[a] = b;
	}
	dfs(1);
	if(shit)
	{
		cout<<"No\n";
		return 0;
	}
	reverse(order.begin(),order.end());
	printf("Yes\n");
	for(int i = 0;i < order.size(); ++i)
	{
		int v = order[i];
		ans[v] = solve_val(v,par[v]);
	}
	for(int i = 1;i <= n; ++i) cout<<ans[i]<<endl;
	return 0;
}

