  if (V[v] != -1)
  {
    SL[v] = SR[v] = V[v];
  }

  FOR (i,0,SZ(G[v]))
  {
    int to = G[v][i];
    if (to == p) continue;
    init(to, v);
    SL[v] = max(SL[v], SL[to]-1);
