		G[u].pb(v); G[v].pb(u);
	}
	scanf("%d", &k); memset(ty, -1, sizeof ty);
	for(int i = 1; i <= k; ++i){
		int v, p; scanf("%d%d", &v, &p);
		res[v] = l[v] = r[v] = p; ty[v] = p & 1;
	}
	for(int i = 1; i <= n; ++i){
		if(ty[i] != -1) continue;
		l[i] = -1e9; r[i] = 1e9;
