  for(int u : G[v])if(u != p){
    dfs(u, v);

    int a, b;
    tie(a, b) = mem[u];

    --a, ++b;

    if (a <= -INF) continue;
    if (l <= -INF) {
      l = a, r = b;
      continue;
    }

    if (l % 2 != a % 2) throw 1;

    l = max(l, a);
    r = min(r, b);
    if (l > r) throw 1;
  }

  mem[v] = make_pair(l, r);
}

