    if (l <= res[p] + 1 && res[p] + 1 <= r) {
      res[v] = res[p] + 1;
    } else {
      res[v] = res[p] - 1;
    }
  }

  for(int u : G[v])if(u != p){
    fill(u, v);
  }
}

