using namespace std;
typedef long long ll;
typedef pair<int, int> ii;
typedef vector<int> vi;
typedef vector<ii> vii;
#define REP(i,n) for (int i = 0; i < n; ++i)
#define FORE(x,xs) for (auto x : xs)
#define PB(x) push_back(x)
#define MP(x, y) make_pair(x, y)

const int MAX = 1e5+10;

int N, K, root;
vi edges[MAX];
vi children[MAX];
int parent[MAX];
vi val;
vii range;
bool isOdd[MAX];

void makeTree(int n) {
    FORE (m, edges[n]) if (children[m].size() == 0) {
        children[n].PB(m);
        parent[m] = n;
        isOdd[m] = !isOdd[n];
        makeTree(m);
    }
}

bool dfs(int n) {
    int v = val[n];
    if (v != -1) {
        if (range[n].first <= v && v <= range[n].second && ((v&1) == isOdd[n])) {
            range[n] = MP(v,v);
        } else return false;
        FORE (m, children[n]) {
            range[m] = MP(v-1, v+1);
            if (!dfs(m)) return false;
        }
        range[parent[n]].first = max(range[parent[n]].first, v-1);
        range[parent[n]].second = min(range[parent[n]].second, v+1);
        if (parent)
        return true;
    } else if (children[n].size() == 0) {
        return true;
    } else {
        FORE (m, children[n]) {
            range[m] = MP(range[n].first-1, range[n].second+1);
            if (!dfs(m)) return false;
            range[parent[n]].first = max(range[parent[n]].first, range[n].first-1);
            range[parent[n]].second = min(range[parent[n]].second, range[n].second+1);
        }
        return true;
    }
}

void solution(int n) {
    int v = val[n];
    FORE (m, children[n]) {
        if (range[m].second >= v+1) {
            val[m] = v+1;
        } else {
            val[m] = v-1;
        }
        solution(m);
    }
