		}
		child[now].push_back(G[now][i]);
		make_family(now, G[now][i]);
	}
}

void dfs(int now) {
	if (child[now].size() == 0) {
		return;
	}
	int i;
	for (i = 0; i < child[now].size(); i++) {
		dfs(child[now][i]);
	}
