			}
			else {
				m = max(m, mM[u].first - 1);
				M = min(M, mM[u].second + 1);
			}
		}

	}
	if (m > M) {
		cout << "No" << endl;
		exit(0);
	}
	else if (mM[now].first == -inf) {
		mM[now].first = m;
		mM[now].second = M;
	}
	else if (m == -inf) {
		return;
	}
	else {
		if (abs(m % 2) != abs(mM[now].first % 2)) {
			cout << "No" << endl;
			exit(0);
		}
		else {
			if (m <= mM[now].first && mM[now].second <= M) {
				return;
			}
			else {
				cout << "No" << endl;
				exit(0);
			}
		}
	}
}

void solve(int now, int a) {
	for (int i = 0; i < child[now].size(); i++) {
		if (mM[child[now][i]].first <= a - 1) {
			ans[child[now][i]] = a - 1;
			solve(child[now][i], a - 1);
		}
		else {
			ans[child[now][i]] = a + 1;
			solve(child[now][i], a + 1);
		}
	}
	return;
}

