vector<int> adj[N];

void dfs (int node , int par , int exp) {
    in[node] = t++;
    if(val[node] == -1){
        v.push_back(INF - exp);
    }else{
        v.push_back(val[node]-exp);
    }
    for(int nxt : adj[node])
        if(nxt != par)
            dfs(nxt , node , exp-1);
    out[node] = t-1;
}

void solve(int node , int par){
    if (st->query(in[node] , out[node]) > 1)
        st->update(in[node] , out[node] , 2);

    for(int nxt : adj[node])
        if(nxt != par)
            solve(nxt , node);
}

