std::vector<std::vector<int>> edge;
std::vector<std::pair<int, int>> range;
std::vector<int> res;
constexpr int inf = std::numeric_limits<int>::max();
constexpr std::pair<int, int> all_ok(-1, -1);
constexpr std::pair<int, int> ng(inf, inf);


bool merge(std::pair<int, int>& x, const std::pair<int, int>& y){
    if(y == ng) return false;
    if(y == all_ok) return true; 
    if(x == all_ok){ x.first = y.first - 1; x.second = y.second + 1; return true; }
    if((x.first & 1) ^ (y.first & 1)){
        if(x.first  < y.first  - 1) x.first  = y.first  - 1;
        if(x.second > y.second + 1) x.second = y.second + 1;
        if(x.first > x.second){ x = ng; return false; }
        return true;
    }
    x = ng;
    return false;
}

bool dfs1(const int v, const int par = -1){
    for(const int nv : edge[v]) if(nv != par){
        dfs1(nv, v);
        if(not merge(range[v], range[nv])) return false;
    }
    return true;
}

void dfs2(const int v, const int par = -1){
    for(const int nv : edge[v]) if(nv != par){
        res[nv] = (range[nv].first <= res[v] - 1) ? res[v] - 1 : res[v] + 1;
        dfs2(nv, v);
    }
}

