  for(int i = 0; i < K; i++) {
    int V, P;
    cin >> V >> P;
    value[--V] = P;
  }
  calc(0, -1);
  dfs(0, (Data) {-1, INF});
  puts("Yes");
  for(int i = 0; i < N; i++) {
    cout << value[i] << endl;
  }
}

