bool ans;

void solve(int v,int p)
{
	l[v]=-INF-1;r[v]=INF+1;
	if(d[v]!=-1){
		l[v]=d[v];
		r[v]=d[v];
	}
	for(int i=0;i<g[v].size();i++){
		int nx=g[v][i];
		if(nx!=p){
			solve(nx,v);
			if(l[nx]<-INF/2) continue;
			if(l[v]<-INF/2){
				l[v]=l[nx]-1;
				r[v]=r[nx]+1;
			}
			else{
				if(abs(l[nx])%2==abs(l[v])%2){
					ans=true;
					return;
				}
				l[v]=max(l[v],l[nx]-1);
				r[v]=min(r[v],r[nx]+1);
			}
		}
	}
	if(l[v]>r[v]){
		ans=true;
	}
}

void make(int v,int p)
{
	if(v==1&&d[v]==-1) d[v]=l[v];
	for(int i=0;i<g[v].size();i++){
		int nx=g[v][i];
