bool DFS(int u, int parent) {
  if (parent >= 0) {
    range[u].first = max(range[u].first, range[parent].first - 1);
    range[u].second = min(range[u].second, range[parent].second + 1);
  }
  if (range[u].second < range[u].first) return false;
  for (auto& v : a[u]) {
    if (v == parent) continue;
    if (!DFS(v, u)) return false;
    range[u].first = max(range[u].first, range[v].first - 1);
    range[u].second = min(range[u].second, range[v].second + 1);
    if (range[u].second < range[u].first) return false;
  }
  return true;
}

bool DFS2(int u, int parent, int k) {
  if (parent >= 0) {
    range[u].first = max(range[u].first, ret[parent] - 1);
    range[u].second = min(range[u].second, ret[parent] + 1);
  }
  if ((range[u].first & 1) == k) {
    ret[u] = range[u].first;
  } else {
    if (range[u].first + 1 <= range[u].second) {
      ret[u] = range[u].first + 1;
    } else {
      return false;
    }
  }
  for (auto& v : a[u]) {
    if (v == parent) continue;
    if (!DFS2(v, u, 1 - k)) return false;
  }
  return true;
}

bool check(int n) {
  copy(range, range + n, old_range);
  if (DFS2(0, -1, 0)) return true;
  copy(old_range, old_range + n, range);
  if (DFS2(0, -1, 1)) return true;
  return false;
}

