void make(int x,int p){
	for(int i=0;i<nei[x].size();i++){
		if(nei[x][i]==p)continue;
		if(l[nei[x][i]]<=a[x]+1&&a[x]+1<=r[nei[x][i]]){
			a[nei[x][i]]=a[x]+1;
		}
		else{
			a[nei[x][i]]=a[x]-1;
		}
		make(nei[x][i],x);
	}
}

void dfs(int x,int p){
	if(a[x]!=-1){
		l[x]=r[x]=a[x];
	}
	for(int i=0;i<nei[x].size();i++){
		if(nei[x][i]==p)continue;
		dfs(nei[x][i],x);

		if(l[nei[x][i]]<-INF/2)continue; 
		if(l[x]<-INF/2){
			l[x]=l[nei[x][i]]-1;
			r[x]=r[nei[x][i]]+1;
			continue; 
		}

		if(abs(l[x])&1==abs(l[nei[x][i]])&1){
			shit();
		}

		l[x]=max(l[x],l[nei[x][i]]-1);
		r[x]=min(r[x],r[nei[x][i]]+1);
	}
	if(l[x]>r[x]){
		shit();
	}
	if(l[x]==r[x]){
		a[x]=l[x];
	}
}

