void solve2(int x, int par, P info){
    chmax(sm[x], info.first);
    chmin(bg[x], info.second);
    info.first--;
    info.second++;
    vector<int> sm1,sm2,bg1,bg2;
    for(auto&i:road[x]){
        if (i==par) {
            continue;
        }
        sm1.emplace_back(sm[i]-2);
        bg1.emplace_back(bg[i]+2);
    }
    sm2=sm1;
    bg2=bg1;
    REP(i,(int)sm1.size()-1){
        chmax(sm1[i], sm1[i-1]);
        chmin(bg1[i], bg1[i-1]);
    }
    REV_RREP(i, 1, (int)sm2.size()-1){
        chmax(sm2[i-1], sm2[i]);
        chmin(bg2[i-1], bg2[i]);
    }
    int cnt=0;
    rep(i,road[x].size()){
        if (road[x][i]==par) {
            continue;
        }
        P neo=info;
        if (cnt) {
            chmax(neo.first, sm1[cnt-1]);
            chmin(neo.second, bg1[cnt-1]);
        }
        if (cnt<(int)sm2.size()-1) {
            chmax(neo.first, sm2[cnt+1]);
            chmin(neo.second, bg2[cnt+1]);
        }
        cnt++;
        solve2(road[x][i], x, neo);
    }
}
