    if(i!=0&&p[i]!=-10000000&&p[q]!=-10000000&&abs(p[i]-p[q])>1) f=1;
    if(p[i]!=-10000000){
        m[i]=p[i];M[i]=p[i];
        for(auto j:v[i]) if(j!=q) dfs(j,i);
        return;
    }
    if(v[i].empty()) return;
    for(auto j:v[i]){if(j!=q){
        dfs(j,i);
        m[i]=max(m[i],m[j]-1);
        M[i]=min(M[i],M[j]+1);
    }}
    if(m[i]>M[i]) f=1;
}

