    if(i==0) ans[i]=m[i];
    for(auto j:v[i]){if(j!=q){
        if(m[j]==-10000000) ans[j]=ans[i]-1;
        else{
            for(int k=-1;k<=1;++k){
                if(m[j]<=ans[i]+k&&ans[i]+k<=M[j]){
                    ans[j]=ans[i]+k;
                    break;
                }
            }
        }
        dfs2(j,i);
    }}
}

