#define REPCLS(i,n) FORCLS(i,1,n)

const int MAX_N = 100005;
const int MAX_P = 1000005;
const int INF = 2 * MAX_P;
int n, k;

struct Node {
	vector<int> adjs;
	int low = -INF; // close range [low, high]
	int high = INF;
};
Node nodes[MAX_N];

// return: 条件を満たせるか？
bool dfs_setRange(int rootI, bool isEven, int parentI) {
	auto& rootNode = nodes[rootI];
	if (rootNode.low == -INF) {
		rootNode.low = isEven ? -INF : -INF - 1;
		rootNode.high = isEven ? INF : INF + 1;
	}
	else if ((rootNode.low % 2 == 0) != isEven){
		return false;
	}

	for (int childI : rootNode.adjs) if (childI != parentI) {
		bool childCond = dfs_setRange(childI, !isEven, rootI);
		if (childCond == false)	return false;

		int newLow = nodes[childI].low - 1;
		int newHigh = nodes[childI].high + 1;
		rootNode.low = max(rootNode.low, newLow);
		rootNode.high = min(rootNode.high, newHigh);
		if (rootNode.high < rootNode.low) return false;
	}

	return true;
}
void dfs_fix(int rootI, int parentI) {
	if (parentI == -1) {
		nodes[rootI].high = nodes[rootI].low;
	}
	else {
		int parentV = nodes[parentI].low;
		int l = parentV - 1;
		int h = parentV + 1;
		if (nodes[rootI].low <= l && l <= nodes[rootI].high) {
			nodes[rootI].low = nodes[rootI].high = l;
		}
		else {
			nodes[rootI].low = nodes[rootI].high = h;
		}
	}
	for (int childI : nodes[rootI].adjs) if (childI != parentI) {
		dfs_fix(childI, rootI);
	}
}

