void bfs() {
  rep(i, k) minv[vp[i].first] = maxv[vp[i].first] = vp[i].second;
  priority_queue<pair<int, int>> pq;
  rep(i, k) pq.push({d[vp[i].first], vp[i].first});
  while (pq.size()) {
    int v = pq.top().second;
    pq.pop();
    if (v == 0) continue;
    if (visited[v]) continue;
    visited[v] = true;
    chmax(minv[p[v]], minv[v] - 1);
    chmin(maxv[p[v]], maxv[v] + 1);
