int n,k,l[100000],r[100000],num[100000];
vector<int> G[100000];
bool flag = true;

void dfs(int v,int par){
	int mi = -INF,ma = INF;
	for(int to : G[v]){
		if(to == par) continue;
		dfs(to,v);
		mi = max(mi,l[to]);
		ma = min(ma,r[to]);
	}
	if(mi == -INF) return;
	mi--;ma++;
	if(l[v] != -INF){
		if(r[v] < mi || ma < l[v]) flag = false;
	}
	else{
		if(mi > ma) flag = false;
		l[v] = mi;
		r[v] = ma;
	}
}

void solve(int v,int par){
	if(par == -1){
		if(l[v] == -INF) num[v] = 0;
		else num[v] = l[v];
	}else{
		if(l[v] <= num[par] + 1 && num[par] + 1 <= r[v]) num[v] = num[par] + 1;
		else if(l[v] <= num[par] - 1 && num[par] - 1 <= r[v]) num[v] = num[par] - 1;
		else flag = false;
	}
	for(int to : G[v]) if(to != par) solve(to,v);
}

int main(){
