array<int, 2> merge(array<int, 2> a, array<int, 2> b) {
	if(a[0] == -1 && b[0] == -1) return a;
	if(a[0] == -1 || b[0] == -1) return b[0] == -1 ? array<int, 2>{a[0], a[1]} : array<int, 2>{b[0]-1, b[1]+1};
	if((a[0]^b[0]^1)&1) bad();
	return {max(a[0], b[0]-1), min(a[1], b[1]+1)};
}
void dfs(int v, int p) {
	for(auto i : g[v]) if(i != p) {
		dfs(i, v);
		dp[v] = merge(dp[v], dp[i]);
	}
	if(dp[v][0] > dp[v][1]) bad();
}
bool can(int v, int x) {
	return (dp[v][0] == -1) || (((dp[v][0]^x)&1) == 0 && x >= dp[v][0] && x <= dp[v][1]);
}
void rec(int v, int p) {
	for(auto i : g[v]) if(i != p) {
		c[i] = c[v]-1;
		if(!can(i, c[i])) c[i] += 2;
		rec(i, v);
	}
}
