#include <bits/stdc++.h>
using namespace std;

struct Tree
{
    int N;
    vector<vector<int>> adjacency_list;

    int root;
    vector<bool> marked;
    vector<int> marks;

    Tree(const int N) : N(N), adjacency_list(N), marked(N), marks(N) {}

    void add_edge(const int a, const int b)
    {
        adjacency_list[a].push_back(b);
        adjacency_list[b].push_back(a);
    }

    void mark_vertex(const int v, const int p)
    {
        root = v;
        marked[v] = true;
        marks[v] = p;
    }

    vector<int> solve()
    {
        const auto infinity = int(1e9);

        struct Interval { int lower, upper; };
        auto constraints = vector<Interval>(N);

        auto distances = vector<int>(N);

        function<void(int, int)> preprocess = [&](const int v, const int parent)
        {
            if (marked[v]) constraints[v] = {marks[v], marks[v]};
            else constraints[v] = {-infinity, infinity};

            for (const auto w : adjacency_list[v]) if (w != parent)
            {
                distances[w] = distances[v]+1;
                preprocess(w, v);
                constraints[v].lower = max(constraints[v].lower, constraints[w].lower-1);
                constraints[v].upper = min(constraints[v].upper, constraints[w].upper+1);
            }
        };
        preprocess(root, -1);

        for (auto v = 0; v < N; v++) if (marked[v])
            if (distances[v]%2 != abs(marks[v]-marks[root])%2)
                return {};

        auto is_consistent = true;
        function<void(int, int)> process = [&](const int v, const int parent)
        {
            auto found = false;
            if (v == root)
                found = constraints[v].lower <= marks[v] && marks[v] <= constraints[v].upper;
            else
            {
                for (const auto m : {marks[parent]-1, marks[parent]+1})
                {
                    if (constraints[v].lower <= m && m <= constraints[v].upper)
                    {
                        marks[v] = m;
                        found = true;
                    }
                }
            }

            if (!found)
            {
                is_consistent = false;
                return;
            }
            else
            {
                for (const auto w : adjacency_list[v]) if (w != parent)
                    process(w, v);
            }
        };
        process(root, -1);

        if (is_consistent) return marks;
        else return {};
    }
};

int main()
{
    ios::sync_with_stdio(false);

    int N; cin >> N;
    auto tree = Tree(N);
    for (auto i = 0; i < N-1; i++)
    {
        int a, b; cin >> a >> b;
        tree.add_edge(a-1, b-1);
    }

    int K; cin >> K;
    for (auto i = 0; i < K; i++)
    {
        int v, p; cin >> v >> p;
        tree.mark_vertex(v-1, p);
    }

    const auto answer = tree.solve();
    if (answer.empty()) cout << "No" << "\n";
    else
    {
        cout << "Yes" << "\n";
        for (const auto x : answer) cout << x << "\n";
    }
}

