    for (int i = 1, ps, x; i <= k; ++i) {
        scanf("%d %d", &ps, &x);
        L[ps] = R[ps] = x;
        root = ps;
    }

    d[root] = L[root] % 2;

    dfs(root, -1);
    dfs(root, -1);

