	for(int i = 0; i < sz; ++i){
		int v = G[u][i];
		if(v == fa) continue;
		if(ty[v] == -1) ty[v] = ty[u] ^ 1;
		else if(ty[v] == ty[u]){
			puts("No"); exit(0);
