		if(res[u] == -N){
			l[u] = max(l[v] - 1, l[u]);
			r[u] = min(r[u], r[v] + 1);
		}
		else if(l[v] - 1 > res[u] || r[v] + 1 < res[u]){
			puts("No"); exit(0);
		}
	}
	if(l[u] > r[u]){
		puts("No"); exit(0);
	}
	return ;
}

void solve(int u, int fa){
	if(res[u] == -N){
		if(res[fa] + 1 >= l[u] && res[fa] + 1 <= r[u]) res[u] = res[fa] + 1;
		else if(res[fa] - 1 >= l[u] && res[fa] - 1 <= r[u]) res[u] = res[fa] - 1;
		else{
			puts("No"); exit(0);
		}
