const int MAX_N = 100005, INF = 0x3f3f3f3f;
typedef pair<int, int> pii;

class Edge {
public:
  int nxt, to;
} e[MAX_N << 1];

int head[MAX_N], cnt;
void addedge(int u, int v) {
  e[++cnt] = (Edge){head[u], v}, head[u] = cnt;
  e[++cnt] = (Edge){head[v], u}, head[v] = cnt;
}

int rt, P[MAX_N];
bool flag;
pii intv[MAX_N];

void dfs(int u, int v, int d) {
  if (P[u] != INF) 
    if (((P[u] & 1) ^ d) != (P[rt] & 1)) flag = 0;

  int L = -INF, R = INF;

  for (int i = head[u]; i; i = e[i].nxt) 
    if (e[i].to != v) {
      dfs(e[i].to, u, d ^ 1);
      L = max(L, intv[e[i].to].first - 1);
      R = min(R, intv[e[i].to].second + 1);
    }
  if (L > R) flag = 0;
  if (P[u] != INF) {
    if (L > P[u] || R < P[u]) flag = 0;
    intv[u] = make_pair(P[u], P[u]);
  } else {
    intv[u] = make_pair(L, R);
  }
}

void dfs2(int u, int v) {
  for (int i = head[u]; i; i = e[i].nxt)
    if (e[i].to != v) {
      if (P[e[i].to] != INF) {
	dfs2(e[i].to, u);
      } else {
	if (P[u] - 1 >= intv[e[i].to].first && P[u] - 1 <= intv[e[i].to].second)
	  P[e[i].to] = P[u] - 1, dfs2(e[i].to, u);
	else
	  P[e[i].to] = P[u] + 1, dfs2(e[i].to, u);
      }
    }
}

