int n, m, a[N];
int tms, en[N], next[N], to[N];

void Link(int u, int v) {
	to[++tms] = v;
	next[tms] = en[u];
	en[u] = tms;
}

int fa[N], b[N], c[N];

void Dfs(int u) {
	if (~a[u]) 
		c[u] = (b[u] - a[u]) / 2;
	else
		c[u] = Inf;
	for (int p = en[u]; p; p = next[p]) {
		int v = to[p];
		if (!fa[v]) {
			fa[v] = u;
			b[v] = b[u] + 1;
			Dfs(v);
		}
	}
	if (~fa[u])
		c[fa[u]] = min(c[fa[u]], c[u]);
}

void Dfs(int u, int lst) {
	if ((~a[u] && a[u] != b[u] - lst * 2) || (a[u] == -1 && lst < c[u])) 
		++lst;
	b[u] -= lst * 2;
	for (int p = en[u]; p; p = next[p]) {
		int v = to[p];
		if (fa[v] == u) 
			Dfs(v, lst);
	}
}

