const int INF=1e7;

void bad(){
  cout<<"No\n";
  exit(0);
}

void dfs(int v,int p,int d){
  if(P[v]!=INF){
    if(P[v]%2!=d%2) bad();
  }
  for(auto u:G[v]) if(u!=p) dfs(u,v,d+1);
  return;
}

void dfs2(int v, int p){
  if(P[v]==INF) L[v]=-INF,R[v]=INF;
  else L[v]=R[v]=P[v];
  for(auto u:G[v]) if(u!=p){
    dfs2(u, v);
    if(P[v]==INF){
      L[v]=max(L[v],L[u]-1);
      R[v]=min(R[v],R[u]+1);
    }
  }
}

void dfs3(int v, int p){
  if(p!=-1){
    int ne[2]={P[p]+1,P[p]-1};
    bool flag=1;
    rep(i,2){
      if(L[v]<=ne[i]&&ne[i]<=R[v]){
        P[v]=ne[i];
        flag=0;
      }
    }
    if(flag) bad();
  }
  if(p!=-1){
    if(abs(P[p]-P[v])>1) bad();
  }
  for(auto u:G[v]) if(u!=p) dfs3(u,v);
}

