#include <bits/stdc++.h>

using namespace std;
const int inf = 0x3f3f3f3f;
const int N = 1e5 + 10;

int n, k;
vector<int> G[N];
int num[N];

int mx[N], mi[N], dep[N];
int l[N], r[N];

bool ok = 1;

void dfs(int u, int fa)
{
	if (num[u] != -1)
	{
		mx[u] = num[u] - dep[u];
		mi[u] = num[u] + dep[u];
	}
	else
	{
		mx[u] = -inf;
		mi[u] = inf;
	}
	for (int i = 0; i < (int) G[u].size(); i++)
	{
		int v = G[u][i];
		if (v == fa) continue;
		dep[v] = dep[u] + 1;
		dfs(v, u);
		mx[u] = max(mx[u], mx[v]);
		mi[u] = min(mi[u], mi[v]);
	}
}
void dfs2(int u, int fa)
{
	if (num[u] == -1)
	{
		if (fa == 0)
		{
			num[u] = l[u];
		}
		else if(l[u] <= num[fa] - 1 && num[fa] - 1 <= r[u])
		{
			num[u] = num[fa] - 1;
		}
		else if(l[u] <= num[fa] + 1 && num[fa] + 1 <= r[u])
		{
			num[u] = num[fa] + 1;
		}
		else
		{
			ok = 0;
			return;
		}
	}
	else
	{
		if (fa != 0 && abs(num[u] - num[fa]) != 1)
		{
			ok = 0;
			return;
		}
	}
	//printf("%d %d\n", u, num[u]);
	for (int i = 0; i < (int) G[u].size(); i++)
	{
		int v = G[u][i];
		if (v == fa) continue;
		dfs2(v, u);
	}
}
int main()
{
	scanf("%d", &n);
	for (int i = 1; i < n; i++)
	{
		int x, y;
		scanf("%d%d", &x, &y);
		G[x].push_back(y);
		G[y].push_back(x);
	}
	for (int i = 1; i <= n; i++)
	{
		num[i] = -1;
	}
	scanf("%d", &k);
	for (int i = 1; i <= k; i++)
	{
		int x, y;
		scanf("%d%d", &x, &y);
		num[x] = y;
	}
	dfs(1, 0);
	for (int i = 1; i <= n; i++)
	{
		l[i] = mx[i] + dep[i];
		r[i] = mi[i] - dep[i];
		//printf("%d %d %d %d\n", i, l[i], r[i], num[i]);
	}
	dfs2(1, 0);

	if (ok == 0)
	{
		puts("No");
	}
	else
	{
		puts("Yes");
		for (int i = 1; i <= n; i++) printf("%d\n", num[i]);
	}
	return 0;
}

