int main()
{
    int n, a, b;
    cin >> n;

    vector<vector<int> > tree(n);

    for (int i = 0; i < n-1; i++) {
        cin >> a >> b;
        tree[--a].push_back(--b);
        tree[b].push_back(a);
    }

    vector<int> data(n, INF);
    priority_queue<pair<int, int>, vector<pair<int, int> >,
        greater<pair<int, int> > > priQue;

    int k;
    cin >> k;
    for (int i = 0; i < k; i++) {
        cin >> a >> b;
        data[--a] = b;
        priQue.push(pair<int, int>(b, a));
    }

    while (!priQue.empty()) {
        pair<int, int> p = priQue.top();
        priQue.pop();
        for (int i = 0; i < tree[p.second].size(); i++) {
            if (data[tree[p.second][i]] == INF) {
                data[tree[p.second][i]] = data[p.second] + 1;
                priQue.push(pair<int, int>(data[tree[p.second][i]], 
                            tree[p.second][i]));
            }
        }
    }

    cout << "endWhile" << endl;


    for (int i = 0; i < n; i++) {
        for (int j = 0; j < tree[i].size(); j++) {
            if (abs(data[i] - data[tree[i][j]]) != 1) {
                cout << "No" << endl;
                return 0;
            }
        }
    }
    cout << "Yes" << endl;
    for (int i = 0; i < n; i++) {
        cout << data[i] << endl;
    }
    return 0;
}

#include "bits/stdc++.h"

using namespace std;

using ll = long long;
using PII = pair<int, int>;
constexpr int INF = numeric_limits<int>::max() / 2;

int N, K;
vector<int> V(100000), P(100000);
vector<int> l(100000, -INF), r(100000, INF), res(100000, -1);
vector<vector<int>> g(100000);
bool f = true;
int root = -1;

PII dfs(int cur, int pre, int dis)
{
    if (res[cur] != -1)
    {
        if (abs(res[cur] - res[root]) % 2 != dis % 2)
        {
            f = false;
        }
    }
    if (cur != root && g[cur].size() == 1)
    {
        return PII(l[cur], r[cur]);
    }
    int ltmp = l[cur], rtmp = r[cur];
    for (int v : g[cur])
    {
        if (v == pre)
            continue;
        PII p = dfs(v, cur, dis + 1);
        ltmp = max(ltmp, p.first-1);
        rtmp = min(rtmp, p.second+1);
    }
    // cout<<cur<<" "<<ltmp<<" "<<rtmp<<endl;
    if (ltmp > rtmp)
    {
        f = false;
    }
    else if (r[cur] < ltmp || rtmp < l[cur])
    {
        f = false;
    }
    l[cur] = ltmp;
    r[cur] = rtmp;
    return PII(l[cur], r[cur]);
}

void dfs2(int cur, int pre)
{
    if (res[cur] == -1)
    {
        int par = res[pre];
        if (l[cur] <= par + 1 && par + 1 <= r[cur])
        {
            res[cur] = par + 1;
        }
        else
        {
            res[cur] = par - 1;
        }
    }
    for (auto v : g[cur])
    {
        if (v == pre)
            continue;
        dfs2(v, cur);
    }
}

int main()
{
    cin.tie(0);
    ios::sync_with_stdio(false);

    cin >> N;
    for (int i = 0; i < N - 1; i++)
    {
        int a, b;
        cin >> a >> b;
        a--;
        b--;
        g[a].push_back(b);
        g[b].push_back(a);
    }
    cin >> K;
    for (int i = 0; i < K; i++)
    {
        cin >> V[i] >> P[i];
        V[i]--;
        l[V[i]] = P[i];
        r[V[i]] = P[i];
        res[V[i]] = P[i];
        root = V[i];
    }
    dfs(root, -1, 0);
    if (!f)
    {
        cout << "No" << endl;
        return 0;
    }
    dfs2(root, -1);
    cout << "Yes" << endl;
    for (int i = 0; i < N; i++)
        cout << res[i] << endl;
}

