int merge(int x,int y)
{
    if(a[y].FT == -INF)return 1;
    auto u = MP(a[y].FT-1,a[y].SD+1);
    //cout<<x<<" "<<y<<" "<<a[x].FT<<" "<<a[x].SD<<" "<<u.FT<<" "<<u.SD<<endl;
    if(a[x].FT == -INF)a[x] = u;
    else if((a[x].FT+u.FT)%2)return 0;
    else if(a[x].FT>u.SD||u.FT>a[x].SD)return 0;
    else
    {
        a[x].FT = max(a[x].FT,u.FT);
        a[x].SD = max(a[x].SD,u.SD);
    }
    return 1;
}
