bool valuable( pii p1 ){
	return p1.F <= p1.S;
}
pii operator+( pii p1 , pii p2 ){	// '+' means ∩(交集)
	pii ret;
	if( !valuable( p1 )  ||  !valuable( p2 ) )
		ret = mp( INF , -INF );
	else{
		if( p1.F > p2.F )
			swap( p1 , p2 );
		if( p1.S < p2.F )
			ret = mp( INF , -INF );
		else
			ret = mp( p2.F , min( p1.S , p2.S ) );
	}
	return ret;
}

