	if ((~a[u] && a[u] != b[u] - lst * 2) || (a[u] == -1 && lst < c[u])) 
		++lst;
	b[u] -= lst * 2;
	for (int p = en[u]; p; p = nxt[p]) {
		int v = to[p];
		if (fa[v] == u) 
			Dfs(v, lst);
	}
}

