pint get(pint a,pint b){
    if(a.first>b.first)swap(a,b);
    if(b.first==inf)return a;
    if(a.first==-inf)return a;
    if(a.second<b.first)return {-inf,-inf};
    if((a.first-b.first)%2)return {-inf,-inf};
    return {a.second,b.first};
}

