//頂点vから書き込みスタート
//val…vからdepだけ登った頂点で書き込まれた値, なければINF
//戻り値…頂点v以下の部分木で矛盾がないかどうか
bool dfs(int parent, int v, int val, int dep) {
	parents[v] = (parent == -1 ? v : parent);

	if (val != INF && num[v] != INF) {
		if (dep < abs(val - num[v]) || abs(val - num[v]) % 2 != dep % 2) return false;

		//depさかのぼる
		/*int tmp = dep;
		int id = v;
		for (int i = 0; i <= tmp; i++) {
			num[v] = ;
			*/
	}

	int i;
	bool ret = true;
	for (i = 0; i < et[v].size(); i++) {
		if (et[v][i] == parent) continue;
		if (num[v] == INF) ret &= dfs(v, et[v][i], val, dep + 1);
		else ret &= dfs(v, et[v][i], num[v], 1);
	}
	return ret;
}

