signed main(void) {
    ios::sync_with_stdio(false);
    cout.setf(ios::fixed, ios::floatfield);
    cout.precision(10);
    cin.tie(0);

    int n;
    cin >> n;
    VI a(n - 1), b(n - 1);
    REP(i, n - 1) {
        cin >> a[i] >> b[i];
        a[i]--;
        b[i]--;
    }
    int k;
    cin >> k;
    VI v(k), p(k);
    REP(i, k) {
        cin >> v[i] >> p[i];
        v[i]--;
    }


    VVI edge(n, VI());
    REP(i, n - 1) {
        edge[a[i]].PB(b[i]);
        edge[b[i]].PB(a[i]);
    }
    VI minp(n, 0), maxp(n, 0);
    vector<bool> check(n, false), check2(n, false);
    queue<PII> q, q2;
    REP(i, k) {
        minp[v[i]] = p[i];
        maxp[v[i]] = p[i];
        check[v[i]] = true;
        check2[v[i]] = true;
        q.push(MP(v[i],-1));
    }

    while (!q.empty()) {
        int t = q.front().FST;
        int prev = q.front().SND;
        q.pop();
        REP(i, edge[t].size()) {
            int next = edge[t][i];
            if(prev==next){
                continue;
            }
            if (check[next]) {
                if (maxp[next] <= minp[t] || maxp[t] <= minp[next] || (maxp[next] - maxp[t]) % 2 == 0) {
                    cout << "No" << ENDL;
                    return 0;
                } else {
                    maxp[next] = min(maxp[next], maxp[t] + 1);
                    minp[next] = max(minp[next], minp[t] - 1);
                    q2.push(MP(next,-1));
                    check[next] = true;
                }
            } else {
                check[next] = true;
                minp[next] = minp[t] - 1;
                maxp[next] = maxp[t] + 1;
                q.push(MP(next,t));
            }
        }
    }

    while (!q2.empty()) {
        int t = q2.front().FST;
        int prev = q2.front().SND;
        q2.pop();
        REP(i, edge[t].size()) {
            int next = edge[t][i];
            if(prev==next){
                continue;
            }
            if (!check[next]) {
                maxp[next] = min(maxp[next], maxp[t] + 1);
                minp[next] = max(minp[next], minp[t] - 1);
                q2.push(MP(next,t));
                check[next] = true;
            }
        }
    }

    cout << "Yes" << ENDL;

    REP(i,n){
        cout << maxp[i] << ENDL;
    }

    return 0;
}

