vector<ll> minval,maxval;

void dfs2(vector<vector<ll>> &g, ll v, ll p,ll d) {
	if(minval[v]!=-INF && minval[v]%2!=d%2){
		cout<<"No"<<endl;exit(0);
	}
	for(ll nextv : g[v]){
		if(nextv==p) continue;
		dfs2(g, nextv, v,d+1);
	}
}



void dfs(vector<vector<ll>> &g, ll v, ll p) {
	if(p!=-1){
		chmax(minval[v],maxval[p]-1);
		chmin(maxval[v],minval[p]+1);
	}

	//更新
	for(ll nextv : g[v]){
		if(nextv==p) continue;
		dfs(g, nextv, v);
	}
	//反映
	for(ll nextv : g[v]){
		if(nextv==p) continue;
		chmax(minval[v],minval[nextv]-1);
		chmin(maxval[v],maxval[nextv]+1);
	}
	if(minval[v]>maxval[v]){
		cout<<"No"<<endl;exit(0);
	}
}

void dfs3(vector<vector<ll>> &g, ll v, ll p,vector<ll> &ans) {
	if(p!=-1){
		ll t=ans[p]-1;
		if(minval[v]<=t)ans[v]=t;
		else ans[v]=t+2;
	}

	for(ll nextv : g[v]){	
		if(nextv==p) continue;
		dfs3(g, nextv, v, ans);
	}

}

void solve() {
	ll N;
	cin>>N;
	vector<vector<ll>> g(N);
	rep(i,N-1){
		ll a,b;
		cin>>a>>b;
		a--;b--;
		g[a].push_back(b);
		g[b].push_back(a);
	}
	ll K;
	cin>>K;
	minval.assign(N,-INF);
	maxval.assign(N,INF);
	ll v,p;
	rep(i,K){
		cin>>v>>p;
		v--;
		minval[v]=p;
		maxval[v]=p;
	}


	dfs2(g,v,-1,p);
	dfs(g,v,-1);

	vector<ll> ans(N,-INF);
	ans[v]=p;
	dfs3(g,v,-1,ans);
	cout<<"Yes"<<endl;
	rep(i,N){
		cout<<ans[i]<<endl;
	}

	debug(minval);
	debug(maxval);
}

