void add(int x,int y)
{
	cnt++;
	to[cnt]=y;
	nxt[cnt]=head[x];
	head[x]=cnt;
}
void dfs(int x,int fa)
{
	for (int i=head[x];i;i=nxt[i])
	{
		int y=to[i];
		if (y==fa)
		{
			continue;
		}
		d[y]=d[x]+1;
		dfs(y,x);
	}
}
void dfs2(int x,int fa)
{
	if (used[x])
	{
		l[x]=v[x];
		r[x]=v[x];
	}
	else
	{
		l[x]=-inf;
		r[x]=inf;
	}
	for (int i=head[x];i;i=nxt[i])
	{
		int y=to[i];
		if (y==fa)
		{
			continue;
		}
		dfs2(y,x);
		l[x]=max(l[x],l[y]-1);
		r[x]=min(r[x],r[y]+1);
	}
	if (l[x]>r[x])
	{
		puts("No");
		exit(0);
	}
}
void work(int x,int fa)
{
	if (!used[x])
	{
		if (v[fa]+1>=l[x] && v[fa]+1<=r[x])
		{
			v[x]=v[fa]+1;
		}
		else
		{
			v[x]=v[fa]-1;
		}
	}
	for (int i=head[x];i;i=nxt[i])
	{
		int y=to[i];
		if (y==fa)
		{
			continue;
		}
		work(y,x);
	}
}
