const int N = 1e5 + 10;
const int INF = 0x3f3f3f3f;
int n, a[N], m, f, wa;
vector<int> G[N];
struct Rg {
    int l, r;
}b[N];
Rg dfs(int fa, int u) {
    if(f) {
        if(a[u] == INF) {
            if(fa == 0) {
                a[u] = b[u].l;
            } else {
                for(int i = a[fa] - 1; i <= a[fa] + 1; i += 2) {
                    if(i >= b[u].l && i <= b[u].r) {
                        a[u] = i;
                        break;
                    }
                }
                // assert(a[u] > 0);
            }
        }
    }
    Rg rg = Rg{-INF, INF};
    if(a[u] != INF) {
        rg.l = rg.r = a[u];
    }
    for(int v : G[u]) {
        if(v != fa) {

            Rg tmp = dfs(u, v);
