void up(int x, int p)
{
    for(auto v : adj[x])
        if(v != p)
        {
            up(v, x);
            mivals[x].push_back({mivals[v][0].first - 1, v});
            mavals[x].push_back({mavals[v][0].first + 1, v});
            for(int j = 0; j < 2; j++)
                reqparity[j][x] |= reqparity[j ^ 1][v];
        }
    sort(mivals[x].begin(), mivals[x].end(), greater<pii>());
    sort(mavals[x].begin(), mavals[x].end());
}

void down(int x, int p, int parmi, int parma)
{
    if(p != -1)
    {
        mivals[x].push_back({parmi - 1, p});
        mavals[x].push_back({parma + 1, p});
        for(int j = 0; j < 2; j++)
            reqparity[j][x] |= reqparity[j ^ 1][p];
        sort(mivals[x].begin(), mivals[x].end(), greater<pii>());
        sort(mavals[x].begin(), mavals[x].end());
    }
    for(auto v : adj[x])
