            L[now]=val[now];
            R[now]=val[now];
        }else if(l<=val[now]&&val[now]<=r&&l%2==val[now]%2){
            L[now]=val[now];
            R[now]=val[now];
        }else fail();
    }
    return mkp(L[now]-1,R[now]+1);
}

