inline void prepare(){
	while(!q.empty()){
		int now = q.front(); q.pop(); root = now;
		for(int i = point[now].size() - 1; i >= 0; --i){
			int qwe = point[now][i]; deg[qwe]--;
			if(deg[qwe] == 1) q.push(qwe);
		}
	}
	node[root].deep = 1; node[root].fa = 0;
}

void build(int t){
	for(int i = point[t].size() - 1; i >= 0; --i){
		int now = point[t][i]; if(node[t].fa == now) continue;
		node[now].fa = t; node[now].deep = node[t].deep + 1; build(now);
	}
}

void dp(int t){
	for(int i = point[t].size() - 1; i >= 0; --i){
		int now = point[t][i]; if(now == node[t].fa) continue;
		dp(now); 
		node[t].l = max(node[t].l, node[now].l - 1); 
		node[t].r = min(node[t].r, node[now].r + 1);
	}
	if(node[t].l > node[t].r) flag = false;
}

void calc(int t){
	if(t != root){
		if(node[t].l <= node[node[t].fa].data + 1 && node[node[t].fa].data + 1 <= node[t].r) node[t].data = node[node[t].fa].data + 1;
		else node[t].data = node[node[t].fa].data - 1;
	}
	for(int i = point[t].size() - 1; i >= 0; --i){
		int now = point[t][i]; if(now == node[t].fa) continue;
		calc(now); 
	}
}

