using namespace std;

int n, k;
int res[N], l[N], r[N], ty[N];

vector < int > G[N];

void dfs(int ,int);
void solve(int ,int);

int main(){
	scanf("%d", &n);
	for(int i = 1; i < n; ++i){
		int u, v; scanf("%d%d", &u, &v);
		G[u].pb(v); G[v].pb(u);
	}
	scanf("%d", &k);
	memset(ty, -1, sizeof ty);
	for(int i = 1; i <= n; ++i) res[i] = -N;
	int pos;
	for(int i = 1; i <= k; ++i){
		int p; scanf("%d%d", &pos, &p);
		res[pos] = l[pos] = r[pos] = p; ty[pos] = p & 1;
	}
	for(int i = 1; i <= n; ++i){
		if(ty[i] != -1) continue;
		l[i] = -1e9; r[i] = 1e9;
	}
	dfs(pos, 0); solve(pos, 0); puts("Yes");
	for(int i = 1; i <= n; ++i)
		printf("%d\n", res[i]);
	return 0;
}

void dfs(int u, int fa){
	int sz = G[u].size();
	for(int i = 0; i < sz; ++i){
		int v = G[u][i];
		if(v == fa) continue;
		if(ty[v] == -1) ty[v] = ty[u] ^ 1;
		else if(ty[v] == ty[u]){
			puts("No"); exit(0);
		}
		dfs(v, u);
		if(res[u] == -N){
			l[u] = max(l[v] - 1, l[u]);
			r[u] = min(r[u], r[v] + 1);
		}
		else if(l[v] - 1 > res[u] || r[v] + 1 < res[u]){
			puts("No"); exit(0);
		}
	}
	if(l[u] > r[u]){
		puts("No"); exit(0);
	}
	return ;
}

void solve(int u, int fa){
	if(res[u] == -N){
		if(res[fa] + 1 >= l[u] && res[fa] + 1 <= r[u]) res[u] = res[fa] + 1;
		else if(res[fa] - 1 >= l[u] && res[fa] - 1 <= r[u]) res[u] = res[fa] - 1;
		else{
			puts("No"); exit(0);
		}
	}
	int sz = G[u].size();
	for(int i = 0; i < sz; ++i){
		int v = G[u][i];
		if(v == fa) continue;
		if(res[v] == -N) l[v] = max(l[u] - 1, l[v]), r[v] = min(r[u] + 1, r[v]);
		solve(v, u);
	}
	return ;
}

