const int N = 100000 + 10;
vector<int> g[N];
int color[N];

pair<int, int> r[N];

pair<int, int> rec(int curr, int prev, pair<int, int> p)
{
  if (color[curr] != -1) {
    if (abs(p.first  - color[curr]) % 2) throw "";
    if (abs(p.second - color[curr]) % 2) throw "";
    p = make_pair(color[curr], color[curr]);
  }

  each (next, g[curr]) {
    if (next == prev) continue;
    pair<int, int> q = make_pair(p.first - 1, p.second + 1);
    p = rec(next, curr, q);
  }
  //cout << curr+1 << ' ' << p << endl;
  r[curr] = p;
  pair<int, int> q = p.first != p.second ? make_pair(p.first + 1, p.second - 1) : p;
  return q;
}

void paint(int curr, int prev, int x)
{
  if (color[curr] == -1) color[curr] = x;
  each (next, g[curr]) {
    if (next == prev) continue;
    if (r[next].second < x + 1) {
      paint(next, curr, x + 1);
    } else {
      paint(next, curr, x - 1);
    }
  }
  return ;
}

