signed main(void){

  int N; cin >> N;

  if( N > 10000){ return 0;}//スキップ

  vector<bool> given(N,false);
  vector<vector<int>> to(N);
  for(int i = 0; i < MAX_N; i++){ low[i] = inf; high[i] = inf;}
  // infは未確定
  for(int i = 1; i < N; i++){ 
    int a,b; cin >> a >> b; a--; b--;
    to[a].push_back(b); to[b].push_back(a);
  }
  int K; cin >> K;
  int pos;
  for(int i = 0; i < K; i++){
    int v,p; cin >> v >> p; v--; pos = v;
    given[v] = true;
    low[v] = p; high[v] = p;
  } 
  bool contradiction = false;
  //ある確定した１つの頂点posからBFSで、残りの点と矛盾なく構成できるかを調べていく
  queue<tuple<int,int,int>> Q; Q.push(make_tuple(pos,low[pos],high[pos]));

  while(!Q.empty()){ 
    auto p = Q.front(); Q.pop();
    int v = get<0>(p);
    for(auto u : to[v]){ 
      if( low[u] != inf ){ //整合するかを確かめる
        int l = get<1>(p); int r = get<2>(p);
        if( !(l-1 <= low[u] && high[u] <= r+1) ){ //この時矛盾
          contradiction = true;break;
        }
        //整合していた場合には、何もする必要はない
      }
      else{ //まだ未到達だった場合

        low[u] = low[v]-1LL; high[u] = high[v]+1LL;
        Q.push(make_tuple(u,low[u],high[u]));
      }
    }//for-u
  }//while

  if(contradiction){ cout << "No" << endl; return 0;}
  // 以下、必ず構成できる場合に具体的に構成していく
  cout << "Yes" << endl;
  //ここまで問題なし

  for(int i = 0; i < N; i++){ 
    if(!given[i]){ continue;}
    // vから範囲を狭めていく
    vector<bool> visited(N,false); visited[i] = true;
    queue<int> Q; Q.push(i);
    while(!Q.empty()){ 
      auto p = Q.front(); Q.pop();
      for(auto u : to[p]){
        if(visited[u]){ continue;}
        visited[u] = true;
        low[u] = max(low[u],low[p]-1);
        high[u] = min(high[u],high[p]+1);
      }
    }
  }

  for(int i = 0; i < N; i++){ 
    cout << low[i] << endl;
  }


