int n,k,val[maxn],l[maxn],r[maxn];
int odd[maxn];
const int inf=0x3f3f3f3f;
bool ans=true;
void dfs(int x,int fa){
    if(v[x].size()==1&&val[x]==-1){
        l[x]=-inf,r[x]=inf;
        return;
    }
    else if(v[x].size()==1){
        l[x]=r[x]=val[x];
        return;
    }
    l[x]=-inf,r[x]=inf;
    bool f[2];
    f[0]=f[1]=false;
    for(auto y:v[x]){
        if(y!=fa&&odd[y]!=-1){
        	dfs(y,x);
	        l[x]=max(l[y]-1,l[x]);
	        r[x]=min(r[y]+1,r[x]);
	        f[odd[x]]=true;
        }
    }
    if(f[0]&&f[1]){
    	ans=false;
    	return;
    }
    if(l[x]>r[x]){
    	ans=false;
    	return;
    }
    if(odd[x]==-1){
    	if(!f[0]&&!f[1]) odd[x]=-1;
    	else if(f[0]) odd[x]=1;
    	else if(f[1]) odd[x]=0;
    	if(odd[x]!=-1&&l[x]==r[x]&&(r[x]%2+2)%2!=odd[x]) ans=false;
    	return;
    }
    else{
    	if(val[x]<l[x]||val[x]>r[x]) ans=false;
    	if(l[x]==r[x]&&l[x]!=val[x]) ans=false;
    	if(l[x]==r[x]&&(l[x]%2+2)%2!=odd[x]) ans=false;
    	if(!f[0]&&!f[1]){
    		l[x]=r[x]=val[x];
    	}
    	else if(f[0]){
    		if(odd[x]==0) ans=false;
    		l[x]=r[x]=val[x];
    	}
    	else if(f[1]){
    		if(odd[x]==1) ans=false;
    		l[x]=r[x]=val[x];
    	}
    }
}
