    read(x), read(y), addedge(x, y);
  int k; read(k);
  int rt;
  for (RI i = 1, x; i <= k; ++i) {
    read(x), read(a[x]), vis[x] = 1;
    if (i == 1) rt = x;
  }
  Dfs(rt, 0);
  puts("Yes");
  for (RI i = 1; i <= n; ++i)
    printf("%d\n", a[i]);

  return 0;
}

