		if(ty[u] == -1) ty[u] = ty[fa] ^ 1;
		else if(ty[u] == ty[fa]) {
			puts("No"); exit(0);
		}
	}
	int sz = G[u].size();
	for(int i = 0; i < sz; ++i){
