const int MAX_N = 128000;

int P[MAX_N];
int l[MAX_N], r[MAX_N], res[MAX_N];
vector<int> graph[MAX_N], g[MAX_N];
bool visited[MAX_N];

void make_graph(int v) {
  visited[v] = true;
  for (int i: graph[v]) {
    if (visited[i]) continue;
    g[v].push_back(i);
    make_graph(i);
  }
}

bool dfs(int v) {
  for (int i: g[v]) {
    if (!dfs(i)) return false;
  }
  l[v] = -1e9; r[v] = 1e9;
  for (int i: g[v]) {
    chmax(l[v], l[i] - 1);
    chmin(r[v], r[i] + 1);
  }
  for (int i: g[v]) {
    if (l[i] > -1e8 && ((l[v] + l[i]) & 1) == 0) return false;
  }
  if (l[v] > r[v]) return false;
  if (P[v] >= 0) {
    if (l[v] > -1e8 && ((l[v] + P[v]) & 1)) return false;
    if (P[v] < l[v] || P[v] > r[v]) return false;
    l[v] = P[v];
    r[v] = P[v];
  }
  // cout << v << " " << l[v] << " " << r[v] << endl;
  return true;
}

void dfs2(int v, int val) {
  res[v] = val;
  for (int i: g[v]) {
    if (val + 1 <= r[i]) dfs2(i, val + 1);
    else dfs2(v, val - 1);
  }
}

