using namespace std;
const int N = 100005, inf = 1e9;

int n, m, dep[N], v[N], s[N], e[N], r;
bool off;

vector<int> adj[N];

bool check (int C, int P) {
	dep[C] = dep[P] + 1;
	if(v[C] && (v[C]-v[r]+dep[C]-1)%2) return false;
	for(auto &T : adj[C]) {
		if(T == P) continue;
		if(!check(T, C)) return false;
	}
	return true;
}

void calc (int C, int P) {
	s[C] = -inf; e[C] = inf;
	if(v[C]) s[C] = e[C] = v[C];
	for(auto &T : adj[C]) {
		if(T == P) continue;
		calc(T, C);
		s[C] = max(s[C], s[T]-1);
		e[C] = min(e[C], e[T]+1);
	}
	if(s[C] > e[C]) off = true;
}

void solve (int C, int P) {
	v[C] = s[C];
	for(auto &T : adj[C]) {
		if(T == P) continue;
		s[T] = max(s[T], s[C]-1);
		e[T] = min(e[T], e[C]+1);
		solve(T, C);
	}
}

