			}
			l[u]=max(l[u],l[v]-1);
			r[u]=min(r[u],r[v]+1);
		}
	}
	if(l[u]>r[u]) ans=false;
	return;
}

void solve(int u,int p){
	if(u==0&&a[u]==-1) a[u]=l[u];
	FOR(i,0,g[u].size()){
