void DFS_init(int o, int f){
	if(L[o] == R[o] && L[o] % 2 != dep[o]){
		puts("No");
		exit(0);
	}
	for(int v : G[o]){
		if(v == f) continue;
		dep[v] = dep[o] ^ 1;
		DFS_init(v, o);
		L[o] = max(L[v] - 1, L[o]), R[o] = min(R[v] + 1, R[o]);
	}
	if(L[o] > R[o]){
		puts("No");
		exit(0);
	}
}

void DFS_work(int o, int f){
	R[o] = L[o];
	for(int v : G[o]){
		if(v == f) continue;
		L[v] = max(L[v], L[o] - 1), R[v] = min(R[v], R[o] + 1);
		DFS_work(v, o);
	}
}

