        mini[from] = max(mini[from], mini[to] - 1);
        if(checker[to] == 2) continue;
        if(checker[from] == 2){
            checker[from] = 1 - checker[to];
            continue;
        }
        if(checker[from] == checker[to]){
            checker[from] = -1;
            return;
        }
    }
    if(p[from] > -1){
        maxi[from] = min(p[from], maxi[from]);
        mini[from] = max(p[from], mini[from]);
    }
    if(maxi[from] < mini[from]){
        checker[from] = -1;
        return;
    }
    if(checker[from] == 2) return;
    if(maxi[from] % 2 != checker[from]) maxi[from]--;
    if(mini[from] % 2 != checker[from]) mini[from]++;
    if(maxi[from] < mini[from]){
        checker[from] = -1;
    }
    return;
}

void dfs3(int from){
    if(from == 1){
        ans[from] = maxi[from];
        for(int i = 0; i < children[from].size(); i++){
            dfs3(children[from][i]);
        }
        return;
    }
    int value = ans[parents[from]];
    if(maxi[from] >= value + 1){
        ans[from] = value + 1;
    } else {
        ans[from] = value - 1;
    }
    for(int i = 0; i < children[from].size(); i++){
        dfs3(children[from][i]);
    }
    return;
}

