VI dijkstra() {
    VI res(N + 1, INF);
    priority_queue<PII, VPII, greater<PII>> pq;
    pq.push({0, N});
    res[N] = 0;
    while (!pq.empty()) {
        int dist, now;
        tie(dist, now) = pq.top();pq.pop();
        if (res[now] < dist) continue;
        FORE(e, graph[now]) {
            int nd, nxt;
            tie(nd, nxt) = e;
            if (res[nxt] <= dist + nd) continue;
            res[nxt] = dist + nd;
            pq.push({res[nxt], nxt});
        }
    }
    return res;
}

