void check(int u, int fa) {
    l[u] = -inf - 1, r[u] = inf + 1;
    if(~ans[u]) l[u] = r[u] = ans[u];
    for(int i = head[u]; i; i = edge[i].nxt) {
        int v = edge[i].to;
        if(v != fa) {
            check(v, u);
            if(l[v] < -inf) continue;
            if(l[u] < -inf) {
                l[u] = l[v] - 1, r[u] = r[v] + 1;
            }
            else {
                if(abs(l[u])%2==abs(l[v])%2) {
                    flag = 0;
                    return;
                }
                l[u] = max(l[u], l[v] - 1);
                r[u] = min(r[u], r[v] + 1);
            }
