	vector<vector<long long int>>Tree( N, vector<long long int>( N, LLONG_MAX / 6 ) );
	for( size_t i = 0; i < N; i++ ) {
		Tree[i][i] = 0;
	}
	for( size_t i = 0; i < N - 1; i++ ) {
		long long int A, B;
		cin >> A >> B;
		A--; B--;
		Tree[A][B] = Tree[B][A] = 1;
	}
	for( size_t k = 0; k < N; k++ ) {
		for( size_t i = 0; i < N; i++ ) {
			for( size_t j = 0; j < N; j++ ) {
				Tree[i][j] = min( Tree[i][j], Tree[i][k] + Tree[k][j] );
				Tree[j][i] = Tree[i][j];
			}
		}
	}
	long long int M;
	cin >> M;
	vector<long long int>D( N, LLONG_MIN / 6 );
	vector<long long int>Amemo;
