		A--;
		D[A] = B;
		for( auto j : Amemo ) {
			long long int len = Tree[A][j];
			long long int sub = abs( B - D[j] );
			if( !(len >= sub&&len % 2 == sub % 2) ) {
				cout << "No" << endl;
				return 0;
			}
		}
		Amemo.push_back( A );
	}
	cout << "Yes" << endl;
