#define LLINF 2000000000000000000LL //2e18
#define SIZE 100010

int n;
vector<int> way[SIZE];
int num[SIZE],mi[SIZE],ma[SIZE];

bool flag = true;

pair<int,int> dfs(int now, int back, int p){

  //debug(p);
  //debug(num[now]);

  if(num[now] != -INF && p%2 != num[now]%2){
    flag = false;
    return make_pair(-INF,-INF);
  }

  //debug(now);

  int l = -SIZE-1, r = SIZE+1; //[l,r]

  if(num[now] != -INF){
    p = num[now];
    l = r = num[now];
  }

  for(int i=0;i<way[now].size();i++){
    if(way[now][i] == back) continue;
    pair<int,int> ret = dfs(way[now][i], now, p+1);

    if(ret.first == -INF) return ret;

    ret.first--;
    ret.second++;


    if(ret.second < l || r < ret.first){
      flag = false;
      return make_pair(-INF,-INF);
    }

    l = max(ret.first,l);
    r = min(ret.second,r);
  }

  mi[now] = l;
  ma[now] = r;

  return make_pair(l,r);
}

void dfs2(int now, int back, int back_p){

  if(num[now] == -INF){

    if(mi[now] <= back_p-1 && back_p-1 <= ma[now]){
      num[now] = back_p-1;
    }else{
      num[now] = back_p+1;
    }
  }

  for(int i=0;i<way[now].size();i++){
    if(way[now][i] == back) continue;
    dfs2(way[now][i], now, num[now]);
  }

}

