vector<int> lift_edge[MAX_N];
int level[MAX_N];
vector< p > sec;
vector<int> num;

p overlap(p &a, p &b) {
    int l = max(a.first,b.first);
    int r = min(a.second,b.second);
    p ret = p(l,r);
    if (r<l) {
        cout << "No" << endl;
        exit(0);
    }
    return ret;
}

void makeTree(int node, int pre) {
    level[node] = level[pre]+1;
    for(auto x:edge[node]) {
        if(level[x]==-1) {
            tree_edge[node].pb(x);
            lift_edge[x].pb(node);
            makeTree(x,node);
        }
    }
}

void lift(int node,p &pre){
    //if (level[node]) return;
    p ret = p(pre.first-1,pre.second+1);
    sec[node] = overlap(sec[node], ret);
    if (lift_edge[node].size()==0) return;
    // 同じ処理を省く
    if (ret.first==ret.second) level[node]=1;
    lift(lift_edge[node][0],sec[node]);
}

void decend(int node, p &pre) {
    p ret = p(pre.first-1,pre.second+1);
    ret = overlap(ret, sec[node]);
    num[node] = ret.first;
    ret = p(num[node],num[node]);
    for (auto x: tree_edge[node]) {
        decend(x, ret);
    }
}

int main(){
    ios::sync_with_stdio(false);
    cin >> N;
    num.resize(N,INF);
    REP(i,N-1) {
        int a,b;
        cin >> a >> b;
        a--;b--;
        edge[a].pb(b);
        edge[b].pb(a);
    }
    cin >> K;
    int st = 0;
    REP(i,K) {
        int v, p;
        cin >> v >> p;
        v--;
        num[v]=p;
        if (i==0) {
            st = v;
        }
    }

    fill(level,level+N+1,-1);
    makeTree(st,N);
    REP(i,N) edge[i].resize(0);
    fill(level,level+N+1,0);

    //　偶奇のチェック
    REP(i,N) {
        if(num[i]!=INF) {
            if(level[i]%2) {
                if(num[i]%2==num[st]%2) {
                    cout << "No" << endl;
                    return 0;
                }
            }
            else {
                if(num[i]%2!=num[st]%2) {
                    cout << "No" << endl;
                    return 0;
                }
            }
        }
    }

    // 区間を決める
    sec.resize(N);
    REP(i,N) {
        if(num[i]!=INF) sec[i]=p(num[i],num[i]);
        else sec[i]=p(-INF,INF);
    }

    REP(i,N) {
        if(tree_edge[i].size()==0) {
            p tmp = p(-INF,INF);
            lift(i,tmp);
        }
    }

    p tmp = p(-INF,INF);
    decend(st,tmp);

    cout << "Yes" << endl;
    REP(i,N) {
        cout << num[i] << endl;
    }

    return 0;
}

