using namespace std;

const int N = 1e5 + 7;
const int INF = 1e9 + 239;

int v[N];
vector<int> g[N];
pair<int, int> dp[N];

void dfs(int cur, int p) {
	int l = -INF;
	int r = INF;
	for (auto t : g[cur]) {
		if (t != p) {
			dfs(t, cur);
			if (dp[t].first != -INF) {
				l = max(l, dp[t].first - 1);
				r = min(r, dp[t].second + 1);
			}
		}
	}
	if (l > r) {
		cout << -1 << endl;
		exit(0);
	}
	if (l == -INF && r == INF && v[cur] != -1) {
		l = v[cur];
		r = v[cur];
	}
	if (v[cur] != -1 && (l - v[cur]) % 2) {
		cout << -1 << endl;
		exit(0);
	}
	if (v[cur] != -1 && (v[cur] < l || r < v[cur])) {
		cout << -1 << endl;
		exit(0);
	}
	dp[cur] = {l, r};
}

int ans[N];

void jfs(int cur, int p, int val) {
	ans[cur] = val;
	for (auto t : g[cur]) {
		if (t != p) {
			for (auto dt : {-1, 1}) {
				if (dp[t].first <= ans[cur] + dt && ans[cur] + dt <= dp[t].second) {
					jfs(t, cur, ans[cur] + dt);
					break;
				}
			}
		}
	}
}

signed main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);

	int n;
	cin >> n;
	for (int i = 0; i + 1 < n; i++) {
		int a, b;
		cin >> a >> b;
		a--;
		b--;
		g[a].push_back(b);
		g[b].push_back(a);
	}
	fill(v, v + n, -1);
	int k;
	cin >> k;
	while (k--) {
		int tv, val;
		cin >> tv >> val;
		tv--;
		v[tv] = val;
	}
	dfs(0, -1);
	jfs(0, -1, dp[0].first);
	for (int i = 0; i < n; i++) {
		cout << ans[i] << ' ';
	}
	cout << '\n';
}

