using namespace std;
typedef pair<long long int, long long int> P;

long long int INF = 1e18;
long long int MOD = 1e9 + 7;

vector<int> E[110000];
long long int val[110000];
P lim[110000];

P check1(int pos, int pre){
	long long int n1 = -INF, n2 = INF;
	long long int rem = -1;
	for(int to : E[pos]){
		if(to == pre){
			continue;
		}
		P ret = check1(to, pos);
		if(ret.second == INF){
			continue;
		}
		ret.first -= 1;
		ret.second += 1;

		if(rem == -1){
			rem = ret.second % 2;
		}else if(rem != ret.second % 2){
			return P(INF, -INF);
		}
		n1 = max(n1, ret.first);
		n2 = min(n2, ret.second);
	}
	if(val[pos] != INF){
		if(n2 != INF && val[pos] % 2 != n2 % 2){
			return P(INF, -INF);
		}
		n1 = max(n1, val[pos]);
		n2 = min(n2, val[pos]);
	}
	if(n1 > n2){
		return P(INF, -INF);
	}
	lim[pos] = P(n1, n2);
	return P(n1, n2);
}

void check2(int pos, int pre, long long int num){
	lim[pos].second = min(lim[pos].second, num);
	for(int to : E[pos]){
		if(to == pre){
			continue;
		}
		check2(to, pos, lim[pos].second + 1);
	}
}

int main(){
	int N;
	cin >> N;
	for(int i = 0; i < N - 1; i++){
		int A, B;
		cin >> A >> B;
		E[A].push_back(B);
		E[B].push_back(A);
	}
	for(int i = 0; i <= N; i++){
		val[i] = INF;
		lim[i] = P(INF, -INF);
	}
	int K;
	cin >> K;
	for(int i = 0; i < K; i++){
		int v, p;
		cin >> v >> p;
		val[v] = p;
	}
	P ret = check1(1, -1);
	if(ret.second == -INF){
		cout << "No" << endl;
		return 0;
	}
	check2(1, -1, lim[1].second);
	cout << "Yes" << endl;
	for(int i = 1; i <= N; i++){
		cout << lim[i].second << endl;
	}
  return 0;
}

