pii merge(pii p1, pii p2){
	if(p1.se%2!=p2.se%2) return {inf,inf};

	if(p1.fi > p2.fi) swap(p1,p2);
	if(p1.se >= p2.fi) return {max(p1.fi,p2.fi), min(p1.se,p2.se)};
	else return {inf,inf};
}

void dfs(int p,int u){
	par[u] = p;
	if(u!=p){
		if(num[u]==-1) range[u] = {range[p].fi-1,range[p].se+1};
		else{
			int ptr = u;
			while(num[par[ptr]]==-1){
				range[par[ptr]] = merge(range[par[ptr]], {range[ptr].fi - 1, range[ptr].se + 1});
//				if(range[par[ptr]]==make_pair(inf,inf)) cout << "No", exit(0);
				ptr = par[ptr];
			}
		}
	}
	for(auto v:g[u]) if(v!=p) dfs(u,v);
}

void trace(int p, int u, int res){
	ans[u] = res;
	for(auto v:g[u])
		if(v!=p) trace(u,v,max(res-1,range[v].fi));
}

