/*
	树, 我首先指定根
	每一个点的值由它下面点的值确定 (一个区间)
	当然, 奇偶性也得确定
	下面没点, 由上面的值确定
*/
#include <bits/stdc++.h>
#define N 100005

using namespace std;

int n, m;
int fa[N];
int head[N], nex[N << 1], to[N << 1], te;
int l[N], r[N], isOdd[N], val[N];

inline void read(int &x) {
	x = 0; bool sgn = false; char ch = getchar();
	while(!isdigit(ch)) (ch == '-') && (sgn = true), ch = getchar();
	while(isdigit(ch)) x = x * 10 + ch - '0', ch = getchar();
	if(sgn) x = -x;
}
inline void ade(int u, int v) {
	nex[++te] = head[u], head[u] = te, to[te] = v;
}

void dfs_1(int u) {
	if(~isOdd[u]) {
		l[u] = r[u] = val[u];
	} else {
		l[u] = -1e9, r[u] = 1e9;
	}

	for(int i = head[u], ll, rr; i; i = nex[i]) {
		int v = to[i];
		if(v == fa[u]) continue;
		fa[v] = u, dfs_1(v);
		if(~isOdd[v]) {
			ll = l[v] - 1, rr = r[v] + 1;
			if(isOdd[v] == isOdd[u] || l[u] > rr || r[u] < ll) {
				puts("No");
				exit(0);
			}
			if(!~isOdd[u]) isOdd[u] = isOdd[v] xor 1;
			l[u] = max(l[u], ll), r[u] = min(r[u], rr);
		}
	}
	return;
}

inline bool check(int u, int v) {
	return !~isOdd[u] ||
		   isOdd[u] == (v & 1) && 
		   l[u] <= v && v <= r[u];
}
void dfs_2(int u) {
	if(!val[u]) {
		if(check(u, val[fa[u]] + 1)) {
			val[u] = val[fa[u]] + 1;
		} else if(check(u, val[fa[u]] - 1)) {
			val[u] = val[fa[u]] - 1;
		} else {
			puts("No");
			exit(0);
		}
	}
	for(int i = head[u]; i; i = nex[i]) {
		int v = to[i];
		if(v == fa[u]) continue;
		dfs_2(v);
	}
	return;
}

int main() {
	read(n);
	for(int i = 1, u, v; i < n; ++i) {
		read(u), read(v);
		ade(u, v), ade(v, u);
	}
	read(m);
	memset(isOdd, -1, sizeof isOdd);
	for(int i = 1, u; i <= m; ++i) {
		read(u), read(val[u]);
		isOdd[u] = val[u] & 1;
	}
	dfs_1(1);

//	for(int i = 1; i <= n; ++i)
//		printf("%d : %d %d\n", i, l[i], r[i]);

	val[0] = l[1] - ((l[1] & 1) == isOdd[1]);

	dfs_2(1);
	puts("Yes");
	for(int i = 1; i <= n; ++i)
		printf("%d\n", val[i]);
	return 0;
}

#include <bits/stdc++.h>
using namespace std;

typedef long long LL;
