const int MAXN = (int) 1e5 + 10;
const int MAXA = (int) 1e9;
int n, k, a[MAXN], h[MAXN];
vector<int> adj[MAXN];

struct Range {
	int l, r;
	Range() {};
	Range(int l, int r): l(l), r(r) {};
	friend Range Merge(Range A, Range B) {
		Range C;
		C.l = max(A.l, B.l);
		C.r = min(A.r, B.r);
		return C;
	}
} f[MAXN], g[MAXN];

void DFS(int u, int p = -1) {
	if (a[u] != -1) g[u] = Range(a[u], a[u]); else g[u] = Range(0, MAXA);
	for (int i = 0; i < (int) adj[u].size(); ++i) {
		int v = adj[u][i];
		if (v != p) {
			h[v] = h[u] ^ 1;
			DFS(v, u);
			g[u] = Merge(g[u], Range(g[v].l - 1, g[v].r + 1));
		}
	}
}

void Compute(int u, int p = -1) {
	if (p != -1) f[u] = Merge(Range(f[p].l - 1, f[p].r + 1), g[u]);
	else f[u] = g[u];
	for (int i = 0; i < (int) adj[u].size(); ++i) {
		int v = adj[u][i];
		if (v != p) Compute(v, u);
	}
}

void Write(int u, int p = -1) {
	if (a[u] == -1) {
		if (f[u].l <= a[p] - 1) a[u] = a[p] - 1;
		else a[u] = a[p] + 1;
	}
	for (int i = 0; i < (int) adj[u].size(); ++i) {
		int v = adj[u][i];
		if (v != p) Write(v, u);
	}
}

int main() {
	scanf("%d", &n);
	for (int i = 1; i <= n - 1; ++i) {
		int u, v; scanf("%d%d", &u, &v);
		adj[u].push_back(v);
		adj[v].push_back(u);
	}

	int root = -1; scanf("%d", &k);
	for (int i = 1; i <= n; ++i) a[i] = -1;
	for (int i = 1; i <= k; ++i) {
		int u, x; scanf("%d%d", &u, &x);
		root = u; a[u] = x;
	}

	h[root] = a[root] % 2;
	DFS(root);
	Compute(root);

	for (int i = 1; i <= n; ++i) {
		int flag = 1;
		flag &= (f[i].l <= f[i].r);
		if (a[i] != -1) {
			flag &= (f[i].l <= a[i] && a[i] <= f[i].r);
			flag &= (a[i] % 2 == h[i]);
		}
		if (flag == 0) {
			puts("No");
			return 0;
		}
	}

	Write(root); puts("Yes");
	for (int i = 1; i <= n; ++i) printf("%d\n", a[i]);
	return 0;
}

