			res = res * 10 + c - 48;
		return res * Q;
}

struct power
{
		int l, r;
}val[ONE];

int n, k;
int x, y;
int pd[ONE];
int next[ONE], first[ONE], go[ONE], tot;

void Add(int u, int v)
{
		next[++tot] = first[u], first[u] = tot, go[tot] = v;
		next[++tot] = first[v], first[v] = tot, go[tot] = u;
}

void dfs(int u, int father)
{
		if(val[u].l == val[u].r) pd[u] = val[u].l % 2;
		for(int e = first[u]; e; e = next[e])
		{
			int v = go[e];
			if(v == father) continue;
			dfs(v, u);
			if(pd[v] == 2) continue;
			if(pd[u] == 2) {pd[u] = pd[v] ^ 1; continue;}
			if(pd[u] != (pd[v] ^ 1)) {printf("No"); exit(0);}
		}
}

void dfs1(int u, int father)
{
		for(int e = first[u]; e; e = next[e])
		{
			int v = go[e];
			if(v == father) continue;
			dfs1(v, u);
			val[u].l = max(val[u].l, val[v].l - 1);
			val[u].r = min(val[u].r, val[v].r + 1);
			if(val[u].l > val[u].r) {printf("No"); exit(0);}
		}
}

int A[ONE];

void dfs2(int u, int father)
{
		if(!(val[u].l <= A[u] && A[u] <= val[u].r)) {printf("No"); exit(0);}
		for(int e = first[u]; e; e = next[e])
		{
			int v = go[e];
			if(v == father) continue;
			if(val[v].l <= A[u] - 1 && A[u] - 1 <= val[v].r) A[v] = A[u] - 1;
			if(val[v].l <= A[u] + 1 && A[u] + 1 <= val[v].r) A[v] = A[u] + 1;
			dfs2(v, u);
		}
}

int main()
{
		n = get();
		for(int i = 1; i < n; i++) x = get(), y = get(), Add(x, y);
		for(int i = 1; i <= n; i++) val[i] = (power){-INF, INF}, pd[i] = 2;
		k = get();
		for(int i = 1; i <= k; i++) x = get(), y = get(), val[x] = (power){y, y};

		dfs(1, 0);
		dfs1(1, 0);

		A[1] = val[1].l;
		if(pd[1] != 2 && A[1] % 2 != pd[1]) A[1]++;

		dfs2(1, 0);

		printf("Yes\n");
		for(int i = 1; i <= n; i++)
			printf("%d\n", A[i]);
}

#include <bits/stdc++.h>
using namespace std;

#define REP(i,n) for(ll i=0; i<(ll)(n); i++)
#define FOR(i,n,m) for (ll i=n; i<(ll)(m); i++)
#define pb push_back
#define INF 1000000007LL
#define all(a) (a).begin(),(a).end()

typedef long long ll;
typedef pair<int,int> p;

int dy[4]={-1,1,0,0};
int dx[4]={0,0,1,-1};

#define MAX_N 100100
int N,K;
vector<int> edge[MAX_N];
vector<int> tree_edge[MAX_N];
vector<int> lift_edge[MAX_N];
unordered_map<int ,unordered_map<int, unordered_map<int, int> > > dp;
int level[MAX_N];
vector< p > sec;
vector<int> num;

p overlap(p &a, p &b) {
    int l = max(a.first,b.first);
    int r = min(a.second,b.second);
    p ret = p(l,r);
    if (r<l) {
        cout << "No" << endl;
        exit(0);
    }
    return ret;
}

void makeTree(int node, int pre) {
    level[node] = level[pre]+1;
    for(auto x:edge[node]) {
        if(level[x]==-1) {
            tree_edge[node].pb(x);
            lift_edge[x].pb(node);
            makeTree(x,node);
        }
    }
}

void lift(int node,p &pre){
    if (level[node]) return;
    if (dp[node][pre.first][pre.second]) return;
    dp[node][pre.first][pre.second]=1;
    p ret = p(pre.first-1,pre.second+1);
    sec[node] = overlap(sec[node], ret);
    if (ret.first==ret.second) level[node]=1;
    if (lift_edge[node].size()==0) return;
    // 同じ処理を省く
    lift(lift_edge[node][0],sec[node]);
}

void decend(int node, p &pre) {
    p ret = p(pre.first-1,pre.second+1);
    ret = overlap(ret, sec[node]);
    num[node] = ret.first;
    ret = p(num[node],num[node]);
    for (auto x: tree_edge[node]) {
        decend(x, ret);
    }
}

int main(){
    ios::sync_with_stdio(false);
    cin >> N;
    num.resize(N,INF);
    REP(i,N-1) {
        int a,b;
        cin >> a >> b;
        a--;b--;
        edge[a].pb(b);
        edge[b].pb(a);
    }
    cin >> K;
    int st = 0;
    REP(i,K) {
        int v, p;
        cin >> v >> p;
        v--;
        num[v]=p;
        if (i==0) {
            st = v;
        }
    }

    fill(level,level+N+1,-1);
    makeTree(st,N);
    REP(i,N) edge[i].resize(0);


    //　偶奇のチェック
    REP(i,N) {
        if(num[i]!=INF) {
            if(level[i]%2) {
                if(num[i]%2==num[st]%2) {
                    cout << "No" << endl;
                    return 0;
                }
            }
            else {
                if(num[i]%2!=num[st]%2) {
                    cout << "No" << endl;
                    return 0;
                }
            }
        }
    }

    // 区間を決める
    fill(level,level+N+1,0);
    sec.resize(N);
    REP(i,N) {
        if(num[i]!=INF) sec[i]=p(num[i],num[i]);
        else sec[i]=p(-INF,INF);
    }

    REP(i,N) {
        if(tree_edge[i].size()==0) {
            p tmp = p(-INF,INF);
            lift(i,tmp);
        }
    }

    p tmp = p(-INF,INF);
    decend(st,tmp);

    cout << "Yes" << endl;
    REP(i,N) {
        cout << num[i] << endl;
    }

    return 0;
}

