inline int getint()
{
	static char c;
	while ((c = getchar()) < '0' || c > '9');

	int res = c - '0';
	while ((c = getchar()) >= '0' && c <= '9')
		res = res * 10 + c - '0';
	return res;
}

template <class T>
inline void relax(T &a, const T &b)
{
	if (b > a)
		a = b;
}
template <class T>
inline void tense(T &a, const T &b)
{
	if (b < a)
		a = b;
}

const int MaxN = 100000;
const int INF = 10000000;

int n, m;
int vl[MaxN + 1], vr[MaxN + 1];

struct halfEdge
{
	int v;
	halfEdge *next;
};
halfEdge adj_pool[MaxN * 2], *adj_tail = adj_pool;
halfEdge *adj[MaxN + 1];

inline void addEdge(const int &u, const int &v)
{
	adj_tail->v = v, adj_tail->next = adj[u];
	adj[u] = adj_tail++;
}

void dfs(const int &u, const int &fa)
{
	for (halfEdge *e = adj[u]; e; e = e->next)
		if (e->v != fa)
		{
			dfs(e->v, u);

			int l = vl[e->v];
			int r = vr[e->v];
			l <= r ? --l, ++r : 0;

			relax(vl[u], l);
			tense(vr[u], r);
		}
}

void construct(const int &u, const int &fa, const int &cur)
{
	vl[u] = cur;

	for (halfEdge *e = adj[u]; e; e = e->next)
		if (e->v != fa)
		{
			int l = vl[e->v], r = vr[e->v];
			int next = cur - 1;
			if (l > next || next > r)
				next = cur + 1;

			construct(e->v, u, next);
		}
}

int ori[MaxN + 1];

int main()
{
	cin >> n;
	for (int i = 1; i < n; ++i)
	{
		int u = getint(), v = getint();
		addEdge(u, v);
		addEdge(v, u);
	}

	cin >> m;
	for (int u = 1; u <= n; ++u)
		vl[u] = -INF, vr[u] = INF;
	for (int i = 0; i < m; ++i)
	{
		int u = getint(), v = getint();
		vl[u] = vr[u] = v;

		ori[u] = v;
	}

	dfs(1, 0);

	if (vl[1] <= vr[1])
	{
		construct(1, 0, vl[1]);

		puts("Yes");
		for (int u = 1; u <= n; ++u)
			printf("%d\n", vl[u]);

		for (int u = 1; u <= n; ++u)
		{
			if (ori[u])
				assert(ori[u] == vl[u]);

			for (halfEdge *e = adj[u]; e; e = e->next)
				assert(vl[u] == vl[e->v] - 1 || vl[u] == vl[e->v] + 1);
		}
	}
	else
		puts("No");

	return 0;
}

#include <algorithm>
#include <iostream>
#include <vector>
using namespace std;
using ll = long long;
const ll INF = 1LL << 60;

vector<vector<int>> nxt;
vector<pair<ll, ll>> rng;

bool overlap(ll a, ll b, ll s, ll t) {
    if (a <= s && s <= b) return true;
    if (a <= t && t <= b) return true;
    if (s <= a && a <= t) return true;
    if (s <= b && b <= t) return true;
    return false;
}

bool dfs(int v, int p) {
    ll l = rng[v].first, r = rng[v].second;
    for (int nv : nxt[v]) if (nv != p) {
        ll &nl = rng[nv].first, &nr = rng[nv].second;
        if (!overlap(l, r, nl, nr)) return false;
        nl = max(l - 1, nl); nr = min(r + 1, nr);
        dfs(nv, v);
    }
    return true;
}

int main() {
    int N; cin >> N;
    nxt.resize(N);
    for (int e = 0; e < N - 1; e++) {
        int a, b; cin >> a >> b; a--, b--;
        nxt[a].push_back(b);
        nxt[b].push_back(a);
    }
    rng.assign(N, make_pair(-INF, INF));
    int K; cin >> K;
    while (K--) {
        int v, p; cin >> v >> p; v--;
        rng[v] = make_pair(p, p);
    }
    for (int v = 0; v < N; v++) {
        if (rng[v] == make_pair(-INF, INF)) continue;
        if (!dfs(v, -1)) {
