struct Edge {
  Edge(int from_, int to_) : from(from_), to(to_) {}
  int from;
  int to;
};

struct Range {
  Range() : lower(-(1<<27)), upper((1<<27)) {}
  Range(int lower_, int upper_) : lower(lower_), upper(upper_) {}
  int lower;
  int upper;
};
Range nullWindow(-(1<<29), -(1<<29)-2);
bool operator== (Range a, Range b) {
  return a.lower == b.lower and a.upper == b.upper;
}

Range operator&& (Range a, Range b) {
  if( a.upper < b.lower ) return nullWindow;
  if( a.lower > b.upper ) return nullWindow;
  if( a.lower != -(1<<27) ) {
    if( (a.lower + b.lower) % 2 == 1 ) return nullWindow;
    if( (a.upper + b.upper) % 2 == 1 ) return nullWindow;
  }
  return Range(std::max(a.lower, b.lower), std::min(a.upper, b.upper));
}

std::vector<Edge> edges[112345];
int n, k;
int num[112345];
Range range[112345];

void fillRange(int i, Range nowRange) {
  Range tempRange = range[i] and nowRange;
  if( range[i] == tempRange ) return;
  range[i] = range[i] and nowRange;
  for(Edge edge : edges[i]) {
    if( num[edge.to] != -(1<<28) ) continue;
    fillRange(edge.to, Range(nowRange.lower - 1, nowRange.upper + 1));
  }
}

