void check(int v, int dist) {
  visited[v] = true;
  d[v] = dist;
  for (int i = 0; i < G[v].size(); ++i) {
    int u = G[v][i];
    if (!visited[u]) {
      check(u,dist+1);
    }
  }
  return;
}

void dfs(int v) {

  for (int i = 0; i < G[v].size(); ++i) {
    if (d[v] < d[G[v][i]]) {
      dfs(G[v][i]);
    }
  }

  for (int i = 0; i < G[v].size(); ++i) {
    if (d[v] < d[G[v][i]]) {
      LB[v] = max(LB[v], LB[G[v][i]]-1);
      UB[v] = min(UB[v], UB[G[v][i]]+1);
    }
  }

  if (UB[v] <= LB[v]) {
    LB[v] = INF;
    UB[v] = -INF;
  }
}

void make(int v, int pn) {
  if (pn+1 >= LB[v] && pn+1 < UB[v]) {
    ans[v] = pn+1;
  } else {
    ans[v] = pn-1;
  }

  for (int i = 0; i < G[v].size(); ++i) {
    if (d[v] < d[G[v][i]]) {
      make(G[v][i], ans[v]);
    }
  }
}

