pair<int,int> dfs(int v,int pre,Graph& g,vector<int> &l,vector<int> &r,vector<int>& vp){
    int lres=-1e9;
    int rres=1e9;
    if(vp[v]!=-1) lres=rres=vp[v];
    for(int i=0;i<g[v].size();i++){
        if(g[v][i]!=pre){
            auto lr=dfs(g[v][i],v,g,l,r,vp);
            int lret=lr.first-1;
            int rret=lr.second+1;
            lres=max(lret,lres);
            rres=min(rret,rres);
            if(rres<lres){
                throw "No";
            }
        }
    }
    l[v]=lres,r[v]=rres;
    return make_pair(lres,rres);
}
void rdfs(int v,int pre,Graph& g,vector<int> &l,vector<int> &r,int ln,int rn){
    l[v]=max(l[v],ln);
    r[v]=min(r[v],rn);
    if(r[v]<l[v]){
        throw "No";
    }
    for(int i=0;i<g[v].size();i++){
        if(g[v][i]!=pre){
            rdfs(g[v][i],v,g,l,r,l[v]-1,r[v]+1);
        }
    }
    return;
}

