using namespace std;
using pii = pair<int, int>;
static const int INF = 1000000000;

pii backward_recur(
	int u, int p, vector<int>& lo, vector<int>& hi,
	const vector<int>& x, const vector<vector<int>>& conn)
{
	int self_lo = -INF, self_hi = INF;
	for(const auto v : conn[u]){
		if(v == p){ continue; }
		const auto c = backward_recur(v, u, lo, hi, x, conn);
		self_lo = max(self_lo, c.first  - 1);
		self_hi = min(self_hi, c.second + 1);
	}
	if(x[u] >= 0){
		if(x[u] < self_lo || self_hi < x[u]){
			throw runtime_error("impossible");
		}
		self_lo = self_hi = x[u];
	}
	lo[u] = self_lo;
	hi[u] = self_hi;
	return pii(self_lo, self_hi);
}

void forward_recur(
	int u, int p, const vector<int>& lo, const vector<int>& hi,
	vector<int>& x, const vector<vector<int>>& conn)
{
	if(x[u] >= 0){
		// skip
	}else if(p < 0){
		x[u] = lo[u];
	}else if(x[p] - 1 >= lo[u]){
		x[u] = x[p] - 1;
	}else if(x[p] + 1 <= hi[u]){
		x[u] = x[p] + 1;
	}else{
		throw runtime_error("impossible");
	}
	for(const auto v : conn[u]){
		if(v == p){ continue; }
		forward_recur(v, u, lo, hi, x, conn);
	}
}

int main(){
	ios_base::sync_with_stdio(false);
	int n;
	cin >> n;
	vector<vector<int>> conn(n);
	for(int i = 1; i < n; ++i){
		int a, b;
		cin >> a >> b;
		--a; --b;
		conn[a].push_back(b);
		conn[b].push_back(a);
	}
	int k;
	cin >> k;
	vector<int> x(n, -1);
	for(int i = 0; i < k; ++i){
		int v, p;
		cin >> v >> p;
		--v;
		x[v] = p;
	}
	vector<int> y(n, INF);
	queue<int> q;
	for(int i = 0; i < n; ++i){
		if(x[i] >= 0){
			y[i] = (x[i] & 1);
			q.push(i);
			break;
		}
	}
	while(!q.empty()){
		const int u = q.front();
		q.pop();
		for(const auto v : conn[u]){
			if(y[v] != INF){ continue; }
			y[v] = y[u] + 1;
			q.push(v);
		}
	}
	bool possible = true;
	for(int i = 0; i < n; ++i){
		if(x[i] < 0){ continue; }
		if((x[i] & 1) != (y[i] & 1)){ possible = false; }
	}
	if(!possible){
		cout << "No" << endl;
		return 0;
	}
	vector<int> lo(n, -INF), hi(n, INF);
	try{
		backward_recur(0, -1, lo, hi, x, conn);
		forward_recur(0, -1, lo, hi, x, conn);
	}catch(runtime_error e){
		cout << "No" << endl;
		return 0;
	}
	cout << "Yes" << endl;
	for(int i = 0; i < n; ++i){
		cout << x[i] << endl;
	}
	return 0;
}

