void dfs(int v, int pre){
    if(p[v] >= 0){
        lo[v] = max(lo[v], p[v]);
        up[v] = min(up[v], p[v]);
    }
    for(auto u : g[v]){
        if(u==pre) continue;
        lo[u] = lo[v]-1;
        up[u] = up[v]+1;
        dfs(u,v);
        lo[v] = max(lo[v], lo[u]-1);
        up[v] = max(up[v], up[u]+1);
    }
}

bool bfs(int root){
    if(lo[root] > up[root]) return false;
    ans[root] = lo[root];
    vector<bool> visited(g.size(),false);
    queue<int> que;
    que.push(root);
    while(!que.empty()){
        int v = que.front();
        que.pop();
        visited[v] = true;
        for(auto u : g[v]){
            if(visited[u]) continue;
            if(lo[u] <= ans[v]-1 && up[u] >= ans[v]-1){
                ans[u] = ans[v]-1;
                que.push(u);
            }
            else if(lo[u] <= ans[v]+1 && up[u] >= ans[v]+1){
                ans[u] = ans[v]+1;
                que.push(u);
            }
            else{
                return false;
            }
        }
    }
    return true;
}

