const int inf=1<<28;
bool ok[N];
set<int> s[N],temp;
void add(int x,int y){
	cnt++;
	e[cnt].k=y;
	e[cnt].next=home[x];
	home[x]=cnt;
}
void dfs(int k,int F){
	if(F&&e[home[k]].next==-1){
		if(w[k]==inf) ok[k]=1;
		else{
			s[k].insert(w[k]);
		}
		return;
	}
	int son=0;
	for(int i=home[k];~i;i=e[i].next) if(e[i].k!=F){
		dfs(e[i].k,k);
		if(s[e[i].k].size()>s[son].size()||!son) son=e[i].k;
	}
	ok[k]=1;
	if(w[k]!=inf) ok[k]=0,s[k].insert(w[k]);
	set<int>::iterator t;
	for(int i=home[k];~i;i=e[i].next) if(e[i].k!=F&&e[i].k!=son){
		int x=e[i].k;
		if(ok[x]) continue;
		temp.clear();
		for(t=s[x].begin();t!=s[x].end();++t){
			if((ok[k]||s[k].find((*t)-1)!=s[k].end())) temp.insert((*t)-1);
			if(ok[k]||s[k].find((*t)+1)!=s[k].end()) temp.insert((*t)+1);
		}
		ok[k]=0;
		s[k]=temp;
	}
	if(!ok[son]&&son){
		if(ok[k]){
			ok[k]=0;
			for(t=s[son].begin();t!=s[son].end();++t) s[k].insert((*t)-1),s[k].insert((*t)+1);
		}
		else{
			for(t=s[k].begin();t!=s[k].end();){
				if(s[son].find((*t)-1)!=s[son].end()||s[son].find((*t)+1)!=s[son].end()){
					++t;continue;
				}
				s[k].erase(t++);
			}
		}
	}
}
void dfs1(int k,int F){
	if(F&&w[k]==inf){
		if(ok[k]||s[k].find(w[F]+1)!=s[k].end()) w[k]=w[F]+1;
		else w[k]=w[F]-1;
	}
	else if(w[k]==inf){
		if(!ok[k]) w[k]=*s[k].begin();
		else w[k]=1;
	}
	for(int i=home[k];~i;i=e[i].next) if(e[i].k!=F){
		dfs1(e[i].k,k);
	}
}
int main(){
	memset(home,-1,sizeof(home));
	scanf("%d",&n);
	for(int i=1;i<=n;i++) w[i]=inf;
	for(int i=1,x,y;i<n;i++){
		scanf("%d%d",&x,&y);
		add(x,y);add(y,x);
	}
	scanf("%d",&m);
	for(int i=1,x,y;i<=m;i++){
		scanf("%d%d",&x,&y);
		w[x]=y;
	}
	dfs(1,0);
	if(s[1].size()==0&&!ok[1]) return puts("No");
	else{
		puts("Yes");
		dfs1(1,0);
		for(int i=1;i<=n;i++) printf("%d\n",w[i]);
	}
	return 0;
}

#include <bits/stdc++.h>

using namespace std;
typedef long long ll;

const int MAXN = 100005;

int n, m;
vector<int> g[MAXN];

bool hv[MAXN];
int val[MAXN], d[MAXN];
int fa[MAXN], rt;

void input()
{
	scanf("%d", &n);
	for(int i = 1; i < n; i++)
	{
		int x, y;
		scanf("%d%d", &x, &y);
		g[x].push_back(y);
		g[y].push_back(x);
	}
	scanf("%d", &m);
	for(int i = 1; i <= m; i++)
	{
		int x, v;
		scanf("%d%d", &x, &v);
		hv[x] = 1;
		val[x] = v;
		if(!rt) rt = x;
	}
}

bool dfs(int x, int p, int ls)
{
	d[x] = d[p] + 1;
	fa[x] = ls;
	if(hv[x])
	{
		if(hv[ls])
		{
			int dv = abs(val[ls] - val[x]);
			int dis = d[x] - d[ls];
			if(dv > dis || ((dv + dis) & 1))
				return false;
		}
		ls = x;
	}
	for(auto y: g[x])
	{
		if(y == p) continue;
		if(!dfs(y, x, ls))
			return false;
	}
	return true;
}

int color(int x, int p)
{
	for(auto y: g[x])
	{
		if(y == p) continue;
		int t = color(y, x);
		if(t == 0) return 0;
		if(!hv[y]) continue;
		if(!hv[x]) val[x] = val[y] + t, hv[x] = 1;
		else if(val[x] != val[y] + t)
			return 0;
	}
	if(fa[x] && val[fa[x]] < val[x])
		return -1;
	else
		return 1;
}

bool ok;

void fix()
{
	queue<int> q;
	for(int i = 1; i <= n; i++)
	{
		if(hv[i])
		{
			for(auto j: g[i])
			{
				if(!hv[j])
				{
					hv[j] = 1;
					val[j] = val[i] - 1;
					q.push(j);
				}
			}
		}
	}
	while(!q.empty())
	{
		int x = q.front();
		q.pop();
		for(auto y: g[x])
			if(!hv[y])
			{
				hv[y] = 1;
				val[y] = val[x] - 1;
				q.push(y);
			}
	}
}

void solve()
{
	if(dfs(rt, 0, 0) && color(rt, 0))
	{
		ok = 1;
		fix();
	}
}

void output()
{
	if(ok)
	{
		assert(dfs(1, 0, 0));
		puts("YES");
		for(int i = 1; i <= n; i++)
		{
			assert(hv[i]);
			printf("%d\n", val[i]);
		}
	}
	else puts("NO");
}

int main()
{
	input();
	solve();
	output();

	return 0;
}

