int L[100005], R[100005];
void dfs2(int u, int p, int d){
    L[u] = -2e6, R[u] = 2e6;
    if(val[u] != -1){
        L[u] = val[u];
        R[u] = val[u];
    }
    for(int i=0;i<sz(g[u]);i++){
        int v = g[u][i];
        if(v == p) continue;
        dfs2(v, u, d+1);
        L[u] = max(L[u], L[v]-1);
        R[u] = min(R[u], R[v]+1);
    }
    if((d+rev)%2 != (L[u]%2+2)%2) L[u]++;
    if((d+rev)%2 != (R[u]%2+2)%2) R[u]--;
    if(L[u] > R[u]){
        printf("No\n");
        exit(0);
    }
    else if(val[u] != -1 && (val[u] < L[u] || val[u] > R[u])){
        printf("No\n");
        exit(0);
    }
}
