        if(L[u] <= ans[p]-1 && ans[p]-1 <= R[u]) ans[u] = ans[p]-1;
        else ans[u] = ans[p]+1;
    }

    for(int i=0;i<sz(g[u]);i++){
        int v = g[u][i];
        if(v == p) continue;
        dfs3(v, u, d+1);
    }
}
