const int N_ = int(1.1e5);

int N;

vector<int> gph[N_];

int low[N_], high[N_];

void dfs (int u, int p = -1) {
  for(int v : gph[u]) if(v != p) {
    low[v] = max(low[v], low[u] - 1);
    high[v] = min(high[v], high[u] + 1);
    dfs(v, u);
    low[u] = max(low[u], low[v] - 1);
    high[u] = min(high[u], high[v] + 1);
  }
}

bool chk (int u, int p, int parity) {
  if(low[u] == high[u] && (low[u] - parity) % 2) {
    return false;
  }
  bool ret = true;
  for(int v : gph[u]) if(v != p) ret &= chk(v, u, !parity);
  return ret;
}

int ans[N_];

void go(int u, int p, int cur) {
  ans[u] = cur;
  for(int v : gph[u]) if(v != p) {
    go(v, u, low[v] <= cur - 1 ? cur - 1 : cur + 1);
  }
}

