bool dfs(int v,int L,int R,int path){
	visit[v] = true;
	if( num[v][2] != -1 && num[v][0] == num[v][1] ){//値が決まっている。
		int odd;//0:偶数,1:奇数
		//odd = ( ((L%2)+2)%2 + path%2 );
		odd = L%2;
		if( L <= num[v][0] && num[v][1] <= R &&
			(num[v][0]%2) == odd ){
			L = num[v][0];
			R = num[v][1];
			path = 0;
		}else{
			return false;
		}
	}else{
		num[v][0] = L;
		num[v][1] = R;
		num[v][2] = path;
	}
	int size = G[v].size();
	for(int i=0;i<size;++i){
		int to = G[v][i];
		if( visit[to] ) continue;
		bool res = dfs(to,L-1,R+1,path+1);
		if( res == false ) return false;
		//num[to][0]
		if( num[to][1]+1 < L || R < num[to][0]-1 ){
			return false;
		}

		int odd = ((num[to][0]-1)%2+2)%2;
		int odd2 = ((L%2)+2)%2;
		if( odd != odd2 ) return false;
		L = max(L,num[to][0]-1);
		R = min(R,num[to][1]+1);
		path = odd;
	}
	num[v][0] = L;
	num[v][1] = R;
	num[v][2] = path;
	return true;
}

void setNum(int v,int prev){
	visit[v] = true;
	if( num[v][0] != num[v][1] ){
		if( num[v][0] <= prev+1 && prev+1 <= num[v][1] ){
			num[v][0] = prev+1;
			num[v][1] = prev+1;
		}else{
			num[v][0] = prev-1;
			num[v][1] = prev-1;
		}
	}
	int size = G[v].size();
	for(int i=0;i<size;++i){
		int to = G[v][i];
		if( visit[to] ) continue;
		setNum(to,num[v][0]);
	}
}
