	return adj_lst[index];
}
vector<Edge*>& Graph::get_incoming(int index){
	return rev_adj_lst[index];
}

using namespace std;
using P = pair<int,int>;
const int N = 1e+5+7;
const int INF = 1e+7;
int V[N];
P Ps[N];

P dfs(int r,Graph& g) {
	int myminmax = -INF;
	int mymaxmin = INF;
	for(auto e: g.get_outgoing(r)) {
		P child = dfs(e->dest,g);

		myminmax = max(myminmax,child.first);
		mymaxmin = min(mymaxmin,child.second);
	}

// 	cout << "r:" << r << endl;
	if(myminmax > mymaxmin){
		Ps[r] = P(myminmax,mymaxmin);
		return P(myminmax,mymaxmin);
	}

	if(V[r] >= 0){
		myminmax = max(myminmax,V[r]);
		mymaxmin = min(mymaxmin,V[r]);
		Ps[r] = P(myminmax,mymaxmin);
		return P(myminmax,mymaxmin);
	}

	Ps[r] = P(myminmax-1,mymaxmin+1);
	return P(myminmax-1,mymaxmin+1);
}

void retraversal(int r,Graph& g, int num) {
	if(V[r] < 0)
		V[r] = num;

	for(auto e: g.get_outgoing(r)) {
		P child = Ps[e->dest];
		if(abs(num+1 - child.first) <= 1 || abs(num+1 - child.second) <=1)
			retraversal(e->dest,g,num+1);
		else
			retraversal(e->dest,g,num-1);
	}
}

