	dfs(1,0);

	queue<int>  q;

	cin >> k;

	int m = -1;

	while(k--)  {
		int u, p;   cin >> u >> p;
		L[u] = ii(p,p);
		q.push(u);
		int c = (p + h[u]) % 2;
		if(m == -1)  m = c;
		if(m != c)  {
			cout << "No";
			exit(0);
		}
	}

	while(q.size()) {
		int u = q.front();  q.pop();
		for(int v : g[u])   {
			ii  tmp = L[v];
			tmp.fi = max(tmp.fi,L[u].fi - 1);
			tmp.se = min(tmp.se,L[u].se + 1);
			if(tmp.fi > tmp.se) {
				cout << "No";
				exit(0);
			}
			if(tmp != L[v]) {
				L[v] = tmp;
				q.push(v);
			}
		}
	}

	cout << "Yes\n";
	for(int i = 1 ; i <= n ; ++i)   {
		cout << L[i].fi << "\n";
		for(int u : g[i])
			L[u] = ii(max(L[u].fi,L[i].fi - 1),min(L[u].se,L[i].fi + 1));
	}
}

