const int maxn=100010;

int n,k,l[maxn],r[maxn],id[maxn];
vector<int> e[maxn];
bool ans;

inline void solve(int v=0,int p=-1)
{
	l[v]=-INF-1;r[v]=INF+1;
	if(id[v]!=-1) l[v]=r[v]=id[v];

	repV(i,e[v]) if(i!=p)
	{
		solve(i,v);
		if(l[i]<-INF/2) continue;
		if(l[v]<-INF/2)
		{
			l[v]=l[i]-1;
			r[v]=r[i]+1;
		}
		else
		{
			if(abs(l[i])%2==abs(l[v])%2)
			{
				ans=0;
				return;
			}

			l[v]=max(l[v],l[i]-1);
			r[v]=min(r[v],r[i]-1);
		}
	}

	if(l[v]>r[v]) ans=0;
}

inline void make(int v=0,int p=-1)
{
	if(v==0&&id[v]==-1) id[v]=l[v];

	repV(i,e[v]) if(i!=p)
	{
		if(id[i]==-1)
		{
			if(l[i]<=id[i]-1&&id[i]-1<=r[i]) id[i]=id[v]-1; else id[i]=id[v]+1;
		}
		make(i,v);
	}
}

