	cin.tie(0); ios::sync_with_stdio(false);

	cin >> n;
	g.resize(n);
	zep(i, 0, n){
		l[i] = 0;
		r[i] = 1e6;
	}
	zep(i, 0, n-1){
		cin >> a >> b; 
		a--; b--;
		g[a].push_back(b);
		g[b].push_back(a);
	}

