	zep(i, 0, k){
		cin >> v >> p;
		v--;
		ansv[v] = p;
		l[v] = p;
		r[v] = p;
		even[v] = p%2;
		s = v;
	}

	bool ans = true;
	queue<ll> q;
	bool use[n];
	memset(use, 0, sizeof(use));
	q.push(s);
	use[s] = true;

	while(!q.empty()){
		ll at = q.front(); q.pop();

		zep(i, 0, g[at].size()){
			ll nx = g[at][i];
			if(even[nx] >= 0 && even[nx] == even[at]){ans = false;}
			even[nx] = 1-even[at];

			if(!use[nx]){
				q.push(nx);
				use[nx] = true;
			}
		}
	}

	if(ans){
		ll cnt[n];
		zep(i, 0, n){cnt[i] = g[i].size();}

		zep(i, 0, n){if(cnt[i] == 1){q.push(i);}}

		while(!q.empty()){
			ll at = q.front(); q.pop();
			if(r[at]-l[at] < 0){ans = false;}

			zep(i, 0, g[at].size()){
				ll nx = g[at][i];

				l[nx] = max(l[at]-1, l[nx]);
				r[nx] = min(r[at]+1, r[nx]);
				cnt[nx]--;

				if(cnt[nx] == 1){q.push(nx);}
			}
			s = at;
		}

		if(ans){
			q.push(s);
			memset(use, 0, sizeof(use));
			use[s] = true;

			while(!q.empty()){
				ll at = q.front(); q.pop();

				zep(i, 0, g[at].size()){
					ll nx = g[at][i];

					if(!use[nx]){
						if(ansv[at]+1 > r[nx]){
							ansv[nx] = ansv[at]-1;
						}
						else{
							ansv[nx] = ansv[at]+1;
						}

						q.push(nx);
						use[nx] = true;
					}
				}
			}
		}
	}

	print((ans)? "Yes" : "No")
	if(ans){
		zep(i, 0, n){
			print(ansv[i])
		}
	}
	return 0;
}

