#include <cmath>
using namespace std;
const int MAXN = 100005;
const int INF = 1e9;
int n, K;
int V[MAXN], P[MAXN];
int et, fir[MAXN], to[MAXN << 1], ne[MAXN << 1];
int s[2][MAXN], v[MAXN];

void link(int u, int v) {
    to[++et] = v, ne[et] = fir[u], fir[u] = et;
    to[++et] = u, ne[et] = fir[v], fir[v] = et;
}

#include <queue>
#define xx first
#define yy second
typedef pair<int, int> pii;
void solve(int t) {
    if (!t) {
        priority_queue<pii> h;
        for (int i = 1; i <= K; i++)
            h.push(make_pair(P[i], V[i]));
        while (!h.empty()) {
            pii o = h.top(); h.pop();
            if (s[t][o.yy] != o.xx)
                continue;
            for (int i = fir[o.yy]; i; i = ne[i])
                if (s[t][to[i]] < o.xx - 1)
                    s[t][to[i]] = o.xx - 1, h.push(make_pair(s[t][to[i]], to[i]));
        }
    } else {
        priority_queue<pii, vector<pii>, greater<pii> > h;
        for (int i = 1; i <= K; i++)
            h.push(make_pair(P[i], V[i]));
        while (!h.empty()) {
            pii o = h.top(); h.pop();
            if (s[t][o.yy] != o.xx)
                continue;
            for (int i = fir[o.yy]; i; i = ne[i])
                if (s[t][to[i]] > o.xx + 1)
                    s[t][to[i]] = o.xx + 1, h.push(make_pair(s[t][to[i]], to[i]));
        }
    }
}

void dfs(int o, int fa) {
    for (int i = fir[o], t; i; i = ne[i])
        if ((t = to[i]) != fa) {
            v[t] = v[o] + 1 <= s[1][t] ? v[o] + 1 : v[o] - 1;
            dfs(t, o);
        }
}

int main() {
    scanf("%d", &n);
    for (int i = 1, x, y; i < n; i++)
        scanf("%d %d", &x, &y), link(x, y);
    for (int i = 1; i <= n; i++)
        s[0][i] = -INF, s[1][i] = INF;
    scanf("%d", &K);
    for (int i = 1; i <= K; i++) {
        scanf("%d %d", V + i, P + i);
        s[0][V[i]] = s[1][V[i]] = P[i];
    }
    solve(0), solve(1);
    for (int i = 1; i <= n; i++)
        if (s[0][i] > s[1][i]) {
            printf("No");
            return 0;
        }
    v[V[1]] = P[1], dfs(V[1], 0);
    for (int i = 1; i <= n; i++)
        if (v[i] < s[0][i] || v[i] > s[1][i]) {
            printf("No");
            return 0;
        }
    puts("Yes");
    for (int i = 1; i <= n; i++)
        printf("%d\n", v[i]);
    return 0;
}

