void dfs(int x) {
    if (v[x] == -1)
        l[x] = r[x] = -1e9;
    else
        l[x] = r[x] = v[x];
    for (auto u:g[x])
        if (u != fa[x]) {
            fa[u] = x;
            dfs(u);
            if (l[u] == -1e9) continue;
            int L = l[u] - 1, R  = r[u] + 1;
            if (l[x] == -1e9)
                l[x] = L, r[x]  = R;
            else{
                ans &= ((l[x] & 1) == (L & 1));
                l[x] = max(l[x], L);
                r[x] = min(r[x], R);
                ans &= (l[x] <= r[x]);
            }
        }
}
void dfs1(int x) {
    for (auto u:g[x])
        if (u != fa[x]) {
            if (l[u] == -1e9)
                v[u] = v[x]  +1, dfs1(u);
            else
            {
                if (v[x] + 1<= r[u])
                    v[u] = v[x] + 1, dfs1(u);
                else
                    v[u] = v[x] - 1, dfs1(u);
            }
        }
}
