#define pb push_back

const int N = 1e5 + 10;
const int oo = 1e9;

int n, k;
int val[N], Lmax[N], Rmax[N];
vector<int> vi[N];

void dfs(int pre, int u)    {
    int lmax = -oo, rmax = oo;
    for(int v: vi[u])   if(v != pre)    {
        dfs(u, v);
        lmax = max(lmax, Lmax[v] - 1);
        rmax = min(rmax, Rmax[v] + 1);
    }
    if(val[u] != -1 && (lmax > val[u] || rmax < val[u]))  {
        cout << "No"; exit(0);
    }
    else if(val[u] != -1) Lmax[u] = Rmax[u] = val[u];
    else Lmax[u] = lmax, Rmax[u] = rmax;
}

void solve(int pre, int u, int spm) {
    int nex = 0;
    if(Lmax[u] <= spm + 1 && spm + 1 <= Rmax[u]) nex = spm + 1;
    else nex = spm - 1;
    val[u] = nex;
    for(int v: vi[u])   if(v != pre){
        solve(u, v, nex);
    }
}

signed main()
{
    ios_base::sync_with_stdio(false);
    cin.tie(0); cout.tie(0);

    cin >> n;
    memset(val, -1, sizeof val);
