    FOR(i, 1, n) if(Lmax[i] > Rmax[i]) {
        cout << "No"; return 0;
    }
    solve(1, 1, Lmax[1] - 1);
    cout << "Yes\n";
    FOR(i, 1, n) cout << val[i] << '\n';
}

