#include <bits/stdc++.h>

using namespace std ;

int n, K ;

const int MAXN = 100010 ; 

int a[MAXN] ;

struct Edge {
		int l, r, nxt;
} e[MAXN << 1]; 

int ecnt = 0, hed[MAXN] ;

void addedge(int l, int r) {
		++ecnt, e[ecnt].l = l, e[ecnt].r = r, e[ecnt].nxt = hed[l], hed[l] = ecnt ;
}

int root = 0 ; 

int L[MAXN], R[MAXN], typ[MAXN] ;

bool flag = 1; 

void Dfs(int x, int fr) {
		L[x] = -1000000000, R[x] = 1000000000, typ[x] = -1 ;
		if (a[x] >= 0) {
			   typ[x] = (a[x] & 1) ; 
			   L[x] = R[x] = (a[x] >> 1);  
		}
		for (int i = hed[x]; i && flag; i = e[i].nxt) {
				int to = e[i].r ;
			    if (to ^ fr) {
						Dfs(to, x) ; 
						if (typ[to] >= 0) { 
								if (typ[to] == typ[x]) {
										flag = 0 ;
										return ; 
								}
								else {
										if (typ[to] == 0) {
												L[x] = max(L[x], L[to] - 1), R[x] = min(R[x], R[to]) ; 
										}
										else L[x] = max(L[x], L[to]), R[x] = min(R[x], R[to] + 1) ; 
								}
								typ[x] = typ[to] ^ 1 ; 
						}
				}
		}
		if (L[x] > R[x]) flag = 0 ;
}

void Dfs2(int x, int fr) {
			for (int i = hed[x]; i; i = e[i].nxt) {
					int to = e[i].r ;
					if (to != fr) { 
							if (L[to] <= (a[x] + 1) / 2 && (a[x] + 1) / 2 <= R[to]) a[to] = a[x] + 1 ;
							else a[to] = a[x] - 1; 
							Dfs2(to, x) ;
					}
			}
}

void Solve() {
		Dfs2(root, 0) ; 
		for (int i = 1; i <= n; i ++) printf("%d\n", a[i]) ;
}

int main() { 
#ifdef YJQ_LOCAL
		freopen(".in", "r", stdin) ;
#endif
		scanf("%d", &n) ;
		for (int i = 1; i < n; i ++) {
				int l, r ;
				scanf("%d%d", &l, &r); 
				addedge(l, r), addedge(r, l) ; 
		}
		scanf("%d", &K) ;
		memset(a, -1, sizeof a) ;
		for (int i = 1; i <= K; i ++) {
				int p, v;
				scanf("%d%d", &p, &v) ;
				a[p] = v ; 
				root = p ; 
		}
		Dfs(root, 0) ; 
		if (!flag) puts("No");
		else {
				puts("Yes") ;
				Solve() ;
		}
}

