vector<int> g[N];
int nums[N];

bool dfs(int v, int p, int f) {
	if (nums[v] != -1) {
		if (nums[v] % 2 != f) return false;
	}
	bool ans = true;
	for (int u : g[v]) if (u != p) {
		ans &= dfs(u, v, f ^ 1);
	}
	return ans;
}

