  Graph graph(N);
  REP(i,N-1) {graph[A[i]].PB(B[i]); graph[B[i]].PB(A[i]);}

  // dfs
  vi depth(N,-1),parent(N,-1);
  queue<ll> q; q.push(V[0]); depth[V[0]]=0;
  while(q.size()) {
    ll from=q.front(); q.pop();
    for(ll to:graph[from]) {
      if(depth[to]==-1) {
        depth[to]=depth[from]+1;
        parent[to]=from;
        q.push(to);
      }
    }
  }

  Tree tree(N);
  ll root;
  REP(i,N) {
    tree[i].d=depth[i];
    tree[i].p=parent[i];
    tree[i].l=-INF;
    tree[i].r=INF;
    tree[i].v=-1;
    if(depth[i]==0) root=i;
  }

  REP(i,K) tree[V[i]].v=P[i];

  vi order(N); REP(i,N) order[i]=i;
