void dfs(int current) {
  int nlv = lv[current],nuv=uv[current];
  visited[current]=true;
  FOR_F(edge, edges[current]) {
    int to=*edge;
    if (visited[to]) continue;
    dfs(to);
    nlv = max(nlv, lv[to]-1);
    nuv = max(nuv, uv[to]+1);
  }
  lv[current] = nlv;uv[current] = nuv;
}

void setValues(int current, int prev) {
  if (lv[current]>uv[current]) {
    OK = false;
    return;
  }
  visited[current]=true;
  if (prev==-1) {
    ans[current]=lv[current];
  } else {
    int temps[]={ans[prev]+1, ans[prev]-1};
    bool flag = true;
    for(int i=0;i<2;++i) {
      if (temps[i]>=lv[current] && temps[i] <=uv[current]) {
        ans[current] = temps[i];
        flag = false;
      }
    }
    if (flag) {
      OK=false;return;
    }
  }
  FOR_F(edge, edges[current]) {
    int to=*edge;
    if (visited[to]) continue;
    setValues(to, current);
  }
}

