bool union_seg(int &lu, int &ru, int lv, int rv, int odd, bool &mark){
	if(!mark){
		lu = lv;
		ru = rv;
		mark = true;
	}
	else{
		lu = std::max(lu, lv);
		ru = std::min(ru, rv);
	}
	if(lu > ru || lu == ru && (lu & 1) != odd) return false;
	return true;
}

bool dfs1(int u, int fa, int odd){
	if(has[u] && (l[u] & 1) != odd){
		return false;
	}
	for(auto v : mat[u]){
		if(v == fa) continue;
		if(!dfs1(v, u, !odd)){
			return false;
		}
		if(!union_seg(l[u], r[u], l[v] - 1, r[v] + 1, odd, has[u])){
			return false;
		}
	}
	if(!has[u]){
		l[u] = - 1e9;
		r[u] =   1e9;
	}
	return true;
}

bool inseg(int x, int l, int r){
	return l <= x && x <= r;
}

bool dfs2(int u, int fa){
	for(auto v : mat[u]){
		if(v == fa) continue;
		if(inseg(l[u] + 1, l[v], r[v])){
			l[v] = l[u] + 1;
			if(!dfs2(v, u)){
				return false;
			}
		}
		else if(inseg(l[u] - 1, l[v], r[v])){
			l[v] = l[u] - 1;
			if(!dfs2(v, u)){
				return false;
			}
		}
		else{
			return false;
		}
	}
	return true;
}

