// Modulo {{{
ll mpow(ll x, ll y, ll m) {
  x %= m;
  ll result = 1;
  while (y > 0) {
    if (y & 1) result = (result * x) % m;
    x = (x * x) % m;
    y >>= 1;
  }
  return result;
}

// mod inverse 法mにおけるxの逆数
ull minverse(ull x, ull m) {
  return mpow(x, m-2, m);
}

// (1 + a + a^2 + a^3 ... + a^(n-1) ) % m
ll modpowsum(ll a, ll n, ll m) {
  if(n==0){
    return 0;
  } else if(n%2==1) {
    return (1+modpowsum(a,n-1,m)*a) % m;
  } else{
    ll t = modpowsum(a,n/2,m);
    return (t+t*mpow(a,n/2,m)) % m;
  }
}

// s % m
ll strmod (const string s, const ll m){
  if(m==1)
    return 0;

  ll len=s.size(), res=0;
  ll t=1; // t: 10^i mod m
  rep(i,0,len){
    int x = s[len-i-1] - '0';
    res = (res + x * t) % m;
    t = (t*10) % m;
  }
  return res;
}
