int N,K;
vector<int> v;
vector<vector<int>> edges;

signed main() {
  cin>>N;
  v.resize(N, -1);
  edges.resize(N);
  for (int i=0; i<N-1; i++) {
    int a,b;
    cin>>a>>b;
    a--;
    b--;
    edges[a].push_back(b);
    edges[b].push_back(a);
  }
  priority_queue <PLL, vector<PLL>, greater<PLL>> q;
  cin>>K;
  for (int i=0; i<K; i++) {
    int a,p;
    cin>>a>>p;
    a--;
    v[a] = p;
    q.emplace(p, a);
  }
  while (!q.empty()) {
    auto t = q.top(); q.pop();
    cout<<t.second<<" -> "<<t.first<<endl;
    for (int c: edges[t.second]) {
      if (v[c] == -1) {
        v[c] = t.first+1;
        q.emplace(v[c], c);
      } else if (abs(v[c] - t.first) != 1) {
        cout<<"No"<<endl;
        return 0;
      }
    }
  }
  cout<<"Yes"<<endl;
  for (int i=0; i<N; i++) {
    cout<<v[i]<<endl;
  }
  return 0;
}

