bool rev[100005];
vector<int> dist(100005, -1);
vector<int> num(100005, -1);
vector<int> lim(100005, -1);
vector<int> ans(100005);
vector<int> g[100005];

int dfs(int u, int d) {
    dist[u] = d;
    if (num[u] != -1 && num[u] % 2 != dist[u] % 2) {
        cout << "No" << endl;
        exit(0);
    }
    int nlim = INF;
    for (auto to : g[u]) {
        if (dist[to] == -1) {
            chmin(nlim, dfs(to, d+1));
        }
    }
    if (num[u] != -1) chmin(nlim, (dist[u] - num[u]) / 2);
    return lim[u] = nlim;
}

void bfs(int u, int cnt) {
    if (num[u] == -1) {
        if (lim[u] > cnt) rev[u] = true, cnt++;
    } else if ((dist[u] - num[u]) / 2 != cnt) {
        cout << "No" << endl;
        exit(0);
    }
    ans[u] = dist[u] - 2 * cnt;
    for(auto to : g[u]) {
        if (dist[u] < dist[to]) bfs(to, cnt);
    }
}

void solve() {
    int n; cin >> n;
    rep (i, n-1) {
        int a, b; cin >> a >> b; --a, --b;
        g[a].pb(b);
        g[b].pb(a);
    }
    int k; cin >> k;
    int s;
    rep (i, k) {
        int v, p; cin >> v >> p; --v;
        s = v;
        num[v] = p;
    }

    dfs(s, num[s]);
    bfs(s, 0);
    cout << "Yes" << endl;
    rep (i, n) cout << ans[i] << endl;
}

