vector<vector<int> >G(100010);
int K;
int V[100010], P[100010];
int vl[100010], vr[100010];
queue<int> q;

int solve()
{
	int i;
	for(i=0; i<K; i++){
		q.push(V[i]);
	}
	int u, v;
	int l, r;
	while(!q.empty() ){
		u = q.front();
		q.pop();
		for(i=0; i<G[u].size(); i++){
			v = G[u][i];
			if(vl[u]-1>vr[v] || vl[v]>vr[u]+1)
				return 0;
			l = vl[u]-1;
			if(l < vl[v])
				l = vl[v];
			r = vr[u]+1;
			if(r > vr[v])
				r = vr[v];
			if(r-l==1)
				return 0;
			if(l!=vl[v] || r!=vr[v]){
				vl[v] = l;
				vr[v] = r;
				q.push(v); 
			}
		}
	}
	return 1;
}

int main()
{
	//freopen("in.txt", "r", stdin);
	int i;
	scanf("%d", &N);
	for(i=0; i<N-1; i++){
		scanf("%d %d", &A, &B);
		A--, B--;
		G[A].push_back(B);
		G[B].push_back(A);
	}
	scanf("%d", &K);
	for(i=0; i<N; i++){
		vl[i] = -10000000;
		vr[i] = 10000000;
	}
	for(i=0; i<K; i++){
		scanf("%d%d", &V[i], &P[i]);
		V[i] --;
		vl[V[i]] = vr[V[i]] = P[i];
	}
	if(solve() ){
		printf("Yes\n");
		for(i=0; i<N; i++){
			printf("%d\n", vl[i]);
		}
	}
	else{
		printf("No\n");
	}
	return 0;
}

