const int N = 100005;

int n, head[N], tot;
struct edge { int to, nxt; } e[N << 1];
void link(int x, int y) {
	e[++tot] = (edge) { y, head[x] }, head[x] = tot;
	e[++tot] = (edge) { x, head[y] }, head[y] = tot;
}

int p[N], rec, l[N], r[N];
void dfs0(int x, int f = 0, int lst = 0, int dis = 0, bool dep = 0) {
	++dis; if (lst) l[x] = p[lst] - dis, r[x] = p[lst] + dis;
	if (p[x] != -1) {
		if ((rec |= 1 << (dep ^ p[x] & 1)) == 3)
			std::cout << "No\n", std::exit(0);
		l[x] = std::max(l[x], p[x]), r[x] = std::min(r[x], p[x]);
		lst = x, dis = 0;
	}
	for (int i = head[x]; i; i = e[i].nxt)
		if (e[i].to != f) {
			dfs0(e[i].to, x, lst, dis, dep ^ 1);
			l[x] = std::max(l[x], l[e[i].to] - 1);
			r[x] = std::min(r[x], r[e[i].to] + 1);
		}
	if (l[x] > r[x]) std::cout << "No\n", std::exit(0);
}

