	for (int i = 0, x, y; i < k; ++i)
		std::cin >> x >> y, p[x] = y, root = x;
	l[root] = r[root] = p[root], dfs0(root);
	std::cout << "Yes\n";
	for (int i = 1; i <= n; ++i)
		std::cout << l[i] << '\n';
	return 0;
}

