	int v,nxt;
}edge[sz<<1];
void make_edge(int u,int v){
	edge[++cnt]=(Edge){v,head[u]};head[u]=cnt;
	edge[++cnt]=(Edge){u,head[v]};head[v]=cnt;
}
void dfs(int x,int fa){
	go(x) if(now!=fa){
		dfs(now,x);
		if(l[now]==-inf&&r[now]==inf) continue;
		if(l[x]!=-inf&&r[x]!=inf&&((l[x]&1)^(l[now]&1)==0||(r[x]&1)^(r[now]&1)==0)) flag=1;
		l[x]=max(l[x],l[now]-1);
		r[x]=min(r[x],r[now]+1);
	}
	flag|=l[x]>r[x];
}
void Dfs(int x,int fa){
	if(fa==0) val[x]=l[x];
	else{
		if(val[fa]-1>=l[x]) val[x]=val[fa]-1;
		else val[x]=val[fa]+1;
	}
	go(x) if(now!=fa) Dfs(now,x);
}
