	ans[p]=w;
	for(int i=first[p];i;i=e[i].next){
		int v=e[i].v;
		if(v==fa)continue;
		dfs3(v,p,(low[v]<=w-1&&high[v]>=w-1?w-1:w+1));
	}
}
