void print(seg a) {
  cerr << a.odd << " " << a.l << " " << a.r << " " << a.any << endl;
}

bool combine(seg &a, seg &b) {
  if (a.any) {
    a = b;
    return true;
  }
  if (b.any) {
    return true;
  }
  if (a.odd != b.odd) {
    return false;
  }
  a.l = max(a.l, b.l);
  a.r = min(a.r, b.r);
  if (a.l > a.r) {
    return false;
  }
  return true;
}

bool inside(seg a, int x) {
  if (a.any) {
    return true;
  }
  return (x & 1) == a.odd && x >= a.l && x <= a.r;
}

void dfs(int v, int par = -1) {
  for (int to : g[v]) {
    if (to != par) {
      dfs(to, v);
    }
  }
  if (!used[v]) {
    s[v].any = true;
  } else {
    s[v].any = false;
    s[v].odd = (p[v] & 1);
    s[v].l = p[v];
    s[v].r = p[v];
  }
  for (int to : g[v]) {
    if (to == par) {
      continue;
    }
    seg sc = s[to];
    sc.odd ^= true;
    sc.l--; sc.r++;
    bool ok = combine(s[v], sc);
    if (!ok) {
      puts("No");
      exit(0);
    }
  }
}

void dfs2(int v, int par = -1) {
  for (int to : g[v]) {
    if (to == par) {
      continue;
    }
    if (inside(s[to], p[v] - 1)) {
      p[to] = p[v] - 1;
    } else {
      p[to] = p[v] + 1;
    }
    dfs2(to, v);
  }
}

