	if(w.size()==0){
		if(v[x]>=0){
			return d[x]=pii(v[x],1);
		}
		else{
			return d[x]=pii(-1,1);
		}
	}
	else{
		if(v[x]>=0){
			bool f = true;
			rep(i,w.size()){
				if(abs(v[x]-w[i].F)<=w[i].S&&abs(v[x]-w[i].F)%2==w[i].S%2){
				}
				else{
					f=false;
				}
			}
			if(f){
				return d[x]=pii(v[x],1);
			}
			else{
				ok=false;
				return d[x]=pii(-1,1);
			}
		}
		else{
			if(w.size()==1){
				return d[x]=pii(w[0].F,w[0].S+1);
			}
			else{
				bool f = true;
				int t = (w[0].F+w[0].S)%2;
				reep(i,1,w.size()){
					if(t != (w[i].F+w[i].S)%2) f=false;
				}
				if(!f){
					ok=false;
					return d[x]=pii(-1,1);
				}
				int l=-INF;
				int r=INF;
				rep(i,w.size()){
					maxs(l,w[i].F-w[i].S);
					mins(r,w[i].F+w[i].S);
				}
				pii ret(l+(r-l)/2,(r-l)/2);
				return d[x]=ret;
			}
		}
	}
}

