  r.assign(n, 3000000);
  res.resize(n, -1);
  for (int i = 0; i < n - 1; ++i) {
    int a, b;
    cin >> a >> b;
    g[--a].push_back(--b);
    g[b].push_back(a);
  }
  cin >> k;
  for (int i = 0; i < k; ++i) {
    int node, p;
    cin >> node >> p;
    --node;
    l[node] = r[node] = res[node] = p;
    root = node;
  }
