pair<int, int> cansolve(int n)
{
    int l = -1000000, r = 1000000;
    for(int i = 0; i < graph[n].size(); i++){
        int nextnode = graph[n][i];
        if(parent[nextnode] != -1 || nextnode == 1) continue;
        parent[nextnode] = n;
        pair<int, int> tmp = cansolve(nextnode);
        if(tmp.first == -1) return make_pair(-1, -1);
        l = max(l, tmp.first - 1);
        r = min(r, tmp.second + 1);
    }
    if(node[n] != -1){
        l = max(l, node[n]);
        r = min(r, node[n]);
    }
    if(r - l < 0 || r - l == 1) l = -1;
    return make_pair(l, r);
}

