inline void merge(int x,int y)
{
	if(F[y][0]==-100000000) return;
	if(F[x][0]==-100000000)
	{
		F[x][0]=F[y][0]-1,F[x][1]=F[y][1]+1;
		return ;
	}
	if(!((F[x][0]&1)^(F[y][0]&1)))
	{
		fg=1; return ;
	}
	if(F[x][1]<F[y][0]-1||F[x][0]>F[y][1]+1)
	{
		fg=1; return;
	}
	F[x][0]=max(F[x][0],F[y][0]-1);
	F[x][1]=min(F[x][1],F[y][1]+1);
}
inline void travel(int rt,int pr)
{
	if(rt==1) Vl[rt]=F[rt][0]==-100000000? 0:F[rt][0];
	else if(Vl[pr]-1>=F[rt][0]&&Vl[pr]+1<=F[rt][1])
		Vl[rt]=Vl[pr]-1;
	else Vl[rt]=Vl[pr]+1;
	for(int i=st[rt];i;i=vs[i].next)
	{
		if(vs[i].v==pr) continue;
		travel(vs[i].v,rt);
	}
}
inline void dfs(int rt,int pr)
{
	cnt++;
	if(s[rt]) F[rt][0]=F[rt][1]=p[rt];
	else F[rt][0]=F[rt][1]=-100000000;
	for(int i=st[rt];i;i=vs[i].next)
	{
		if(vs[i].v==pr) continue;
		dfs(vs[i].v,rt);
		merge(rt,vs[i].v);
	}
}
