        //} else if (rv == inf) {
        //    continue;
        } else if (R[i] != inf && rv != inf && R[i].first % 2 != rv.first % 2) {
            return fail;
        //} else if (R[i].second < rv.first) {
        //    return fail;
        //} else if (rv.second < R[i].first) {
