    --a;--b;
    g[a].push_back(b);
    g[b].push_back(a);
  }
  int k;
  cin>>k;
  vecint num(n, -1);
  REP(i,k) {
    int v,p;
    cin>>v>>p;
    --v;
    num[v] = p;
  }
  vector<tuple<int,int,bool,bool>> vr(n);
  REP(i,n) {
    if (num[i] < 0) {
      int mn, mx;
      bool ise, iso;
      tie(mn, mx, ise, iso) = dfs(g, num, vr, i);
      dfs2(g, num, vr, mn+1, i);
    }
  }
  cout<<"Yes\n";
  REP(i,n) {
    cout<<num[i]<<"\n";
  }
  return 0;
}

