vector<int>G[100006];
int al[100006], au[100006];
int des[100006],dis[100006];
void dfs1(int now, int par) {
	rep(i, G[now].size()) {
		int e = G[now][i];
		if (e == par)continue;
		al[e] = max(al[e], al[now]-1);
		au[e] = min(au[e], au[now]+1);
		dis[e] = dis[now] + 1;
		dfs1(e, now);
	}
	return;
}

void dfs2(int now, int par) {
	rep(i, G[now].size()) {
		int e = G[now][i];
		if (e == par)continue;
		dfs2(e, now);
	}
	for (auto c : G[now]) {
		if (c == par)continue;
		al[now] = max(al[now], al[c]-1);
		au[now] = min(au[now], au[c]+1);
	}
}

