		tree[a].push_back(b);
	}

	int k; cin >> k;
	for (int i = 0; i < k; ++i) {
		int a, b; cin >> a >> b;
		weight[a] = b;
	}

	foo(1);
	if (ret[1][0] > ret[1][1] && ret[1][2] > ret[1][3]) cout << "No\n";
	else {
		cout << "Yes\n";
		result(1, INT);
		for (int i = 1; i <= n; ++i) cout << weight[i] << '\n';
	}
	return 0;
}

