int dfs(int u, int d) {
    dist[u] = d;
    if (num[u] != -1 && num[u] % 2 != dist[u] % 2) {
        cout << "No" << endl;
        exit(0);
    }
    int nlim = INF;
    for (auto to : g[u]) {
        if (dist[to] == -1) {
            chmin(nlim, dfs(to, d+1));
        }
    }
    if (num[u] != -1) chmin(nlim, (dist[u] - num[u]) / 2);
    return lim[u] = nlim;
}

void bfs(int u, int cnt) {
    if (lim[u] > cnt) rev[u] = true, cnt++;
    if (num[u] != -1 && (dist[u] - num[u]) / 2 != cnt) {
        cout << "No" << endl;
        exit(0);
    }
    ans[u] = dist[u] - 2 * cnt;
    for(auto to : g[u]) {
        if (dist[u] < dist[to]) bfs(to, cnt);
    }
}

