		node[v[i]].low = p[i];
		node[v[i]].high = p[i];
	}

	REP(i, k) {
		std::vector<bool> visited(n, false);
		std::queue<int> queue;
		visited[v[i]] = true;
		queue.push(v[i]);
		while (!queue.empty()) {
			int now_i = queue.front(); queue.pop();
			Node& now = node[now_i];
			int low = now.low - 1, high = now.high + 1;
			for (auto check_i : now.next) {
				Node& check = node[check_i];
				if (!visited[check_i]) {
					visited[check_i] = true;
					if (check.low > check.high) {
						check.low = low;
						check.high = high;
						queue.push(check_i);
						continue;
