					if (check.low > check.high) {
						OUT("No")BR;
						return 0;
					}
					if (low <= check.low && high >= check.high) continue;
					CHMAX(check.low, low);
					CHMIN(check.high, high);
					if (check.low > check.high) {
						OUT("No")BR;
						return 0;
					}
					queue.push(check_i);
				}
			}
		}
	}
	OUT("Yes")BR;
	REP(i, n) {
		OUT(node[i].low)/*SP OUT(node[i].high)*/BR;
