inline int getint()
{
	static char c;
	while ((c = getchar()) < '0' || c > '9');

	int res = c - '0';
	while ((c = getchar()) >= '0' && c <= '9')
		res = res * 10 + c - '0';
	return res;
}

template <class T>
inline void relax(T &a, const T &b)
{
	if (b > a)
		a = b;
}
template <class T>
inline void tense(T &a, const T &b)
{
	if (b < a)
		a = b;
}

const int MaxN = 100000;
const int INF = 10000000;

int n, m;
int vl[MaxN + 1], vr[MaxN + 1];

struct halfEdge
{
	int v;
	halfEdge *next;
};
halfEdge adj_pool[MaxN * 2], *adj_tail = adj_pool;
halfEdge *adj[MaxN + 1];

inline void addEdge(const int &u, const int &v)
{
	adj_tail->v = v, adj_tail->next = adj[u];
	adj[u] = adj_tail++;
}

void dfs(const int &u, const int &fa)
{
	for (halfEdge *e = adj[u]; e; e = e->next)
		if (e->v != fa)
		{
			dfs(e->v, u);

			int l = vl[e->v];
			int r = vr[e->v];
			l <= r ? --l, ++r : 0;

			relax(vl[u], l);
			tense(vr[u], r);
		}
}

void construct(const int &u, const int &fa, const int &cur)
{
	vl[u] = cur;

	for (halfEdge *e = adj[u]; e; e = e->next)
		if (e->v != fa)
		{
			int l = vl[e->v], r = vr[e->v];
			int next = cur - 1;
			if (l > next || next > r)
				next = cur + 1;

			construct(e->v, u, next);
		}
}

int main()
{
	cin >> n;
	for (int i = 1; i < n; ++i)
	{
		int u = getint(), v = getint();
		addEdge(u, v);
		addEdge(v, u);
	}

	cin >> m;
	for (int u = 1; u <= n; ++u)
		vl[u] = -INF, vr[u] = INF;
	for (int i = 0; i < m; ++i)
	{
		int u = getint(), v = getint();
		vl[u] = vr[u] = v;
	}

	dfs(1, 0);

	if (vl[1] <= vr[1])
	{
		construct(1, 0, vl[1]);

		puts("Yes");
		for (int u = 1; u <= n; ++u)
			printf("%d\n", vl[u]);
	}
	else
		puts("No");

	return 0;
}

