bool chmax(int &a, int b) {if (a < b) { a = b; return true; } else return false; }
bool chmin(int &a, int b) {if (a > b) { a = b; return true; } else return false; }

const int MAX = 110000;
int N;
vector<int> tree[MAX];

int K;
int P[MAX];
int lo[MAX], hi[MAX];
int res[MAX];

bool dfs(int v, int p) {
  bool can = true;
  lo[v] = hi[v] = -1;
  if (P[v] != -1) lo[v] = hi[v] = P[v];
  for (int i = 0; i < tree[v].size(); ++i) {
    int to = tree[v][i];
    if (to == p) continue;
    if (!dfs(to, v)) return false;
  }
  for (int i = 0; i < tree[v].size(); ++i) {
    int to = tree[v][i];
    if (to == p) continue;
    if (lo[to] == -1) continue;
    int tlo = lo[to] - 1;
    int thi = hi[to] + 1;
    if (lo[v] == -1) {
      lo[v] = tlo;
      hi[v] = thi;
    }
    else {
      if ( abs(lo[v] - tlo) % 2 != 0 ) return false;
      chmax(lo[v], tlo);
      chmin(hi[v], thi);
      if (lo[v] > hi[v]) return false;
    }
  }
  //cout << v << ": " << lo[v] << ", " << hi[v] << endl;
  return true;
}

void reconstruct(int v, int p) {
  if (p == -1) res[v] = hi[v];
  else {
    if (lo[v] != -1) res[v] = min(hi[v], res[p]+1);
    else res[v] = res[p]+1;
  }
  for (auto to : tree[v]) {
    if (to == p) continue;
    reconstruct(to, v);
  }
}


int main() {
  while (cin >> N) {
    for (int i = 0; i < MAX; ++i) tree[i].clear(), P[i] = -1;
    for (int i = 0; i < N-1; ++i) {
      int a, b;
      scanf("%d %d", &a, &b);
      --a, --b;
      tree[a].push_back(b);
      tree[b].push_back(a);
    }
    cin >> K;
    for (int i = 0; i < K; ++i) {
      int v, p;
      scanf("%d %d", &v, &p);
      --v;
      P[v] = p;
    }
    bool can = dfs(0, -1);
    reconstruct(0, -1);

    if (can) {
      puts("Yes");
      for (int i = 0; i < N; ++i) cout << res[i] << endl;
    }
    else puts("No");
  }
}

