const int INF = (1<<25);
const ll INFLL = (1ll<<60);
const ll MOD = (ll)(1e9+7);

#define l_ength size

void mul_mod(ll& a, ll b){
	a *= b;
	a %= MOD;
}

void add_mod(ll& a, ll b){
	a = (a<MOD)?a:(a-MOD);
	b = (b<MOD)?b:(b-MOD);
	a += b;
	a = (a<MOD)?a:(a-MOD);
}

int n,ufr[225816],ufp[225816],s[100100],x[100100];
vector<int> g[100100];
P rng[100100];

void ufinit(void){
	int i;
	for(i=0; i<n*2; ++i){
		ufr[i] = 1;
		ufp[i] = i;
	}
}

int ufind(int x){
	if(x == ufp[x]){
		return x;
	}
	ufp[x] = ufind(ufp[x]);
	return ufp[x];
}

void unionf(int x, int y){
	x = ufind(x);
	y = ufind(y);
	if(x == y){
		return;
	}
	if(ufr[x] < ufr[y]){
		swap(x,y);
	}
	ufr[x] += ufr[y];
	ufp[y] = x;
}

void solve1(int u, int p = -1){
	int i,v;
	for(i=(g[u].l_ength()-1); i>=0; --i){
		v = g[u][i];
		if(v == p){
			continue;
		}
		solve1(v,u);
		rng[u].first = max(rng[u].first,rng[v].first-1);
		rng[u].second = min(rng[u].second,rng[v].second+1);
	}
}

void solve2(int u, int p = -1){
	int i,v;
	ll val;
	val = rng[u].first;
	if(ufind(u+n*(abs(val)%2))!=ufind(s[0]+n*(x[0]%2))){
		++val;
	}
	rng[u].first = val; rng[u].second = val;
	for(i=(g[u].l_ength()-1); i>=0; --i){
		v = g[u][i];
		if(v == p){
			continue;
		}
		rng[v].first = max(rng[v].first,rng[u].first-1);
		rng[v].second = min(rng[v].second,rng[u].second+1);
		solve2(v,u);
	}
}

int main(void){
