	fill(rng,rng+n,P(-INFLL,INFLL));
	ufinit();
	for(i=1; i<n; ++i){
		cin >> u >> v;
		--u; --v;
		g[u].push_back(v);
		g[v].push_back(u);
		unionf(u,v+n);
		unionf(u+n,v);
	}
	cin >> k;
	for(i=0; i<k; ++i){
		cin >> s[i] >> x[i]; --s[i];
		rng[s[i]] = P(x[i],x[i]);
