void solve(vvi& g,vi& xs)
{
	int n=g.size();
	vector<vector<tuple<int,int>>> rs(n);
	rep(i,n) if(xs[i]!=-1)
		dfs(g,-1,i,xs[i],xs[i],xs,rs);

	vector<tuple<int,int>> ss(n);
	rep(i,n){
		int mn,mx; tie(mn,mx)=rs[i][0];
