			int x,y; tie(x,y)=p;
			if(mn%2!=x%2){
				cout<<"No"<<endl;
				return;
			}
			mn=max(mn,x);
			mx=min(mx,y);
		}
		if(mn>mx){
			cout<<"No"<<endl;
			return;
		}
		ss[i]=mt(mn,mx);
	}

	cout<<"Yes"<<endl;
	rep(i,n) cout<<get<0>(ss[i])<<endl;
}

