int l[maxn],r[maxn],odd[maxn];
bool have[maxn];

void dfs(int x,int par){
	int curl=-INF,curr=INF,curodd=0;
	rep(i,edge[x].size()){
		int y=edge[x][i];
		if(y==par)continue;
		dfs(y,x);
		if(curodd&&odd[y]==curodd){
			puts("No");
			exit(0);
		}
		if(odd[y])curodd=3-odd[y];
		curl=max(curl,l[y]-1);
		curr=min(curr,r[y]+1);
		if(curl>curr){
			puts("No");
			exit(0);
		}
	}
	if(have[x]){
		if(curl>l[x]||curr<r[x]||(curodd&&curodd!=odd[x])){
			puts("No");
			exit(0);
		}
	}
	else{
		l[x]=curl;
		r[x]=curr;
		odd[x]=curodd;
	}
} 

void dfs2(int x,int par){
	rep(i,edge[x].size()){
		int y=edge[x][i];
		if(y==par)continue;
		if(have[y]){
			if(l[x]-1>l[y]||r[x]+1<r[y]||(odd[x]&&odd[x]==odd[y])){
				puts("No");
				exit(0);
			}
			continue;
		}
		if(odd[x]&&odd[y]==odd[x]){
			puts("No");
			exit(0);
		}
		if(!odd[y])odd[y]=3-odd[x];
		l[y]=max(l[y],l[x]-1);
		r[y]=min(r[y],r[x]+1);
		if(l[y]>r[y]){
			puts("No");
			exit(0); 
		}
		dfs2(y,x);
	}
}

