void DFS(int nod, int fth)
{
    lft[nod] = -INF;
    rgt[nod] = INF;
    par[nod] = -1;
    if(v[nod] != -1)
    {
        lft[nod] = rgt[nod] = v[nod];
        par[nod] = v[nod] & 1;
    }

    for(auto nxt: edg[nod])
    {
        if(nxt == fth)  continue;

        DFS(nxt, nod);
        lft[nod] = max(lft[nod], lft[nxt] - 1);
        rgt[nod] = min(rgt[nod], rgt[nxt] + 1);
        if(par[nxt] != -1)
        {
            if(par[nod] == -1)
                par[nod] = 1 ^ par[nxt];
            if(par[nod] == par[nxt])
            {
                printf("No\n");
                exit(0);
            }
        }
    }

    if(lft[nod] > rgt[nod])
    {
        printf("No\n");
        exit(0);
    }
}

void solve(int nod, int fth)
{
    if(v[nod] == -1)
    {
        if( lft[nod] <= v[fth] - 1 && v[fth] - 1 <= rgt[nod] )
            v[nod] = v[fth] - 1;
        else if( lft[nod] <= v[fth] + 1 && v[fth] + 1 <= rgt[nod] )
            v[nod] = v[fth] + 1;
        else
        {
            printf("No\n");
            exit(0);
        }
    }

    for(auto nxt: edg[nod])
    {
        if(nxt == fth)  continue;
        solve(nxt, nod);
    }
}

