inline void ERROR() {
	printf("No\n");
	exit(0);
}

struct Range {
	int l, r;
	Range(int _l = -inf, int _r = inf) {
		l = _l;
		r = _r;
	}
	void CombineRange(int nl, int nr) {
		l = max(l, nl);
		r = min(r, nr);
		if (l > r)
			ERROR();
	}
} range[N];

int dis[N];
vector <int> g[N];
int val[N];

void bfs(int s) {
	queue <int> que;
	que.push(s);
	while (!que.empty()) {
		int u = que.front(); que.pop();
		for (int i = 0; i < (int) g[u].size(); ++ i) {
			int v = g[u][i];
			if (!~dis[v]) {
				dis[v] = dis[u] ^ 1;
				range[v].CombineRange(range[u].l - 1, range[u].r + 1);
				que.push(v);
			}
			else if (dis[v] != (dis[u] ^ 1))
				ERROR();
		}
	}
}

void bfs1(int s) {
	queue <int> que;
	que.push(s);
	while (!que.empty()) {
		int u = que.front(); que.pop();
		for (int i = 0; i < (int) g[u].size(); ++ i) {
			int v = g[u][i];
			if (val[v] == -inf) {
				Range rangev = range[v];
				rangev.CombineRange(val[u] - 1, val[u] + 1);
//				printf("%d %d %d\n", v, rangev.l, rangev.r);
				val[v] = rangev.l;
				que.push(v);
			}
		}
	}
}

