	for (int q = 0; q < vertexs[now].size(); ++q) {
		if (vertexs[now][q] != back) {
			int now_ans = final_ans[now];
			int next_itr = vertexs[now][q];
			if (geko[next_itr].first <= now_ans + 1 && now_ans + 1 <= geko[next_itr].second) {
				final_ans[next_itr] = now_ans + 1;
