			else if(ki[x]==ki[a[i].v]){died=1;return ;}
		}
	if(mi[x]>mx[x]){died=1;return ;}
	if(is[x])
		if(mi[x]>is[x]||mx[x]<is[x]){died=1;return ;}
		else mx[x]=mi[x]=is[x];
}

