void check(int u, int fa) {
    l[u] = -inf - 1, r[u] = inf + 1;
    if(~ans[u]) l[u] = r[u] = ans[u];
    for(int i = head[u]; i; i = edge[i].nxt) {
        int v = edge[i].to;
        if(v != fa) {
            check(v, u);
            if(l[v] < -inf) continue;
            if(l[u] < -inf) {
                l[u] = l[v] - 1, r[u] = r[v] + 1;
            }
            else {
                if((abs(l[u]) & 1) == (abs(l[v]) & 1)) {
                    flag = 0;
                    return;
                }
                l[u] = max(l[u], l[v] - 1);
                r[u] = min(r[u], r[v] + 1);
            }
        }
    }
    if(l[u] > r[u]) flag = 0;
}

void make(int u, int fa) {
    for(int i = head[u]; i; i = edge[i].nxt) {
        int v = edge[i].to;
        if(v != fa) {
            if(ans[v] == -1) {
                if(l[v] <= ans[u] - 1 && ans[u] - 1 <= r[v]) ans[v] = ans[u] - 1;
                else ans[v] = ans[u] + 1;
            }
            make(v, u);
        }
    }
}

