#include <bits/stdc++.h>
using namespace std;
#define VI vector<int>

void dfsGetIntervals(int node, vector<VI> &G, VI &lf, VI &rt, VI &d) {
    for(auto temp : G[node]) {
        if(d[temp] > -1)
            continue;
        d[temp] = d[node] + 1;
        dfsGetIntervals(temp, G, lf, rt, d);
        lf[node] = max(lf[node], lf[temp] - 1);
        rt[node] = min(rt[node], rt[temp] + 1);
    }
}

void dfsSolve(int node, vector<VI> &G, VI &lf, VI &rt, VI &sol) {
    for(auto temp : G[node]) {
        if(sol[temp] > -1e9)
            continue;
        for(int d = -1; d <= 1; d += 2)
            if(lf[temp] <= sol[node] + d && sol[node] + d <= rt[temp])
                sol[temp] = sol[node] + d;
        assert(sol[temp] > -1e9);
        dfsSolve(temp, G, lf, rt, sol);
    }
}

int main() {

    //ifstream cin("testE.in");

    int n; cin >> n;
    vector<VI> G(n);

    for(int i = 0; i < n - 1; ++i) {
        int a, b; cin >> a >> b;
        a--, b--;
        G[a].push_back(b);
        G[b].push_back(a);
    }

    VI lf(n, 0), rt(n, 0);
    VI mark(n, 0);

    for(int i = 0; i < n; ++i) {
        lf[i] = -3 * n;
        rt[i] = 3 * n;
    }

    int k; cin >> k;

    for(int i = 0; i < k; ++i) {
        int who, val; cin >> who >> val;
        who--;
        mark[who] = 1;
        lf[who] = val, rt[who] = val;
    }

    VI d(n, -1);
    d[0] = 0;
    dfsGetIntervals(0, G, lf, rt, d);

    for(int i = 0; i < n; ++i)
        if(lf[i] > rt[i]) {
            cout << "No\n";
            return 0;
        }

    VI par(2, -1);

    for(int i = 0; i < n; ++i) {
        if(par[d[i] % 2] == -1 && mark[i]) {
            par[d[i] % 2] = lf[i] % 2;
        } else if(mark[i] && par[d[i] % 2] != lf[i] % 2) {
            cout << "No\n";
            return 0;
        }
    }

    cout << "Yes\n";
    vector<int> sol(n, -1e9);
    sol[0] = lf[0];

    dfsSolve(0, G, lf, rt, sol);

    for(auto temp : sol)
        cout << temp << "\n";
}

