const ll MOD = 1e9+7;

int main() {
  std::cin.tie(0);
  std::ios::sync_with_stdio(false);
  //問題文中の添え字が0-indexか1-indexか確認!

  ll n;
  std::cin>>n;

  std::vector<std::vector<ll>> graph(n);
  std::vector<ll> num(n,-1);

  rep(i,0,n-1){
    ll a,b;
    std::cin>>a>>b;

    a--;b--;
    graph[a].push_back(b);
    graph[b].push_back(a);
  }

  ll k;
  std::cin>>k;

  ll root;

  rep(i,0,k){
    ll v,p;
    std::cin>>v>>p;
    v--;
    num[v]=p;
    root=v;
  }

  struct Point{ll from,now,odd;};

  std::vector<ll> sort;

  std::queue<Point> que;
  que.push(Point{-1,root,(num[root]+1)%2});

  while(que.size()){
    Point e=que.front();que.pop();
    sort.push_back(e.now);
    if((num[e.now]!=-1)&&(num[e.now]%2==e.odd)){
      std::cout<<"No";
      return 0;
    }

    for(ll i:graph[e.now]){
      if(i!=e.from){
        que.push(Point{e.now,i,(e.odd+1)%2});
      }
    }
  }

  std::vector<P> len(n,{-MOD,MOD});

  std::vector<bool> used(n,false);

  for(ll i=n-1;i>=0;i--){
    ll now=sort[i];
    used[now]=true;
    if((len[now].first>len[now].second)||((num[now]!=-1)&&((len[now].first>num[now])||(num[now]>len[now].second)))){
      std::cout<<"No";
      return 0;
    }
    if(num[now]!=-1)len[now]={num[now],num[now]};

    for(ll next:graph[now]){
      if(!used[next]){
        len[next]={std::max(len[next].first,len[now].first-1),std::min(len[next].second,len[now].second+1)};
      }
    }
  }

  que.push({-1,root,num[root]-1});

  while(que.size()){
    Point e=que.front();que.pop();
    if(e.odd+1<=len[e.now].second)num[e.now]=e.odd+1;
    else num[e.now]=e.odd-1;

    for(ll i:graph[e.now]){
      if(i!=e.from){
        que.push({e.now,i,num[e.now]});
      }
    }
  }

  std::cout<<"Yes\n";

  rep(i,0,n)std::cout<<num[i]<<"\n";

  return 0;
}

