bool __dfs(int cur, int pre, int num){
	if(high[cur] % 2 != num % 2) return true;

	bool res = false;
	for(auto to : g[cur]){
		if(to == pre or high[cur] == INF) continue;
		res |= __dfs(to, cur, num + 1);
	}
	return false;
}

void dfs(int cur, int pre){
	for(auto to : g[cur]){
		if(to == pre) continue;

		dfs(to, cur);
