const ll MOD = 1000000007;
const int iNF = 0x3f3f3f3f;
const ll MAXN = 100005;

int n, k, num[MAXN];
vector<int> edge[MAXN];

bool valid (int nd, int par) {
    bool ret = true;
    for (auto v : edge[nd]) {
        if (v != par) {
            ret &= valid(v, nd);
            if (num[nd] != iNF && num[v] != iNF) {
                ret &= abs(num[v] - num[nd]) == 1;
            }
        }
    }
    return ret;
}

pii wev = {-iNF, iNF};
pii nso = {iNF, -iNF};
pii rng[MAXN];
bool vis[MAXN];
void dfs (int nd, int par) {
    vis[nd] = true;
    if (num[nd] != iNF) {
        rng[nd] = pii(num[nd], num[nd]);
    } else if (nd != par && SZ(edge[nd]) == 1) { // leaf
        rng[nd] = wev;
    } else {
        rng[nd] = wev;
        for (auto v : edge[nd]) {
            if (v != par) {
                dfs(v, nd);
                pii ch = {rng[v].X - 1, rng[v].Y + 1};
                if (rng[v] != wev) {
                    if (rng[nd] == wev) {
                        rng[nd] = ch;
                    } else if (rng[nd].X % 2 != ch.X % 2) {
                        rng[nd] = nso;
                    } else {
                        rng[nd].X = max(rng[nd].X, ch.X);
                        rng[nd].Y = min(rng[nd].Y, ch.Y);
                    }
                }
            }
        }
    }
}

void write (int nd, int par, int cur) {
    if (num[nd] != iNF) {
        return;
    }
    num[nd] = cur;
    for (auto v : edge[nd]) {
        if (v != par) {
            if (cur + 1 >= rng[v].X && cur + 1 <= rng[v].Y) {
                write(v, nd, cur + 1);
            } else if (cur - 1 >= rng[v].X && cur - 1 <= rng[v].Y) {
                write(v, nd, cur - 1);
            }
        }
    }
}
