Range range[112345];

void fillRange(int i, Range nowRange) {
  Range tempRange = range[i] and nowRange;
  if( range[i] == tempRange ) return;
  range[i] = range[i] and nowRange;
  for(Edge edge : edges[i]) {
    if( num[edge.to] != -(1<<28) ) continue;
    fillRange(edge.to, Range(nowRange.lower - 1, nowRange.upper + 1));
  }
}

