const int N = 1e5+7, inf = 1e9;

#define pii pair<int,int>
#define fi first
#define se second

vector<int> g[N], ans(N);
vector<pii> range(N, {-inf, inf}), edge;
int n, k;

pii merge(pii x, pii y){
	if(x > y) swap(x, y);
	return {max(x.fi, y.fi), min(x.se, y.se)};
}

void dfs(int p, int u){
	for(auto v: g[u]){
		if(v != p){
			dfs(u, v);
			range[u] = merge(range[u], {range[v].fi - 1, range[v].se + 1});
		}
	}
}

void build(int p, int u){
	for(auto v: g[u]){
		if(v != p){
			if(range[v].fi <= ans[u] - 1 && ans[u] - 1 <= range[v].se) ans[v] = ans[u] - 1;
			else ans[v] = ans[u] + 1;
			build(u, v);
		}
	}
}

