const ll INF = (1ll<<60);
vector<ll> lb(101010, -INF), ub(101010, INF), parity(101010, -1);

pll merge(ll L1, ll R1, ll L2, ll R2){
	if(L1 == INF or L2 == INF) return {INF, -INF};
	if(L1 > L2){
		swap(L1, L2);
		swap(R1, R2);
	}

	if(L2>R1){
		return {INF, -INF};
	}else{
		return {L2, min(R1, R2)};
	}
}

void dfs1(ll now, ll par, Graph &G){

	ll L = lb[now], U = ub[now], bi = parity[now];

	for(auto next: G[now]){
		if(next == par) continue;
		dfs1(next, now, G);

		// update of segment
		auto tmp = merge(L, U, lb[next]-1, ub[next]+1);
		L = tmp.first;
		U = tmp.second;

		// update of bi

		if(parity[next] != -1){
			if(bi == -1){
				bi = 1 - parity[next];
			}else{
				if(bi != 1-parity[next]){
					cout << "No" << endl;
					exit(0);
				}
			}
		}
	}

	if(L == INF){
		cout << "No" << endl;
		exit(0);
	}

	lb[now] = L;
	ub[now] = U;
	parity[now] = bi;

	return;
}

void dfs2(ll now, ll par, Graph &G, vector<ll> &P){
	if(par == -1){
		if(parity[now] == 0 and lb[now]%2) P[now] = lb[now]+1;
		if(parity[now] == 0 and !lb[now]%2) P[now] = lb[now];
		if(parity[now] == 1 and lb[now]%2) P[now] = lb[now];
		if(parity[now] == 1 and !lb[now]%2) P[now] = lb[now]+1;
	}else{
		ll x1 = P[par]-1;
		ll x2 = P[par]+1;
		if(lb[now]<=x1 and x1<=ub[now]) P[now] = x1;
		else P[now] = x2;
	}

	for(auto next: G[now]){
		if(next == par) continue;
		dfs2(next, now, G, P);
	}
	return;
}

