int stat[maxn];
void preDfs(const int u,const int prev, const int sign) {
	stat[u] = sign;
	for (int v : V[u]) if (v != prev) {
		if (p[v] != -1 && ((p[v] & 1) !=  (sign ^ 1)) ) return fail();
		preDfs(v, u, sign ^ 1);
	}
