int upper[maxn], lower[maxn];
const int MX = 1000000;
void solveUpper(int p[], int upper[]) {
	priority_queue<pair<int,int> > qu;
	For(i,1,n) if (p[i] == -1) {
		upper[i] = MX;
		for (int j : V[i]) if (p[j] != -1) {
			upper[i] = min(upper[i], p[j] + 1);
		}
		if (upper[i] < MX) {
			qu.push(make_pair(-upper[i], i));
		}
	}

	while (!qu.empty()) {
		auto cur = qu.top(); qu.pop();
		int u = cur.second;
		if (upper[u] != -cur.first) {
			continue;
		}

		for (int v : V[u]) if (p[v] == -1) {
			int z = upper[u] + 1;
			if (z < upper[v]) {
				upper[v] = z;
				qu.push(make_pair(-upper[v], v));
			}
		}
	}
}

bool inrange(const int l, const int r, const int mid) {
	return mid >= l && mid <= r;
}
inline void dfsCal(const int u, const int prev) {
	for (int v : V[u]) if (v != prev) {
		if (p[v] == -1) {
			if (inrange(lower[v], upper[v], p[u] - 1)) {
				p[v] = p[u] - 1;
			} else p[v] = p[u] + 1;
		}
		dfsCal(v, u);
	}
}

bool was[maxn];
void bfsCal(int root) {
	queue<int> qu;
	qu.push(root);
	memset(was,false,sizeof(was));
	was[root] = true;
	while (!qu.empty()) {
		int u = qu.front(); qu.pop();
		for (int v : V[u]) if (!was[v]) {
			was[v] = true;
			if (p[v] == -1) {
				if (inrange(lower[v], upper[v], p[u] + 1)) {
					p[v] = p[u] + 1;
				} else p[v] = p[u] - 1;
			}
			qu.push(v);
		}
	}
}

void Process() {
	solveUpper(p,upper);
	For(i,1,n) if (p[i] != -1) p[i] = MX - p[i];
	solveUpper(p,lower);
	For(i,1,n) if (p[i] != -1) p[i] = MX - p[i];
	For(i,1,n) lower[i] = MX - lower[i];

	bfsCal(root);
	For(i,1,n) {
		for (int j : V[i]) {
			if (abs(p[i] - p[j]) != 1) {
				return fail();
			}
		}
	}

	cout << "Yes" << endl;
	For(i,1,n) cout << p[i] << "\n";
}

