const int maxn = 100100;
int seen[maxn], unk[maxn], par[maxn], l[maxn], r[maxn];
vector<int> e[maxn], ord;
void dfs(int u, int v){
	ord.push_back(u);
	for(int to : e[u]) if(to != v) dfs(to, u);
}
int main(){
	int n; cin >> n;
	for(int i = 0; i < n - 1; i++){
		int x, y; cin >> x >> y; x--; y--;
		e[x].push_back(y);
		e[y].push_back(x);
	}
	int k; cin >> k;
	for(int i = 0; i < k; i++){
		int v, p; cin >> v >> p; v--;
		unk[v] = 1; par[v] = p&1; l[v] = p; r[v] = p;
	}
	dfs(0, -1);
	auto bad = [&](){
		cout << "No" << endl;
		exit(0);
	};
	auto push = [&](int v, int m2, int ll, int rr){
		if(!unk[v]){
			unk[v] = 1;
			par[v] = m2;
			l[v] = ll;
			r[v] = rr;
		} else {
			if(par[v] != m2) bad();
			l[v] = max(l[v], ll);
			r[v] = min(r[v], rr);
			if(l[v] > r[v]) bad();
		}
	};
	auto relax = [&](int from, int to, int step){
		memset(seen, 0, sizeof(seen));
		while(from != to){
			int v = ord[from];
			seen[v] = 1;
			if(unk[v]){
				for(int u : e[v]){
					if(!seen[u]){
						push(u, par[v] ^ 1, l[v] - 1, r[v] + 1);	
					}
				}
			}
			from += step;
		}
	};
	auto force = [&](int from, int to, int step){
		memset(seen, 0, sizeof(seen));
		while(from != to){
			int v = ord[from];
			seen[v] = 1;
			if(!unk[v]) bad();
			r[v] = l[v];
			for(int u : e[v]){
				if(!seen[u]){
					push(u, par[v] ^ 1, l[v] - 1, r[v] + 1);	
				}
			}
			from += step;
		}
	};
	relax(0, n, 1);
	relax(n - 1, -1, -1);
	relax(0, n, 1);
	relax(n - 1, -1, -1);
	relax(0, n, 1);
	relax(n - 1, -1, -1);
	relax(0, n, 1);
	relax(n - 1, -1, -1);
	force(0, n, 1);
	cout << "Yes" << endl;
	for(int i = 0; i < n; i++) cout << l[i] << endl;
	return 0;
}

