	for (int u = 1; u <= n; ++u)
		vl[u] = -INF, vr[u] = INF;
	for (int i = 0; i < m; ++i)
	{
		int u = getint(), v = getint();
		vl[u] = vr[u] = v;
	}

	dfs(1, 0);

	puts("No");
	return 0;

	if (vl[1] <= vr[1])
	{
		construct(1, 0, vl[1]);

		puts("Yes");
		for (int u = 1; u <= n; ++u)
			printf("%d\n", vl[u]);
	}
	else
		puts("No");

	return 0;
}

