const int INF = 1e9;

void NO() {
  cout << "No" << endl;
  exit(0);
}

class Tree {
 public:
  Tree(const auto& G, const auto& W) : child(G.size()), interval(G.size(), {-INF, INF}) {build(G, W);}

  void solve() {
    function<void(int)> dp = [&](int cur) {
      for(auto nex: child[cur]) {
        dp(nex);
        auto i = interval[nex];
        if(i.max != INF) {
          --i.min; ++i.max;
          if(i.max<interval[cur].min ||interval[cur].max<i.min) NO();
          if(interval[cur].max != INF) {
            if((i.min&1) != (interval[cur].min&1)) NO();
            if((i.max&1) != (interval[cur].max&1)) NO();
          }
        }
        interval[cur].min = max(interval[cur].min, i.min);
        interval[cur].max = min(interval[cur].max, i.max);
      }
    };
    dp(0);

    vector<int> ans(interval.size(), INF);
    ans[0] = interval[0].min;
    function<void(int, int)> aadp = [&](int cur, int pre) {
      if(cur != 0) {
        auto min = ans[pre] - 1;
        auto max = ans[pre] + 1;
        if(interval[cur].min <= min && min <= interval[cur].max) ans[cur] = min;
        if(interval[cur].min <= max && max <= interval[cur].max) ans[cur] = max;
        if(ans[cur] == INF) NO();
      }
      interval[cur];
      for(auto nex: child[cur]) aadp(nex, cur);
    };
    aadp(0, 0);

    cout << "Yes" << endl;
    for(auto i: ans) cout << i << endl;
  }

 private:
  struct Interval {int min, max;};

  void build(const auto& G, const auto& W) {
    function<void(int, int)> dfs = [&](auto cur, auto pre) {
      if(W[cur] != INF) interval[cur] = {W[cur], W[cur]};
      for(const auto& nex: G[cur]) if(nex != pre) {
        child[cur].emplace_back(nex);
        dfs(nex, cur);
      }
    };
    dfs(0, 0);
  }

  vector<vector<int>> child;
  vector<Interval> interval;
};

int main() {
  int N;
