    vector<vector<int>> E(N);
    for (int i=0; i<N-1; i++)
    {
        int A, B;
        cin>>A>>B;
        E[A-1].push_back(B-1);
        E[B-1].push_back(A-1);
    }
    int K;
    cin>>K;
    int oo = 2000000;
    vector<int> L(N,-oo), U(N,+oo), P(N,-1);

    for (int i=0; i<K; i++)
    {
        int v, p;
        cin>>v>>p;
        L[v-1] = U[v-1] = p;
        P[v-1] = p%2;
    }

    function<void(int,int)> BT1 = [&](int cur, int pre)
    {
        bool e = P[cur]==-1 || P[cur]==0;
        bool o = P[cur]==-1 || P[cur]==1;

        for (int c: E[cur])
        if (c!=pre)
        {
            BT1(c, cur);
            L[cur] = max(L[cur], L[c]-1);
            U[cur] = min(U[cur], U[c]+1);
            if (P[c]==0)
                e = false;
            if (P[c]==1)
                o = false;
        }

        if (e && !o)
            P[cur] = 0;
        if (!e && o)
            P[cur] = 1;
        if (!e && !o)
            L[cur] = +oo,
            U[cur] = -oo;
    };
    BT1(0, -1);

    bool ok = true;
    for (int i=0; i<N; i++)
        if (L[i]>U[i])
            ok = false;

    if (ok)
    {
        cout<<"Yes"<<endl;
        vector<int> A(N);

        function<void(int,int)> BT2 = [&](int cur, int pre)
        {
            if (pre==-1)
                A[cur] = L[cur];
            else
                A[cur] = L[cur]<=A[pre]-1 && A[pre]-1<=U[cur] ? A[pre]-1 : A[pre]+1;

            for (int c: E[cur])
            if (c!=pre)
                BT2(c, cur);
        };
        BT2(0, -1);
        for (int a: A)
            cout<<a<<endl;
    }
    else
    {
        cout<<"No"<<endl;
    }
}

