	else l[x]=r[x]=v[x];
	for(int i=head[x];i;i=nxt[i])
	{
		if(ver[i]==f)continue;
		l[ver[i]]=max(l[ver[i]],v[x]-1);
		r[ver[i]]=min(r[ver[i]],v[x]+1);
