struct range
{
	int64_t max;
	int64_t min;
};
bool check(int now, int from, range ran, std::map<int, std::set<int>>const& edge, std::vector<boost::optional<range>>& data)
{
	if (data[now])
	{
		if ((data[now]->max + ran.max) % 2 != 0)
		{
			return false;
		}
		data[now]->max = std::min(data[now]->max, ran.max);
		data[now]->min = std::max(data[now]->min, ran.min);
		if (data[now]->max < data[now]->min)
		{
			return false;
		}
	}
	else
	{
		data[now] = ran;
	}
	for (auto v : edge.at(now))
	{
		if (v == from)
			continue;
		if (!check(v, now, range{ ran.max + 1,ran.min - 1 }, edge, data))
		{
			return false;
		}
	}
	return true;
}
