using namespace std;
#define VI vector<int>

void dfsGetIntervals(int node, vector<VI> &G, VI &lf, VI &rt, VI &d) {
    for(auto temp : G[node]) {
        if(d[temp] > -1)
            continue;
        d[temp] = d[node] + 1;
        dfsGetIntervals(temp, G, lf, rt, d);
        lf[node] = max(lf[node], lf[temp] - 1);
        rt[node] = min(rt[node], rt[temp] + 1);
    }
}

void dfsSolve(int node, vector<VI> &G, VI &lf, VI &rt, VI &sol) {
    for(auto temp : G[node]) {
        if(sol[temp] > -1e9)
            continue;
        for(int d = -1; d <= 1; d += 2)
            if(lf[temp] <= sol[node] + d && sol[node] + d <= rt[temp])
                sol[temp] = sol[node] + d;
        assert(sol[temp] > -1e9);
        dfsSolve(temp, G, lf, rt, sol);
    }
}

