typedef pair<int, int> ii;

bool ans = true;

ii merge(ii a, ii b){
	if(a.first == -1) return b;
	if(b.first == -1) return a;
	if(a.first > b.first) swap(a, b);
	if(a.second < b.first){
		//cout<<"SHITS "<<a.first<<" "<<a.second<<" "<<b.first<<" "<<b.second<<endl;
		cout<<"No"<<endl;
		exit(0);
	}
	return {b.first, a.second};
}

vector<ii> up;

ii propUp(int cur, int par){
	ii v = {a[cur], a[cur]};
	for(int u: g[cur]){
		if(u == par){
			continue;
		}

		ii c = propUp(u, cur);
		if(c.first != -1){
			c.first -= 1; c.second += 1;
		}
		v = merge(c, v);
	}
	up[cur] = v;
	return v;
}

void propDown(int cur, int par, ii val = {-1, -1}){
	up[cur] = merge(up[cur], val);
	for(int u: g[cur]){
		if(u == par) continue;
		ii temp = up[cur];
		if(temp.first != -1){
			temp.first -=1, temp.second += 1;
		}
		propDown(u, cur, temp);
	}
}

vector<int> as;

void assign(int cur, int par, int pval = -1){
	if(pval == -1){
		as[cur] = up[cur].first;
	}else{
		if(up[cur].first <= pval - 1 && up[cur].second >= pval - 1){
			as[cur] = pval - 1;
		}else if(up[cur].first <= pval + 1 && up[cur].second >= pval + 1){
			as[cur] = pval + 1;
		}else{
			assert(false);
		}
	}
	for(int u: g[cur])	{
		if(u == par) continue;
		assign(u, cur, as[cur]);
	}
}

