vector<PLL> poss;

PLL dfs(int64 v, int64 p) {
    if (p != -1 && poss[p].fs != -INF) {
        chmax(poss[v].fs, poss[p].fs-1);
        chmin(poss[v].sc, poss[p].sc+1);
        if (poss[v].fs > poss[v].sc) {
            cout << "No" << endl;
            exit(0);
        }
    }
    for (auto &u : G[v]) {
        if (u == p) continue;
        PLL ret = dfs(u, v);
        if (poss[v] == PLL(-INF, INF)) {
            poss[v] = ret;
        } else {
            chmax(poss[v].fs, ret.fs);
            chmin(poss[v].sc, ret.sc);
            if ((ret.fs > -INF && abs(poss[v].fs)%2 != abs(ret.fs)%2) || poss[v].sc < poss[v].fs) {
                cout << "No" << endl;
                exit(0);
            }
        }
    }
//    cout << v << " " << p << " (" << poss[v].fs << " " << poss[v].sc << ") " << endl;
    return PLL(poss[v].fs-1, poss[v].sc+1);
}

