vector<int> g[MAXN];

bool flag = false;
int L[MAXN], R[MAXN];

void dfs_down(int v, int p) {
    for (int to:g[v]) {
        if (to == p)
            continue;
        if (L[to] < L[v] - 1) {
            L[to] = L[v] - 1;
            flag = true;
        }
        if (R[to] > R[v] + 1) {
            R[to] = R[v] + 1;
            flag = true;
        }
        dfs_down(to, v);
    }
}

void dfs_up(int v, int p) {
    for (int to:g[v]) {
        if (to == p)
            continue;

        dfs_up(to, v);
        if (L[v] < L[to] - 1) {
            L[v] = L[to] - 1;
            flag = true;
        }
        if (R[v] > R[to] + 1) {
            R[v] = R[to] + 1;
            flag = true;
        }
    }
}

int val[MAXN];

void dfs(int v, int p, int vl = 0) {
    bool first = true;
    if (vl) {
        L[v] = max(L[v], vl - 1);
        R[v] = min(R[v], vl + 1);
    }
    for (int to:g[v]) {
        if (to == p)
            continue;


        if (first) {
            dfs(to, v);
            L[v] = max(L[v], val[to] - 1);
            R[v] = min(R[v], val[to] + 1);
            assert(L[v] <= R[v]);
            val[v] = L[v];
            first = false;
        } else {
            dfs(to, v, val[v]);

        }
    }

    if (first == true) {
        val[v] = L[v];
    }
}

