    for (int i = 1; i <= n; ++i) {
        L[i] = -inf_int;
        R[i] = inf_int;
    }
    for (int i = 1; i <= k; ++i) {
        int v, x;
        cin >> v >> x;
        L[v] = R[v] = x;
    }

    int it = 1;
    while (true) {
        dout << "it " << it << endl;
        it++;
        flag = false;
        dfs_up(1, -1);
        dfs_down(1, -1);
        for (int i = 1; i <= n; ++i) {
            if (L[i] > R[i]) {
                cout << "No";
                return;
            }
        }
        if (!flag) {
            break;
        }
    }

    dfs(1, -1);
    cout <<"Yes\n";
    for(int i=1;i<=n;++i){
        cout << val[i]<<"\n";
    }


}

