#include <bits/stdc++.h>
using namespace std; 
int N, K; 
vector<int> E[100010]; 
int D[100010]; 
int mn[100010]; int mx[100010]; 
int INF = 1145141919; 
int ans[100010] = {}; 
void dfs1(int now, int parent, int dist){
	D[now] = dist; 
	for(int i = 0; i < E[now].size(); i++){
		if(E[now].at(i) == parent) continue; 
		dfs1(E[now].at(i), now, dist + 1); 
	}
}
void dfs2(int now, int parent){
	int m = -INF; int M = INF;
	for(int i = 0; i < E[now].size(); i++){
		if(E[now].at(i) == parent) continue; 
		dfs2(E[now].at(i), now); 
		m = max(m, mn[E[now].at(i)]); 
		M = min(M, mx[E[now].at(i)]); 
		mn[now] = max({-INF, m - 1, mn[now]}); 
		mx[now] = min({INF, M + 1, mx[now]}); 
	}	
}
void dfs3(int now, int parent, int value){
	if(!ans[now]) ans[now] = value;
	for(int i = 0; i < E[now].size(); i++){ 
		if(E[now].at(i) == parent) continue;
		if(value - 1 >= mn[E[now].at(i)] && value - 1 <= mx[E[now].at(i)]){
			dfs3(E[now].at(i), now, value - 1); 
		}
		else dfs3(E[now].at(i), now, value + 1);  
	}	
}
int main(){
	cin >> N; 
	for(int i = 0; i < N-1; i++){
		int a, b; cin >> a >> b;  
		a--; b--; 
		E[a].push_back(b); 
		E[b].push_back(a); 
	}
	fill(mn, mn + N, -INF); 
	fill(mx, mx + N, INF); 
	dfs1(0, -1, 0); 
	cin >> K; 
	int odd = 0; int even = 0; 
	for(int i = 0; i < K; i++){
		int v, p; cin >> v >> p; 
		v--; 
		mn[v] = p; mx[v] = p; 
		if(abs(D[v] - p) % 2) odd ++; 
		else even ++; 
		ans[v] = p; 
	}
	if(odd != 0 && even != 0){
		cout << "No" << endl; return 0; 
	}
	dfs2(0, -1); 
	for(int i = 0; i < N; i++){
		if(mn[i] > mx[i]){
			cout << "No" << endl; return 0; 
		}
	}
	cout << "Yes" << endl; 
	dfs3(0, -1, mn[0]); 
	for(int i = 0; i < N; i++) cout << ans[i] << endl; 
}

