struct edge { int ver,next; } e[N*2];
int n,k,t,Head[N],val[N];
inline void insert(int x,int y) { e[++t] = (edge){y,Head[x]} , Head[x] = t; }
inline void input(void)
{
    scanf("%d",&n);
    for (int i=1;i<n;i++)
    {
        int x,y;
        scanf("%d%d",&x,&y);
        insert( y , x );
        insert( x , y );
    }
    scanf("%d",&k);
    for (int i=1;i<=k;i++)
    {
        int x,y;
        scanf("%d%d",&x,&y);
        val[x] = y;
    }
}
inline void solve(void)
{
    priority_queue < pii , vector< pii > , greater< pii > > Heap;
    for (int i=1;i<=n;i++)
        if ( val[i] != -1 )
            Heap.push( make_pair( val[i] , i ) );
    if ( Heap.empty() )
        Heap.push( make_pair( 1 , 1 ) ) , val[1] = 1;
    while ( !Heap.empty() )
    {
        int x = Heap.top().second; Heap.pop();
        for (int i=Head[x];i;i=e[i].next)
        {
            int y = e[i].ver;
            if ( val[y] == -1 )
            {
                val[y] = val[x] + 1;
                Heap.push( make_pair( val[y] , y ) );
            }
        }
    }
}
inline bool check(void)
{
    for (int i=1;i<=n;i++)
        for (int j=Head[i];j;j=e[j].next)
            if ( abs( val[e[j].ver] - val[i] ) != 1 )
                return false;
    return true;
}
