{
    memset( val , 0xff , sizeof val );
    input();
    solve();
    if ( check() )
    {
        puts("Yes");
        for (int i=1;i<=n;i++)
            printf("%d\n",val[i]);
    }
    else puts("No");
    return 0;
}

