void prod(int x, int y) {
	if(has[y]) {
		if(has[x] && abs(mi[x] - mi[y]) % 2 == 0) { ans = false; }

		if(has[x]) {
			mi[x] = max(mi[x], mi[y] - 1);
			ma[x] = min(ma[x], ma[y] + 1);
		} else {
			mi[x] = mi[y] - 1;
			ma[x] = ma[y] + 1;
		}
		if(mi[x] > ma[x]) { ans = false; }
		has[x] = true;
	}
}

void dfs(int node, int pre) {
	if(pre != -1) { prod(node, pre); }
	for(auto && i : vec[node]) {
		if(i != pre) {
			dfs(i, node);
			prod(node, i);
		}
	}
}

