#include <bits/stdc++.h>

using namespace std;

vector<int> adj[100010];
int arr[100010];
int meml[100010];
int memr[100010];
const int INF = 1000000;

bool f(int x, int p, int l, int r, int d)
{
    if(arr[x] != -1)
    {
        if(arr[x] % 2 != d % 2 || arr[x] < l || arr[x] > r)
            return 0;
        l = r = arr[x];
    }

    for(int y : adj[x])
    {
        if(y == p)
            continue;

        if(!f(y, x, l - 1, r + 1, d + 1))
            return 0;

        l = max(l, meml[y] - 1);
        r = min(r, memr[y] + 1);
        if(r < l)
            return 0;
    }

    meml[x] = l;
    memr[x] = r;
    return 1;
}

bool g(int x, int p, int l, int r)
{
    if(arr[x] != -1 && (arr[x] < l || arr[x] > r))
        return 0;

    l = max(l, meml[x]);
    r = min(r, memr[x]);
    if(r < l)
        return 0;

    if(arr[x] == -1)
    {
        arr[x] = l;
        r = l;
    }

    for(int y : adj[x])
    {
        if(y == p)
            continue;

        if(!(g(y, x, l - 1, r + 1)))
            return 0;
    }

    return 1;
}

int main()
{
    int n, k, i;
    scanf("%d", &n);
    for(i = 0; i < n - 1; i++)
    {
        int x, y;
