    int s;
    for(i = 0; i < k; i++)
    {
        int x, p;
        scanf("%d%d", &x, &p);
        arr[x] = p;
        s = x;
    }

    bool ok = f(s, s, -INF, INF, arr[s] % 2);
    if(!ok)
    {
        puts("No");
        return 0;
    }

    ok = g(s, s, -INF, INF);
    if(!ok)
    {
        puts("No");
        return 0;
    }

    puts("Yes");
    for(i = 1; i <= n; i++)
        printf("%d\n", arr[i]);

    return 0;
}

