    _init();
    flag=1;
    scanf("%d",&n);
    int x,y;
    for (int i=1;i<n;i++) {
        scanf("%d%d",&x,&y);
        add(x,y);
    }
    scanf("%d",&k);
    for (int i=1;i<=k;i++) {
        scanf("%d%d",&x,&y);
        a[x]=y; mark[x]=1;
    }
    for (int i=1;i<=n;i++) {
        if (!mark[i]) continue;
        v[i]=a[i]&1; dfs1(i,0);
    }
    if (!flag) {
        puts("No");
        return 0;
    }
    dfs2(1,0);
    if (!flag) {
        puts("No");
        return 0;
    }
    L[1]+=((L[1]&1)^v[1]);
    a[1]=L[1];
    dfs3(1,0);
    puts("Yes");
    for (int i=1;i<=n;i++) printf("%d\n", a[i]);
    return 0;
}

