int n, e, ter[N], nxt[N], lnk[N], v[N] ;
struct poi {
	int st, l, r ;
} f[N] ;

void add(int x, int y) {
	ter[++ e] = y, nxt[e] = lnk[x], lnk[x] = e ;
}

bool dfs(int p, int las) {
	f[p].st = 3 ;
	f[p].l = - inf, f[p].r = inf ;
	for (int i = lnk[p]; i; i = nxt[i]) if (ter[i] != las) {
		int u = ter[i] ;
		if (!dfs(u, p)) return false ;
		if (!(f[u].st & 2)) f[p].st &= 2 ;
		if (!(f[u].st & 1)) f[p].st &= 1 ;
		f[p].l = max(f[p].l, f[u].l - 1) ;
		f[p].r = min(f[p].r, f[u].r + 1) ;
	}
	if (!f[p].st || f[p].l > f[p].r) return false ;
	if (f[p].l == f[p].r) {
		if ((f[p].l & 1) && !(f[p].st & 1)) return false ;
		if (!(f[p].l & 1) && !(f[p].st & 2)) return false ;
	}
	if (v[p] != - 1) {
		if (v[p] < f[p].l || v[p] > f[p].r) return false ;
		if (v[p] & 1) f[p].st &= 1 ; else f[p].st &= 2 ;
		if (!f[p].st) return false ;
		f[p].l = f[p].r = v[p] ;
	}
	return true ;
}

void solve(int p, int las) {
	for (int i = lnk[p]; i; i = nxt[i]) if (ter[i] != las) {
		int u = ter[i] ;
		if (v[u] == - 1) {
			v[u] = v[p] - 1 ;
			if (v[u] < f[u].l || v[u] > f[u].r) v[u] = v[p] + 1 ;
		}
		solve(ter[i], p) ;
	}
}

