template <class T>
bool chmax(T &a, const T &b) {
    return (a < b) ? (a = b, 1) : 0;
}
template <class T>
bool chmin(T &a, const T &b) {
    return (b < a) ? (a = b, 1) : 0;
}

int main() {
    cin.tie(nullptr);
    ios::sync_with_stdio(false);
    int n;
    cin >> n;
    vector<vector<int>> edges(n);
    for (int i = 0; i < n - 1; ++i) {
        int u, v;
        cin >> u >> v;
        u--, v--;
        edges[u].emplace_back(v);
        edges[v].emplace_back(u);
    }
    int k;
    cin >> k;
    vector<lint> p(n, -inf);
    for (int i = 0; i < k; ++i) {
        int v, w;
        cin >> v >> w;
        v--;
        p[v] = w;
    }
    vector<lint> mini(n, -inf);
    vector<lint> maxi(n, inf);
    function<void(int, int)> dfsup = [&](int c, int pa) {
        if (p[c] != -inf) {
            maxi[c] = mini[c] = p[c];
        }
        for (auto &v : edges[c]) {
            if (v == pa)
                continue;
            dfsup(v, c);
            if (mini[v] != -inf)
                chmax(mini[c], mini[v] - 1);
            if (maxi[v] != inf)
                chmin(maxi[c], maxi[v] + 1);
            if (mini[v] == mini[c] || maxi[v] == mini[c]) {
                cout << "No"
                     << "\n";
                exit(0);
            }
        }
        if (p[c] != -inf) {
            if (mini[c] > p[c] || maxi[c] < p[c]) {
                cout << "No "
                     << "\n";
                exit(0);
            }
        }
    };
    dfsup(0, -1);
    function<void(int, int)> dfsdn = [&](int c, int pa) {
        if (p[c] != -inf) {
            if (mini[c] > p[c] || maxi[c] < p[c]) {
                cout << "No "
                     << "\n";
                exit(0);
            }
        }
        for (auto &v : edges[c]) {
            if (v == pa)
                continue;
            if (mini[c] != -inf)
                chmax(mini[v], mini[c] - 1);
            if (maxi[c] != inf)
                chmin(maxi[v], maxi[c] + 1);
            dfsdn(v, c);
        }
    };
    dfsdn(0, -1);
    for (int i = 0; i < n; ++i) {
        if (maxi[i] >= mini[i]) {
            p[i] = mini[i];
        } else {
            cout << "No"
                 << "\n";
            return 0;
        }
    }
    function<void(int, int)> dfs = [&](int c, int p) {
        for (auto &v : edges[c]) {
            if (v == p)
                continue;
            if (maxi[v] == maxi[c] || mini[v] == mini[c]) {
                cout << "No"
                     << "\n";
                exit(0);
            }
            dfs(v, c);
        }
    };
    dfs(0, -1);

    cout << "Yes"
         << "\n";
    for (int i = 0; i < n; ++i) {
        cout << p[i] << "\n";
    }
    return 0;
}

