const int maxn=1e5+5;

int n,k,tot,rt;
bool fake,bo[maxn];
int now[maxn],pre[maxn*2],son[maxn*2];
int l[maxn],r[maxn],odd[maxn],ans[maxn];

int read() {
    int x=0,f=1;char ch=getchar();
    for(;ch<'0'||ch>'9';ch=getchar())if(ch=='-')f=-1;
    for(;ch>='0'&&ch<='9';ch=getchar())x=x*10+ch-'0';
    return x*f;
}

void add(int a,int b) {
    pre[++tot]=now[a];
    now[a]=tot,son[tot]=b;
}

void dfs(int fa,int u,int now_odd) {
    if(fake)return;
    if(bo[u]&&odd[u]!=now_odd) {fake=1;return;}
    if(!bo[u]) {odd[u]=now_odd,l[u]=l[fa]-1,r[u]=r[fa]+1;}
    for(int p=now[u],v=son[p];p;p=pre[p],v=son[p])
        if(v!=fa) {
            dfs(u,v,now_odd^1);
            l[u]=max(l[u],l[v]-1);
            r[u]=min(r[u],r[v]+1);
        }
    if(r[u]<l[u])fake=1;
}

void check(int fa,int u,int x) {
    ans[u]=x;
    for(int p=now[u],v=son[p];p;p=pre[p],v=son[p])
        if(v!=fa) {
            if(x-1>=l[v]&&x-1<=r[v])check(u,v,x-1);
            else check(u,v,x+1);
        }
}

int main() {
    n=read();
    for(int i=1;i<n;i++) {
        int x=read(),y=read();
        add(x,y),add(y,x);
    }
    k=read();
    for(int i=1;i<=k;i++) {
        int x=read(),v=read();
        if(i==1)rt=x;bo[x]=1;
        l[x]=r[x]=v,odd[x]=v&1;
    }
    dfs(0,rt,odd[rt]);
    if(!fake) {
        puts("Yes");check(0,rt,l[rt]);
        for(int i=1;i<=n;i++)
            printf("%d\n",ans[i]);
    }
    else puts("No");
    return 0;
}

