int H;
int c[100005],C[100005],L[100005],R[100005],g[100005],M[100005],V[100005];
vector<int> r[100005],X[100005];

void f(int x, int h)
{
    int i;
    H=max(H,h);
    c[x]++;
    X[h].pb(x);
    for(i=0;i<r[x].size();i++){
        if(c[r[x][i]])continue;
        g[r[x][i]]=x;
        f(r[x][i],h+1);
    }
}

void G(int x)
{
    int i;
    L[x]=-1e9,R[x]=1e9;
    if(C[x]){
        L[x]=R[x]=C[x]-1;
        return;
    }
    for(i=0;i<r[x].size();i++){
        if(r[x][i]==g[x])continue;
        L[x]=max(L[x],L[r[x][i]]-1);
        R[x]=min(R[x],R[r[x][i]]+1);
        if(M[x]==0)M[x]=M[r[x][i]];
        else if(M[r[x][i]]&&M[x]!=M[r[x][i]]){
            printf("No\n");
            exit(0);
        }
    }
    M[x]=3-M[x];
    if(L[x]>R[x]){
        printf("No\n");
        exit(0);
    }
}

void h(int x)
{
    int i,nx;
    for(i=0;i<r[x].size();i++){
        nx=r[x][i];
        if(nx==g[x])continue;
        if(L[nx]<=V[x]-1&&V[x]-1<=R[r[x][i]])V[nx]=V[x]-1;
        if(L[nx]<=V[x]+1&&V[x]+1<=R[r[x][i]])V[nx]=V[x]+1;
        h(nx);
    }
}

int main()
{
    int n,k,s,e,i,x,v;
    scanf("%d", &n);
    for(i=1;i<n;i++){
        scanf("%d %d", &s, &e);
        r[s].pb(e);
        r[e].pb(s);
    }
    scanf("%d", &k);
    for(i=1;i<=k;i++){
        scanf("%d %d", &x, &v);
        C[x]=v+1;
    }
    f(1,1);
    while(H){
        for(i=0;i<X[H].size();i++)G(X[H][i]);
        H--;
    }
    V[1]=L[1];
    h(1);
    printf("Yes\n");
    for(i=1;i<=n;i++){
        printf("%d\n", V[i]);
    }
    return 0;
}

