using pii = std::pair<int, int>;

struct Node {
	int min{-10000000}, max{10000000};
	std::list<int> edges;
	bool visited{};
};
std::vector<Node> tree;

pii construct(int, int, int, int);

int main()
{
	int n;
	scanf("%d", &n);
	tree.resize(n);
	for (int i = 0; i < n - 1; i++)
	{
		int a, b;
		scanf("%d%d", &a, &b);
		a--; b--;
		tree[a].edges.push_back(b);
		tree[b].edges.push_back(a);
	}
	int k, start_v, start_p;
	scanf("%d", &k);
	for (int i = 0; i < k; i++)
	{
		int v, p;
		scanf("%d%d", &v, &p);
		v--;
		tree[v].min = tree[v].max = p;
		if (!i)
		{
			start_v = v;
			start_p = p % 2;
		}
	}
	pii result{construct(start_v, start_p, tree[start_v].min, tree[start_v].max)};
	if (result.first == -1)
		printf("No\n");
	else
	{
		printf("Yes\n");
		for (auto& e: tree) e.visited = false;
		construct(start_v, start_p, tree[start_v].min, tree[start_v].max);
		for (auto& node: tree)
			printf("%d\n", node.min);
	}

	return 0;
}

pii construct(int v, int p, int min, int max)
{
	Node& node{tree[v]};
	if (node.visited) return pii(node.max + 1, node.min - 1);
	node.visited = true;
	if (node.min > -10000000 && node.min % 2 != p) return pii(-1, -1);
	if (node.max < min || node.min > max) return pii(-1, -1);
	node.max = std::min(max, node.max);
	node.min = std::max(min, node.min);
	for (auto &e: node.edges)
	{
		pii tmp{construct(e, 1 - p, node.min - 1, node.max + 1)};
		if (tmp.first == -1) return std::move(tmp);
		node.max = std::min(node.max, tmp.first);
		node.min = std::max(node.min, tmp.second);
		if (node.max < node.min)
			return pii(-1, -1);
	}
	return pii(node.max + 1, node.min - 1);
}

