const double PI=acos(-1);
const double EPS=1e-8;
const int inf=1e8;
class DIJ{
	public:
	struct edge{
		int to,cost;
	};
	vector<vector<edge> >G;
	vp in;
	int n;
	vi d;//distance
	DIJ(int size){
		n=size;
		G=vector<vector<edge> >(n);
	}
	void add_edge(int a,int b,int c){
		edge e={b,c},ee={a,c};
		G[a].pb(e);
		G[b].pb(ee);
	}
	void dij(){
		d=vi(n,inf);
		priority_queue<pii>q;
		rep(i,in.size()){
			int a=in[i].first,b=in[i].second;
			q.push(pii(-b,a-1));
			d[a-1]=b;
		}
		while(!q.empty()){
			pii p=q.top();
			q.pop();
			int pos=p.second,cost=-p.first;
			if(cost>d[pos])continue;
			rep(i,G[pos].size()){
				edge e=G[pos][i];
				int to=e.to;
				int nowcost=cost+e.cost;
				if(nowcost<d[to]){
					d[to]=nowcost;
					q.push(pii(-d[to],to));
				}
			}
		}
	}
	void solve(){
		rep(i,n-1){
			int a,b;
			cin>>a>>b;
			a--;b--;
			add_edge(a,b,1);
			add_edge(b,a,1);
