		dij();
		bool h=true;
		rep(i,n)rep(j,G[i].size()){
			int to=G[i][j].to;
			if(abs(d[i]-d[to])!=G[i][j].cost)h=false;
		}
		rep(i,m)if(in[i].second!=d[in[i].first-1])h=false;
		if(h){
			cout<<"Yes"<<endl;
			rep(i,n)cout<<d[i]<<endl;
		}else cout<<"No"<<endl;
	}
};
