			else
			{
				if(abs(l[to])%2==abs(l[v])%2)
				{
					ans=false;
					return;
				}
				l[v]=max(l[v],l[to]-1);
				r[v]=min(r[v],r[to]+1);
			}
		}
	}
	if(l[v]>r[v])
		ans=false;
}
