    for (int i=1;i<=k;i++)
    {
        int ver,p;
        scanf("%d%d",&ver,&p);
        v[ver] = p;
    }
}
inline void dfs1(int x,int fa)
{
    sum[x] = v[x] > -1 , mark[x] = true;
    for (int i=Head[x];i;i=e[i].next)
    {
        int y = e[i].ver;
        if ( y == fa ) continue;
        dfs1( y , x );
        sum[x] += sum[y];
    }
    if ( !sum[x] ) mark[x] = false;
    //printf("mark[%d] = %d\n",x,mark[x]);
}
inline void dfs2(int x,int fa,int p)
{
    if ( v[x] > -1 ) p = v[x];
    for (int i=Head[x];i;i=e[i].next)
    {
        int y = e[i].ver;
        if ( y == fa || !mark[y] ) continue;
        up[y] = p , dfs2( y , x , p );
    }
    //printf("up[%d] = %d\n",x,up[x]);
}
inline void dfs3(int x,int fa)
{
    for (int i=Head[x];i;i=e[i].next)
    {
        int y = e[i].ver;
        if ( y == fa || !mark[y] ) continue;
        dfs3( y , x );
        if ( v[x] > -1 ) continue;
        if ( up[y] > v[y] ) v[x] = v[y] + 1;
        else v[x] = v[y] - 1;
    }
    //printf("v[%d] = %d\n",x,v[x]);
}
inline void dfs4(int x,int fa)
{
    for (int i=Head[x];i;i=e[i].next)
    {
        int y = e[i].ver;
        if ( y == fa ) continue;
        if ( v[y] == -1 ) v[y] = v[x] + 1;
        dfs4( y , x );
    }
}
inline bool check(void)
{
    for (int i=1;i<=n;i++)
        for (int j=Head[i];j;j=e[j].next)
            if ( abs( v[e[j].ver] - v[i] ) != 1 )
                return false;
    return true;
}
int main(void)
{
    memset( v , 0xff , sizeof v );
    input();
    int root = 0;
    for (int i=1;i<=n;i++)
        if ( v[i] ) root = i;
    //printf("root = %d\n",root);
    if ( root == 0 ) v[root=1] = 1;
    dfs1( root , 0 );
    dfs2( root , 0 , v[root] );
    dfs3( root , 0 );
    dfs4( root , 0 );
    if ( check() )
    {
        puts("Yes");
        for (int i=1;i<=n;i++)
            printf("%d\n",v[i]);
    }
    else puts("No");
    return 0;
}

#include <bits/stdc++.h>

using namespace std;

const int INF = 0x0fffffff;

int N;
int K;

typedef pair<int, int> ii;

vector< vector<int> > M;
vector<bool> V; // visited

vector<ii> R; // range

const ii inf = make_pair(-INF, INF);
const ii fail = make_pair(INF, -INF);

ii dfs(int i) {
    if (V[i]) {
        return inf;
    }

    V[i] = true;

    for (size_t j = 0; j < M[i].size(); ++j) {
        int ni = M[i][j]; // next i

        ii rv = dfs(ni);

        if (rv == make_pair(-INF-1, INF+1)) {
            rv = inf;
        }

        if (rv == fail) {
            return fail;
        } else if (R[i] == inf){
            R[i] = rv;
        } else if (rv == inf) {
            continue;
        } else if (R[i].first % 2 != R[i].second % 2) {
            return fail;
        } else if (R[i].second < rv.first) {
            return fail;
        } else if (rv.second < R[i].first) {
            return fail;
        } else {
            R[i].second = min(R[i].second, rv.second);
            R[i].first  = max(R[i].first, rv.first);
        }
    }

    if (R[i].second < R[i].first) {
        return fail;
    }

    return make_pair(R[i].first-1, R[i].second+1);
}

void dfs2(int i) {
    if (V[i]) {
        return;
    } 

    V[i] = true;

    R[i] = make_pair(R[i].first, R[i].first);

    for (size_t j = 0; j < M[i].size(); ++j) {
        int ni = M[i][j]; // next i

        if (V[ni]) {
            continue;
        }

        R[ni] = make_pair(max(R[ni].first, R[i].first-1), min(R[ni].second, R[i].second+1));

        dfs2(ni);
    }
}

int main(int argc, char* argv[]) {
    // for cin
    ios::sync_with_stdio(false);
