        q1.pop();

        for (const int& w : G[v]) {
            if (w == par) continue;

            up[w] = v;
            depth[w] = depth[v] + 1;

            if (p[w] != MOD) {
                pq.push({depth[w], w});

                if (ma[v] % 2 == p[w] % 2) boo();
                if (ma[v] + 1 < p[w]) boo();
                if (mi[v] - 1 > p[w]) boo();
                ma[w] = mi[w] = p[w];
            } else {
