#include<bits/stdc++.h>
using namespace std;
const int maxn = 1e6 + 7, W = 2e5;
int n, m, L[maxn], R[maxn], o = -1, ans[maxn];

int fir[maxn], nxt[2 * maxn], to[2 * maxn], e = 0;
void add(int x, int y) {
	to[++e] = y; nxt[e] = fir[x]; fir[x] = e;
	to[++e] = x; nxt[e] = fir[y]; fir[y] = e;
}

int d[maxn];
void s(int pos, int f) {
	d[pos] = d[f] ^ 1;
	int y, z;
	for (y = fir[pos]; y; y = nxt[y]) {
		if((z = to[y]) == f) continue;
		s(z, pos);
	}
}

bool dfs(int pos, int f) {
	int y, z; 
	for (y = fir[pos]; y; y = nxt[y]) {
		if((z = to[y]) == f) continue;
		if(!dfs(z, pos)) return 0;
		L[pos] = max(L[pos], L[z] - 1);
		R[pos] = min(R[pos], R[z] + 1);
	}
	if((d[pos] ^ (L[pos] & 1)) != o) ++L[pos];
	if((d[pos] ^ (R[pos] & 1)) != o) --R[pos];
	if(L[pos] > R[pos]) return 0;
	return 1;
}

void cal(int pos, int f) {
	if(L[pos] > R[pos]) assert(0);
	if(pos > 1 && ans[f] + 1 <= R[pos]) ans[pos] = ans[f] + 1;
	else if(pos > 1 && ans[f] - 1 >= L[pos]) ans[pos] = ans[f] - 1;
	else if(pos == 1) ans[pos] = L[pos];
	else assert(0);
	int y, z;
	for(y = fir[pos]; y; y = nxt[y]) {
		if((z = to[y]) == f) continue;
		cal(z, pos);
	}
}

bool check() {
	int x, y;
	for (int i = 1; i <= m; ++i) {
		scanf("%d%d", &x, &y);
		if(L[x] == R[x]) {
			if(L[x] != y) return 0;
			continue;
		}
		L[x] = R[x] = y;
		if(o == -1) {
			o = (d[x] ^ (y & 1));
		}
		else {
			if(o != (d[x] ^ (y & 1))) return 0;
		}
	}
	if(!dfs(1, 0)) return 0;
	cal(1, 0);
	printf("Yes\n");
	for (int i = 1; i <= n; ++i) printf("%d\n", ans[i]);
	return 1;
}

int main() {
	scanf("%d", &n);
	int x, y;
	for (int i = 1; i < n; ++i) {
		scanf("%d%d", &x, &y);
		add(x, y);
	}
	for (int i = 1; i <= n; ++i) L[i] = -W, R[i] = W;
	s(1, 0);
	scanf("%d", &m);
	if(!check()) printf("No\n");
	return 0;
}

