void solveL() {
	priority_queue <pii> q;
	for (int i = 1; i <= K; i++) q.push(mp(P[i], V[i]));
	while (!q.empty()) {
		pii o = q.top(); q.pop();
		if (L[o.sec] != o.fir) continue;
		for (auto v : E[o.sec]) {
			if (L[v] < o.fir - 1) {
				L[v] = o.fir - 1;
				q.push(mp(L[v], v));
			}
		}
	}
}

void solveR() {
	priority_queue <pii, vector <pii>, greater<pii> > q;
	for (int i = 1; i <= K; i++) q.push(mp(P[i], V[i]));
	while (!q.empty()) {
		pii o = q.top(); q.pop();
		if (R[o.sec] != o.fir) continue;
		for (auto v : E[o.sec]) {
			if (R[v] > o.fir + 1) {
				R[v] = o.fir + 1;
				q.push(mp(R[v], v));
			}
		}
	}
}

