    Point e=que.front();que.pop();
    sort.push_back(e.now);
    if((num[e.now]!=-1)&&(num[e.now]%2==e.odd)){
      std::cout<<"No";
      return 0;
    }

    for(ll i:graph[e.now]){
      if(i!=e.from){
        que.push(Point{e.now,i,(e.odd+1)%2});
      }
    }
  }

  std::vector<P> len(n,{-MOD,MOD});

  std::vector<bool> used(n,false);

  for(ll i=n-1;i>=0;i--){
    ll now=sort[i];
    used[now]=true;
    if((len[now].first>len[now].second)||((num[now]!=-1)&&((len[now].first>num[now])||(num[now]>len[now].second)))){
