    for(ll next:graph[now]){
      if(!used[next]){
        len[next]={std::max(len[next].first,len[now].first-1),std::min(len[next].second,len[now].second+1)};
      }
    }
  }

  que.push({-1,root,num[root]-1});

  while(que.size()){
    Point e=que.front();que.pop();
    if(e.odd+1<=len[e.now].second)num[e.now]=e.odd+1;
    else num[e.now]=e.odd-1;

    for(ll i:graph[e.now]){
      if(i!=e.from){
        que.push({e.now,i,num[e.now]});
      }
    }
  }

