int N,K;

vector<int> g[100010];
bool used[100010];
pair<int,int> col[100010];
int fix[100010];

int ival=1e7;
pair<int,int> INF=make_pair(-1e7,1e7);
pair<int,int> IMP=make_pair(1e9,1e9);

pair<int,int> dfs(int now){
    used[now]=true;
    int l=-ival,r=ival;
    if(fix[now]!=-1){
        l=fix[now];
        r=fix[now];
    }
    bool leaf=true;
    for(int i=0;i<g[now].size();i++){
        int next=g[now][i];
        if(used[next]) continue;

        leaf=false;
        pair<int,int> tp=dfs(next);
        if(tp==IMP) return IMP;
        else if(tp==INF) continue;

        if(r==ival){
            l=tp.first-1;
            r=tp.second+1;
        }else{
            if(r%2!=(tp.second+1)%2) return IMP;
            l=max(l,tp.first-1);
            r=min(r,tp.second+1);
        }

        if(r<l) return IMP;
    }

    if(leaf&&fix[now]==-1) return col[now]=INF;
    return col[now]=make_pair(l,r);
}

void rec(int now,int pval){
    used[now]=true;
    if(fix[now]==-1){
        if(col[now].first<=pval-1) fix[now]=pval-1;
        else fix[now]=pval+1;
    }
    for(int i=0;i<g[now].size();i++){
        int next=g[now][i];
        if(used[next]) continue;
        rec(next,fix[now]);
    }
    return;
}

