  cin>>K;
  for(int i=0;i<K;i++){
      int v,p;
      cin>>v>>p;
      v--;
      fix[v]=p;
      col[v]=make_pair(p,p);
  }

  pair<int,int> f=dfs(0);
  if(f==IMP){
      cout<<"No"<<endl;
      return 0;
  }

  if(K<N){
      int start=0;
      for(int i=0;i<N;i++){
          if(fix[i]==-1&&col[i]!=INF) start=i;
          used[i]=false;
      }
      fix[start]=col[start].first;
      rec(start,fix[start]);
  }

  cout<<"Yes"<<endl;
  for(int i=0;i<N;i++) cout<<fix[i]<<endl;

  return 0;
}

