			l=max(l,ls[c]-1);
			h=min(h,hs[c]+1);
			e|=es[c]*2+es[c]/2;
		}
	}
	if(e==1){
		if(l%2==0){
			l++;
		}
		if(h%2==0){
			h--;
		}
	}
	else if(e==2){
		if(l%2){
			l++;
		}
		if(h%2){
			h--;
		}
	}
	if(h<l||e==3){
