        node[v] = p;
    }
    parent[v] = 0;
    bool result = cansolve(v), ans = definenode(v);
    if(result && ans){
        cout << "Yes" << endl;
        for(int i = 1; i <= n; i++){
            cout << node[i] << endl;
        }
    } else {
        cout << "No" << endl;
    }
    return 0;
}

