int c[N], cnt[N];
int dfs(int x, int p = 0) {
	int leaf = 0;
	if (has[x]) leaf = c[x] % 2 ? 1 : 2;
	cnt[x] = has[x];
	for (int u : G[x]) if (u != p) {
		int o = dfs(u, x);
		cnt[x] += cnt[u];
		if (o == 0) continue;
		if (o != -1) o = 3 - o;
		if (!leaf) leaf = o; else {
			if (leaf != o) leaf = -1;
		}
	}
	return leaf;
}
int par[N], l[N], r[N];
pair<int, int> dfs2(int x, int p = 0) {
	int &l = ::l[x] = -1e9, &r = ::r[x] = 1e9;
	par[x] = p;
	for (int u : G[x]) if (u != p) {
		auto seg = dfs2(u, x);
		seg.first --;
		seg.second ++;
		l = max(seg.first, l);
		r = min(seg.second, r);
	}
	if (has[x]) l = r = c[x];
	//printf("%d : %d %d\n", x, l, r);
	c[x] = l;
	return {l, r};
}
void dfs3(int x, int p = 0) {
	if (p == 0) {
		c[x] = l[x];
	}
	else {
		int cho1 = c[p] + 1;
		int cho2 = c[p] - 1;
		if (cho1 >= l[x] && cho1 <= r[x]) {
			c[x] = cho1;
		}
		else if (cho2 >= l[x] && cho2 <= r[x]) {
			c[x] = cho2;
		}
	}
	for (int u : G[x]) if (u != p) {
		dfs3(u, x);
	}
}
