		else if(lb[u]<= ans[p]+1 && ans[p]+1<= rb[u]) ans[u] = ans[p]+1;
		else assert(false);
	}
	for(int v : adj[u])
	{
		if(v == p) continue;
		recon(v, u);
	}
}

