    if(a[y].FT == -INF)return 1;
    auto u = MP(a[y].FT-1,a[y].SD+1);
    //cout<<x<<" "<<y<<" "<<a[x].FT<<" "<<a[x].SD<<" "<<u.FT<<" "<<u.SD<<endl;
    if(a[x].FT == -INF)a[x] = u;
    else if((a[x].FT+u.FT)%2)return 0;
    else if(a[x].FT>u.SD||u.FT>a[x].SD)return 0;
    else
    {
        a[x].FT = max(a[x].FT,u.FT);
        a[x].SD = min(a[x].SD,u.SD);
    }
    return 1;
}
int dfs(int u,int fa)
{
    int f = 1;
    for(auto v:e[u])
    {
        if(v == fa)continue;
        f&=dfs(v,u);
        f&=merge(u,v);
    }
    return f;
}
void dfs1(int u,int fa,int val)
{
    ans[u] = val;
    for(auto v:e[u])
    {
        if(v == fa)continue;
        int x;
        if((val+1)>=a[v].FT&&(val+1)<=a[v].SD&&(val+1+a[v].FT)%2 == 0)x = val+1;
        else if((val-1)>=a[v].FT&&(val-1)<=a[v].SD&&(val-1+a[v].FT)%2 == 0)x = val-1;
        else x = val-1;
        dfs1(v,u,x);
    }
}
