typedef pair<int,int> P;
vector<int> G[N];
int Dep[N],Tree[N],root,par[30][N];
set<int> S;
int n;

void dfs(int pos,int pre,int dep){
  par[0][pos]=pre;
  Dep[pos]=dep;
  for(int i=0;i<G[pos].size();i++)
    if(G[pos][i]!=pre)dfs(G[pos][i],pos,dep+1);
}

void init(){
  dfs(root,-1,0);
  for(int k=0;k+1<30;k++){
    for(int v=0;v<n;v++){
      if(par[k][v]<0) par[k+1][v]=-1;
      else par[k+1][v]=par[k][par[k][v]];
    }
  }
}

int lca(int u,int v){
  if(Dep[u]>Dep[v])swap(u,v);
  for(int k=0;k<30;k++){
    if(((Dep[v]-Dep[u])>>k)&1)v=par[k][v];
  }
  if(u==v)return u;

  for(int k=30-1;k>=0;k--){
    if(par[k][u]!=par[k][v]){
      u=par[k][u];
      v=par[k][v];
    }
  }
  return par[0][u];
}

bool check(int pos,int a){
  if(S.count(pos)&&Tree[pos]!=a)return 0;
  if(S.count(pos)){
    S.erase(S.find(pos));
    return 1;
  }

  set<int>::iterator it=S.begin();
  for(;it!=S.end();it++){
    int res=lca(pos,*it);
    int dis=Dep[pos]+Dep[*it]-2*Dep[res];
    int b=Tree[*it];
    if(dis%2==1&&a%2==b%2)return 0;
    if(dis%2==0&&a%2!=b%2)return 0;
    if(dis<abs(a-b))return 0;
    set<int>:: iterator tmp=it;
    tmp--;
    if(res==*it)S.erase(it),it=tmp;
  }
  return 1;
}

int flg=1;
void mk_tree(int pos,int pre){
  if(flg==0)return;
  int a=Tree[pos];
  for(int i=0;i<G[pos].size();i++){
    int npos=G[pos][i];
    if(npos==pre)continue;
    if(check(npos,a+1))Tree[npos]=a+1,mk_tree(npos,pos);
    else if(check(npos,a-1))Tree[npos]=a-1,mk_tree(npos,pos);
    else flg=0;
  }
}

int main(){
  cin>>n;
  for(int i=0;i<n-1;i++){
    int a,b;
    cin>>a>>b;
    G[a-1].push_back(b-1);
    G[b-1].push_back(a-1);
  }

  int K;
  cin>>K;
  for(int i=0;i<K;i++){
    int a,b;
    cin>>a>>b;
    Tree[a-1]=b;
    S.insert(a-1);
  }
  root=*S.begin();
  init();
  mk_tree(root,root);

  if(!flg)cout<<"No"<<endl;
  else {
    cout <<"Yes"<<endl;
    for(int i=0;i<n;i++) cout << Tree[i]<<endl;
  }

  return 0;
}

