pii merge(pii p1, pii p2){
	if(p1.se%2!=p2.se%2) return {inf,inf};

	if(p1.fi > p2.fi) swap(p1,p2);
	if(p1.se >= p2.fi) return {max(p1.fi,p2.fi), min(p1.se,p2.se)};
	else return {inf,inf};
}

void bfs(const vector<int> &vi){
