	for(auto v:vi){
		q.push(v);
		range[v] = {num[v],num[v]};
		chk[v] = true;
	}
	while(!q.empty()){
		auto u = q.front();
		q.pop();

		for(auto v:g[u]){
			if(!chk[v]){
				chk[v] = true;
				range[v] = {range[u].fi - 1, range[u].se + 1};
				q.push(v);
			}else{
				pii res = merge({range[u].fi-1,range[u].se+1}, range[v]);
				if(res==make_pair(inf,inf)) cout << "No", exit(0);
				else range[v] = res;
			}
		}
	}
