			ans[v] = ans[u]+1;
		}
		else
		{
			int val = ans[u];
			if(ans[u]<mini[v])
			{
				val++;
			}
			else if(ans[u]>maxi[v])
			{
				val--;
			}
			else
			{
				int l = abs(mini[v]-ans[u]);
				int r = abs(maxi[v]-ans[u]);
				if(l>r) val--;
				else if(l<r) val++;
				else
				{
					l = abs(minn[v]-ans[u]);
					r = abs(maxx[v]-ans[u]);
					if(l>r) val--;
					else val++;
				}
			}
			//cerr<<v+1<<' '<<val<<'\n';
			if(ans[v]<INF&&val!=ans[v])
			{
				return false;
			}
			ans[v]=val;
		}
		if(!dfs(v, u)) return false;
	}
	return true;
}

