#include <bits/stdc++.h>
#define RI register int
#define Cannot puts("No"), exit(0);
typedef long long LL;

#define FILEIO(name) freopen(name".in", "r", stdin), freopen(name".out", "w", stdout);

using namespace std;

char buf[1000000], *p1 = buf, *p2 = buf;
inline char gc() {
  if (p1 == p2) p2 = (p1 = buf) + fread(buf, 1, 1000000, stdin);
  return p1 == p2 ? EOF : *(p1++);
}
template <class T> inline void read(T &n) {
  n = 0; RI ch = gc(), f;
  while ((ch < '0' || ch > '9') && ch != '-') ch = gc();
  f = (ch == '-' ? ch = gc(), -1 : 1);
  while (ch >= '0' && ch <= '9') n = n * 10 + (ch ^ 48), ch = gc();
  n *= f;
}

int const MAXN = 1e5 + 5;
struct Edges { int to, next; } e[MAXN * 2];
int head[MAXN], tot;
int l[MAXN], r[MAXN], a[MAXN], vis[MAXN];

inline void addedge(int from, int to) {
  e[++tot] = (Edges){to, head[from]};
  head[from] = tot;
  e[++tot] = (Edges){from, head[to]};
  head[to] = tot;
}

void Put(int now, int fa, int num) {
  vis[now] = 1;
  ++l[now], --r[now];
  if (((l[now] & 1) ^ (num & 1)) && (l[now] < -9e5)) Cannot;
  if (r[now] == num - 1) a[now] = r[now];
  else a[now] = num + 1;
  for (RI i = head[now]; i; i = e[i].next)
    if (e[i].to != fa && !vis[e[i].to])
      Put(e[i].to, now, a[now]);
}

void Dfs(int now, int fa) {
  if (vis[now]) l[now] = r[now] = a[now];
  else l[now] = -1e6, r[now] = 1e6;
  for (RI i = head[now]; i; i = e[i].next)
    if (e[i].to != fa) {
      Dfs(e[i].to, now);
      l[now] = max(l[now], l[e[i].to]);
      r[now] = min(r[now], r[e[i].to]);
    }
  if (l[now] > r[now]) Cannot;
  if (vis[now]) {
    if (l[now] > a[now] || r[now] < a[now]) Cannot;
    if ((a[now] & 1) ^ (l[now] & 1)) Cannot;
    l[now] = r[now] = a[now];
    for (RI i = head[now]; i; i = e[i].next)
      if (e[i].to != fa && !vis[e[i].to])
        Put(e[i].to, now, a[now]);
  }
  --l[now], ++r[now];
}

int main() {

#ifdef LOCAL
  FILEIO("a");
#endif

  int n; read(n);
  for (RI i = 1, x, y; i < n; ++i)
    read(x), read(y), addedge(x, y);
  int k; read(k);
  int rt;
  for (RI i = 1, x; i <= k; ++i) {
    read(x), read(a[x]), vis[x] = 1;
    if (i == 1) rt = x;
  }
  Dfs(rt, 0);
  puts("Yes");
  for (RI i = 1; i <= n; ++i)
    printf("%d\n", a[i]);

  return 0;
}

