struct Node {
	int low, high;
	std::vector<int> next;
	Node() : low(1), high(0) {}
};

signed main() {
	INIT;
	VAR(int, n);
	std::vector<Node> node(n);
	std::vector<int> a(n - 1), b(n - 1);
	REP(i, n - 1) {
		std::cin >> a[i] >> b[i];
		--a[i]; --b[i];
		node[a[i]].next.emplace_back(b[i]);
		node[b[i]].next.emplace_back(a[i]);
	}
	VAR(int, k);
	std::vector<int> v(k), p(k);
	REP(i, k) {
		std::cin >> v[i] >> p[i];
		--v[i];
		node[v[i]].low = p[i];
		node[v[i]].high = p[i];
	}

	REP(i, k) {
		std::vector<bool> visited(n, false);
		std::queue<int> queue;
		visited[v[i]] = true;
		queue.push(v[i]);
		while (!queue.empty()) {
			int now_i = queue.front(); queue.pop();
			Node& now = node[now_i];
			int low = now.low - 1, high = now.high + 1;
			for (auto check_i : now.next) {
				Node& check = node[check_i];
				if (!visited[check_i]) {
					visited[check_i] = true;
					if (check.low > check.high) {
						check.low = low;
						check.high = high;
						queue.push(check_i);
						continue;
					}
					if (low % 2 != check.low % 2) {
						OUT("No")BR;
						return 0;
					}
					if (low <= check.low && high >= check.high) continue;
					CHMAX(check.low, low);
					CHMIN(check.high, high);
					if (check.low > check.high) {
						assert(false);
						OUT("No")BR;
						return 0;
					}
					queue.push(check_i);
				}
			}
		}
	}
	OUT("Yes")BR;
	REP(i, n) {
		OUT(node[i].low)/*SP OUT(node[i].high)*/BR;
	}

	return 0;
}

