Info info[100000];
vector<int> G[100000];
int P[100000];
bool dfs(int v, int par) {
	int l = -1 << 30;
	int r = 1 << 30;
	int p = -1;
	for (int to : G[v]) {
		if (to == par) continue;
		if (!dfs(to, v)) return false;
		if (info[to].second != -1) {
			if (p == -1) {
				p = info[to].second ^ 1;
			}
			else if (p == info[to].second) {
				return false;
			}
			l = max(l, info[to].first.first - 1);
			r = min(r, info[to].first.second + 1);
		}
	}
	if (p == -1) {
		if (P[v] == -1) {
			info[v] = Info(Range(-1 << 30, 1 << 30), -1);
		}
		else {
			info[v] = Info(Range(P[v], P[v]), P[v] % 2);
		}
	}
	else {
		if (l > r || (l == r) && (abs(l) % 2 != p)) return false;
		if (P[v] == -1) {
			info[v] = Info(Range(l, r), p);
		}
		else if (l <= P[v] && P[v] <= r && P[v] % 2 == p) {
			info[v] = Info(Range(P[v], P[v]), P[v] % 2);
		}
		else {
			return false;
		}
	}
	return true;
}
void make(int v, int par) {
	if (par != -1) {
		if (info[v].second == -1) {
			P[v] = P[par] - 1;
		}
		else {
			int l = info[v].first.first, r = info[v].first.second, p = info[v].second;
			if (l <= (P[par] - 1) && (P[par] - 1) <= r && (P[par] - 1) % 2 == p) {
				P[v] = P[par] - 1;
			}
			else {
				P[v] = P[par] + 1;
			}
		}
	}
	for (int to : G[v]) {
		if (to == par) continue;
		make(to, v);
	}
}
