		--a;--b;
		e[a].push_back(b);
		e[b].push_back(a);
	}
	for(int i=0;i<n;++i){
		st[i] = -N;
		cnt[i] = N * 10;
	}
	scanf("%d",&k);
	for(int i=0;i<k;++i){
		int vi, pi;
		scanf("%d%d",&vi,&pi);
		--vi;
		st[vi] = pi;
		cnt[vi] = 1;
		//assert(pi <= 1e5);
	}
