void bad(){
	printf("No\n");
	exit(0);
}

void check(int u){
	if(cnt[u] == 0){
		bad();
	}
}

void merge(int u, int to){
	if(st[u] == -N){
		st[u] = st[to] - 1;
		cnt[u] = cnt[to] + 1;
		return;
	}
	int le = (st[to] - 1);
	if(le % 2 != st[u] % 2){
		cnt[u] = 0;
		return;
	}
	int ri = (cnt[to]) * 2 + le;
	le = max(le, st[u]);
	ri = min(ri, st[u] + (cnt[u] - 1) * 2);
	if(le > ri){
		cnt[u] = 0;
		return;
	}
	st[u] = le;
	cnt[u] = (ri - le) / 2 + 1;
}

void dfs(int u, int p){
	for(int i=0;i<e[u].size();++i){
		int to = e[u][i];
		if(to == p){
			continue;
		}
		dfs(to, u);
		merge(u, to);
		check(u);
	}
}

void dfs1(int u, int p, int curV){
	ans[u] = curV;
	for(int i=0;i<e[u].size();++i){
		int to = e[u][i];
		if(to == p){
			continue;
		}
		if(st[to] <= curV - 1 && st[to] + (cnt[to] - 1) * 2 >= curV -1){
			dfs1(to, u, curV-1);
		}else{
			dfs1(to, u, curV+1);
		}
	}
}

void solve(){
	dfs(0, 0);
	dfs1(0, 0, st[0]);
	printf("Yes\n");
	for(int i=0;i<n;++i){
		printf("%d\n",ans[i]);
	}
}

