void getinterval(int a,int f)
{
	for(int i = 0; i < G[a].size(); i++)
		if(G[a][i] != f)
		{
			getinterval(G[a][i], a);

			if(sub[G[a][i]])
			{
				int l = L[G[a][i]] - 1;
				int r = R[G[a][i]] + 1;				

				if(sub[a])
				{
					if(r < L[a] || l > R[a] || ((l & 1) ^ (L[a] & 1))) ans = false;

					L[a] = std::max(L[a], l);
					R[a] = std::min(R[a], r);
				}
				else
				{
					L[a] = l;
					R[a] = r;
					sub[a] = true;
				}
			}
		}

	if(vp[a] == true)
	{
		if(sub[a] && (P[a] < L[a] || P[a] > R[a] || ((P[a] & 1) ^ (L[a] & 1)))) ans = false;

		L[a] = R[a] = P[a];
		sub[a] = true;
	}
}
void getvalue(int a,int f)
{
	if(a == 1)
	{
		P[a] = L[a];
	}
	else
	{
		if(P[f] - 1 >= L[a])
		{
			P[a] = P[f] - 1;
		}
		else
		{
			P[a] = P[f] + 1;
		}
	}

	for(int i = 0; i < G[a].size(); i++)
		if(G[a][i] != f)
		{
			getvalue(G[a][i], a);
		}
}
