vector<int> adj[N];
pair<int, int> range[N];

int v[N];
bool valid = true;

bool combine(const pair<int, int>& a, pair<int, int>& b) {
	if ((a.first & 1) != (b.first & 1)) return false;
	if (a.second < 1 || b.second < 1) return false;
	if (a.first + 2 * (a.second - 1) < b.first) return false;
	if (b.first + 2 * (b.second - 1) < a.first) return false;

	int lo = max(a.first, b.first);
	int hi = min(a.first + 2 * (a.second - 1), b.first + 2 * (b.second - 1));
	b = make_pair(lo, 1 + (hi - lo) / 2);
	return true;
}

pair<int, int> dfs(int u, pair<int, int> r, int prev = -1) {
	if (v[u] != -1) {
		if (!combine(make_pair(v[u], 1), r)) {
			valid = false;
			return make_pair(1, 0);
		}
	}

	for (int v : adj[u]) {
		if (v == prev) continue;
		if (!combine(dfs(v, make_pair(r.first - 1, r.second + 1), u), r)) {
			valid = false;
			return make_pair(1, 0);
		}
	}

	range[u] = r;

	// printf("range de %d, (%d, %d)\n", 1 + u, r.first, r.second);

	return make_pair(r.first - 1, r.second+ 1);
}

void solve(int u, int prev = -1) {
	// printf("to no %d\n", 1 + u);
	if (v[u] == -1) {
		auto f = [&](int x) -> bool {
			auto r = range[u];
			if ((x & 1) != (r.first & 1)) {
				return false;
			}
			return x >= r.first && x < r.first + 2 * r.second;
		};

		// printf("range (%d, %d), possiveis {%d, %d}\n", range[u].first, range[u].second, v[prev] - 1, v[prev] + 1);

		if (f(v[prev] - 1)) v[u] = v[prev] - 1;
		if (f(v[prev] + 1)) v[u] = v[prev] + 1;

		assert(v[u]);
	}

	for (int v : adj[u]) {
		if (v == prev) continue;
		solve(v, u);
	}
}

int main() {
	memset(v, -1, sizeof v);

	int n;
	scanf("%d", &n);

	for (int i = 1; i < n; i++) {
		int u, v;
		scanf("%d %d", &u, &v);
		u--, v--;
		adj[u].emplace_back(v);
		adj[v].emplace_back(u);
	}

	int k;
	scanf("%d", &k);

	int root;
	for (int i = 0; i < k; i++) {
		int u, x;
		scanf("%d %d", &u, &x);
		v[u - 1] = x;
		root = u - 1;
	}

	dfs(root, make_pair(v[root], 1));

	if (!valid) {
		puts("No");
		return 0;
	}

	// printf("root: %d\n", root);

	puts("Yes");
	solve(root);

	for (int i = 0; i < n; i++) {
		printf("%d\n", v[i]);
	}

	return 0;
}

