using Range = pair<int, int>;

int n;
vector<vector<int>> tree;
vector<Range> ranges;
vector<int> ps;

const int inf = 1 << 28;

pair<bool, Range> merge(Range a, Range b) {
    if (a > b) {
        swap(a, b);
    }

    if (a.first == -inf) {
        return {true, b};
    }

    if (b.first == -inf) {
        return {true, a};
    }

    if (a.second < b.first) {
        return {false, {}};
    }

    if ((a.first ^ b.first) & 1) {
        return {false, {}};
    }

    Range r(max(a.first, b.first), min(a.second, b.second));

    return {true, r};
}

Range dfs(int node, int par) {
    Range r = ranges[node];

    for (int to : tree[node]) {
        if (to == par) {
            continue;
        }

        auto rc = dfs(to, node);

        if (rc.first != -inf) {
            rc.first--;
        }

        if (rc.second != inf) {
            rc.second++;
        }

        auto merged = merge(r, rc);

        if (!merged.first) {
            out("No");
            exit(0);
        }

        r = merged.second;
    }
    return ranges[node] = r;
}

void setValue(int node, int par, int p) {
    if (ps[node] == -1) {
        if (par == -1) {
            ps[node] = ranges[node].first;
        } else {
            if (ranges[node].first <= p + 1 && p + 1 <= ranges[node].second) {
                ps[node] = p + 1;
            } else {
                ps[node] = p - 1;
            }
        }
    }

    for (int to : tree[node]) {
        if (to == par) {
            continue;
        }

        setValue(to, node, ps[node]);
    }
}

int main() {
    in(n);

    tree.assign(n, {});
    ps.assign(n, -1);
    ranges.assign(n, {-inf, inf});

    for (int i : rep(0, n - 1)) {
        int a, b;
        in(a, b);

        a--;
        b--;

        tree[a].push_back(b);
        tree[b].push_back(a);
    }

    int k;
    in(k);

    for (int i : rep(0, k)) {
        int v, p;
        in(v, p);

        v--;

        ps[v] = p;
        ranges[v].first = ranges[v].second = p;
    }

    auto r = dfs(0, -1);

    setValue(0, -1, -1);

    out("Yes");

    for (int i : rep(0, n)) {
        out(ps[i]);
    }
}

