inline int gi() {
    int x=0,o=1;
    char ch=getchar();
    while(ch!='-'&&(ch<'0'||ch>'9')) ch=getchar();
    if(ch=='-') o=-1,ch=getchar();
    while(ch>='0'&&ch<='9') x=x*10+ch-'0',ch=getchar();
    return x*o;
}
inline void dfs(int x,int fa) {
    if(w[x]) L[x]=R[x]=a[x];
    else L[x]=-1e6,R[x]=1e6;
    for(int i=head[x];i;i=nxt[i]) {
	int y=to[i];
	if(y!=fa) {
	    dfs(y,x);
	    if(R[y]<5e5&&R[x]<5e5&&(R[y]+1<L[x]||R[x]<L[y]-1))
		puts("No"),exit(0);
	    L[x]=max(L[x],L[y]-1),R[x]=min(R[x],R[y]+1);
	}
    }
}
inline void solve(int x,int fa) {
    for(int i=head[x];i;i=nxt[i]) {
	int y=to[i];
	if(y!=fa) {
	    if(a[x]-1>=L[y]&&a[x]-1<=R[y]) a[y]=a[x]-1;
	    else if(a[x]+1>=L[y]&&a[x]+1<=R[y]) a[y]=a[x]+1;
	    else puts("NO"),exit(0);
	    solve(y,x);
	}
    }
}
