struct Edge {
	int v;
	Edge *nxt;
} pool[Maxn*2], *tree[Maxn], *tail = pool;
inline void addedge(const int &u, const int &v) {
	tail->v = v;
	tail->nxt = tree[u], tree[u] = tail++;
}

int n, k, a[Maxn];
bool visited[Maxn];
priority_queue<pair<int, int>> heap;

void solve() {
	for (int u; !heap.empty(); ) {
		u = heap.top().second, heap.pop();
		for (Edge *p = tree[u]; p; p = p->nxt) {
			if (!visited[p->v]) {
				a[p->v] = a[u]-1;
				visited[p->v] = true;
				heap.push({a[p->v], p->v});
			} else {
				if (abs(a[p->v]-a[u]) > 1) {
					puts("No");
