ll rec(int x,int frm, int deep) {

	vis[x] = true;
	int nd = deep + 1;
	int nf = frm;
	if (re[x] != -1) {
		if (frm + deep < x || frm - deep > x) {
			return -1;
		}
		if ((abs(re[x] - re[frm]) % 2) ^ (deep % 2))
			return -1;
		nd = 1;
		nf = x;
	}
	vector<int> pv;
	for (auto v : es[x])
	{
		if (vis[v]) continue;
		auto p = rec(v, nf, nd);
		if (p == -1) return -1;
		pv.push_back(v);
	}

	// この時点で取れる範囲のデフォルト
	int big = re[nf] + (nd - 1);
	int mii = re[nf] - (nd - 1);
	for (auto v : pv)
	{
		int t = min(big, range[v].second + 1);
		int u = max(mii, range[v].first - 1);
		if (t < u) { 
			return -1; 
		}
		big = t;
		mii = u;
	}
	if (re[x] == -1) {
		range[x].first = mii;
		range[x].second = big;

	}
	else {
		range[x].first = re[x];
		range[x].second = re[x];
	}
	return 0;
}
