		else if (fv - 1 == re[x]) nf = fv - 1;
	}
	else
	{

		if (fv + 1 <= range[x].second) {
			re[x] = fv + 1;

		}
		else if(fv - 1 >= range[x].first){
			re[x] = fv - 1;
		}
		nf = re[x];
	}

	for (auto v : es[x]) {
		if (vis[v]) continue;
		rec(v, nf);
	}
}
