    seg() {
        l = r = BAD;
    }
};

vector <seg> dp(N);

void solve(int v) {
    vector <seg> t;
    for (int to : g[v]) {
        if (to != par[v]) {
            solve(to);
            if (have[to] && dp[to].l != BAD) {
                t.push_back(dp[to]);
            }
        }
    }
    if (col[v] != BAD) {
        dp[v].l = col[v];
        dp[v].r = col[v];
        return;
    }  
    if (t.empty()) {

    } else {
        int x = t[0].l % 2;
        bool bad = false;
        for (auto to : t) {
            if (to.l % 2 != x) {
                bad = true;
            }  
        }
        if (bad) {

        } else {
            int mn = 1e9, mx = -1e9;
            for (auto to : t) {
                mn = min(mn, to.r);
                mx = max(mx, to.l);
            }
            if (mx >= mn) {
                mn--;
                mx++;
                dp[v].l = mn;
                dp[v].r = mx;
            }
        }
    }
}

void flex(int v) {
    if (col[v] == BAD && have[v]) {
        int c = col[par[v]];
        if (c % 2 == dp[v].l) {
            cout << "No\n";
            exit(0);
        }
        if (c + 1 > dp[v].r || c + 1 < dp[v].l) {
            if (c - 1 > dp[v].r || c - 1 < dp[v].l) {
                cout << "No\n";
                exit(0);
            }
            col[v] = c - 1;
        } else {
            col[v] = c + 1;
        }
    }
    for (auto to : g[v]) {
        if (to != par[v]) {
            flex(to);
        }
    }
}

