int fallen = 0, L[MAXN], R[MAXN], ans[MAXN], K, n;
vector<int> adj[MAXN];

void dfs(int u, int p = -1) {
	for (int i=0; i<sz(adj[u]); i++) {
		int v = adj[u][i];
		if (v == p) continue;
		dfs(v, u);
		if (fallen) return;

		if (L[v] == -oo && R[v] == oo) continue;
		int lo = L[v] - 1;
		int hi = R[v] + 1;
//		cout << u << " " << v << " " << lo << " " << hi << endl;

		if (L[u] == -oo && R[u] == oo) {
			L[u] = lo; R[u] = hi;
		}
		else {
			if (((L[u] - lo) % 2 != (R[u] - hi) % 2)) {
//				cout << u << " " << v << " " << lo << " " << hi << endl;
				fallen = 1;
				return;
			}

			L[u] = max(L[u], lo);
			R[u] = min(R[u], hi);

			if (R[u] < L[u]) {
				fallen = 1;
				return;
			}
		}
	}
}

void findTree(int u, int p = -1) {
	if (!~p) {
		ans[u] = L[u];
	}
	else {
		int nxt = ans[p] + 1;
		if (L[u] <= nxt && nxt <= R[u]) {
			ans[u] = nxt;
		}
		else {
			ans[u] = ans[p] - 1;
		}
	}

	for (int i=0; i<sz(adj[u]); i++) {
		int v = adj[u][i];
		if (v == p) continue;
		findTree(v, u);
	}
}

