pair<int,int> inter(pair<int,int> x,pair<int,int> y){
	if (x.first==-1e9 || y.first==-1e9) return mp(-1e9,-1e9);
	if (x.first>y.first) swap(x,y);
	if (x.second<y.first) return mp(-1e9,-1e9);
	return mp(y.first,min(x.second,y.second)); 
}
