	while (!que.empty()) {
		ll v = que.front(); que.pop();
		for (ll i = 0; i < e[v].size(); i++) {
			ll nv = e[v][i];
			if (S[nv] <= 0)continue;
			S[nv]--;
			Max[nv] = min(Max[nv], Max[v] + 1);
			Min[nv] = max(Min[nv], Min[v] - 1);
			if (S[nv] == 1) {
				que.push(nv);

			}
		}
	}

	vi ans(n);
	queue<int> Q;
	Q.push(ex);
	vi yatta(n, 0); yatta[ex] = 1;
