					Min[nv] = max(Min[nv], ans[i] - 1);
					Q.push(nv);
				}
			}
			yatta[i] = 1;
		}
	}

	cout << "Yes" << endl;
	for (ll i = 0; i < n; i++) {
		cout << ans[i] << endl;
	}
	return 0;
}

