#include <bits/stdc++.h>
using namespace std;
void err () {
  cout << "No\n";
  exit(0);
}
void dfs (int cur, int par, const vector<vector<int>>& g, vector<int>& val, vector<int>& done, vector<pair<int, int>>& range, vector<int>& parity) {
  if (done[cur] && val[cur] % 2 != parity[cur]) err();
  for (int child : g[cur]) if (child != par) {
    parity[child] ^= parity[cur];
    dfs (child, cur, g, val, done, range, parity);
  }
}
void dfs2 (int cur, int par, const vector<vector<int>>& g, vector<int>& val, vector<int>& done, vector<pair<int, int>>& range, vector<int>& parity) {
  pair<int, int> get = make_pair(-1e9, 1e9);
  for (int child : g[cur]) if (child != par) {
    get.first = max(get.first, range[child].first - 1);
    get.second = min(get.second, range[child].second + 1);
  }
  if (!done[cur] || (get.first <= range[cur].first && get.second >= range[cur].second)) {
    range[cur].first = max(get.first, range[cur].first);
    range[cur].second = min(get.second, range[cur].second);
    for (int child : g[cur]) if (child != par) {
      dfs2 (child, cur, g, val, done, range, parity);
    }
  } else {
    err();
  }
}
void dfs3 (int cur, int par, pair<int, int> candi, const vector<vector<int>>& g, vector<int>& val, vector<int>& done, vector<pair<int, int>>& range, vector<int>& parity) {
  if (done[cur]) {
    candi.first = val[cur] - 1;
    candi.second = val[cur] + 1;
  } else {
    int c = (candi.first % 2 == parity[cur] ? candi.first : candi.second);
    if (range[cur].first <= c && c <= range[cur].second) {
      done[cur] = true;
      val[cur] = c;
      range[cur] = make_pair(c, c);
    } else {
      err();
    }
  }
  candi = make_pair(val[cur] - 1, val[cur] + 1);
  for (int child : g[cur]) if (child != par) {
    dfs3 (child, cur, candi, g, val, done, range, parity);
  }
}
signed main() { 
  ios::sync_with_stdio(false); cin.tie(0);
  int n;
  cin >> n;
  vector<vector<int>> g(n);
  for (int i = 1; i < n; i++) {
    int a, b;
    cin >> a >> b;
    a--;
    b--;
    g[a].push_back(b);
    g[b].push_back(a);
  }
  int k;
  cin >> k;
  vector<int> val(n);
  vector<int> done(n);
  vector<pair<int, int>> range(n, make_pair(-1e9, 1e9));
  int root;
  for (int i = 0; i < k; i++) {
    int v, p;
    cin >> v >> p;
    v--;
    val[v] = p;
    done[v] = true;
    range[v] = make_pair(p, p);
    root = v;
  }
  vector<int> parity(n, val[root] % 2);
  dfs (root, -1, g, val, done, range, parity);
  dfs2 (root, -1, g, val, done, range, parity);
  dfs3 (root, -1, range[root], g, val, done, range, parity);
  cout << "Yes\n";
  for (int i = 0; i < n; i++) {
    cout << val[i] << '\n';
  }
  return 0;
}

