inline int read()
{
	char c;
	int res,flag=0;
	while((c=getchar())>'9'||c<'0') if(c=='-')flag=1;
	res=c-'0';
	while((c=getchar())>='0'&&c<='9') res=(res<<3)+(res<<1)+c-'0';
	return flag?-res:res;
}
const int N=210000;
int point[N],lock[N];
int fir[N],go[N],nex[N],val[N][2];
inline void rotate(int u,int f,int V)
{
	int e,v;
	bool pf2=1,pz2=1;
	for(e=fir[u];v=go[e],e;e=nex[e])
	if(v!=f)
	{
		if(lock[v])
		if(val[v][0]!=V-2&&val[v][1]!=V-2&&val[v][0]!=V&&val[v][1]!=V) pf2=0;
		if(lock[v])
		if(val[v][0]!=V+2&&val[v][1]!=V+2&&val[v][0]!=V&&val[v][1]!=V) pz2=0;
	}
	if(pf2)
	{
		if(val[u][0]) 
		val[u][1]=V-1,lock[u]=2;
		else
		val[u][0]=V-1,lock[u]=1;
	} 
	if(pz2)
	{
		if(val[u][0])
		val[u][1]=v+1,lock[u]=2;
	}
}
inline void dfs(int u,int f)
{
	if(go[fir[u]]==f&&!nex[fir[u]])
	return;
	int e,v;
	for(e=fir[u];v=go[e],e;e=nex[e])
	if(v!=f)
	dfs(v,u);
	for(e=fir[u];v=go[e],e;e=nex[e])
	if(v!=f)
	{
		if(lock[v])
		{
			if(lock[v]==2)
			{
				rotate(u,f,val[v][0]);
				rotate(u,f,val[v][1]);
			}
			else
				rotate(u,f,val[v][0]);
			if(!lock[u])
			{
				printf("No");
				exit(0);
			}
		}
	}
}
int ans[N];
inline void get_ans(int u,int f)
{
	if(u!=f)
	{
		if(abs(val[u][0]-ans[f])!=1) ans[u]=val[u][1];
		else ans[u]=val[u][0];
		if(!lock[u]) ans[u]=ans[f]-1;
	}
	int e,v;
	for(e=fir[u];v=go[e],e;e=nex[e])
	if(v!=f)
		get_ans(v,u);
}
int tot;
inline void add(int x,int y)
{
	nex[++tot]=fir[x];fir[x]=tot;go[tot]=y;
	nex[++tot]=fir[y];fir[y]=tot;go[tot]=x;
}
