void Calculate_Depth(vector<vector<int>>&edge, vector<int>&depth, int stnode) {
	depth[stnode] = 0;
	queue<int>Q;
	Q.push(stnode);
	while (!Q.empty()) {
		int cn = Q.front();
		Q.pop();
		for (auto i : edge[cn]) {
			if (depth[i] > depth[cn] + 1) {
				depth[i] = depth[cn] + 1;
				Q.push(i);
			}
		}
	}
	return;
}

void TopDown(vector<int>&depth, vector<int>&l, vector<int>&r, vector<vector<int>>&edge, int node) {
	for (auto i : edge[node]) {
		if (depth[i] > depth[node]) {
			if (l[i] == l[node])l[i]++;
			l[i] = max(l[i], l[node] - 1);
			if (r[i] == r[node])r[i]--;
			r[i] = min(r[i], r[node] + 1);
			TopDown(depth, l, r, edge, i);
		}
	}
	return;
}

void BottomUp(vector<int>&depth, vector<int>&l, vector<int>&r, vector<vector<int>>&edge, int node) {
	for (auto i : edge[node]) {
		if (depth[i] > depth[node]) {
			BottomUp(depth, l, r, edge, i);
			if (l[node] == l[i])l[node]++;
			l[node] = max(l[node], l[i] - 1);
			if (r[node] == r[i])r[node]--;
			r[node] = min(r[node], r[i] + 1);
		}
	}
	return;
}

