const int INFTY = 1e8;

void solve() {
  int n; cin >> n;
  Graph<int> tree(n);
  rep1(i,n) {
    int a, b; cin >> a >> b; --a, --b;
    tree[a].emplace_back(b);
    tree[b].emplace_back(a);
  }
  int k; cin >> k;
  vi MAX(n, INFTY), MIN(n, -INFTY);
  rep(i,k) {
    int v, p; cin >> v >> p; --v;
    MAX[v] = MIN[v] = p;
  }

  function<bool(int, int)> dfs = [&](int v, int p) {
    for (int &nv : tree[v]) {
      if (nv != p) {
        if (!dfs(nv, v)) return false;
        if (MAX[v] != INFTY && MAX[nv] != INFTY && (MAX[v] & 1) == (MAX[nv] & 1)) return false;
        chmin(MAX[v], MAX[nv] + 1);
        chmax(MIN[v], MIN[nv] - 1);
        if (MAX[v] < MIN[v]) return false;
      }
    }
    return true;
  };

  if (!CoutYN(dfs(0, -1))) return;

  vi ans(n);
  ans[0] = MAX[0];

  function<void(int, int)> confirm = [&](int v, int p) {
    for (int &nv : tree[v]) {
      if (nv != p) {
        ans[nv] = min(ans[v] + 1, MAX[nv]);
        confirm(nv, v);
      }
    }
  };

  confirm(0, -1);
  interval[0] = "\n";
  cout << ans << endl;
}


/* -------- <programs end> -------- */


signed main() {
  cin.tie(nullptr);
  ios::sync_with_stdio(false);
  cout << fixed << setprecision(10);
  solve();
  return 0;
}

