bool both_even(int a, int b) {
    return (a%2==0)&&(b%2==0);
}

pair<int, int> dfs(int u, int p) {
    for(auto v:adj[u]) if( v != p ) {
        pair<int, int> tmp = dfs(v, u);
        if( tmp == all ) continue;
        if( val[u] == all ) {
            val[u].F = tmp.F-1;
            val[u].S = tmp.S+1;
            continue;
        }
        if( val[u].F-tmp.S>1 || tmp.F-val[u].S>1 || both_even(tmp.F, val[u].F) ) {
            puts("No");
            exit(0);
        } else {
            val[u].F = max(val[u].F, tmp.F-1);
            val[u].S = min(val[u].S, tmp.S+1);
        }
    }
    return val[u];
}
void dfs2(int u, int p, int vl) {
    ans[u] = vl;
    for(auto v:adj[u]) if( v != p ) {
        if( vl+1 <= val[v].S && vl+1 >= val[v].F )
            dfs2(v, u, vl+1);
        else {
            assert( vl-1 <= val[v].S && vl-1 >= val[v].F );
            dfs2(v, u, vl-1);
        }
    }
}
