bool dfs(ll u, ll l, ll r, ll &l2, ll &r2){
	if(ub[u]!=INF && (r+ub[u])%2==1) return false;
	chmax(lb[u], l);
	chmin(ub[u], r);
	used[u] = true;
	for(int w: e[u]){
		if(used[w]) continue;
		if(!dfs(w, l-1, r+1, lb[u], ub[u])) return false;
	}
	if(lb[u]>ub[u]) return false;
	chmax(l2, lb[u]-1);
	chmin(r2, ub[u]+1);
	return true;
}

