    G[a].push_back(b);
    G[b].push_back(a);
  }

  vector<int> V(N, -1);
  priority_queue<pii, vector<pii>, greater<pii>> P;

  int K;
  cin >> K;
  for (int i = 0; i < K; i++) {
    int a, v;
    scanf("%d%d", &a, &v);
    a--;
    P.push(mp(v, a));
  }

  while(!P.empty()) {
    pii p = P.top(); P.pop();
    V[p.second] = p.first;
    for(int i = 0; i < G[p.second].size(); i++) {
      if (V[G[p.second][i]] != -1 && abs(p.first - V[G[p.second][i]]) != 1) {
        printf("No\n");
        return 0;
      }
      if (V[G[p.second][i]] == -1) P.push(mp(p.first + 1, G[p.second][i]));
    }
  }

  printf("Yes\n");
  for (int i = 0; i < N; i++) {
    printf("%d", V[i]);
  }

  return 0;
}

