	for (unsigned i = 0; i < a[pos].size(); i++)
		if (a[pos][i] != fa) dfs(a[pos][i], pos);
}
void update(int x, int y) {
	l[x] = max(l[x], l[y] - 1);
	r[x] = min(r[x], r[y] + 1);
	if (l[x] > r[x]) halted = true;
}
void work(int pos, int fa) {
	for (unsigned i = 0; i < a[pos].size(); i++)
		if (a[pos][i] != fa) {
			work(a[pos][i], pos);
			update(pos, a[pos][i]);
		}
}
