template<class Lambda>
auto treeDP(ll n, const unordered_multimap<ll, ll>& graph, ll root, const Lambda& lambda) {
	VL out(n, 0);
	{
		queue<ll> q; q.emplace(root);
		while (!q.empty()) {
			auto from = q.front();
			q.pop();

			auto range = graph.equal_range(from);
			REPI2(itr, range.first, range.second) {
				auto to = itr->second;
				if (out[to] == 0) {
					q.emplace(to);
					++out[from];
				}
			}
		}
	}
	{
		queue<ll> q;
		REP(i, n)if (out[i] == 0) { q.emplace(i); }
		while (!q.empty()) {
			auto from = q.front();
			q.pop();

			auto range = graph.equal_range(from);
			REPI2(itr, range.first, range.second) {
				auto to = itr->second;
				--out[to];
				if (out[to] == 0) {
					q.emplace(to);
				}
				lambda(from, to);
			}
		}
	}
}
template<class Lambda>
auto graphBFS(ll n, const unordered_multimap<ll, ll>& graph, ll root, const Lambda& lambda) {
	V<bool> isUsed(n, false); isUsed[root] = true;
	queue<ll> q; q.emplace(root);
	while (!q.empty()) {
		auto from = q.front();
		q.pop();

		auto range = graph.equal_range(from);
		REPI2(itr, range.first, range.second) {
			auto to = itr->second;
			if (!isUsed[to]) {
				q.emplace(to);
				isUsed[to] = true;
				lambda(from, to);
			}
		}
	}
}

