	Point()
	{
		l=-10000000,r=10000000,sign=2;
	}
	Point(int _l,int _r,int _sign)
	{
		l=_l;
		r=_r;
		sign=_sign;
	}
	Point operator +(const Point &A) const
	{
		Point ret;
		ret.l=max(l,A.l);
		ret.r=min(r,A.r);
		if(sign==2||A.sign==3)
			ret.sign=A.sign;
		else if(A.sign==2||sign==3)
			ret.sign=sign;
		else if(sign==A.sign)
			ret.sign=sign;
		else
			ret.sign=3;
		if(ret.l>ret.r)
			ret.sign=3;
		if(ret.l==ret.r&&ret.sign<2&&ret.sign%2!=ret.l)
