        Q.push({{dis+2, next}, {f, s}});
        continue;
      }
      if(f <= P[next].first && P[next].second <= s) {
        continue;
      }

      if(P[next].first%2 != f%2) {
        flag = false;
        break;
      }
      if(P[next].second < f || s < P[next].first) {
        flag = false;
        break;
      }

      int ns, nf, nd;

      ns =  min(P[next].second, s);
      nf = max(P[next].first, f);

      nd = ns - nf;

      Q.push({{nd,next},{nf,ns}});
    }
  }



  if(flag == false) {
    cout<<"No"<<endl;
    // for(int i = 0; i < N; i++){
    //  cout<<P[i].first<<" <> "<<P[i].second<<endl;
    // }
    return 0;
  }



  while(Q.size()){
    pair<pair<int,int>,pair<int,int>> p = Q.top(); Q.pop();
    int f = p.second.first, s = p.second.second;
    int node = p.first.second, dis = p.first.first;

    if(P[node].first == INF) {
      P[node].first = f;
      P[node].second = s;
    } else {
      if(f%2 != P[node].first%2) {
        flag = false;
        break;
      }
      if(P[node].second < f || s < P[node].first) {
        flag = false;
        break;
      }
      if(f < P[node].first && P[node].second < s) {
        continue;
      }

      P[node].second = min(P[node].second, s);
      P[node].first = max(P[node].first, f);
    }

    dis = P[node].second - P[node].first;

    for(int next : tree[node]){

      if(P[next].first == INF) {
        Q.push({{dis+2, next}, {f-1, s+1}});
        continue;
      }
      if(f < P[next].first && P[next].second < s) {
        continue;
      }

      if(P[next].first%2 == f%2) {
        flag = false;
        break;
      }
      if(P[next].second < f || s < P[next].first) {
        flag = false;
        break;
      }

      int ns, nf, nd;

      ns =  min(P[next].second, s);
      nf = max(P[next].first, f);

      nd = ns - nf;

      Q.push({{nd,next},{nf,nf}});
    }
  }

  cout<<"Yes"<<endl;

  for(int i = 0; i < N; i++){
    cout<<P[i].first<<endl;
  }

  return 0;
