int lb[100010], ub[100010];

pair<int,int> get_range(int u, int p){
    int mi = -INF;
    int ma = INF;
    for(auto &e : g[u]){
        int v = e.dst;
        if(v == p) continue;
        int tmi, tma;
        tie(tmi, tma) = get_range(v, u);
        mi = max(mi, tmi);
        ma = min(ma, tma);
    }

    --mi;
    ++ma;

    pair<int,int> res;
    if(mi > ma){
        res = BAD;
    } else {
        if(num[u] != -1){
            if(mi <= num[u] && num[u] <= ma){
                res = make_pair(num[u], num[u]);
            } else {
                res = BAD;
            }
        } else {
            res = make_pair(mi, ma);
        }
    }

    tie(lb[u], ub[u]) = res;
    return res;
}

void paint(int u, int p, int pc){
    int c = lb[u] <= pc-1 && pc-1 <= ub[u] ? pc-1 : pc+1;
    num[u] = c;
    for(auto &e : g[u]){
        int v = e.dst;
        if(v == p) continue;
        paint(v, u, c);
    }
}

