using namespace std;
const int MAXN = 100005;
const int INF = 2000000000;
int numEdge, n, k;
int head[MAXN], id[MAXN];
int L[MAXN], R[MAXN];
struct Edge
{
    int v, next;
}edge[MAXN << 1];
void addEdge(int u, int v)
{
    edge[numEdge].v = v;
    edge[numEdge].next = head[u];
    head[u] = numEdge++;
}
void dfs(int u, int pre)
{
    for(int i = head[u]; i != -1; i = edge[i].next)
    {
        int v = edge[i].v;
        if(v == pre) continue;
        dfs(v, u);
        if(R[v] + 1 < L[u] || L[v] - 1 > R[u]) id[u] = 2;
        L[u] = max(L[u], L[v] - 1);
        R[u] = min(R[u], R[v] + 1);
        if(id[u] == -1) id[u] = id[v] ^ 1;
        else if(id[u] == id[v]) id[u] = 2;
    }
}
void dfs(int u, int pre, int nxtL, int nxtR)
{
    if(pre != -1)
    {
        if(nxtR < L[u] || nxtL > R[u]) id[u] = 2;
        L[u] = max(L[u], nxtL);
        R[u] = min(R[u], nxtR);
    }
    int max1 = nxtL, max2 = -INF;
    int min1 = nxtR, min2 =  INF;
    for(int i = head[u]; i != -1; i = edge[i].next)
    {
        int v = edge[i].v;
        if(v == pre) continue;
        if(L[v] - 1 >= max1) max2 = max1, max1 = L[v] - 1;
        else if(L[v] - 1 > max2) max2 = L[v] - 1;

        if(R[v] + 1 <= min1) min2 = min1, min1 = R[v] + 1;
        else if(R[v] + 1 < min2) min2 = R[v] + 1;
    }
    for(int i = head[u]; i != -1; i = edge[i].next)
    {
        int v = edge[i].v;
        if(v == pre) continue;
        int tmpL = max1 - 1, tmpR = min1 + 1;
        if(L[v] - 1 == tmpL + 1) tmpL = max2 - 1;
        if(R[v] + 1 == tmpR - 1) tmpR = min2 + 1;
        dfs(v, u, tmpL, tmpR);
    }
}
int main()
{
    scanf("%d", &n);
    numEdge = 0;
    memset(head, -1, sizeof(head));
    memset(id, -1, sizeof(id));
    for(int u, v, i = 1; i < n; i++)
    {
        scanf("%d%d", &u, &v);
        addEdge(u, v);
        addEdge(v, u);
    }
    for(int i = 1; i <= n; i++) L[i] = -INF, R[i] = INF;
    scanf("%d", &k);
    for(int v, p, i = 0; i < k; i++)
    {
        scanf("%d%d", &v, &p);
        id[v] = p & 1;
        L[v] = R[v] = p;
    }
    if(k == 0) k = 1 / INF - INF;
    dfs(1, -1);
    dfs(1, -1, -INF, INF);
    bool flag = true;
    for(int i = 1; i <= n; i++) if(id[i] == 2) flag = false;
    if(!flag) puts("No");
    else
    {
        puts("Yes");
        for(int i = 1; i <= n; i++) printf("%d\n", L[i]);
    }
    return 0;
}

