int main()
{
    int N; cin >> N;
    auto adjacency_list = vector<vector<int>>(N);
    for (auto i = 0; i < N-1; i++)
    {
        int a, b; cin >> a >> b;
        a--; b--;

        adjacency_list[a].push_back(b);
        adjacency_list[b].push_back(a);
    }

    struct State { int vertex, mark; };
    const auto compare = [](const State a, const State b) { return a.mark < b.mark; };
    auto queue = priority_queue<State, vector<State>, decltype(compare)>(compare);

    auto seen = vector<bool>(N);
    auto marks = vector<int>(N);
    int K; cin >> K;
    for (auto i = 0; i < K; i++)
    {
        int v, m; cin >> v >> m;
        v--;

        seen[v] = true;
        marks[v] = m;
        for (const auto w : adjacency_list[v])
            queue.push({w, m-1});
    }

    while (!queue.empty())
    {
        const auto s = queue.top(); queue.pop();
        if (!seen[s.vertex])
        {
            seen[s.vertex] = true;
            marks[s.vertex] = s.mark;
            for (const auto w : adjacency_list[s.vertex])
                queue.push({w, s.mark-1});
        }
    }

    auto ok = true;
    for (auto v = 0; v < N; v++)
        for (auto w : adjacency_list[v])
            ok &= abs(marks[v]-marks[w]) == 1;

    if (ok)
    {
        cout << "Yes" << "\n";
        for (const auto x : marks) cout << x << "\n";
    }
    else cout << "No" << "\n";
}

