int val[N];

void simpleDfs(int u, int fa) {
	val[u] = val[fa] + 1;
	for (int i = 0; i < edge[u].size(); ++i) {
		int v = edge[u][i];
		if (v != fa) {
			simpleDfs(v, u);
		}
	}
}

int up[N], down[N];
bool dfs(int u, int fa) {
	up[u] = INF; down[u] = -INF;
	for (int i = 0; i < edge[u].size(); ++i) {
		int v = edge[u][i];
		if (v != fa) {
			if (!dfs(v, u)) return false;
		}
//cout << u << ' ' << up[u] << ' ' << up[v] << ' ' << down[v] << endl;
		if ((up[u] < INF || down[u] > -INF) && (abs(up[v]) & 1) != ((abs(up[u]) & 1) ^ 1)) return false;
		up[u] = min(up[v] + 1, up[u]);
		down[u] = max(down[v] - 1, down[u]);
	}

//cout << u << ' ' << down[u] << ' ' << up[u] << endl;	
	if (down[u] > up[u]) return false;
	if (vis[u]) {
		if (down[u] > val[u] || up[u] < val[u]) return false;
		down[u] = up[u] = val[u];
	}
	return true;
}

void getAns(int u, int fa) {
	for (int i = 0; i < edge[u].size(); ++i) {
		int v = edge[u][i];
		if (v != fa) {
			if (val[u] + 1 <= up[u] && val[u] + 1 >= down[u]) val[v] = val[u] + 1;
			else val[v] = val[u] - 1;
			getAns(v, u);
		}
	}
}

