void link(int u, int v) { g[u].push_back(v); g[v].push_back(u); }

void dfs(int u, int p)
{
    for (auto v : g[u])
    {
        if (v == p) continue;
        father[v] = u;
        color[v] = 1 - color[u];
        dfs(v,u);
        lb[u] = max(lb[u],lb[v]-1);
        ub[u] = min(ub[u],ub[v]+1);
    }
}

void dfs2(int u, int p)
{
    for (auto v : g[u])
    {
        if (v == p) continue;
        lb[v] = max(lb[v], lb[u]-1);
        ub[v] = min(ub[v], ub[u]+1);
        dfs2(v,u);
    }
}

bool check()
{
    for (int i=0;i+1<even.size();i++)
    {
        if (color[even[i]] != color[even[i+1]]) return false;
    }
    for (int i=0;i+1<odd.size();i++)
    {
        if (color[odd[i]] != color[odd[i+1]]) return false;
    }
    if (even.empty() || odd.empty()) return true;
    return color[even[0]] != color[odd[0]];
}

