} e[maxn << 1];

int first[maxn];

inline void add_edge(int from, int to)
{
	static int cnt = 0;
	e[++cnt].nxt = first[from];
	first[from] = cnt;
	e[cnt].to = to;
	e[++cnt].nxt = first[to];
	first[to] = cnt;
	e[cnt].to = from;
}

int ll[maxn], rr[maxn];
int fa[maxn];

inline void dfs(int now)
{
//	cout << "now = " << now << ' ' << ll[now] << ' ' << rr[now] << endl;
	for(int i = first[now]; i; i = e[i].nxt)
	{
		int to = e[i].to;
		if(to != fa[now])
		{
			if(~jo[to] && (jo[to] ^ (!jo[now])))
			{
				puts("No");
				exit(0);
			}
			jo[to] = !jo[now];
			fa[to] = now;
			ll[to] = max(ll[now] - 1, ll[to]);
			rr[to] = min(rr[now] + 1, rr[to]);
			dfs(to);
		}
	}
}

int anss[maxn];

inline void dfs2(int now)
{
//	cout << "dfs2 " << now << ' ' << ll[now] << ' ' << rr[now] << endl;
	ll[now] = max(anss[fa[now]] - 1, ll[now]);
	if(jo[now] ^ (ll[now] & 1))
	{
		ll[now]++;
		if(ll[now] > rr[now])
		{
			puts("No");
			exit(0);
		}
	}
	rr[now] = min(anss[fa[now]] + 1, rr[now]);
	anss[now] = ll[now];
	for(int i = first[now]; i; i = e[i].nxt)
	{
		int to = e[i].to;
//		cout << "to = " << to << ' ' << fa[now] << endl;
		if(to != fa[now])
			dfs2(to);
	}
}

