	int rig;
	st(){
		lef = INT_MAX;
		rig = INT_MAX;
	}
	st(int lef_, int rig_){
		lef = lef_;
		rig = rig_;
	}
	st add(){
		st r;
		r.lef = lef;
		r.rig = rig;
		if (r.lef != INT_MAX){
			r.lef--;
			r.rig++;
		}
		return r;
	}
};

