bool used[MAX];
int c[MAX];

st merge(st a, st b){
	if (a.lef == INT_MAX){
		return b;
	}
	if (b.lef == INT_MAX){
		return a;
	}
	if (a.lef % 2 != b.lef % 2){
		return st(INT_MIN, INT_MIN);
	}
	if (a.lef > b.lef){
		swap(a, b);
	}
	if (a.lef <= b.lef&&b.rig <= a.rig){
		return a;
	}
	if (a.rig < b.lef){
		return st(INT_MIN, INT_MIN);
	}
	return st(b.lef, a.rig);
}
st tmp[MAX];

inline st dfs(int b,int pr=-1){
