vector<vector<ll>> edges;
vector<ll> value;
vector<pair<ll, ll>> conds;
bool flag;

pair<ll, ll> dfs(ll curr, ll min_value, ll max_value, ll pre) {
    if (value[curr] != -1) {
        if (min_value <= value[curr] && value[curr] <= max_value && value[curr] % 2 == min_value % 2) {
            //ok
            min_value = value[curr];
            max_value = value[curr];
        } else {
            //ng
            flag = false;
            return { -1, -1 };
        }
    }

    for (ll i = 0; i < edges[curr].size(); i++) {
        ll next = edges[curr][i];
        if (next == pre) {
            continue;
        }
        auto cond = dfs(next, min_value - 1, max_value + 1, curr);
        if (cond.second < min_value || max_value < cond.first) {
            flag = false;
            return { -1, -1 };
        }

        if (cond.first - 1 > min_value) {
            min_value = cond.first - 1;
            i = -1;
        }
        if (cond.second + 1 < max_value) {
            max_value = cond.second + 1;
            i = -1;
        }
    }
    return conds[curr] = { min_value, max_value };
}

