		else if (lb[u]<= ans[p]+1 && ans[p]+1<= rb[u]) ans[u] = ans[p]+1;
		// else printf("prblem at %d, [%d, %d] p = %d, ans[p] = %d\n", u, lb[u], rb[u], p, ans[p]);
	}
	for(int v : adj[u])
	{
		if(v == p) continue;
		recon(v, u);
	}
}

