    vector<vector<int>> chi(n);
    vector<int> siz(n, 0);
    function<void(int,int)> f = [&](int x, int y){
        par[x] = y;
        if(x)
            siz[x] = siz[y] + 1;
        for(auto& ed : edges[x]){
            if(par[ed] == -2)
                f(ed, x);
            if(par[ed] == x)
                chi[x].push_back(ed);
        }
    };
    f(0, -1);
    vector<i64> mi(n, -MOD);
    vector<i64> ma(n, MOD);
    int q, qq;
