    queue<int> que;
    for(int i = 0; i < n; ++i)
        if(!(out[i] = chi[i].size()))
            que.emplace(i);

    int fl = (siz[qq] ^ mi[qq]) & 1;
    for(int i = 0; i < n; ++i)
        siz[i] = (siz[i] ^ fl) & 1;

