        while(!que.empty()){
            int t = que.front();
            que.pop();
            if(par[t] != -1 && !(--out[par[t]]))
                que.emplace(par[t]);

            for(auto& c : chi[t]){
                mi[t] = max(mi[t], mi[c] - 1);
