   for(int i=0;i<N-1;i++){
      int a,b; cin>>a>>b;
      a--; b--;
      G[a].push_back(b);
      G[b].push_back(a);
   }
   vector<int> num(N,-1);
   int K; cin>>K;
   for(int i=0;i<K;i++){
      int v,p; cin>>v>>p;
      v--;
      num[v]=p;
   }

   vector<int> par(N,-1),last(N,-1);
   bool ok=true;
   function<void(int ,int ,int ,int)> dfs=[&](int v,int p,int lst,int d)
   {
      if(num[v]>=0 and lst!=-1){
         if(abs(num[lst]-num[v])>d or abs(num[lst]-num[v])%2!=d%2){
            ok=false;
         }
      }
      if(num[v]>=0){
         for(auto u:G[v]) if(u!=p){
            par[u]=v;
            last[u]=v;
            dfs(u,v,v,1);
         }
      }else{
         for(auto u:G[v]) if(u!=p){
            par[u]=v;
            last[u]=lst;
            dfs(u,v,lst,d+1);
         }
      }
   };
   int root=-1;
   for(int i=0;i<N;i++) if(num[i]>=0) root=i;
   dfs(root,-1,-1,0);
   if(!ok){
      cout<<"No"<<endl;
      return 0;
   }

