         if(curnum>num[last[v]]) curnum--;
         else if(curnum<num[last[v]]) curnum++;
         else curnum++;
         num[u]=curnum;
      }
   }

   function<void(int,int)> dfs2=[&](int v,int p)
   {
      if(num[v]<0) num[v]=num[p]+1;
      for(int u:G[v]) if(u!=p) dfs2(u,v);
   };

   dfs2(root,-1);
   cout<<"Yes"<<endl;
   for(int i=0;i<N;i++) cout<<i+1<<' '<<num[i]<<endl;
   return 0;
}

