vpint seg;
void DFS(int now){
	done[now]=1;
	if(!node[now].size())
		return;
	//可能な区間を求める
	int left=seg[now].first, right=seg[now].second;
	for(int next:node[now]){
		if(done[next])
			continue;
		DFS(next);
		left=max(left, seg[next].first-1);
		right=min(right, seg[next].second+1);
	}
	seg[now]=mp(left, right);
}
int con(int now, int prev){
	eone[now]=1;
	int left=seg[now].first, right=seg[now].second;
	bool isNG=0;
	if(right<left)
		isNG=1;
	else if(num[now]!=-1){
		if(left<=num[now] && num[now]<=right)
			isNG=0;
		else
			isNG=1;
	}
	else if(now==0)
		num[now]=left;
	else if(left<=prev+1 && prev+1<=right)
		num[now]=prev+1;
	else if(left<=prev-1 && prev-1<=right)
		num[now]=prev-1;
	else
		isNG=1;
	if(isNG)
		return 1;
	else{
		for(int next:node[now])
			if(!eone[next] && con(next, num[now]))
				return 1;
		return 0;
	}
}
