using namespace std;

int nNode;
int vs[100000+10];
int parity[100000+10];
int lbs[100000+10];
int ubs[100000+10];
vector<int> g[100000+10];

bool go(int si) {
  stack<pair<int,int> > q; 
  q.push(make_pair(si, -1));
  while(!q.empty()) { // 対象ノード。親ノード。
    pair<int,int> cur = q.top(); q.pop();
    int u = cur.first;
    int parent = cur.second;
    if(u < 0) { // 帰り。子たちの範囲とパリティが判明済み
      u = ~u;
      if(lbs[u] > ubs[u] || parity[u] == 0) { // 無理
        return false;
      }
      if(lbs[u] == ubs[u] && (parity[u] & (1 << (lbs[u] % 2))) == 0) {
        return false;
      }
      if(parent >= 0) {
        REP(i, 2) {
          if((parity[u] & (1 << i)) == 0) {
            parity[parent] &= ~(1 << !i);
          }
        }
        lbs[parent] = max(lbs[parent], lbs[u]-1);
        ubs[parent] = min(ubs[parent], ubs[u]+1);
      }
    } else { // 行き。
      q.push(make_pair(~u, parent));
      REP(i, g[u].size()) {
        int v = g[u][i];
        if(v != parent) {
          q.push(make_pair(v, u));
        }
      }
    }
  }
  return true;
}

void go2(int si) {
  queue<pair<int,int> > q; // 対象ノード。親ノード。
  q.push(make_pair(si, -1));
  while(!q.empty()) {
    pair<int,int> cur = q.front(); q.pop();
    int u = cur.first;
    int parent = cur.second;
    int value;
    if(parent < 0) {
      value = lbs[u];
      if((parity[u] & (1 << (value%2))) == 0) {
        ++value;
      }
    } else {
      value = lbs[parent]-1;
      if(value < lbs[u]) {
        value += 2;
      }
    }
    lbs[u] = ubs[u] = value;
    REP(i, g[u].size()) {
      int v = g[u][i];
      if(v != parent) {
        q.push(make_pair(v, u));
      }
    }
  }
}

int main(void) {
  scanf("%d", &nNode);
  REP(i, nNode-1) {
    int a, b;
    scanf("%d%d", &a, &b);
    --a;
    --b;
    g[a].push_back(b);
    g[b].push_back(a);
  }
  REP(i, nNode) {
    parity[i] = 3;
    lbs[i] = 0;
    ubs[i] = 1000000;
  }
  int nInit;
  scanf("%d", &nInit);
  REP(i, nInit) {
    int v, p;
    scanf("%d%d", &v, &p);
    --v;
    lbs[v] = ubs[v] = p;
    parity[v] = 1 << (p % 2);
  }

  bool ok = go(0);
  if(ok) {
    puts("Yes");
    go2(0);
    REP(i, nNode) {
      assert(lbs[i] == ubs[i]);
