	while (k--) {
		int tv, val;
		cin >> tv >> val;
		tv--;
		v[tv] = val;
	}
	dfs(0, -1);
	jfs(0, -1, dp[0].first);
	cout << "Yes\n";
	for (int i = 0; i < n; i++) {
		cout << ans[i] << '\n';
	}
}

