#include <bits/stdc++.h>
using namespace std;
using ll = long long;
template<class T> inline bool chmax(T& a, T b) {if(a<b) {a=b;return 1;} return 0;}
template<class T> inline bool chmin(T& a, T b) {if(a>b) {a=b;return 1;} return 0;}
const int INF = 1LL<<28;

bool updated = false;
vector<vector<int>> G;
vector<int> P, Pmin, Pmax, Podd;

bool dfs1(int v, int p, int mn, int mx, int odd) {
    int M = 1e6;
    if ( P[v] != INF ) {
        if ( mx < P[v] ) return false;
        if ( mn > P[v] ) return false;
        if ( Pmax[v] < P[v] ) return false;
        if ( Pmin[v] > P[v] ) return false;
        updated |= chmin(Pmax[v], P[v]);
        updated |= chmax(Pmin[v], P[v]);
        int vodd = P[v] % 2;
        if ( vodd < 0 ) vodd = 1;
        if ( vodd != odd ) return false;
        Podd[v] = vodd;
    } else {
        updated |= chmin(Pmax[v], mx);
        updated |= chmax(Pmin[v], mn);
        if ( Pmax[v] < Pmin[v] ) return false;
        if ( Podd[v] == -1 ) {
            Podd[v] = odd;
        } else if ( Podd[v] != odd ) {
            return false;
        }
    }
    for ( int u : G[v] ) {
        if ( u == p ) continue;
        if ( !dfs1(u, v, Pmin[v] - 1, Pmax[v] + 1, 1 - Podd[v]) ) return false;
        updated |= chmin(Pmax[v], Pmax[u] + 1);
        updated |= chmax(Pmin[v], Pmin[u] - 1);
    }
    if ( (Pmax[v] + M) % 2 != odd ) Pmax[v]--, updated = true;
    if ( (Pmin[v] + M) % 2 != odd ) Pmin[v]++, updated = true;
    if ( Pmax[v] < Pmin[v] ) return false;
    return true;
}

bool dfs2(int v, int p, int x) {
    if ( P[v] = INF ) {
        P[v] = x;
    }
    for ( int u : G[v] ) {
        if ( u == p ) continue;
        if ( Pmin[u] <= x + 1  && x + 1 <= Pmax[u] ) {
            if ( !dfs2(u, v, x + 1) ) return false;
        } else if ( Pmin[u] <= x - 1  && x - 1 <= Pmax[u] ) {
            if ( !dfs2(u, v, x - 1) ) return false;
        } else {
            return false;
        }
    }
    return true;
}

void solve() {
    ll N, K;
    cin >> N;
    G.resize(N);
    P.resize(N, INF), Pmin.resize(N, -INF), Pmax.resize(N, INF), Podd.resize(N, -1);
    ll a, b;
    for ( int i = 0; i < N - 1; i++ ) {
        cin >> a >> b;
        a--, b--;
        G[a].push_back(b);
        G[b].push_back(a);
    }
    cin >> K;
    int v, p, v0;
    for ( int i = 0; i < K; i++ ) {
        cin >> v >> p;
        v--;
        P[v] = p;
        if ( i == 0 ) v0 = v;
    }

    bool ok = true;
    while ( ok ) {
        updated = false;
        ok = dfs1(v0, -1, -INF, INF, P[v0] % 2);
        if ( !updated ) break;
    }
    if ( ok ) {
        ok = dfs2(v0, -1, P[v0]);
    }

    if ( ok ) {
        cout << "Yes\n";
        for ( int i = 0; i < N; i++ ) {
            cout << P[i] << "\n";
        }
    } else {
        cout << "No\n";
    }
}

int main() {
    solve();
    return 0;
}

