#define MAXN 100000

using namespace std;

int N, K;
vector <int> adj[MAXN];
int val[MAXN];
int par[MAXN];
bool vis[MAXN];

int parity[MAXN];
int minval[MAXN], maxval[MAXN];

void dfs(int i, int prv) {
    par[i] = prv;
    for (int j : adj[i])
        if (j != prv)
            dfs(j, i);
}

void dfs_set(int i) {
    int prv = par[i];
    if (prv == -1) {
        val[i] = minval[i];
        assert((val[i] % 2 + 2) % 2 == parity[i]);
    }
    else if (val[i] == -1) {
        if (val[prv] - 1 >= minval[i] && val[prv] - 1 <= maxval[i])
            val[i] = val[prv] - 1;
        else
            val[i] = val[prv] + 1;
    }
    for (int j : adj[i])
        if (j != prv)
            dfs_set(j);
}

bool solve() {
    for (int i = 0; i < N; i++) {
        if (adj[i].size() > 1)
            continue;
        int prv = i;
        int cur = par[i];
        while (cur != -1) {
            vis[prv] = true;
            if (parity[prv] != -1) {
                if (parity[cur] != -1) {
                    if (parity[cur] != 1 - parity[prv])
                        return false;
                    // opt: if no change, done
                    if (vis[cur]
                            && minval[cur] >= minval[prv] - 1
                            && maxval[cur] <= maxval[prv] + 1)
                        break;
                    minval[cur] = max(minval[cur], minval[prv] - 1);
                    maxval[cur] = min(maxval[cur], maxval[prv] + 1);
                    if (minval[cur] > maxval[cur])
                        return false;
                }
                else {
                    parity[cur] = 1 - parity[prv];
                    minval[cur] = minval[prv] - 1;
                    maxval[cur] = maxval[prv] + 1;
                }
            }
            prv = cur;
            cur = par[cur];
        }
    }
    return true;
}

