        u--, v--;
        adj[u].push_back(v);
        adj[v].push_back(u);
    }

    for (int i = 0; i < N; i++) {
        val[i] = -1;
        parity[i] = -1;
    }
    scanf("%d", &K);
    int root = -1;
    for (int i = 0; i < K; i++) {
        int v, p;
        scanf("%d%d", &v, &p);
        v--;
        root = v;
        val[v] = p;
        parity[v] = p % 2;
        minval[v] = maxval[v] = p;
    }

