const int N = 100000 + 10;
vector<int> g[N];
int color[N];

pair<int, int> r[N];

pair<int, int> rec(int curr, int prev, pair<int, int> p)
{
  if (color[curr] != -1) {
    if (abs(p.first  - color[curr]) % 2) throw "";
    if (abs(p.second - color[curr]) % 2) throw "";
    p = make_pair(color[curr], color[curr]);
  }

  each (next, g[curr]) {
    if (next == prev) continue;
    pair<int, int> x = make_pair(p.first - 1, p.second + 1);
    pair<int, int> q = rec(next, curr, x);
    q.first  = min({p.second, q.first  + 1, x.second});
    q.second = max({p.first, q.second - 1, x.first});
    if (abs(p.first - q.first) % 2 || abs(p.first - q.second) % 2) {
      // cout << "$" << curr+1 << "->" << next+1 << ' ' << p << ' ' << q << endl;
      throw "";
    }
    if (q.second < p.first || p.second < q.second) {
      // cout << "#" << curr+1 << "->" << next+1 << ' ' << p << ' ' << q << endl;
      throw "";
    }
    p.first = max(p.first, q.first);
    p.second = min(p.second, q.second);
  }
  //cout << curr+1 << ' ' << p << endl;
  return r[curr] = p;
}

void paint(int curr, int prev, int x)
{
  if (color[curr] == -1) color[curr] = x;
  each (next, g[curr]) {
    if (next == prev) continue;
    if (r[next].second < x + 1) {
      paint(next, curr, x + 1);
    } else {
      paint(next, curr, x - 1);
    }
  }
  return ;
}

