{
    int v,nx;
}edge[maxn<<1];
int cnt;
bool flag;

void _init() {
    cnt=0;
    memset(head,-1,sizeof(head));
}

void add(int u,int v) {
    edge[cnt].v=v; edge[cnt].nx=head[u];
    head[u]=cnt++;
    edge[cnt].v=u; edge[cnt].nx=head[v];
    head[v]=cnt++;
}

void dfs1(int u,int fa) {
    if (mark[u] && (v[u]^(a[u]&1))) {
        flag=0; return;
    }
    for (int i=head[u];i!=-1;i=edge[i].nx) {
        int to=edge[i].v;
        if (to==fa) continue;
        v[to]=v[u]^1;
        dfs1(to,u);
    }
}

void dfs2(int u,int fa) {
    if (mark[u]) L[u]=R[u]=a[u];
    else L[u]=-1e9,R[u]=1e9;
    for (int i=head[u];i!=-1;i=edge[i].nx) {
        int to=edge[i].v;
        if (to==fa) continue;
        dfs2(to,u);
        L[u]=max(L[to]-1,L[u]);
        R[u]=min(R[to]+1,R[u]);
    }
    if (L[u]>R[u]) flag=0;
}

void dfs3(int u,int fa) {
    for (int i=head[u];i!=-1;i=edge[i].nx) {
        int to=edge[i].v;
        if (to==fa) continue;
        a[to]=a[u]+(a[u]+1>R[u]?-1:1);
        dfs3(to,u);
    }
}

