vector<int64_t> solv1(int64_t a,int64_t b){//頂点a について(b->aという向き) bのありうるパターンについて返す
    bool flag=true;//目的の木を作れるかどうか判定
    vector<int64_t> ret;
    if(b != -1 && G[a].size()==1){//葉の時
        if(P[a]!=INF){
            v[a].push_back(P[a]);
            ret.push_back(P[a]-1);
            ret.push_back(P[a]+1);
        }
    }else{
        for(int i=0;i<G[a].size();i++){
            if(G[a][i]!=b){
                vector<int64_t> tmp = solv1(G[a][i],a);//葉について先に処理する。
                if(tmp.size()!=0 && tmp[0]==INF){
                    flag=false;
                }else{
                    if(tmp.size()!=0){//葉に値の決まっている頂点があった時
                        if(P[a]!=INF){
                            int64_t x = P[a]-tmp[0];
                            int64_t y = P[a]-tmp[1];
                            if(x%2 != 0 || y%2 != 0){
                                flag=false;
                            }
                        }
                        if(v[a].size()==0){
                            v[a]=tmp;
                        }else{
                            sort(v[a].begin(),v[a].end());
                            sort(tmp.begin(),tmp.end());
                            if(tmp[1]<v[a][0] || v[a][1]<tmp[0]){
                                flag=false;
                            }else{
                                v[a][0]=max(tmp[0],v[a][0]);
                                v[a][1]=min(tmp[1],v[a][1]);
                            }
                        }
                    }
                }
            }
        }//これでv[a]がもとまった。次に、returnの処理をする。
        if(flag){
            if(P[a]!=INF){
                if(v[a].size()!=0){
                    if(P[a]<v[a][0] || P[a]>v[a][1]){
                        flag=false;
                    }else{
                        v[a].clear();
                        v[a].push_back(P[a]);
                        ret.push_back(P[a]-1);
                        ret.push_back(P[a]+1);
                    }
                }else{
                    v[a].push_back(P[a]);
                    ret.push_back(P[a]-1);
                    ret.push_back(P[a]+1);
                }
            }else{
                if(v[a].size()!=0){
                    ret.push_back(v[a][0]-1);
                    ret.push_back(v[a][1]+1);
                }
            }
        }
        if(!flag){
            ret.push_back(INF);
            ret.push_back(INF);
        }
    }
    return ret;
}
void solv2(int64_t a,int64_t c,int64_t b){//b->aへcがきた。(P[b]=c)
    if(b==-1){
        P[a]=v[a][0];
        for(int i=0;i<G[a].size();i++){
            solv2(G[a][i],P[a],a);
        }
    }else{
        if(P[a]==INF){
            if(v[a].size()==0){
                P[a]=c-1;
            }else if(v[a].size()==1){
                P[a]=v[a][0];
            }else{
                if(v[a][0]<= c-1 && c-1<= v[a][1]){
                    P[a]=c-1;
                }
                if(v[a][0]<= c+1 && c+1 <= v[a][1]){
                    P[a]=c+1;
                }
            }
        }
        for(int i=0;i<G[a].size();i++){
            if(G[a][i]!=b){
                solv2(G[a][i],P[a],a);
            }
        }
    }
}



