        int64_t a,b;
        cin>>a>>b;
        a--;
        P[a]=b;
    }
    vector<int64_t> tmp=solv1(0,-1);
    if(tmp[0]!=INF){
        cout<<"Yes"<<endl;
        solv2(0,0,-1);
