const int INFTY = 1e7;
vb seen;

bool dfs(Graph<int> &g, vector<pii> &num, int v, int p) {
  if (seen[v]) return true;

  for (int &nv : g[v]) {
    if (nv != p) {
      if (!dfs(g, num, nv, v)) return false;

      if (num[v].first != -INFTY && (num[v].first + num[nv].first) % 2 == 0) return false;

      chmax(num[v].first, num[nv].first - 1);
      chmin(num[v].second, num[nv].second + 1);

      if (num[v].first - num[v].second > 0) return false;
    }
  }

  return seen[v] = true;
}

void confirm(Graph<int> &g, vector<pii> &num, vi &ans, int v, int p) {
  for (int &nv : g[v]) {
    if (nv != p) {
      ans[nv] = num[nv].first < ans[v] ? ans[v] - 1 : ans[v] + 1;
      confirm(g, num, ans, nv, v);
    }
  }
}

