  int n; cin >> n;
  Graph<int> g(n);
  rep1(i,n) {
    int a, b; cin >> a >> b; --a, --b;
    g[a].emplace_back(b);
    g[b].emplace_back(a);
  }

  vector<pii> num(n, {-INFTY, INFTY});
  seen.assign(n, false);

  int k, v, p; cin >> k;
  rep(i,k) {
    cin >> v >> p; --v;
    num[v] = {p, p};
    seen[v] = true;
  }

  rep(i,n) {
    if (seen[i]) continue;

    if (!dfs(g, num, i, -1)) {
      cout << "No\n";
      return;
    }
  }

  vi ans(n);
  ans[v] = p;
  confirm(g, num, ans, v, -1);

  cout << "Yes\n";
  interval[0] = "\n";
  cout << ans << endl;
}


