#include <bits/stdc++.h>
using namespace std;

using pii = pair<int, int>;

int absolut(const int vodka){
	return max(vodka, -vodka); }

pii intersect(const pii a, const pii b){
	return pii { max(a.first, b.first), min(a.second, b.second) }; }

pii enlarge(const pii a){
	return pii { a.first - 1, a.second + 1 }; }

constexpr pii universal { (int)-1e5 - 10, (int)1e5 + 10 };
constexpr int unknown = -1;

vector<vector<int>> vec;

vector<int> inits;
vector<pii> good_intervals;

bool first_dfs(const int cur, const int prev){
	for(const auto next : vec[cur]){
		if(next == prev) continue;
		else if(inits[next] == unknown) inits[next] = (inits[cur] ^ 1);
		else if(inits[next] == inits[cur]) return false;

		if(!first_dfs(next, cur)) return false; }
	return true; }

bool dfs(const int cur, const int prev){
	for(const auto next : vec[cur]){
		if(next == prev) continue;
		if(!dfs(next, cur)) return false;
		good_intervals[cur] = intersect(good_intervals[cur], enlarge(good_intervals[next])); }
	return good_intervals[cur].first <= good_intervals[cur].second; }

void build(const int cur, const int prev){
	for(const auto next : vec[cur]){
		if(next == prev) continue;
		good_intervals[next] = intersect(good_intervals[next], enlarge(good_intervals[cur]));
		build(next, cur); } }

int main(){
	int n, k;
	cin >> n;
	vec.resize(n), inits.resize(n, unknown), good_intervals.resize(n, universal);
	for(int i = n-1, x, y; i; --i){
		cin >> x >> y;
		vec[--x].push_back(--y);
		vec[y].push_back(x); }

	cin >> k;

	int root = 0;
	for(int i = k, v, p; i; --i){
		cin >> v >> p;
		root = --v;
		inits[v] = absolut(p)%2;
		good_intervals[v] = make_pair(p, p); }

	if(!first_dfs(root, -1) || !dfs(root, -1)){
		cout << "NO\n";
		return 0; }
	build(root, -1);

	for(int i = 0; i < n; ++i){
		if(absolut(good_intervals[i].first) % 2 != inits[i]) ++good_intervals[i].first; }

	cout << "YES\n";
	for(const auto x : good_intervals){
		cout << x.first << '\n'; }

	return 0; }

