using namespace std;
constexpr int inf = 10000000;

int N;
vector<vector<int> > edge;
int K;
vector<int> P;

vector<int> low, high;

bool flg;

vector<int> ans;

void calclh(int now, int prev)
{
    int min_tmp = -inf, max_tmp = inf;

    if (P[now] >= 0) min_tmp = max_tmp = P[now];

    for (auto v : edge[now])
    {
        if (v == prev) continue;
        calclh(v, now);
        if (max_tmp < inf && high[v] < inf && (abs(high[v] - max_tmp) % 2 == 0))
        {
            flg = true;
        }
        max_tmp = min(max_tmp, high[v]+1);
        min_tmp = max(min_tmp, low[v]-1);
        if (max_tmp < min_tmp) flg = true;
    }
    low[now] = min_tmp;
    high[now] = max_tmp;
}

void calcans(int now, int prev)
{
    if (prev < 0) ans[now] = low[now];
    else
    {
        ans[now] = ans[prev] - 1;
        if (ans[now] < low[now]) ans[now] += 2;
    }
    for (auto v : edge[now])
    {
        if (v == prev) continue;
        calcans(v, now);
    }
}

