    int vi, pi;
    for (int i=0; i<K; i++)
    {
        cin >> vi >> pi;
        vi--;
        P[vi] = pi;
    }

    flg = false;
    low = high = vector<int>(N, -inf);
    calclh(vi, -1);
    if (flg)
    {
        cout << "No" << endl;
    }
    else
    {
        cout << "Yes" << endl;
        ans.resize(N);
        calcans(vi, -1);
        for (auto v : ans) cout << v << endl;
    }
}

