void solve(int v,int lst){
	l[v]=-Inf-1;
	r[v]=Inf+1;
	if(num[v]!=Inf){
		l[v]=r[v]=num[v];
	}
	for(int i=0;i<SZ(nei[v]);i++){
		int u=nei[v][i];
		if(u==lst){
			continue;
		}
		solve(u,v);
		if(l[u]<-Inf/2){
			continue;
		}
		if(l[v]<-Inf/2){
			l[v]=l[u]-1;
			r[v]=r[u]+1;
		}else{
			if(abs(l[u])%2==abs(l[v])%2){
				fuck=1;
				return;
			}
			l[v]=max(l[v],l[u]-1);
			r[v]=min(r[v],r[u]+1);
		}
	}
	if(l[v]>r[v]){
		fuck=1;
	}
}

void gao(int v,int lst){
	if(v==1&&num[v]==Inf){
		num[v]=l[v];
	}
	for(int i=0;i<SZ(nei[v]);i++){
		int u=nei[v][i];
		if(u==lst){
			continue;
		}
		if(num[u]==Inf){
			if(l[u]<=num[v]-1&&num[v]-1<=r[u]){
				num[u]=num[v]-1;
			}else{
				num[u]=num[v]+1;
			}
		}
		gao(u,v);
	}
}

