P dfs(int m, int _ma, int _mi) {
	if (f[m])return P(_ma - 1, _mi + 1);
	f[m] = true;

	ma[m] = min(_ma, ma[m]);
	mi[m] = max(_mi, mi[m]);

	if (mi[m] > ma[m]) {
		cout << "No" << endl;
		exit(0);
	}

	each(to, e[m]) {
		auto p = dfs(to, ma[m] + 1, mi[m] - 1);
		ma[m] = min(p.first,  ma[m]);
		mi[m] = max(p.second, mi[m]);

		if (mi[m] > ma[m]) {
			cout << "No" << endl;
			exit(0);
		}
	}

	return P(ma[m] + 1, mi[m] - 1);
}

void dfs2(int m, int t, int dist) {
	if (f[m])return;
	f[m] = true;

	if (ma[m] == mi[m]) {
		if (abs(ma[m] - t) % 2 != dist % 2) {
			cout << "No" << endl;
			exit(0);
		}
	}

	each(to, e[m]) {
		if (ma[m] == mi[m]){
			dfs2(to, ma[m], 1);
		}
		else {
			dfs2(to, t, dist + 1);
		}
	}
}

