vi label;

vi isW (2);
vi isB (2);

void dfs1(int cur, int par, int col) {
	if (label[cur] >= 0) {
		if (col) isW[label[cur] % 2] = true;
		else     isB[label[cur] % 2] = true;
	}
	for (int n : graph[cur]) if (n != par) {
		dfs1(n, cur, 1-col);
	}
}

bool fail = false;
vi lo;
vi hi;
void dfs2(int cur, int par, bool isEven) {
	if (graph[cur].size() + (par != -1) == 1) {
		// leaf
		if (label[cur] == -1) {
			lo[cur] = -1e6 - !isEven;
			hi[cur] = 1e6 + !isEven;
		} else {
			lo[cur] = label[cur];
			hi[cur] = label[cur];
		}
	} else {
		int clo = -1e7;
		int chi = 1e7;
		for (int n : graph[cur]) if (n != par) {
			dfs2(n, cur, !isEven);
			clo = max(clo, lo[n]);
			chi = min(chi, hi[n]);
		}
		if (clo > chi) fail = true;
		lo[cur] = clo - 1;
		hi[cur] = chi + 1;
		if (label[cur] != -1) {
			if (!(lo[cur] <= label[cur] && label[cur] <= hi[cur])) fail = true;
			lo[cur] = label[cur];
			hi[cur] = label[cur];
		}
	}
}

void dfs3(int cur, int par, int val) {
	if (val - 1 >= lo[cur]) {
		label[cur] = val - 1;
	} else {
		label[cur] = val + 1;
	}
	for (int n : graph[cur]) if (n != par) {
		dfs3(n, cur, label[cur]);
	}
}

