                if(kind[u]==-1) kind[u]=(kind[v]+1)%2;
                else if(kind[u]!=(kind[v]+1)%2) return false;
            }
            lb[u]=max(lb[u],lb[v]-1);
            ub[u]=min(ub[u],ub[v]+1);
        }
