void dfs(int p, int rt, int d)
{
	dep[p] = d;
	for (int q : graph[p]) if (q != rt) {
		dfs(q, p, d + 1);
		low[p] = max(low[p], low[q] - 1);
		hi[p] = min(hi[p], hi[q] + 1);
	}
}
void dfs2(int p, int rt)
{
	for (int q : graph[p]) if (q != rt) {
		low[q] = max(low[q], low[p] - 1);
		hi[q] = min(hi[q], hi[p] + 1);
		dfs2(q, p);
	}
}
