			ans=false;
			return;
		}
		l[x]=max(l[x],l[g[x][i]]-1);
		r[x]=min(r[x],r[g[x][i]]+1);
		}
	}
	if(l[x]>r[x])ans=false;
}
void make(int x,int par=-1){
	if(x==1&&id[x]==-1)id[x]=l[x];
	for(int i=0;i<g[x].size();i++){
