#include"bits/stdc++.h"
using namespace std;
using ll = int64_t;

vector<vector<ll>> edges;
vector<ll> value;
vector<pair<ll, ll>> conds;
bool flag;

pair<ll, ll> solve(ll curr, ll pre) {
    pair<ll, ll> cond{ INT_MIN, INT_MAX };
    if (value[curr] != -1) {
        cond.first = cond.second = value[curr];
    }
    for (ll i = 0; i < edges[curr].size(); i++) {
        ll next = edges[curr][i];
        if (next == pre) {
            continue;
        }
        auto next_cond = solve(next, curr);
        cond.first = max(cond.first, next_cond.first);
        cond.second = min(cond.second, next_cond.second);
        if (cond.first > cond.second) {
            flag = false;
            return { INT_MAX, INT_MIN };
        }
    }
    conds[curr] = cond;
    return { cond.first - 1, cond.second + 1 };
}

void write(ll curr, ll pre) {
    if (pre != -1) {
        if (conds[curr].first <= value[pre] + 1 && value[pre] + 1 <= conds[curr].second) {
            value[curr] = value[pre] + 1;
        } else if(conds[curr].first <= value[pre] - 1 && value[pre] - 1 <= conds[curr].second) {
            value[curr] = value[pre] - 1;
        } else {
            flag = false;
            return;
        }
    }

    for (ll next : edges[curr]) {
        if (next == pre) {
            continue;
        }
        write(next, curr);
    }
}

int main() {
    ll N;
    cin >> N;
    value.resize(N, -1);
    conds.resize(N);
    edges.resize(N);
    for (ll i = 0; i < N - 1; i++) {
        ll A, B;
        cin >> A >> B;
        A--; B--;
        edges[A].push_back(B);
        edges[B].push_back(A);
    }

    ll K;
    cin >> K;
    vector<ll> V(K), P(K);
    for (ll i = 0; i < K; i++) {
        cin >> V[i] >> P[i];
        V[i]--;
        value[V[i]] = P[i];
    }

    flag = true;
    solve(V[0], -1);

    if (!flag) {
        cout << "No" << endl;
    } else {
        write(V[0], -1);
        if (!flag) {
            cout << "No" << endl;
            return 0;
        }
        cout << "Yes" << endl;
        for (ll i = 0; i < N; i++) {
            cout << value[i] << endl;
        }
    }
}

