{
	for (int i = Head[u], v;i;i = Next[i])
		if ((v = To[i]) != fa)
			dfs(v, u), L[u] = max(L[u], L[v] - 1), R[u] = min(R[u], R[v] + 1);
	if (L[u] > R[u])
