	for (int i = Head[u], v;i;i = Next[i])
		if ((v = To[i]) != fa)
		{
			if (L[v] <= Ans[u] - 1 && Ans[u] - 1 <= R[v])
				Ans[v] = Ans[u] - 1;
			else
				Ans[v] = Ans[u] + 1;
			printAns(v, u);
		}
}

