// O(N)
void f1(int v, int p, bool pari, const VVI& G) {
	if (cond[v].second - cond[v].first == 0) {
		// 値が決まっている場合
	}
	else { // そうではない
		// 親のcondをみて、自身の区間を決定する
		// parityいらなくないか
		cond[v].first = cond[p].first - 1;
		cond[v].second = cond[p].second + 1;
	}

	PLL rg = PLL(-INF, INF);
	for (int nx : G[v]) {
		if (nx == p)continue;
