using namespace std;

const int INF = 1 << 30;

struct Data
{
  int small, big;
};

int N, K;
int value[100000];
vector< int > tree[100000];
int sz[100000];
int cost[100000];

Data dfs(int idx, Data order, int par = -1)
{
  if(~value[idx]) {
    if(order.big == INF) {
      order.small = order.big = value[idx];
    } else {
      if(order.small <= value[idx] && value[idx] <= order.big && order.small % 2 == value[idx] % 2) {
        order.small = order.big = value[idx];
      } else {
        puts("No");
        exit(0);
      }
    }
  }

  int top = -1;
  for(int i = 0; i < tree[idx].size(); i++) {
    if(tree[idx][i] == par) continue;
    if(top == -1 || sz[tree[idx][top]] < sz[tree[idx][i]]) top = i;
  }
  if(~top) swap(tree[idx][0], tree[idx][top]);

  for(int to : tree[idx]) {
    if(to == par) continue;
    Data ord = dfs(to, {order.small - 1, order.big + 1}, idx);
    order.small = max(order.small, ord.small);
    order.big = min(order.big, ord.big);
  }

  if(order.small > order.big) {
    puts("No");
    exit(0);
  }
  value[idx] = order.small;

  order.small--;
  order.big++;
  return (order);
}

int calc(int idx, int par)
{
  for(int to : tree[idx]) {
    if(to == par) continue;
    sz[idx] += calc(to, idx);
  }
  if(~value[idx]) ++sz[idx];
  return (sz[idx]);
}

int main()
{
  cin >> N;
  for(int i = 0; i < N - 1; i++) {
    int A, B;
    cin >> A >> B;
    tree[--A].push_back(--B);
    tree[B].push_back(A);
  }
  cin >> K;
  memset(value, -1, sizeof(value));
  for(int i = 0; i < K; i++) {
    int V, P;
    cin >> V >> P;
    value[--V] = P;
  }
  calc(0, -1);
  dfs(0, (Data) {-1, INF});
  puts("Yes");
  for(int i = 0; i < N; i++) {
    cout << value[i] << endl;
  }
}

