void calc(int s, int val) {
    res[s] = val;
    for (int i = 0; i < g[s].size(); i++) {
        int idx = g[s][i];
        if (!used[idx]) {
            used[idx] = true;
            if (memo[idx].first <= val-1 && val-1 <= memo[idx].second) calc(idx, val-1);
            else calc(idx, val+1);
        }
    }
}

inline P intersect(P p0, P p1) {
    if (p0.second < p1.first || p1.second < p0.second) return P(inf, -inf);
    return P(max(p0.first, p1.first), min(p0.second, p1.second));
}

P rec(int s, P q) {
    if (memo[s].first >= 0) {
        if ((q.first-memo[s].first)%2 != 0 || !(q.first <= memo[s].first && memo[s].second <= q.second)) return P(inf, -inf);
        q = memo[s];
        for (int i = 0; i < g[s].size(); i++) {
            int idx = g[s][i];
            if (!used[idx]) {
                used[idx] = true;
                P ret = rec(idx, P(q.first-1, q.second+1));
                if (ret.first > ret.second) return ret;
                memo[s] = intersect(memo[s], ret);
                if (memo[s].first > memo[s].second) return memo[s];
            }
        }
        return P(memo[s].first-1, memo[s].second+1);
    } else {
        memo[s] = q;
        for (int i = 0; i < g[s].size(); i++) {
            int idx = g[s][i];
            if (!used[idx]) {
                used[idx] = true;
                P ret = rec(idx, P(q.first-1, q.second+1));
                if (ret.first > ret.second) return ret;
                memo[s] = intersect(memo[s], ret);
                if (memo[s].first > memo[s].second) return memo[s];
            }
        }
        return P(memo[s].first-1, memo[s].second+1);
    }
}

void solve() {
