		nei[y].push_back(x);
	}
	scanf("%d",&k);
	while(k--){
		int x,val;
		scanf("%d%d",&x,&val);
		ver[x]=val;
	}
	check(1,-1);
	if(ok){
		puts("Yes");
		make(1,-1);
		for(int i=1;i<=n;i++) printf("%d\n",ver[i]);
	}else{
		puts("No");
	}
	return 0;
}

