    numEdge = 0;
    memset(head, -1, sizeof(head));
    memset(id, -1, sizeof(id));
    for(int u, v, i = 1; i < n; i++)
    {
        scanf("%d%d", &u, &v);
        addEdge(u, v);
        addEdge(v, u);
    }
    for(int i = 1; i <= n; i++) L[i] = -INF, R[i] = INF;
