    for(int i=1;i<=K;i++) {
        int v,p;
        cin>>v>>p;
        isset[v]=true;
        range[v]=make_pair(p,p);
    }

    for(int i=1;i<=N;i++) {
        for(int j=0;j<edges[i].size();j++) {
            if (!isset[edges[i][j]])
                unset_edges[i].push_back(edges[i][j]);
        }
    }


    bool ok = true;
    bool change = false;
    for(int v=1;v<=N;v++) {
        if (isset[v]) {
            for(int j=0;j<unset_edges[v].size();j++) {
                ok &= dfs(v,unset_edges[v][j],range[v]);
                if (!ok)
                    break;
            }
        }
        if (!ok)
            break;
    }


    if (ok) {
        for(int v=1;v<=N;v++) {
            if (isset[v]) {
                answer[v]=range[v].first;
                for(int j=0;j<edges[v].size();j++) {
                    ok &= dfs2(v,edges[v][j],range[v].first);
                    if (!ok)
                        break;
                }
                if (!ok)
                    break;
                break;
            }
            if (!ok)
                break;
        }
    }


    if (ok) {
        cout << "Yes" << endl;

        for(int v=1;v<=N;v++) {
            cout << answer[v] << endl;
        }


    } else {
