void dfs(int v, int value)
{
    mod2[v] = value;
    if (p[v] != -INF && p[v] % 2 != value)
    {
        cout << "No";
        exit(0);
    }
    if (c[v] == 1)
        return;
    c[v] = 1;
    for (int j = 0; j < graph[v].size(); j++)
    {
        int u = graph[v][j];
        dfs(u, 1 - value);
    }
}

signed main()
{
    ios_base::sync_with_stdio(false);
    cin.tie(0);
