const ll inf = 5e15;

struct Solver {
    ll n, k;
    graph::Graph<false> tree;
    vec<ll> val;
    std::queue<ll> que;
    vec<ll> par;
    vec<pll> ranges;
    const pll err = pll(-inf, -inf), init = pll(inf, inf);

    Solver(ll n) : n(n), tree(n), val(n, -1), par(n), ranges(n) {
        for (ll i = 1; i < n; i++) {
            ll a, b;
            std::cin >> a >> b;
            tree.add_edge(a - 1, b - 1);
        }

        std::cin >> k;
        for (ll i = 0; i < k; i++) {
            ll v, p;
            std::cin >> v >> p;
            val[v - 1] = p;
        }
    }

    bool is_init(pll p) {
        ll l, r;
        std::tie(l, r) = p;
        return inf <= std::max(std::abs(l), std::abs(r));
    }

    pll merge(pll p, pll q) {
        if (p > q) std::swap(p, q);
        if (p == err) return p;
        if (is_init(p)) return init;
        if (is_init(q)) return p;
        ll a, b, c, d;
        std::tie(a, b) = p;
        std::tie(c, d) = q;
        bool o1 = std::abs(a) & 1;
        bool o2 = std::abs(c) & 1;
        if (o1 ^ o2) return err;
        ll x = std::max(a, c), y = std::min(b, d);
        if (y < x) return err;
        return pll(x, y);
    }

    bool valid(pll rng, ll v) {
        ll l, r;
        std::tie(l, r) = rng;
        return l <= v && v <= r;
    }

    bool dfs(ll cur, ll pre) {
        par[cur] = pre;
        pll rng = (val[cur] == -1 ? init : pll(val[cur], val[cur]));
        if (val[cur] == -1) que.push(cur);
        for (ll nxt : graph::dst(tree[cur])) {
            if (nxt == pre) continue;
            if (!dfs(nxt, cur)) return false;
            ll l, r;
            std::tie(l, r) = ranges[nxt];
            rng = merge(rng, pll(l - 1, r + 1));
        }
        ranges[cur] = rng;
        return rng != err;
    }

    void write() {
        while (que.size()) {
            ll cur = que.front();
            que.pop();
            ll pv = val[par[cur]];
            if (valid(ranges[cur], pv + 1)) val[cur] = pv + 1;
            else val[cur] = pv - 1;
        }
    }

    vec<ll> solve() {
        for (ll i = 0; i < n; i++) {
            if (val[i] == -1) continue;
            if (!dfs(i, -1)) return vec<ll>();
        }
        write();
        return val;
    }
};

int main() {
    ll n;
    std::cin >> n;
    Solver solver(n);
    auto ans = solver.solve();
    if (ans.empty()) {
        std::cout << "No\n";
    } else {
        std::cout << "Yes\n";
        for (ll e : ans) std::cout << e << "\n";
    }
    return 0;
}

