int n, k;
int  l[100000 + 5], r[100000 + 5];
vector<vector<int>> g(100000 + 5);
int ans[100000 + 5];
bool update[100000 + 5];

void dfs(int s, int val, int now, int par, int dist) {
    l[now] = max(l[now], val - dist);
    r[now] = min(r[now], val + dist);
    if (update[now]) {
        if (ans[now] < l[now] || r[now] < ans[now]) {
            cout << "No" << endl;
            exit(0);
        }
        if (s != now) return ;
    }
    for (auto nx : g[now]) {
        if (nx == par) continue;
        dfs(s, val, nx, now, dist + 1);
    }
}

signed main() {	
    cin.tie(0);
    ios::sync_with_stdio(false);
    cin >> n;
    rep(i, n - 1) {
        int a, b;
        cin >> a >> b;
        a--; b--;
        g[a].push_back(b);
        g[b].push_back(a);
    }
    cin >> k;
    rep(i, k) {
        int v, p;
        cin >> v >> p;
        v--;
        update[v] = true;
        ans[v] = p;
    }
    rep(i, n) {
        l[i] = -INFLL;
        r[i] = INFLL;
    }
    rep(i, n) {
        if (update[i]) {
            dfs(i, ans[i], i, -1, 0);
        }
    }
    cout << "Yes" << endl;
    rep(i, n) {
        if (update[i]) {
            cout << ans[i] << endl;
        }
        else {
            cout << r[i] << endl;
        }
    }

}

