inline void link (int u, int v)
{
	tot++;
	e[tot].u = u;
	e[tot].v = v;
	e[tot].last = last[u];
	last[u] = tot;
}
inline void get_in (int x, int fa, int z, int sum)
{
	a[x].num = a[z].num;
	a[x].cnt = sum;
	for (int i = last[x]; i; i = e[i].last)
	{
		int v = e[i].v;
		if (v != fa)
		{
			get_in (v, x, z, sum + 1);
		}
	}
}
inline bool dfs (int x, int fa)
{
	int nowx = a[x].num, nowcnt = a[x].cnt;
	for (int i = last[x]; i; i = e[i].last)
	{
		int v = e[i].v;
		if (v != fa)
		{
			bool q = dfs (v, x);
			if (!q)
			return false;
			if (a[x].num != -1 && a[v].num == -1)
			get_in (v, x, x, 1);
			if (a[v].num == -1)
			continue;
			if (nowx == -1 && a[v].num != -1)
			{
				nowx = a[v].num;
				nowcnt = a[v].cnt + 1;
				continue;
			}
			if (((abs(nowx - a[v].num) % 2) ^ (abs(nowcnt - (a[v].cnt + 1)) % 2)) == 1)
			return false;
			int maxnow, minnow, maxv, minv;
			maxnow = nowx + nowcnt;
			minnow = nowx - nowcnt;
			maxv = a[v].num + (a[v].cnt + 1);
			minv = a[v].num - (a[v].cnt + 1);
			if (minv > maxnow || minnow > maxv)
			return false;
			minnow = max (minnow, minv);
			maxnow = min (maxnow, maxv);
			nowx = (minnow + maxnow) >> 1;
			nowcnt = nowx - minnow;
		}
	}
	a[x].num = nowx;
	a[x].cnt = nowcnt;
	return true;
}
inline void check (int x, int fa)
{
	for (int i = last[x]; i; i = e[i].last)
	{
		int v = e[i].v;
		if (v != fa)
		{
			if (a[v].num == -1)
			get_in (v, x, x, 1);
			else
			check (v, x);
		}
	}
}
