using namespace std;
const int LEN = 1e5 + 5;
const int oo = 1e9;
int head[LEN];
struct edge {
    int vet, next;
} E[LEN * 2];
int i, j, k, n, m, s, t, tot;
bool checkodd, checkval;
int L[LEN], R[LEN], isodd[LEN], ans[LEN];
void add(int u, int v) {
    E[++tot] = (edge){v, head[u]};
    head[u] = tot;
}
void dfs(int u, int pre) {
    for (int e = head[u]; e != -1; e = E[e].next) {
        int v = E[e].vet;
        if (v != pre) {
            if (isodd[v] != -1 && isodd[v] != (isodd[u] ^ 1)) {
                checkodd = false;
            }
            isodd[v] = isodd[u] ^ 1;
            dfs(v, u);
            L[u] = max(L[u], L[v] - 1);
            R[u] = min(R[u], R[v] + 1);
        }
    }
    if (L[u] > R[u]) {
        checkval = false;
    }
}
void dfs2(int u, int pre) {
    for (int e = head[u]; e != -1; e = E[e].next) {
        int v = E[e].vet;
        if (v != pre) {
            L[v] = max(L[v], L[u] - 1);
            R[v] = min(R[v], R[u] + 1);
            dfs2(v, u);
        }
    }
}
void dfsans(int u, int pre) {
    for (int e = head[u]; e != -1; e = E[e].next) {
        int v = E[e].vet;
        if (v != pre) {
            if (L[v] <= ans[u] + 1 && ans[u] + 1 <= R[v]) {
                ans[v] = ans[u] + 1;
            } else {
                ans[v] = ans[u] - 1;
            }
            dfsans(v, u);
        }
    }
}
int main() {
    scanf("%d", &n);
    for (i = 1; i <= n; i++) {
        head[i] = -1;
        L[i] = -oo;
        R[i] = oo;
        isodd[i] = -1;
    }
    for (int i = 1; i < n; i++) {
        int x, y;
        scanf("%d %d", &x, &y);
        add(x, y);
        add(y, x);
    }
    scanf("%d", &m);
    for (int i = 1; i <= m; i++) {
        int x, c;
        scanf("%d %d", &x, &c);
        L[x] = R[x] = c;
        isodd[x] = c % 2;
        s = x;
    }
    checkodd = checkval = true;
    dfs(s, -1);
    if (checkodd == false || checkval == false) {
        puts("No");
        return 0;
    }
    ans[s] = L[s];
    dfsans(s, -1);
    puts("Yes");
    for (int i = 1; i <= n; i++) {
        printf("%d\n", ans[i]);
    }
    return 0;
}

#include <bits/stdc++.h>
using namespace std;
#define rep(i,n) for(int i = 0; i < (int)n; i++)
using ll = long long;
const int INF = 1e9;
const int MAX = 1e5;
vector<int> u(MAX), l(MAX,-INF), r(MAX,INF);
vector<vector<int>> g(MAX);
vector<int> color(MAX,0);

void dfs(int v, int p) {
  for(auto to : g[v]) {
    if(to != p) {
      dfs(to,v);
      l[v] = max(l[v],l[to]-1);
      r[v] = min(r[v],r[to]+1);
    }
  }
}

bool bipartite_dfs(int v, int c){
  color[v] = c;
  for(auto to : g[v]){
    if(color[to] == c) return false;
    if(color[to] == 0 && !bipartite_dfs(to,-c)) return false; 
  }
  return true;
}

bool draw(int v, int p) {
  if(p == -1) {
    if(color[v] == -1 && l[v] % 2) l[v]++;
    if(color[v] == 1 && l[v] % 2 == 0) l[v]++;
    if(l[v] > r[v]) return false;
    else u[v] = l[v];
  } else {
    int a = u[p] + 1, b = u[p] - 1;
    if(a >= l[v] && a <= r[v]) u[v] = a;
    else if(b >= l[v] && b <= r[v]) u[v] = b;
    else return false;
  }
  bool f = true;
  for(auto to : g[v]) {
    if(to != p) f = draw(to,v);
  }
  return f;
}

int main(){
  int n;
  cin >> n;
  rep(i,n-1) {
    int u, v;
    cin >> u >> v;
    u--; v--;
    g[u].push_back(v);
    g[v].push_back(u);
  }
  int k, s, c;
  cin >> k;
  rep(i,k) {
    int v, p;
    cin >> v >> p;
    v--;
    l[v] = p, r[v] = p;
    color[v] = (p % 2 ? 1 : -1);
    s = v, c = color[v];
  }
  if(!bipartite_dfs(s,c)) {
    cout << "No" << endl;
    return 0;
  }
  dfs(0,-1);
  bool ok = draw(0,-1);
  if(!ok) cout << "No" << endl;
  else {
    cout << "Yes" << endl;
    rep(i,n) cout << u[i] << endl;
  }
  return 0;
}

