#include <bits/stdc++.h>
using namespace std;
const int maxn = 1e5 + 10 ;
vector<int> G[maxn] ;
int l[maxn], r[maxn] ;
int ans[maxn] ;
void addEdge (int u, int v) {
	G[u].push_back (v) ;
	G[v].push_back (u) ;
}
bool find_ans = 1 ;
void dfs (int v, int fa) {
	bool flag = 0 ;
	int L = -1e9, R = 1e9 ;
	for (int i = 0; i < G[v].size(); i ++) {
		int to = G[v][i] ;
		if (to == fa) continue ;
		flag = 1 ;
		dfs (to, v) ;
		if (l[to] <= -1e9 || r[to] >= 1e9) continue ;
		if (L <= -1e9 || R >= 1e9) L = l[to] - 1, R = r[to] + 1 ;
		else {
			if (L % 2 != (l[to] - 1) % 2) find_ans = 0 ;
			L = max (L, l[to] - 1); R = min (R, r[to] + 1) ;
		}
	}
	if (!flag) {
		if (ans[v] == -1) l[v] = 1e-9, r[v] = 1e9 ;
		else l[v] = r[v] = ans[v] ;
	} else {
		if (L > R) find_ans = 0 ;
		l[v] = L; r[v] = R ;
		if (ans[v] != -1 && (ans[v] % 2 != l[v] % 2 || ans[v] < l[v] || ans[v] > r[v])) find_ans = 0 ;
	}
}
void dfs2 (int v, int fa) {
	if (ans[v] == -1) ans[v] = l[v] ;
	for (int i = 0; i < G[v].size(); i ++) {
		int to = G[v][i] ;
		if (to == fa) continue ;
		if (ans[v] + 1 >= l[to] && ans[v] + 1 <= r[to]) ans[to] = ans[v] + 1 ;
		else ans[to] = ans[v] - 1 ;
		dfs2 (to, v) ;
	}
}
int main() {
	int n, k ;
	scanf("%d", &n) ;
	for (int i = 1; i < n; i ++) {
		int u, v ;
		scanf("%d%d", &u, &v) ;
		addEdge (u, v) ;
	}
	fill (ans + 1, ans + n + 1, -1) ;
	scanf("%d", &k) ;
	for (int i = 1; i <= k; i ++) {
		int v, p ;
		scanf("%d%d", &v, &p) ;
		ans[v] = p ;
	}
	dfs (1, 0) ;
	if (!find_ans) printf("No\n") ;
	else {
		printf("Yes\n") ;
		dfs2 (1, 0) ;
		for (int i = 1; i <= n; i ++) printf("%d\n", ans[i]) ;
	}
	return 0 ;
}

