        cout << "No" << endl;
        return 0;
    }
    reverse(order.begin(), order.end());
    for (int i = 0; i < order.size(); i++) {
        int to = order[i];
        val[to] = solve_val(to, par[to]);
    }
    cout << "Yes" << endl;
    for (int i = 1; i <= n; i++) {
        cout << val[i] << endl;
    }

