    if( minv[x] <= ans[px] + 1 && ans[px] + 1 <= maxv[x] ) ans[x] = ans[px] + 1;

    if( minv[x] <= ans[px] - 1 && ans[px] - 1 <= maxv[x] ) ans[x] = ans[px] -1;

