void pre_dfs(int u, int pr)
{
	if(val[u] == -1) low[u] = -1e9, high[u] = 1e9; 
	else low[u] = high[u] = val[u];

	for(int v: adj[u])
		if(v != pr)
		{
			pre_dfs(v, u);
			chkmax(low[u], low[v] - 1);
			chkmin(high[u], high[v] + 1);
		}
}

void dfs1(int u, int pr)
{
	if(u != pr)
	{
		chkmax(low[u], low[pr] - 1);
		chkmin(high[u], high[pr] + 1);
	}

	for(int v: adj[u])
		if(v != pr)
			dfs1(v, u);
}

