			int l = max(now[u] - dif[u], now[v] - x), r = min(now[u] + dif[u], now[v] + x);
			if(l > r)
				exit(0 * puts("No"));
			assert((l + r) % 2 == 0);
			now[u] = (l + r) >> 1, dif[u] = r - now[u];
		}
		else
			if(~dif[v])
				now[u] = now[v], dif[u] = dif[v] + 1;
	}
	if(~val[u]) {
		if(~dif[u] && (val[u] < now[u] - dif[u] || val[u] > now[u] + dif[u]))
