// dijkstra shortest path O(E logV)
void dijkstra(int from){
  priority_queue<pair<long, int>, vector<pair<long, int> >, greater<pair<long, int> > > que; //pair<dist, idx>
  fill(all(d), INF);
  d[from] = 0;
  que.push(mp(0,from));
  while(!que.empty()){
    pair<long, int> p = que.top(); que.pop();
    int v = p.second;
    long dis = p.first;
    if(d[v] < dis) continue;
    for(edge e : vec[v]){
      long target = dis + e.cost;
      if(d[e.to] > target){
        d[e.to] = target;
	      que.push(mp(d[e.to], e.to));
      }
    }
  }
}
// END dijkstra

bool check_dfs(int from, int n){
  if(from!=-1 && abs(d[from]-d[n])!=1) return false;
  for(auto e : vec[n]) if(e.to != from && e.to!=0){
    if(!check_dfs(n, e.to)) return false;
  }
  return true;
}

