void copy(int x,int y){
	if(!y){
		rep(i,0,1)mi[x][i]=(1e9);
	}
	else{
		cl[x]=cl[y];
		cr[x]=cr[y];
		rep(i,0,1)mi[x][i]=mi[y][i];
	}
}
void insert(int &me,int l,int r,int x,int v){
	++segtot;
	copy(segtot,me);
	me=segtot;
	if(l==r){
		rep(i,0,1)mi[me][i]=v+dx[i]*x;
		return;
	}
	int mid=(l+r)>>1;
	if(x<=mid)insert(cl[me],l,mid,x,v);
	else insert(cr[me],mid+1,r,x,v);

	rep(i,0,1)mi[me][i]=min(mi[cl[me]][i],mi[cr[me]][i]);
}
int merge(int a,int b,int l,int r){
	if(!a||!b)return a+b;
	int d=++segtot;

	if(l==r){
		rep(i,0,1)mi[d][i]=min(mi[a][i],mi[b][i]);
		return d;
	}
	int mid=(l+r)>>1;
	cl[d]=merge(cl[a],cl[b],l,mid);
	cr[d]=merge(cr[a],cr[b],mid+1,r);
	rep(i,0,1)mi[d][i]=min(mi[cl[d]][i],mi[cr[d]][i]);
	return d;
}
void dfs(int x){
	for(int u=head[x];u;u=np[u])if(p[u]^fa[x]){
		fa[p[u]]=x;dep[p[u]]=dep[x]+1;dfs(p[u]);
		seg[x]=merge(seg[x],seg[p[u]],0,100000);
	}
	if(key[x]>=0){
		insert(seg[x],0,100000,key[x],dep[x]);
	}
}
int ask(int k,int me,int l,int r,int x,int y){
	if((x>y)||(!me))return 1000000000;
	if(x<=l&&r<=y)return mi[me][k];
	int ret=1000000000;
	int mid=(l+r)>>1;
	if(x<=mid){
		int D=ask(k,cl[me],l,mid,x,y);
		if(D<ret)ret=D;
	}
	if(y>mid){
		int D=ask(k,cr[me],mid+1,r,x,y);
		if(D<ret)ret=D;
	}
	return ret;
}
void work(int x,int fav){
	//printf("%d %d\n",x,fav);
	if(key[x]>=0){
		fav=key[x];
		for(int u=head[x];u;u=np[u])if(p[u]^fa[x])work(p[u],fav);
		return;
	}
	//1
	bool flag=1;
	fav++;
	int dj=ask(1,seg[x],0,100000,0,fav);
	if(dj<dep[x]+fav)flag=0;
	//printf("__+ %d\n",dj);
	dj=ask(0,seg[x],0,100000,fav,100000);
	//printf("__+ %d\n",dj);
	if(dj<dep[x]-fav)flag=0;
	if(flag){
		key[x]=fav;
		for(int u=head[x];u;u=np[u])if(p[u]^fa[x])work(p[u],fav);
		return;
	}
	//-1
	fav-=2;
	flag=1;
	dj=ask(1,seg[x],0,100000,0,fav);
	if(dj<dep[x]+fav)flag=0;
	//printf("__- %d\n",dj);
	dj=ask(0,seg[x],0,100000,fav,100000);
	if(dj<dep[x]-fav)flag=0;
	//printf("__- %d\n",dj);
	if(flag){
		key[x]=fav;
		for(int u=head[x];u;u=np[u])if(p[u]^fa[x])work(p[u],fav);
		return;
	}
}
