int root;

void dfs(int u, int p = -1, int depth = 0) {
	d[u] = depth;
	if(yes[u]) {
		mn[u] = color[u] + d[u];
		mx[u] = color[u] - d[u];
		if((color[u] + depth) % 2 != color[root] % 2)
			ok = false;
	}
	int mxx = -INF, mnn = INF;
	for(int v:G[u]) if(v != p ){
		dfs(v, u, depth + 1);
		mnn = min(mnn, mn[v]);
		mxx = max(mxx, mx[v]);
	}
	if(mxx > mnn - 2 * d[u]) ok = false;
	if(yes[u]) {
		if(mxx > mx[u]) ok = false;
		if(mnn < mn[u]) ok = false;
	}
	mx[u] = max(mx[u], mxx);
	mn[u] = min(mn[u], mnn);
}

bool can(int u, int val, int p) {
	if(yes[u]) return val == color[u];
	int mymn = val + d[u];
	int mymx = val - d[u];
	int mxx = -INF, mnn = INF;
	for(int v:G[u]) if(v != p){
		mnn = min(mnn, mn[v]);
		mxx = max(mxx, mx[v]);
	}
	if(mxx > mymx) return false;
	if(mnn < mymn) return false;
	return true;
}

void dfs1(int u, int p = -1) {
	for(int v:G[u]) if(v != p) {
		if(can(v, color[u]+1, u)) {
			color[v] = color[u] + 1;
		} else{
			color[v] = color[u] - 1;
		}
		dfs1(v, u);
	}
}

