const int maxn = 500010, inf = 1e9 + 233;
struct edge{int too, pre;}e[maxn << 1];
int n, x, y, tot, root, m;
int dep[maxn], mn[maxn][2], a[maxn], last[maxn];

inline void add(int x, int y) {e[++tot] = (edge){y, last[x]}; last[x] = tot;}

void dfs(int x, int fa)
{
	if (a[x] && ((a[x] - dep[x] + n) % 2 != (a[root] - dep[root] + n) % 2))
		puts("No"), exit(0);
	mn[x][0] = mn[x][1] = inf;
	for (int i = last[x], too; i; i = e[i].pre)
		if ((too = e[i].too) != fa)
		{
			dep[too] = dep[x] + 1;
			dfs(too, x);
			mn[x][0] = min(mn[x][0], mn[too][0]);
			mn[x][1] = min(mn[x][1], mn[too][1]);
		}

	if (a[x]) mn[x][0] = min(mn[x][0], a[x] + dep[x]), mn[x][1] = min(mn[x][1], dep[x] - a[x]);

	if (mn[x][0] + mn[x][1] < 2 * dep[x]) puts("No"), exit(0);
}

inline bool check(int x, int delta)
{
	return (mn[x][0] + dep[x] - delta >= 2 * dep[x]) && (mn[x][1] + dep[x] + delta >= 2 * dep[x]);
}

void work(int x, int fa, int pre)
{
	if (!a[x])
	{
		if (check(x, pre + 1)) a[x] = pre + 1;
		else a[x] = pre - 1;
	}

	for (int i = last[x], too; i; i = e[i].pre)
		if ((too = e[i].too) != fa)
			work(too, x, a[x]);
}

int main()
{
	scanf("%d", &n);
	for (int i = 1; i < n; i++)
		scanf("%d%d", &x, &y), add(x, y), add(y, x);

	scanf("%d", &m);
	for (int i = 1; i <= m; i++)
	{
		scanf("%d%d", &x, &y);
		a[x] = y;
	}
	root = x;

	dfs(root, 0);

	work(root, 0, 0);

	puts("Yes");
	for (int i = 1; i <= n; i++)
		printf("%d\n", a[i]);
}

