pii dfs(int x, int fa) {
	if (a[x] != -1 && abs(a[x] - a[root]) % 2 != dep[x] % 2) {
		return pii(0, -1);
	}

	int l = -inf, r = inf;

	if (a[x] != -1) l = r = a[x];

	for (int v : e[x]) if (v != fa) {
		dep[v] = dep[x] + 1;
