	if (a[x] == -1) {
		if (f[x].fi <= t - 1 && t - 1 <= f[x].se) a[x] = t - 1;
		else a[x] = t + 1;
	}
	for (int v : e[x]) if (v != fa) dfs1(v, x, a[x]);
}

