	vector<pii> cost;
	rep(i,K) {
		int v, p;
		cin >> v >> p;
		v--;
		cost.push_back(pii(v,p));
		V[v].rn = pii(p,p);
		V[v].orig = true;
	}

	bool ok = true;
	rep(i,cost.size()) {
		rep(j,E[cost[i].fi].size()) {
			int v;
			v = E[cost[i].fi][j];
			if(!vis[v]) {
				pii tmp;
				tmp = dfs(v,i, !(cost[i].se % 2));
				if(tmp.fi > tmp.se) {
					ok = false;
				}
				else {
					if(!solve(v,cost[i].fi)) {
						ok = false;
					}
				}
			}
		}
	}
	if(ok) {
		cout << "Yes" << endl;
		rep(i,N) {
			cout << V[i].rn.fi << endl;
		}
	}
	else {
		cout << "No" << endl;
	}

	return 0;
}

