void dfs(int v, int p, int d) {
	for (int u : E[v]) {
		if (u == p)continue;
		dfs(u, v, d ^ 1);
		a[v] = max(a[v], a[u] - 1);
		b[v] = min(b[v], b[u] + 1);
	}
	if (a[v] % 2 != d)a[v]++;
	if (b[v] % 2 != d)b[v]--;
	if (a[v] > b[v]) {
		puts("No"); exit(0);
	}
}
void dfs2(int v, int p) {
	for (int u : E[v]) {
		if (u == p)continue;
		if (a[u] <= ans[v] + 1 && ans[v] + 1 <= b[u]) {
			ans[u] = ans[v] + 1; dfs2(u, v);
		}
		else {
			ans[u] = ans[v] - 1; dfs2(u, v);
		}
	}
}
