const int MN=100000+5;
using namespace std;
typedef long long ll;
template<typename T>T&IN(T&in){
	in=0;char c=getchar();int f=1;
	while(!isdigit(c)){if(c=='-')f=-1;c=getchar();}
	while(isdigit(c))in=in*10+c-'0',c=getchar();
	in*=f;return in;
}
int n,k;
int nxt[MN*2],to[MN*2],h[MN],cnt;
int rt,a[MN],f[MN],L[MN],R[MN];
void add(int u,int v){to[cnt]=v,nxt[cnt]=h[u],h[u]=cnt++;}
int dfs1(int u,int fa){
	if(a[u]!=-1)L[u]=R[u]=a[u];
	else L[u]=INT_MIN+100,R[u]=INT_MAX-100;
	for(int e=h[u],v=to[e];~e;e=nxt[e],v=to[e])if(v^fa){
		f[v]=f[u]^1;
		if(!dfs1(v,u))return 0;
		L[u]=max(L[u],L[v]-1),R[u]=min(R[u],R[v]+1);
	}
	return L[u]<=R[u];
}
int dfs2(int u,int fa){
	for(int e=h[u],v=to[e];~e;e=nxt[e],v=to[e])if(v^fa){
		L[v]=max(L[v],L[u]-1),R[v]=min(R[v],R[u]+1);
		if(!dfs2(v,u))return 0;
	}
	return L[u]<=R[u];
}
void input(){
	IN(n);memset(h,-1,sizeof h);memset(a,-1,sizeof a);
	for(int i=1,u,v;i<n;++i)IN(u),IN(v),add(u,v),add(v,u);
	IN(k);
	for(int i=1,x,y;i<=k;++i)IN(x),IN(y),a[rt=x]=y;
	f[rt]=a[rt]&1;
	if(!dfs1(rt,0))return puts("No"),void();
	if(!dfs2(rt,0))return puts("No"),void();
	for(int i=1;i<=n;++i){
		if(L[i]==R[i]&&(L[i]&1)!=f[i])return puts("No"),void();
		if((L[i]&1)==f[i])a[i]=L[i];
		else a[i]=L[i]+1;
	}
	puts("Yes");
	for(int i=1;i<=n;++i)printf("%d\n",a[i]);
}
