constexpr int inf = 1e9;

int main() {
    int n; cin >> n;
    vector<vector<int>> g(n);
    for(int i = 0; i < n - 1; ++i) {
        int a, b; cin >> a >> b;
        a--, b--;
        g[a].push_back(b);
        g[b].push_back(a);
    }
    int k, rt; cin >> k;
    vector<int> mini(n, -inf), maxi(n, inf);
    for(int i = 0; i < k; ++i) {
        cin >> rt;
        rt--;
        cin >> mini[rt];
        maxi[rt] = mini[rt];
    }

    function<void(int, int)> calc_range = [&] (int v, int p) {
        for(auto const to : g[v]) {
            if(to == p) continue;
            calc_range(to, v);
            mini[v] = max(mini[v], mini[to] - 1);
            maxi[v] = min(maxi[v], maxi[to] + 1);
        }
    };
    calc_range(rt, -1);
    vector<int> ans(n);
    function<bool(int, int, int)> solve = [&] (int v, int p, int prev_val) {
        int cur_val = inf;
        if(mini[v] <= prev_val + 1 && prev_val + 1 <= maxi[v]) {
            cur_val = prev_val + 1;
        }
        if(mini[v] <= prev_val - 1 && prev_val - 1 <= maxi[v]) {
            cur_val = prev_val - 1;
        }

        if(cur_val == inf) return false;
        ans[v] = cur_val;
        bool res = true;
        for(auto const to : g[v]) {
            if(to == p) continue;
            res &= solve(to, v, cur_val);
        }
        return res;
    };

    if(!solve(rt, -1, mini[rt] + 1)) {
        cout << "No" << endl;
    } else {
        cout << "Yes" << endl;
        for(auto const& v : ans) {
            cout << v << endl;
        }
    }
}

