vector<int> values;

using Interval = pair<int, int>;

Interval INVALID = Interval {-(1<<30), -(1<<30)};

Interval intersect(Interval A, Interval B) {
    int min_val = max(A.first, B.first);
    int max_val = min(A.second, B.second);

    if ((A.first & 1) != (B.first & 1))
        return INVALID;

    if (min_val > max_val) {
        return INVALID;
    }

    return Interval {min_val, max_val};
} 

bool in_interval(int x, Interval A) {
    if ((A.first & 1) != (x & 1))
        return false;
    return x >= A.first && x <= A.second; 
}

Interval dfs (int x, int p, Interval interval) {
    //debug() << "dfs: " << x << " " << p << " " << interval;
    if (values[x] != -1) {
        if (!in_interval(values[x], interval)) {
            return INVALID;
        }
        interval = Interval{values[x], values[x]};
    }

    auto old_interval = interval;    
    //debug() << "boom: " << interval << " : " << g[x];
    for (auto v : g[x]) {
        if (v != p) {
            //debug() << "go: " << v;
            auto cur = dfs(v, x, Interval{old_interval.first - 1, old_interval.second + 1});
            cur.first--;
            cur.second++;
            interval = intersect(interval, cur);
            if (interval == INVALID) {
                //debug() << "INVALID: " << v << " " << x << " " << cur << " " << interval;
                return INVALID;
            }
        } 
    }

    if (values[x] == -1) {
        values[x] = interval.first;
    }

    return interval;
}

