#include<bits/stdc++.h>
using namespace std;

using P=pair<int,int>;
using Graph=vector<vector<int>>;
const int SIZE=100010;
const int INF=1e9;

int N;
Graph G;
int num[SIZE],L[SIZE],R[SIZE];
bool ok=true;

void parity_check(int v,int p,int parity)
{
   if(num[v]>=0 and num[v]%2!=parity) ok=false;
   for(int u:G[v]) if(u!=p){
      parity_check(u,v,parity^1);
   }
}

P calc(int v,int p)
{
   if(num[v]>=0) L[v]=R[v]=num[v];
   for(int u:G[v]) if(u!=p){
      P child=calc(u,v);
      L[v]=max(L[v],child.first-1);
      R[v]=min(R[v],child.second+1);
   }
   if(L[v]>R[v]) ok=false;
   return make_pair(L[v],R[v]);
}

void write(int v,int p)
{
   for(int u:G[v]) if(u!=p){
      if(L[u]<=num[v]-1 and num[v]-1<=R[u]) num[u]=num[v]-1;
      else num[u]=num[v]+1;
      write(u,v);
   }
}

int main()
{
   cin>>N;
   G.resize(N);
   for(int i=0;i<N-1;i++){
      int a,b; cin>>a>>b;
      a--; b--;
      G[a].push_back(b);
      G[b].push_back(a);
   }

   int K; cin>>K;
   for(int i=0;i<N;i++) num[i]=-1;
   for(int i=0;i<K;i++){
      int v,p; cin>>v>>p;
      num[v-1]=p;
   }

   int root=-1;
   for(int i=0;i<N;i++) if(num[i]>=0) root=i;

   parity_check(root,-1,num[root]%2);
   if(!ok){
      cout<<"No"<<endl; return 0;
   }

   for(int i=0;i<N;i++) L[i]=-INF,R[i]=INF;
   calc(root,-1);
   if(!ok){
      cout<<"No"<<endl; return 0;
   }
   write(root,-1);
   cout<<"Yes"<<endl;
   for(int i=0;i<N;i++) cout<<num[i]<<endl;
   return 0;
}

