		aa[v] = p;
		if( i == 1 ) root = v;
	}
	for( int i = 1; i <= n; i++ ) {
		dp[i][0] = dp[i][1] = oo;
	}
	dep[root] = 1;
	dfs( root, root, aa[root] & 1 );
	dfs2( root, root );
	for( int u = 1; u <= n; u++ ) {
		for( int t = 0; t < (int)g[u].size(); t++ ) {
