const int MAX_N = 128000;

int P[MAX_N];
int l[MAX_N], r[MAX_N], res[MAX_N];
vector<int> graph[MAX_N], g[MAX_N];
bool visited[MAX_N];

void make_graph(int v) {
  visited[v] = true;
  for (int i: graph[v]) {
    if (visited[i]) continue;
    g[v].push_back(i);
    make_graph(i);
  }
}

bool dfs(int v) {
  for (int i: g[v]) {
    if (!dfs(i)) return false;
  }
  l[v] = -1e9; r[v] = 1e9;
  for (int i: g[v]) {
    chmax(l[v], l[i] - 1);
    chmin(r[v], r[i] + 1);
  }
  for (int i: g[v]) {
    if (l[i] > -1e8 && (l[v] + l[i]) % 2 == 0) return false;
  }
  if (l[v] > r[v]) return false;
  if (P[v] >= 0) {
    if (l[v] > -1e8 && (l[v] + P[v]) % 2 == 1) return false;
    if (P[v] < l[v] || P[v] > r[v]) return false;
    l[v] = P[v];
    r[v] = P[v];
  }
  // cout << v << " " << l[v] << " " << r[v] << endl;
  return true;
}

void dfs2(int v, int val) {
  res[v] = val;
  for (int i: g[v]) {
    if (val + 1 <= r[i]) dfs2(i, val + 1);
    else dfs2(v, val - 1);
  }
}

void solve() {
  int N, K;
  cin >> N;
  REP(i,N-1) {
    int A, B;
    cin >> A >> B;
    graph[A-1].push_back(B-1);
    graph[B-1].push_back(A-1);
  }
  memset(P, -1, sizeof(P));
  cin >> K;
  REP(i,K) {
    int V, C;
    cin >> V >> C;
    P[V-1] = C;
  }
  make_graph(0);
  if (!dfs(0)) { cout << false << endl; return; }
  dfs2(0, l[0]);
  cout << true << endl;
  REP(i,N) cout << res[i] << endl;
  return;
}

#include <bits/stdc++.h>

using namespace std;
typedef long long ll;

const int MAXN = 100005;

int n, m;
vector<int> g[MAXN];

bool hv[MAXN];
int val[MAXN], d[MAXN];
int fa[MAXN], rt;

void input()
{
	scanf("%d", &n);
	for(int i = 1; i < n; i++)
	{
		int x, y;
		scanf("%d%d", &x, &y);
		g[x].push_back(y);
		g[y].push_back(x);
	}
	scanf("%d", &m);
	for(int i = 1; i <= m; i++)
	{
		int x, v;
		scanf("%d%d", &x, &v);
		hv[x] = 1;
		val[x] = v;
		if(!rt) rt = x;
	}
}

bool dfs(int x, int p, int ls)
{
	d[x] = d[p] + 1;
	fa[x] = ls;
	if(hv[x])
	{
		if(hv[ls])
		{
			int dv = abs(val[ls] - val[x]);
			int dis = d[x] - d[ls];
			if(dv > dis || ((dv + dis) & 1))
				return false;
		}
		ls = x;
	}
	for(auto y: g[x])
	{
		if(y == p) continue;
		if(!dfs(y, x, ls))
			return false;
	}
	return true;
}

int color(int x, int p)
{
	for(auto y: g[x])
	{
		if(y == p) continue;
		int t = color(y, x);
		if(t == 0) return 0;
		if(!hv[y]) continue;
		if(!hv[x]) val[x] = val[y] + t, hv[x] = 1;
		else if(val[x] != val[y] + t)
			return 0;
	}
	if(fa[x] && val[fa[x]] < val[x])
		return -1;
	else
		return 1;
}

bool ok;

void fix()
{
	queue<int> q;
	for(int i = 1; i <= n; i++)
	{
		if(hv[i])
		{
			for(auto j: g[i])
			{
				if(!hv[j])
				{
					hv[j] = 1;
					val[j] = val[i] - 1;
					q.push(j);
				}
			}
		}
	}
	while(!q.empty())
	{
		int x = q.front();
		q.pop();
		for(auto y: g[x])
			if(!hv[y])
			{
				hv[y] = 1;
				val[y] = val[x] - 1;
				q.push(y);
			}
	}
}

void solve()
{
	if(dfs(rt, 0, 0) && color(rt, 0))
	{
		ok = 1;
		fix();
	}
}

void output()
{
	if(ok)
	{
		puts("YES");
		for(int i = 1; i <= n; i++)
			printf("%d\n", val[i]);
	}
	else puts("NO");
}

int main()
{
	input();
	solve();
	output();

	return 0;
}

