const int N=100010;
int tt;
bool w[N];
int head[N],to[N*2],nxt[N*2],L[N],R[N],a[N];
inline int gi() {
    int x=0,o=1;
    char ch=getchar();
    while(ch!='-'&&(ch<'0'||ch>'9')) ch=getchar();
    if(ch=='-') o=-1,ch=getchar();
    while(ch>='0'&&ch<='9') x=x*10+ch-'0',ch=getchar();
    return x*o;
}
inline void dfs(int x,int fa) {
    if(w[x]) L[x]=R[x]=a[x];
    else L[x]=-1e6,R[x]=1e6;
    for(int i=head[x];i;i=nxt[i]) {
	int y=to[i];
	if(y!=fa) {
	    dfs(y,x);
	    if(R[y]<5e5&&R[x]<5e5&&(L[y]%2==L[x]%2||R[y]+1<L[x]||R[x]<L[y]-1))
		puts("NO"),exit(0);
	    L[x]=max(L[x],L[y]-1),R[x]=min(R[x],R[y]+1);
	}
    }
}
inline void solve(int x,int fa) {
    for(int i=head[x];i;i=nxt[i]) {
	int y=to[i];
	if(y!=fa) {
	    if(a[x]-1>=L[y]) a[y]=a[x]-1;
	    else a[y]=a[x]+1;
	    solve(y,x);
	}
    }
}
int main() {
    int n,k;
    cin>>n;
    for(int i=1;i<n;i++) {
	int x=gi(),y=gi();
	to[++tt]=y,nxt[tt]=head[x],head[x]=tt;
	to[++tt]=x,nxt[tt]=head[y],head[y]=tt;
    }
    cin>>k;
    while(k--) {
	int x=gi(),y=gi();
	w[x]=1,a[x]=y;
    }
    dfs(1,0);
    a[1]=L[1],solve(1,0);
    puts("YES");
    for(int i=1;i<=n;i++) printf("%d\n",a[i]);
    return 0;
}

