#define MAX_V 100000

vector<int> G[MAX_V];

pii mr(pii a,pii b){
	if(a.first%2!=b.first%2)return pii(1,-1);



	if(a.first<b.first&&b.second<a.second){
		return b;
	}else if(b.first<a.first&&a.second<b.second){
		return a;
	}else if(a.second<b.first || b.second<a.first){
		return pii(1,-1);
	}else if(a.first<=b.first){
		return pii(b.first,a.second);
	}else if(b.first<=a.first){
		return pii(a.first,b.second);
	}else{
		assert(0);
		return pii(1,-1);
	}
}

vector<pii> cand;
void dfs(int cur,vector<int> &ans){
	if(cand[cur].first-cand[cur].second==0)ans[cur] = cand[cur].first;
	else{
		pii t = cand[cur];
		for(auto &e:G[cur]){
			if(ans[e]==-1)continue;
			t = mr(t,pii(ans[e]-1,ans[e]+1));
		}

		ans[cur] = t.first;
	}
	for(auto &e:G[cur]){
		if(ans[e]==-1){
			dfs(e,ans);
		}
	}
}


