#include <iostream>
#include <vector>
using namespace std;

int N,K,inf = 2e9;
int A[100010],B[100010],even[100010] = {0},visited[100010] = {0},ans[100010];
vector<vector<int>> v(100010);
bool judge = true;


void dfs1(int n,int mod){
	visited[n] = 1;
	even[n] = mod;
	if(A[n]!=-inf && A[n]%2!=mod) judge = false;
	for(int i=0;i<v[n].size();i++){
		int s = v[n][i];
		if(visited[s]==0){
			dfs1(s,1-mod);
		} 
	}
}

void dfs2(int n){
	visited[n] = 1;
	int ma = inf,mi = -inf;
	for(int i=0;i<v[n].size();i++){
		int s = v[n][i];
		if(visited[s]==0){
			int s = v[n][i];
			dfs2(s);
			mi = max(A[s]-1,mi);
			ma = min(B[s]+1,ma);
			if(ma<mi) judge = false;
		}
	}
	if(ma!=inf){
		B[n] = ma;
		A[n] = mi;
	}
}

void write(int n,int t){
	visited[n] = 1;
	if(A[n]==-inf) ans[n] = t+1;
	else if(t<A[n]) ans[n] = A[n];
	else if(t>B[n]) ans[n] = B[n];
	else{
		if(A[n]%2==even[n]) ans[n] = A[n];
		else ans[n] = A[n]+1;
	}
	for(int i=0;i<v[n].size();i++){
		int s = v[n][i];
		if(visited[s]==0){
			write(s,ans[n]);
		}
	}
}

int main(){
	cin >> N;
	for(int i=1;i<=N;i++){
		A[i] = -inf;
		B[i] = inf;
		even[i] = -1;
	}
	int a,b;
	for(int i=0;i<N-1;i++){
		cin >> a >> b;
		v[a].push_back(b);
		v[b].push_back(a);
	}
	cin >> K;
	for(int i=0;i<K;i++){
		cin >> a >> b;
		A[a] = b;
		B[a] = b;
		even[a] = b%2;
	}
	dfs1(a,even[a]);
	if(!judge){
		cout << "No" << endl;
		return 0;
	}
	for(int i=1;i<=N;i++) visited[i] = 0;
	dfs2(1);
	if(!judge) cout << "No" << endl;
	else{
		for(int i=1;i<=N;i++) visited[i] = 0;
		if(A[1]==-inf){
			ans[1] = even[1];
			write(1,even[1]);
		}
		else if(A[1]%2==even[1]){
			ans[1] = A[1];
			write(1,A[1]);
		}
		else if(A[1]%2!=even[1]){
			ans[1] = A[1]+1;
			write(1,A[1]+1);
		}
		cout << "Yes" << endl;
		for(int i=1;i<=N;i++){
			cout << ans[i] << endl;
		}
	}
}

#include"bits/stdc++.h"
using namespace std;
using ll = int64_t;

vector<vector<ll>> edges;
vector<ll> value;
vector<pair<ll, ll>> conds;
bool flag;

pair<ll, ll> solve(ll curr, ll pre) {
    pair<ll, ll> cond{ INT_MIN, INT_MAX };
    if (value[curr] != -1) {
        cond.first = cond.second = value[curr];
    }
    for (ll i = 0; i < edges[curr].size(); i++) {
        ll next = edges[curr][i];
        if (next == pre) {
            continue;
        }
        auto next_cond = solve(next, curr);
        cond.first = max(cond.first, next_cond.first);
        cond.second = min(cond.second, next_cond.second);
        if (cond.first > cond.second) {
            flag = false;
            return { INT_MAX, INT_MIN };
        }
    }
    conds[curr] = cond;
    return { cond.first - 1, cond.second + 1 };
}

void write(ll curr, ll pre) {
    if (pre != -1) {
        if (conds[curr].first <= value[pre] + 1 && value[pre] + 1 <= conds[curr].second) {
            value[curr] = value[pre] + 1;
        } else {
            value[curr] = value[pre] - 1;
        }
    }

    for (ll next : edges[curr]) {
        if (next == pre) {
            continue;
        }
        write(next, curr);
    }
}

int main() {
    ll N;
    cin >> N;
    value.resize(N, -1);
    conds.resize(N);
    edges.resize(N);
    for (ll i = 0; i < N - 1; i++) {
        ll A, B;
        cin >> A >> B;
        A--; B--;
        edges[A].push_back(B);
        edges[B].push_back(A);
    }

    ll K;
    cin >> K;
    vector<ll> V(K), P(K);
    for (ll i = 0; i < K; i++) {
        cin >> V[i] >> P[i];
        V[i]--;
        value[V[i]] = P[i];
    }

    flag = true;
    solve(V[0], -1);

    if (!flag) {
        cout << "No" << endl;
    } else {
        cout << "Yes" << endl;
        write(V[0], -1);
        for (ll i = 0; i < N; i++) {
            cout << value[i] << endl;
        }
    }
}

#include <algorithm>
#include <cstdio>

const int N=100005;

int L[N],R[N],v[N],fst[N],tot,rt;
bool flag=1;
struct Edge{
	int to,nxt;
}e[N*2];

void addedge(int x,int y){
	e[++tot].to=y;e[tot].nxt=fst[x];fst[x]=tot;
}

void dfs(int x,int father){
	for (int i=fst[x];i && flag;i=e[i].nxt){
		int y=e[i].to;
		if (y!=father){
			dfs(y,x);
			L[x]=std::max(L[x],L[y]-1);
			R[x]=std::min(R[x],R[y]+1);
			if (L[x]>R[x]) flag=0;
		}
	}
}

void dfs2(int x,int father){
	if (L[x]>R[x]) flag=0;
	v[x]=L[x];
	for (int i=fst[x];i && flag;i=e[i].nxt){
		int y=e[i].to;
		if (y!=father){
			L[y]=std::max(L[y],v[x]-1);
			R[y]=std::min(R[y],v[x]+1);
			dfs2(y,x);
		}
	}
}

int main(){
	int n,k;
	scanf("%d\n",&n);
	for (int i=1;i<n;i++){
		int x,y;
		scanf("%d%d",&x,&y);
		addedge(x,y);
		addedge(y,x);
	}
	for (int i=1;i<=n;i++) L[i]=-(R[i]=100000000);
	scanf("%d\n",&k);
	for (int i=1;i<=k;i++){
		int x,y;
		scanf("%d%d",&x,&y);
		L[rt=x]=R[x]=y;
	}
	dfs(rt,0);
	v[rt]=L[rt];
	dfs2(rt,0);
	if (flag){
		printf("Yes\n");
		for (int i=1;i<=n;i++) printf("%d\n",v[i]);
	}
	else printf("No\n");
}

