struct ST{
  int i;
  int v;
};
bool operator<(const ST& a, const ST& b){
  return a.v < b.v;
}

void dfs_mx(int i, int v){
  if(mx[i] <= v) return;
  mx[i] = v;
  rep(j,G[i].size()){
    dfs_mx(G[i][j], v+1);
  }
}
void dfs_mn(int i, int v){
  if(mn[i] >= v) return;
  mn[i] = v;
  rep(j,G[i].size()){
    dfs_mn(G[i][j], v-1);
  }
}

int main(){
