  }

  vector<ST> v;
  rep(i,K){
    int V, P;
    cin >> V >> P;
    V--;
    val[V] = P;
    v.push_back((ST){V,P});
  }

  sort(ALLOF(v));
  rep(i,v.size()){
    dfs_mx(v[i].i, v[i].v);
  }
  for(int i=v.size()-1; i>=0; i--){
    dfs_mn(v[i].i, v[i].v);    
  }


  rep(i,N){
    if(mn[i] > mx[i]){
      cout << "No" << endl;
      return 0;
    }
  }
  cout << "Yes" << endl;
  rep(i,N){
    cout << mn[i] << endl;
  }


  return 0;
}

