vector<vector<int> > s;
vector<char> any;

int n;
vector<vector<int> > g;
vector<int> val;

void dfs(int v, int p)
{
	if (sz(g[v]) == 1 && g[v][0] == p) {
		if (val[v] == -1) {
			any[v] = true;
		} else {
			any[v] = false;
			s[v] = {val[v]};
		}
		return;
	}
	vector<int> sons;
	for (int to : g[v]) {
		if (to != p) {
			dfs(to, v);
			if (!any[to]) {
				sons.pb(to);
			}
		}
	}
	if (sons.empty()) {
		if (val[v] == -1) {
			any[v] = true;
		} else {
			any[v] = false;
			s[v] = {val[v]};
		}
		return;
	}
	any[v] = false;
	vector<int> ptr(sz(sons));
	for (int x : s[sons[0]]) {
		if (val[v] != -1 && abs(val[v] - x) != 1) {
			continue;
		}
		bool can_1 = true;
		bool can1 = true;
		for (int i = 1; i < sz(sons); ++i) {
			int son = sons[i];
			bool a = false, b = false, c = false;
			while (ptr[i] + 1 < sz(s[son]) && s[son][ptr[i]] < x - 2) {
				++ptr[i];
			}
			int curr = ptr[i];
			for (int t = 0; t < 5; ++t) {
				if (curr >= sz(s[son])) {
					break;
				}
				if (s[son][curr] == x - 2) {
					c = true;
				}
				if (s[son][curr] == x) {
					b = true;
				}
				if (s[son][curr] == x + 2) {
					a = true;
				}
				++curr;
			}
			if (!a && !b) {
				can1 = false;
			}
			if (!b && !c) {
				can_1 = false;
			}
		}
		if (can_1 && (val[v] == -1 || val[v] == x - 1)) {
			s[v].pb(x - 1);
		}
		if (can1 && (val[v] == -1 || val[v] == x + 1)) {
			s[v].pb(x + 1);
		}
	}
	sort(all(s[v]));
	s[v].resize(unique(all(s[v])) - s[v].begin());
}

vector<int> ans;

void dfs_solve(int v, int p, int x)
{
	ans[v] = x;
	for (int to : g[v]) {
		if (to != p) {
			int pos = -1;
			for (int j = 0; j < sz(s[to]); ++j) {
				if (s[to][j] == x - 1) {
					pos = j;
				}
			}
			if (any[to] || pos != -1) {
				dfs_solve(to, v, x - 1);
			} else {
				dfs_solve(to, v, x + 1);
			}
		}
	}
}

