using namespace std;
const int maxn=1e6;
const int N=1e5+10;
const int inf=1e9;
int n;
struct edge{int to,Next;}ed[N<<1];
int edcnt,head[N];
void addedge(int u,int v){ed[++edcnt]=(edge){v,head[u]};head[u]=edcnt;}
int le[N],ri[N];
void dfslr(int u,int Fa)
{
	for(int i=head[u];i;i=ed[i].Next)
	if(ed[i].to!=Fa)
	{
		int v=ed[i].to;
		le[v]=max(le[v],le[u]-1);
		ri[v]=min(ri[v],ri[u]+1);
		dfslr(v,u);
	}
	if(Fa)
	{
		le[Fa]=max(le[Fa],le[u]-1);
		ri[Fa]=min(ri[Fa],ri[u]+1);
	}
}
int ans[N];bool used[maxn*2];
bool dfsans(int u,int Fa)
{
	for(int i=head[u];i;i=ed[i].Next)
	if(le[ed[i].to]==ri[ed[i].to]) used[le[ed[i].to]+maxn]=true;
	int l=le[u];
	while(l<=ri[u]&&used[l+maxn]) l++;
	if(l>ri[u]) return false;
	le[u]=ri[u]=ans[u]=l;
	for(int i=head[u];i;i=ed[i].Next)
	if(le[ed[i].to]==ri[ed[i].to]) used[le[ed[i].to]+maxn]=false;
	for(int i=head[u];i;i=ed[i].Next)
	if(ed[i].to!=Fa)
	{
		int v=ed[i].to;
		le[v]=max(le[v],le[u]-1);
		ri[v]=min(ri[v],ri[u]+1);
		if(!dfsans(v,u)) return false;
	}
	return true;
}
int main()
{
	scanf("%d",&n);
	for(int i=1;i<n;i++)
	{
		int u,v;scanf("%d%d",&u,&v);
		addedge(u,v);addedge(v,u);
	}
	for(int i=1;i<=n;i++)
	{
		le[i]=-maxn;
		ri[i]=maxn;
	}
	int K;scanf("%d",&K);
	for(int i=1;i<=K;i++)
	{
		int Id,Val;scanf("%d%d",&Id,&Val);
		le[Id]=ri[Id]=Val;
	}
	dfslr(1,0);dfslr(1,0);
	bool flag=true;
	for(int i=1;i<=n;i++)
	if(le[i]>ri[i])
	{
		flag=false;
		break;
	}
