vector<array<int, 2>>bound;

array<int, 2>dfs1(int pos, int lb, int ub, int prevpos) {
	int nextlb, nextub;
	if (bound[pos][0] == -1) {
		nextlb = lb - 1;
		nextub = ub + 1;
	}
	else {
		int fixnum = bound[pos][0];
		if (fixnum < lb || ub < fixnum || (fixnum - lb) % 2 != 0) {
			return{ -2,-2 };
		}
		lb = fixnum;
		ub = fixnum;
		nextlb = fixnum-1;
		nextub = fixnum+1;
	}

	for (auto x : g[pos])if (x != prevpos) {
		auto re = dfs1(x, nextlb, nextub, pos);
		if (re[0] == -2)return{ -2,-2 };
		lb = max(lb, re[0]);
		ub = min(ub, re[1]);
	}
	assert(lb <= ub);
	bound[pos] = { lb,ub };
	return{ lb - 1,ub + 1 };
}



