#include<bits/stdc++.h>
using namespace std;
const int maxn=100005;

int h[maxn],mem;
struct
{
    int v,next;
}e[maxn<<1];
int num[maxn];
void add(int u,int v)
{
    e[mem].v=v;
    e[mem].next=h[u];
    h[u]=mem++;
}
bool can;
int deep[maxn];
int mi[maxn],mx[maxn];
void dfs(int u,int f)
{
    if(num[u]){
        mx[u]=mi[u]=num[u];
    }
    else{
        mx[u]=1000000000;
        mi[u]=-1000000000;
    }

    if(num[u]&&abs(num[u]-deep[u])&1){
        //printf("%d %d %d uuuu\n",num[u],deep[u],u);
        can=0;return ;
    }
    for(int i=h[u];i+1;i=e[i].next)
    {
        int v=e[i].v;
        if(v==f) continue;
        deep[v]=deep[u]+1;
        dfs(v,u);
        if(!can) return ;
        mi[v]--;
        mx[v]++;
        mi[u]=max(mi[u],mi[v]);
        mx[u]=min(mx[u],mx[v]);
    }
    if(mx[u]<mi[u]){
        //printf("%d %d %d\n",u,mx[u],mi[u]);
        can=0;
    }
}
void dfsnum(int u,int f)
{
    for(int i=h[u];i+1;i=e[i].next)
    {
        int v=e[i].v;
        if(v==f) continue;
        if(num[u]-1>=mi[v]){
            num[v]=num[u]-1;
        }
        else{
            num[v]=num[u]+1;
        }
        dfsnum(v,u);
    }
}
int main()
{
    int n;
    scanf("%d",&n);
    memset(h,-1,sizeof(h));mem=0;
    memset(num,0,sizeof(num));
    for(int i=1;i<n;i++)
    {
        int x,y;
        scanf("%d%d",&x,&y);
        add(x,y);
        add(y,x);
    }
    int k;
    scanf("%d",&k);
    int root;
    for(int i=1;i<=k;i++)
    {
        int v,p;
        scanf("%d%d",&v,&p);
        num[v]=p;
        root=v;
    }
    if(k==0){
        root=1;
        num[1]=1;
    }
    deep[root]=num[root];can=1;
    dfs(root,root);
    if(can==0){
        printf("No\n");return 0;
    }
    dfsnum(root,root);
    printf("Yes\n");
    for(int i=1;i<=n;i++)
        printf("%d\n",num[i]);
    return 0;
}

