#include<bits/stdc++.h>
using namespace std;
const int N = 1e5 + 11;
int L[N], R[N], n, mark[N], ans[N];
int head[N], nex[N<<1], to[N<<1], size;
void add(int u, int v){
    nex[++size] = head[u];
    to[size] = v;
    head[u] = size;
}
void dfs(int u, int fa){
    for(int i = head[u];i;i = nex[i]){
        int v = to[i];
        if(v == fa)continue;
        dfs(v, u);
        if(mark[v] == -1)continue;
        if(mark[u] == -1)mark[u] = mark[v] ^ 1;
        else{
            if((mark[v] ^ 1) != mark[u]){
                puts("No");
                exit(0);
            }
        }
        L[u] = max(L[u], L[v] - 1);
        R[u] = min(R[u], R[v] + 1);
    }
    if(L[u] > R[u]){
        puts("No");
        exit(0);
    }
    if(ans[u] != ans[0]){
        if(mark[u] == -1)mark[u] = ans[u] & 1;
        if(L[u] > ans[u] || R[u] < ans[u] || (ans[u] & 1) != mark[u]){
            puts("No");
            exit(0);
        }
        L[u] = R[u] = ans[u];
    }
}
void get(int u, int fa){
    //printf("u=%d ans[u]=%d ans0=%d\n", u, ans[u], ans[0]);
    if(ans[u] == ans[0]){
        if(ans[fa] + 1 >= L[u] && ans[fa] + 1 <= R[u])ans[u] = ans[fa] + 1;
        else if(ans[fa] - 1 >= L[u] && ans[fa] - 1 <= R[u]) ans[u] = ans[fa] - 1;
        else {
            puts("No"); exit(0);
        }
        //printf("u=%d ans=%d\n", u, ans[u]);
    }
    //puts("XBX");
    for(int i = head[u];i;i = nex[i]){
        int v = to[i];
        //printf("u=%d v=%d fa=%d\n", u, v, fa);
        if(v == fa)continue;
        get(v, u);
    }
}
int main(){
    cin>>n;
    int u, v;
    for(int i = 1;i < n; i++){
        scanf("%d%d", &u, &v);
        add(u, v); add(v, u);
    }
    int k;
    scanf("%d", &k);
    memset(L, -127, sizeof(L));
    memset(R, 127, sizeof(R));
    memset(ans, -127, sizeof(ans));
    memset(mark, -1, sizeof(mark));
    for(int i = 1;i <= k; i++){
        scanf("%d", &u);
        scanf("%d", &ans[u]);
        mark[u] = ans[u] & 1;
    }
    dfs(u, u);
    get(u, u);
    puts("Yes");
    for(int i = 1;i <= n; i++){
        //printf("i=%d L=%d R=%d ans=%d mark=%d\n", i, L[i], R[i], ans[i], mark[i]);
        printf("%d\n", ans[i]);
    }
    return 0;
}

