void dfs(int x, int f) {
	for (int i = 0; i < (int)nxt[x].size(); ++i) if (nxt[x][i] ^ f) {
		dfs(nxt[x][i], x); l[x] = max(l[x], l[nxt[x][i]] - 1); r[x] = min(r[x], r[nxt[x][i]] + 1);
	} if (a[x] >= 0) l[x] = max(l[x], a[x]), r[x] = min(r[x], a[x]);
}

void gen(int x, int f) {
	for (int i = 0; i < (int)nxt[x].size(); ++i) if (nxt[x][i] ^ f) {
		int L = l[nxt[x][i]], R = r[nxt[x][i]];
		if (L <= a[x] - 1 && a[x] - 1 <= R) a[nxt[x][i]] = a[x] - 1; 
		else if (L <= a[x] + 1 && a[x] + 1 <= R) a[nxt[x][i]] = a[x] + 1;
		else throw;
		gen(nxt[x][i], x);
	}
}

