		if(!DFS(u, x, !po))
			return false;
		range[x].F=max(range[x].F, range[u].F-1);
		range[x].S=min(range[x].S, range[u].S+1);
		if(range[x].F>range[x].S) return false;
	}
	return true;
}

bool DFS2(int x,int p) {
	if(range[x].F>range[x].S) return false;
	for(int i=SZ(e[x])-1;i>=0;i--) {
		int u=e[x][i];
		if(u==p) continue;
		range[u].F=max(range[u].F, range[x].F-1);
		range[u].S=min(range[u].S, range[x].S+1);
		if(!DFS2(u, x))
			return false;
		range[x].F=max(range[x].F, range[u].F-1);
		range[x].S=min(range[x].S, range[u].S+1);
