bool possible = true;
void check(int n, int pre, int root,int d) {
	for (auto nxt : G[n]) {
		if (nxt == pre)continue;
		if (P[nxt] != -1) {
			if ((d ^ P[nxt]) & 1)possible = false;
		}
		check(nxt, n, root, d + 1);
	}
}

void dfs(int n, int pre) {
	int l = L[n], r = R[n];
	for (auto nxt : G[n]) {
		if (nxt == pre)continue;
		dfs(nxt, n);
		l = max(l, L[nxt]-1);
		r = min(r, R[nxt]+1);
	}
	L[n] = l, R[n] = r;
	if (L[n] > R[n])possible = false;
}

void decide(int n, int pre) {
	//print(n+1);
	for (auto nxt : G[n]) {
		if (nxt == pre)continue;
		if (ans[n] + 1 >= L[nxt] && ans[n] + 1 <= R[nxt]) {
			ans[nxt] = ans[n] + 1;
		}
		else if (ans[n] - 1 >= L[nxt] && ans[n] - 1 <= R[nxt]) {
			ans[nxt] = ans[n] - 1;
		}
		else {
			//pe(n + 1); print(nxt + 1);
			possible = false;
			return;
		}
		//cout << "->" << ans[n] << endl;
		decide(nxt, n);
	}
}

