		int u, v; cin >> u >> v;
		u--, v--;
		G[u].push_back(v); G[v].push_back(u);
	}
	cin >> K;
	int root = 0;
	REP(i, N)P[i] = -1;

	REP(i, K) {
		int v, p; cin >> v >> p;
		P[v - 1] = p;
		root = v - 1;
	}
	REP(i, N) {
		L[i] = -INF;
		R[i] = INF;
	}
	REP(i, N) {
		if (P[i] != -1) {
			L[i] = P[i];
			R[i] = P[i];
		}
	}
	check(root, root, root, 0);

	dfs(root, root);
	if (!possible) { print("No"); return; }
	/*REP(i, N) {
		pe(i + 1); pe(L[i]); print(R[i]);
	}*/
	ans[root] = P[root];
	decide(root, root);
	if (!possible) { print("No"); exit(1); }
	print("Yes");
	REP(i, N)print(ans[i]);
}


