int fir[N], ne[M], to[M], cnt = 1, L[N], R[N], K, x, y, n;
int Num[N];

void add(int x, int y) {
	ne[++ cnt] = fir[x];
	fir[x] = cnt;
	to[cnt] = y;
}

void link(int x, int y) {
	add(x, y);
	add(y, x);
}

#define Foreachson(i, x) for(int i = fir[x]; i; i = ne[i])

void dfs(int x, int f, int l, int r) {
	l = max(l, L[x]);
	r = min(r, R[x]);
	L[x] = l, R[x] = r;
	Foreachson(i, x) {
		int V = to[i];
		if(V == f) continue;
		dfs(V, x, l - 1, r + 1);
	}
}

void dfs2(int x, int f) {
	Foreachson(i, x) {
		int V = to[i];
		if(V == f) continue;
		dfs2(V, x);
		L[x] = max(L[x], L[V] - 1);
		R[x] = min(R[x], R[V] + 1);
	}
}

void getNum(int x, int f, int g) {
	Foreachson(i, x) {
		int V = to[i];
		if(V == f) continue;
		getNum(V, x, g ^ 1);
	}
	if(Num[x] != -1 && g != Num[x]) exit(0 * puts("No"));
}

