void Addedge(int fr,int to)
{
	edge[++cnt].to = to;
	edge[cnt].next = head[fr];
	head[fr] = cnt;
}
int p[100005];
bool vp[100005];
bool vi[100005];
int l[100005],r[100005];
bool DFS1(int now, int fa)
{
	for(int i = head[now]; i; i = edge[i].next)
	{
		if(edge[i].to != fa)
		{
			if(!DFS1(edge[i].to, now))
			{
				return 0;
			}
			if(vi[edge[i].to])
			{
				int ll = l[edge[i].to] - 1;
				int rr = r[edge[i].to] + 1;
				if(vi[now])
				{
					if(rr < l[now] || ll > r[now] ||((ll & 1) != (l[now] & 1)))
					{
						return 0;
					}
					l[now] = max(l[now], ll);
					r[now] = min(r[now], rr);
				}
				else
				{
					vi[now] = 1;
					l[now] = ll;
					r[now] = rr;
				}
			}
		}
	}
	if(vp[now])
	{
		if(vi[now] && (p[now] < l[now] || p[now] > r[now] || (p[now] & 1) != (l[now] & 1)))
		{
			return 0;
		}
		vi[now] = 1;
		l[now] = r[now] = p[now];
	}
	return 1;
}
void DFS2(int now, int fa)
{
	if(now == 1)
	{
		p[now] = l[now];
	}
	else
	{
		if(p[fa] - 1 >= l[now])
		{
			p[now] = p[fa] - 1;
		}
		else
		{
			p[now] = p[fa] + 1;
		}
	}
	for(int i = head[now]; i; i = edge[i].next)
	{
		if(edge[i].to != fa)
		{
			DFS2(edge[i].to, now);
		}
	}
}
