bool pality_check(int u, int p, int x){
    if(num[u] != -1 && num[u]%2 != x){
        return false;
    }

    for(auto &e : g[u]){
        int v = e.dst;
        if(v == p) continue;
        if(!pality_check(v, u, 1-x)){
            return false;
        }
    }

    return true;
}

int lb[100010], ub[100010];

void get_range(int u, int p){
    int mi = -INF;
    int ma = INF;
    for(auto &e : g[u]){
        int v = e.dst;
        if(v == p) continue;
        get_range(v, u);
        mi = max(mi, lb[v]);
        ma = min(ma, ub[v]);
    }

    --mi;
    ++ma;

    pair<int,int> res;
    if(mi > ma){
        lb[u] = +INF;
        ub[u] = -INF;
    } else {
        if(num[u] != -1){
            if(mi <= num[u] && num[u] <= ma){
                lb[u] = num[u];
                ub[u] = num[u];
            } else {
                lb[u] = +INF;
                ub[u] = -INF;
            }
        } else {
            lb[u] = mi;
            ub[u] = ma;
        }
    }
}

void paint(int u, int p, int pc){
    int c = lb[u] <= pc-1 && pc-1 <= ub[u] ? pc-1 : pc+1;
    num[u] = c;
    for(auto &e : g[u]){
        int v = e.dst;
        if(v == p) continue;
        paint(v, u, c);
    }
}

