void printans(int p, int val, int par=-1, int oe=-1) {
    if(oe < 0) oe = (val % 2);
    ans[p] = val;
    for(auto to : G[p]) {
        if(to == par) continue;
        int cur = val - 1;
        valid = false;
        for(int i=0; i<3; i++) {
            int nval = cur + i;
            if(oe != (nval % 2) && L[to] <= nval && nval <= R[to]) {
                valid = true;
                printans(to, nval, p, nval % 2);
                break;
            }
        }
        if(!valid) {
            cout << "No" << endl;
            exit(0);
        }
    }
}

