bool sub[maxn];
int L[maxn], R[maxn];
std::vector<int> G[maxn];
bool vp[maxn];
bool ans;

void getinterval(int a,int f)
{
	for(int i = 0; i < G[a].size(); i++)
		if(G[a][i] != f)
		{
			getinterval(G[a][i], a);

			if(sub[G[a][i]])
			{
				int l = L[G[a][i]] - 1;
				int r = R[G[a][i]] + 1;				

				if(sub[a])
				{
					if(r < L[a]) ans = false;
					if(l > R[a]) ans = false;

					if((l & 1) ^ (L[a] & 1)) ans = false;
				}
				else
				{
					L[a] = l;
					R[a] = r;
					sub[a] = true;
				}
			}
		}

	if(vp[a] == true)
	{
		if(sub[a] && (P[a] < L[a] || P[a] > R[a] || ((P[a] & 1) ^ (L[a] & 1)))) ans = false;

		L[a] = R[a] = P[a];
		sub[a] = true;
	}
}
void getvalue(int a,int f)
{
	if(a == 1)
	{
		P[a] = L[a];
	}
	else
	{
		if(P[f] - 1 >= L[a])
		{
			P[a] = P[f] - 1;
		}
		else
		{
			P[a] = P[f] + 1;
		}
	}

	for(int i = 0; i < G[a].size(); i++)
		if(G[a][i] != f)
		{
			getvalue(G[a][i], a);
		}
}
int main()
{
	scanf("%d", &N);
	for(int i = 1, x, y; i < N; i++)
	{
		scanf("%d%d", &x, &y);
		G[x].push_back(y);
		G[y].push_back(x);
	}

	scanf("%d", &K);
	for(int i = 1; i <= K; i++)
	{
		scanf("%d", &V[i]);
		scanf("%d", &P[V[i]]);
	}

	for(int i = 1; i <= K; i++)
	{
		vp[V[i]] = true;
	}

	ans = true;
	getinterval(1, 0);
	getvalue(1, 0);

	if(ans)
	{
		puts("Yes");

		for(int i = 1; i <= N; i++)
		{
			printf("%d\n", P[i]);
		}
	}
	else
	{
		puts("No");
	}
	return 0;
}

