inline void add(int x, int y)
{
	next[++t] = first[x]; first[x] = t; go[t] = y;
}
inline void dfs(int now, int las)
{
	if (ok) return;
	int L = l[now], R = r[now];
	for(int i = first[now]; i; i = next[i])
		if (go[i] != las)
		{
			int ll = l[go[i]] - 1, rr = r[go[i]] + 1;
			if (R < ll || L > rr) ok = 1;
			L = max(L, ll);
			R = min(R, rr);
		}
	l[now] = L; r[now] = R;
}
inline void getans(int now, int las, int w)
{
	a[now] = w;
	if (ok) return;
	for(int i = first[now]; i; i = next[i])
		if (go[i] != las)
		{
			if (w - 1 >= l[go[i]] && w - 1 <= r[go[i]]) getans(go[i], now, w - 1);
			else if (w + 1 >= l[go[i]] && w + 1 <= r[go[i]]) getans(go[i], now, w + 1);
