#define MAX 100010

bool visited[MAX] = {0};
vector<int> G[MAX];
int high[MAX], low[MAX], ans[MAX];

bool dfs(int i, int a) {
    if (low[i] > a || high[i] < a) return false;
    ans[i] = a;
    for (auto g:G[i]) {
        if (ans[g] >= 0) continue;
        bool minus = dfs(g, a-1);
        if (!minus && !dfs(g, a+1)) return false;
    }
    return true;
}

struct node {int v, p;};

int main() {
    int n;
    cin >> n;
    for (int i=0, a, b; i<n-1; i++) {
