        G[a].push_back(b);
        G[b].push_back(a);
    }
    int k;
    cin >> k;
    int v, p;
    queue<node> qh, ql;
    fill(high, high+n, 10000000);
    fill(low, low+n, -1);
    for (int i=0; i<k; i++) {
        cin >> v >> p;
        v--;
        high[v] = low[v] = p;
        qh.push(node{v, p});
        ql.push(node{v, p});
    }
    while (!qh.empty()) {
        node f = qh.front(); qh.pop();
        for (auto g:G[f.v]) {
            if (high[g] > f.p + 1) {
                high[g] = f.p + 1;
                qh.push(node{g, high[g]});
            }
        }
    }
    while (!ql.empty()) {
        node f = ql.front(); ql.pop();
        for (auto g:G[f.v]) {
            if (low[g] < f.p - 1) {
                low[g] = f.p - 1;
                ql.push(node{g, low[g]});
            }
        }
    }
    fill(ans, ans+n, -1);
    if (dfs(v, p)) {
        cout << "Yes" << '\n';
        for (int i=0; i<n; i++) cout << ans[i] << '\n';
    } else {
        cout << "No" << '\n';
    }
    return 0;
}

