const int N = 100005;

int n;
vector<int> g[N];
struct I {
	int l, r, o;
	I(int _l = 0, int _r = 0, int _o = -1): l(_l), r(_r), o(_o) {}
	I tr() { return I(l-1, r+1, o^1); }
	void comb(I a) {
		if (a.l == -1 && a.r == 1) return;
		if (o == -1) return l = a.l, r = a.r, o = a.o, void();
		if (a.o != o) FAIL;
		l = max(l, a.l), r = min(r, a.r);
		if (l > r) FAIL;
	}
	int In(int x) { return l <= x && x <= r; }
}it[N];
int w[N];

void S(int x, int par) {
	Fore(x) {
		S(*i, x);
		it[x].comb(it[*i].tr());
	}
}
void O(int x, int par) {
	Fore(x) {
		it[*i].comb(it[x].tr());
		O(*i, x);
	}
}

void Dw(int x, int par) {
	Fore(x) {
		w[*i] = (it[*i].In(w[x]+1) ? w[x]+1 : w[x]-1);
		Dw(*i, x);
	}
}

