	}

	F(i, 1, rd()) {
		int v = rd(), p = rd();
		it[v].comb(I(p, p, p&1));
	}

	S(1, -1);
	O(1, -1);

	w[1] = it[1].l;
	Dw(1, -1);
	puts("Yes");
	F(i, 1, n) printf("%d\n", w[i]);

	return 0;
}

