void solver() {
  int N = input();

  auto G = make_v(N, 0, 0);
  range(i, 0, N - 1) {
    int a = input() - 1, b = input() - 1;
    G[a].push_back(b);
    G[b].push_back(a);
  }

  int K = input();
  vector<int> A(N, -inf);
  priority_queue<pair<int, int>> q;

  range(i, 0, K) {
    int V = input() - 1, P = input();
    A[V] = P;
    q.emplace(V, P);
  }

  while (!q.empty()) {
    auto p = q.top();
    q.pop();

    int v = p.first, a = p.second;

    for (auto to : G[v]) {
      if (A[to] == -inf) {
        A[to] = a - 1;
        q.emplace(to, A[to]);
      } else if (abs(A[to] - a) != 1) {
        cout << No << endl;
        return;
      }
    }
  }

  cout << Yes << endl;
  for (auto &ans : A) cout << ans << endl;
}

