int n, k;

struct Edge { int ver, nxt; } edge[Maxn << 1];
int tot = 0, head[Maxn];
inline void add(int x, int y) { edge[++tot].ver = y, edge[tot].nxt = head[x], head[x] = tot; }

priority_queue<pair<int, int> > q;
int val[Maxn], fa[Maxn];
bool vis[Maxn];

void input() {
  n = read();
  for (rint i = 1; i < n; ++i) {
    int u = read(), v = read();
    add(u, v), add(v, u);
  }
  k = read();
  for (rint i = 1; i <= k; ++i) {
    int u = read(), p = read();
    val[u] = p; vis[u] = true;
  }
}

namespace Solution {
  bool BFS() {
    for (rint i = 1; i <= n; ++i) if (vis[i]) q.push(make_pair(val[i], i));
    while (q.size()) {
      int u = q.top().second; int x = q.top().first;
      q.pop();
			for (rint i = head[u]; i; i = edge[i].nxt) {
        int v = edge[i].ver;
        if (v == fa[u]) continue;
        fa[v] = u;
        if (vis[v]) {
        	if (abs(x - val[v]) != 1) return false;
        	return true;
				} else vis[v] = true, q.push(make_pair(val[v] = val[u] - 1, v));
      }
    }
    return true;
  }
  void solve() {
    if (!BFS()) return void(puts("No"));
    puts("Yes");
    for (rint i = 1; i <= n; ++i) printf("%d\n", val[i]); 
  }
}

