bool findAns(vector<vector<int>>& e_list, vector<int>& v_val, vector<pair<int,int>>& edge, int avg, int min, int max){
	if(edge.empty()){
		cout << "Yes" << endl;
		for(int i=1; i<v_val.size();i++){
			cout << v_val[i] << endl;
		}
		return true;
	}

	else{
		pair<int,int> e = edge.back();
		int f = e.first;
		int ne = e.second; 
//		cout << "Handling: " << f << "\t" << ne << endl;
		if(v_val[ne]!=-2){
			if(v_val[ne] - v_val[f] != -1 && v_val[ne] - v_val[f] != 1)
				return false;
			else{
				edge.pop_back();
				bool r = findAns(e_list,v_val,edge, avg, min, max);
				if(r)
					return true;
				edge.push_back(e);
				return false;
			}

		}
		else{
			int f = e.first;
			int ne = e.second; 

			edge.pop_back();
			for(int i=0;i<e_list[ne].size();i++){
				edge.push_back(pair<int,int>(ne,e_list[ne][i]));
			}

 			if(v_val[f] < min + 2){
				v_val[ne] = v_val[f] + 1;

				bool r = findAns(e_list,v_val,edge,avg, min, max);
				if(r)
					return true;
			}else if(v_val[f] > max - 2){
				v_val[ne] = v_val[f] - 1;

				bool r = findAns(e_list,v_val,edge,avg, min, max);
				if(r)
					return true;
			}else if(v_val[f] > avg){
				v_val[ne] = v_val[f] - 1;

				bool r = findAns(e_list,v_val,edge,avg, min, max);
				if(r)
					return true;
				v_val[ne] = v_val[f] + 1;

				r = findAns(e_list,v_val,edge,avg, min, max);
				if(r)
					return true;

			}else{
				v_val[ne] = v_val[f] + 1;

				bool r = findAns(e_list,v_val,edge,avg, min, max);
				if(r)
					return true;
				v_val[ne] = v_val[f] - 1;

				r = findAns(e_list,v_val,edge,avg, min, max);
				if(r)
					return true;
			}

			v_val[ne] = -2;

			for(int i=0;i<e_list[ne].size();i++){
				edge.pop_back();
			}
			edge.push_back(e);
			return false;
		}
	}
	return findAns(e_list,v_val,edge,avg, min, max);
}


