		return cost < r.cost;
	}
};

signed main() {
	INIT;
	VAR(int, n);
	std::vector<std::vector<Edge>> graph(n + 1);
	std::vector<int> a(n - 1), b(n - 1);
	REP(i, n - 1) {
		std::cin >> a[i] >> b[i];
		--a[i]; --b[i];
		graph[a[i]].emplace_back(Edge(b[i], 1));
		graph[b[i]].emplace_back(Edge(a[i], 1));
	}
	VAR(int, k);
	std::vector<int> v(k), p(k);
	REP(i, k) {
		std::cin >> v[i] >> p[i];
		--v[i];
		graph[n].emplace_back(Edge(v[i], p[i]));
	}

	std::vector<int> dist(/*頂点数*/n + 1);

	std::function<void(int)> Dijkstra = [&](int s) {
		using P = std::pair<int, int>;
		std::priority_queue<P, std::vector<P>, std::greater<P>> pq;
		std::fill(dist.begin(), dist.end(), INFINT);
		dist[s] = 0;
		pq.push(P(0, s));
		while (!pq.empty()) {
			P p = pq.top(); pq.pop();
			int v = p.second;
			if (dist[v] < p.first) continue;
			for (int i = 0; i < graph[v].size(); ++i) {
				Edge e = graph[v][i];
				if (dist[e.to] > dist[v] + e.cost) {
					dist[e.to] = dist[v] + e.cost;
					pq.push(P(dist[e.to], e.to));
				}
			}
		}
	};

	Dijkstra(n);

	std::vector<bool> visited(n, false);
	std::queue<int> queue;
	visited[0] = true;
	queue.push(0);
	while (!queue.empty()) {
		int now_i = queue.front(); queue.pop();
		std::vector<Edge>& now = graph[now_i];
		for (auto edge : now) {
			if (std::abs(dist[now_i] - dist[edge.to]) != 1) {
				OUT("No")BR;
				return 0;
			}
			if (!visited[edge.to]) {
				visited[edge.to] = true;
				queue.push(edge.to);
			}
		}
	}
	REP(i, k) {
		if (dist[v[i]] != p[i]) {
			OUT("No")BR;
			return 0;
		}
	}
	OUT("Yes")BR;
	REP(i, n) {
		OUT(dist[i])BR;
	}
	return 0;
}

