int val[N], Lmax[N], Rmax[N];
vector<int> vi[N];

void dfs(int pre, int u, bool spm)    {
    if(val[u] != -1) Lmax[u] = Rmax[u] = val[u];
    else Lmax[u] = -oo, Rmax[u] = oo;
    for(int v: vi[u])   if(v != pre)    {
        dfs(u, v, spm);
        if(val[v] != -1)    {
            //if(spm == 1 && u == 3) cout << Lmax[u] << ' ' << Lmax[v] << "s;fs\n";
            if(spm) Lmax[u] = max(Lmax[u], Lmax[v] - 1), Rmax[u] = min(Rmax[u], val[v] - 1);
            else Rmax[u] = min(Rmax[u], Rmax[v] + 1), Lmax[u] = max(Lmax[u], val[v] + 1);
        } else {
            Lmax[u] = max(Lmax[u], Lmax[v] - 1);
            Rmax[u] = min(Rmax[u], Rmax[v] + 1);
        }
    }
}

void solve(int pre, int u, int spm) {
    int nex = 0;
    if(Lmax[u] <= spm + 1 && spm + 1 <= Rmax[u]) nex = spm + 1;
    else nex = spm - 1;
    val[u] = nex;
    for(int v: vi[u])   if(v != pre){
        solve(u, v, nex);
    }
}

