using namespace std;
const int LEN = 1e5 + 5;
const int oo = 1e9;
int head[LEN];
struct edge {
    int vet, next;
} E[LEN * 2];
int i, j, k, n, m, s, t, tot;
bool checkodd, checkval;
int L[LEN], R[LEN], isodd[LEN], ans[LEN];
void add(int u, int v) {
    E[++tot] = (edge){v, head[u]};
    head[u] = tot;
}
void dfs(int u, int pre) {
    for (int e = head[u]; e != -1; e = E[e].next) {
        int v = E[e].vet;
        if (v != pre) {
            if (isodd[v] != -1 && isodd[v] != (isodd[u] ^ 1)) {
                checkodd = false;
            }
            isodd[v] = isodd[u] ^ 1;
            dfs(v, u);
            L[u] = max(L[u], L[v] - 1);
            R[u] = min(R[u], R[v] + 1);
        }
    }
    for (int e = head[u]; e != -1; e = E[e].next) {
        int v = E[e].vet;
        if (v != pre) {
            L[v] = max(L[v], L[u] - 1);
            R[v] = min(R[v], R[u] + 1);
            dfs(v, u);
        }
    }
    if (L[u] > R[u]) {
        checkval = false;
    }
}
void dfsans(int u, int pre) {
    for (int e = head[u]; e != -1; e = E[e].next) {
        int v = E[e].vet;
        if (v != pre) {
            if (L[v] <= ans[u] + 1 && ans[u] + 1 <= R[v]) {
                ans[v] = ans[u] + 1;
            } else {
                ans[v] = ans[u] - 1;
            }
            dfsans(v, u);
        }
    }
}
int main() {
    scanf("%d", &n);
    for (i = 1; i <= n; i++) {
        head[i] = -1;
        L[i] = -oo;
        R[i] = oo;
        isodd[i] = -1;
    }
    for (int i = 1; i < n; i++) {
        int x, y;
        scanf("%d %d", &x, &y);
        add(x, y);
        add(y, x);
    }
    scanf("%d", &m);
    for (int i = 1; i <= m; i++) {
        int x, c;
        scanf("%d %d", &x, &c);
        L[x] = R[x] = c;
        isodd[x] = c % 2;
        s = x;
    }
    checkodd = checkval = true;
    dfs(s, -1);
    if (checkodd == false || checkval == false) {
        puts("No");
        return 0;
    }
    ans[s] = L[s];
    dfsans(s, -1);
    puts("Yes");
    for (int i = 1; i <= n; i++) {
        printf("%d\n", ans[i]);
    }
    return 0;
}

#include <bits/stdc++.h>

const int MAXN = 100010;
void bye() { std::cout << "No" << std::endl; exit(0); }
struct info {
	int l, r, typ;
	info operator + (info b) {
		if (typ != b.typ) return (info) {0, 0, -233};
		return (info) {std::max(l, b.l), std::min(r, b.r), typ};
	}
	info ex() { return (info) {l - 1, r + 1, typ ^ 1}; }
	bool none() { return typ < 0 || l > r; }
} val[MAXN];
struct edge {
	int nxt, to;
} es[MAXN << 1];
int head[MAXN], tot;
void adde(int b, int e) {
	es[++tot] = (edge) {head[b], e}; head[b] = tot;
	es[++tot] = (edge) {head[e], b}; head[e] = tot;
}
int fa[MAXN], dfn[MAXN], idx, dep[MAXN];
void dfs(int u) {
	dfn[++idx] = u; dep[u] = dep[fa[u]] + 1;
	for (int i = head[u]; i; i = es[i].nxt)
		if (es[i].to != fa[u])
			fa[es[i].to] = u, dfs(es[i].to);
}

int main() {
	std::ios_base::sync_with_stdio(false), std::cin.tie(0);
	int n; std::cin >> n;
	for (int i = 1, b, e; i < n; ++i)
		std::cin >> b >> e, adde(b, e);
	dfs(1);
	int K; std::cin >> K; int coe = -1;
	memset(val, -1, sizeof val);
	for (int i = 1, u, v; i <= K; ++i) {
		std::cin >> u >> v;
		if (i == 1) coe = (dep[u] ^ v) & 1;
		if ((dep[u] ^ v) % 2 != coe) bye();
		val[u] = (info) {v, v, v & 1};
	}
	for (int i = 1; i <= n; ++i) if (val[i].typ == -1) {
		if ((dep[i] ^ coe) & 1)
			val[i] = {-123457, 123457, 1};
		else val[i] = {-123456, 123456, 0};
	}
	for (int i = n; i; --i) {
		const int u = dfn[i];
		if (val[u].none()) bye();
		val[fa[u]] = val[fa[u]] + val[u].ex();
	}
	for (int i = 1; i <= n; ++i) {
		const int u = dfn[i];
		if (val[u].none()) bye();
		if (fa[u]) val[u] = val[u] + val[fa[u]].ex();
		val[u].r = val[u].l;
	}
	std::cout << "Yes\n";
	for (int i = 1; i <= n; ++i) std::cout << val[i].l << '\n';
	return 0;
}

