void dfs_down(int v, int p) {
    for (int to:g[v]) {
        if (to == p)
            continue;
        if (L[to] < L[v] - 1) {
            L[to] = L[v] - 1;
            flag = true;
        }
        if (R[to] > R[v] + 1) {
