        }
        dfs_down(to, v);
    }
}

void dfs_up(int v, int p) {
    for (int to:g[v]) {
        if (to == p)
            continue;

        dfs_up(to, v);

        if (L[v] < L[to] - 1) {
            L[v] = L[to] - 1;
            flag = true;
        }
        if (R[v] > R[to] + 1) {
            R[v] = R[to] + 1;
            flag = true;
        }
        if (used[to]) {
