{
  t++; b[t][0]=p[x]; p[x]=t; b[t][1]=y;
}
void dfs(int u,int fa)
{
   if (a[u]>=0)
     {
       l[u]=r[u]=a[u];
       sign[u]=a[u] % 2;
     }
   else 
     {
       l[u]=1e-8; r[u]=1e8;
       sign[u]=-1;
     }
   int t=p[u];
   while (t) 
   {
     int y=b[t][1];
     if (y!=fa) 
     {
       dfs(y,u);
       if (sign[y] != -1)
       {
         if (sign[u]==sign[y])
           {
             puts("No");
             exit(0);
           }
       sign[u]=sign[y] ^ 1;
       l[u]=max(l[u],l[y]-1);
       r[u]=min(r[u],r[y]-1);
       if (l[u]>r[u])
         {
           puts("No");
             exit(0);
         }
       }
     }
     t=b[t][0];
   }
}
void redfs(int x,int fa)
{
  if (sign[x]==-1) a[x]=a[fa]+1;
  else
  {
    if (fa)
      if (a[fa]+1>=l[x] && a[fa]+1<=r[x])
        a[x]=a[fa]+1;
       else
        a[x]=a[fa]-1;
    else
      a[x]=l[x];
  }
  int t=p[x];
  while (t)
    {
      int y=b[t][1];
      if (y!=fa) redfs(y,x);
      t=b[t][0];
    }

}
