	priority_queue< PII > que;
	REP( i, K )
	{
		values[ V[i] ] = P[i];
		que.EM( P[i] * -1 * sgn, V[i] );
		odd_even[ V[i] ] |= 1 << ( P[i] % 2 );
	}

	while ( !que.empty() )
	{
		const int val = que.top().fst;
		const int u = que.top().snd;
		que.pop();

		odd_even[u] |= 1 << ( val % 2 );

		if ( val * -1 * sgn != values[u] )
		{
			continue;
		}

		FOR( v, G[u] )
		{
			if ( marked[v] )
			{
				continue;
			}

			if ( 0 < sgn ? chmin( values[v], values[u] + sgn ) : chmax( values[v], values[u] + sgn ) )
			{
				que.EM( values[v] * -1 * sgn, v );
			}
		}
	}

	return move( values );
}

void coloring( const VVI &G, const VI &val_min, const VI &val_max, const int u, const int p, VI &res, const int prev = -1 )
{
	res[u] = p;

	FOR( v, G[u] )
	{
		for ( const int np : { p - 1, p + 1 } )
		{
			if ( v != prev && val_min[v] <= np && np <= val_max[v] )
			{
				coloring( G, val_min, val_max, v, np, res, u );
				break;
			}
		}
	}

	return;
}

