	VI V( K ), P( K );
	REP( i, K )
	{
		scanf( "%d%d", &V[i], &P[i] );
		--V[i];
	}

	VI marked( N );
	FOR( v, V )
	{
		marked[v] = 1;
	}

	VI odd_even( N );
	const VI val_min = value_range( G, V, P, marked, -1, odd_even ), val_max = value_range( G, V, P, marked, 1, odd_even );

