        if(x.first > x.second){ x = ng; return false; }
        return true;
    }
    x = ng;
    return false;
}

bool dfs1(const int v, const int par = -1){
    for(const int nv : edge[v]) if(nv != par){
        dfs1(nv, v);
        if(not merge(range[v], range[nv])) return false;
    }
    return true;
}

