namespace G{
	int cnt,fir[N],fa[N],dep[N];
	struct edge{
		int to,nx;
	}eg[N<<1];

	inline void add(const int a,const int b){
		//printf("add: %d %d\n",a,b);
		eg[++cnt]=(edge){b,fir[a]};
		fir[a]=cnt;
	}

	void dfs_dep(const int x){
		for(int i=fir[x]; i; i=eg[i].nx){
			const int y=eg[i].to;
			if(y==fa[x]) continue;
			fa[y]=x;
			dep[y]=dep[x]+1;
			dfs_dep(y);
		}
	}

	bool dfs_vld(const int x){
		if(lim_r[x]==-1){
			lim_r[x]=(dep[x]==dif?1e5:1e5+1);
			lim_l[x]=(dep[x]==dif?0:1);
		}
		for(int i=fir[x]; i; i=eg[i].nx){
			const int y=eg[i].to;
			if(y==fa[x]) continue;
			if(!dfs_vld(y)) return 0;
			apn(lim_r[x],lim_r[y]+1);
			apx(lim_l[x],lim_l[y]-1);
		}
		assert(((lim_l[x]^lim_r[x])&1)==0);
		return lim_l[x]<=lim_r[x];
	}

	void dfs_ans(const int x){
		for(int i=fir[x]; i; i=eg[i].nx){
			const int y=eg[i].to;
			if(y==fa[x]) continue;
			ans[y]=ans[x]<lim_l[y]?ans[x]+1:ans[x]-1;
			dfs_ans(y);
		}
	}
}

