int N, K;
int A[110000], B[110000], V[110000], P_[110000];
vector<int> G[110000];
bool decided[110000], visited1[110000], visited2[110000];
int odd[110000];
P seg[110000];
int ans[110000];

void no() {
    cout << "No" << endl;
    exit(0);
}

void dfs1(int x, int n) {
    if (decided[n] && ans[n] % 2 != x) no();
    visited1[n] = true;
    odd[n] = x;
    for (int i = 0; i < G[n].size(); i++) {
        if (visited1[G[n][i]]) continue;
        dfs1((x + 1) % 2, G[n][i]);
    }
}

P dfs2(int n) {
    visited2[n] = true;
    if (decided[n]) return seg[n] = P(ans[n], ans[n]);
    int l = -1e13, r = 1e13;
    for (int i = 0; i < G[n].size(); i++) {
        if (visited2[G[n][i]] && !decided[G[n][i]]) continue;
        P p = dfs2(G[n][i]);
        l = max(l, p.first);
        r = min(r, p.second);
    }
    l--; r++;
    if (abs(l) % 2 != odd[n]) l++;
    if (abs(r) % 2 != odd[n]) r--;
    if (l > r) no();
    return seg[n] = P(l, r);
}

void dfs3(int x, int n) {
    decided[n] = true;
    ans[n] = seg[n].first <= x - 1 ? x - 1 : x + 1;
    for (int i = 0; i < G[n].size(); i++) {
        if (decided[G[n][i]]) continue;
        dfs3(ans[n], G[n][i]);
    }
}

