        ans[V[i]] = P_[i];
    }
    dfs1(P_[0] % 2, V[0]);
    for (int i = 1; i <= N; i++) {
        if (decided[i]) continue;
        dfs2(i);
        dfs3(seg[i].first + 1, i);
    }
    cout << "Yes" << endl;
    for (int i = 1; i <= N; i++) {
        cout << ans[i] << endl;
    }
    return 0;
}

