int num[100000];				//num[i] = 頂点iに書かれている値 (なければINF)
pair<int, int> range[100000];	//range[i] = 頂点i以下で矛盾を無くしたいときに頂点iに書ける値の範囲 (閉区間)

//開始頂点の番号を返す
int input() {
	int i;
	cin >> n;
	for (i = 0; i < n - 1; i++) {
		int u, v;
		cin >> u >> v; u--; v--;
		et[u].push_back(v);
		et[v].push_back(u);
	}
	for (i = 0; i < n; i++) { num[i] = INF; }

	int k;
	int ret = -1;
	cin >> k;
	for (i = 0; i < k; i++) {
		int v, p;
		cin >> v >> p; v--;
		num[v] = p;
		ret = v;
	}
	return ret;
}

//偶奇チェック
bool dfs(int parent, int v, int mod) {
	if (num[v] != INF && num[v] % 2 != mod) { return false; }
	for (int i = 0; i < et[v].size(); i++) {
		if (et[v][i] == parent) continue;
		if (!dfs(v, et[v][i], (mod + 1) % 2)) return false;
	}
	return true;
}

//値範囲決め (頂点v以下で矛盾がないようにしたとき, 頂点vに入る値の集合は1つの区間になる)
pair<int, int> dfs2(int parent, int v) {
	pair<int, int> ret = pair<int, int>(-INF, INF);

	if (num[v] != INF) ret = pair<int, int>(num[v], num[v]);

	for (int i = 0; i < et[v].size(); i++) {
		if (et[v][i] == parent) continue;
		pair<int, int> res = dfs2(v, et[v][i]);
		ret.first = max(ret.first, res.first - 1);
		ret.second = min(ret.second, res.second + 1);
	}
	return (range[v] = ret);
}

//値を根から決めていく
void dfs3(int parent, int v) {
	if (parent == -1) { num[v] = range[v].first; }
	else {
		if (range[v].first <= num[parent] - 1 && num[parent] - 1 <= range[v].second) { num[v] = num[parent] - 1; }
		else { num[v] = num[parent] + 1; }
	}
	for (int i = 0; i < et[v].size(); i++) {
		if (parent == et[v][i]) continue;
		dfs3(v, et[v][i]);
	}
}

