	if (!dfs(-1, start, num[start] % 2)) { cout << "No" << endl; return 0; }
	pair<int, int> res = dfs2(-1, start);
	if (res.first > res.second) { cout << "No" << endl; return 0; }

	cout << "Yes" << endl;
	dfs3(-1, start);
	for (int i = 0; i < n; i++) {
		cout << num[i] << endl;
	}
	return 0;
}

