		edge[v].push_back(u);
	}

	scanf("%d", &k);
	for (int i = 1; i <= k; ++i) {
		scanf("%d%d", &a[i], &b[i]);
		val[a[i]] = b[i];
		vis[a[i]] = 1;
	}
	if (!dfs(a[1], 0, (b[1] & 1))) {
		puts("No");
	}
	else {
		puts("Yes");
		//assert(false);
		val[a[1]] = b[1];
		getAns(a[1], 0);
		for (int i = 1; i <= n; ++i) printf("%d\n", val[i]);
	}
}

