pair<ll, ll> dfs(ll from, ll now){
  if(num[now][1]<=10000000) return make_pair(num[now][0], num[now][1]);
  ll l=-INF, r=INF;
  for(int i=0;i<G[now].size();i++){
    if(from==G[now][i]) continue;
    pair<ll, ll> tmp = dfs(now, G[now][i]);
    l = max(l, tmp.first);
    r = min(r, tmp.second);
  }
  num[now][0] = l-1, num[now][1] = r+1;
  return make_pair(l-1, r+1);
}
int check(int from, int now){
  if(oe[now]!=-1) return oe[now];
  int ret = -1;
  for(int i=0;i<G[now].size();i++){
    if(from==G[now][i]) continue;
    int tmp = check(now, G[now][i]);
    if(tmp==2) return -2;
    if(ret==-1&&tmp==0) ret = 1;
    if(ret==-1&&tmp==1) ret = 0;
    if(ret!=-1&&ret==tmp) return -2;
  }
  oe[now] = ret;
  return ret;
}
