	Rep(p,x)if(des[p]!=fa)dfs2(des[p],x),mini[x]=min(mini[x],mini[des[p]]);
}
void calc(int x,int fa,int now){
	if(cnt[x]!=now)flag=1;
	Rep(u,x)if(des[u]!=fa){
		if(mini[des[u]]>now){
			p[des[u]]=p[x]+1;
			calc(des[u],x,now+1);
		}else{
			p[des[u]]=p[x]-1;
			calc(des[u],x,now);
		}
	}
}
