vector<int> edge[101000];
int p[101000];
P hist[101000];
int resV[101000];

P mergeP(P x, P y){
    return P(max(x.fs, y.fs), min(x.sc, y.sc));
}


P dfs(int s, int prev, int index){
    P x;
    if(p[s] != -1){
        if(p[s] % 2 != index){
            return P(10000010, -10100000);
        }
        else {
            x = P(p[s], p[s]);
        }

    }
    else if(index == 0){
        x = P(-2000000, 2000000);
    }
    else{
        x = P(-1999999, 1999999);
    }

    for(auto v: edge[s]){
        if(v == prev){
            continue;
        }
        x = mergeP(x, dfs(v, s, 1-index));
    }
    hist[s] = x;
    return P(x.fs - 1, x.sc + 1);
}


bool dfs2(int s, int prev, int prevValue){
    bool res = true;
    if(prevValue + 1 >= hist[s].fs && prevValue + 1 <= hist[s].sc){
        resV[s] = prevValue + 1;
    }
    else if(prevValue - 1 >= hist[s].fs && prevValue - 1 <= hist[s].sc){
        resV[s] = prevValue - 1;
    }
    else{
        return false;
    }

    for(auto v: edge[s]){
        if(v == prev){
            continue;
        }
        if(!dfs2(v, s, resV[s])){
            res = false;
        }
    }
    return res;
}


