void dfs(int x,int dep,int fa) {
	mn[x][Mn[0]+dep&1]=min(mn[x][Mn[0]+dep&1],Mn[0]+dep);
	mn[x][Mn[1]+dep&1]=min(mn[x][Mn[1]+dep&1],Mn[1]+dep);
	mx[x][Mx[0]-dep&1]=max(mx[x][Mx[0]-dep&1],Mx[0]-dep);
	mx[x][Mx[1]-dep&1]=max(mx[x][Mx[1]-dep&1],Mx[1]-dep);
	for(int i=first[x];i;i=nxt[i]) if(to[i]!=fa&&!vis[to[i]]) dfs(to[i],dep+1,x);
