using namespace std;
const int Size=1<<16;
char buffer[Size],*head,*tail;
inline char Getchar() {
    if(head==tail) {
        int l=fread(buffer,1,Size,stdin);
        tail=(head=buffer)+l;
    }
    if(head==tail) return -1;
    return *head++;
}
inline int read() {
    int x=0,f=1;char c=getchar();
    for(;!isdigit(c);c=getchar()) if(c=='-') f=-1;
    for(;isdigit(c);c=getchar()) x=x*10+c-'0';
    return x*f;
}
typedef long long ll;
const int maxn=100010;
const int inf=1e9;
int n,first[maxn],nxt[maxn<<1],to[maxn<<1],e;
void AddEdge(int u,int v) {
	to[++e]=v;nxt[e]=first[u];first[u]=e;
	to[++e]=u;nxt[e]=first[v];first[v]=e;
}
int minv[20][maxn],dep[maxn],pos[maxn],cnt;
void dfs(int x,int fa) {
     minv[0][++cnt]=x;pos[x]=cnt;
     for(int i=first[x];i;i=nxt[i]) if(to[i]!=fa) {
         dep[to[i]]=dep[x]+1;dfs(to[i],x); 
         minv[0][++cnt]=x;
     }
}
int Log[maxn];
int better(int x,int y) {return dep[x]<dep[y]?x:y;}
void init() {
     Log[0]=-1;rep(i,1,cnt) Log[i]=Log[i>>1]+1;
     for(int j=1;(1<<j)<=cnt;j++)
        for(int i=1;i+(1<<j)-1<=cnt;i++)
           minv[j][i]=better(minv[j-1][i],minv[j-1][i+(1<<j-1)]);     
}
int dist(int x,int y) {
	int ans=dep[x]+dep[y];
    x=pos[x];y=pos[y];if(x>y) swap(x,y);
    int k=Log[y-x+1];
    return ans-2*dep[better(minv[k][x],minv[k][y-(1<<k)+1])];    
}
int f[maxn],siz[maxn],vis[maxn],size,root;
void getroot(int x,int fa) {
	int maxs=0;siz[x]=1;
	for(int i=first[x];i;i=nxt[i]) if(to[i]!=fa&&!vis[to[i]]) {
		getroot(to[i],x);siz[x]+=siz[to[i]];
		maxs=max(maxs,siz[to[i]]);
	}
	f[x]=max(maxs,size-siz[x]);
	if(f[root]>f[x]) root=x;
}
int fa[maxn];
void solve(int x,int FA) {
	vis[x]=1;fa[x]=FA;
	for(int i=first[x];i;i=nxt[i]) if(!vis[to[i]]) {
		f[0]=size=siz[to[i]];getroot(to[i],root=0);
		solve(root,x);
	}
}
int Mx[maxn][2],Mn[maxn][2];
void upmax(int& a,int b) {if(b>a) a=b;}
void upmin(int& a,int b) {if(b<a) a=b;}
void update(int x,int c) {
	upmax(Mx[x][c&1],c);
	upmin(Mn[x][c&1],c);
	for(int i=x;fa[i];i=fa[i]) {
		int D=dist(x,fa[i]);
		upmax(Mx[fa[i]][c-D&1],c-D);
		upmin(Mn[fa[i]][c+D&1],c+D);
	}
}
#define mp make_pair
pair<int,int> query(int x) {
	int R[2],L[2];
	R[0]=Mn[x][0];R[1]=Mn[x][1];
	L[0]=Mx[x][0];L[1]=Mx[x][1];
	for(int i=x;fa[i];i=fa[i]) {
		int D=dist(x,fa[i]);
		upmax(L[Mx[fa[i]][0]-D&1],Mx[fa[i]][0]-D);
		upmax(L[Mx[fa[i]][1]-D&1],Mx[fa[i]][1]-D);
		upmin(R[Mn[fa[i]][0]+D&1],Mn[fa[i]][0]+D);
		upmin(R[Mn[fa[i]][1]+D&1],Mn[fa[i]][1]+D);
	}
	int cnt=0,l,r;
	if(L[0]!=-inf&&R[0]!=inf) cnt++,l=L[0],r=R[0];
	else if(L[0]>R[0]) cnt=233;
	if(L[1]!=-inf&&R[1]!=inf) cnt++,l=L[1],r=R[1];
	else if(L[1]>R[1]) cnt=233;
	if(cnt!=1) return mp(inf,-inf);
	return mp(l,r);
}
int val[maxn],mx[maxn][2],mn[maxn][2];
void color(int x,int fa) {
	for(int i=first[x];i;i=nxt[i]) if(to[i]!=fa) {
		if(val[x]-1>=mx[to[i]][0]&&val[x]-1<=mn[to[i]][0]) val[to[i]]=val[x]-1;
		else val[to[i]]=val[x]+1;
		color(to[i],x);
	}
}
int main() {
	n=read();
	rep(i,2,n) AddEdge(read(),read());
	dfs(1,0);init();
	rep(i,1,n) Mx[i][0]=Mx[i][1]=-inf,Mn[i][0]=Mn[i][1]=inf;
	f[0]=size=n;getroot(1,root=0);
	solve(root,0);
	int k=read();
	memset(val,-1,sizeof(val));
	rep(i,1,k) {
		int x=read(),y=read();
		update(x,y);val[x]=y;
	}
	int ok=1;
	rep(i,1,n) {
		pair<int,int> tmp=query(i);
		mx[i][0]=tmp.first;mn[i][0]=tmp.second;
		if(tmp.first>tmp.second) ok=0;
	}
	if(ok) {
		puts("Yes");
		rep(i,1,n) if(val[i]>=0) {
			color(i,0);
			break;
		}
		rep(i,1,n) printf("%d\n",val[i]);
	}
	else puts("No");
	return 0;
}

