    for(int v, p, i = 0; i < k; i++)
    {
        scanf("%d%d", &v, &p);
        id[v] = p & 1;
        L[v] = R[v] = p;
    }
    dfs(1, -1);
    dfs(1, -1, -INF, INF);
    bool flag = true;
    for(int i = 1; i <= n; i++) if(id[i] == 2) flag = false;
    if(!flag) puts("No");
