void dfs1(int t, int f, int d)
{
    if (ai[t] != -1 && ((ai[t] & 1) ^ d)) puts("No"), exit(0);
    L[t] = 0; R[t] = INF; if (ai[t] != -1) L[t] = R[t] = ai[t];
    for (int i = 0; i < bi[t].size(); ++ i) if (bi[t][i] != f)
    {
        dfs1(bi[t][i], t, !d);
        L[t] = max(L[t], L[bi[t][i]] - 1);
        R[t] = min(R[t], R[bi[t][i]] + 1);
    }
}
void dfs2(int t, int f, int l, int r)
{
    L[t] = max(L[t], l - 1);
    R[t] = min(R[t], r + 1);
    for (int i = 0; i < bi[t].size(); ++ i) if (bi[t][i] != f)
        dfs2(bi[t][i], t, L[t], R[t]);
}
void dfs3(int t, int f, int d)
{
    ai[t] = d;
    for (int i = 0; i < bi[t].size(); ++ i) if (bi[t][i] != f)
        dfs3(bi[t][i], t, (d - 1 < L[bi[t][i]]? d + 1: d - 1));
}
