    for (auto to : g[v]) {
        if (to != pr && have[to]) {
            kek = true;
        }
    }
    if (col[v] > 0 && !kek) good.push_back(v);
}

void paint(int v, int cur) {
    col[v] = cur;
    for (int to : g[v]) {
        if (to != par[v]) {
            paint(to, cur + 1);
        }
    }
}

