        l = r = BAD;
    }
};

vector <seg> dp(N);

void solve(int v) {
    vector <seg> t;
    for (int to : g[v]) {
        if (to != par[v]) {
            solve(to);
            if (have[to] && dp[to].l != BAD) {
                t.push_back(dp[to]);
            }
        }
    }
    if (col[v] != BAD) {
        dp[v].l = col[v];
        dp[v].r = col[v];
        return;
    }  
    if (t.empty()) {

    } else {
