                mx = max(mx, to.l);
            }
            if (mx >= mn) {
                mn--;
                mx++;
                dp[v].l = mn;
                dp[v].r = mx;
            }
        }
    }
}

void flex(int v) {
    if (col[v] == BAD && have[v]) {
        int c = col[par[v]];
        if (c % 2 == dp[v].l % 2) {
            cout << "No\n";
            exit(0);
        }
        if (c + 1 > dp[v].r || c + 1 < dp[v].l) {
            if (c - 1 > dp[v].r || c - 1 < dp[v].l) {
                cout << "No\n";
                exit(0);
            }
            col[v] = c - 1;
        } else {
            col[v] = c + 1;
        }
    }
