      if(hani[pt] != MP(D1, D1)){
	if(hani[now] == MP(D1, D1)){
	  hani[now] = MP(hani[pt].F - 1, hani[pt].S + 1);
	}
	else if(hani[now].S < hani[pt].F || hani[pt].S < hani[now].F || (hani[now].F & 1) == (hani[pt].F & 1)){
	  return MP(D2, D2);
	}
	else{
	  hani[now] = MP(max(hani[now].F, hani[pt].F - 1), min(hani[now].S, hani[pt].S + 1));
	}
      }
    }
  }
  return hani[now];
}

void bfs2(int now, int prev, int prenum)
{
  if(hani[now] == MP(D1, D1)){
    ans[now] = prenum + 1;
  }

  else if(prenum < hani[now].F){
    ans[now] = prenum + 1;
  }
  else{
    ans[now] = prenum - 1;
  }

  for(auto pt:node[now]){
    if(pt != prev){
      bfs2(pt, now, ans[now]);
    }
  }
}
