bool chmin(int &a, int b) {if (a > b) { a = b; return true; } else return false; }

const int MAX = 110000;
int N;
vector<int> tree[MAX];

int K;
int P[MAX];
int lo[MAX], hi[MAX];
int res[MAX];

bool dfs(int v, int p) {
  bool can = true;
  lo[v] = hi[v] = P[v];
  for (int i = 0; i < tree[v].size(); ++i) {
    int to = tree[v][i];
    if (to == p) continue;
    if (!dfs(to, v)) return false;
  }
  for (int i = 0; i < tree[v].size(); ++i) {
    int to = tree[v][i];
    if (to == p) continue;
    if (lo[to] == -1) continue;
    int tlo = lo[to] - 1;
    int thi = hi[to] + 1;
    if (lo[v] == -1) {
      lo[v] = tlo;
      hi[v] = thi;
    }
    else {
      if ( abs(lo[v] - tlo) % 2 != 0 ) return false;
      chmax(lo[v], tlo);
      chmin(hi[v], thi);
      if (lo[v] > hi[v]) return false;
    }
  }
  //cout << v << ": " << lo[v] << ", " << hi[v] << endl;
  return true;
}

void reconstruct(int v, int p) {
  if (p == -1) {
    if (lo[v] != -1) res[v] = hi[v];
    else res[v] = 0;
  }
  else {
    if (lo[v] != -1) res[v] = min(hi[v], res[p]+1);
    else res[v] = res[p]+1;
  }
  for (auto to : tree[v]) {
    if (to == p) continue;
    reconstruct(to, v);
  }
}


