    h[u]=mem++;
}
bool can;
int deep[maxn];
int mi[maxn],mx[maxn];
void dfs(int u,int f)
{
    if(num[u]){
        mx[u]=mi[u]=num[u];
    }
    else{
        mx[u]=1000000000;
        mi[u]=-1000000000;
    }

    if(num[u]&&(abs(num[u]-deep[u])&1)){
        //printf("%d %d %d uuuu\n",num[u],deep[u],u);
        can=0;return ;
    }
    for(int i=h[u];i+1;i=e[i].next)
    {
        int v=e[i].v;
        if(v==f) continue;
        deep[v]=deep[u]+1;
        dfs(v,u);
        if(!can) return ;
        mi[v]--;
        mx[v]++;
        mi[u]=max(mi[u],mi[v]);
        mx[u]=min(mx[u],mx[v]);
    }
    if(mx[u]<mi[u]){
        //printf("%d %d %d\n",u,mx[u],mi[u]);
        can=0;
    }
