{
    for(int i=h[u];i+1;i=e[i].next)
    {
        int v=e[i].v;
        if(v==f) continue;
        if(num[u]-1>=mi[v]){
            num[v]=num[u]-1;
        }
        else{
            num[v]=num[u]+1;
        }
        if(num[v]<mi[v]||num[v]>mx[v]) while(1);
        dfsnum(v,u);
    }
}
