using namespace std;

const int INF = 1 << 30;

struct Data
{
  int small, big;
};

int N, K;
int value[100000];
vector< int > tree[100000];
int sz[100000];
int cost[100000];

bool c[100000];

void color(int idx, bool now, int par = -1)
{
  if(~value[idx] && value[idx] % 2 != now) {
    puts("No");
    exit(0);
  }
  c[idx] = now;
  for(int to : tree[idx]) {
    if(to == par) continue;
    color(to, now ^ 1, idx);
  }
}

Data dfs(int idx, Data order, int par = -1)
{
  if(~value[idx]) {
    if(order.big == INF) {
      order.small = order.big = value[idx];
    } else {
      if(order.small <= value[idx] && value[idx] <= order.big) {
        order.small = order.big = value[idx];
      } else {
        puts("No");
        exit(0);
      }
    }
  }

  int top = -1;
  for(int i = 0; i < tree[idx].size(); i++) {
    if(tree[idx][i] == par) continue;
    if(top == -1 || sz[tree[idx][top]] < sz[tree[idx][i]]) top = i;
  }
  if(~top) swap(tree[idx][0], tree[idx][top]);

  for(int to : tree[idx]) {
    if(to == par) continue;
    Data ord = dfs(to, {max(order.small - 1, -1), min(INF, order.big + 1)}, idx);
    order.small = max(order.small, ord.small);
    order.big = min(order.big, ord.big);
  }
  while(order.small < 0) ++order.small;
  while(order.small % 2 != c[idx]) ++order.small;
  if(order.small > order.big) {
    puts("No");
    exit(0);
  }
  if(~value[idx] && order.small != 0) {
    puts("No");
    exit(0);
  }
  value[idx] = order.small;
  order.small = max(order.small - 1, -1);
  order.big = min(order.small + 1, INF);
  return (order);
}

int calc(int idx, int par)
{
  for(int to : tree[idx]) {
    if(to == par) continue;
    sz[idx] += calc(to, idx);
  }
  if(~value[idx]) ++sz[idx];
  return (sz[idx]);
}

