    value[--V] = P;
  }
  for(int i = 0; i < K; i++) {
    if(~value[i]) {
      color(i, value[i] & 1);
      break;
    }
  }
  calc(0, -1);
  dfs(0, (Data) {-1, INF});
  puts("Yes");
