void solve(){
    int n;
    cin >> n;
    vector<vector<int>> graph(n);
    rep(i,0,n-1){
        int a,b;
        cin >> a >> b;
        --a;
        --b;
        graph[a].push_back(b);
        graph[b].push_back(a);
    }


    int k;
    cin >> k;
    vector<int> p(n,-1);
    rep(i,0,k){
        int v;
        cin >> v;
        --v;
        cin >> p[v];
    }

    vector<bool> used(n);
    vector<int> lb(n,-inf),ub(n,inf),kind(n,-1);
    function<bool(int)> rec=[&](int u){
        used[u]=true;
        if(p[u]!=-1) lb[u]=ub[u]=p[u];
        for(int v:graph[u]){
            if(used[v]) continue;
            if(!rec(v)) return false;
            if(kind[v]!=-1){
                if(kind[u]==-1) kind[u]=(kind[v]+1)%2;
                else if(kind[u]!=(kind[v]+1)%2) return false;
            }
            if(ub[v]+1<lb[u] or ub[u]<lb[v]-1) return false;
            lb[u]=max(lb[u],lb[v]-1);
            ub[u]=min(ub[u],ub[v]+1);
        }
        if(lb[u]>ub[u]) return false;
        return true;
    };
    rep(i,0,n){
        if(p[i]!=-1){
            if(!rec(i)){
                cout << "No" << endl;
                return;
            }
            break;
        }
    }

    vector<int> ans(n);
    function<void(int,int)> write=[&](int u,int parent){
        if(p[u]!=-1) ans[u]=p[u];
        else{
            if(lb[u]<=ans[parent]-1 and ans[parent]-1<=ub[u]) ans[u]=ans[parent]-1;
            if(lb[u]<=ans[parent]+1 and ans[parent]+1<=ub[u]) ans[u]=ans[parent]+1;
        }
        for(int v:graph[u]){
            if(v==parent) continue;
            write(v,u);
        }
    };
    rep(i,0,n){
        if(p[i]!=-1){
            write(i,-1);
            break;
        }
    }
    cout << "Yes" << endl;
    rep(i,0,n) cout << ans[i] << endl;
}

int main(){
    std::cin.tie(0);
    std::ios::sync_with_stdio(false);
    cout.setf(ios::fixed);
    cout.precision(10);
    solve();
    return 0;
}

