bool res = 1;

void dfs(int now, int par){
	l[now] = -INF, r[now] = INF;
	rep(i, a[now].size()){
		if(a[now][i] == par) continue;
		parent[a[now][i]] = now;
		dfs(a[now][i], now);
//		if(!res) return ;
		if(known_parity[a[now][i]][0]) known_parity[now][1] = 1;
		if(known_parity[a[now][i]][1]) known_parity[now][0] = 1;
		l[now] = max(l[now], l[a[now][i]] - 1);
		r[now] = min(r[now], r[a[now][i]] + 1);
	}
	if(tag[now] != -INF){
		l[now] = max(l[now], tag[now]);
		r[now] = min(r[now], tag[now]);
		known_parity[now][tag[now] % 2] = 1;
	}
	if(known_parity[now][1] && known_parity[now][0]) res = false;
	if(l[now] > r[now]) res = false;
	order.pb(now);
	return ;
}

int make(int now){
	if(parent[now] == -1) return l[now];
	l[now] = max(l[now], l[parent[now]] - 1);
	r[now] = min(r[now], r[parent[now]] + 1);
	while((l[now] % 2) == (tag[parent[now]] % 2)) l[now]++;
	return l[now];
}

