void level(int s)
{
    int i,a,x=ad[s].size();
    vis[s]=1;
    rep(i,x)
    {
        a=ad[s][i];
        if(!vis[a])
            lev[a]=lev[s]+1,level(a);
    }
    return ;
}
void dfs(int s,int p)
{
    int i,a,x=ad[s].size(),f=1;
    while(f)
    {
        f=0;
        rep(i,x)
        {
            a=ad[s][i];
            if(a!=p)
            {
                low[a]=max(low[a],low[s]-1);
                high[a]=min(high[a],high[s]+1);
                dfs(a,s);
                if(low[s]<low[a]-1 || high[s]>high[a]+1)
                {
                    f=1;
                    low[s]=max(low[s],low[a]-1);
                    high[s]=min(high[s],high[a]+1);
                }
            }
        }
    }
}
void value(int s,int p)
{
    int i,a,x=ad[s].size();
    if(low[s]<high[s])
    {
        a=(lev[s]&1)-odd[root];
        if(a<0)
            a+=2;
        if((low[s]&1)!=a)
            low[s]++;
        high[s]=low[s];
    }
    rep(i,x)
    {
        a=ad[s][i];
        if(a!=p)
        {
            low[a]=max(low[a],low[s]-1);
            high[a]=min(high[a],high[s]+1);
            value(a,s);
        }
    }
    return ;
}
