void AddEdge(int u,int v) {
	to[++e]=v;nxt[e]=first[u];first[u]=e;
	to[++e]=u;nxt[e]=first[v];first[v]=e;
}
int mn[maxn][2],mx[maxn][2];
int f[maxn],siz[maxn],vis[maxn],size,root;
void getroot(int x,int fa) {
	int maxs=0;siz[x]=1;
	for(int i=first[x];i;i=nxt[i]) if(to[i]!=fa&&!vis[to[i]]) {
		getroot(to[i],x);siz[x]+=siz[to[i]];
		maxs=max(maxs,siz[to[i]]);
	}
	f[x]=max(maxs,size-siz[x]);
	if(f[root]>f[x]) root=x;
}
int A[maxn];
int Mx[2],Mn[2];
// Max (v - d)  Min (v + d)
void dfs(int x,int dep,int fa) {
	mn[x][Mn[0]+dep&1]=min(mn[x][Mn[0]+dep&1],Mn[0]+dep);
	mn[x][Mn[1]+dep&1]=min(mn[x][Mn[1]+dep&1],Mn[1]+dep);
	mx[x][Mx[0]-dep&1]=max(mx[x][Mx[0]-dep&1],Mx[0]-dep);
	mx[x][Mx[1]-dep&1]=max(mx[x][Mx[1]-dep&1],Mx[1]-dep);
	for(int i=first[x];i;i=nxt[i]) if(to[i]!=fa&&!vis[to[i]]) dfs(to[i],dep+1,x);
}
void dfs2(int x,int dep,int fa) {
	if(val[x]>=0) {
		Mn[val[x]+dep&1]=min(Mn[val[x]+dep&1],val[x]+dep);
		Mx[val[x]-dep&1]=max(Mx[val[x]-dep&1],val[x]-dep);
	}
	for(int i=first[x];i;i=nxt[i]) if(to[i]!=fa&&!vis[to[i]]) dfs2(to[i],dep+1,x);
}
void solve(int x) {
	vis[x]=1;int cnt=0;
	for(int i=first[x];i;i=nxt[i]) if(!vis[to[i]]) A[++cnt]=to[i];

	Mx[0]=Mx[1]=-inf;Mn[0]=Mn[1]=inf;
	if(val[x]>=0) {
		Mx[val[x]&1]=Mn[val[x]&1]=val[x];
		mn[x][val[x]&1]=min(mn[x][val[x]&1],val[x]);
		mx[x][val[x]&1]=max(mx[x][val[x]&1],val[x]);
	}
	rep(i,1,cnt) {
		dfs(A[i],1,0);
		dfs2(A[i],1,0);
	}
	int dep=0;
	mn[x][Mn[0]+dep&1]=min(mn[x][Mn[0]+dep&1],Mn[0]+dep);
	mn[x][Mn[1]+dep&1]=min(mn[x][Mn[1]+dep&1],Mn[1]+dep);
	mx[x][Mx[0]-dep&1]=max(mx[x][Mx[0]-dep&1],Mx[0]-dep);
	mx[x][Mx[1]-dep&1]=max(mx[x][Mx[1]-dep&1],Mx[1]-dep);

	Mx[0]=Mx[1]=-inf;Mn[0]=Mn[1]=inf;
	if(val[x]>=0) Mx[val[x]&1]=Mn[val[x]&1]=val[x];
	dwn(i,cnt,1) {
		dfs(A[i],1,0);
		dfs2(A[i],1,0);
	}

	for(int i=first[x];i;i=nxt[i]) if(!vis[to[i]]) {
		f[0]=size=siz[to[i]];getroot(to[i],root=0);
		solve(root);
	}
}
