	for(int i=first[x];i;i=nxt[i]) if(to[i]!=fa) {
		if(val[x]-1>=mx[to[i]][0]&&val[x]-1<=mn[to[i]][0]) val[to[i]]=val[x]-1;
		else val[to[i]]=val[x]+1;
		color(to[i],x);
	}
}
