int v[100010],p[100010],lb[100010],ub[100010];
vector<int> G[100010];
bool f=false;
int n;
void dfs(int i,int pre,int l,int r){//(頂点、前の頂点、ありうるmin、ありうるmax)
	if(p[i]!=-1){
		if(p[i]%2!=l%2||p[i]<l||p[i]>r){
			f=true;
			return;
		}
		l=p[i];
		r=p[i];
	}
	lb[i]=l,ub[i]=r;
	for(auto &e:G[i]){
		if(e==pre)continue;
		dfs(e,i,l-1,r+1);
		lb[i]=max(lb[i],lb[e]-1);
		ub[i]=min(ub[i],ub[e]+1);
	}
}
void dfs2(int i,int pre,int l,int r){
	if(p[i]!=-1){
		if(p[i]%2!=l%2||p[i]<l||p[i]>r){
			f=true;
			return;
		}
	}
	for(auto &e:G[i]){
		if(e==pre)continue;
		dfs2(e,i,lb[i]-1,ub[i]+1);
		lb[i]=max(lb[i],lb[e]-1);
		ub[i]=min(ub[i],ub[e]+1);
	}
}
void dfs3(int i,int pre){
	if(p[i]==-1&&pre!=-1){
		if(lb[i]<=p[pre]+1&&p[pre]+1<=ub[i]){
			p[i]=p[pre]+1;
		}else if(lb[i]<=p[pre]-1&&p[pre]-1<=ub[i]){
			p[i]=p[pre]-1;
		}
	}
	for(auto &e:G[i]){
		if(e==pre)continue;
		dfs3(e,i);
	}
}
