	}
}

#include <iostream>
#include <vector>
using namespace std;

int N,K,inf = 2e9;
int A[100010],B[100010],even[100010] = {0},visited[100010] = {0},ans[100010];
vector<vector<int>> v(100010);
bool judge = true;


void dfs1(int n,int mod){
	visited[n] = 1;
	even[n] = mod;
	if(A[n]!=-inf && A[n]%2!=mod) judge = false;
	for(int i=0;i<v[n].size();i++){
		int s = v[n][i];
		if(visited[s]==0){
			dfs1(s,1-mod);
		} 
	}
}

void dfs2(int n){
	visited[n] = 1;
	int ma = inf,mi = -inf;
	for(int i=0;i<v[n].size();i++){
		int s = v[n][i];
		if(visited[s]==0){
			int s = v[n][i];
			dfs2(s);
			mi = max(A[s]-1,mi);
			ma = min(B[s]+1,ma);
			if(ma<mi) judge = false;
		}
	}
	if(ma!=inf){
		B[n] = ma;
		A[n] = mi;
	}
}

void write(int n,int t){
	visited[n] = 1;
	if(A[n]==B[n]) ans[n] = A[n];
	else if(A[n]==-inf) ans[n] = t+1;
	else if(t<A[n]) ans[n] = A[n];
	else if(t>B[n]) ans[n] = B[n];
	else{
		if(t+1<=B[n]) ans[n] = t+1;
		else ans[n] = t-1;
	}
	for(int i=0;i<v[n].size();i++){
		int s = v[n][i];
		if(visited[s]==0){
			write(s,ans[n]);
		}
	}
}

int main(){
	cin >> N;
	for(int i=1;i<=N;i++){
		A[i] = -inf;
		B[i] = inf;
		even[i] = -1;
	}
	int a,b;
	for(int i=0;i<N-1;i++){
		cin >> a >> b;
		v[a].push_back(b);
		v[b].push_back(a);
	}
	cin >> K;
	for(int i=0;i<K;i++){
		cin >> a >> b;
		A[a] = b;
		B[a] = b;
		even[a] = b%2;
	}
	dfs1(a,even[a]);
	if(!judge){
		cout << "No" << endl;
		return 0;
	}
	for(int i=1;i<=N;i++) visited[i] = 0;
	dfs2(1);
	if(!judge) cout << "No" << endl;
	else{
		for(int i=1;i<=N;i++) visited[i] = 0;
		if(A[1]==-inf){
			ans[1] = even[1];
			write(1,even[1]-1);
		}
		else if(A[1]%2==even[1]){
			ans[1] = A[1];
			write(1,A[1]-1);
		}
		else if(A[1]%2!=even[1]){
			ans[1] = A[1]+1;
			write(1,A[1]);
		}
		cout << "Yes" << endl;
		for(int i=1;i<=N;i++){
			cout << ans[i] << endl;
		}
	}
}

