struct edge{int to,next;}e[MN*2+5];
inline void ins(int f,int t)
{
    e[++cnt]=(edge){t,head[f]};head[f]=cnt;
    e[++cnt]=(edge){f,head[t]};head[t]=cnt;
}
void dfs(int x,int fa)
{
    l[x]=L[x]=b[x]?s[x]:-1e6;r[x]=R[x]=b[x]?s[x]:1e6;
    for(int i=head[x];i;i=e[i].next) if(e[i].to!=fa)
    {
        dfs(e[i].to,x);
        if(l[e[i].to]-1>l[x]) L[x]=l[x],l[x]=l[e[i].to]-1,fl[x]=e[i].to;
        else L[x]=max(L[x],l[e[i].to]-1);
        if(r[e[i].to]+1<r[x]) R[x]=r[x],r[x]=r[e[i].to]+1,fr[x]=e[i].to;
        else R[x]=min(R[x],r[e[i].to]+1);
    }
}
void Solve(int x,int fa,int lt,int rt)
{
    int ll=max(lt,l[x]),rr=min(rt,r[x]);
    if(ll>rr) flag=0; else lt=rt=s[x]=ll;
    for(int i=head[x];i;i=e[i].next) if(e[i].to!=fa)
        Solve(e[i].to,x,max(lt,fl[x]==e[i].to?L[x]:l[x])-1,min(rt,fr[x]==e[i].to?R[x]:r[x])+1);
}
