    void dfs2(int v, int val, int p) {
        ans[v] = val;
        for (auto to : G[v]) {
            if (to == p) continue;
            if (range[to].first <= val - 1) {
                dfs2(to, val - 1, v);
            } else if (range[to].second >= val + 1) {
                dfs2(to, val + 1, v);
            }
        }
    }


    void solve(std::istream& cin, std::ostream& cout) {
        int N;
        cin >> N;
        G.resize(N);
        REP(i, N - 1) {
            int a, b;
            cin >> a >> b;
            a--, b--;
            G[a].push_back(b);
            G[b].push_back(a);
        }

        int K;
        cin >> K;
        vector<int> v(K), p(K);
        REP(i, K) {
            cin >> v[i] >> p[i];
            v[i]--;
        }

        range.resize(N);
        REP(i, N) range[i] = {-INF, INF};
        REP(i, K) {
            range[v[i]] = {p[i], p[i]};
        }

        ok = true;
        dfs(v[0], -1);

        if (!ok) {
            cout << "No" << endl;
            return;
        }

        cout << "Yes" << endl;
        ans.resize(N);
        dfs2(v[0], p[0], -1);
        REP(i, N) {
            cout << ans[i] << endl;
        }
    }
};


