    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    cout.tie(nullptr);
    std::istream& in(std::cin);
    std::ostream& out(std::cout);

    EIntegersOnATree solver;
    solver.solve(in, out);
    return 0;
}

