int main(void) {
    cin.tie(0); ios::sync_with_stdio(false);

    ll n;
    cin >> n;
    vector<vector<ll>> G(n);
    for(ll i=0; i<n-1; i++) {
        ll x, y;
        cin >> x >> y;
        x--, y--;
        G[x].push_back(y);
        G[y].push_back(x);
    }

    bool ng = false;
    vector<tuple<ll,ll,ll>> mm(n, make_tuple(-1e9, 1e9, 2));
    {

        ll k;
        cin >> k;
        while(k--) {
            ll v, p;
            cin >> v >> p;
            v--;
            mm[v] = make_tuple(p, p, p&1);
        }

        auto dfs = [&](auto dfs, ll cur, ll pre) -> void {
            ll &m = get<0>(mm[cur]);
            ll &M = get<1>(mm[cur]);
            ll &oe = get<2>(mm[cur]);
            for(auto &v: G[cur]) {
                if(v == pre) continue;
                dfs(dfs, v, cur);
                ll _m, _M, _oe;
                tie(_m, _M, _oe) = mm[v];
                m = max(m, _m-1);
                M = min(M, _M+1);
                if(oe&2) oe = _oe^1;
                else if(~_oe&2 && oe==_oe) ng = true;
            }
            if(m > M) ng = true;
        };
        dfs(dfs, 0, -1);
    }

    if(ng) {
        cout << "No" << endl;
        return 0;
    }

    vector<ll> res(n);
    {
        auto dfs = [&](auto dfs, ll cur, ll pre) -> void {

            for(auto &v: G[cur]) {
                if(v == pre) continue;

                ll m, M, oe;
                tie(m, M, oe) = mm[cur];
                res[v] = m <= res[cur]-1 && res[cur]-1 <= M ? res[cur]-1 : res[cur]+1;
                dfs(dfs, v, cur);
            }
        };
        res[0] = get<0>(mm[0]);
        dfs(dfs, 0, -1);
    }

    cout << "Yes" << endl;
    for(auto &e: res) cout << e << endl;
}

