		int v=e[x][i];
		if (v==fa) continue;
		dep[v]=dep[x]+1;
		dfs(v,x);
		Min0[x]=min(Min0[x],Min0[v]);
		Min1[x]=min(Min1[x],Min1[v]);
	}
}
