void solve(int x,int fa){
	if (fa){
		cnt0[x]=cnt0[fa];
		cnt1[x]=cnt1[fa];
		if (Min0[x]>cnt0[x]) cnt0[x]++,v[x]=v[fa]-1;else
		if (Min1[x]>cnt1[x]) cnt1[x]++,v[x]=v[fa]+1;else
		puts("No"),exit(0);
	}
	for (int i=0;i<e[x].size();i++)
	if (e[x][i]!=fa) solve(e[x][i],x);
}
