PLL dfs(int64 v, int64 p) {
    if (p != -1 && poss[p].fs != -1) {
        chmax(poss[v].fs, poss[p].fs-1);
        chmin(poss[v].sc, poss[p].sc+1);
    }
    for (auto &u : G[v]) {
        if (u == p) continue;
        PLL ret = dfs(u, v);
        if (poss[v] == PLL(-1, INF)) {
            poss[v] = ret;
