    for(int i=head[x];i;i=nxt[i]) {
	int y=to[i];
	if(y!=fa) {
	    if(a[x]-1>=L[y]) a[y]=a[x]-1;
	    else a[y]=a[x]+1;
	    solve(y,x);
	}
    }
}
