        int a, b; cin >> a >> b;
        a--, b--;
        edges[a].emplace_back(b), edges[b].emplace_back(a);
    }
    node_range.resize(n, make_pair(-VMAX, VMAX) );
    int k; cin >> k;
    int bv = -1;
    col.resize(n, -1);
    for (int i = 0; i < k; i++) {
        int v, p; cin >> v >> p;
        v--;
        node_range[v] = make_pair(p, p);
        if (p & 1) col[v] = 0;
        else col[v] = 1;
        if (bv == -1) bv = v;
    }
    dfs_barp(bv, -1, col[bv]);
    if (!ok_bar) {
        cout << "No\n";
        return 0;
    }
    dfs(0, -1, make_pair(-VMAX, VMAX));
    if (!ok_range) {
        cout << "No\n";
        return 0;
    }

    cout << "Yes\n";
    ans.resize(n, VMAX);
    dfs_ans(bv, -1, node_range[bv].second + 1);
    for (int i = 0; i < n; i++) cout << ans[i] << '\n';
    return 0;
}

