    u--, v--;
    graph.at(u).emplace_back(v);
    graph.at(v).emplace_back(u);
  }
  debug(graph);
  std::vector< int > value_vec(n, -1);
  {
    int k; std::cin >> k;
    loop(k) {
      int v, p; std::cin >> v >> p;
      v--;
      value_vec.at(v) = p;
    }
  }
  debug(value_vec);

  int root = 0;
  int inf = std::numeric_limits< int >::max();
  std::vector< int > constrain(n, false);
  std::vector< int > min_vec(n, -inf), max_vec(n, inf);
  auto dfs = [&](auto&& dfs, int crr, int prv) -> void {
    int& min = min_vec.at(crr);
    int& max = max_vec.at(crr);
    int value = value_vec.at(crr);
    for (int nxt : graph.at(crr)) {
      if (nxt == prv) continue;
      dfs(dfs, nxt, crr);
      if (constrain.at(nxt)) {
        constrain.at(crr) = true;
        int nxtmin = min_vec.at(nxt);
        int nxtmax = max_vec.at(nxt);
        assert(nxtmin != -inf);
        assert(nxtmax !=  inf);
        cmx(min, nxtmin - 1);
        cmn(max, nxtmax + 1);
      }
    }
    if (constrain.at(crr)) {
      require(((max-min)%2 == 0) && min <= max);
    }
    if (value != -1) {
      if (constrain.at(crr)) {
        require(min <= value && value <= max && ((value - min)%2==0));
      } else {
        constrain.at(crr) = true;
        min = max = value;
      }
    }
  };
  dfs(dfs, root, root);
  debug(constrain,fmt(-inf)(min_vec), fmt(inf)(max_vec));

  std::vector< int > ans(n);
  ans.at(root) = constrain.at(root) ? min_vec.at(root) : 0;
  auto efs = [&](auto&& efs, int crr, int prv) -> void {
    for (int nxt : graph.at(crr)) {
      if (nxt == prv) continue;
      int nxtmin = min_vec.at(nxt);
      int nxtmax = max_vec.at(nxt);
      int nxtans = ans.at(crr) - 1;
      if (nxtans < nxtmin) {
        nxtans += 2;
      }
      assert(nxtmin <= nxtans && nxtans <= nxtmax);
      ans.at(nxt) = nxtans;
      efs(efs, nxt, crr);
    }
  };
  efs(efs, root, root);

  std::cout << "Yes" << std::endl;
  for (int x : ans) {
    std::cout << x << std::endl;
  }
  return 0;
}

