		}
		int nowl=l[v]-1,nowr=r[v]+1;
		if(nowl>r[k]||nowr<l[k])
		{
			Get=true;
			return;
		}
		else
		{
			l[k]=max(l[k],nowl);
			r[k]=min(r[k],nowr);
		}
	}
}

void DFS1(int k,int now)
{
	for(int i=head[k];i;i=edge[i].next)
	{
		int v=edge[i].to;
		if(v==fa[k])
			continue;
		if(now+1>=l[v]&&now+1<=r[v])
		{
			A[v]=now+1;
