		g.con(a - 1, b - 1);
	}

	vector<int> depth(n),par(n);
	function<void(int, int)> dfs = [&](int c, int p) {
		par[c] = p;
		depth[c] = p == -1 ? 0 : depth[p] + 1;
		for (auto itr : g.g[c])
			if (itr.first != p)
				dfs(itr.first, c);
	};
	dfs(0, -1);

	vector<pii> num(n, {INT_MAX, INT_MAX});
	vector<int> ev(n, -1);

	int m;
	cin >> m;
	priority_queue<pii, vector<pii> , greater<pii>> pq;
	REP(i, m) {
		int a, b;
		scanf("%d %d", &a, &b);
		--a;
		num[a] = { b,b };
		pq.push(MP(depth[a], a));
		ev[a] = b % 2;
	}
	while (pq.size()) {
		auto cur = pq.top();
		pq.pop();

		if (cur.second == 0)
			continue;

		if (num[par[cur.second]] == MP(INT_MAX, INT_MAX)) {
			num[par[cur.second]] = MP(num[cur.second].first - 1, num[cur.second].second + 1 );
		}
		else {
			int cl = num[cur.second].first - 1, cr = num[cur.second].second + 1, l = num[par[cur.second]].first, r = num[par[cur.second]].second;

			num[par[cur.second]] = { max(cl,l), min(cr,r) };
			if (num[par[cur.second]].first > num[par[cur.second]].second) {
				printf("No\n");
				return 0;
			}
		}
			if (ev[par[cur.second]] != -1) {
				if (ev[par[cur.second]] != (1 - ev[cur.second])) {
					printf("No\n");
					return 0;
				}
			}
			ev[par[cur.second]] = 1 - ev[cur.second];
		if(par[cur.second] != 0)
			pq.push(MP( depth[par[cur.second]],par[cur.second] ));
	}

	printf("Yes\n");
	vector<int> out(n);
	function<void(int, int)> ans = [&](int c, int p) {

		if (p == -1) 
			out[c] = num[c].first;
