const int MAXN = 100005;

int n, m;
vector<int> g[MAXN];

bool hv[MAXN];
int val[MAXN];
bool rng[MAXN];
int L[MAXN], R[MAXN];

void input()
{
	scanf("%d", &n);
	for(int i = 1; i < n; i++)
	{
		int x, y;
		scanf("%d%d", &x, &y);
		g[x].push_back(y);
		g[y].push_back(x);
	}
	scanf("%d", &m);
	for(int i = 1; i <= m; i++)
	{
		int x, v;
		scanf("%d%d", &x, &v);
		hv[x] = 1;
		val[x] = v;
	}
}

bool getrng(int x, int p)
{
	for(auto y: g[x])
	{
		if(y == p) continue;
		if(!getrng(y, x))
			return 0;
		if(rng[y])
		{
			int l = L[y] - 1;
			int r = R[y] + 1;
			if(rng[x])
			{
				if(R[x] < l || L[x] > r || ((L[x] + l) & 1))
					return 0;
				L[x] = max(l, L[x]);
				R[x] = min(r, R[x]);
			}
			else
			{
				rng[x] = 1;
				L[x] = l;
				R[x] = r;
			}
		}
	}
	if(hv[x])
	{
		if(rng[x] && (L[x] > val[x] || val[x] > R[x] || ((L[x] + val[x]) & 1)))
			return 0;
		rng[x] = 1;
		L[x] = R[x] = val[x];
	}
	return 1;
}

void getval(int x, int p)
{
	if(x == 1)
		val[x] = L[x];
	else
	{
		if(L[x] <= val[p] - 1)
			val[x] = val[p] - 1;
		else
			val[x] = val[p] + 1;
	}
	for(auto y: g[x])
		if(y != p)
			getval(y, x);
}

bool ok;

void solve()
{
	ok = getrng(1, 0);
	if(ok) getval(1, 0);
}

void output()
{
	if(ok)
	{
		puts("YES");
		for(int i = 1; i <= n; i++)
			printf("%d\n", val[i]);
	}
	else puts("NO");
}

int main()
{
	input();
	solve();
	output();

	return 0;
}

