  for (int i = 0; i < n; i++) {
    if (num[i] != -1) {
      root = i;
      break;
    }
  }

  vector<lint> l(n);
  vector<lint> r(n);

  function<void(int, int, int)> dfs = [&](int cur, int par, int mod2) {

    // 子に対する答えを計算
    int chSize = 0;
    for (auto nxt : g[cur]) {
      if (nxt == par) continue;
      chSize++;
      dfs(nxt, cur, mod2 ^ 1);
    }

    // 今が葉なら
    if (chSize == 0) {
      if (num[cur] == -1) {
        l[cur] = -INF;
        r[cur] = INF;
      } else {
        l[cur] = num[cur];
        r[cur] = num[cur];
        if (l[cur] % 2 != r[cur] % 2) {
          l[cur] = INF;
          r[cur] = -INF;
        }
      }
    } else {
      lint L = -INF;
      lint R = INF;
      for (auto nxt : g[cur]) {
        if (nxt == par) continue;
        lint chL = l[nxt];
        lint chR = r[nxt];
        L = max(L, chL - 1);
        R = min(R, chR + 1);
      }

      if (num[cur] != -1) {
        L = max(L, num[cur]);
        R = min(R, num[cur]);
      }

      if ((lint)abs(L) % 2 != mod2) {
        L++;
      }

      if ((lint)abs(R) % 2 != mod2) {
        R--;
      }

      if (L > R) {
        L = INF;
        R = -INF;
      }

      l[cur] = L;
      r[cur] = R;
    }
  };

  dfs(root, -1, num[root] % 2);

