      for (auto nxt : g[cur]) {
        if (nxt == par) continue;
        dfs2(nxt, cur);
      }
    };

    dfs2(root, -1);

    for (int i = 0; i < n; i++) {
      cout << ans[i] << endl;
    }

  }
  return 0;
}

