const ll INF = 1LL<<55;
vector<ll> dijkstra(int s){
	priority_queue< pii, vector<pii>, greater<pii> > que;
	vector<ll> d(sz(r), INF);
	d[s] = 0; 
	que.push(pii(0, s));
	while(!que.empty()){
		ll cost, v; tie(cost, v) = que.top();
		que.pop();
		if(d[v] < cost) continue;
		for(const auto& rp : r[v]){ 
			ll rct, rto; tie(rto, rct) = rp;
			if(d[rto] > d[v] + rct){
				d[rto] = d[v] + rct;
				que.push(pii(d[rto], rto));
			}
		}
	}
	return d;
}




