void dfs(int pos,int par){

	//cout<<pos<<"-"<<id[pos]<<endl;
	l[pos]=-MAX-1;
	r[pos]=MAX+1;
	if(id[pos]!=-1){

		l[pos]=r[pos]=id[pos];
	}

	for(int i=0;i<nei[pos].size();i++){
		int to=nei[pos][i];
		if(to!=par){
			dfs(to,pos);

			if(l[to]<-MAX/2){
				//bad
				continue;	
			}

			if(l[pos]<-MAX/2){
				l[pos]=l[to]-1;
				r[pos]=r[to]+1;
			}else{
				if(abs(l[pos])%2==abs(l[to])%2){
					puts("No");
					exit(0);
				}

				l[pos]=max(l[pos],l[to]-1);
				r[pos]=min(r[pos],r[to]+1);
			}
		}
	}

	if(l[pos]>r[pos]){
		puts("No");
		exit(0);
	}
}

void gen(int pos,int par){
	if(pos==0 && id[pos]==-1){
		id[pos]=l[pos];
	}

	for(int i=0;i<nei[pos].size();i++){
		int to=nei[pos][i];
		if(to!=par){
			if(id[to]==-1){
				if(l[to]<=id[pos]-1 && id[pos]-1<=r[to]){
					id[to]=id[pos]-1;
				}else{
					id[to]=id[pos]+1;
				}
			}

			gen(to,pos);
		}


	}
}

