class Graph{
	private:
	int V,root;
	vvi List;
	vi rank,a,L,R;
	void Rank(int v){
		queue<P> q;
		q.push({v,0});
		rank[v]=0;
		while(!q.empty()){
			P p=q.front();
			q.pop();
			int u=p.first;
			for(int i=0;i<List[u].size();i++){
				int w=List[u][i];
				if(rank[w]==-1){
					rank[w]=p.second+1;
					q.push({w,p.second+1});
				}
			}
		}
	}
	void DFS(int v){
		int l=-inf,r=inf;
		for(int i=0;i<List[v].size();i++){
			int u=List[v][i];
			if(rank[v]<rank[u]){
				DFS(u);
				l=max(l,L[u]-1);
				r=min(r,R[u]+1);
			}
		}
		if(a[v]!=-1){
			l=max(l,a[v]);
			r=min(r,a[v]);
		}
		int eo=a[root]%2^rank[v]%2;
		if(l%2!=eo) l++;
		if(r%2!=eo) r--;
		L[v]=l;
		R[v]=r;
	}
	bool dfs(int v,int x){
		if(R[v]<x||x<L[v]) return 1;
		a[v]=x;
		for(int i=0;i<List[v].size();i++){
			int u=List[v][i];
			if(rank[v]<rank[u]){
				if(dfs(u,x-1)) if(dfs(u,x+1)) return 1;
			}
		}
		return 0;
	}
	public:
	Graph(int v){
		V=v;
		List=vvi(v);
	}
	void add_edge(int s,int t){
		List[s].push_back(t);
		List[t].push_back(s);
	}
	void solve(){
		L=R=vi(V);
		a=rank=vi(V,-1);
		int k;
		cin>>k;
		for(int i=0;i<k;i++){
			int v,p;
			cin>>v>>p;
			a[v-1]=p;
