		}
		Rank(root);
		DFS(root);
		if(dfs(root,a[root])) cout<<"No"<<endl;
		else{
			cout<<"Yes"<<endl;
			for(int i=0;i<V;i++) cout<<a[i]<<endl;
		}
	}
};

