int LB[100100], UB[100100], INF = 1<<30;
vector<int> adj[100100];

bool check(int v, int p, int r) {
    if (LB[v] == UB[v] && (LB[v] - r) % 2 != 0) return false;
    for (int u : adj[v]) if (u != p && !check(u, v, 1-r)) return false;
    return true;
}

bool dfs(int v, int p) {
    for (int u : adj[v]) {
        if (u == p) continue;
        if (!dfs(u, v)) return false;
        UB[v] = min(UB[v], UB[u]+1);
        LB[v] = max(LB[v], LB[u]-1);
    }
    return LB[v] <= UB[v];
}

void reconstruct(int v, int p, int val) {
    UB[v] = val;
    for (int u : adj[v]) {
        if (u == p) continue;
        reconstruct(u, v, val+1 <= UB[u] ? val+1 : val-1);
    }
}

