void dfs1(int i){
  used[i] = true;
  for(auto e: edge[i]){
    if(used[e])continue;
    par[e] = i;
    child[i].pb(e);
    dfs1(e);
  }
}

bool dfs2(int i){
  ll lb = - linf, rb = linf;
  for(auto e: child[i]){
    bool b = dfs2(e);
    if(!b)return false;
    lb = max(L[e] - 1, lb);
    if(g.dis[e] < R[e]){
      rb = min(R[e], rb);
    }else{
      rb = min(R[e], rb - 1);
    }
  }
  if(lb > rb)return false;
  if(p[i] == - inf){
    L[i] = lb, R[i] = rb;
  }else{
    int t = (p[r] + g.dis[i] - p[i]) / 2;
    if(!(lb <= t && t <= rb))return false;
    L[i] = t, R[i] = t;
  }
  return true;
}

void dfs3(int i){
  if(i == r){
    cnt[i] = 0;
  }else{
    if(cnt[par[i]] + 1 == L[i]){
      cnt[par[i]] = L[i];
      p[i] = p[par[i]] - 1;
    }else{
      p[i] = p[par[i]] + 1;
    }
  }
  for(auto e: child[i]){
    dfs3(e);
  }
}

