		if (l <= tl && tr <= r) return t[v];
		if (tl > r || tr < l) return inf;
		int tm = tl + tr >> 1;
		return min(get(l, r, v << 1, tl, tm), get(l, r, v << 1 | 1, tm + 1, tr));
