int n;
int dep[MAXN], dfn[MAXN], piv;
int val[MAXN], par[MAXN];
vector<int> gph[MAXN];
int minv[MAXN], actually[MAXN];

void solve(int x, int p){
	minv[x] = 2e9;
	if(x != p && val[x] != -1){
		minv[x] = val[x];
		return;
	}
	for(auto &i : gph[x]){
		if(i != par[x]){
			solve(i, p);
			minv[x] = min(minv[x], minv[i]);
		}
	}
}

void go(int x, int p){
	for(auto &i : gph[x]){
		if(i != par[x]){
			if(actually[i]) continue;
			if(minv[i] > val[x]){
				val[i] = val[x] + 2;
			}
			else val[i] = val[x];
			go(i, p);
		}
	}
}

void dfs(int x, int p){
	dfn[x] = ++piv;
	for(auto &i : gph[x]){
		if(i != p){
			par[i] = x;
			dep[i] = dep[x] + 1;
			dfs(i, x);
		}
	}
}

