    if(tmp==2) return -2;
    if(ret==-1&&tmp==0) ret = 1;
    if(ret==-1&&tmp==1) ret = 0;
    if(ret!=-1&&ret==tmp) return -2;
  }
  oe[now] = ret;
  return ret;
}
