using namespace utils;

class solver{
    istream& is;
    ostream& os;
    E_Set E;
    vector<ll> vL, vR;
    vector<bool> odd;

public:
    solver(istream& I, ostream& O) :is(I), os(O) {}

    bool odd_even(int v, int p = -1, bool t = false){
        if(vL[v] != -INF){
            odd[v] = vL[v] % 2 ;
            if(p != -1 and (t != odd[v])){
                return false;
            }
            t = odd[v];
        }
        else{
            odd[v] = t;
        }
        for (auto &&u : E[v]) {
            if(u == p) continue;
            if(!odd_even(u, v, !t)) return false;
        } // end u
        return true;
    }

    bool dfs(int v, int p){
        for (auto &&u : E[v]) {
            if(u == p) continue;
            if(!dfs(u, v)) return false;
            auto r = vR[u];
            auto l = vL[u];
            min_update(vR[v], r+1);
            max_update(vL[v], l-1);
        } // end i
        if((abs(vL[v]) % 2) != odd[v]) vL[v]++;
        if((abs(vR[v]) % 2) != odd[v]) vR[v]--;

        return vL[v] <= vR[v];
    }

    bool det_answer(int v, ll l, ll r, int p = -1){
        vL[v] = max(l, vL[v]);
        vR[v] = min(r, vR[v]);
        if((abs(vL[v]) % 2) != odd[v]) vL[v]++;
        if((abs(vR[v]) % 2) != odd[v]) vR[v]--;
        if(vL[v] > vR[v]) return false;
        for (auto &&u : E[v]) {
            if(u == p) continue;
            if(!det_answer(u, vL[v]-1, vR[v]+1, v)) return false;
        } // end u
        return true;
    }


    void run(){
        ll N;
        is >> N;
        if(!is) return;
        vL.resize(N, -INF);
        vR.resize(N, INF);
        for (int i = 0; i < N - 1; ++i) {
            int a, b; is >> a >> b; a--;b--;
            E[a].insert(b); E[b].insert(a);
        } // end i
        ll K;
        is >> K;
