bool dfs1(int s, int par){
	if (v[s] != -1){
		dp_min[s][v[s] & 1] = dp_max[s][v[s] & 1] = v[s];
		unset_dp(s, (v[s] & 1) ^ 1);
	}
	REP(i, 0, SZ(g[s])){
		int to = g[s][i];
		if (to != par){
			if (!dfs1(to, s)){
				return false;
			}
			REP(j, 0, 2){
				if (dp_min[to][j] > dp_max[to][j]){
					unset_dp(s, j ^ 1);
				}
				dp_min[s][j ^ 1] = max(dp_min[s][j ^ 1], dp_min[to][j] - 1);
				dp_max[s][j ^ 1] = min(dp_max[s][j ^ 1], dp_max[to][j] + 1);
			}
		}
	}
	//printf("%d %d %d %d %d\n", s, dp_min[s][0], dp_min[s][1], dp_max[s][0], dp_max[s][1]);
	return dp_min[s][0] <= dp_max[s][0] || dp_min[s][1] <= dp_max[s][1];

}

void dfs2(int s, int par){
	int ind, val;
	if (dp_min[s][0] <= dp_max[s][0]){
		ind = 0;
