	ans[s] = dp_min[s][ind];
	REP(i, 0, SZ(g[s])){
		int to = g[s][i];
		if (to != par){
			unset_dp(to, ind);
			dp_min[to][ind ^ 1] = max(dp_min[to][ind ^ 1], ans[s] - 1);
			dp_max[to][ind ^ 1] = min(dp_max[to][ind ^ 1], ans[s] + 1);
			dfs2(to, s);
		}
	}
}

