void dfs2(int n){
	visited[n] = 1;
	int ma = inf,mi = -inf;
	for(int i=0;i<v[n].size();i++){
		int s = v[n][i];
		if(visited[s]==0){
			int s = v[n][i];
			dfs2(s);
			if(ma<A[s]-1 || B[s]+1<mi) judge = false;
			else if(A[s]-1<=mi && ma<=B[s]+1) continue;
			else if(mi<=A[s]-1 && B[s]+1<=ma){
				ma = B[s]+1;
				mi = A[s]-1;
			}
			else if(B[s]+1>=mi){
//				mi = max(A[s]-1,mi);
				ma = B[s]+1;
//				ma = min(B[s]+1,ma);
			}else{
				mi = A[s]-1;
			}
			if(ma<mi) judge = false;
		}
	}
	if(ma==mi && ma%2!=even[n]) judge = false; 
	if(ma!=inf){
		B[n] = ma;
		A[n] = mi;
	}
}

void write(int n,int t){
	visited[n] = 1;
	if(A[n]==B[n]) ans[n] = A[n];
	else if(A[n]==-inf) ans[n] = t+1;
	else if(t<A[n]) ans[n] = A[n];
	else if(t>B[n]) ans[n] = B[n];
	else{
		if(t+1<=B[n]) ans[n] = t+1;
		else ans[n] = t-1;
	}
	for(int i=0;i<v[n].size();i++){
		int s = v[n][i];
		if(visited[s]==0){
			write(s,ans[n]);
		}
	}
}

