		l[v]=max(l[v],l[to]-1);
		r[v]=min(r[v],r[to]+1);
	}
	if(known[v]==1)
	{
		l[v]=max(l[v],val[v]);
		r[v]=min(r[v],val[v]);
		known_parity[v][val[v]%2]=1;
	}
	if(known_parity[v][0] == 1 && known_parity[v][1] == 1) shit=1;
	if(l[v] > r[v]) shit = 1;
	order.pb(v);
}

int solve_val(int v,int par)
{
	if(par == 0) return l[v];
	l[v] = max(l[v],ans[par] - 1);
	r[v] = max(r[v],ans[par] + 1);
	while(l[v] % 2 == ans[par] % 2) ++l[v];
	return l[v];
}

