void dfs( int u, int fa, int odd ) {
	if( aa[u] != oo ) {
		dp[u][0] = dep[u] - aa[u];
		dp[u][1] = dep[u] + aa[u];
//		if( (aa[u] & 1) != odd ) no();
	} else {
		dp[u][0] = dp[u][1] = oo;
	}
	for( int t = 0; t < (int)g[u].size(); t++ ) {
		int v = g[u][t];
		if( v == fa ) continue;
		dep[v] = dep[u] + 1;
		dfs( v, u, odd ^ 1 );
		dp[u][0] = min( dp[u][0], dp[v][0] );
		dp[u][1] = min( dp[u][1], dp[v][1] );
	}
//	if( aa[u] != oo && (dp[u][0] < dep[u] - aa[u] || dp[u][1] < dep[u] + aa[u]) ) no();
}
void dfs2( int u, int fa ) {
	for( int t = 0; t < (int)g[u].size(); t++ ) {
		int v = g[u][t];
		if( v == fa ) continue;
		if( aa[v] == oo ) {
			if( dp[u][0] < dp[u][1] ) {
				aa[v] = aa[u] + 1;
			} else {
				aa[v] = aa[u] - 1;
			}
		}
		dfs2( v, u );
	}
}
