struct CWW {
    int l, r, parity;
    CWW() : l(-inf), r(inf), parity(-1) {}
    CWW(int _l, int _r, int _parity) : l(_l), r(_r), parity(_parity) {}
    void print() {
        cout << l << " " << r << " " << parity << endl;
    }
};

const CWW dameCWW = CWW(inf, -inf, -1);

vector<CWW> cww;
Graph G;
vector<int> ans;

bool dame(const CWW& c) {
    return c.l > c.r;
}

CWW merge(const CWW& c1, const CWW& c2) {
    if (dame(c1) || dame(c2)) return dameCWW;
    if (c1.parity == -1 && c2.parity != -1) {
        return c2;
    }
    if (c1.parity != -1 && c2.parity == -1) {
        return c1;
    }
    if (c1.parity == -1 && c2.parity == -1) {
        return CWW();
    }
    if (c1.parity != c2.parity) return dameCWW;
    CWW tmp = CWW(max(c1.l, c2.l), min(c1.r, c2.r), c1.parity);
    if (dame(tmp)) return dameCWW;
    return tmp;
}

CWW expand(const CWW& c) {
    if (c.parity == -1) return c;
    return CWW(c.l - 1, c.r + 1, c.parity^1);
}

CWW dfs(int now, int pre, CWW preCWW) {
    CWW hereCWW = merge(cww[now], preCWW);
    CWW childCWW;
    for (auto nxt : G[now]) {
        if (nxt == pre) continue;
        childCWW = merge(childCWW, dfs(nxt, now, expand(hereCWW)));
    }

    cww[now] = merge(hereCWW, childCWW);
    return expand(cww[now]);
}

void dfs2(int now, int pre, int pre_x) {
    int x;
    if (pre == -1) {
        x = cww[now].l;
    } else {
        if (cww[now].l <= pre_x + 1 && pre_x + 1 <= cww[now].r) {
            x = pre_x + 1;
        } else if (cww[now].l <= pre_x - 1 && pre_x - 1 <= cww[now].r) {
            x = pre_x - 1;
        } else {
            assert(false);
        }
    }
    ans[now] = x;
    for (auto nxt : G[now]) {
        if (nxt == pre) continue;
        dfs2(nxt, now, x);
    }

}

