const int INF = 1e9;

using Weight = int;
using Capacity = int;
struct Edge {
    int src, dst; Weight weight;
    Edge(int s, int d, Weight w) : src(s), dst(d), weight(w) {}
};
using Edges = vector<Edge>;
using Graph = vector<Edges>;
using Array = vector<Weight>;
using Matrix = vector<Array>;

pair<int,int> BAD = {+INF, -INF};

int n;
Graph g;
int k;

int num[100010];

bool pality_check(int u, int p, int x){
    if(num[u] != -1 && num[u]%2 != x){
        return false;
    }

    for(auto &e : g[u]){
        int v = e.dst;
        if(v == p) continue;
        if(!pality_check(v, u, 1-x)){
            return false;
        }
    }

    return true;
}

int lb[100010], ub[100010];

pair<int,int> get_range(int u, int p){
    int mi = -INF;
    int ma = INF;
    for(auto &e : g[u]){
        int v = e.dst;
        if(v == p) continue;
        int tmi, tma;
        tie(tmi, tma) = get_range(v, u);
        mi = max(mi, tmi);
        ma = min(ma, tma);
    }

    --mi;
    ++ma;

    pair<int,int> res;
    if(mi > ma){
        res = BAD;
    } else {
        if(num[u] != -1) res = make_pair(num[u], num[u]);
        else             res = make_pair(mi, ma);
    }

    tie(lb[u], ub[u]) = res;
    return res;
}

void paint(int u, int p, int pc){
    int c = lb[u] <= pc-1 && pc-1 <= ub[u] ? pc-1 : pc+1;
    num[u] = c;
    for(auto &e : g[u]){
        int v = e.dst;
        if(v == p) continue;
        paint(v, u, c);
    }
}

