            --x; --y;
            g[x].emplace_back(x,y,1);
            g[y].emplace_back(y,x,1);
        }
        cin >> k;
        rep(i,k){
            int v,p;
            cin >> v >> p;
            --v;
            num[v] = p;
        }

        bool yes = true;
        rep(i,n){
            if(num[i] != -1){
                if(!pality_check(i, -1, num[i]%2)){
                    yes = false;
                    break;
                }

                pair<int,int> res = get_range(i, -1);

                if(res == BAD){
                    yes = false;
                    break;
                }

                paint(i, -1, lb[i]-1);
                break;
            }
        }

        if(!yes){
            cout << "No" << endl;
        } else {
            cout << "Yes" << endl;
            rep(i,n) cout << num[i] << '\n';
        }
    }
}

