typedef long long ll;
const int INF = 1 << 28;

vector<int> G[100000];
int mod[100000];
int X[100000];
int d[100000];
int l[100000];
int r[100000];

int main() {
	cin.tie(0);
	ios::sync_with_stdio(false);

	int N, K;
	cin >> N;
	for(int i = 0; i < N - 1; i++) {
		int A, B;
		cin >> A >> B;
		A--, B--;
		G[A].push_back(B);
		G[B].push_back(A);
	}
	cin >> K;
	fill(X, X + N, INF);
	fill(d, d + N, INF);
	fill(l, l + N, -INF);
	fill(r, r + N, INF);

	queue<int> q;
	for(int i = 0; i < K; i++) {
		int V;
		cin >> V;
		V--;
		cin >> X[V];
		mod[V] = X[V] % 2;
		q.push(V);
		d[V] = 0;
		l[V] = r[V] = X[V];
	}

	while(q.size()) {
		int v = q.front();
		q.pop();
		for(auto c : G[v]) {
			if(d[c] == INF) {
				d[c] = d[v] + 1;
				q.push(c);
				mod[c] = 1 - mod[v];
			}
			else {
				if(mod[c] == mod[v]) {
					cout << "No" << endl;
					return 0;
				}
			}
			l[c] = max(l[c], l[v] - 1);
			r[c] = min(r[c], r[v] + 1);
			if(l[c] > r[c]) {
				cout << "No" << endl;
				return 0;
			}
		}
	}

	int max_d = *max_element(d, d + N);
	typedef pair<int, int> P;
	priority_queue<P> pq;
	for(int i = 0; i < N; i++) {
		if(d[i] == 0) continue;
		if(d[i] == max_d) {
			X[i] = l[i];
		}
		else {
			pq.push(P(d[i], i));
		}
	}

	while(pq.size()) {
		int v = pq.top().second;
		pq.pop();
		map<int, int> t;
		int cnt = 0;
		for(auto c : G[v]) {
			if(d[c] == d[v] + 1) {
				cnt++;
				t[X[c] + 1]++;
				t[X[c] - 1]++;
			}
		}
		for(auto p : t) {
			if(p.second != cnt) continue;
			if(l[v] <= p.first && p.first <= r[v]) {
				X[v] = p.first;
				break;
			}
		}
		assert(X[v] != INF);
	}

	cout << "Yes" << endl;
	for(int i = 0; i < N; i++) {
		cout << l[i] << endl;
	}
}

