inline void merge(int x,int y)
{
	if(F[y][0]==-100000000) return;
	if(F[x][0]==-100000000)
	{
		F[x][0]=F[y][0]-1,F[x][1]=F[y][1]+1;
		return ;
	}
	if(!((F[x][0]&1)^(F[y][0]&1)))
	{
		fg=1; return ;
