vector<int> g[100010],order;
int d[100010],anss[100010],r[100010],l[100010],par[100010],n,k;
bool ans;

void solve(int v,int p)
{
	l[v]=-INF-1;r[v]=INF+1;
	if(d[v]!=-1){
		l[v]=d[v];
		r[v]=d[v];
	}
	for(int i=0;i<g[v].size();i++){
		int nx=g[v][i];
		if(nx!=p){
			par[nx]=v;
			solve(nx,v);
			if(l[nx]<-INF/2) continue;
			if(l[v]<-INF/2){
				l[v]=l[nx]-1;
				r[v]=r[nx]+1;
			}
			else{
				if(abs(l[nx])%2==abs(l[v])%2){
					ans=true;
					return;
				}
				l[v]=max(l[v],l[nx]-1);
				r[v]=min(r[v],r[nx]+1);
			}
		}
	}
	if(l[v]>r[v]){
		ans=true;
	}
	order.push_back(v);
}

int make_it(int v,int pr)
{
	if(pr==0) return l[v];
	l[v]=max(l[v],anss[pr]-1);
	r[v]=min(r[v],anss[pr]+1);
	while(l[v]%2==anss[pr]%2) l[v]++;
	return l[v];
}

