int deg[100005];

void AddEdge(int u, int v) {
	next[++ed] = head[u]; head[u] = ed; to[ed] = v;
}

pii DFS(int now, int fa, int L, int R) {
	if (vis[now]) L = R = ans[now];
	pii tmp;
	for (int i = head[now]; i; i = next[i]) {
		if (to[i] == fa) continue;
		tmp = DFS(to[i], now, L - 1, R + 1);
		L = std::max(L, tmp.first - 1);
		R = std::min(R, tmp.second + 1);
		if (L > R) {
			puts("No"); exit(0);
		}
	}
	ans[now] = L;
	return mp(L, R);
}

