void init() {
    for(int i=1; i<=n; i++) {
        p[i].val = -1;
        p[i].fail=false;
        p[i].has = false;
    }
}

void cal(int u,int fa) {
    for(int i=0; i<e[u].size(); i++) {
        int v = e[u][i];
        if(v==fa)continue;
        cal(v,u);
        if(p[v].fail){
            p[u].fail=true;
            return;
        }
        if(p[v].has){
            if(!p[u].has){
                p[u].has=true;
                p[u].l=p[v].l-1,p[u].r=p[v].r+1;
            } else {
                if(abs(p[u].l-p[v].l+1)&1){
                    p[u].fail=true;
                    return;
                }
                if(p[u].l>p[v].r+1||p[v].l-1>p[u].r){
                    p[u].fail=true;
                    return;
                }
                p[u].l=max(p[u].l,p[v].l-1);
                p[u].r=min(p[u].r,p[v].r+1);
            }
        }
    }
}

void dfs(int u,int fa){
    if(fa==0){
        p[u].val=p[u].l;
    } else {
        if(p[u].has){
            if(p[fa].val-1>=p[u].l&&p[fa].val-1<=p[u].r){
                p[u].val=p[fa].val-1;
            } else p[u].val=p[fa].val+1;
        } else {
            p[u].val=p[fa].val+1;
        }
    }
    for(int i=0;i<e[u].size();i++){
        int v=e[u][i];
        if(v==fa)continue;
        dfs(v,u);
    }
}

