constexpr int INF = LIM<>::max() / 2;

VI value_range( const VVI &G, const VI &V, const VI &P, const int sgn, VI &odd_even )
{
	const int N = SZ( G ), K = SZ( V );

	VI values( N, 0 < sgn ? INF : -INF );
	priority_queue< PII > que;
	REP( i, K )
	{
		values[ V[i] ] = P[i];
		que.EM( P[i] * -1 * sgn, V[i] );
		odd_even[ V[i] ] |= 1 << ( P[i] % 2 );
	}

	while ( !que.empty() )
	{
		const int val = que.top().fst;
		const int u = que.top().snd;
		que.pop();

		odd_even[u] |= 1 << ( val % 2 );

		if ( val * -1 * sgn != values[u] )
		{
			continue;
		}

		FOR( v, G[u] )
		{
			if ( 0 < sgn ? chmin( values[v], values[u] + sgn ) : chmax( values[v], values[u] + sgn ) )
			{
				que.EM( values[v] * -1 * sgn, v );
			}
		}
	}

	return move( values );
}

void coloring( const VVI &G, const VI &val_min, const VI &val_max, const int u, const int p, VI &res, const int prev = -1 )
{
	res[u] = p;

	FOR( v, G[u] )
	{
		for ( const int np : { p - 1, p + 1 } )
		{
			if ( v != prev && val_min[v] <= np && np <= val_max[v] )
			{
				coloring( G, val_min, val_max, v, np, res, u );
				break;
			}
		}
	}

	return;
}

int main()
{
	cin.tie( 0 );
	ios::sync_with_stdio( false );
	cout << setprecision( 12 ) << fixed;

	int N;
	scanf( "%d", &N );

	VVI G( N );
	REP( N - 1 )
	{
		int u, v;
		scanf( "%d%d", &u, &v );
		--u, --v;
		G[u].PB( v );
		G[v].PB( u );
	}

	int K;
	scanf( "%d", &K );

	VI V( K ), P( K );
	REP( i, K )
	{
		scanf( "%d%d", &V[i], &P[i] );
		--V[i];
	}

	VI odd_even( N );
	const VI val_min = value_range( G, V, P, -1, odd_even ), val_max = value_range( G, V, P, 1, odd_even );

	REP( i, N )
	{
		if ( val_max[i] < val_min[i] || odd_even[i] == 3 )
		{
			puts( "No" );
			fflush( stdout );
			return 0;
		}
	}

	VI res( N );
	coloring( G, val_min, val_max, V[0], P[0], res );

	puts( "Yes" );
	FOR( r, res )
	{
		printf( "%d\n", r );
	}
	fflush( stdout );

	return 0;
}

