ll INF = 1e18;
ll n;
vpll adj[200005]; 
ll dist[200005], bw[200005], val[200005];
void dijkstra(ll src){
	for (ll i = 0; i <= n; i++) dist[i] = INF; dist[src] = 0;                    
  	priority_queue <pll, vpll, greater <pll>> pq; 
	pq.push(mp(0LL, src));
  	while (!pq.empty()){        
    	pll fr = pq.top(); pq.pop();   
    	ll d = fr.fi, u = fr.se;
    	if (d == dist[u]){
      		for (ll j = 0; j < adj[u].size(); j++){
        		pll v = adj[u][j];                      
        		if (dist[u] + v.se < dist[v.fi]){
          			dist[v.fi] = dist[u] + v.se;               
          			pq.push(mp(dist[v.fi], v.fi));
  				}   
			}
		}
	} 
}
void dfs(ll u, ll p){
	bw[u] = 1 - bw[p];
	for (ll i = 0; i < adj[u].size(); i++){
		ll v = adj[u][i].fi; if (v == p) continue; dfs(v, u);
	}
}
int main(){
	// one of the other weird problems on Atcoder ._.
	// this is implement-heavy, but at least a lot better than Codeforces...
	cin >> n; 
	for (ll i = 0; i <= n; i++) val[i] = -1;
	for (ll i = 0; i < n - 1; i++){
		ll u, v; cin >> u >> v;
		adj[u].pb(mp(v, 1LL)); adj[v].pb(mp(u, 1LL));
	}
	dfs(1, 1); // finding black-white
	ll k; cin >> k;
	ll tp = -1;
	for (ll i = 0; i < k; i++){
		ll v, p; cin >> v >> p; val[v] = p;
		adj[0].pb(mp(v, p)); adj[v].pb(mp(0, p));
		if (tp == -1) tp = (p % 2) ^ bw[v];
		else{
			ll t = (p % 2) ^ bw[v];
			if (t == tp) continue;
			else{
				cout << "No\n"; return 0;
			}
		}
	}
	dijkstra(0);
	for (ll i = 1; i <= n; i++){
		if (dist[i] < val[i]){
			cout << "No\n"; return 0;
 		}
		val[i] = dist[i];
		ll x = bw[i] ^ tp; x ^= val[i]; x %= 2;
		if (x) val[i]--;
	}
	for (ll i = 1; i <= n; i++){
		for (ll j = 0; j < adj[i].size(); j++){
			ll v = adj[i][j].fi; if (v == 0) continue;
			if (abs(val[i] - val[v]) != 1){
				cout << "No\n"; return 0;
			}
		}
	}
	cout << "Yes\n";
	for (ll i = 1; i <= n; i++) cout << val[i] << endl;
}

