using namespace std;

int n, k;
int res[N], l[N], r[N], ty[N];

vector < int > G[N];

void dfs(int ,int);
void solve(int ,int);

int main(){
	scanf("%d", &n);
	for(int i = 1; i < n; ++i){
		int u, v; scanf("%d%d", &u, &v);
		G[u].pb(v); G[v].pb(u);
	}
	scanf("%d", &k); memset(ty, -1, sizeof ty);
	for(int i = 1; i <= k; ++i){
		int v, p; scanf("%d%d", &v, &p);
		res[v] = l[v] = r[v] = p; ty[v] = p & 1;
	}
	for(int i = 1; i <= n; ++i){
		if(ty[i] != -1) continue;
		l[i] = -(N + N); r[i] = N + N;
	}
	dfs(1, 0); solve(1, 0); puts("Yes");
	for(int i = 1; i <= n; ++i)
		printf("%d\n", l[i]);
	return 0;
}

void dfs(int u, int fa){
	if(ty[fa] != -1){
		l[u] = max(l[fa] - 1, l[u]); 
		r[u] = min(r[u], r[fa] + 1);
		ty[u] = ty[fa] ^ 1;
	}
	int sz = G[u].size();
	for(int i = 0; i < sz; ++i){
		int v = G[u][i];
		if(v == fa) continue;
		dfs(v, u);
		l[u] = max(l[v] - 1, l[u]);
		r[u] = min(r[u], r[v] + 1);
		if(ty[u] == -1) ty[u] = ty[v] ^ 1;
		else if(ty[u] != (ty[v] ^ 1)){
			puts("No"); exit(0);
		}
	}
	if(l[u] > r[u]){
		puts("No"); exit(0);
	}
	return ;
}

void solve(int u, int fa){
	if((l[u] & 1) != ty[u]) ++l[u];
	l[u] = r[u]; int sz = G[u].size();
	for(int i = 0; i < sz; ++i){
		int v = G[u][i];
		if(v == fa) continue;
		l[v] = max(l[u] - 1, l[v]); r[v] = min(r[u] + 1, r[v]);
		solve(v, u);
	}
	return ;
}

#include<bits/stdc++.h>
int co[100010],L[100010],R[100010];
std::vector<int>edge[100010];
bool ok,vi[100010];
bool in[100010];
void dfs(int x){
    if(co[x]!=0){
        L[x]=R[x]=co[x];
        in[x]=true;
    }
    for(int k=0;k<edge[x].size();k++){
        int y=edge[x][k];
        if(vi[y]) continue;
        vi[y]=true;
        dfs(y);
        if(!in[y]) continue;
        if(!in[x]){
            in[x]=true;
            L[x]=L[y]-1;
            R[x]=R[y]+1;
        }
        else{
            int p,q;
            p=L[y]-1;q=R[y]+1;
            if((L[x]-p)%2!=0) ok=false;
            L[x]=std::max(L[x],p);
            R[x]=std::min(R[x],q);
            if(L[x]>R[x]) ok=false;
        }
    }
    return;
}
void print(int x){
    co[x]=L[x];
    for(int k=0;k<edge[x].size();k++){
        int y=edge[x][k];
        if(vi[y]) continue;
        vi[y]=true;
        if(!in[y]){
            L[y]=L[x]-1;
            R[y]=R[x]+1;
            in[y]=true;
        }
        else{
            L[y]=std::max(L[y],L[x]-1);
            R[y]=std::min(R[y],R[x]+1);
        }
        print(y);
    }
    return;
}
