    for(k=1;k<=m;k++){
        scanf("%d%d",&d,&c);
        co[d]=c;
    }
    ok=true;
    vi[1]=true;
    dfs(1);
    //for(k=1;k<=n;k++) printf("%d %d %d\n",k,L[k],R[k]);
    if(!ok){
        puts("No");
        return 0;
    }
    puts("Yes");
    memset(vi,0,sizeof(vi));
