int fa[N], dep[N];

int v[N], p[N];
int l[N], r[N];

void dfs(int a) {
  for (int i = 0; i < adj[a].size(); ++i) {
    int b = adj[a][i];
    if (b != fa[a]) {
      fa[b] = a;
      dep[b] = dep[a] + 1;
      dfs(b);
      l[a] = std::max(l[a], l[b] - 1);
      r[a] = std::min(r[a], r[b] + 1);
    }
  }
}

void solve(int a) {
  for (int i = 0; i < adj[a].size(); ++i) {
    int b = adj[a][i];
    if (b != fa[a]) {
      l[b] = std::max(l[b], l[a] - 1);
      r[b] = std::min(r[b], r[a] + 1);
      solve(b);
    }
  }
}

bool flag;

int val[N];

void get(int a) {
  val[a] = INF;
  for (int i = l[a]; i <= r[a]; ++i) {
    if (((i + dep[a]) & 1) == flag) {
      val[a] = i;
      break;
    }
  }
  for (int i = 0; i < adj[a].size(); ++i) {
    int b = adj[a][i];
    if (b != fa[a]) {
      l[b] = std::max(l[b], val[a] - 1);
      r[b] = std::min(r[b], val[a] + 1);
      get(b);
    }
  }
}

