const int Max = 1e5 + 5;

PLL cond[Max]; // 1
PLL adje[Max]; // 2
LL fnl[Max]; // 3
const PLL ERROR = PLL(LINF, -LINF);
// adgeのparityは満たされるものだけをつくるとする
// O(N)
void f1(int v, int p, bool pari, const VVI& G) {
	if (cond[v].second - cond[v].first == 0) {
		// 値が決まっている場合
	}
	else { // そうではない
		// 親のcondをみて、自身の区間を決定する
		// parityいらなくないか
		cond[v].first = cond[p].first - 1;
		cond[v].second = cond[p].second + 1;
	}

	PLL rg = PLL(-INF, INF);
	for (int nx : G[v]) {
		if (nx == p)continue;
		f1(nx, v, !pari, G);
		// merge
		rg.first = max(rg.first, adje[nx].first);
		rg.second = min(rg.second, adje[nx].second);
		if (rg.first > rg.second) {
			break;
		}
	}
	if (rg.first>rg.second) { // NO
		adje[v] = ERROR;
	}
	else {
		// rg∧condを満たす区間があるならばその最大範囲を持つ
		rg.first--, rg.second++;
		adje[v].first = max(rg.first, cond[v].first);
		adje[v].second = min(rg.second, cond[v].second);
		if (adje[v].first > adje[v].second) {
			adje[v] = ERROR;
		}
	}

}

void f2(int v, int p, const VVI&G) {
	// adje,pからfnlが決定される
	if (p != -1) {
		int val = fnl[p];
		if (adje[v].first <= val + 1 && val + 1 <= adje[v].second) {
			fnl[v] = val + 1;
		}
		else if (adje[v].first <= val - 1 && val - 1 <= adje[v].second) {
			fnl[v] = val - 1;
		}
		else {
			assert(0);
		}
	}
	for (int nx : G[v]) {
		if (nx == p)continue;
		f2(nx, v, G);
	}
}


