    if(a[u] != -1){
        mi = a[u], mx = a[u];
    }
    int x = mi;
    for(auto v : G[u]){
        if(v == f) continue;
        x = dfs(v, u, mi - 1, mx + 1);
        if(x == INF) return x;
        if(x < mi - 1 || x > mx + 1){
            ok = 0;
            return INF;
        }
        if(a[u] == -1) Max(mi, x - 1);
        if(a[u] == -1) Min(mx, x + 1);
    }
    if(a[u] != -1) return a[u];
    a[u] = mi;
    return mi;
}
