#define MAX_N 200005
vector<int> pre_G[MAX_N];
vector<int> G[MAX_N];
int par[MAX_N];
int flag_netsukigi[MAX_N];
void make_netsukigi(int r){
    queue<int> que;
    que.push(r);
    flag_netsukigi[r] = 1;
    par[r] = -1;

    while(que.size() > 0){
        int x = que.front();
        que.pop();
        flag_netsukigi[x] = 1;
        rep(i,pre_G[x].size()){
            if(flag_netsukigi[pre_G[x][i]] == 0){
                par[pre_G[x][i]] = x;
                G[x].push_back(pre_G[x][i]);
                que.push(pre_G[x][i]);
            }
        }
    }
}

int is_free[MAX_N] = {};
int l[MAX_N] = {};
int r[MAX_N] = {};
int ans[MAX_N] = {};

void dfs(int x){
    if(G[x].size() == 0){
        ; // 葉
    }else{
        rep(i,G[x].size()){
            if(is_free[G[x][i]] == 0){
                ans[G[x][i]] = ans[x] - 1;
                dfs(G[x][i]);
            }else{
                l[G[x][i]] = max(l[G[x][i]], ans[x] - 1);
                r[G[x][i]] = min(r[G[x][i]], ans[x] + 1);
                ans[G[x][i]] = l[G[x][i]];
                dfs(G[x][i]);
            }
        }
    }
}

int main() {
    int n;
    cin >> n;


    rep(i,n-1){
        int a, b;
        scanf("%d%d", &a, &b);
        a--; b--; // 0-indexにするため.
        pre_G[a].push_back(b);
        pre_G[b].push_back(a);
    }

    make_netsukigi(0);


    int count_sons[MAX_N] = {};
    queue<int> que;
    rep(i,n){
        if(G[i].size() == 0){ // 葉かどうか.
            que.push(i);
        }
    }



    int k;
    cin >> k;
    rep(i,k){
        int v, p;
        scanf("%d%d", &v, &p);
        v--; // 0-indexにするため.
        if(p%2==1){
            is_free[v] = 1;
        }else{
            is_free[v] = 2;
        }
        l[v] = p;
        r[v] = p;
    }

    // Yes No 判定
    while(que.size() > 0){
        int x = que.front();
        que.pop();
        if(par[x] == -1)continue;
        if(count_sons[x] < G[x].size())continue;
        count_sons[par[x]]++;
        if(is_free[x] != 0){
            if(is_free[par[x]] == 0){
                if(is_free[x] == 1){
                    is_free[par[x]] = 2;
                }else{
                    is_free[par[x]] = 1;
                }
                l[par[x]] = l[x] - 1;
                r[par[x]] = r[x] + 1;
            }else{
                if(is_free[x] == is_free[par[x]]){
                    cout << "No" << endl;
                    return 0;
                }
                if(l[x] % 2 == l[par[x]] % 2)l[par[x]]++;
                if(r[x] % 2 == r[par[x]] % 2)r[par[x]]--;
                l[par[x]] = max(l[par[x]], l[x] - 1);
                r[par[x]] = min(r[par[x]], r[x] + 1);
                if(r[par[x]] < l[par[x]]){
                    cout << "No" << endl;
                    return 0;
                }
            }
        }
    }

    // 逆伝播
    ans[0] = l[0];
    dfs(0);

    cout << "Yes" << endl;
    rep(i,n){
        printf("%d\n", ans[i]);
    }

    return 0;
}

#include <cstdio>
#include <algorithm>
int N, __K__, head[100001], next[199999], to[199999], E, q[100001], fa[100001];
int p[100001], w[100001], g[100001], L[100001], R[100001];
int main()
{
	scanf("%d", &N);
	for (int i = 1, u, v; i < N; i++)
	{
		scanf("%d%d", &u, &v);
		next[++E] = head[u], to[E] = v, head[u] = E;
		next[++E] = head[v], to[E] = u, head[v] = E;
	}
	for (scanf("%d", &__K__); __K__--; )
	{
		int x, y;
		scanf("%d%d", &x, &y);
		p[x] = 1;
		w[x] = y;
	}
	int H = 0, T = 1, u;
	q[1] = 1;
	while (H < T)
		for (int e = head[u = q[++H]]; e; e = next[e])
			if (to[e] != fa[u])
				fa[q[++T] = to[e]] = u;
	for (int i = N; i; i--)
	{
		int u = q[i];
		int appear_0 = 0, L_0 = -1000000000, R_0 = 1000000000;
		int appear_1 = 0, L_1 = -1000000000, R_1 = 1000000000;
		for (int e = head[u]; e; e = next[e])
			if (to[e] != fa[u] && g[to[e]])
			{
				if (L[to[e]] & 1)
				{
					appear_1 = 1;
					L_1 = std::max(L_1, L[to[e]]);
					R_1 = std::min(R_1, R[to[e]]);
				}
				else
				{
					appear_0 = 1;
					L_0 = std::max(L_0, L[to[e]]);
					R_0 = std::min(R_0, R[to[e]]);
				}
			}
		if (appear_0 && appear_1)
		{
			puts("No");
			return 0;
		}
		if (!appear_0 && !appear_1)
		{
			if (p[u])
			{
				g[u] = 1;
				L[u] = R[u] = w[u];
			}
			else
				g[u] = 0;
		}
		else
		{
			if (appear_0)
			{
				L[u] = L_0 - 1;
				R[u] = R_0 + 1;
			}
			else
			{
				L[u] = L_1 - 1;
				R[u] = R_1 + 1;
			}
			if (L[u] > R[u])
			{
				puts("No");
				return 0;
			}
			if (p[u])
			{
				if (w[u] < L[u] || w[u] > R[u] || (w[u] ^ L[u]) & 1)
				{
					puts("No");
					return 0;
				}
				L[u] = R[u] = w[u];
			}
			g[u] = 1;
		}
	}
	for (int i = 1; i <= N; i++)
	{
		int u = q[i];
		if (p[u])
			continue;
		if (u == 1)
			w[u] = L[u];
		else if (!g[u])
			w[u] = w[fa[u]] + 1;
		else if (L[u] <= w[fa[u]] + 1 && w[fa[u]] + 1 <= R[u])
			w[u] = w[fa[u]] + 1;
		else
			w[u] = w[fa[u]] - 1;
	}
	puts("Yes");
	for (int i = 1; i <= N; i++)
		printf("%d\n", w[i]);
	return 0;
}

