using namespace std;

typedef pair<long long, long long> range;

bool ok = true;
#define l first
#define r second

int n, k;	
vector<int> g[100005];
range a[100005];
bool vis[100005];
int h[100005];

bool mergerange(range& a, range b) {
	if (a.l > b.r+1 || a.r < b.l-1) return false;
	if (b.l > a.r+1 || b.r < a.l-1) return false;
	if (a.l == -INT_MAX) {
		a.l = b.l-1;
		a.r = b.r+1;
		return true;
	}
	if ((a.l + b.l-1) % 2 != 0) ok = false;
	range na, nb;
	na = {max(a.l, b.l-1), min(a.r, b.r+1)};
	a = na;
	return true;
}

void dfs(int u) {
	vis[u] = 1;
	for (auto v : g[u]) {
		if (!vis[v]) {
			dfs(v);
			if (a[v].l != -INT_MAX) ok &= mergerange(a[u], a[v]);
		}
	}
}

void getres(int u) {
	vis[u] = 1;
	for (auto v : g[u]) {
		if (!vis[v]) {
			if (h[u]-1 >= a[v].l && h[u]-1 <= a[v].r) {
				h[v] = h[u]-1;
			}
			else {
				h[v] = h[u]+1;
			}
			getres(v);
		}
	}
}

