const int V_MAX = 100000;

int V;
vector<int> G[V_MAX];
int last = 0;

void add_edge(int from, int to) {
  G[from].push_back(to);
  G[to].push_back(from);
}

//------------------------------------------------------------------------------
const int N_MAX = 100000;
const int K_MAX = N_MAX;
const int INF = 1e9;

struct node {
  int b, l, r;
};

int N;
int K;

int v0, p0;
node a[N_MAX];

void dump() {
  REP(i, N) {
    printf("v: %d, b: %d, l: %d, r: %d\n",
      i, a[i].b, a[i].l, a[i].r);
  }
}

bool check_parity(int p, int v, int b) {
  if (a[v].b >= 0) {
    if (a[v].b != b) return false;
  } else {
    a[v].b = b;
  }
  REP(i, G[v].size()) {
    int u = G[v][i];
    if (u == p) continue;
    if (!check_parity(v, u, 1 - b)) {
      return false;
    }
  }
  return true;
}

bool update_range(int v, int l, int r) {
  int l2 = max(a[v].l, l);
  int r2 = min(a[v].r, r);
  if (l2 > r2) return false;
  a[v].l = l2; a[v].r = r2;
  return true;
}

bool check_range(int p, int v, int l, int r) {
  if (!update_range(v, l, r)) return false;
  REP(i, G[v].size()) {
    int u = G[v][i];
    if (u == p) continue;
    if (!check_range(v, u, l - 1, r + 1)) return false;
    if (!update_range(v, a[u].l - 1, a[u].r + 1)) return false;
  }
  return true;
}

void fix_value(int p, int v, int l) {
  a[v].l = max(a[v].l, l);
  REP(i, G[v].size()) {
    int u = G[v][i];
    if (u == p) continue;
    fix_value(v, u, a[v].l - 1);
  }
}

void solve() {
  bool ret;
  ret = check_parity(-1, v0, p0 % 2);
  if (!ret) {
    puts("No");
    return;
  }

  ret = check_range(-1, v0, p0, p0);
  if (!ret) {
    puts("No");
    return;
  }

  puts("Yes");
  fix_value(-1, v0, p0);
  // dump();

  REP(i, N) printf("%d\n", a[i].l);
}

void input() {
  scanf("%d", &N);
  V = N;
  REP(i, N - 1) {
    int a, b;
    scanf("%d%d", &a, &b);
    add_edge(a - 1, b - 1);
  }
  REP(i, N) a[i] = { -1, -INF, INF };
  scanf("%d", &K);
  REP(i, K) {
    int v, p;
    scanf("%d%d", &v, &p);
    if (i == 0) {
      v0 = v - 1;
      p0 = p;
    }
    a[v - 1] = { p % 2, p, p };
  }
}

int main() {
  input();
  solve();
  return 0;
}

