void dfs(int u,int p){
	if(a[u]!=-1) l[u]=r[u]=a[u];
	else l[u]=-INF,r[u]=INF;
	FOR(i,0,g[u].size()){
		int v=g[u][i];
		if(v==p) continue;
		dfs(v,u);
		if(l[v]<=-INF/2) continue;
		if(l[u]<=-INF/2){
			l[u]=l[v]-1;r[u]=r[v]+1;
		}else{
			if(abs(l[u])&1==abs(l[v])&1) ans=false;
			l[u]=max(l[u],l[v]-1);
			r[u]=min(r[u],r[v]+1);
		}
	}
	if(l[u]>r[u]) ans=false;
	return;
}

void solve(int u,int p){
	if(!u&&a[u]==-1) a[u]=l[u];
	FOR(i,0,g[u].size()){
		int v=g[u][i];
		if(v==p) continue;
		if(a[v]==-1){
			if(l[v]<=a[u]-1&&r[v]>=a[u]-1) a[v]=a[u]-1;
			else a[v]=a[u]+1;
		}
		solve(v,u);
	}
	return;
}

