void dfs(int x,int fa)
{
	if (!bo) return;
	int k,v,bo2=0;
	for (k=first[x];k;k=net[k])
	{
		v=zhi[k];
		if (v==fa) continue;
		dfs(v,x);
		p[x]|=p[v];
	}
	if (a[x]!=-1) p[x]=1;
	if (!bo) return;
	if (!p[x]) return;
	if (a[x]!=-1)
		bo2=1,l1[x]=r1[x]=a[x];
	for (k=first[x];k;k=net[k])
	{
		v=zhi[k];
		if (v==fa) continue;
		if (!p[v]) continue;
		if (!bo2)
		{
			bo2=1;
			l1[x]=l1[v]-1;
			r1[x]=r1[v]+1;
		} else
		{
			if (l1[v]-1>r) {bo=0;return;}
			if (r1[v]+1<l) {bo=0;return;}
			if (l1[x]%2!=(l1[v]-1)%2) {bo=0;return;}
			l1[x]=max(l1[x],l1[v]-1);
			r1[x]=min(r1[x],r1[v]+1);
			if (l1[x]>r1[x]) {bo=0;return;}
		}
	}
}
void solve(int x,int fa)
{
