typedef long long ll;
typedef long double ld;
typedef vector<int> vi;
typedef vector<string> vs;
typedef pair<int, int> pii;
const int MOD = 1000000007;
const int INF = MOD + 1;
const int init = INT32_MAX;
const ld EPS = 1e-12;
template<class T> T &chmin(T &a, const T &b) { return a = min(a, b); }
template<class T> T &chmax(T &a, const T &b) { return a = max(a, b); }

/*--------------------template--------------------*/

void out(bool f, vi v = {})
{
	if (!f) cout << "No" << endl;
	else cout << "Yes" << endl;
	for (auto i : v) cout << i << endl;
	exit(0);
}

vector<vi> tree;
vi dep;
vector<pii> range;

pii dfs(int v)
{
	pii res;
	if (range[v].first != init) res = range[v];
	else res = pii(-INF, INF);
	for (auto i : tree[v])
	{
		pii tmp = dfs(i);
		chmax(res.first, tmp.first - 1);
		chmin(res.second, tmp.second + 1);
	}
	if (res.first > res.second) out(false);
	return range[v] = res;
}

int main()
{
	cin.sync_with_stdio(false); cout << fixed << setprecision(10);
	int n; cin >> n;
	vector<vi> t(n);
	REP(i, n - 1)
	{
		int a, b; cin >> a >> b;
		a--; b--;
		t[a].push_back(b);
		t[b].push_back(a);
	}
	tree.resize(n);
	queue<int> que;
	que.push(0);
	vector<bool> vis(n);
	dep.resize(n);
	vis[0] = true;
	while (!que.empty())
	{
		int a = que.front(); que.pop();
		for (auto i : t[a])
		{
			if(vis[i]) continue;
			vis[i] = true;
			que.push(i);
			tree[a].push_back(i);
			dep[i] = dep[a] + 1;
		}
	}
	range.resize(n, pii(init, init));
	int k; cin >> k;
	int check;
	bool f = true;
	REP(i, k)
	{
		int v, p; cin >> v >> p;
		v--;
		range[v] = pii(p, p);
		if(i == 0) check = (dep[v] + p) % 2;
		else
		{
			if (check != (dep[v] + p) % 2) f = false;
		}
	}
	if (!f) out(f);
	dfs(0);
	while (!que.empty()) que.pop();
	que.push(0);
	vi ans(n);
	ans[0] = range[0].first;
	while (!que.empty())
	{
		int v = que.front();
		que.pop();
		int tmp = ans[v];
		for (auto i : tree[v])
		{
			if (tmp + 1 >= range[i].first && tmp + 1 <= range[i].second)
			{
				ans[i] = tmp + 1;
			}
			else if (tmp - 1 >= range[i].first && tmp - 1 <= range[i].second)
			{
				ans[i] = tmp - 1;
			}
			else assert(false);
			que.push(i);
		}
	}
	out(true, ans);
	return 0;
}

