using namespace std;
using ll = long long;
constexpr ll INF = 3000000000000000000;

constexpr int ushi = 100000000;

int main() {
    int n;
    cin >> n;
    vector<int> P(n, ushi);
    vector<vector<int>> G(n);
    REP(i, n - 1) {
        int a, b;
        cin >> a >> b;
        --a; --b;
        G[a].push_back(b);
        G[b].push_back(a);
    }
    int k;
    cin >> k;
    REP(i, k) {
        int v, p;
        cin >> v >> p;
        --v;
        P[v] = p;
    }

    vector<int> par(n, -1), vec;
    queue<int> q;
    q.push(0);
    while (!q.empty()) {
        int u = q.front();
        q.pop();
        for (int v : G[u]) {
            if (v != par[u]) {
                par[v] = u;
                q.push(v);
            }
        }
        vec.push_back(u);
    }
    reverse(ALL(vec));

    vector<pair<int, int>> range(n, {-ushi, ushi});
    for (int u : vec) {
        if (P[u] != ushi) range[u] = {P[u], P[u]};
        for (int v : G[u]) {
            if (v == par[u]) continue;
            if (range[v].first == -ushi) continue;
            if ((range[u].first & 1) == (range[v].first & 1) && range[u].first != -ushi) {
                cout << "No\n";
                return 0;
            }
            range[u].first = max(range[u].first, range[v].first - 1);
            range[u].second = min(range[u].second, range[v].second + 1);
            if (range[u].first > range[u].second) {
                cout << "No\n";
                return 0;
            }
        }
    }

    vector<int> ans(n, ushi);
    reverse(ALL(vec));
    for (int v : vec) {
        if (v == 0) {
            ans[v] = range[v].first;
        } else {
            if (ans[par[v]] + 1 >= range[v].first && ans[par[v]] + 1 <= range[v].second) {
                ans[v] = ans[par[v]] + 1;
            } else {
                ans[v] = ans[par[v]] - 1;
            }
        }
    }

    cout << "Yes\n";
    REP(i, n) cout << ans[i] << "\n";
    return 0;
}

#include<stdio.h>
