    min[u]=MAX(min[u],min[i]-1);
    max[u]=MIN(max[u],max[i]-1);
  }
  for(i=0;i<n;i++){
    for(j=0;j<child[i]->len;j++){
      int u;
      getAt(child[i],j,&u);
      min[u]=MAX(min[u],min[i]-1);
      max[u]=MIN(max[u],max[i]+1);
    }
  }
  for(i=0;i<n;i++){
    if(min[i]>max[i] || (max[i]-min[i])%2){
      printf("No\n");
      return;
    }
  }
  printf("Yes\n");
