int main()
{
	const int sup = 1 << 30, inf = -sup;
	int i, N, K, u, w, l[100001], r[100001];
	list *adj[100001] = {}, e[200001];
	scanf("%d", &N);
	for (i = 0; i < N - 1; i++) {
		scanf("%d %d", &u, &w);
		e[i*2].v = w;
		e[i*2+1].v = u;
		e[i*2].next = adj[u];
		e[i*2+1].next = adj[w];
		adj[u] = &(e[i*2]);
		adj[w] = &(e[i*2+1]);
	}
	scanf("%d", &K);
	for (i = 1; i <= N; i++) {
		l[i] = inf;
		r[i] = sup;
	}
	for (i = 1; i <= K; i++) {
		scanf("%d", &u);
		scanf("%d", &(l[u]));
		r[u] = l[u];
	}

	int par[100001] = {}, q[100001], head, tail;
	list *p;
	par[1] = 1;
	q[0] = 1;
	for (head = 0, tail = 1; head < tail; head++) {
		u = q[head];
		for (p = adj[u]; p != NULL; p = p->next) {
			w = p->v;
			if (par[w] == 0) {
				par[w] = u;
				q[tail++] = w;
			}
		}
	}
	for (head--; head > 0; head--) {
		u = q[head];
		if (l[u] == inf) continue;
		if (l[par[u]] == inf) {
			l[par[u]] = l[u] - 1;
			r[par[u]] = r[u] + 1;
		} else if ((l[par[u]] + l[u]) % 2 != 0) {
			l[par[u]] = (l[u] - 1 > l[par[u]])? l[u] - 1: l[par[u]];
			r[par[u]] = (r[u] + 1 < r[par[u]])? r[u] + 1: r[par[u]];
			if (l[par[u]] > r[par[u]]) break;
		} else break;
	}
	if (head > 0) {
		printf("No\n");
		fflush(stdout);
		return 0;
	}

	for (head++; head < tail; head++) {
		u = q[head];
		if (l[u] == inf) l[u] = l[par[u]] + 1;
		else if (l[par[u]] + 1 >= l[u] && l[par[u]] + 1 <= r[u]) l[u] = l[par[u]] + 1;
		else l[u] = l[par[u]] - 1;
	}
	printf("Yes\n");
	for (i = 1; i <= N; i++) printf("%d\n", l[i]);
	fflush(stdout);
	return 0;
}

