  int i;
  for(i=0;i<v;i++)ta[i]=-1;
  for(i=0;i<e;i++){
    nt[i  ]=ta[to[i+e]=a[i]];
    nt[i+e]=ta[to[i  ]=b[i]];
    co[ta[b[i]]=i+e]=co[ta[a[i]]=i]=c[i];
  }
}
void dijk(int v,int mi){
  for(i=0;i<v;i++)CO[i]=1000000000;
  CO[mi]=0;
  while(f[mi]-1){
