		int[] ub = new int[n];
		int[] lb = new int[n];
		ArrayList<Integer>[] tree = new ArrayList[n];
		for(int i=0;i<n;i++) {
			tree[i] = new ArrayList<>();
		}
		for(int i=0;i<n-1;i++) {
			int a = io.nextInt() - 1;
			int b = io.nextInt() - 1;
			tree[a].add(b);
			tree[b].add(a);
		}
		Arrays.fill(ub, INF);
		Arrays.fill(lb, -INF);
		int k = io.nextInt();
		for(int i=0;i<k;i++) {
			int v = io.nextInt() - 1;
			int p = io.nextInt();
			ub[v] = lb[v] = p;
		}
		int s1 = randInt(0,n-1);
		dfsUp(s1,-1,n,ub,lb,tree);
		dfsDown(s1,-1,n,ub,lb,tree);
		int s = -1;
		for(int i=0;i<n;i++) {
			if (ub[i] < lb[i]) {
				System.out.println("No");
				return;
			}
			if (ub[i] == lb[i]) {
				s = i;
			}
		}
		int[] ans = new int[n];
		ans[s] = lb[s];
		dfsDown2(s, -1, n, ans, ub, lb, tree);
		if (fail) {
			System.out.println("No");
			return;
		}
		io.println("Yes");
		for(int i=0;i<n;i++) {
			io.println(ans[i]);
		}
		io.flush();
	}

	public int randInt(int min,int max) {
		return (int) (Math.random() * (max - min + 1)) + min;
	}

	public void dfsUp(int v,int p,int n,int[] ub,int[] lb,ArrayList<Integer>[] tree) {
		for(int c: tree[v]) {
			if (c == p) continue;
			dfsUp(c, v, n, ub, lb, tree);
			ub[v] = Math.min(ub[v], ub[c] + 1);
			lb[v] = Math.max(lb[v], lb[c] - 1);
		}
	}

	public void dfsDown(int v,int p,int n,int[] ub,int[] lb,ArrayList<Integer>[] tree) {
		for(int c: tree[v]) {
			if (c == p) continue;
			ub[c] = Math.min(ub[c], ub[v] + 1);
			lb[c] = Math.max(lb[c], lb[v] - 1);
			dfsDown(c, v, n, ub, lb, tree);
		}
	}

	public boolean fail = false;
	public void dfsDown2(int v,int p,int n,int[] ans,int[] ub,int[] lb,ArrayList<Integer>[] tree) {
		for(int c: tree[v]) {
			if (c == p) continue;
			boolean ok = false;
			for(int k=-1;k<=1;k+=2) {
				int next = ans[v] + k;
				if (lb[c] <= next && next <= ub[c]) {
					ans[c] = next;
					ok = true;
					break;
				}
			}
			if (!ok) {
				fail = true;
				return;
			}
			dfsDown2(c, v, n, ans, ub, lb, tree);
			if (fail) {
				return;
			}
		}
	}

}
class IO extends PrintWriter {
	private final InputStream in;
	private final byte[] buffer = new byte[1024];
	private int ptr = 0;
	private int buflen = 0;

	public IO() { this(System.in);}
	public IO(InputStream source) { super(System.out); this.in = source;}
	private boolean hasNextByte() {
		if (ptr < buflen) {
			return true;
		}else{
			ptr = 0;
			try {
				buflen = in.read(buffer);
			} catch (IOException e) {
				e.printStackTrace();
			}
			if (buflen <= 0) {
				return false;
			}
		}
		return true;
	}
	private int readByte() { if (hasNextByte()) return buffer[ptr++]; else return -1;}
	private static boolean isPrintableChar(int c) { return 33 <= c && c <= 126;}
	private static boolean isNewLine(int c) { return c == '\n' || c == '\r';}
	public boolean hasNext() { while(hasNextByte() && !isPrintableChar(buffer[ptr])) ptr++; return hasNextByte();}
	public boolean hasNextLine() { while(hasNextByte() && isNewLine(buffer[ptr])) ptr++; return hasNextByte();}
	public String next() {
		if (!hasNext()) {
			throw new NoSuchElementException();
		}
		StringBuilder sb = new StringBuilder();
		int b = readByte();
		while(isPrintableChar(b)) {
			sb.appendCodePoint(b);
			b = readByte();
		}
		return sb.toString();
	}
	public char[] nextCharArray(int len) {
		if (!hasNext()) {
			throw new NoSuchElementException();
		}
		char[] s = new char[len];
		int i = 0;
		int b = readByte();
		while(isPrintableChar(b)) {
			if (i == len) {
				throw new InputMismatchException();
			}
			s[i++] = (char) b;
			b = readByte();
		}
		return s;
	}
	public String nextLine() {
		if (!hasNextLine()) {
			throw new NoSuchElementException();
		}
		StringBuilder sb = new StringBuilder();
		int b = readByte();
		while(!isNewLine(b)) {
			sb.appendCodePoint(b);
			b = readByte();
		}
		return sb.toString();
	}
	public long nextLong() {
		if (!hasNext()) {
			throw new NoSuchElementException();
		}
		long n = 0;
		boolean minus = false;
		int b = readByte();
		if (b == '-') {
			minus = true;
			b = readByte();
		}
		if (b < '0' || '9' < b) {
			throw new NumberFormatException();
		}
		while(true){
			if ('0' <= b && b <= '9') {
				n *= 10;
				n += b - '0';
			}else if(b == -1 || !isPrintableChar(b)){
				return minus ? -n : n;
			}else{
				throw new NumberFormatException();
			}
			b = readByte();
		}
	}
	public int nextInt() {
		long nl = nextLong();
		if (nl < Integer.MIN_VALUE || nl > Integer.MAX_VALUE) {
			throw new NumberFormatException();
		}
		return (int) nl;
	}
	public char nextChar() {
		if (!hasNext()) {
			throw new NoSuchElementException();
		}
		return (char) readByte();
	}
	public double nextDouble() { return Double.parseDouble(next());}
	public int[] nextIntArray(int n) { int[] a = new int[n]; for(int i=0;i<n;i++) a[i] = nextInt(); return a;}
	public long[] nextLongArray(int n) { long[] a = new long[n]; for(int i=0;i<n;i++) a[i] = nextLong(); return a;}
	public double[] nextDoubleArray(int n) { double[] a = new double[n]; for(int i=0;i<n;i++) a[i] = nextDouble(); return a;}
	public void nextIntArrays(int[]... a) { for(int i=0;i<a[0].length;i++) for(int j=0;j<a.length;j++) a[j][i] = nextInt();}
	public int[][] nextIntMatrix(int n,int m) { int[][] a = new int[n][]; for(int i=0;i<n;i++) a[i] = nextIntArray(m); return a;}
	public char[][] nextCharMap(int n,int m) { char[][] a = new char[n][]; for(int i=0;i<n;i++) a[i] = nextCharArray(m); return a;}
	public void close() { super.close(); try {in.close();} catch (IOException e) {}}
}

import java.io.PrintWriter;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Scanner;

public class Main {
	static class Tree {
		public class Edge {
			int to, rev;

			public Edge(int to, int rev) {
				this.to = to;
				this.rev = rev;
			}
		}

		int V;
		ArrayList<ArrayList<Edge>> G;
		int root;
		int[] p;
		int[] min;
		int[] max;
		int[] evenOdd;

		public Tree(int[] a, int[] b) {
			this.V = a.length+1;
			p = new int[V];
			min = new int[V];
			max = new int[V];
			evenOdd = new int[V];

			Arrays.fill(min, -10000000);
			Arrays.fill(max, 10000000);

			G = new ArrayList<ArrayList<Edge>>();
			for(int i=0; i<V; i++) {
				G.add(new ArrayList<Edge>());
			}

			for(int i=0; i<V-1; i++) {
				G.get(a[i]).add(new Edge(b[i], G.get(b[i]).size()));
				G.get(b[i]).add(new Edge(a[i], G.get(a[i]).size()-1));
			}
			setRoot(0);
		}

		public void setRoot(int root) {
			this.root = root;
			setRoot(root, -1);
		}
		public void setRoot(int cur, int parent) {
			p[cur] = parent;
			for(int i=0; i<G.get(cur).size(); i++) {
				int next = G.get(cur).get(i).to;
				if(next!=parent) {
					setRoot(next, cur);
				}
			}
		}
		public boolean check() {
			if(!check(0))
				return false;
			setRecursive(0, min[0], min[0]);
			return true;
		}
		public void set(int i, int v) {
			min[i] = max[i] = v;
			evenOdd[i] = v%2==0 ? 2 : 1;
		}

		boolean check(int i) {
			boolean[] eo = new boolean[3];
			for(Edge e : G.get(i)) {
				if(e.to==p[i])
					continue;
				if(!check(e.to))
					return false;
				min[i] = Math.max(min[i], min[e.to]-1);
				max[i] = Math.min(max[i], max[e.to]+1);
				eo[evenOdd[e.to]] = true;
			}
			if(evenOdd[i]!=0)
				eo[3-evenOdd[i]] = true;
			if(eo[1] && eo[2])
				return false;
			evenOdd[i] = eo[1] ? 2 : (eo[2] ? 1 : 0);
			return min[i]<=max[i];
		}
		void setRecursive(int i, int x1, int x2) {
			if(min[i]<=x1 && x1<=max[i])
				min[i] = max[i] = x1;
			else
				min[i] = max[i] = x2;

			for(Edge e : G.get(i)) {
				if(e.to==p[i])
					continue;
				setRecursive(e.to, min[i]-1, min[i]+1);
			}
		}

	}

	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);
		PrintWriter pw = new PrintWriter(System.out);

		int N = sc.nextInt();

		int[] a = new int[N-1];
		int[] b = new int[N-1];
		for(int i=0; i<N-1; i++) {
			a[i] = sc.nextInt()-1;
			b[i] = sc.nextInt()-1;
		}

		Tree tree = new Tree(a, b);

		int K = sc.nextInt();
		for(int i=0; i<K; i++) {
			int V = sc.nextInt()-1;
			int P = sc.nextInt();
			tree.set(V, P);
		}

		if(tree.check()) {
			pw.println("Yes");
			for(int i=0; i<N; i++)
				pw.println(tree.min[i]);
		} else {
			pw.println("No");
		}

		sc.close();
		pw.close();
	}

}

