    static ArrayList<Integer> g[];
    static int v[];
    static Point pv[];
    static boolean isValid(Point p){
        if(p.x>p.y)
            return false;
        return true;
    }
    static boolean isInfinite(Point a){
        return a.x==Integer.MIN_VALUE&&a.y==Integer.MAX_VALUE;
    }
    static void merge(Point a, Point b, int chng){
        if(isInfinite(a)&&!isInfinite(b)){
            a.x=b.x-chng;
            a.y=b.y+chng;
            return;
        }else if(isInfinite(b)){
            return;
        }else{
            if(a.x%2!=(b.x-chng)%2){
              a.x=0;a.y=-1;
              return;
            }
            if(((b.x-chng)>a.y)||(a.x>(b.y+chng))){
                a.x=0;
                a.y=-1;
                return;
            }
            a.x=Math.max(a.x,b.x-chng);
            a.y=Math.min(a.y,b.y+chng);
            if(!isValid(a)){
                a.x=0;a.y=-1;
                return;
            }                
        }
    }
    static Point sol(int nd, int p, Point parV){
        //if node already has a value
        if(v[nd]!=0){
            pv[nd]=new Point(v[nd], v[nd]);
            merge(pv[nd], parV,1);
            if(!isValid(pv[nd]))
                return pv[nd];
        }
        else{
            pv[nd]=new Point(Integer.MIN_VALUE, Integer.MAX_VALUE);
            merge(pv[nd], parV,1);
        }
        for(int nn:g[nd]){
            if(nn==p)
                continue;
            Point nnv=sol(nn,nd,pv[nd]);
            if(!isValid(nnv))
            {
                pv[nd]=new Point(0,-1);
              break;
            }
            merge(pv[nd],nnv,1);
            if(!isValid(pv[nd]))
                break;
        }
        return pv[nd];
    }
    static void fill(int nd, int p, Point parV){
        //if node doesnot have a value create value
        if(v[nd]==0){
            merge(pv[nd], parV, 1);
            if(isInfinite(pv[nd]))
                v[nd]=0;
            else
                v[nd]=pv[nd].x;
        }
        pv[nd]=new Point(v[nd],v[nd]);
        for(int nn:g[nd]){
            if(nn!=p){
                fill(nn,nd,pv[nd]);
            }
        }
    }
    static void solve() throws IOException
    {
        Scanner in=new Scanner(System.in);
        PrintWriter out=new PrintWriter(System.out);
        int n=in.nextInt();
        g=new ArrayList[n+1];
        for(int i=0;i<=n;i++)
            g[i]=new ArrayList<>();
        for(int i=1;i<n;i++){
            int u=in.nextInt();
            int v=in.nextInt();
            g[u].add(v);
            g[v].add(u);
        }
        v=new int[n+1];
        pv=new Point[n+1];
        for(int i=in.nextInt();i>0;i--){
            v[in.nextInt()]=in.nextInt();
        }
        if(isValid(sol(1,0, new Point(Integer.MIN_VALUE, Integer.MAX_VALUE)))){
            out.println("Yes");
            fill(1,0, new Point(Integer.MIN_VALUE, Integer.MAX_VALUE));
            for(int i=1;i<=n;i++)
                out.println(v[i]);

        }
        else{
            out.println("No");
        }

        out.close();

    }
