import java.io.*;
import java.lang.*;
import java.util.*;

public class Main {

	static boolean debug = false;

	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);
		int N = sc.nextInt();
		Tree tree = new Tree(N);
		for (int j = 0; j < N - 1; j++) {
			int x = sc.nextInt(), y = sc.nextInt();
			tree.insert(x - 1, y - 1);
			tree.insert(y - 1, x - 1);
		}
		int K = sc.nextInt(), start = 0;
		Color[] color = new Color[N];
		for (int j = 0; j < K; j++) {
			int v = sc.nextInt();
			color[v - 1] = new Color(sc.nextInt(), 1);
			start = v - 1;
		}
		if (solve(tree, color, -1, start)) {
			System.out.println("Yes");
			for (int j = 0; j < N; j++)
				System.out.println(color[j].start);
		}
		else
			System.out.println("No");
	}

	private static boolean solve(Tree tree, Color[] color, int parent, int node) {
		if (debug) System.out.println(String.format("solve(tree, color, %d, %d)", parent, node));
		if (color[node] == null)
			color[node] = color[parent].expand();
		Node child = tree.first(node);
		while (child != null) {
			if (child.node != parent) {
				if (!solve(tree, color, node, child.node))
					return false;
				color[node] = merge(color[node], color[child.node]);
				if (color[node] == null)
					return false;
			}
			child = tree.next(child);
		}
		return true;
	}

	private static Color merge(Color current, Color child) {
		if (debug) System.out.println(String.format("merge(current: [%d, %d] with child: [%d, %d])",
			current.start, current.count, child.start, child.count));
		Color merge;
		if (current.start % 2 == child.start % 2)
			merge = null;
		Color expand = child.expand();
		// check colors intercept.
		/*if (expand.start > current.start + 2 * (current.count - 1)
			|| current.start > expand.start + 2 * (expand.count - 1))
			merge = null;*/
		int start = Math.max(expand.start, current.start);
		int end = Math.min(current.start + 2 * (current.count - 1), expand.start + 2 * (expand.count - 1));
		merge = new Color(start, (end - start + 2) / 2);
		if (merge.count <= 0)
			merge = null;
		if (debug) System.out.println(merge != null ? String.format("merge result: [%d, %d]", merge.start, merge.count) : "merge result: [null]");
		return merge;
	}

	static class Color {
		int start, count;

		public Color(int start, int count) {
			this.start = start;
			this.count = count;
		}

		public Color expand() {
			 return new Color(start - 1, count + 1);
		}
	}

	static class Tree {

		private Node[] tree;
		private int[] last;
		private int current;

		public Tree(int N) {
			tree = new Node[2 * N + 1];
			last = new int[N];
			current = 1;
		}

		public Node next(Node node) {
			return node.next > 0
				? tree[node.next]
				: null;
		}
		public Node first(int node) {
			return tree[last[node]];
		}

		public void insert(int x, int y) {
			tree[current] = new Node(x, last[y]);
			last[y] = current;
			current++;
		}

	}
	static class Node {
		int node, next;

		public Node(int node, int next) {
			this.node = node;
			this.next = next;
		}
	}

}

import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.InputMismatchException;
import java.util.NoSuchElementException;

public class Main implements Runnable {
	public static final int INF = 1 << 29;

	public static void main(String[] args) {
		new Thread(null, new Main(), "", 16L * 1024 * 1024).start();
	}

	int n;
	ArrayList<Integer>[] tree;
	int k;
	int[] v,p;
	int[] ub,lb,ans;

	@SuppressWarnings("unchecked")
	public void run() {
		IO io = new IO();
		n = io.nextInt();
		ub = new int[n];
		lb = new int[n];
		tree = new ArrayList[n];
		for(int i=0;i<n;i++) {
			tree[i] = new ArrayList<>();
		}
		for(int i=0;i<n-1;i++) {
			int a = io.nextInt() - 1;
			int b = io.nextInt() - 1;
			tree[a].add(b);
			tree[b].add(a);
		}
		k = io.nextInt();
		v = new int[k];
		p = new int[k];
		for(int i=0;i<k;i++) {
			v[i] = io.nextInt() - 1;
			p[i] = io.nextInt();
		}
		ans = new int[n];
		ArrayList<Integer> ans = null;
		ArrayList<Integer> uso = new ArrayList<>();
		for(int i=0;i<n;i++) {
			uso.add(i);
		}
		Collections.shuffle(uso);
		int max = Math.min(50, n);
		for(int i=0;i<max;i++) {
			ans = solve(uso.get(i));
			if (ans != null) break;
		}
		if (ans == null) {
			System.out.println("No");
		}else{
			io.println("Yes");
			for(int x: ans) {
				io.println(x);
			}
			io.flush();
		}
	}

	public ArrayList<Integer> solve(int s1) {
		Arrays.fill(ub, INF);
		Arrays.fill(lb, -INF);
		Arrays.fill(ans, 0);
		for(int i=0;i<k;i++) {
			ub[v[i]] = lb[v[i]] = p[i];
		}
		dfsUp(s1,-1);
		dfsDown(s1,-1);
		int s = -1;
		for(int i=0;i<n;i++) {
			if (ub[i] < lb[i]) {
				return null;
			}
			if (ub[i] == lb[i]) {
				s = i;
			}
		}
		ans[s] = lb[s];
		fail = false;
		dfsDown2(s, -1);
		if (fail) {
			return null;
		}
		for(int i=0;i<n;i++) {
			for(int j: tree[i]) {
				if (Math.abs(ans[i] - ans[j]) != 1) {
					return null;
				}
			}
		}
		ArrayList<Integer> al = new ArrayList<>();
		for(int i=0;i<n;i++) {
			al.add(ans[i]);
		}
		return al;
	}

	public int randInt(int min,int max) {
		return (int) (Math.random() * (max - min + 1)) + min;
	}

	public void dfsUp(int v,int p) {
		for(int c: tree[v]) {
			if (c == p) continue;
			dfsUp(c, v);
			ub[v] = Math.min(ub[v], ub[c] + 1);
			lb[v] = Math.max(lb[v], lb[c] - 1);
		}
	}

	public void dfsDown(int v,int p) {
		for(int c: tree[v]) {
			if (c == p) continue;
			ub[c] = Math.min(ub[c], ub[v] + 1);
			lb[c] = Math.max(lb[c], lb[v] - 1);
			dfsDown(c, v);
		}
	}

	public boolean fail = false;
	public void dfsDown2(int v,int p) {
		for(int c: tree[v]) {
			if (c == p) continue;
			boolean ok = false;
			for(int k=-1;k<=1;k+=2) {
				int next = ans[v] + k;
				if (lb[c] <= next && next <= ub[c]) {
					ans[c] = next;
					ok = true;
					break;
				}
			}
			if (!ok) {
				fail = true;
				return;
			}
			dfsDown2(c, v);
			if (fail) {
				return;
			}
		}
	}

