/**
 * @author https://atcoder.jp/users/suisen
 * 
 * Queue for int type.
 */
final class IntQueue implements Iterable<Integer> {
    private static final int DEFAULT_SIZE = 64;
    private int[] q;
    private int head = 0, tail = 0;
    public IntQueue(final int capacity) {this.q = new int[capacity];}
    public IntQueue() {this(DEFAULT_SIZE);}
    public int peek() {
        if (head == tail) throw new NoSuchElementException("No Elements.");
        return q[head];
    }
    public int getFromHead(int index) {
        if (head + index >= tail || index < 0) throw new NoSuchElementException("Index out of bounds.");
        return q[head + index];
    }
    public int getFromTail(int index) {
        if (head + index >= tail || index < 0) throw new NoSuchElementException("Index out of bounds.");
        return q[tail - 1 - index];
    }
    public void add(final int v) {
        if (tail == q.length) grow();
        q[tail++] = v;
    }
    public void add(final int... vals) {for (int v : vals) add(v);}
    public int poll() {
        if (head == tail) throw new NoSuchElementException("No Elements.");
        int ret = q[head++];
        if (head == tail) head = tail = 0;
        else if (head >= 1e7) relocate();
        return ret;
    }
    private void relocate() {
        final int[] newQ = new int[q.length];
        System.arraycopy(q, head, newQ, 0, tail - head);
        q = newQ;
        tail -= head;
        head = 0;
    }
    public int size() {return tail - head;}
    public void clear() {head = tail = 0;}
    private void grow() {
        final int[] grown = new int[q.length << 1];
        final int len = size();
        System.arraycopy(q, head, grown, 0, len);
        q = grown;
        tail = len;
        head = 0;
    }
    public PrimitiveIterator.OfInt iterator() {return new IntQueueIterator();}
    private class IntQueueIterator implements PrimitiveIterator.OfInt {
        private int i = head;
        public boolean hasNext() {return i < tail;}
        public int nextInt() {return q[i++];}
    }
}

import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.InputMismatchException;
import java.util.NoSuchElementException;

public class Main implements Runnable {
	public static final int INF = 1 << 29;

	public static void main(String[] args) {
		throw new RuntimeException();
		//new Thread(null, new Main(), "", 16L * 1024 * 1024).start();
	}

	int n;
	ArrayList<Integer>[] tree;
	int k;
	int[] v,p;
	int[] ub,lb,ans;

	@SuppressWarnings("unchecked")
	public void run() {
		IO io = new IO();
		n = io.nextInt();
		ub = new int[n];
		lb = new int[n];
		tree = new ArrayList[n];
		for(int i=0;i<n;i++) {
			tree[i] = new ArrayList<>();
		}
		for(int i=0;i<n-1;i++) {
			int a = io.nextInt() - 1;
			int b = io.nextInt() - 1;
			tree[a].add(b);
			tree[b].add(a);
		}
		boolean path = true;
		for(int i=0;i<n;i++) {
			if (tree[i].size() > 2) {
				path = false;
			}
		}
		if (path) {
			System.out.println("No");
			return;
		}
		k = io.nextInt();
		v = new int[k];
		p = new int[k];
		for(int i=0;i<k;i++) {
			v[i] = io.nextInt() - 1;
			p[i] = io.nextInt();
		}
		ans = new int[n];
		ArrayList<Integer> ans = null;
//		ArrayList<Integer> uso = new ArrayList<>();
//		for(int i=0;i<n;i++) {
//			uso.add(i);
//		}
//		Collections.shuffle(uso);
//		int max = Math.min(100, n);
//		for(int i=0;i<max;i++) {
			ans = solve(0);
//			if (ans != null) break;
//		}
		if (ans == null) {
			System.out.println("No");
		}else{
			io.println("Yes");
			for(int x: ans) {
				io.println(x);
			}
			io.flush();
		}
	}

	public ArrayList<Integer> solve(int s1) {
		Arrays.fill(ub, INF);
		Arrays.fill(lb, -INF);
		Arrays.fill(ans, 0);
		for(int i=0;i<k;i++) {
			ub[v[i]] = lb[v[i]] = p[i];
		}
		dfsUp(s1,-1);
		dfsDown(s1,-1);
		int s = -1;
		for(int i=0;i<n;i++) {
			if (ub[i] < lb[i]) {
				return null;
			}
			if (ub[i] == lb[i]) {
				s = i;
			}
		}
		ans[s] = lb[s];
		fail = false;
		dfsDown2(s, -1);
		if (fail) {
			return null;
		}
		for(int i=0;i<n;i++) {
			for(int j: tree[i]) {
				if (Math.abs(ans[i] - ans[j]) != 1) {
					return null;
				}
			}
		}
		ArrayList<Integer> al = new ArrayList<>();
		for(int i=0;i<n;i++) {
			al.add(ans[i]);
		}
		return al;
	}

	public int randInt(int min,int max) {
		return (int) (Math.random() * (max - min + 1)) + min;
	}

	public void dfsUp(int v,int p) {
		for(int c: tree[v]) {
			if (c == p) continue;
			dfsUp(c, v);
			ub[v] = Math.min(ub[v], ub[c] + 1);
			lb[v] = Math.max(lb[v], lb[c] - 1);
		}
	}

	public void dfsDown(int v,int p) {
		for(int c: tree[v]) {
			if (c == p) continue;
			ub[c] = Math.min(ub[c], ub[v] + 1);
			lb[c] = Math.max(lb[c], lb[v] - 1);
			dfsDown(c, v);
		}
	}

	public boolean fail = false;
	public void dfsDown2(int v,int p) {
		for(int c: tree[v]) {
			if (c == p) continue;
			boolean ok = false;
			for(int k=-1;k<=1;k+=2) {
				int next = ans[v] + k;
				if (lb[c] <= next && next <= ub[c]) {
					ans[c] = next;
					ok = true;
					break;
				}
			}
			if (!ok) {
				fail = true;
				return;
			}
			dfsDown2(c, v);
			if (fail) {
				return;
			}
		}
	}

