import java.util.ArrayList;
import java.util.Scanner;

public class Main {
  static Scanner sc = new Scanner(System.in);
  static final int INF = Integer.MAX_VALUE;
  static Node[] nodes;

  public static void main(String[] args) {
    boolean result = solve();
    if (result) {
      System.out.println("Yes");
      StringBuilder sb = new StringBuilder();
      for (int i = 0; i < nodes.length; i++) {
        sb.append(nodes[i].v + "\n");
      }
      System.out.print(sb);
    } else {
      System.out.println("No");
    }
  }

  static boolean solve() {
    int N = sc.nextInt();
    nodes = new Node[N];
    for (int i = 0; i < N; i++) {
      nodes[i] = new Node(i);
    }
    for (int i = 0; i < N - 1; i++) {
      int A = Integer.parseInt(sc.next()) - 1;
      int B = Integer.parseInt(sc.next()) - 1;
      nodes[A].next.add(nodes[B]);
      nodes[B].next.add(nodes[A]);
    }
    int K = sc.nextInt();
    for (int i = 0; i < K; i++) {
      int V = Integer.parseInt(sc.next()) - 1;
      int P = Integer.parseInt(sc.next());
      nodes[V].v = nodes[V].min = nodes[V].max = P;
    }
    Node[] order = new Node[N];
    order[0] = nodes[0];
    nodes[0].parent = -1;
    for (int i = 0, pos = 1; i < N; i++) {
      for (Node c : order[i].next) {
        if (c.parent != INF) continue;
        c.parent = order[i].id;
        c.depth = order[i].depth + 1;
        order[pos++] = c;
      }
    }
    int parity = -1;
    for (int i = 0; i < N; i++) {
      if (order[i].v == INF) continue;
      int p = (order[i].v ^ order[i].depth) & 1;
      if (parity == -1) {
        parity = p;
      } else if (parity != p) {
        return false;
      }
    }
    for (int i = N - 1; i >= 0; i--) {
      for (Node c : order[i].next) {
        if (c.id == order[i].parent) continue;
        order[i].min = Math.max(order[i].min, c.min - 1);
        order[i].max = Math.min(order[i].max, c.max + 1);
      }
      if (order[i].min > order[i].max) return false;
    }
    for (int i = 1; i < N; i++) {
      order[i].min = Math.max(order[i].min, nodes[order[i].parent].min - 1);
      order[i].max = Math.min(order[i].max, nodes[order[i].parent].max + 1);
      if (order[i].min > order[i].max) return false;
    }
    order[0].v = order[0].min;
    for (int i = 1; i < N; i++) {
      int pv = nodes[order[i].parent].v;
      if (order[i].min <= pv - 1 && pv - 1 <= order[i].max) {
        order[i].v = pv - 1;
      } else {
        order[i].v = pv + 1;
      }
    }
    return true;
  }


  static class Node {
    int id, depth, parent = INF, v = INF, min = -INF / 2, max = INF / 2;
    ArrayList<Node> next = new ArrayList<>();

    public Node(int id) {
      this.id = id;
    }
  }
}

import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.InputMismatchException;
import java.util.NoSuchElementException;

public class Main implements Runnable {
	public static final int INF = 1 << 29;

	public static void main(String[] args) {
		new Thread(null, new Main(), "", 16L * 1024 * 1024).start();
	}

	int n;
	ArrayList<Integer>[] tree;
	int k;
	int[] v,p;
	int[] ub,lb,ans;

	@SuppressWarnings("unchecked")
	public void run() {
		IO io = new IO();
		n = io.nextInt();
		ub = new int[n];
		lb = new int[n];
		tree = new ArrayList[n];
		for(int i=0;i<n;i++) {
			tree[i] = new ArrayList<>();
		}
		for(int i=0;i<n-1;i++) {
			int a = io.nextInt() - 1;
			int b = io.nextInt() - 1;
			tree[a].add(b);
			tree[b].add(a);
		}
		k = io.nextInt();
		v = new int[k];
		p = new int[k];
		for(int i=0;i<k;i++) {
			v[i] = io.nextInt() - 1;
			p[i] = io.nextInt();
		}
		ans = new int[n];
		ArrayList<Integer> ans = null;
		for(int i=0;i<5;i++) {
			ans = solve(randInt(0, n-1));
			if (ans != null) break;
		}
		if (ans == null) {
			System.out.println("No");
		}else{
			io.println("Yes");
			for(int x: ans) {
				io.println(x);
			}
			io.flush();
		}
	}

	public ArrayList<Integer> solve(int s1) {
		Arrays.fill(ub, INF);
		Arrays.fill(lb, -INF);
		for(int i=0;i<k;i++) {
			ub[v[i]] = lb[v[i]] = p[i];
		}
		dfsUp(s1,-1);
		dfsDown(s1,-1);
		int s = -1;
		for(int i=0;i<n;i++) {
			if (ub[i] < lb[i]) {
				return null;
			}
			if (ub[i] == lb[i]) {
				s = i;
			}
		}
		ans[s] = lb[s];
		fail = false;
		dfsDown2(s, -1);
		if (fail) {
			return null;
		}
		ArrayList<Integer> al = new ArrayList<>();
		for(int i=0;i<n;i++) {
			al.add(ans[i]);
		}
		return al;
	}

	public int randInt(int min,int max) {
		return (int) (Math.random() * (max - min + 1)) + min;
	}

	public void dfsUp(int v,int p) {
		for(int c: tree[v]) {
			if (c == p) continue;
			dfsUp(c, v);
			ub[v] = Math.min(ub[v], ub[c] + 1);
			lb[v] = Math.max(lb[v], lb[c] - 1);
		}
	}

	public void dfsDown(int v,int p) {
		for(int c: tree[v]) {
			if (c == p) continue;
			ub[c] = Math.min(ub[c], ub[v] + 1);
			lb[c] = Math.max(lb[c], lb[v] - 1);
			dfsDown(c, v);
		}
	}

	public boolean fail = false;
	public void dfsDown2(int v,int p) {
		for(int c: tree[v]) {
			if (c == p) continue;
			boolean ok = false;
			for(int k=-1;k<=1;k+=2) {
				int next = ans[v] + k;
				if (lb[c] <= next && next <= ub[c]) {
					ans[c] = next;
					ok = true;
					break;
				}
			}
			if (!ok) {
				fail = true;
				return;
			}
			dfsDown2(c, v);
			if (fail) {
				return;
			}
		}
	}

}
class IO extends PrintWriter {
	private final InputStream in;
	private final byte[] buffer = new byte[1024];
	private int ptr = 0;
	private int buflen = 0;

	public IO() { this(System.in);}
	public IO(InputStream source) { super(System.out); this.in = source;}
	private boolean hasNextByte() {
		if (ptr < buflen) {
			return true;
		}else{
			ptr = 0;
			try {
				buflen = in.read(buffer);
			} catch (IOException e) {
				e.printStackTrace();
			}
			if (buflen <= 0) {
				return false;
			}
		}
		return true;
	}
	private int readByte() { if (hasNextByte()) return buffer[ptr++]; else return -1;}
	private static boolean isPrintableChar(int c) { return 33 <= c && c <= 126;}
	private static boolean isNewLine(int c) { return c == '\n' || c == '\r';}
	public boolean hasNext() { while(hasNextByte() && !isPrintableChar(buffer[ptr])) ptr++; return hasNextByte();}
	public boolean hasNextLine() { while(hasNextByte() && isNewLine(buffer[ptr])) ptr++; return hasNextByte();}
	public String next() {
		if (!hasNext()) {
			throw new NoSuchElementException();
		}
		StringBuilder sb = new StringBuilder();
		int b = readByte();
		while(isPrintableChar(b)) {
			sb.appendCodePoint(b);
			b = readByte();
		}
		return sb.toString();
	}
	public char[] nextCharArray(int len) {
		if (!hasNext()) {
			throw new NoSuchElementException();
		}
		char[] s = new char[len];
		int i = 0;
		int b = readByte();
		while(isPrintableChar(b)) {
			if (i == len) {
				throw new InputMismatchException();
			}
			s[i++] = (char) b;
			b = readByte();
		}
		return s;
	}
	public String nextLine() {
		if (!hasNextLine()) {
			throw new NoSuchElementException();
		}
		StringBuilder sb = new StringBuilder();
		int b = readByte();
		while(!isNewLine(b)) {
			sb.appendCodePoint(b);
			b = readByte();
		}
		return sb.toString();
	}
	public long nextLong() {
		if (!hasNext()) {
			throw new NoSuchElementException();
		}
		long n = 0;
		boolean minus = false;
		int b = readByte();
		if (b == '-') {
			minus = true;
			b = readByte();
		}
		if (b < '0' || '9' < b) {
			throw new NumberFormatException();
		}
		while(true){
			if ('0' <= b && b <= '9') {
				n *= 10;
				n += b - '0';
			}else if(b == -1 || !isPrintableChar(b)){
				return minus ? -n : n;
			}else{
				throw new NumberFormatException();
			}
			b = readByte();
		}
	}
	public int nextInt() {
		long nl = nextLong();
		if (nl < Integer.MIN_VALUE || nl > Integer.MAX_VALUE) {
			throw new NumberFormatException();
		}
		return (int) nl;
	}
	public char nextChar() {
		if (!hasNext()) {
			throw new NoSuchElementException();
		}
		return (char) readByte();
	}
	public double nextDouble() { return Double.parseDouble(next());}
	public int[] nextIntArray(int n) { int[] a = new int[n]; for(int i=0;i<n;i++) a[i] = nextInt(); return a;}
	public long[] nextLongArray(int n) { long[] a = new long[n]; for(int i=0;i<n;i++) a[i] = nextLong(); return a;}
	public double[] nextDoubleArray(int n) { double[] a = new double[n]; for(int i=0;i<n;i++) a[i] = nextDouble(); return a;}
	public void nextIntArrays(int[]... a) { for(int i=0;i<a[0].length;i++) for(int j=0;j<a.length;j++) a[j][i] = nextInt();}
	public int[][] nextIntMatrix(int n,int m) { int[][] a = new int[n][]; for(int i=0;i<n;i++) a[i] = nextIntArray(m); return a;}
	public char[][] nextCharMap(int n,int m) { char[][] a = new char[n][]; for(int i=0;i<n;i++) a[i] = nextCharArray(m); return a;}
	public void close() { super.close(); try {in.close();} catch (IOException e) {}}
}

import java.io.OutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.Arrays;
import java.util.Collection;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.List;
import java.util.StringTokenizer;
import java.util.Queue;
import java.io.BufferedReader;
import java.util.LinkedList;
import java.io.InputStream;

/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        TaskE solver = new TaskE();
        solver.solve(1, in, out);
        out.close();
    }

    static class TaskE {
        private static final int MAX_PRICE = 100005;
        List<Integer>[] adj;
        boolean[] marked;
        int[] val;
        List<Integer>[] priceToVertex;

        public void solve(int testNumber, InputReader in, PrintWriter out) {
            int N = in.nextInt();
            adj = (List<Integer>[]) new LinkedList[N];
            priceToVertex = (List<Integer>[]) new LinkedList[2 * MAX_PRICE];
            for (int i = 0; i < priceToVertex.length; i++) priceToVertex[i] = new LinkedList<>();
            for (int i = 0; i < N; i++) adj[i] = new LinkedList<>();

            for (int i = 0; i < N - 1; i++) {
                int v = in.nextInt() - 1;
                int w = in.nextInt() - 1;
                adj[v].add(w);
                adj[w].add(v);
            }

            val = new int[N];
            Arrays.fill(val, -1);
            marked = new boolean[N];
            long K = in.nextLong();

            int min = Integer.MAX_VALUE;

            for (int i = 0; i < K; i++) {
                int vertex = in.nextInt() - 1;
                int price = in.nextInt();
                if (min > price) {
                    min = price;
                }

                val[vertex] = price;
                priceToVertex[price].add(vertex);
            }

            Queue<Integer> bfs = new LinkedList<>();

            for (int x : priceToVertex[min]) {
                bfs.add(x);
                marked[x] = true;
            }

            while (!bfs.isEmpty()) {
                int v = bfs.poll();

                int valueAtVertex = val[v];

                for (int w : adj[v]) {
                    if (val[w] == -1) {
                        marked[w] = true;
                        val[w] = valueAtVertex + 1;
                        bfs.add(w);
                        for (int x : priceToVertex[val[w]]) {
                            if (!marked[x]) {
                                bfs.add(x);
                                marked[x] = true;
                            }
                        }
                    } else if (!marked[w] && val[w] != valueAtVertex + 1) {
                        out.println("No");
                        return;
                    }
                }
            }

            out.println("Yes");

            for (int i = 0; i < N; i++) out.println(val[i]);

        }

    }

    static class InputReader {
        public BufferedReader reader;
        public StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

    }
}

