    static ArrayList<Integer> g[];
    static int v[];
    static Point pv[];
    static boolean isValid(Point p){
        if(p.x>p.y)
            return false;
        return true;
    }
    static boolean isInfinite(Point a){
        return a.x==Integer.MIN_VALUE&&a.y==Integer.MAX_VALUE;
    }
    static void merge(Point a, Point b, int chng){
        if(isInfinite(a)&&!isInfinite(b)){
            a.x=b.x-chng;
            a.y=b.y+chng;
            return;
        }else if(isInfinite(b)){
            return;
        }else{
            if(a.x%2!=(b.x-chng)%2){
              a.x=0;a.y=-1;
              return;
            }
            if(((b.x-chng)>a.y)||(a.x>(b.y+chng))){
                a.x=0;
                a.y=-1;
                return;
            }
            a.x=Math.max(a.x,b.x-chng);
            a.y=Math.min(a.y,b.y+chng);
            if(!isValid(a)){
                a.x=0;a.y=-1;
                return;
            }                
        }
    }
    static Point sol(int nd, int p, Point parV){
        //if node already has a value
        if(v[nd]!=0){
            pv[nd]=new Point(v[nd], v[nd]);
            merge(pv[nd], parV,1);
            if(!isValid(pv[nd]))
                return pv[nd];
        }
        else{
            pv[nd]=new Point(Integer.MIN_VALUE, Integer.MAX_VALUE);
            merge(pv[nd], parV,1);
        }
        for(int nn:g[nd]){
            if(nn==p)
                continue;
            Point nnv=sol(nn,nd,pv[nd]);
            if(!isValid(nnv))
            {
                pv[nd]=new Point(0,-1);
            }
            merge(pv[nd],nnv,1);
            if(!isValid(pv[nd]))
                break;
        }
        return pv[nd];
    }
    static void fill(int nd, int p, Point parV){
        //if node doesnot have a value create value
        if(v[nd]==0){
            merge(pv[nd], parV, 1);
            if(isInfinite(pv[nd]))
                v[nd]=0;
            else
                v[nd]=pv[nd].x;
        }
        pv[nd]=new Point(v[nd],v[nd]);
        for(int nn:g[nd]){
            if(nn!=p){
                fill(nn,nd,pv[nd]);
            }
        }
    }
    static void solve() throws IOException
    {
        Scanner in=new Scanner(System.in);
        PrintWriter out=new PrintWriter(System.out);
        int n=in.nextInt();
        g=new ArrayList[n+1];
        for(int i=0;i<=n;i++)
            g[i]=new ArrayList<>();
        for(int i=1;i<n;i++){
            int u=in.nextInt();
            int v=in.nextInt();
            g[u].add(v);
            g[v].add(u);
        }
        v=new int[n+1];
        pv=new Point[n+1];
        for(int i=in.nextInt();i>0;i--){
            v[in.nextInt()]=in.nextInt();
        }
        if(isValid(sol(1,0, new Point(Integer.MIN_VALUE, Integer.MAX_VALUE)))){
            out.println("Yes");
            fill(1,0, new Point(Integer.MIN_VALUE, Integer.MAX_VALUE));
            for(int i=1;i<=n;i++)
                out.println(v[i]);

        }
        else{
            out.println("No");
        }

        out.close();

    }
}

import java.io.IOException;
import java.io.InputStream;
import java.io.OutputStream;
import java.lang.reflect.Array;
import java.lang.reflect.Field;
import java.util.Arrays;
import java.util.Collection;
import java.util.HashSet;
import java.util.NoSuchElementException;
import java.util.PrimitiveIterator;
import java.util.function.IntBinaryOperator;
import java.util.function.IntFunction;
import java.util.function.IntPredicate;
import java.util.function.IntSupplier;
import java.util.function.IntUnaryOperator;
import java.util.function.LongUnaryOperator;
import static java.lang.Math.abs;



public class Main {
    public static void main(String[] args) throws Exception {
        Field f = System.out.getClass().getDeclaredField("autoFlush");
        f.setAccessible(true);
        f.set(System.out, false);
        execute(System.in, System.out);
    }

    public static void execute(InputStream in, OutputStream out) {
        ExtendedScanner s = new ExtendedScanner(System.in);
        Out o = new Out(System.out);
        solve(s, o);
        o.flush();
        o.close();
    }

    static int n;
    static int root;
    static IntArrayList[] g;
    static int[] x;
    static int[] par;
    static int[] dep;
    static int[] dif;
    static int[] min;

    public static void solve(ExtendedScanner sc, Out out) {
        n = sc.nextInt();
        g = ObjArrayFactory.generate(n, i -> new IntArrayList(), IntArrayList.class);
        for (int i = 0; i < n - 1; i++) {
            int a = sc.nextInt() - 1;
            int b = sc.nextInt() - 1;
            g[a].add(b);
            g[b].add(a);
        }
        int k = sc.nextInt();
        x = IntArrayFactory.filled(n, -1);
        for (int i = 0; i < k; i++) {
            int v = sc.nextInt() - 1;
            int p = sc.nextInt();
            x[v] = p;
            root = v;
        }
        int[] cnt = new int[n];
        int[] y = new int[n];
        y[root] = x[root];
        par = new int[n];
        dep = new int[n];
        dif = new int[n];
        min = new int[n];
        par[root] = -1;
        dfs(root);
        IntQueue q = new IntQueue();
        q.add(root);
        while (q.size() > 0) {
            int u = q.poll();
            if (u != root) {
                cnt[u] = cnt[par[u]];
                y[u] = y[par[u]] + 1;
            }
            int m = Const.IINF;
            PrimitiveIterator.OfInt it;
            it = g[u].iterator();
            while (it.hasNext()) {
                int v = it.nextInt();
                if (v == par[u]) continue;
                m = Math.min(m, min[v]);
                q.add(v);
            }
            if (m != Const.IINF &&  (m & 1) != 0) {
                out.write("No\n");
                return;
            }
            m >>= 1;
            m -= cnt[u];
            if (m < Const.IINF && m > 0 && y[u] != x[u]) {
                if (u != root) {
                    cnt[u]++;
                    y[u] -= 2;
                } else {
                    out.write("No\n");
                    return;
                }
            } else if (m < 0) {
                out.write("No\n");
                return;
            }
        }
        for (int i = 0; i < n; i++) {
            if (x[i] >= 0 && x[i] != y[i]) {
                out.write("No\n");
                return;
            }
        }
        q.add(root);
        while (q.size() > 0) {
            int u = q.poll();
            PrimitiveIterator.OfInt it = g[u].iterator();
            while (it.hasNext()) {
                int v = it.nextInt();
                if (v == par[u]) continue;
                if (abs(y[u] - y[v]) != 1) {
                    out.write("No\n");
                    return;
                }
                q.add(v);
            }
        }
        out.write("Yes\n").write(IntArrays.join(y, "\n")).write("\n");
    }

    public static void dfs(int u) {
        min[u] = dif[u];
        PrimitiveIterator.OfInt it = g[u].iterator();
        while (it.hasNext()) {
            int v = it.nextInt();
            if (v == par[u]) continue;
            par[v] = u;
            dep[v] = dep[u] + 1;
            dif[v] = x[v] < 0 ? Const.IINF : x[root] + dep[v] - x[v];
            dfs(v);
            min[u] = Math.min(min[u], dif[v]);
        }
    }
}


class BasicScanner {
    private final InputStream in;
    private final byte[] buf = new byte[1024];
    private int ptr = 0;
    private int buflen = 0;
    public BasicScanner(InputStream in) {this.in = in;}
    private boolean hasNextByte() {
        if (ptr < buflen) return true;
        ptr = 0;
        try {buflen = in.read(buf);}
        catch (final IOException e) {e.printStackTrace();}
        return buflen > 0;
    }
    private int readByte() {return hasNextByte() ? buf[ptr++] : -1;}
    public boolean hasNext() {
        while (hasNextByte() && !(33 <= buf[ptr] && buf[ptr] <= 126)) ptr++;
        return hasNextByte();
    }
    private StringBuilder nextSequence() {
        if (!hasNext()) throw new NoSuchElementException();
        final StringBuilder sb = new StringBuilder();
        int b = readByte();
        while (33 <= b && b <= 126) {sb.appendCodePoint(b); b = readByte();}
        return sb;
    }
    public char nextChar() {
        return (char) readByte();
    }
    public String next() {
        return nextSequence().toString();
    }
    public String next(int len) {
        return new String(nextChars(len));
    }
    public char[] nextChars() {
        final StringBuilder sb = nextSequence();
        int l = sb.length();
        char[] dst = new char[l];
        sb.getChars(0, l, dst, 0);
        return dst;
    }
    public char[] nextChars(int len) {
        if (!hasNext()) throw new NoSuchElementException();
        char[] s = new char[len];
        int i = 0;
        int b = readByte();
        while (33 <= b && b <= 126 && i < len) {s[i++] = (char) b; b = readByte();}
        if (i != len) throw new NoSuchElementException(String.format("length %d is longer than the sequence.", len));
        return s;
    }
    public long nextLong() {
        if (!hasNext()) throw new NoSuchElementException();
        long n = 0;
        boolean minus = false;
        int b = readByte();
        if (b == '-') {minus = true; b = readByte();}
        if (b < '0' || '9' < b) throw new NumberFormatException();
        while (true) {
            if ('0' <= b && b <= '9') n = n * 10 + b - '0';
            else if (b == -1 || !(33 <= b && b <= 126)) return minus ? -n : n;
            else throw new NumberFormatException();
            b = readByte();
        }
    }
    public int nextInt() {return Math.toIntExact(nextLong());}
    public double nextDouble() {return Double.parseDouble(next());}
}


class Out {
    private final OutputStream out;
    private byte[] buf = new byte[1024];
    private int ptr = 0;
    private static final int AUTO_FLUSH_THRETHOLD = 1 << 17;

    public Out(OutputStream out) {
        this.out = out;
    }

    public void flush() {
        try {
            out.write(buf, 0, ptr);
            out.flush();
            ptr = 0;
        } catch (IOException e) {e.printStackTrace();}
    }

    public void close() {
        try {out.close();} catch (IOException e) {e.printStackTrace();}
    }

    public Out write(Object o) {
        return write(o.toString());
    }

    public Out write(String s) {
        try {
            Field strValueField = s.getClass().getDeclaredField("value");
            strValueField.setAccessible(true);
            byte[] b = (byte[]) strValueField.get(s);
            int l = s.length();
            if (l > AUTO_FLUSH_THRETHOLD) {
                flush();
                int i = 0;
                while (i + AUTO_FLUSH_THRETHOLD < l) {
                    out.write(b, i, AUTO_FLUSH_THRETHOLD);
                    out.flush();
                    i += AUTO_FLUSH_THRETHOLD;
                }
                ensureCapacity(l - i);
                System.arraycopy(b, i, buf, 0, l - i);
                ptr = l - i;
            } else {
                ensureCapacity(ptr + l);
                System.arraycopy(b, 0, buf, ptr, l);
                ptr += l;
            }
        } catch (Exception e) {e.printStackTrace();}
        return this;
    }

    public Out write(char[] c) {
        int l = c.length;
        if (l > AUTO_FLUSH_THRETHOLD) {
            flush();
            ensureCapacity(AUTO_FLUSH_THRETHOLD);
            int i = 0;
            while (i + AUTO_FLUSH_THRETHOLD < l) {
                for (int j = 0; j < AUTO_FLUSH_THRETHOLD; j++) {
                    buf[ptr++] = (byte) c[i + j];
                }
                flush();
                i += AUTO_FLUSH_THRETHOLD;
            }
            for (; i < l; i++) {
                buf[ptr++] = (byte) c[i];
            }
        } else {
            ensureCapacity(ptr + l);
            for (char ch : c) buf[ptr++] = (byte) ch;
        }
        return this;
    }

    public Out write(char c) {
        ensureCapacity(ptr + 1);
        buf[ptr++] = (byte) c;
        return this;
    }

    public Out write(byte b) {
        ensureCapacity(ptr + 1);
        buf[ptr++] = b;
        return this;
    }

    public Out write(int x) {
        if (x == 0) {
            ensureCapacity(ptr + 1);
            buf[ptr++] = '0';
            return this;
        }
        int d = stringSize(x);
        ensureCapacity(ptr + d);
        if (x < 0) {
            buf[ptr++] = '-';
            x = -x;
            d--;
        }
        int j = ptr + d; 
        while (x > 0) {
            buf[--j] = (byte) ('0' + (x % 10));
            x /= 10;
        }
        ptr += d;
        return this;
    }

    public Out write(long x) {
        if (x == 0) {
            ensureCapacity(ptr + 1);
            buf[ptr++] = '0';
            return this;
        }
        int d = stringSize(x);
        ensureCapacity(ptr + d);
        if (x < 0) {
            buf[ptr++] = '-';
            x = -x;
            d--;
        }
        int j = ptr + d; 
        while (x > 0) {
            buf[--j] = (byte) ('0' + (x % 10));
            x /= 10;
        }
        ptr += d;
        return this;
    }

    public Out write(double d) {
        return write(Double.toString(d));
    }

    private void ensureCapacity(int cap) {
        if (cap > AUTO_FLUSH_THRETHOLD) {
            flush();
        }
        if (cap >= buf.length) {
            int newLength = buf.length;
            while (newLength < cap) newLength <<= 1;
            byte[] newBuf = new byte[newLength];
            System.arraycopy(buf, 0, newBuf, 0, buf.length);
            buf = newBuf;
        }
    }
    private static int stringSize(long x) {
        int d = 1;
        if (x >= 0) {d = 0; x = -x;}
        long p = -10;
        for (int i = 1; i < 19; i++, p *= 10) if (x > p) return i + d;
        return 19 + d;
    }
    private static int stringSize(int x) {
        int d = 1;
        if (x >= 0) {d = 0; x = -x;}
        int p = -10;
        for (int i = 1; i < 10; i++, p *= 10) if (x > p) return i + d;
        return 10 + d;
    }
}


