        int x, y, z;

        public Pair(int x, int y, int z) {
            this.x = x;
            this.y = y;
            this.z = z;
        }
    }

    public class Pair2 {
        int x, y;

        public Pair2(int x, int y) {
            this.x = x;
            this.y = y;
        }
    }

