import java.io.*;
import java.math.*;
import java.util.*;

import static java.util.Arrays.*;

public class Main {
	private static final int mod = (int)1e9+7;

	final Random random = new Random(0);
	final IOFast io = new IOFast();

	/// MAIN CODE
	public void run() throws IOException {
//		int TEST_CASE = Integer.parseInt(new String(io.nextLine()).trim());
		int TEST_CASE = 1;
		while(TEST_CASE-- != 0) {
			int n = io.nextInt();
			g = new SimpleAdjListGraph(n, 2*n);
			for (int i = 0; i < n - 1; i++) {
				int a = io.nextInt() - 1;
				int b = io.nextInt() - 1;
				g.addEdge(a, b);
				g.addEdge(b, a);
			}
			int r = -1;
			val = new int[n];
			Arrays.fill(val, -1);
			int K = io.nextInt();
			for (int i = 0; i < K; i++) {
				int v = io.nextInt() - 1;
				val[v] = io.nextInt();
				r = v;
			}
			int[][] dp = g.bfs(r);
			for (int i = 0; i < n; i++) if (val[i] != -1) {
				if (Math.abs(val[i] - val[r]) > dp[0][i]) {
					io.out.println("No");
					return;
				}
				if (Math.abs(val[i] - val[r]) % 2 != dp[0][i] % 2) {
					io.out.println("No");
					return;
				}
			}
			prev = dp[1];
			dfs(r);
			io.out.println("Yes");
			for(int v : val) io.out.println(v);
		}
	}

	int[] val;
	SimpleAdjListGraph g;
	int[] prev;
	void dfs(int v) {
		boolean leaf = true;
		for(int e = g.head[v]; e != -1; e = g.next[e]) {
			int t = g.to[e];
			if (t == prev[v]) continue;
			leaf = false;
			dfs(t);
		}
		if(val[v] != -1 || leaf) {
			int d = 1;
			int pp = prev[v];
			while(pp != -1 && val[pp] == -1) {
				d++;
				pp = prev[pp];
			}
//			dump(v + 1, leaf, prev[v] + 1, pp + 1);
			if(pp != -1) {
				int v1 = leaf && val[v] == -1 ? val[pp] + d : val[v];
				int v2 = val[pp];
				pp = prev[v];
				val[v] = v1;
				while(pp != -1 && val[pp] == -1) {
					if(v1 < v2) val[pp] = ++v1;
					else val[pp] = --v1;
					pp = prev[pp];
				}
			}
		}
	}

	static
	class SimpleAdjListGraph {
		int m, V, E;
		int[] head, next, to;

		public SimpleAdjListGraph(int V, int E) {
			head = new int[V];
			next = new int[E];
			to = new int[E];
			this.V = V;
			this.E = E;
			clear();
		}

		public void clear() {
			m = 0;
			Arrays.fill(head, -1);
		}

		public void addEdge(int s, int t) {
			next[m] = head[s];
			head[s] = m;
			to[m++] = t;
		}


		public int[][] bfs(final int src) {
			final int[] dist = new int[head.length];
			final int[] prev = new int[head.length];
			final int[] q = new int[2 * head.length + 10];
			int s = 0, t = 0;

			Arrays.fill(dist, -1);
			Arrays.fill(prev, -1);
			dist[src] = 0;
			q[t++] = src;
			while(s != t) {
				final int v = q[s++];
				for(int e = head[v]; e != -1; e = next[e]) {
					final int u = to[e];
					if(dist[u] == -1) {
						dist[u] = dist[v] + 1;
						prev[u] = v;
						q[t++] = u;
					}
				}
			}
			return new int[][] { dist, prev };
		}
	}


