import java.util.StringTokenizer;
import java.util.Map;
import java.util.Queue;
import java.io.BufferedReader;
import java.util.LinkedList;
import java.io.InputStream;

/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        TaskE solver = new TaskE();
        solver.solve(1, in, out);
        out.close();
    }

    static class TaskE {
        List<Integer>[] adj;
        boolean[] marked;
        int[] val;
        Map<Integer, List<Integer>> priceToVertex;

        public void solve(int testNumber, InputReader in, PrintWriter out) {
            int N = in.nextInt();
            adj = (List<Integer>[]) new LinkedList[N];
            priceToVertex = new HashMap<>();

            for (int i = 0; i < N; i++) adj[i] = new LinkedList<>();

            for (int i = 0; i < N - 1; i++) {
                int v = in.nextInt() - 1;
                int w = in.nextInt() - 1;
                adj[v].add(w);
                adj[w].add(v);
            }

            val = new int[N];
            Arrays.fill(val, -1);
            marked = new boolean[N];
            long K = in.nextLong();

            int min = Integer.MAX_VALUE;

            for (int i = 0; i < K; i++) {
                int vertex = in.nextInt() - 1;
                int price = in.nextInt();
                if (min > price) {
                    min = price;
                }

                val[vertex] = price;
                priceToVertex.compute(price, (k, v) -> {
                    if (v == null) {
                        v = new LinkedList<Integer>();
                    }
                    v.add(vertex);
                    return v;
                });
            }

            Queue<Integer> bfs = new LinkedList<>();

            for (int x : priceToVertex.get(min)) {
                bfs.add(x);
                marked[x] = true;
            }

            while (!bfs.isEmpty()) {
                int v = bfs.poll();

                int valueAtVertex = val[v];

                for (int w : adj[v]) {
                    if (!marked[w]) {
                        marked[w] = true;
                        if (val[w] == -1) {
                            val[w] = valueAtVertex + 1;
                            bfs.add(w);
                        } else {
                            if (val[w] != valueAtVertex + 1) {
                                out.println("No");
                                return;
                            }
                        }
                        List<Integer> integers = priceToVertex.get(val[w]);
                        if (integers != null) {
                            for (int x : integers) {
                                if (!marked[x]) {
                                    bfs.add(x);
                                    marked[x] = true;
                                }
                            }
                        }
                    }
                }
            }
            out.println("Yes");
            for (int i = 0; i < N; i++) {
                out.println(val[i]);
            }
        }

    }

    static class InputReader {
        public BufferedReader reader;
        public StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

    }
}

