public class Main {
	@SuppressWarnings("unchecked")
	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);
		int N = Integer.parseInt(sc.next());
		ArrayList<Edge>[] g = new ArrayList[N + 1];
		for (int i = 0; i < N + 1; ++i) {
			g[i] = new ArrayList<>();
		}
		for (int i = 0; i < N - 1; ++i) {
			int a = Integer.parseInt(sc.next()) - 1;
