	public ArrayList<Integer> solve(int s1) {
		Arrays.fill(ub, INF);
		Arrays.fill(lb, -INF);
		Arrays.fill(ans, 0);
		for(int i=0;i<k;i++) {
			ub[v[i]] = lb[v[i]] = p[i];
		}
		dfsUp(s1,-1);
		dfsDown(s1,-1);
		int s = -1;
		for(int i=0;i<n;i++) {
			if (ub[i] < lb[i]) {
				return null;
			}
			if (ub[i] == lb[i]) {
				s = i;
			}
		}
		ans[s] = lb[s];
		fail = false;
		dfsDown2(s, -1);
		if (fail) {
			return null;
		}
		for(int i=0;i<n;i++) {
			for(int j: tree[i]) {
				if (Math.abs(ans[i] - ans[j]) != 1) {
					return null;
				}
			}
		}
		ArrayList<Integer> al = new ArrayList<>();
		for(int i=0;i<n;i++) {
			al.add(ans[i]);
		}
		return al;
	}

	public int randInt(int min,int max) {
		return (int) (Math.random() * (max - min + 1)) + min;
	}

	public void dfsUp(int v,int p) {
		for(int c: tree[v]) {
			if (c == p) continue;
			dfsUp(c, v);
			ub[v] = Math.min(ub[v], ub[c] + 1);
			lb[v] = Math.max(lb[v], lb[c] - 1);
		}
	}

	public void dfsDown(int v,int p) {
		for(int c: tree[v]) {
			if (c == p) continue;
			ub[c] = Math.min(ub[c], ub[v] + 1);
			lb[c] = Math.max(lb[c], lb[v] - 1);
			dfsDown(c, v);
		}
	}

	public boolean fail = false;
	public void dfsDown2(int v,int p) {
		for(int c: tree[v]) {
			if (c == p) continue;
			boolean ok = false;
			for(int k=-1;k<=1;k+=2) {
				int next = ans[v] + k;
				if (lb[c] <= next && next <= ub[c]) {
					ans[c] = next;
					ok = true;
					break;
				}
			}
			if (!ok) {
				fail = true;
				return;
			}
			dfsDown2(c, v);
			if (fail) {
				return;
			}
		}
	}

