public class Main {
	private static void solve() {
		int n = ni();
		int[][] ab = nis2(n - 1, 2);
		int k = ni();
		int[][] vp = nis2(k, 2);

		int m = n - 1; // num edges
		int[] nes = new int[n]; // num edges for each vertex
		int[][] es = new int[n][]; // edges for each vertex
		for (int i = 0; i < m; i++) {
			int a = --ab[i][0];
			int b = --ab[i][1];
			nes[a]++;
			nes[b]++;
		}
		for (int i = 0; i < n; i++) {
			es[i] = new int[nes[i]];
			nes[i] = 0;
		}
		for (int i = 0; i < m; i++) {
			int a = ab[i][0];
			int b = ab[i][1];
			es[a][nes[a]] = b;
			es[b][nes[b]] = a;
			nes[a]++;
			nes[b]++;
		}

		int[] vs = new int[n];
		Arrays.fill(vs, -1);
		for (int i = 0; i < k; i++) {
			vs[--vp[i][0]] = vp[i][1];
		}
		int root = vp[0][0];

		int[][] range = new int[n][2];
		for (int i = 0; i < n; i++) {
			if (vs[i] == -1) {
				range[i][0] = -1000000000;
				range[i][1] = 1000000000;
			} else {
				range[i][0] = vs[i];
				range[i][1] = vs[i];
			}
		}
		dfs(range, root, new boolean[n], nes, es, vs[root] % 2);
		if (range[root][0] > range[root][1])
			kil("No");
		write(range, root, new boolean[n], nes, es, vs, vs[root] - 1);
		out("Yes");
		for (int i = 0; i < n; i++) {
			out(vs[i]);
		}
	}

	static void dfs(int[][] range, int i, boolean[] vis, int[] nes, int[][] es, int parity) {
		vis[i] = true;
		if (range[i][0] == range[i][1] && range[i][0] % 2 != parity)
			kil("No");
		for (int j = 0; j < nes[i]; j++) {
			int to = es[i][j];
			if (vis[to])
				continue;
			dfs(range, to, vis, nes, es, parity ^ 1);
			range[i][0] = max(range[i][0], range[to][0] - 1);
			range[i][1] = min(range[i][1], range[to][1] + 1);
		}
	}

	static void write(int[][] range, int i, boolean[] vis, int[] nes, int[][] es, int[] vs, int parent) {
		vis[i] = true;
		int v1 = parent + 1;
		int v2 = parent - 1;
		if (v1 >= range[i][0] && v1 <= range[i][1])
			vs[i] = v1;
		else if (v2 >= range[i][0] && v2 <= range[i][1])
			vs[i] = v2;
		else
			kil("No");
		for (int j = 0; j < nes[i]; j++) {
			int to = es[i][j];
			if (vis[to])
				continue;
			write(range, to, vis, nes, es, vs, vs[i]);
		}
	}

