/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        TaskE solver = new TaskE();
        solver.solve(1, in, out);
        out.close();
    }

    static class TaskE {
        private static final int MAX_PRICE = 100005;
        List<Integer>[] adj;
        boolean[] marked;
        int[] val;
        List<Integer>[] priceToVertex;

        public void solve(int testNumber, InputReader in, PrintWriter out) {
            int N = in.nextInt();
            adj = (List<Integer>[]) new LinkedList[N];
            priceToVertex = (List<Integer>[]) new LinkedList[2 * MAX_PRICE];
            for (int i = 0; i < priceToVertex.length; i++) priceToVertex[i] = new LinkedList<>();
            for (int i = 0; i < N; i++) adj[i] = new LinkedList<>();

            for (int i = 0; i < N - 1; i++) {
                int v = in.nextInt() - 1;
                int w = in.nextInt() - 1;
                adj[v].add(w);
                adj[w].add(v);
            }

            val = new int[N];
            Arrays.fill(val, -1);
            marked = new boolean[N];
            long K = in.nextLong();

            int min = Integer.MAX_VALUE;

            for (int i = 0; i < K; i++) {
                int vertex = in.nextInt() - 1;
                int price = in.nextInt();
                if (min > price) {
                    min = price;
                }

                val[vertex] = price;
                priceToVertex[price].add(vertex);
            }

            Queue<Integer> bfs = new LinkedList<>();

            for (int x : priceToVertex[min]) {
                bfs.add(x);
                marked[x] = true;
            }

            while (!bfs.isEmpty()) {
                int v = bfs.poll();

                int valueAtVertex = val[v];

                for (int w : adj[v]) {
                    if (val[w] == -1) {
                        marked[w] = true;
                        val[w] = valueAtVertex + 1;
                        bfs.add(w);
                        for (int x : priceToVertex[val[w]]) {
                            if (!marked[x]) {
                                bfs.add(x);
                                marked[x] = true;
                            }
                        }
                    } else if (!marked[w] && val[w] != valueAtVertex + 1) {
                        out.println("No");
                        return;
                    }
                }
            }

            out.println("Yes");

            for (int i = 0; i < N; i++) out.println(val[i]);

        }

    }

    static class InputReader {
        public BufferedReader reader;
        public StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

    }
}

import java.io.*;
