class IO extends PrintWriter {
	private final InputStream in;
	private final byte[] buffer = new byte[1024];
	private int ptr = 0;
	private int buflen = 0;

	public IO() { this(System.in);}
	public IO(InputStream source) { super(System.out); this.in = source;}
	private boolean hasNextByte() {
		if (ptr < buflen) {
			return true;
		}else{
			ptr = 0;
			try {
				buflen = in.read(buffer);
			} catch (IOException e) {
				e.printStackTrace();
			}
			if (buflen <= 0) {
				return false;
			}
		}
		return true;
	}
	private int readByte() { if (hasNextByte()) return buffer[ptr++]; else return -1;}
	private static boolean isPrintableChar(int c) { return 33 <= c && c <= 126;}
	private static boolean isNewLine(int c) { return c == '\n' || c == '\r';}
	public boolean hasNext() { while(hasNextByte() && !isPrintableChar(buffer[ptr])) ptr++; return hasNextByte();}
	public boolean hasNextLine() { while(hasNextByte() && isNewLine(buffer[ptr])) ptr++; return hasNextByte();}
	public String next() {
		if (!hasNext()) {
			throw new NoSuchElementException();
		}
		StringBuilder sb = new StringBuilder();
		int b = readByte();
		while(isPrintableChar(b)) {
			sb.appendCodePoint(b);
			b = readByte();
		}
		return sb.toString();
	}
	public char[] nextCharArray(int len) {
		if (!hasNext()) {
			throw new NoSuchElementException();
		}
		char[] s = new char[len];
		int i = 0;
		int b = readByte();
		while(isPrintableChar(b)) {
			if (i == len) {
				throw new InputMismatchException();
			}
			s[i++] = (char) b;
			b = readByte();
		}
		return s;
	}
	public String nextLine() {
		if (!hasNextLine()) {
			throw new NoSuchElementException();
		}
		StringBuilder sb = new StringBuilder();
		int b = readByte();
		while(!isNewLine(b)) {
			sb.appendCodePoint(b);
			b = readByte();
		}
		return sb.toString();
	}
	public long nextLong() {
		if (!hasNext()) {
			throw new NoSuchElementException();
		}
		long n = 0;
		boolean minus = false;
		int b = readByte();
		if (b == '-') {
			minus = true;
			b = readByte();
		}
		if (b < '0' || '9' < b) {
			throw new NumberFormatException();
		}
		while(true){
			if ('0' <= b && b <= '9') {
				n *= 10;
				n += b - '0';
			}else if(b == -1 || !isPrintableChar(b)){
				return minus ? -n : n;
			}else{
				throw new NumberFormatException();
			}
			b = readByte();
		}
	}
	public int nextInt() {
		long nl = nextLong();
		if (nl < Integer.MIN_VALUE || nl > Integer.MAX_VALUE) {
			throw new NumberFormatException();
		}
		return (int) nl;
	}
	public char nextChar() {
		if (!hasNext()) {
			throw new NoSuchElementException();
		}
		return (char) readByte();
	}
	public double nextDouble() { return Double.parseDouble(next());}
	public int[] nextIntArray(int n) { int[] a = new int[n]; for(int i=0;i<n;i++) a[i] = nextInt(); return a;}
	public long[] nextLongArray(int n) { long[] a = new long[n]; for(int i=0;i<n;i++) a[i] = nextLong(); return a;}
	public double[] nextDoubleArray(int n) { double[] a = new double[n]; for(int i=0;i<n;i++) a[i] = nextDouble(); return a;}
	public void nextIntArrays(int[]... a) { for(int i=0;i<a[0].length;i++) for(int j=0;j<a.length;j++) a[j][i] = nextInt();}
	public int[][] nextIntMatrix(int n,int m) { int[][] a = new int[n][]; for(int i=0;i<n;i++) a[i] = nextIntArray(m); return a;}
	public char[][] nextCharMap(int n,int m) { char[][] a = new char[n][]; for(int i=0;i<n;i++) a[i] = nextCharArray(m); return a;}
	public void close() { super.close(); try {in.close();} catch (IOException e) {}}
}

import java.io.*;
import java.util.*;

public class Main {

	static ArrayList<Integer>[] adj;
	static int INF = (int) 1e9;
	static int[] l, r;

	static void dfs(int u, int p) {
		boolean decided = l[u] != -INF;

		for (int v : adj[u])
			if (v != p) {
				dfs(v, u);
				l[u] = Math.max(l[v], l[u]);
				r[u] = Math.min(r[v], r[u]);
			}
		if (!decided) {
			l[u]--;
			r[u]++;

		}
	}

	static boolean solve(int u, int p) {
		int prev = l[p];
		boolean ans = false;
		for (int i = -1; i <= 1; i += 2)
			if (prev + i >= l[u] && prev + i <= r[u]) {
				l[u] = prev + i;
				ans = true;
				break;
			}
		if (!ans)
			return false;
		for (int v : adj[u])
			if (v != p) {
				ans &= solve(v, u);
			}
		return ans;
	}

	public static void main(String[] args) throws IOException {
		Scanner sc = new Scanner();
		PrintWriter out = new PrintWriter(System.out);
		int n = sc.nextInt();
		adj = new ArrayList[n];
		for (int i = 0; i < n; i++)
			adj[i] = new ArrayList();
		for (int i = 1; i < n; i++) {
			int u = sc.nextInt() - 1, v = sc.nextInt() - 1;
			adj[u].add(v);
			adj[v].add(u);

		}
		int k = sc.nextInt();
		int root = -1;
		l = new int[n];
		r = new int[n];
		Arrays.fill(l, -INF);
		Arrays.fill(r, INF);
		while (k-- > 0) {
			root = sc.nextInt() - 1;
			l[root] = r[root] = sc.nextInt();
		}
		dfs(root, root);

		boolean ans = true;
		for (int i = 0; i < n; i++)
			ans &= l[i] <= r[i];
		for (int v : adj[root])
			ans &= solve(v, root);
		out.println(ans ? "Yes" : "No");
		if (ans)
			for (int i = 0; i < n; i++)
				out.println(l[i]);
		out.close();

	}

	static class Scanner {
		BufferedReader br;
		StringTokenizer st;

		Scanner() {
			br = new BufferedReader(new InputStreamReader(System.in));
		}

		Scanner(String fileName) throws FileNotFoundException {
			br = new BufferedReader(new FileReader(fileName));
		}

		String next() throws IOException {
			while (st == null || !st.hasMoreTokens())
				st = new StringTokenizer(br.readLine());
			return st.nextToken();
		}

		String nextLine() throws IOException {
			return br.readLine();
		}

		int nextInt() throws IOException {
			return Integer.parseInt(next());
		}

		long nextLong() throws NumberFormatException, IOException {
			return Long.parseLong(next());
		}

		double nextDouble() throws NumberFormatException, IOException {
			return Double.parseDouble(next());
		}

		boolean ready() throws IOException {
			return br.ready();
		}

		int[] nxtArr(int n) throws IOException {
			int[] ans = new int[n];
			for (int i = 0; i < n; i++)
				ans[i] = nextInt();
			return ans;
		}

	}

	static void sort(int[] a) {
		shuffle(a);
		Arrays.sort(a);
	}

	static void shuffle(int[] a) {
		int n = a.length;
		Random rand = new Random();
		for (int i = 0; i < n; i++) {
			int tmpIdx = rand.nextInt(n);
			int tmp = a[i];
			a[i] = a[tmpIdx];
			a[tmpIdx] = tmp;
		}
	}

}

import java.io.OutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.Arrays;
import java.util.StringTokenizer;
import java.io.IOException;
import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.InputStream;

/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 */
public class Main {
	public static void main(String[] args) {
		InputStream inputStream = System.in;
		OutputStream outputStream = System.out;
		FastScanner in = new FastScanner(inputStream);
		PrintWriter out = new PrintWriter(outputStream);
		TaskE solver = new TaskE();
		solver.solve(1, in, out);
		out.close();
	}

	static class TaskE {
		final int BAD = Integer.MAX_VALUE / 2;
		int n;
		int[][] ls;
		int[][] rs;
		int[] ptr;
		int[][] adj;
		int[] a;
		boolean[] colored;

		public void solve(int testNumber, FastScanner in, PrintWriter out) {
			n = in.nextInt();
			adj = readTree(n, in);
			int k = in.nextInt();
			a = new int[n];
			Arrays.fill(a, -1);
			colored = new boolean[n];
			for (int i = 0; i < k; i++) {
				int v = in.nextInt() - 1;
				a[v] = in.nextInt();
				colored[v] = true;
			}

			ls = new int[n][];
			rs = new int[n][];
			ptr = new int[n];
			for (int i = 0; i < n; i++) {
				ls[i] = new int[adj[i].length];
				rs[i] = new int[adj[i].length];
			}

			for (int i = 0; i < n; i++) {
				if (colored[i]) {
					dfs1(i, -1, a[i], a[i]);
				}
			}

			for (int i = 0; i < n; i++) {
				if (colored[i]) {
					continue;
				}
				boolean even = ls[i][0] % 2 == 0;
				int l = ls[i][0];
				int r = rs[i][0];
				for (int j = 0; j < ptr[i]; j++) {
					boolean e = ls[i][j] % 2 == 0;
					if (even != e) {
						out.println("No");
						return;
					}
					l = Math.max(l, ls[i][j]);
					r = Math.min(r, rs[i][j]);
				}
				if (l > r) {
					out.println("No");
					return;
				}
				a[i] = l;
				colored[i] = true;
			}

			for (int v = 0; v < n; v++) {
				if (colored[v]) {
					for (int u : adj[v]) {
						int c = dfs2(u, v, a[v] - 1, a[v] + 1);
						if (c == BAD) {
							out.println("No");
							return;
						}
					}
				}
			}

			for (int v = 0; v < n; v++) {
				if (!colored[v]) {
					throw new AssertionError();
				}
				for (int u : adj[v]) {
					if (Math.abs(a[v] - a[u]) != 1) {
						out.println("No");
						return;
					}
				}
			}

			out.println("Yes");
			for (int i = 0; i < n; i++) {
				out.println(a[i]);
			}
		}

		private void dfs1(int v, int p, int l, int r) {
			if (!colored[v]) {
				ls[v][ptr[v]] = l;
				rs[v][ptr[v]] = r;
				++ptr[v];
				if (adj[v].length > 2) {
					return;
				}
			}
			for (int u : adj[v]) {
				if (u == p) {
					continue;
				}
				if (!colored[u]) {
					dfs1(u, v, l - 1, r + 1);
				}
			}
		}

		private int dfs2(int v, int p, int l, int r) {
			if (colored[v]) {
				boolean e1 = l % 2 == 0;
				boolean e2 = a[v] % 2 == 0;
				if (e1 != e2 || !(a[v] >= l && a[v] <= r)) {
					return BAD;
				}
				return a[v];
			}
			for (int u : adj[v]) {
				if (u == p) {
					continue;
				}
				int c = dfs2(u, v, l - 1, r + 1);
				if (c == BAD) {
					return c;
				}
				for (int nc = c - 1; nc <= c + 1; nc += 2) {
					if (nc >= l && nc <= r) {
						colored[v] = true;
						a[v] = c - 1;
						return c - 1;
					}
				}
			}
			return BAD;
		}

		private int[][] readTree(int n, FastScanner in) {
			int[] as = new int[n - 1];
			int[] bs = new int[n - 1];
			int[] deg = new int[n];
			for (int i = 0; i < n - 1; i++) {
				as[i] = in.nextInt() - 1;
				bs[i] = in.nextInt() - 1;
				++deg[as[i]];
				++deg[bs[i]];
			}
			int[][] adj = new int[n][];
			for (int i = 0; i < n; i++) {
				adj[i] = new int[deg[i]];
				deg[i] = 0;
			}
			for (int i = 0; i < n - 1; i++) {
				int a = as[i];
				int b = bs[i];
				adj[a][deg[a]] = b;
				adj[b][deg[b]] = a;
				++deg[a];
				++deg[b];
			}
			return adj;
		}

	}

	static class FastScanner {
		private BufferedReader in;
		private StringTokenizer st;

		public FastScanner(InputStream stream) {
			in = new BufferedReader(new InputStreamReader(stream));
		}

		public String next() {
			while (st == null || !st.hasMoreTokens()) {
				try {
					st = new StringTokenizer(in.readLine());
				} catch (IOException e) {
					throw new RuntimeException(e);
				}
			}
			return st.nextToken();
		}

		public int nextInt() {
			return Integer.parseInt(next());
		}

	}
}

import java.io.*;
import java.util.*;
import java.util.function.Function;

public class Main {

    static int N;
    static int[] A, B;
    static int K;
    static int[] V, P;

    public static void main(String[] args) {
        FastScanner sc = new FastScanner(System.in);
        N = sc.nextInt();
        A = new int[N-1];
        B = new int[N-1];
        for (int i = 0; i < N-1; i++) {
            A[i] = sc.nextInt()-1;
            B[i] = sc.nextInt()-1;
        }
        K = sc.nextInt();
        V = new int[K];
        P = new int[K];
        for (int i = 0; i < K; i++) {
            V[i] = sc.nextInt()-1;
            P[i] = sc.nextInt();
        }

        int[] ans = solve();
        if( ans != null ) {
            System.out.println("Yes");
            writeLines(ans);
        } else {
            System.out.println("No");
        }
    }

    static int[] solve() {
        int[][] G = adjB(N, A, B);
        if( !checkParity(G) ) {
            return null;
        }

        int[][] cond = new int[N][];
        for (int i = 0; i < K; i++) {
            cond[V[i]] = new int[]{P[i], P[i]};
        }

        for (Node node : orderFromLeaf(N, G, 0)) {
            int min = Integer.MIN_VALUE;
            int max = Integer.MAX_VALUE;

            for (int b : G[node.a]) {
                if( b == node.parent ) continue;

                if( cond[b] != null ) {
                    min = Math.max(min, cond[b][0]-1);
                    max = Math.min(max, cond[b][1]+1);
                }
            }
            if( max < min ) return null;

            if( cond[node.a] != null ) {
                // check
                if( min != Integer.MIN_VALUE ) {
                    int p = cond[node.a][0];
                    if( p < min || max < p ) return null;
                }

            } else {
                // set
                if( min != Integer.MIN_VALUE ) {
                    cond[node.a] = new int[]{min, max};
                }
            }
        }

        int[] ans = new int[N];
        for (Node node : orderFromRoot(N, G, 0)) {
            if( cond[node.a] == null ) {
                ans[node.a] = ans[node.parent] + 1; // 何でもよい

            } else {
                int min = cond[node.a][0];
                int max = cond[node.a][1];
                if( node.a == 0 ) {
                    ans[node.a] = min;

                } else {
                    int parent = ans[node.parent];
                    if( min <= parent - 1 && parent -1 <= max ) {
                        ans[node.a] = parent - 1;
                    } else {
                        ans[node.a] = parent + 1;
                    }
                }
            }
        }

        return ans;
    }

    static boolean checkParity(int[][] G) {
        int[] parity = new int[N];
        for (int i = 0; i < K; i++) {
            parity[V[i]] = P[i] % 2 == 0 ? 2 : 1;
        }
        for (Node node : orderFromLeaf(N, G, 0)) {
            int p = 0;
            for (int b : G[node.a]) {
                if( b == node.parent ) continue;
                if( parity[b] == 0 ) continue;

                int req = parity[b] == 1 ? 2 : 1;
                if( p == 0 ) {
                    p = req;

                } else {
                    if( p != req ) {
                        return false;
                    }
                }
            }
            // debug(node.a, p);
            if( p != 0 ) {
                if( parity[node.a] == 0 ) {
                    parity[node.a] = p;
                } else {
                    if( parity[node.a] != p ) return false;
                }
            }
        }
        return true;
    }

    static Node[] orderFromRoot(int N, int[][] G, int root) {
        ArrayDeque<Node> q = new ArrayDeque<>();
        Node[] ret = new Node[N];
        int idx = 0;
        q.add(new Node(-1, root));
        while(!q.isEmpty()) {
            Node n = q.poll();
            ret[idx++] = n;
            for (int next : G[n.a]) {
                if( next == n.parent ) continue;

                q.add(new Node(n.a, next));
            }
        }
        return ret;
    }

    static Node[] orderFromLeaf(int N, int[][] G, int root) {
        ArrayDeque<Node> q = new ArrayDeque<>();
        Node[] ret = new Node[N];
        int idx = N-1;
        q.add(new Node(-1, root));
        while(!q.isEmpty()) {
            Node n = q.poll();
            ret[idx--] = n;
            for (int next : G[n.a]) {
                if( next == n.parent ) continue;

                q.add(new Node(n.a, next));
            }
        }
        return ret;
    }

    static class Node {
        int parent, a;

        public Node(int parent, int a) {
            this.parent = parent;
            this.a = a;
        }
    }

    static int[][] adjB(int n, int[] from, int[] to) {
        int[][] adj = new int[n][];
        int[] cnt = new int[n];
        for (int f : from) {
            cnt[f]++;
        }
        for (int t : to) {
            cnt[t]++;
        }
        for (int i = 0; i < n; i++) {
            adj[i] = new int[cnt[i]];
        }
        for (int i = 0; i < from.length; i++) {
            adj[from[i]][--cnt[from[i]]] = to[i];
            adj[to[i]][--cnt[to[i]]] = from[i];
        }
        return adj;
    }

    @SuppressWarnings("unused")
    static class FastScanner {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        FastScanner(InputStream in) {
            reader = new BufferedReader(new InputStreamReader(in));
            tokenizer = null;
        }

        String next() {
            if (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        String nextLine() {
            if (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    return reader.readLine();
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken("\n");
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        int[] nextIntArray(int n) {
            int[] a = new int[n];
            for (int i = 0; i < n; i++)
                a[i] = nextInt();
            return a;
        }

        int[] nextIntArray(int n, int delta) {
            int[] a = new int[n];
            for (int i = 0; i < n; i++)
                a[i] = nextInt() + delta;
            return a;
        }

        long[] nextLongArray(int n) {
            long[] a = new long[n];
            for (int i = 0; i < n; i++)
                a[i] = nextLong();
            return a;
        }
    }

    static <A> void writeLines(A[] as, Function<A, String> f) {
        PrintWriter pw = new PrintWriter(System.out);
        for (A a : as) {
            pw.println(f.apply(a));
        }
        pw.flush();
    }

    static void writeLines(int[] as) {
        PrintWriter pw = new PrintWriter(System.out);
        for (int a : as) pw.println(a);
        pw.flush();
    }

    static void writeLines(long[] as) {
        PrintWriter pw = new PrintWriter(System.out);
        for (long a : as) pw.println(a);
        pw.flush();
    }

    static int max(int... as) {
        int max = Integer.MIN_VALUE;
        for (int a : as) max = Math.max(a, max);
        return max;
    }

    static int min(int... as) {
        int min = Integer.MAX_VALUE;
        for (int a : as) min = Math.min(a, min);
        return min;
    }

    static void debug(Object... args) {
        StringJoiner j = new StringJoiner(" ");
        for (Object arg : args) {
            if (arg instanceof int[]) j.add(Arrays.toString((int[]) arg));
            else if (arg instanceof long[]) j.add(Arrays.toString((long[]) arg));
            else if (arg instanceof double[]) j.add(Arrays.toString((double[]) arg));
            else if (arg instanceof Object[]) j.add(Arrays.toString((Object[]) arg));
            else if ( arg != null ) j.add(arg.toString());
            else j.add("null");
        }
        System.err.println(j.toString());
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.*;

public class Main {

    static BufferedReader in;
    static PrintWriter out;
    static StringTokenizer tok;

    void solve() throws IOException {
        int n = ni();
        int[] a = new int[n];
        int[] b = new int[n];
        for (int i = 0; i < n - 1; i++) {
            a[i] = ni() - 1;
            b[i] = ni() - 1;
        }

        int k = ni();
        int[] v = new int[k];
        int[] p = new int[k];
        for (int i = 0; i < k; i++) {
            v[i] = ni() - 1;
            p[i] = ni();
        }

        ArrayList<ArrayList<Integer>> G = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            G.add(new ArrayList<>());
        }

        for (int i = 0; i < n - 1; i++) {
            G.get(a[i]).add(b[i]);
            G.get(b[i]).add(a[i]);
        }

        ArrayDeque<Pair> Q = new ArrayDeque<>();
        HashMap<Integer, Pair2> H = new HashMap<>();
        for (int i = 0; i < k; i++) {
            H.put(v[i], new Pair2(p[i], p[i], p[i] % 2));
            Q.add(new Pair(v[i], p[i], p[i], p[i] % 2));
        }

        boolean[] used = new boolean[n];

        while (!Q.isEmpty()) {
            Pair pair = Q.poll();
            if (used[pair.x]) continue;
            used[pair.x] = true;
            for (int next : G.get(pair.x)) {
                if (H.containsKey(next)) {
                    Pair2 pair2 = H.get(next);
                    if (pair.y + 1 < pair2.y || pair.z - 1 > pair2.x || pair.w == pair2.w) {
                        out.println("No");
                        return;
                    }
                    H.put(next, new Pair2(Math.min(pair.y + 1, pair2.x), Math.max(pair.z - 1, pair2.y), pair.w ^ 1));
                } else {
                    H.put(next, new Pair2(pair.y + 1, pair.z - 1, pair.w ^ 1));
                }
                if (!used[next]) {
                    Q.add(new Pair(next, H.get(next).x, H.get(next).y, H.get(next).w));
                }
            }
        }

        out.println("Yes");
        for (int i = 0; i < n; i++) {
            out.println(H.get(i).x);
        }
    }

    public class Pair {
        int x, y, z, w;

        public Pair(int x, int y, int z, int w) {
            this.x = x;
            this.y = y;
            this.z = z;
            this.w = w;
        }
    }

    public class Pair2 {
        int x, y, w;

        public Pair2(int x, int y, int w) {
            this.x = x;
            this.y = y;
            this.w = w;
        }
    }

    String ns() throws IOException {
        while (!tok.hasMoreTokens()) {
            tok = new StringTokenizer(in.readLine(), " ");
        }
        return tok.nextToken();
    }

    int ni() throws IOException {
        return Integer.parseInt(ns());
    }

    long nl() throws IOException {
        return Long.parseLong(ns());
    }

    double nd() throws IOException {
        return Double.parseDouble(ns());
    }

    String[] nsa(int n) throws IOException {
        String[] res = new String[n];
        for (int i = 0; i < n; i++) {
            res[i] = ns();
        }
        return res;
    }

    int[] nia(int n) throws IOException {
        int[] res = new int[n];
        for (int i = 0; i < n; i++) {
            res[i] = ni();
        }
        return res;
    }

    long[] nla(int n) throws IOException {
        long[] res = new long[n];
        for (int i = 0; i < n; i++) {
            res[i] = nl();
        }
        return res;
    }

    public static void main(String[] args) throws IOException {
        in = new BufferedReader(new InputStreamReader(System.in));
        out = new PrintWriter(System.out);
        tok = new StringTokenizer("");
        Main main = new Main();
        main.solve();
        out.close();
    }
}

import java.io.FileInputStream;
import java.io.FileNotFoundException;
import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.InputMismatchException;
import java.util.PriorityQueue;

public class Main {
	private static final int UNDEFINED = -1000000;

	InputStream is;

	int __t__ = 1;
	int __f__ = 0;
	int __FILE_DEBUG_FLAG__ = __f__;
	String __DEBUG_FILE_NAME__ = "src/D1";

	FastScanner in;
	PrintWriter out;

	class State implements Comparable<State> {
		int id;
		int v;

		State(int id, int v) {
			this.id = id;
			this.v = v;
		}

		public int compareTo(State s) {
			return v - s.v;
		}

		public String toString() {
			return "(" + id + ", " + v + ")";
		}
	}

	ArrayList<Integer>[] g;
	int[] V;

	public void solve() {
		int N = in.nextInt();
		g = new ArrayList[N];
		for (int i = 0; i < N; i++)
			g[i] = new ArrayList<Integer>();

		for (int i = 0; i < N - 1; i++) {
			int a = in.nextInt() - 1, b = in.nextInt() - 1;
			g[a].add(b);
			g[b].add(a);
		}

		int K = in.nextInt();
		V = new int[N];
		Arrays.fill(V, UNDEFINED);

		PriorityQueue<State> pq = new PriorityQueue<>();
		for (int i = 0; i < K; i++) {
			int v = in.nextInt() - 1, p = in.nextInt();
			V[v] = p;
			pq.add(new State(v, p));
		}		

		while (!pq.isEmpty()) {
			State st = pq.poll();
			for (int v : g[st.id]) {
				if (V[v] == UNDEFINED) {
					V[v] = V[st.id] + 1;
					pq.add(new State(v, V[v]));
				} else if (Math.abs(V[v] - V[st.id]) != 1) {
					System.out.println("No");
					return;
				}
			}
		}

		out.println("Yes");
		for (int i = 0; i < N; i++) {
			out.println(V[i]);
		}
		out.close();
	}

	public void run() {
		if (__FILE_DEBUG_FLAG__ == __t__) {
			try {
				is = new FileInputStream(__DEBUG_FILE_NAME__);
			} catch (FileNotFoundException e) {
				e.printStackTrace();
			}
			System.out.println("FILE_INPUT!");
		} else {
			is = System.in;
		}
		in = new FastScanner(is);
		out = new PrintWriter(System.out);

		Thread t = new Thread(null, new Runnable() {

			@Override
