	public void calcChildSize(int root) {
		int[] st = new int[2*V+100];
		Arrays.fill(childSize, -1);
		int sp = 0;
		st[sp++] = root;
		while(sp != 0) {
			int v = st[--sp];
			if(childSize[v] == -1) {
				childSize[v] = 0;
				st[sp++] = v;
				for(int e = head[v]; e != -1; e = next[e]) {
					final int t = to[e];
					if(childSize[t] == -1) {
						st[sp++] = t;
					}
				}
			}
			else {
				for(int e = head[v]; e != -1; e = next[e]) {
					final int t = to[e];
					if(childSize[t] > 0) {
						childSize[v] += childSize[t];
					}
				}
				childSize[v]++;
			}
		}
	}

