	private void visitBridge(int v, int u, List<Integer> br,
			List<List<Integer>> tecomp, Stack<Integer> roots, Stack<Integer> S,
			boolean[] inS, int[] num, int time) {
		num[v] = ++time;
		S.push(v);
		inS[v] = true;
		roots.push(v);
		int eu = -1;
		for(int e = head[v]; e != -1; e = next[e]) {
			int w = to[e];

