			if(num[w] == 0) {
				visitBridge(w, v, br, tecomp, roots, S, inS, num, time);
			}
			else if(u != w && inS[w]) {
				while(num[roots.peek()] > num[w]) {
					roots.pop();
				}
			}
		}
		if(v == roots.peek()) {
			br.add(eu);
			List<Integer> xs = new ArrayList<Integer>();
			while(true) {
				int w = S.pop();
				inS[w] = false;
				xs.add(w);
				if(v == w) break;
			}
			tecomp.add(xs);
			roots.pop();
		}
	}

