            G.add(new ArrayList<>());
        }

        for (int i = 0; i < n - 1; i++) {
            G.get(a[i]).add(b[i]);
            G.get(b[i]).add(a[i]);
        }

        ArrayDeque<Pair> Q = new ArrayDeque<>();
        HashMap<Integer, Pair2> H = new HashMap<>();
        for (int i = 0; i < k; i++) {
            H.put(v[i], new Pair2(p[i], p[i], p[i] % 2));
            Q.add(new Pair(v[i], p[i], p[i], p[i] % 2, -1));
        }

        while (!Q.isEmpty()) {
            Pair pair = Q.poll();
            for (int next : G.get(pair.x)) {
                if (next == pair.prev) continue;
                if (H.containsKey(next)) {
                    Pair2 pair2 = H.get(next);
                    if (pair.y + 1 < pair2.y || pair.z - 1 > pair2.x || pair.w == pair2.w) {
                        out.println("No");
                        return;
                    }
                    H.put(next, new Pair2(Math.min(pair.y + 1, pair2.x), Math.max(pair.z - 1, pair2.y), pair.w ^ 1));
                } else {
                    H.put(next, new Pair2(pair.y + 1, pair.z - 1, pair.w ^ 1));
                }
                Q.add(new Pair(next, H.get(next).x, H.get(next).y, H.get(next).w, pair.x));
            }
        }

        out.println("Yes");
        for (int i = 0; i < n; i++) {
            out.println((i + 1) + ": " + (H.get(i).w == H.get(i).x % 2 ? H.get(i).x : H.get(i).x - 1));
        }
    }

    public class Pair {
        int x, y, z, w, prev;

        public Pair(int x, int y, int z, int w, int prev) {
            this.x = x;
            this.y = y;
            this.z = z;
            this.w = w;
            this.prev = prev;
        }
    }

