		Arrays.fill(lb, -INF);
		int k = io.nextInt();
		for(int i=0;i<k;i++) {
			int v = io.nextInt() - 1;
			int p = io.nextInt();
			ub[v] = lb[v] = p;
		}
		dfsUp(0,-1,n,ub,lb,tree);
		dfsDown(0,-1,n,ub,lb,tree);
