			boolean ok = false;
			for (int i = -1; i <= 1; i += 2) {
				val[v] = val[prev[v]] + i;
				if (val[v] >= range[v][0] && val[v] <= range[v][1]) {
					ok = true;
					break;
				}
			}
			if (!ok) {
//				dump(v + 1, val[v], range);
				return false;
			}
		}
		for(int e = g.head[v]; e != -1; e = g.next[e]) {
			int t = g.to[e];
			if (t == prev[v]) continue;
			if (!dfs(t)) {
				return false;
			}
		}
		return true;
	}
	int[] dfs2(int v) {
		if (val[v] != -1) return range[v] = new int[]{val[v], val[v]};
		range[v] = new int[]{-(1<<29), 1<<29};
		for(int e = g.head[v]; e != -1; e = g.next[e]) {
			int t = g.to[e];
			if (t == prev[v]) continue;
			int[] rr = dfs2(t);
			range[v][0] = Math.max(range[v][0], rr[0] - 1);
			range[v][1] = Math.min(range[v][1], rr[1] + 1);
		}
		return range[v];
	}

	static
	class SimpleAdjListGraph {
		int m, V, E;
		int[] head, next, to;

		public SimpleAdjListGraph(int V, int E) {
			head = new int[V];
			next = new int[E];
			to = new int[E];
			this.V = V;
			this.E = E;
			clear();
		}

		public void clear() {
			m = 0;
			Arrays.fill(head, -1);
		}

		public void addEdge(int s, int t) {
			next[m] = head[s];
			head[s] = m;
			to[m++] = t;
		}


		public int[][] bfs(final int src) {
			final int[] dist = new int[head.length];
			final int[] prev = new int[head.length];
			final int[] q = new int[2 * head.length + 10];
			int s = 0, t = 0;

			Arrays.fill(dist, -1);
			Arrays.fill(prev, -1);
			dist[src] = 0;
			q[t++] = src;
			while(s != t) {
				final int v = q[s++];
				for(int e = head[v]; e != -1; e = next[e]) {
					final int u = to[e];
					if(dist[u] == -1) {
						dist[u] = dist[v] + 1;
						prev[u] = v;
						q[t++] = u;
					}
				}
			}
			return new int[][] { dist, prev };
		}
	}


