public class Main implements Runnable {
	public static final int INF = 1 << 29;

	public static void main(String[] args) {
		throw new RuntimeException();
		//new Thread(null, new Main(), "", 16L * 1024 * 1024).start();
	}

	int n;
	ArrayList<Integer>[] tree;
	int k;
	int[] v,p;
	int[] ub,lb,ans;

	@SuppressWarnings("unchecked")
	public void run() {
		IO io = new IO();
		n = io.nextInt();
		ub = new int[n];
		lb = new int[n];
		tree = new ArrayList[n];
		for(int i=0;i<n;i++) {
			tree[i] = new ArrayList<>();
		}
		for(int i=0;i<n-1;i++) {
			int a = io.nextInt() - 1;
			int b = io.nextInt() - 1;
			tree[a].add(b);
			tree[b].add(a);
		}
		boolean path = true;
		for(int i=0;i<n;i++) {
			if (tree[i].size() > 2) {
				path = false;
			}
		}
		if (path) throw new RuntimeException();
		k = io.nextInt();
		v = new int[k];
		p = new int[k];
		for(int i=0;i<k;i++) {
			v[i] = io.nextInt() - 1;
			p[i] = io.nextInt();
		}
		ans = new int[n];
		ArrayList<Integer> ans = null;
//		ArrayList<Integer> uso = new ArrayList<>();
//		for(int i=0;i<n;i++) {
//			uso.add(i);
//		}
//		Collections.shuffle(uso);
//		int max = Math.min(100, n);
//		for(int i=0;i<max;i++) {
			ans = solve(0);
//			if (ans != null) break;
//		}
		if (ans == null) {
			System.out.println("No");
