        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

    }
}

public class Main {

  private final static int INF = 10000000;
  private static void solve() {
    int n = ni();
    int[] from = new int[n - 1];
    int[] to = new int[n - 1];
    for (int i = 0; i < n - 1; i++) {
      from[i] = ni() - 1;
      to[i] = ni() - 1;
    }
    int[][] g = packU(n, from, to);
    int[][] range = new int[n][2];
    for (int i = 0; i < n; i ++) {
      range[i] = new int[] {-INF, INF};
    }

    int k = ni();
    for (int i = 0; i < k; i ++) {
      int v = ni() - 1;
      int p = ni();
      range[v] = new int[] {p, p};
    }
    if (!dfs(0, -1, g, range) ) {
      System.out.println("No");
      return;
    }
    if (!dfs(0, -1, g, range) ) {
      System.out.println("No");
      return;
    }
    out.println("Yes");
    for (int i = 0; i < n; i ++) {
      out.println(range[i][0]);
    }
  }


  private static boolean dfs(int now, int pre, int[][] g, int[][] range) {
    range[now][0] = Math.max(pre < 0 ? -INF: (range[pre][0] - 1), range[now][0]);
    range[now][1] = Math.min(pre < 0 ? INF : (range[pre][1] + 1), range[now][1]);
    if (range[now][0] > range[now][1]) return false;

    for (int next : g[now]) {
      if (next == pre) continue;
      if (!dfs(next, now, g, range)) return false;

      range[now][0] = Math.max(range[next][0] - 1, range[now][0]);
      range[now][1] = Math.min(range[next][1] + 1, range[now][1]);

      if (range[now][0] > range[now][1]) return false;
    }
    return true;
  }

  private static int[][] packU(int n, int[] from, int[] to) {
    int[][] g = new int[n][];
    int[] p = new int[n];
    for (int f : from)
      p[f]++;
    for (int t : to)
      p[t]++;
    for (int i = 0; i < n; i++)
      g[i] = new int[p[i]];
    for (int i = 0; i < from.length; i++) {
      g[from[i]][--p[from[i]]] = to[i];
      g[to[i]][--p[to[i]]] = from[i];
    }
    return g;
  }

