	List<Integer>[] node;
	Range dfs(Range r, int v, int par){
		Range res = new Range();
		res.and(p[v]);
		res.and(r);
		Range next = res.copy();
		next.inc();
		for(int nv: node[v]){
			if(nv==par) continue;
			Range ret = dfs(next, nv, v);
			res.and(ret);
		}
		range[v] = res;
		valid &= res.valid();
		res.inc();
		return res;
	}

	void set(int pre, int v, int par){
		if(pre+1 > range[v].max) pre--;
		else pre++;
		p[v] = pre;
		for(int nv: node[v]){
			if(nv==par) continue;
			set(pre, nv, v);
		}
	}
