class Range{
	int max, min, mod;
	Range(int max, int min, int mod){
		this.max = max;
		this.min = min;
		this.mod = mod;
	}
	Range(){
		max = Integer.MAX_VALUE/2;
		min = Integer.MIN_VALUE/2;
		mod = 3;
	}
	void and(Range r){
		mod &= r.mod;
		max = Math.min(max, r.max);
		min = Math.max(min, r.min);
	}
	void and(int a){
		if(a==-1) return;
		max = a;
		min = a;
		mod = a%2+1;
	}
	void inc(){
		max++;
		min--;
		if(mod==1) mod = 2;
		else if(mod==2) mod = 1;
	}
	Range copy(){
		return new Range(max, min, mod);
	}
	boolean valid(){
		return max >= min && mod != 0;
	}
}

