    public void Solve()
    {
        var N = sc.Int;
        edge = Create(N, () => new List<int>());
        for(var i = 0; i < N - 1; i++)
        {
            int a, b;
            sc.Make(out a, out b);a--;b--;
            edge[a].Add(b);edge[b].Add(a);
        }
        var dist = Create(N, () => -1);
        var pq = new PriorityQueue<Pi>((a,b)=>a.v1.CompareTo(b.v1));
        for(var i = sc.Int; i > 0; i--)
        {
            int v, p;
            sc.Make(out v, out p);
            v--;dist[v] = p;pq.Enqueue(new Pi(p, v));
        }
        while (pq.Any())
        {
            int cost, idx;
            pq.Dequeue().Deconstruct(out cost, out idx);
            foreach (var e in edge[idx])
                if (dist[e] == -1)
                {
                    dist[e] = dist[idx] + 1;
                    pq.Enqueue(new Pi(dist[e], e));
                }
        }
        for (var i = 0; i < N; i++)
            foreach (var e in edge[i])
                if (Abs(dist[e] - dist[i]) != 1) Fail("No");
        WriteLine("Yes");

