            if(ans[i] != -999999){
                if(odd[i] && ans[i]%2 == 0) yn = false;
                if(!odd[i] && ans[i]%2 == 1) yn = false;
            }
        }
        pmin = new int[n];
        pmax = new int[n];
        for(int i=0; i<n; i++){
            pmin[i] = -999999;
