			g=h[a];
		}
		else{g=ans[a-1]=tu1[a]>=g+1&&tu2[a]<=g+1?g+1:g-1;}
		for(int i=0;i<li[a].Count;i++){
			if(!b[li[a][i]]){Fu2(li[a][i],g);}
		}
	}
	static void Fu(int a,int g){
		b[a]=true;
		tu1[a]=h[a]==-1?2000000:h[a];
		tu2[a]=h[a]==-1?-1000000:h[a];
		if(h[a]!=-1&&h[a]%2!=g){bo=false;}
		for(int i=0;bo&&i<li[a].Count;i++){
			if(!b[li[a][i]]){
				Fu(li[a][i],g^1);
				tu1[a]=Min(tu1[a],tu1[li[a][i]]+1);
				tu2[a]=Max(tu2[a],tu2[li[a][i]]-1);
			}
		}
		if(tu1[a]<tu2[a]){bo=false;}
	}
}

