    bool dfs(Vertex v){
        v.c = true;
        int min = -10000000;
        int max = 10000001;
        int oe = -1;
        for(int i=0;i<v.edges.Count;i++){
            Vertex vv = v.edges[i].v;
            if(!vv.c){
                if(!dfs(vv)){
                    return false;
                }
                if(oe == -1 && vv.oe == 0){
                    oe = 1;
                }
                else if(oe == -1 && vv.oe == 1){
                    oe = 0;
                }
                else if(oe != -1 && oe == vv.oe){
                    return false;
                }
                if(vv.min != -10000000 && vv.min-1 > min){
                    min = vv.min-1;
                }
                if(vv.max != 10000001 && vv.max+1 < max){
                    max = vv.max+1;
                }
            }
        }
        if(v.c2){
            if(min > v.j){
                return false;
            }
            if(max < v.j){
                return false;
            }
            if(oe != -1 && oe != v.j%2){
                return false;
            }
            v.min = v.j;
            v.max = v.j;
            v.oe = v.j%2;
        }
        else{
            if(max < min){
                return false;
            }
            v.min = min;
            v.max = max;
            v.oe = oe;
        }
        return true;
    }
    void dfs2(Vertex v,int a){
        v.c = false;
        if(v.min > a-1){
            v.j = a+1;
        }
        else{
            v.j = a-1;
        }
        for(int i=0;i<v.edges.Count;i++){
            Vertex vv = v.edges[i].v;
            if(vv.c){
                dfs2(vv,v.j);
            }
        }
    }
