	class Problem : IDisposable
	{
		bool IsGCJ;
		int Repeat;
		Scanner sc;
		Printer pr;
		public Problem(bool isGCJ, Scanner scanner, Printer printer)
		{
			sc = scanner;
			pr = printer;
			IsGCJ = isGCJ;
			if (isGCJ) Repeat = sc.Get<int>();
			else Read();
		}
		public Problem(bool isGCJ) : this(isGCJ, new Scanner(), new Printer()) { }
		public Problem(bool isGCJ, Scanner scanner) : this(isGCJ, scanner, new Printer()) { }
		public Problem(bool isGCJ, Printer printer) : this(isGCJ, new Scanner(), printer) { }
		public void Solve()
		{
			if (IsGCJ) for (var i = 0; i < Repeat; i++) { Read(); pr.Write("Case #" + (i + 1) + ": "); SolveOne(); }
			else SolveOne();
		}
		public void Dispose()
		{
			sc.Dispose();
			pr.Dispose();
		}
		public int Size { get { return 1; } }
		public const long Mod = 1000000007;
		//public const long Mod = 924844033;
		RandomSFMT rand = Program.rand;
		int K, N;
		Tuple<int, int>[] rs, qs;
		void Read()
		{
			sc.Read(out N);
			rs = sc.ReadManyLines<int, int>(N - 1);
			sc.Read(out K);
			qs = sc.ReadManyLines<int, int>(K);
		}
		int root;
		int[] p, z;
		HashSet<int>[] es;
		Tuple<int, int>[] r;
		void SolveOne()
		{
			p = new int[N];
			r = new Tuple<int, int>[N];
			z = new int[N];
			es = new HashSet<int>[N];
			for (var i = 0; i < N; i++) es[i] = new HashSet<int>();
			foreach (var e in rs) { int a = e.Item1 - 1, b = e.Item2 - 1; es[a].Add(b); es[b].Add(a); }
			for (var i = 0; i < N; i++) z[i] = -Inf - 1;
			foreach (var q in qs) z[q.Item1 - 1] = q.Item2;
			root = qs[0].Item1 - 1;
			if (DFS(root, -1, qs[0].Item2 % 2) == null) pr.WriteLine("No");
			else
			{
				pr.WriteLine("Yes");
				DFS2(root, z[root]);
				for (var i = 0; i < N; i++) pr.WriteLine(z[i]);
			}
		}
		void DFS2(int u, int val)
		{
			z[u] = val;
			foreach (var v in es[u])
			{
				if (Contains(r[v], val + 1)) DFS2(v, val + 1);
				else DFS2(v, val - 1);
			}
		}
		Tuple<int, int> DFS(int u, int par, int even)
		{
			es[u].Remove(p[u] = par);
			r[u] = Range();
			foreach (var v in es[u])
			{
				var b = DFS(v, u, 1 - even);
				if (b == null) return null;
				r[u] = And(r[u], Extend(b));
			}
			if (!OK(r[u])) return null;
			if (z[u] >= 0)
			{
				if (!Contains(r[u], z[u]) || z[u] % 2 != even) return null;
				r[u] = Range(z[u]);
			}
			return r[u];
		}
		Tuple<int, int> Range() => new Tuple<int, int>(-Inf, Inf);
		Tuple<int, int> Range(int z) => new Tuple<int, int>(z, z);
		Tuple<int, int> Range(int l, int r) => new Tuple<int, int>(l, r);
		bool OK(Tuple<int, int> a) => a.Item1 <= a.Item2;
		bool Contains(Tuple<int, int> a, int b) => a.Item1 <= b && b <= a.Item2;
		Tuple<int, int> And(Tuple<int, int> a, Tuple<int, int> b) => new Tuple<int, int>(Max(a.Item1, b.Item1), Min(a.Item2, b.Item2));
		Tuple<int, int> Extend(Tuple<int, int> a) => new Tuple<int, int>(a.Item1 - 1, a.Item2 + 1);
	}
}
class Tree2
{
	public TreeNode2 head;
	public List<TreeNode2> tails;
	public Tree2() { head = new TreeNode2(null); tails = new List<TreeNode2>(); }
	public void Add(IEnumerable<char> S, int i)
	{
		var node = head;
		foreach (var c in S)
		{
			if (!node.children.ContainsKey(c)) node.children[c] = new TreeNode2(node);
			node = node.children[c];
		}
		if (!node.children.ContainsKey('`')) node.children['`'] = new TreeNode2(node);
		node = node.children['`'];
		node.elements = new HashSet<int>();
		node.elements.Add(i);
		tails.Add(node);
	}
	public void Compress()
	{
		foreach (var tmp in tails)
		{
			TreeNode2 t = tmp, p = t;
			while (t != null)
			{
				var c = t.children.Count;
				if (c == 1) t.elements = p.elements;
				else if (c > 1)
				{
					if (t.elements == null) t.elements = new HashSet<int>();
					t.elements.UnionWith(p.elements);
				}
				p = t; t = t.parent;
			}
		}
	}
	public TreeNode2 Search(IEnumerable<char> S)
	{
		var node = head;
		foreach (var c in S) node = node.children[c];
		return node.children['`'];
	}
}
