class Tree
{
	public TreeNode head;
	public Tree() { head = new TreeNode(); }
	public void Add(IEnumerable<char> S)
	{
		var node = head;
		head.size++;
		foreach (var c in S)
		{
			var x = c - '`';
			if (node.children[x] == null) node.children[x] = new TreeNode();
			node = node.children[x];
			node.size++;
		}
		if (node.children[0] == null) node.children[0] = new TreeNode();
		node = node.children[0];
		node.size++;
	}
	public int Sum(IEnumerable<char> S, string order)
	{
		var node = head;
		var sum = 0;
		foreach (var c in S)
		{
			if (c != '`')
			{
				sum += node.Size(0);
				for (var i = 0; i < 26; i++)
				{
					if (order[i] != c) sum += node.Size(order[i] - '`');
					else break;
				}
			}
			if (node.size == 1) break;
			node = node.children[c - '`'];
		}
		return sum;
	}
}
