    public void Solve()
    {
        var N = sc.Int;
        edge = Create(N, () => new List<int>());
        for(var i = 0; i < N - 1; i++)
        {
            int a, b;
            sc.Make(out a, out b);a--;b--;
            edge[a].Add(b);edge[b].Add(a);
        }
        var dist = Create(N, () => -1);
        var pq = new PriorityQueue<Pi>((a,b)=>a.v1.CompareTo(b.v1));
        for(var i = sc.Int; i > 0; i--)
        {
            int v, p;
            sc.Make(out v, out p);
            v--;dist[v] = p;pq.Enqueue(new Pi(p, v));
        }
        while (pq.Any())
        {
            int cost, idx;
            pq.Dequeue().Deconstruct(out cost, out idx);
            foreach (var e in edge[idx])
                if (dist[e] == -1)
                {
                    dist[e] = dist[idx] + 1;
                    pq.Enqueue(new Pi(dist[e], e));
                }
        }
        for (var i = 0; i < N; i++)
            foreach (var e in edge[i])
                if (Abs(dist[e] - dist[i]) != 1) Fail("No");
        WriteLine("YES");

        Console.WriteLine(string.Join("\n", dist));
    }
}

public class PriorityQueue<T>
{
    private List<T> item = new List<T>();
    private Comparison<T> cmp;
    public int Count { get { return item.Count; } }
    public T Peek { get { return item[0]; } }
    public PriorityQueue() { cmp = Comparer<T>.Default.Compare; }

    public PriorityQueue(Comparison<T> comparison) { cmp = comparison; }

    public PriorityQueue(IComparer<T> comparer) { cmp = comparer.Compare; }

    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    private int Parent(int i)
        => (i - 1) >> 1;
    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    private int Left(int i)
        => (i << 1) + 1;
    public T Enqueue(T val)
    {
        int i = item.Count;
        item.Add(val);
        while (i > 0)
        {
            int p = Parent(i);
            if (cmp(item[p], val) <= 0)
                break;
            item[i] = item[p];
            i = p;
        }
        item[i] = val;
        return val;
    }
    public T Dequeue()
    {
        var ret = item[0];
        var p = 0;
        var x = item[item.Count - 1];
        while (Left(p) < item.Count - 1)
        {
            var l = Left(p);
            if (l < item.Count - 2 && cmp(item[l + 1], item[l]) < 0) l++;
            if (cmp(item[l], x) >= 0)
                break;
            item[p] = item[l];
            p = l;
        }
        item[p] = x;
        item.RemoveAt(item.Count - 1);
        return ret;
    }
    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    public bool Any() => item.Count > 0;
}

