// (づ°ω°)づﾐe★゜・。。・゜゜・。。・゜☆゜・。。・゜゜・。。・゜
public class Solver
{
    List<int>[] g;
    int[] tsize, cind, cpos, csize, cdep, cpar, depth;
    int ccnt;

    void Dfs1(int x, int p)
    {
        tsize[x] = 1;
        foreach (int e in g[x])
            if (e != p)
            {
                depth[e] = depth[x] + 1;
                Dfs1(e, x);
                tsize[x] += tsize[e];
            }
    }

    void Dfs2(int x, int p, int cid)
    {
        cind[x] = cid;
        cpos[x] = csize[cid];
        csize[cid]++;
        foreach (int e in g[x])
            if (e != p)
            {
                if (tsize[e] * 2 >= tsize[x])
                    Dfs2(e, x, cid);
                else
                {
                    ccnt++;
                    cdep[ccnt] = cdep[cid] + 1;
                    cpar[ccnt] = x;
                    Dfs2(e, x, ccnt);
                }
            }
    }

    int Lca(int u, int v)
    {
        int pu = cind[u], pv = cind[v];
        while (pu != pv)
        {
            if (cdep[pu] > cdep[pv])
            {
                u = cpar[pu];
                pu = cind[u];
            }
            else
            {
                v = cpar[pv];
                pv = cind[v];
            }
        }
        return cpos[u] < cpos[v] ? u : v;
    }

    int[] load, dpl, dpr;
    bool Fun(int x, int p)
    {
        int l = int.MinValue / 2, r = int.MaxValue / 2;
        foreach (int e in g[x])
            if (e != p)
            {
                Fun(e, x);
                l = Math.Max(l, dpl[e] - 1);
                r = Math.Min(r, dpr[e] + 1);
            }

        if (l > r)
            return true;
        if (load[x] != int.MaxValue)
        {
            if (load[x] < l || load[x] > r)
                return true;
            dpl[x] = dpr[x] = load[x];
        }
        else
        {
            dpl[x] = l;
            dpr[x] = r;
        }

        return false;
    }

    bool Fun2(int x, int p, int pl, int pr)
    {
        if (load[x] != int.MaxValue)
        {
            if (load[x] < pl || load[x] > pr)
                return true;
            pl = pr = load[x];
        }
        else
        {
            pl = Math.Max(pl, dpl[x]);
            pr = Math.Min(pr, dpr[x]);
            if (pl > pr)
                return true;
            load[x] = pl;
        }
        foreach (int e in g[x])
            if (e != p)
                Fun2(e, x, pl - 1, pr + 1);

        return false;
    }

    public void Solve()
    {
        int n = ReadInt();

        g = Init<List<int>>(n);
        for (int i = 1; i < n; i++)
        {
            int u = ReadInt() - 1;
            int v = ReadInt() - 1;
            g[u].Add(v);
            g[v].Add(u);
        }

        tsize = new int[n];
        depth = new int[n];
        Dfs1(0, -1);

        cind = new int[n];
        cpos = new int[n];
        csize = new int[n];
        cdep = new int[n];
        cpar = new int[n];
        Dfs2(0, -1, 0);

        int root = -1;
        load = Enumerable.Repeat(int.MaxValue, n).ToArray();
        for (int m = ReadInt(); m > 0; m--)
        {
            int u = ReadInt() - 1;
            load[u] = ReadInt();
            if (root != -1)
            {
                int lca = Lca(u, root);
                int d = depth[u] + depth[root] - 2 * depth[lca];
                if ((load[u] + load[root]) % 2 != d % 2)
                {
                    Write("No");
                    return;
                }
            }
            root = u;
        }

        dpl = new int[n];
        dpr = new int[n];
        if (Fun(root, -1))
        {
            Write("No");
            return;
        }

        if (Fun2(root, -1, load[root], load[root]))
            Write("No");
        else
        {
            Write("Yes");
            WriteLines(load);
        }
    }

