				tu[a]=Tuple.Create(Min(tu[a].Item1,tu[li[a][i]].Item1+1),Max(tu[a].Item2,tu[li[a][i]].Item2-1));
			}
		}
		if(tu[a].Item1<tu[a].Item2){bo=false;}
	}
}

