const INF = 1000000000

func main() {
  input := Input{bufio.NewReaderSize(os.Stdin,100)}
  n := input.NextInt()
  g := make([][]int,n)
  for i:=0;i<n-1;i++ {
    a,b := input.NextInts()
    g[a-1] = append(g[a-1],b-1)
    g[b-1] = append(g[b-1],a-1)
  }
  m := make([]int,n)
  for i:=0;i<n;i++ { m[i] = -INF }
  k := input.NextInt()
  root := INF
  for i:=0;i<k;i++ {
    v,p := input.NextInts()
    m[v-1] = p
    if root > v-1 { root = v-1 }
  }
  d := dijkstra(g,root)
  l := make([]int,n)
  u := make([]int,n)
  for i:=0;i<n;i++ {
    if m[i] != -INF && (m[i]+d[i])%2 != m[root]%2 { fmt.Println("No");return }
    l[i],u[i] = -INF,INF
    if m[i] != -INF { l[i],u[i] = m[i],m[i] }
  }
  var btmup func(int,int)
  btmup = func(v,p int) {
    x,y := l[v],u[v]
    for _,e := range g[v] {
      if e == p { continue }
      btmup(e,v)
      if x < l[e]-1 { x = l[e]-1 }
      if y > u[e]+1 { y = u[e]+1 }
    }
    if x > y { fmt.Println("No");os.Exit(0) }
    l[v],u[v] = x,y
  }
  btmup(root,-1)
  var topdn func(int,int,int)
  topdn = func(v,p,c int) {
    m[v] = c
    for _,e := range g[v] {
      if e == p { continue }
      if l[e] <= c-1 && c-1 <= u[e] { topdn(e,v,c-1);continue }
      if l[e] <= c+1 && c+1 <= u[e] { topdn(e,v,c+1);continue }
    }
  }
  topdn(root,-1,m[root])
  fmt.Println("Yes")
  for i:=0;i<n;i++ { fmt.Println(m[i]) }
}

func dijkstra(g [][]int,start int) []int {
  n := len(g)
  c := make([]int,n)
  for i:=0;i<n;i++ { c[i] = INF }
  var pq PriorityQueue
  heap.Init(&pq)
  heap.Push(&pq,&Item{start,0})
  c[start] = 0
  for pq.Len() > 0 {
    s := heap.Pop(&pq).(*Item)
    if s.cost > c[s.pos] { continue }
    for _,e := range g[s.pos] {
      if c[e] > s.cost+1 {
        c[e] = s.cost+1
        heap.Push(&pq,&Item{e,c[e]})
      }
    }
  }
  return c
}
type Item struct { pos,cost int }
type PriorityQueue []*Item
func(pq PriorityQueue) Len() int { return len(pq) }
func(pq PriorityQueue) Less(i,j int) bool { return pq[i].cost < pq[j].cost }
func(pq PriorityQueue) Swap(i,j int) { pq[i],pq[j] = pq[j],pq[i] }
func(pq *PriorityQueue) Push(x interface{}) {
  item := x.(*Item)
  *pq = append(*pq,item)
}
func(pq *PriorityQueue) Pop() interface{} {
  old := *pq
  n := len(old)
  item := old[n-1]
  *pq = old[:n-1]
  return item
}

