		this._value = v;
		this.hasValue = 1;
		return _value;
		}
	int value(){	
		return _value;
		}
	void markEnd(){
		if(this.hasValue) return;
		else if(this.adjnodes.length > 1) return;
		this.isDeadend = true;
		Node nd = this.adjnodes[0];
		while(1){
			if(nd.adjnodes.length != 2) break;
			if(nd.hasValue) break;
			nd.isDeadend = true;
			if(!nd.adjnodes[0].isDeadend) nd = nd.adjnodes[0];
			else if(!nd.adjnodes[1].isDeadend) nd = nd.adjnodes[1];
			else break;
			}
		}
	void start(){
		Node[] q;
		foreach(nd; this.adjnodes) q ~= [this, nd];
		while(q.length){
			Node nd0, nd;
			nd0 = q[0], q = q[1 .. $];
			nd = q[0], q = q[1 .. $];
//			if(nd.isDeadend) continue;
			if(nd.min < nd0.min - 1 || nd.max > nd0.max + 1){
				if(nd.min > nd0.max + 1 || nd.max < nd0.min - 1){
					hasError = true;
					return;
					}
				if(nd.min > nd0.min - 1) nd.min = nd0.min - 1;
				if(nd.max > nd0.max + 1) nd.max = nd0.max + 1;
				foreach(nd2; nd.adjnodes) q ~= [nd, nd2];
				}
			}
		}
	string toString(){
		return (isDeadend? "*": " ") ~ adjnodes.length.to!string ~ (hasValue? ("(" ~ value.to!string ~ ")"): "");
		}
	}

