import math

class IntegerTree(object):
	def __init__(self, N):
		self.edges = [[] for i in range(N)]
		self.integers = [float('nan') for i in range(N)]
		self.integer_nodes = {}
		self.done = [False for i in range(N)]

	def make_edge(self, u, v):
		self.edges[u].append(v)
		self.edges[v].append(u)

	def set_integer(self, v, p):
		self.integers[v] = p
		if p in self.integer_nodes:
			self.integer_nodes[p].append(v)
		else:
			self.integer_nodes[p] = [v]

	def check(self, v):
		v_edge = self.edges[v]
		for u in v_edge:
			if math.isnan(self.integers[u]):
				return 0
			if abs(self.integers[v]-self.integers[u])!=1:
				return -1
		return 1

	def argmin_v(self):
		if len(self.integer_nodes.keys())==0:
			return -1
		min_p = min(self.integer_nodes.keys())
		return self.integer_nodes[min_p][0]

	def done_node(self, v):
		self.done[v] = True
		p = self.integers[v]
		self.integer_nodes[p].remove(v)

		if len(self.integer_nodes[p])==0:
			del self.integer_nodes[p]

