def calc_rng(v=1,parent=None):
    # None : 自由
    # False : 矛盾
    x = v_to_p[v]
    y = x
    for c in graph[v]:
        if c == parent:
            continue
        ret = calc_rng(c,v)
        if ret == False:
            return False
        x1,y1 = ret
        if x1 is None:
            continue
        # merge [x,y] and [x1-1,y1+1]
        if x is None:
            x,y = x1-1, y1+1
            continue
        # どちらも値が入っている
        if not (x - x1) & 1:
            return False
        if x < x1 - 1:
            x = x1 - 1
        if y > y1 + 1:
            y = y1 + 1
    if x is not None and x > y:
        return False
    rng[v] = (x,y)
    return x,y

