use std::collections::{BinaryHeap, VecDeque};

fn main() {
    let (r, w) = (std::io::stdin(), std::io::stdout());
    let mut sc = IO::new(r.lock(), w.lock());

    let n = sc.read();
    let mut graph = vec![vec![]; n];
    for _ in 1..n {
        let a = sc.read::<usize>() - 1;
        let b = sc.read::<usize>() - 1;
        graph[a].push(b);
        graph[b].push(a);
    }

    let mut min: Vec<i64> = vec![-1e15 as i64; n];
    let mut max: Vec<i64> = vec![1e15 as i64; n];
    let k: usize = sc.read();
    for _ in 0..k {
        let v = sc.read::<usize>() - 1;
        let p = sc.read::<i64>();
        min[v] = p;
        max[v] = p;
    }

    let mut max_heap = BinaryHeap::new();
    for i in 0..n {
        let min = min[i];
        if min != std::i64::MIN {
            max_heap.push((min, i));
        }
    }
    while let Some((_, v)) = max_heap.pop() {
        for &next in graph[v].iter() {
            if min[next] < min[v] - 1 {
                min[next] = min[v] - 1;
                max_heap.push((min[next], next));
            }
        }
    }

    let mut min_heap = BinaryHeap::new();
    for i in 0..n {
        let max = max[i];
        if max != std::i64::MAX {
            min_heap.push((-max, i));
        }
    }
    while let Some((_, v)) = min_heap.pop() {
        for &next in graph[v].iter() {
            if max[next] > max[v] + 1 {
                max[next] = max[v] + 1;
                min_heap.push((-max[next], next));
            }
        }
    }

    for i in 0..n {
        if min[i] > max[i] {
            println!("No");
            return;
        }
    }

    let mut q = VecDeque::new();
    for i in 0..n {
        if max[i] == min[i] {
            q.push_back(i);
        }
    }
    while let Some(v) = q.pop_front() {
        assert_eq!(min[v], max[v]);
        let value = min[v];
        for &next in graph[v].iter() {
            if min[next] == max[next] {
                continue;
            }
            if min[next] <= value - 1 && value - 1 <= max[next] {
                min[next] = value - 1;
                max[next] = value - 1;
            } else if min[next] <= value + 1 && value + 1 <= max[next] {
                min[next] = value + 1;
                max[next] = value + 1;
            } else {
                unimplemented!();
                //                println!("No");
                //                return;
            }

            q.push_back(next);
        }
    }

    sc.write("Yes\n");
    for i in 0..n {
        assert_eq!(min[i], max[i]);
        sc.write(format!("{}\n", min[i]));
    }
}

pub struct IO<R, W: std::io::Write>(R, std::io::BufWriter<W>);

impl<R: std::io::Read, W: std::io::Write> IO<R, W> {
    pub fn new(r: R, w: W) -> IO<R, W> {
        IO(r, std::io::BufWriter::new(w))
    }
    pub fn write<S: std::ops::Deref<Target = str>>(&mut self, s: S) {
        use std::io::Write;
        self.1.write(s.as_bytes()).unwrap();
    }
    pub fn read<T: std::str::FromStr>(&mut self) -> T {
        use std::io::Read;
        let buf = self
            .0
            .by_ref()
            .bytes()
            .map(|b| b.unwrap())
            .skip_while(|&b| b == b' ' || b == b'\n' || b == b'\r' || b == b'\t')
            .take_while(|&b| b != b' ' && b != b'\n' && b != b'\r' && b != b'\t')
            .collect::<Vec<_>>();
        unsafe { std::str::from_utf8_unchecked(&buf) }
            .parse()
            .ok()
            .expect("Parse error.")
    }
    pub fn vec<T: std::str::FromStr>(&mut self, n: usize) -> Vec<T> {
        (0..n).map(|_| self.read()).collect()
    }
    pub fn chars(&mut self) -> Vec<char> {
        self.read::<String>().chars().collect()
    }
}

macro_rules! input {
    (source = $s:expr, $($r:tt)*) => {
        let mut iter = $s.split_whitespace();
        let mut next = || { iter.next().unwrap() };
        input_inner!{next, $($r)*}
    };
    ($($r:tt)*) => {
        let stdin = std::io::stdin();
        let mut bytes = std::io::Read::bytes(std::io::BufReader::new(stdin.lock()));
        let mut next = move || -> String {
            bytes
                .by_ref()
                .map(|r| r.unwrap() as char)
                .skip_while(|c| c.is_whitespace())
                .take_while(|c| !c.is_whitespace())
                .collect()
        };
        input_inner!{next, $($r)*}
    };
}

macro_rules! input_inner {
    ($next:expr) => {};
    ($next:expr, ) => {};

    ($next:expr, $var:ident : $t:tt $($r:tt)*) => {
        let $var = read_value!($next, $t);
        input_inner!{$next $($r)*}
    };

    ($next:expr, mut $var:ident : $t:tt $($r:tt)*) => {
        let mut $var = read_value!($next, $t);
        input_inner!{$next $($r)*}
    };
}

macro_rules! read_value {
    ($next:expr, ( $($t:tt),* )) => {
        ( $(read_value!($next, $t)),* )
    };

    ($next:expr, [ $t:tt ; $len:expr ]) => {
        (0..$len).map(|_| read_value!($next, $t)).collect::<Vec<_>>()
    };

    ($next:expr, [ $t:tt ]) => {
        {
            let len = read_value!($next, usize);
            (0..len).map(|_| read_value!($next, $t)).collect::<Vec<_>>()
        }
    };

    ($next:expr, chars) => {
        read_value!($next, String).chars().collect::<Vec<char>>()
    };

    ($next:expr, usize1) => {
        read_value!($next, usize) - 1
    };

    ($next:expr, $t:ty) => {
        $next().parse::<$t>().expect("Parse error")
    };
}

