use std::cmp::{min, max};
use std::collections::{HashMap, HashSet};

fn main() {
    input!{
        n: usize,
        es: [(usize1, usize1); n - 1],
        k: usize,
        vp: [(usize1, i64); k]
    }
    let mut t = vec![vec![]; n];
    for &(a, b) in &es {
        t[a].push(b);
        t[b].push(a);
    }
    let mut tab = vec![None; n];
    for &(v, p) in &vp {
        tab[v] = Some((p, p + 1));
    }
    dfs(vp[0].0, vp[0].0, &t, &mut tab, vp[0].1 % 2);
    if tab[0].unwrap().0 >= tab[0].unwrap().1 {
        println!("No");
        return;
    }
    println!("Yes");
    let mut ans = vec![0; n];
    ans[vp[0].0] = vp[0].1;
    dfs2(vp[0].0, vp[0].0, &t, &tab, &mut ans);
    for i in 0..n {
        println!("{}", ans[i]);
    }
}

fn dfs(r: usize, p: usize, t: &Vec<Vec<usize>>, tab: &mut Vec<Option<(i64, i64)>>, f: i64) {
    if let Some((a, _)) = tab[r] {
        if a.abs() % 2 != f {
            tab[r] = Some((a, a));
            return;
        }
    }
    let mut range = tab[r];
    for &c in &t[r] {
        if c == p {
            continue;
        }
        dfs(c, r, t, tab, 1 - f);
        if let Some((a, b)) = tab[c] {
            if a >= b {
                tab[r] = tab[c];
                return;
            }
            range = Some(range.map_or((a - 1, b + 1), |x| (max(a - 1, x.0), min(b + 1, x.1))));
        }
    }
    tab[r] = range;
}

fn dfs2(r: usize, p: usize, t: &Vec<Vec<usize>>, tab: &Vec<Option<(i64, i64)>>, v: &mut Vec<i64>) {
    for &c in &t[r] {
        if c == p {
            continue;
        }
        if let Some((a, b)) = tab[c] {
            if a <= v[r] + 1 && v[r] + 1 < b {
                v[c] = v[r] + 1;
            } else {
                v[c] = v[r] - 1;
            }
        } else {
            v[c] = v[r] + 1;
        }
        dfs2(c, r, t, tab, v);
    }
}

use std::collections::{BinaryHeap, VecDeque};

fn main() {
    let (r, w) = (std::io::stdin(), std::io::stdout());
    let mut sc = IO::new(r.lock(), w.lock());

    let n = sc.read();
    let mut graph = vec![vec![]; n];
    for _ in 1..n {
        let a = sc.read::<usize>() - 1;
        let b = sc.read::<usize>() - 1;
        graph[a].push(b);
        graph[b].push(a);
    }

    let mut min: Vec<i64> = vec![-1e15 as i64; n];
    let mut max: Vec<i64> = vec![1e15 as i64; n];
    let k: usize = sc.read();
    for _ in 0..k {
        let v = sc.read::<usize>() - 1;
        let p = sc.read::<i64>();
        min[v] = p;
        max[v] = p;
    }

    let mut max_heap = BinaryHeap::new();
    for i in 0..n {
        let min = min[i];
        if min != std::i64::MIN {
            max_heap.push((min, i));
        }
    }
    while let Some((_, v)) = max_heap.pop() {
        for &next in graph[v].iter() {
            if min[next] < min[v] - 1 {
                min[next] = min[v] - 1;
                max_heap.push((min[next], next));
            }
        }
    }

    let mut min_heap = BinaryHeap::new();
    for i in 0..n {
        let max = max[i];
        if max != std::i64::MAX {
            min_heap.push((-max, i));
        }
    }
    while let Some((_, v)) = min_heap.pop() {
        for &next in graph[v].iter() {
            if max[next] > max[v] + 1 {
                max[next] = max[v] + 1;
                min_heap.push((-max[next], next));
            }
        }
    }

    for i in 0..n {
        if min[i] > max[i] {
            println!("No");
            return;
        }
    }

    let mut q = VecDeque::new();
    for i in 0..n {
        if max[i] == min[i] {
            q.push_back(i);
        }
    }
    while let Some(v) = q.pop_front() {
        assert_eq!(min[v], max[v]);
        let value = min[v];
        for &next in graph[v].iter() {
            if min[next] == max[next] {
                continue;
            }
            if min[next] <= value - 1 && value - 1 <= max[next] {
                min[next] = value - 1;
                max[next] = value - 1;
            } else if min[next] <= value + 1 && value + 1 <= max[next] {
                min[next] = value + 1;
                max[next] = value + 1;
            } else {
                println!("No");
                return;
            }

            q.push_back(next);
        }
    }

    sc.write("Yes\n");
    for i in 0..n {
        assert_eq!(min[i], max[i]);
        sc.write(format!("{}\n", min[i]));
    }

    for i in 0..n {
        for &next in graph[i].iter() {
            let d = min[i] - min[next];
            assert_eq!(d.abs(), 1);
        }
    }
}

pub struct IO<R, W: std::io::Write>(R, std::io::BufWriter<W>);

impl<R: std::io::Read, W: std::io::Write> IO<R, W> {
    pub fn new(r: R, w: W) -> IO<R, W> {
        IO(r, std::io::BufWriter::new(w))
    }
    pub fn write<S: std::ops::Deref<Target = str>>(&mut self, s: S) {
        use std::io::Write;
        self.1.write(s.as_bytes()).unwrap();
    }
    pub fn read<T: std::str::FromStr>(&mut self) -> T {
        use std::io::Read;
        let buf = self
            .0
            .by_ref()
            .bytes()
            .map(|b| b.unwrap())
            .skip_while(|&b| b == b' ' || b == b'\n' || b == b'\r' || b == b'\t')
            .take_while(|&b| b != b' ' && b != b'\n' && b != b'\r' && b != b'\t')
            .collect::<Vec<_>>();
        unsafe { std::str::from_utf8_unchecked(&buf) }
            .parse()
            .ok()
            .expect("Parse error.")
    }
    pub fn vec<T: std::str::FromStr>(&mut self, n: usize) -> Vec<T> {
        (0..n).map(|_| self.read()).collect()
    }
    pub fn chars(&mut self) -> Vec<char> {
        self.read::<String>().chars().collect()
    }
}

