    while let Some(v) = q.pop_front() {
        for &next in graph[v].iter() {
            if min[next] < min[v] - 1 {
                min[next] = min[v] - 1;
                q.push_back(next);
            }
        }
    }
    let mut q = (0..n).collect::<VecDeque<_>>();
    while let Some(v) = q.pop_front() {
        for &next in graph[v].iter() {
            if max[next] > max[v] + 1 {
                max[next] = max[v] + 1;
                q.push_back(next);
            }
        }
    }

    if (0..n).any(|i| max[i] < min[i]) {
        println!("No");
        return;
    }

    let mut ans = vec![None; n];
    ans[0] = Some(max[0]);
    let mut q = VecDeque::new();
    q.push_back(0);
    while let Some(v) = q.pop_front() {
        let va = ans[v].unwrap();
        for &next in graph[v].iter() {
            if ans[next].is_some() {
                continue;
            }

            if min[next] <= va + 1 && va + 1 <= max[next] {
                ans[next] = Some(va + 1);
            } else if min[next] <= va - 1 && va - 1 <= max[next] {
                ans[next] = Some(va - 1);
            } else {
                println!("No");
                return;
            }
            q.push_back(next);
        }
    }

    println!("Yes");
    for ans in ans.into_iter() {
        println!("{}", ans.unwrap());
    }
}

pub struct IO<R, W: std::io::Write>(R, std::io::BufWriter<W>);

impl<R: std::io::Read, W: std::io::Write> IO<R, W> {
    pub fn new(r: R, w: W) -> Self {
        IO(r, std::io::BufWriter::new(w))
    }
    pub fn write<S: ToString>(&mut self, s: S) {
        use std::io::Write;
        self.1.write(s.to_string().as_bytes()).unwrap();
    }
    pub fn read<T: std::str::FromStr>(&mut self) -> T {
        use std::io::Read;
        let buf = self
            .0
            .by_ref()
            .bytes()
            .map(|b| b.unwrap())
            .skip_while(|&b| b == b' ' || b == b'\n' || b == b'\r' || b == b'\t')
            .take_while(|&b| b != b' ' && b != b'\n' && b != b'\r' && b != b'\t')
            .collect::<Vec<_>>();
        unsafe { std::str::from_utf8_unchecked(&buf) }
            .parse()
            .ok()
            .expect("Parse error.")
    }
    pub fn vec<T: std::str::FromStr>(&mut self, n: usize) -> Vec<T> {
        (0..n).map(|_| self.read()).collect()
    }
    pub fn chars(&mut self) -> Vec<char> {
        self.read::<String>().chars().collect()
    }
}

