struct Range{
    from: i32, 
    to: i32,
}
fn up(nodes: &Vec<Vec<usize>>, value_range: &mut Vec<Range>, parity: &mut Vec<i32>, depth: Vec<usize>) -> () {
    let mut queue = VecDeque::new();
    let mut child_count = nodes.iter().map(|n|n.len()).collect::<Vec<_>>();
    for i in 1 .. value_range.len() {
        if child_count[i] == 1 {
            queue.push_back(i);
        }
    }
    while let Some(top) = queue.pop_front() {
        for &next in &nodes[top] {
            if child_count[next] > 1 {
                child_count[next] -= 1;
                if child_count[next] == 1 && depth[next] < depth[top] {
                    queue.push_back(next);
                }
                if parity[next] == -1 && parity[top] != -1 {
                    parity[next] = 1 - parity[top];
                }
                value_range[next] = Range{from: max(value_range[next].from, value_range[top].from - 1), to: min(value_range[next].to, value_range[top].to + 1)};
            }
        }
    }
}
fn down(nodes: &Vec<Vec<usize>>, value_range: &mut Vec<Range>, parity: &mut Vec<i32>) -> Vec<usize> {
    let mut is_visit = vec![false; nodes.len()];
    let mut queue = VecDeque::new();
    let mut depth = vec![0; nodes.len()];
    is_visit[0] = true; queue.push_back(0);
    while let Some(top) = queue.pop_front() {
        for &next in &nodes[top] {
            if !is_visit[next] {
                is_visit[next] = true;
                depth[next] = depth[top] + 1;
                queue.push_back(next);
                if parity[next] == -1 && parity[top] != -1 {
                    parity[next] = 1 - parity[top];
                }
                value_range[next] = Range{from: max(value_range[next].from, value_range[top].from - 1), to: min(value_range[next].to, value_range[top].to + 1)};
            }
        }
    }
    depth
}
fn main() {
    assign!{
        n: usize
    }
    let mut nodes = vec![Vec::new() as Vec<usize>; n];
    for _ in 1 .. n {
        assign! {
            a: usize
            b: usize
        }
        nodes[a - 1].push(b - 1);
        nodes[b - 1].push(a - 1);
    }
    assign!{k: usize}
