    let mut parity = vec![-1; n];
    for _ in 0 .. k {
        assign!{
            v: usize
            p: i32
        }
        value_range[v - 1] = Range{from: p, to: p};
        parity[v - 1] = p & 1;
    }
    let depth = down(&nodes, &mut value_range, &mut parity);
    up(&nodes, &mut value_range, &mut parity, depth);
    down(&nodes, &mut value_range, &mut parity);
