use std::io::Write;

fn run() {
    input! {
        n: usize,
        e: [(usize1, usize1); n - 1],
        m: usize,
        p: [(usize1, i32); m],
    }
    let mut a = vec![None; n];
    for (v, p) in p {
        a[v] = Some(p);
    }
    let inf = 1_000_000 + 1;
    type Value = (i32, i32);
    type Edge = ();
    let init = |v: usize| -> Value {
        if let Some(p) = a[v] {
            (p, p)
        } else {
            (-inf, 2 * inf)
        }
    };
    let merge = |a: &Value, b: &Value, _c: &Edge| -> Value {
        (std::cmp::max(a.0, b.0 - 1), std::cmp::min(a.1, b.1 + 1))
    };
    let mut solver = Rerooting::new(n, init, merge);
    for (a, b) in e {
        solver.add_edge(a, b, ());
    }
    let res = solver.solve();
    if !res.iter().all(|p| p.0 <= p.1 && (p.1 - p.0) % 2 == 0) {
        println!("No");
        return;
    }
    let out = std::io::stdout();
    let mut out = std::io::BufWriter::new(out.lock());
    writeln!(out, "Yes").ok();
    for (a, _) in res {
        writeln!(out, "{}", a).ok();
    }
}

fn main() {
    run();
}

