fn run<I: Input, O: Write>(mut kin: I, mut out: O) {
    macro_rules! output { ($($args:expr),+) => { write!(&mut out, $($args),+).unwrap(); }; }
    macro_rules! outputln {
        ($($args:expr),+) => { output!($($args),+); outputln!(); };
        () => { output!("\n"); if cfg!(debug_assertions) { out.flush().unwrap(); } }
    }

    let n: usize = kin.input();
    let mut g = vec![Vec::new(); n + 1];
    for (a, b) in kin.iter::<(usize, usize)>().take(n - 1) {
        g[a].push(b);
        g[b].push(a);
    }
    let k: usize = kin.input();
    let mut range = vec![(0, INF); n + 1];
    let mut r = 0;
    for (v, p) in kin.iter::<(usize, i32)>().take(k) {
        range[v] = (p, p);
        r = v;
    }

    if !dfs_parity(&g, &range, r, 0, range[r].1 & 1) {
        outputln!("No");
        return;
    }
    dfs1(&g, &mut range, 1, 0);
    dfs2(&g, &mut range, 1, 0);

    for u in 1..=n {
        let (l, r) = range[u];
        if l > r {
            outputln!("No");
            return;
        }
    }

    outputln!("Yes");
    for u in 1..=n {
        outputln!("{}", range[u].1);
    }
}

const INF: i32 = 100000000;

fn intersection((al, ar): (i32, i32), (bl, br): (i32, i32)) -> (i32, i32) {
    (al.max(bl), ar.min(br))
}
fn inc((l, r): (i32, i32)) -> (i32, i32) {
    (l.saturating_sub(1), r + 1)
}

fn dfs_parity(g: &[Vec<usize>], range: &[(i32, i32)], u: usize, p: usize, c: i32) -> bool {
    if range[u].1 != INF && (range[u].1 ^ c) & 1 == 1 {
        return false;
    }
    for &v in &g[u] {
        if v == p {
            continue;
        }
        if !dfs_parity(g, range, v, u, c ^ 1) {
            return false;
        }
    }
    true
}

fn dfs1(g: &[Vec<usize>], range: &mut [(i32, i32)], u: usize, p: usize) {
    for &v in &g[u] {
        if v == p {
            continue;
        }
        dfs1(g, range, v, u);
        range[u] = intersection(range[u], inc(range[v]));
    }
}

fn dfs2(g: &[Vec<usize>], range: &mut [(i32, i32)], u: usize, p: usize) {
    for &v in &g[u] {
        if v == p {
            continue;
        }
        range[v] = intersection(range[v], inc(range[u]));
        dfs2(g, range, v, u);
    }
}

