use std::collections::VecDeque;

fn main() {
    let (r, w) = (std::io::stdin(), std::io::stdout());
    let mut sc = IO::new(r.lock(), w.lock());

    let n: usize = sc.read();
    let mut graph = vec![vec![]; n];
    for _ in 1..n {
        let a = sc.read::<usize>() - 1;
        let b = sc.read::<usize>() - 1;
        graph[a].push(b);
        graph[b].push(a);
    }

    let mut min = vec![-(1 << 60); n];
    let mut max = vec![1 << 60; n];
    let k: usize = sc.read();
    for _ in 0..k {
        let v = sc.read::<usize>() - 1;
        let p: i64 = sc.read();
        min[v] = p;
        max[v] = p;
    }

    let mut q = (0..n).collect::<VecDeque<_>>();
    while let Some(v) = q.pop_front() {
        for &next in graph[v].iter() {
            if min[next] < min[v] - 1 {
                min[next] = min[v] - 1;
                q.push_back(next);
            }
        }
    }
    let mut q = (0..n).collect::<VecDeque<_>>();
    while let Some(v) = q.pop_front() {
        for &next in graph[v].iter() {
            if max[next] > max[v] + 1 {
                max[next] = max[v] + 1;
                q.push_back(next);
            }
        }
    }

    if (0..n).any(|i| max[i] < min[i]) {
        println!("No");
        return;
    }

    let mut ans = vec![None; n];
    ans[0] = Some(max[0]);
    let mut q = VecDeque::new();
    q.push_back(0);
    while let Some(v) = q.pop_front() {
        let va = ans[v].unwrap();
        for &next in graph[v].iter() {
            if ans[next].is_some() {
                continue;
            }

            if min[next] <= va + 1 && va + 1 <= max[next] {
                ans[next] = Some(va + 1);
            } else if min[next] <= va - 1 && va - 1 <= max[next] {
                ans[next] = Some(va - 1);
            } else {
                unreachable!()
            }
            q.push_back(next);
        }
    }

    println!("Yes");
