        let b = sc.read::<usize>() - 1;
        graph[a].push(b);
        graph[b].push(a);
    }

    let k: usize = sc.read();
    let mut has_num = vec![false; n];
    let mut num = vec![0; n];
    let mut root = n;
    for _ in 0..k {
        let v = sc.read::<usize>() - 1;
        num[v] = sc.read::<i64>();
        has_num[v] = true;
        root = v;
    }

    let mut min_max = vec![(0, 0); n];
    dfs(root, root, &graph, &num, &has_num, &mut min_max);
    if !answer_dfs(root, root, &graph, &mut num, &mut min_max) {
        println!("No");
        return;
    } else {
        println!("Yes");
        for i in 0..n {
            println!("{}", num[i]);
        }
    }
    validate_answer(root, root, &graph, &num);
