use std::cmp;
use std::collections::{BinaryHeap, VecDeque};

fn main() {
    let (r, w) = (std::io::stdin(), std::io::stdout());
    let mut sc = IO::new(r.lock(), w.lock());

    let n = sc.read();
    let mut graph = vec![vec![]; n];
    for _ in 1..n {
        let a = sc.read::<usize>() - 1;
        let b = sc.read::<usize>() - 1;
        graph[a].push(b);
        graph[b].push(a);
    }

    let mut min: Vec<i64> = vec![-1e15 as i64; n];
    let mut max: Vec<i64> = vec![1e15 as i64; n];
    let k: usize = sc.read();
    for _ in 0..k {
        let v = sc.read::<usize>() - 1;
        let p = sc.read::<i64>();
        min[v] = p;
        max[v] = p;
    }

    let mut max_heap = BinaryHeap::new();
    for i in 0..n {
        if min[i] == max[i] {
            max_heap.push((min[i], i));
        }
    }
    while let Some((_, v)) = max_heap.pop() {
        for &next in graph[v].iter() {
            if min[next] < min[v] - 1 {
                min[next] = min[v] - 1;
                max_heap.push((min[next], next));
            }
        }
    }

    let mut min_heap = BinaryHeap::new();
    for i in 0..n {
        if min[i] == max[i] {
            min_heap.push((-max[i], i));
        }
    }
    while let Some((_, v)) = min_heap.pop() {
        for &next in graph[v].iter() {
            if max[next] > max[v] + 1 {
                max[next] = max[v] + 1;
                min_heap.push((-max[next], next));
            }
        }
    }

    for i in 0..n {
        if min[i] > max[i] {
            println!("No");
            return;
        }
    }

    let mut q = VecDeque::new();
    let mut vis = vec![false; n];
    for i in 0..n {
        if max[i] == min[i] {
            q.push_back(i);
            vis[i] = true;
        }
    }

    while let Some(v) = q.pop_front() {
        assert_eq!(min[v], max[v]);
        let value = min[v];
        for &next in graph[v].iter() {
            if vis[next] {
                continue;
            }
            if min[next] <= value - 1 && value - 1 <= max[next] {
                min[next] = value - 1;
                max[next] = value - 1;
            } else if min[next] <= value + 1 && value + 1 <= max[next] {
                min[next] = value + 1;
                max[next] = value + 1;
            } else {
                println!("No");
                return;
            }

            let value = min[next];
            for &next in graph[next].iter() {
                min[next] = cmp::max(min[next], value - 1);
                max[next] = cmp::min(max[next], value + 1);
            }
            vis[next] = true;
            q.push_back(next);
        }
    }

    sc.write("Yes\n");
    for i in 0..n {
        assert_eq!(min[i], max[i]);
        sc.write(format!("{}\n", min[i]));
    }

    for i in 0..n {
        for &next in graph[i].iter() {
            let d = min[i] - min[next];
            assert_eq!(d.abs(), 1);
        }
    }
}

