use std::collections::{BinaryHeap, VecDeque};

fn main() {
    let (r, w) = (std::io::stdin(), std::io::stdout());
    let mut sc = IO::new(r.lock(), w.lock());

    let n = sc.read();
    let mut graph = vec![vec![]; n];
    for _ in 1..n {
        let a = sc.read::<usize>() - 1;
        let b = sc.read::<usize>() - 1;
        graph[a].push(b);
        graph[b].push(a);
    }

    let mut min = vec![std::i64::MIN; n];
    let mut max = vec![std::i64::MAX; n];
    let k: usize = sc.read();
    for _ in 0..k {
        let v = sc.read::<usize>() - 1;
        let p = sc.read::<i64>();
        min[v] = p;
        max[v] = p;
    }

    let mut max_heap = BinaryHeap::new();
    for i in 0..n {
        let min = min[i];
        if min != std::i64::MIN {
            max_heap.push((min, i));
        }
    }
    while let Some((_, v)) = max_heap.pop() {
        for &next in graph[v].iter() {
            if min[next] < min[v] - 1 {
                min[next] = min[v] - 1;
                max_heap.push((min[next], next));
            }
        }
    }

    let mut min_heap = BinaryHeap::new();
    for i in 0..n {
        let max = max[i];
        if max != std::i64::MAX {
            min_heap.push((-max, i));
        }
    }
    while let Some((_, v)) = min_heap.pop() {
        for &next in graph[v].iter() {
            if max[next] > max[v] + 1 {
                max[next] = max[v] + 1;
                min_heap.push((-max[next], next));
            }
        }
    }

    for i in 0..n {
        if min[i] > max[i] {
            println!("No");
            return;
        }
    }

    let mut q = VecDeque::new();
    for i in 0..n {
        if max[i] == min[i] {
            q.push_back(i);
        }
    }
    while let Some(v) = q.pop_front() {
        assert_eq!(min[v], max[v]);
        let value = min[v];
        for &next in graph[v].iter() {
            if min[next] == max[next] {
                continue;
            }
            if min[next] <= value - 1 && value - 1 <= max[next] {
                min[next] = value - 1;
                max[next] = value - 1;
            } else if min[next] <= value + 1 && value + 1 <= max[next] {
                min[next] = value + 1;
                max[next] = value + 1;
            } else {
                println!("No");
                return;
            }

            q.push_back(next);
        }
    }

    for i in 0..n {
        for &next in graph[i].iter() {
            let d = min[next] - min[i];
            if d.abs() != 1 {
                println!("No");
                return;
            }
        }
    }

    sc.write("Yes\n");
    for i in 0..n {
        assert_eq!(min[i], max[i]);
        sc.write(format!("{}\n", min[i]));
    }
}

