pub mod kyoproio {
    use std::io::prelude::*;
    pub trait Input {
        fn str(&mut self) -> &str;
        fn input<T: InputParse>(&mut self) -> T {
            T::input(self)
        }
        fn iter<T: InputParse>(&mut self) -> Iter<T, Self> {
            Iter(self, std::marker::PhantomData)
        }
        fn seq<T: InputParse, B: std::iter::FromIterator<T>>(&mut self, n: usize) -> B {
            self.iter().take(n).collect()
        }
    }
    pub struct KInput<R> {
        src: R,
        buf: String,
        pos: usize,
    }
    impl<R: BufRead> KInput<R> {
        pub fn new(src: R) -> Self {
            Self {
                src,
                buf: String::with_capacity(1024),
                pos: 0,
            }
        }
        pub fn src(&mut self) -> &mut R {
            &mut self.src
        }
    }
    impl<R: BufRead> Input for KInput<R> {
        fn str(&mut self) -> &str {
            loop {
                if self.pos >= self.buf.len() {
                    self.pos = 0;
                    self.buf.clear();
                    if self.src.read_line(&mut self.buf).expect("io error") == 0 {
                        return &self.buf;
                    }
                }
                let range = self.pos
                    ..self.buf[self.pos..]
                        .find(|c: char| c.is_ascii_whitespace())
                        .map(|i| i + self.pos)
                        .unwrap_or_else(|| self.buf.len());
                self.pos = range.end + 1;
                if range.end > range.start {
                    return &self.buf[range];
                }
            }
        }
    }
    pub struct Iter<'a, T, I: ?Sized>(&'a mut I, std::marker::PhantomData<*const T>);
    impl<'a, T: InputParse, I: Input + ?Sized> Iterator for Iter<'a, T, I> {
        type Item = T;
        fn next(&mut self) -> Option<T> {
            Some(self.0.input())
        }
    }
    pub trait InputParse: Sized {
        fn input<I: Input + ?Sized>(src: &mut I) -> Self;
    }
    impl InputParse for Vec<u8> {
        fn input<I: Input + ?Sized>(src: &mut I) -> Self {
            src.str().as_bytes().to_owned()
        }
    }
    macro_rules! from_str_impl {
        { $($T:ty)* } => {
            $(impl InputParse for $T {
                fn input<I: Input + ?Sized>(src: &mut I) -> Self {
                    src.str().parse::<$T>().expect("parse error")
                }
            })*
        }
    }
    from_str_impl! {
        String char bool f32 f64 isize i8 i16 i32 i64 i128 usize u8 u16 u32 u64 u128
    }
    macro_rules! tuple_impl {
        ($H:ident $($T:ident)*) => {
            impl<$H: InputParse, $($T: InputParse),*> InputParse for ($H, $($T),*) {
                fn input<I: Input + ?Sized>(src: &mut I) -> Self {
                    ($H::input(src), $($T::input(src)),*)
                }
            }
            tuple_impl!($($T)*);
        };
        () => {}
    }
    tuple_impl!(A B C D E F G);
    #[macro_export]
    macro_rules! kdbg {
        ($($v:expr),*) => {
            if cfg!(debug_assertions) { dbg!($($v),*) } else { ($($v),*) }
        }
    }
}

use std::cmp;
use std::collections::VecDeque;

const INF: i32 = 1e9 as i32;

fn main() {
    let s = std::io::stdin();
    let mut sc = Scanner { reader: s.lock() };
    let n = sc.read();
    let mut graph = vec![vec![]; n];
    for _ in 1..n {
        let a = sc.read::<usize>() - 1;
        let b = sc.read::<usize>() - 1;
        graph[a].push(b);
        graph[b].push(a);
    }

    let k = sc.read();
    let mut num = vec![0; n];
    let mut is_numbered = vec![false; n];
    for _ in 0..k {
        let v = sc.read::<usize>() - 1;
        let p: i32 = sc.read();
        num[v] = p;
        is_numbered[v] = true;
    }

    let mut color = vec![0; n];
    for i in 0..n {
        if is_numbered[i] {
            if num[i] % 2 == 0 {
                color[i] = 2;
            } else {
                color[i] = 1;
            }
        }
    }

    for i in 0..n {
        if is_numbered[i] {
            if !color_dfs(i, &mut color, &graph) {
                println!("No");
                return;
            }
            break;
        }
    }

    let mut max = vec![INF; n];
    let mut min = vec![-INF; n];
    let mut vis = vec![false; n];
    let mut q = VecDeque::new();
    for i in 0..n {
        if is_numbered[i] {
            max[i] = num[i];
            min[i] = num[i];
            q.push_back(i);
            vis[i] = true;
        }
    }

    while let Some(v) = q.pop_front() {
        for &next in graph[v].iter() {
            max[next] = cmp::min(max[next], max[v] + 1);
            min[next] = cmp::max(min[next], min[v] - 1);
            if !vis[next] {
                vis[next] = true;
                q.push_back(next);
            }
        }
    }

    for i in 0..n {
        if max[i] < min[i] {
            println!("No");
            return;
        }
        num[i] = max[i];
    }

    println!("Yes");
    for i in 0..n {
        println!("{}", num[i]);
        // eprintln!("{} {}", max[i], min[i]);
    }
}

fn color_dfs(v: usize, color: &mut Vec<usize>, graph: &Vec<Vec<usize>>) -> bool {
    for &next in graph[v].iter() {
        let next_color = if color[v] == 1 { 2 } else { 1 };
        if color[next] == 0 {
            color[next] = next_color;
            if !color_dfs(next, color, graph) {
                return false;
            }
        } else if color[next] != next_color {
            return false;
        }
    }
    true
}

