    pub lb: Vec<i64>,
    pub ub: Vec<i64>,
}
impl TreeRec {
    pub fn new(n: usize, vp: Vec<(usize, i64)>) -> TreeRec {
        let mut lb = vec![-1_001_001_001; n];
        let mut ub = vec![1_001_001_001; n];
        for &(v, p) in &vp {
            lb[v] = p;
            ub[v] = p;
        }
        TreeRec {
            n: n,
            lb: lb,
            ub: ub,
        }
    }
    pub fn dfs(&mut self, u: usize, p: usize, graph: &Graph) {
        for v in graph.adjacency(u) {
            if v.to != p {
                self.lb[u] = max(self.lb[u], self.lb[v.to] - 1);
                self.ub[u] = min(self.ub[u], self.ub[v.to] + 1);
                self.lb[v.to] = max(self.lb[v.to], self.lb[u] - 1);
                self.ub[v.to] = min(self.ub[v.to], self.ub[u] + 1);
                self.dfs(v.to, u, graph);
                self.lb[u] = max(self.lb[u], self.lb[v.to] - 1);
                self.ub[u] = min(self.ub[u], self.ub[v.to] + 1);
                self.lb[v.to] = max(self.lb[v.to], self.lb[u] - 1);
                self.ub[v.to] = min(self.ub[v.to], self.ub[u] + 1);
            }
        }
        if p < self.n {
            self.lb[u] = max(self.lb[u], self.lb[p] - 1);
            self.lb[p] = max(self.lb[p], self.lb[u] - 1);
            self.ub[u] = min(self.ub[u], self.ub[p] + 1);
            self.ub[p] = min(self.ub[p], self.ub[u] + 1);
        }
    }
}
