const INF: i64 = 1e15 as i64;

fn main() {
    let s = std::io::stdin();
    let mut sc = Scanner { reader: s.lock() };
    let n = sc.read();
    let mut graph = vec![vec![]; n];
    for _ in 1..n {
        let a = sc.read::<usize>() - 1;
        let b = sc.read::<usize>() - 1;
        graph[a].push(b);
        graph[b].push(a);
    }

    let k = sc.read();
    let mut num: Vec<i64> = vec![0; n];
    let mut is_numbered = vec![false; n];
    let mut max = vec![INF; n];
    let mut min = vec![-INF; n];
    let mut q = VecDeque::new();
    let mut vis = vec![false; n];
    for _ in 0..k {
        let v = sc.read::<usize>() - 1;
        num[v] = sc.read();
        is_numbered[v] = true;
        max[v] = num[v];
        min[v] = num[v];
        vis[v] = true;
        q.push_back(v);
    }

    while let Some(v) = q.pop_back() {
        for &next in graph[v].iter() {
            max[next] = cmp::min(max[next], max[v] + 1);
            min[next] = cmp::max(min[next], min[v] - 1);
            if !vis[next] {
                vis[next] = true;
                q.push_back(next);
            }
        }
    }

    for i in 0..n {
        if is_numbered[i] {
            if !dfs(i, i, &graph, &mut num, &mut min, &mut max) {
                println!("No");
            } else {
                println!("Yes");
                for i in 0..n {
                    println!("{}", num[i]);
                }
            }
            return;
        }
    }
}

fn dfs(
    v: usize,
    p: usize,
    graph: &Vec<Vec<usize>>,
    num: &mut Vec<i64>,
    min: &mut Vec<i64>,
    max: &mut Vec<i64>,
) -> bool {
    for &next in graph[v].iter() {
        if next == p {
            continue;
        }
        max[next] = cmp::min(max[next], num[v] + 1);
        min[next] = cmp::max(min[next], num[v] - 1);
        if max[next] < min[next] {
            return false;
        }
        if min[next] <= num[v] + 1 && num[v] + 1 <= max[next] {
            num[next] = num[v] + 1;
        } else if min[next] <= num[v] - 1 && num[v] - 1 <= max[next] {
            num[next] = num[v] - 1;
        } else {
            return false;
        }
        if !dfs(next, v, graph, num, min, max) {
            return false;
        }
    }
    true
}

