        let b = it.next().unwrap().parse::<usize>().unwrap() - 1;
        g[a].push(b);
        g[b].push(a);
    }
    let mut l = vec![-1_000_000; n];
    let mut r = vec![2_000_000; n];
    let k: usize = it.next().unwrap().parse().unwrap();
    let mut src = 0;
    for _ in 0..k {
        let v = it.next().unwrap().parse::<usize>().unwrap() - 1;
        let p: i32 = it.next().unwrap().parse().unwrap();
        l[v] = p;
        r[v] = p;
        src = v;
    }
    let mut q = vec![];
    let mut parent = vec![src; n];
    let mut stack = vec![src];
    while let Some(v) = stack.pop() {
        q.push(v);
        for &u in &g[v] {
            if u == parent[v] {
                continue;
            }
            parent[u] = v;
            stack.push(u);
        }
    }
    for &v in &q {
        for &u in &g[v] {
            if u == parent[v] {
                continue;
            }
            l[u] = max(l[u], l[v] - 1);
            r[u] = min(r[u], r[v] + 1);
        }
    }
    for &v in q.iter().rev() {
        let p = parent[v];
        l[p] = max(l[p], l[v] - 1);
        r[p] = min(r[p], r[v] + 1);
    }
    for &v in &q {
        for &u in &g[v] {
            if u == parent[v] {
                continue;
            }
            l[u] = max(l[u], l[v] - 1);
            r[u] = min(r[u], r[v] + 1);
        }
    }
    for i in 0..n {
        if l[i] > r[i] || (r[i] - l[i]) % 2 == 1 {
            println!("No");
            return;
        }
    }
