        k: usize,
        vp: [(usize1, i64); k]
    }
    let mut t = vec![vec![]; n];
    for &(a, b) in &es {
        t[a].push(b);
        t[b].push(a);
    }
    let mut sets = vec![None; n];
    for &(v, p) in &vp {
        let mut s = HashSet::new();
        s.insert(p);
        sets[v] = Some(s);
    }
    dfs(0, 0, &t, &mut sets);
    if sets[0].clone().unwrap().is_empty() {
        println!("No");
        return;
    }
    println!("Yes");
    let mut ans = vec![0; n];
    ans[0] = *sets[0].clone().unwrap().iter().nth(0).unwrap();
    dfs2(0, 0, &t, &sets, &mut ans);
    for i in 0..n {
        println!("{}", ans[i]);
    }
}

fn dfs(r: usize, p: usize, t: &Vec<Vec<usize>>, sets: &mut Vec<Option<HashSet<i64>>>) {
    let mut ss = vec![];
    if let Some(s) = sets[r].clone() {
        ss.push(s);
    }
    for &c in &t[r] {
        if c == p {
            continue;
        }
        dfs(c, r, t, sets);
        if let Some(s) = sets[c].clone() {
            ss.push(s.iter().map(|x| x + 1).chain(s.iter().map(|x| x - 1)).collect());
        }
    }
    if ss.len() == 1 {
        sets[r] = Some(ss[0].clone());
    } else if ss.len() > 1 {
        ss.sort_by_key(|x| x.len());
        let mut sr: HashSet<i64> = ss[0].intersection(&ss[1]).cloned().collect();
        for i in 2..ss.len() {
            sr = sr.intersection(&ss[i]).cloned().collect();
        }
        sets[r] = Some(sr);
    }
}

fn dfs2(r: usize, p: usize, t: &Vec<Vec<usize>>, sets: &Vec<Option<HashSet<i64>>>, v: &mut Vec<i64>) {
    for &c in &t[r] {
        if c == p {
            continue;
        }
        if let Some(s) = sets[c].clone() {
            if s.contains(&(v[r] + 1)) {
                v[c] = v[r] + 1;
            } else {
                v[c] = v[r] - 1;
            }
        } else {
            v[c] = v[r] + 1;
        }
        dfs2(c, r, t, sets, v);
    }
}

