    let mut dp: Vec<i32> = vec![INF; n];
    let mut q = BinaryHeap::new();
    for i in 0..k {
        let (v, p): (usize, i32) = read();
        dp[v-1] = p;
        q.push((-p, v-1));
    }

    while let Some((mp, now)) = q.pop() {
        let value = -mp;
        let next = value + 1;

        for &to in &graph[now] {
            if dp[to] == INF {
                dp[to] = next;
                q.push((-next, to));
            }
        }
    }

    let mut is_ok = true;
    for u in 0..n {
        for &v in &graph[u] {
            if (dp[u]-dp[v]).abs() != 1 {
                is_ok = false;
            }
        }
    }

    if is_ok {
        println!("Yes");
        for i in 0..n {
            println!("{}", dp[i]);
        }
    } else {
        println!("No");
    }
}
